      val l = bit2.sum(xid + 1)
      upL(i) = l
      bit2.add(xid, 1)
    }

    REP(N) { i =>
      val upR = N - 1 - i - upL(i)
      val downR = i - downL(i)
//      ans += downL(i).toLong * upR + downR.toLong * upL(i)

      ans += (MOD + pow2(downL(i)) - 1) % MOD * (MOD + pow2(upR) - 1) % MOD *
        pow2(downR + upL(i)) % MOD

      ans += pow2(downL(i) + upR) *
        (MOD + pow2(downR) - 1) % MOD * (MOD + pow2(upL(i)) - 1) % MOD

      ans = MOD + ans - (MOD + pow2(downL(i)) - 1) % MOD * (MOD + pow2(upR) - 1) % MOD *
        (MOD + pow2(downR) - 1) % MOD * (MOD + pow2(upL(i)) - 1) % MOD

      debug(s"upR:$upR upL${upL(i)} downR:$downR downL:${downL(i)}")

      ans %= MOD
    }

    debug(downL)
    debug(upL)

    val NN = N

    def powMod(x: Int, n: Int, m: Int): Int = {
      def step(x: Long, n: Int, stack: Long): Long = {
        n match {
          case 0 => stack
          case _ => step(x * x % m, n / 2, if (n % 2 == 1) stack * x % m else stack)
        }
      }
      step(x, n, 1).toInt
    }

    val F = Array.ofDim[Long](NN + 1)
    F(0) = 1
    REP(NN) { i =>
      F(i + 1) = F(i) * (i + 1) % MOD
    }
    val I = Array.ofDim[Long](F.length)
    I(NN) = powMod(F(NN).toInt, MOD - 2, MOD)

    // x! = x(x-1)!
    // x!I(x!) ≡ (x-1)!I((x-1)!)
    // I((x-1)!) ≡ I(x!) * x   MODがでかいので(x-1)!はMODと素
    REP_r(NN) { i =>
      I(i) = I(i + 1) * (i + 1) % MOD
    }

    def comb(n: Int, k: Int): Long = {
      if (n < k) 0
      else F(n) * I(n - k) % MOD * I(k) % MOD
    }

    REP(N, 1) { i =>
      ans = (ans + i * comb(N, i)) % MOD
    }

    out.println(ans)
  }

  class BIT(n: Int, zero: Int)(f: (Int, Int) => Int) {
  def this(n: Int) = this(n, 0)(_ + _)

  private val N = {
    val a = Integer.highestOneBit(n)
    if (a == n) a else a << 1
  }
  private val bit = if (zero != 0) Array.fill[Int](N + 1)(zero) else Array.ofDim[Int](N + 1)

  /**
    * 1 index
    * addとindex違うよ
    * cumsumなんかといっしょ
    */
  def sum(i: Int): Int = {
    assert(i <= n)
    var x = i
    var s: Int = zero
    while(x > 0) {
      s = f(s, bit(x))
      x -= x & -x
    }
    s
  }

  /**
    * 0 index
    */
  def add(i: Int, a: Int): Unit = {
    assert(i < n)
    var x = i + 1
    while(x <= N) {
      bit(x) = f(bit(x), a)
      x += x & -x
    }
  }

  def sumAll: Int = sum(n)

  /**
    * [l, r)
    */
  def query(l: Int, r: Int)(sub: (Int, Int) => Int): Int = {
    assert(r > l)
    sub(sum(r), sum(l))
  }

  def lowerBound(W: Int)(sub: (Int, Int) => Int, lt: (Int, Int) => Boolean): Int = {
    var k = N
    var x = 0
    var w = W
    while(k > 0) {
      if (x + k <= N && lt(bit(x + k), w)) {
        w = sub(w, bit(x + k))
        x += k
      }
      k /= 2
    }
    x
  }
}
  def lb(a: Array[Int], x: Int): Int = {
    def step(l: Int, h: Int): Int = {
      if (h - l == 1) h
      else {
        val mid = (l + h) / 2
        if (a(mid) >= x) step(l, mid)
        else step(mid, h)
      }
    }

    step(-1, a.length)
  }
}

