  val M = 998244353

  class BIT(x: Int){
    val n = Stream.from(0).map(Math.pow(2, _).toInt).find(_ >= x).get + 1
    val as = Array.fill(n)(0)

    def f(i: Int): Int = {
      var r = 0
      var j = i
      while (j > 0) {
        r += as(j)
        j -= j & -j
      }
      j = i
      while (j < n) {
        as(j) += 1
        j += j & -j
      }
      r
    }
  }

  val e = Array.fill(N + 1)(0)
