        rep(i, n) p[i].second = mp[p[i].second];
    }

    sort(p.begin(), p.end());
    vector<int> a(n);
    vector<int> b(n);
    vector<int> c(n);
    vector<int> d(n);
    rep(_, 2) {
        {
