long long mod_pow(long long n, long long p, long long m) {
	if (p == 0) return 1;
	if (p % 2 == 0) {
		long long t = mod_pow(n, p / 2, m);
		return (t * t) % m;
	}
	return n * mod_pow(n, p - 1, m) % m;
}

class BIT {
private:
	vector<int>bit;
	int n;
public:
	BIT() {
		n = 0;
	}
	void set(int _n) {
		bit.resize(_n + 1);
		rep(i, _n + 1) bit[i] = 0;
		n = _n;
	}
	//i 1-indexed
	int sum(int i) {
		int s = 0;
		while (i > 0) {
			s += bit[i];
			i -= (i & -i);
		}
		return s;
	}
	void add(int i, int x) {
		while (i <= n) {
			bit[i] += x;
			i += (i & -i);
		}
	}
};

