        rsort(p.begin(), p.end());
        for(unsigned int i = 0; i < N; ++i)p[i] = {p[i].second, i + 1};
        rsort(p.begin(), p.end());
        transform(p.cbegin(), p.cend(), perm.begin(), [](auto i){return i.second;});
    }

    constexpr unsigned long MOD = 998244353;
    array<unsigned long, maxN> binary;
    unsigned long n = binary[0] = 1;
    generate(binary.begin() + 1, binary.end(), [&n](){n <<= 1;return n -= (n >= MOD) * MOD;});

    array<unsigned int, maxN> fenwick_tree{};
    auto que = [&fenwick_tree, &N](unsigned int i){
        unsigned int s{0}, j{i};
        while(i){
            s += fenwick_tree[i];
            i -= i & -i;
        }
        while(j <= N){
            ++fenwick_tree[j];
            j += j & -j;
        }
        return s;
    };

    array<unsigned int, maxN> coef{};
    coef[N] = N + MOD - 4;
    for(unsigned long i = 0; i != N; ++i){
        auto p = perm[i], q = que(p);
        ++coef[q];
        ++coef[i - q];
        ++coef[perm[i] - q - 1];
        ++coef[N - i - perm[i] + q];
    }

    cout << inner_product(binary.begin(), binary.end(), coef.begin(), 4 + MOD - N) % MOD << endl;
    return 0;
}

