    for(int i=0; i<n; ++i) {
        xx[i]=pos[i].fir;
        yy[i]=pos[i].sec;
    }
    sort(all(xx));
    sort(all(yy));
    xx.erase(unique(all(xx)),end(xx));
    yy.erase(unique(all(yy)),end(yy));
    for(int i=0; i<n; ++i) {
        pos[i].fir=lower_bound(all(xx),pos[i].fir)-xx.begin();
        pos[i].sec=lower_bound(all(yy),pos[i].sec)-yy.begin();
    }
    solve();
}

