  for(int i=0;i<N;i++) cin>>x[i]>>y[i];

  vector<pair<ll,int>> v,w;
  for(int i=0;i<N;i++) w.push_back(mkp(y[i],i));
  for(int i=0;i<N;i++) v.push_back(mkp(x[i],i));
  map<ll,int> xmp,ymp;
  sort(v.begin(),v.end());
  sort(w.begin(),w.end());
  for(int i=0;i<N;i++){
    xmp[v[i].first]=i;
    ymp[w[i].first]=i;
  }

  LazySegmentTree lsg(vector<ll> (N+1,0));
  LazySegmentTree rsg(vector<ll> (N+1,0));

  vector<ll> ld(N+1,0),lu(N+1,0),rd(N+1,0),ru(N+1,0);
  for(int i=0;i<N;i++){
    int now=v[i].second;
    int val=ymp[y[now]];
    int z=lsg.getSum(0,val);
    int p=i-z;
    ld[i]=z;
    lu[i]=p;
    lsg.add(val,val+1,1);
  }
  for(int i=N-1;i>=0;i--){
    int now=v[i].second;
    int val=ymp[y[now]];
    int z=rsg.getSum(0,val);
    int p=N-1-i-z;
    rd[i]=z;
    ru[i]=p;
    rsg.add(val,val+1,1);
  }

  ll two[N+1]={};
  two[0]=1;
  for(int i=1;i<=N;i++) two[i]=two[i-1]*2%MOD;

  ll ans=0;
  for(int i=0;i<N;i++){
    ll resa=(two[ld[i]]-1)*(two[ru[i]]-1)%MOD;
    resa=resa*(two[N-(ld[i]+ru[i]+1)])%MOD;

    ll resb=(two[lu[i]]-1)*(two[rd[i]]-1)%MOD;
    resb=resb*(two[ru[i]]-1+two[ld[i]])%MOD;

    ll res=(resa+resb)%MOD;
    ans=(ans+res)%MOD;
    ans=(ans+two[N-1])%MOD;
  }

  cout<<(ans+MOD)%MOD<<endl;


  return 0;
}

