template<typename Data, typename Func>
class SegmentTree{
  int n;
  std::vector<Data> data;
  Func f;
  Data d;

  Data query(int a, int b, int k, int l, int r) const{
    if(r <= a || b <= l) return d;
    if(a <= l && r <= b) return data[k];
    else{
      const Data v1 = query(a, b, k * 2 + 1, l, (l + r) / 2);
      const Data v2 = query(a, b, k * 2 + 2, (l + r) / 2, r);
      return f(v1, v2);
    }
  }

public:
  SegmentTree(int nn, Func f, Data d) : f(f), d(d){
    n = 1;
    while(n < nn) n *= 2;
    data = std::vector<Data>(2 * n, d);
  }

  void update(int k, const Data &a){
    k += n - 1;
    data[k] = a;
    while(k > 0){
      k = (k - 1) / 2;
      data[k] = f(data[k * 2 + 1], data[k * 2 + 2]);
    }
  }

  // [a, b)
  Data query(int a, int b) const{
    return query(a, b, 0, 0, n);
  }
};

template<typename Data, typename Func> SegmentTree<Data, Func>
segtree(int numberOfElements, Data defaultValue, Func mergeFunc){
  return SegmentTree<Data, Func>(numberOfElements, mergeFunc, defaultValue);
}

const ll mod = 998244353;

ll mpow(ll b, ll e){
  ll ret = 1;
  while(e){
    if(e & 1) ret = (ret * b) % mod;
    b = (b * b) % mod;
    e /= 2;
  }
  return ret;
}


int main(){
  const int n = getInt();
  vector<pair<int, int> > xy(n);
  vector<int> ys(n);
  REP(i,n){
    xy[i].first = getInt();
    ys[i] = xy[i].second = getInt();
  }
  sort(xy.begin(), xy.end());
  sort(ys.begin(), ys.end());
  map<int, int> yid;
  REP(i,n) yid[ys[i]] = i;

  auto left = segtree(n, 0, [](int x, int y){ return x + y; });
  auto right = segtree(n, 0, [](int x, int y){ return x + y; });
  REP(i,n) right.update(i, 1);

  ll res = 0;

  REP(i,n){
    const int x = xy[i].first;
    const int y = xy[i].second;
    const int id = yid[y];
    right.update(id, 0);

    const int leftBottom = left.query(0, id);
    const int leftTop = left.query(id, n);
    const int rightBottom = right.query(0, id);
    const int rightTop = right.query(id, n);

    // printf("%d %d (%d):\n %d %d\n %d %d\n", x, y, id, leftTop, rightTop, leftBottom, rightBottom);

    res += mpow(2, n - 1); res %= mod;

    res += mpow(2, n - 1); res %= mod;
    res += mod - mpow(2, leftBottom + leftTop); res %= mod;
    res += mod - mpow(2, leftTop + rightTop); res %= mod;
    res += mod - mpow(2, rightTop + rightBottom); res %= mod;
    res += mod - mpow(2, rightBottom + leftBottom); res %= mod;
    res += mpow(2, leftBottom); res %= mod;
    res += mpow(2, leftTop); res %= mod;
    res += mpow(2, rightBottom); res %= mod;
    res += mpow(2, rightTop); res %= mod;
    res += mod - 1; res %= mod;

    left.update(id, 1);
  }

  printf("%lld\n", res);

  return 0;
}

