			long long p = (p2[c1] - 1) * (p2[c2] - 1) % mod;

			cnta = p * (p2[n - 1 - c1 - c2]) % mod;
			cntab = cntab * p %mod;
		}

		{
			int c1 = wm.count(x + 1, inf, 0, y);
			int c2 = wm.count(0, x, y + 1, inf);
