			cntb = p * (p2[n - 1 - c1 - c2]) % mod;
			cntab = cntab * p % mod;
		}

		ans += cnta;
		ans += cntb;
		ans -= cntab;
		ans += p2[n - 1];
		ans %= mod;
	}


