template < template < typename ... > class Container, typename T >
auto coenumerate(Container< T > const& v) {
  auto n = v.size();
  Container< std::pair< T, int >> ret(n);
  for (std::size_t i = 0; i < n; i++)
    { ret.at(i) = {v.at(i), i}; }
  return ret;
}

template < template < typename ... > class Container, typename T >
auto compress (Container< T > const& v) {
  int n = v.size();
  Container< std::pair< T, int > > pairs(n);
  for (auto i = 0; i < n; i++)
    { pairs.at(i) = {v.at(i), i}; }
  std::sort(pairs.begin(), pairs.end());
  std::vector< int > new_v(n);
  for (auto i = 0; i < n; i++)
    { new_v.at(pairs.at(i).second) = i; }
  return new_v;
}


