      0
    );
    std::vector< int > lwr(n), upr(n);
    rep(i, 0, n) {
      auto crr = p.at(i);
      lwr.at(i) = sum_tree.query(0, crr);
      upr.at(i) = sum_tree.query(crr, n);
      sum_tree.add(crr, 1);
    }
    return std::make_pair(lwr, upr);
  };
  std::vector< int > p(n);
