// K-Dimensional Tree
#include<algorithm>
#include<vector>
struct Point {
  Point(int K) : dat(K) {}
  Point(std::initializer_list<int> init) : dat(init.begin(), init.end()) {}
  int& operator[](int k) {return dat[k];}
  const int operator[](int k) const {return dat[k];}
  std::vector<int> dat, low, high;
  int val;
  int lchild=-1, rchild=-1;
};
class KDTree {
 public:
  KDTree(int K, const std::vector<Point>& p) : K(K), P(p) {
    ROOT = build(0, P.size(), 0);
    P[ROOT].low.resize(K); P[ROOT].high.resize(K);
    for(auto k=0; k<K; ++k) {
      P[ROOT].low[k]  = (*std::min_element(std::begin(P), std::end(P), [&](const auto& lhs, const auto& rhs){return lhs[k]<rhs[k];}))[k];
      P[ROOT].high[k] = (*std::max_element(std::begin(P), std::end(P), [&](const auto& lhs, const auto& rhs){return lhs[k]<rhs[k];}))[k];
    }
    std::function<void(int,int)> dfs = [&](int n, int k) {
      P[n].val = 1;
      for(auto nex: {P[n].lchild, P[n].rchild}) if(nex != -1) {
        P[nex].low  = P[n].low;
        P[nex].high = P[n].high;
        if(nex == P[n].lchild) P[nex].high[k] = P[n][k];
        else                   P[nex].low[k]  = P[n][k];
        dfs(nex, (k+1)%K);
        P[n].val += P[nex].val;
      }
//       cout<<"calc: "<<n<<P[n].dat<<", children: "<<P[n].lchild<<","<<P[n].rchild<<", val: "<<P[n].val<<", area: "<<P[n].low<<P[n].high<<endl;
    };
    dfs(ROOT, 0);
  }
  int query(const Point& l, const Point& h) const {return query(l, h, ROOT, 0);}
 private:
  int build(int l, int r, int k) {
    if(!(l < r)) return -1;
    std::sort(begin(P)+l, begin(P)+r, [&k](const auto& lhs, const auto& rhs){return lhs[k]<rhs[k];});
    auto m = (l+r)>>1;
    P[m].lchild = build(l,   m, (k+1)%K);
    P[m].rchild = build(m+1, r, (k+1)%K);
    return m;
  };
  int query(const Point& l, const Point& h, int n, int k) const {
    if(n == -1) return 0;
//     cout<<"Q: "<<n<<":"<<k<<"*"<<P[n].dat<<l.dat<<h.dat<<endl;
    auto ok = true;
    for(auto k=0; k<K; ++k) if(P[n].low[k]<l[k] || h[k]<P[n].high[k]) ok = false;
    if(ok) return P[n].val;
    int res = 1;
    for(auto k=0; k<K; ++k) if(P[n][k]<l[k] || h[k]<=P[n][k]) res = 0;
    if(l[k] <= P[n][k]) res += query(l, h, P[n].lchild, (k+1)%K);
    if(P[n][k] < h[k])  res += query(l, h, P[n].rchild, (k+1)%K);
    return res;
  }
  int K, ROOT;
  std::vector<Point> P;
};

using LL = long long;
const LL M = 998244353;

LL power(LL m, LL n) {
  if(!n) return 1;
  return (n & 1) ? (power(m, n - 1) * m % M) : power(m * m % M, n >> 1);
}

int main() {
  int N;
  cin >> N;
  vector<Point> P(N, Point(2));
  for(auto& i: P) cin >> i[0] >> i[1];

  KDTree kdtree(2, P);

  LL ans = 0;
  const int INF = 1e9+1;
  for(const auto& p: P) {
    // T に含まれる場合
    ans += power(2, N-1);
    ans %= M;
    // T に含まれない場合
    LL lr = kdtree.query({p[0], -INF}, {1+INF, 1+p[1]}) - 1;
//     cout<<"*lr "<<lr<<endl;
    LL ul = kdtree.query({-INF, p[1]}, {1+p[0], 1+INF}) - 1;
//     cout<<"*ul "<<ul<<endl;
    LL ll = kdtree.query({-INF, -INF}, {1+p[0]-1, 1+p[1]-1});
//     cout<<"*ll "<<ll<<endl;
    LL ur = kdtree.query({p[0]+1, p[1]+1}, {1+INF, 1+INF});
//     cout<<"*ur "<<ur<<endl;
    LL urll = (power(2,ur)-1) * (power(2,ll)-1) % M;
    LL ullr = (power(2,ul)-1) * (power(2,lr)-1) % M;
//     cout<<"*"<<lr<<","<<ul<<","<<ll<<","<<ur<<endl;
    ans += urll * power(2,N-1-ur-ll) % M;
    ans %= M;
    ans += ullr * power(2,N-1-ul-lr) % M;
    ans %= M;
    ans += M - (urll * ullr % M) * power(2,N-1-ur-ll-ul-lr) % M;
    ans %= M;
  }
  cout << ans << endl;
}

