ll f(int a, int b, int c, int d) {
	ll res = 0;
	vector<int> num = {a, b, c, d};
	vector<ll> o(4), ox(4);
	for (int i = 0; i < 4; i++) {
		ox[i] = ((ll) pow(2, num[i])) % mod;
		o[i] = ox[i] - 1;
	}
	res += (ox[0] % mod) * (o[1] % mod) * (o[2] % mod) * (ox[3] % mod);
	res %= mod;
	res += (o[0] % mod) * (ox[1] % mod) * (ox[2] % mod) * (o[3] % mod);
	res %= mod;
	res -= (o[0] % mod) * (o[1] % mod) * (o[2] % mod) * (o[3] % mod);
	res %= mod;
	res += (ox[0] % mod) * (ox[1] % mod) * (ox[2] % mod) * (ox[3] % mod);
	res %= mod;
	return res;
}

