using namespace std;

using LL = long long;
const LL M = 998244353;

LL power(LL m, LL n) {
  if(!n) return 1;
  return (n & 1) ? (power(m, n - 1) * m % M) : power(m * m % M, n >> 1);
}

int main() {
  struct Point {int x, y;};
  const int INF = 2e9;

  int N;
  cin >> N;
  vector<Point> P(N);
  for(auto& i: P) cin >> i.x >> i.y;

  vector<int> v{-INF, INF};
  for(auto& i: P) v.emplace_back(i.x), v.emplace_back(i.y);
  Compression C(v);

  RangeTree<int> T(C.size(), C.size());
  for(auto& i: P) T.update(C.index(i.x), C.index(i.y), 1);
  return 0;

  LL ans = 0;
  for(const auto& p: P) {
    // T に含まれる場合
    ans += power(2, N-1);
    ans %= M;
    // T に含まれない場合
    auto x=C.index(p.x),  y=C.index(p.y);
    auto l=C.index(-INF), h=C.index(INF);
    LL lr = T.query(x, l, 1+h, 1+y) - 1;
    LL ul = T.query(l, y, 1+x, 1+h) - 1;
    LL ll = T.query(l, l, 1+x-1, 1+y-1);
    LL ur = T.query(x+1, y+1, 1+h, 1+h);
    LL urll = (power(2,ur)-1) * (power(2,ll)-1) % M;
    LL ullr = (power(2,ul)-1) * (power(2,lr)-1) % M;
    ans += urll * power(2,N-1-ur-ll) % M;
    ans %= M;
    ans += ullr * power(2,N-1-ul-lr) % M;
    ans %= M;
    ans += M - (urll * ullr % M) * power(2,N-1-ur-ll-ul-lr) % M;
    ans %= M;
  }
  cout << ans << endl;
}

