const Int MOD = 998244353;
void compress(vector<int> &X) {
    vector<pair<int, int>> Y(X.size());
    for (int i = 0; i < X.size(); i++) {
        Y[i] = make_pair(X[i], i);
    }
    sort(begin(Y), end(Y));
    for (int i = 0; i < X.size(); i++) {
        X[Y[i].second] = i+1; // 1-indexed
    }
}
struct BIT {
    vector<int> A;
    int N;
    BIT(int n) : A(n+1), N(n) {}
    void add(int i, int x) {
        if (i > N) return;
        A[i] += x;
        add(i + (i & -i), x);
    }
    int sum(int i) {
        if (!i) return 0;
        return A[i] + sum(i - (i & -i));
    }
};
int main()
{
    int N; cin >> N;
    vector<int> X(N), Y(N);
    for (int i = 0; i < N; i++) cin >> X[i] >> Y[i];
    compress(X);
    compress(Y);
    vector<int> I(N);
    iota(begin(I), end(I), 0);
    sort(begin(I), end(I), [&](int i, int j) { return X[i] < X[j]; });
    vector<int> A(N), B(N), C(N), D(N);
    auto bit = BIT(N);
    for (int i = 0; i < N; i++) {
        int j = I[i];
        A[j] = bit.sum(Y[j]);
        B[j] = i - A[j];
        bit.add(Y[j], 1);
    }
    bit = BIT(N);
    for (int i = 0; i < N; i++) {
        int j = I[N-1-i];
        C[j] = bit.sum(Y[j]);
        D[j] = i - C[j];
        bit.add(Y[j], 1);
    }
    vector<Int> POW2(N+1);
    POW2[0] = 1;
    for (int i = 1; i <= N; i++) POW2[i] = POW2[i-1] * 2 % MOD;
    Int ans = 0;
    for (int i = 0; i < N; i++) {
        int a = A[i], b = B[i], c = C[i], d = D[i];
        ans += POW2[N] - 1 - (POW2[a+b] + POW2[b+d] + POW2[d+c] + POW2[c+a]
                              - POW2[a] - POW2[b] - POW2[c] - POW2[d]);
        ans += 1000 * MOD;
        ans %= MOD;
    }
    cout << ans << '\n';
    return 0;
}

