#define mod 998244353

// 区間の和を計算するBIT, 1-indexed
template<typename T>
struct BIT{
    using F = function<T(T, T)>;
    using INV = function<T(T)>;
    BIT(int N, T unit, F f, INV inv) : value(N+1, unit), unit(unit), f(f), inv(inv) {}

    T sum(int i, int j) {
        if(i > j) return unit;
        if(i == 0) return sum(j);
        return f(sum(j), inv(sum(i-1)));
    }

    void add (int k, T x) {
        for (; k < value.size(); k += k & -k) value[k] = f(value[k], x);
    }

  T sum(int k) {
        T res = unit;
        for (; k > 0; k -= k & -k) res = f(res, value[k]);
        return res;
    }

private:
    vector<T>value;
    const F f;
    const T unit;
    const INV inv;
};

int main() {
    int N;
    cin >> N;
    vector<int>x(N);
    vector<int>y(N);
    vector<pair<int, int>> elements(N);
    for (int i = 0; i < N; ++i) {
        cin >> x[i] >> y[i];
    }

    // y座標を 1-indexed で圧縮後, x座標でソート
    vector<int> copyY(y);
    sort(copyY.begin(), copyY.end());
    map<int, int> mp;
    for (int i = 0; i < N; ++i) {
        mp[copyY[i]] = i + 1;
    }
    for (int i = 0; i < N; ++i) {
        y[i] = mp[y[i]];
        elements[i] = make_pair(x[i], y[i]);
    }
    sort(elements.begin(), elements.end());

    // 2の累乗計算
    ll modPow[N+1];
    modPow[0] = 1;
    for (int i = 1; i < N+1; ++i) {
        modPow[i] = modPow[i-1] * 2 % mod;
    }

    ll ans = modPow[N] + mod - 1;
    ans %= mod;
    ans = ans * N % mod;

    BIT<int> tree(N, 0, plus<int>(), [](int a){ return -a;});
    sort(y.begin(), y.end());

    for (int i = 0; i < N; ++i) {
        // 左にi個, 右にN-i-1個の点
        int yi = elements[i].second;
        // vector y には自分自身も含まれていることに注意
        auto iter1 = lower_bound(y.begin(), y.end(), yi);
        int low = distance(y.begin(), iter1);
        // 下にlow個, 上にN-low-1個の点

        int lowOver = tree.sum(yi);
        tree.add(yi, 1);

        // 左下にlowOver個, 左上にi-lowOver個の点
        ans = ans + mod + mod + mod + mod;
        ans = ans - modPow[low] - modPow[N-low-1] - modPow[i] - modPow[N-i-1] + 4;
        ans = ans + modPow[lowOver] + modPow[i-lowOver] + modPow[low - lowOver] + modPow[N-low-1-i+lowOver] - 4;
        ans %= mod;
    }
    cout << ans;
    return 0;
}

