int init_BIT(std::vector<int> &BIT, int N_MAX){
  for(int i = 0; i < N_MAX; i++){
    BIT[i] = 0;
  }
  return 0;
}

int add_num(std::vector<int> &BIT, int N_MAX, int index, int d){
  index ++;
  while(index < N_MAX){
    BIT[index-1] += d;
    index += (index & -index);
  }

  return 0;
}

int cumulative_sum(std::vector<int> &BIT, int r){
  // sum of no elements
  if(r == -1){
    return 0;
  }

  r++;
  long long int sum = 0;
  while(r > 0){
    sum += BIT[r-1];
    r -= (r & -r);
  }

  return sum;
}

long long int power_of_2(int n, long long int MOD){
  long long int ans = 1;
  for(int i = 0; i < n; i++){
    ans = ans << 1;
    ans %= MOD;
  }
  return ans;
}

