struct OrderedSet {
        vector< ll > data;
        ll num = 0;
        ll size = 1;

        OrderedSet(int sz) {
                while(size<sz)size<<=1;
                data.assign(size+1, 0);
        }

        ll sum(int k) {
                ll ret = 0;
                for(++k; k > 0; k -= k & -k) ret += data[k];
                return (ret);
        }

        void add(int k, ll x) {
                for(++k; k < data.size(); k += k & -k) data[k] += x;
                num+=x;
        }

        ll search(int k) {
                if(k<1)return 0;
                if(k>num)return size+1;
                ll x = 0, sx = 0;
                ll step = size;
                while(step){
                        ll y = x+step;
                        ll sy = sx+data[y];
                        if(sy<k){
                                x = y;
                                sx = sy;
                        }
                        step >>= 1;
                }
                return x;
        }
};

