        Y.emplace_back(y);
    }

    sort(points.begin(), points.end());
    sort(Y.begin(), Y.end());

    map<int, int> y2index;
    for(int i=0; i<n; i++){
        y2index[Y[i]] = i;
    }

    vector<ll> A(n, 0);
    vector<ll> B(n, 0);
    vector<ll> C(n, 0);
    vector<ll> D(n, 0);

    SegmentTree pseg(vector<int>(n, 0));
    SegmentTree nseg(vector<int>(n, 1));

    for(int i=0; i<n; i++){
        int x, y;
        tie(x, y) = points[i];

        int index = y2index[y];

        nseg.add(index, -1);
        pseg.add(index, 1);

        B[i] = nseg.getsum(index + 1, n);
        D[i] = nseg.getsum(0, index);
        A[i] = pseg.getsum(index + 1, n);
        C[i] = pseg.getsum(0, index);
    }

    ll ans = 0;
    for(int i=0; i<n; i++){
        ans += modpow(2, n-1);
        ans %= MOD;
        ll num1 = (((modpow(2, A[i]) - 1) * (modpow(2, D[i]) - 1) % MOD) * ((modpow(2, B[i]) * modpow(2, C[i])) % MOD)) % MOD;
        ll num2 = (((modpow(2, B[i]) - 1) * (modpow(2, C[i]) - 1) % MOD) * ((modpow(2, A[i]) * modpow(2, D[i])) % MOD)) % MOD;

        ans += ((num1 + num2) % MOD) - (((modpow(2, A[i]) - 1) * (modpow(2, B[i]) - 1) % MOD) * ((modpow(2, C[i]) - 1) * (modpow(2, D[i]) - 1) % MOD)) % MOD + MOD;
        ans %= MOD;
    }

    cout << ans << endl;

    return 0;
}

#include<functional>
#include<iostream>
#include<memory>
template<typename S, typename E = S> class SegmentTreeDLP {
 public:
  using Size = long long;
  using FS = std::function<S(S, S)>;
  using FA = std::function<S(S, E)>;
  using FE = std::function<E(E, E)>;
  SegmentTreeDLP(Size L, Size R, FS fs, FA fa, FE fe, S es, E ee) : L(L), R(R), fs(fs), fa(fa), fe(fe), es(es), ee(ee), root(std::make_unique<Node>(es,ee)) {}
  void set(Size a, S x) {set(a, x, root, L, R);}
  void update(Size a, Size b, E x) {update(a, b, x, root, L, R);}
  S query(Size a, Size b) {return query(a, b, root, L, R);}
  Size lower_bound(Size a, Size b, const std::function<bool(S)>& check) {return lower_bound(a, b, check, root, L, R);}
  void debug() {std::cout << "segtree: size " << L << " to " << R << std::endl; traverse(root, 0, L, R);}
  void traverse(const auto& node, Size d, Size l, Size r) {
    if(not node->lchild || not node->rchild) return;
    propagate(node);
    auto m = (l + r) / 2;
    if(l+1!=r) traverse(node->rchild, d + 1, m, r);
    for(auto i = 0; i < d; ++i) std::cout << "    ";
    std::cout << "[" << l << "," << r << ") ";
    std::cout << node->val << std::endl;
    if(l+1!=r) traverse(node->lchild, d + 1, l, m);
  }
 private:
  struct Node {
    S val;
    E laz;
    std::unique_ptr<Node> lchild, rchild;
    Node(S val, E laz) : val(val), laz(laz) {}
  };
  inline S reflect(const auto& n) {return n->laz==ee ? n->val : fa(n->val, n->laz);}
  inline void propagate(const auto& n) {
    if(not n->lchild) n->lchild = std::make_unique<Node>(es, ee);
    if(not n->rchild) n->rchild = std::make_unique<Node>(es, ee);
    if(n->laz == ee) return;
    n->lchild->laz = fe(n->lchild->laz, n->laz);
    n->rchild->laz = fe(n->rchild->laz, n->laz);
    n->val = reflect(n);
    n->laz = ee;
  }
  inline void recalc(const auto& n) {n->val = fs(reflect(n->lchild), reflect(n->rchild));}
  void set(Size a, E x, const auto &n, Size l, Size r) {
    propagate(n);
    if(l+1 == r) {
      n->val = x;
      return;
    }
    auto m = (l + r) / 2;
    if(a < m) set(a, x, n->lchild, l, m);
    else      set(a, x, n->rchild, m, r);
    recalc(n);
  }
  void update(Size a, Size b, E x, const auto &n, Size l, Size r) {
    propagate(n);
    if(b <= l || r <= a) return;
    if(a <= l && r <= b) {
      n->laz = fe(n->laz, x);
      propagate(n);
      return;
    }
    auto m = (l + r) / 2;
    update(a, b, x, n->lchild, l, m);
    update(a, b, x, n->rchild, m, r);
    recalc(n);
  }
  S query(Size a, Size b, const auto &n, Size l, Size r) {
    propagate(n);
    if(b <= l || r <= a) return es;
    if(a <= l && r <= b) return reflect(n);
    auto m = (l + r) / 2;
    auto vl = query(a, b, n->lchild, l, m);
    auto vr = query(a, b, n->rchild, m, r);
    return fs(vl, vr);
  }
  Size lower_bound(Size a, Size b, const auto& check, const auto& node, Size l, Size r) {
    propagate(node);
    if(b <= l || r <= a) return R;
    if(!check(reflect(node))) return R;
    if(l + 1 == r) return l;
    auto m = (l + r) / 2;
    auto i = lower_bound(a, b, check, node->lchild, l, m);
    if(i != R) return i;
    return lower_bound(a, b, check, node->rchild, m, r);
  }
  Size L, R;
  std::unique_ptr<Node> root;
  FS fs;
  FA fa;
  FE fe;
  S es;
  E ee;
};

