vector<ll> divisor(ll n){
    vector<ll> res(0);
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}

//Range Sum Query
const ll N_ = (1 << 18);
ll seg[2*N_-1];
void add(ll k, ll x){
  k += N_-1;
  seg[k] += x;
  while(k > 0){
    k = (k-1)/2;
    seg[k] = seg[2*k+1] + seg[2*k+2];
  }
}

ll get_sum(ll x, ll y, ll k = 0, ll left = 0, ll right = N_){
  if(right <= x || y <= left) return 0;
  if(x <= left && right <= y) return seg[k];
  ll mid = (left + right) / 2;
  ll l = get_sum(x, y, 2*k+1, left, mid);
  ll r = get_sum(x, y, 2*k+2, mid, right);
  return l + r;
}

mint all_exist_2(ll x, ll y){
  mint res = 0;
  res += pow_mod(2, x+y);
  res -= pow_mod(2, x);
  res -= pow_mod(2, y);
  res += pow_mod(2, 0);
  return res;
}
mint all_exist_3(ll x, ll y, ll z){
  mint res = 0;
  res += pow_mod(2, x+y+z);
  res -= pow_mod(2, x+y);
  res -= pow_mod(2, x+z);
  res -= pow_mod(2, y+z);
  res += pow_mod(2, x);
  res += pow_mod(2, y);
  res += pow_mod(2, z);
  res -= pow_mod(2, 0);
  return res;
}
mint all_exist_4(ll x, ll y, ll z, ll w){
  mint res = 0;
  res += pow_mod(2, x+y+z+w);
  res -= pow_mod(2, x+y+z);
  res -= pow_mod(2, x+y+w);
  res -= pow_mod(2, x+z+w);
  res -= pow_mod(2, y+z+w);
  res += pow_mod(2, x+y);
  res += pow_mod(2, x+z);
  res += pow_mod(2, x+w);
  res += pow_mod(2, y+z);
  res += pow_mod(2, y+w);
  res += pow_mod(2, z+w);
  res -= pow_mod(2, x);
  res -= pow_mod(2, y);
  res -= pow_mod(2, z);
  res -= pow_mod(2, w);
  res += pow_mod(2, 0);

  return res;
}
ll N;
vector<pair<ll, ll>> xy;
void compress(){
  vector<ll> xs, ys;
  rep(i, N){
    xs.pb(xy[i].f);
    ys.pb(xy[i].s);
  }
  sort(xs.begin(), xs.end());
  sort(ys.begin(), ys.end());
  rep(i, N){
    xy[i].f = lower_bound(xs.begin(), xs.end(), xy[i].f) - xs.begin();
    xy[i].s = lower_bound(ys.begin(), ys.end(), xy[i].s) - ys.begin();
  }
}

void solve(){
  vector<ll> LeftUp(N, 0), RightUp(N, 0), LeftDown(N, 0), RightDown(N, 0);
  sort(xy.begin(), xy.end());
  rep(i, N){
    LeftDown[i] = get_sum(0, xy[i].s);
    LeftUp[i] = i - LeftDown[i];
    add(xy[i].s, 1);
  }

  rep(i, 2*N_-1) seg[i] = 0;
  revrep(i, N){
    RightDown[i] = get_sum(0, xy[i].s);
    RightUp[i] = (N-1-i) - RightDown[i];
    add(xy[i].s, 1);
  }
  mint ans = 0;
  rep(i, N){
    ll ld = LeftDown[i], lu = LeftUp[i];
    ll rd = RightDown[i], ru = RightUp[i];
    ans += pow_mod(2, ld+lu+rd+ru);//iが含まれる
    //iが含まれない
    ans += all_exist_4(ld, lu, rd, ru);
    ans += all_exist_3(ld, lu, rd);
    ans += all_exist_3(ld, lu, ru);
    ans += all_exist_3(ld, ru, rd);
    ans += all_exist_3(lu, ru, rd);
    ans += all_exist_2(ld, ru);
    ans += all_exist_2(rd, lu);
  }
  ans.get();
}

int main(){
  cin >> N;
  xy.resize(N);
  rep(i, N){
    cin >> xy[i].f >> xy[i].s;
  }
  compress();
  solve();
}

