template<typename T>
struct segtree {
    T L0 = 0;
    T L1 = inf;
    T INF = 0;
    int n;
    vector<T> lazy, dat, lazyupdate;

    void init(int n_) {
        n = 1;
        while (n < n_) {
            n *= 2;
        }
        lazy.assign(2 * n - 1, L0);
        lazyupdate.assign(2 * n - 1, inf);
        dat.assign(2 * n - 1, INF);
    }

    void push(ll len, int k) {
        if (lazyupdate[k] != L1) {
            dat[k] = lazyupdate[k] * len;
            if (k < n - 1) {
                lazyupdate[k * 2 + 1] = lazyupdate[k];
                lazyupdate[k * 2 + 2] = lazyupdate[k];
            }
            lazyupdate[k] = L1;
        } else {
            if (lazy[k] == L0) {
                return;
            }
            dat[k] += lazy[k] * len;
            if (k < n - 1) {
                if (lazyupdate[k * 2 + 1] != L1) {
                    lazyupdate[k * 2 + 1] += lazy[k];
                } else {
                    lazy[k * 2 + 1] += lazy[k];
                }
                if (lazyupdate[k * 2 + 2] != L1) {
                    lazyupdate[k * 2 + 2] += lazy[k];
                } else {
                    lazy[k * 2 + 2] += lazy[k];
                }
            }
        }
        lazy[k] = L0;
    }

    void baseadd(int a, int b, T x, int k, int l, int r) {
        push(r - l, k);
        if (a <= l && r <= b) {
            lazy[k] += x;
            push(r - l, k);
        } else if (l < b && a < r) {
            baseadd(a, b, x, k * 2 + 1, l, (l + r) / 2);
            baseadd(a, b, x, k * 2 + 2, (l + r) / 2, r);
            dat[k] = dat[k * 2 + 1] + dat[k * 2 + 2];
        }
    }

    void addquery(int a, int b, T x) {
        baseadd(a, b, x, 0, 0, n);
    }

    void baseupdate(int a, int b, T x, int k, int l, int r) {
        push(r - l, k);
        if (a <= l && r <= b) {
            lazyupdate[k] = x;
            push(r - l, k);
        } else if (l < b && a < r) {
            baseupdate(a, b, x, k * 2 + 1, l, (l + r) / 2);
            baseupdate(a, b, x, k * 2 + 2, (l + r) / 2, r);
            dat[k] = dat[k * 2 + 1] + dat[k * 2 + 2];
        }
    }

    void updatequery(int a, int b, T x) {
        baseupdate(a, b, x, 0, 0, n);
    }

    T basequery(int a, int b, int k, int l, int r) {
        push(r - l, k);
        if (r <= a || b <= l) {
            return INF;
        }
        if (a <= l && r <= b) {
            return dat[k];
        } else {
            T vl = basequery(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = basequery(a, b, k * 2 + 2, (l + r) / 2, r);
            // dat[k] = dat[k * 2 + 1] + dat[k * 2 + 2];
            return vl + vr;
        }
    }

    //[l, r)の範囲の合計を返す
    T query(int l, int r) {
        return basequery(l, r, 0, 0, n);
    }

    //k番目にaを代入する
    void update(int k, T a) {
        T base = query(k, k + 1);
        addquery(k, k + 1, a - base);
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N;
    cin >> N;
    plglg pt[N];
    ll ys[N];
    REP(i, 0, N) {
        ll x, y;
