        pt[i] = plglg(x, y);
        ys[i] = y;
    }
    two[0] = 1;
    REP(i, 0, N) {
        two[i + 1] = multiply(two[i], 2);
    }
    REP(i, 0, N + 1) {
        two[i] = modminus(two[i], 1);
    }
    sort(pt, pt + N);
    sort(ys, ys + N);
    map<ll, ll> mp;
    REP(i, 0, N) {
        mp[ys[i]] = i;
    }
    segtree<ll> seg;
    seg.init(N);
    ll sum = 0;
    REP(i, 0, N) {
        plglg p = pt[i];
        ll lf = i;
        ll rt = (N - 1 - i);
        ll bot = lower_bound(ys, ys + N, p.second) - ys;
        ll top = N - 1 - bot;
        ll lfbot = seg.query(0, mp[p.second]);
        seg.update(mp[p.second], 1);
        // cout << lfbot << endl;
        ll rtbot = bot - lfbot;
        ll lftop = lf - lfbot;
        ll rttop = rt - rtbot;
        // cout << lf << " "  << rt << " " << bot << " " << top << endl;
        // cout << lfbot << " " << rtbot << " " << lftop << " " << rttop << endl;
        // cout << "aaa" << endl;
        ll tmp = modadd(two[lf], two[rt]);
        tmp = modadd(tmp, modadd(two[top], two[bot]));
        tmp = modminus(tmp, modadd(two[lfbot], two[lftop]));
        tmp = modminus(tmp, modadd(two[rtbot], two[rttop]));
        sum = modadd(sum, tmp);
        // cout << tmp << endl;
        // if (i % 1000 == 0) {
        //     cout << "aaa" << i << endl;
        // }
    }
    ll ans = modminus(multiply(modminus(modpower(2, N), 1), N), sum);
    cout << ans << endl;
}

