template<typename T>
struct BIT {
	int n;
	vector<T>dat;
	BIT(int n = 0) {
		initialize(n);
	}
	void initialize(int temp) {
		n = temp;
		dat.resize(n);
		rep(i, 0, n)dat[i] = 0;
	}
	T sum(int i) {
		T s = 0;
		while (i >= 0) {
			s += dat[i];
			i = (i & (i + 1)) - 1;
		}
		return s;
	}
	T sum_between(int i, int j) {
		if (i > j)return 0;
		return sum(j) - sum(i - 1);
	}
	void plus(int i, T x) {
		while (i < n) {
			dat[i] += x;
			i |= i + 1;
		}
	}
	int lower_bound(T x) {
		if (sum(n - 1) < x)return -1;
		else if (sum(0) >= x)return 0;
		int ng = 0, ok = n - 1;
		while (ok - ng > 1) {
			int mid = (ok + ng) / 2;
			if (sum(mid) >= x)ok = mid;
			else ng = mid;
		}
		return ok;
	}
};

const ll mod = 998244353;

ll modpow(ll a, ll n) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) res = res * a % mod;
		a = a * a % mod;
		n >>= 1;
	}
	return res;
}

int main() {
	int N;
	cin >> N;
	vector<pair<int, int>>p(N);
	vector<int>Y(N);
	for (int i = 0; i < N; i++) {
		cin >> p[i].first >> p[i].second;
		Y[i] = p[i].second;
	}
	sort(all(p));
	sort(all(Y));

	BIT<int>unused(N);
	BIT<int>used(N);
	for (int i = 0; i < N; i++) {
		int ind = lower_bound(all(Y), p[i].second) - Y.begin();
		unused.plus(ind,1);
	}

	ll ans = 0;
	for (int i = 0; i < N; i++) {
		int ind = lower_bound(all(Y), p[i].second) - Y.begin();
		int a = unused.sum_between(ind + 1, N - 1);
		int b = used.sum_between(ind + 1, N - 1);
		int c = used.sum_between(0, ind - 1);
		int d = unused.sum_between(0,ind-1);
		ans += modpow(2,N-1);
		ans %= mod;
		ll num1 = ((modpow(2, a) - 1) * (modpow(2, c) - 1)) % mod;
		num1 *= (modpow(2,b) * modpow(2,d)) % mod;
		num1 %= mod;
		ll num2 = ((modpow(2, b) - 1) * (modpow(2, d) - 1)) % mod;
		num2 *= (modpow(2, a)*modpow(2, c))%mod;
		num2 %= mod;
		ll num3 = ((modpow(2, a) - 1)*(modpow(2, b) - 1))%mod;
		num3 *= ((modpow(2, c) - 1)*(modpow(2, d) - 1))%mod;
		num3 %= mod;
		ans += num1 + num2 - num3 + 10LL*mod;
		ans %= mod;
		unused.plus(ind, -1);
		used.plus(ind, 1);
	}
	puts(ans);

	return 0;
}

