	while ( abs( right - left ) > 1 )
	{
		ll mid = ( left + right ) / 2;
		if ( val > v[mid] )
			left = mid;
		else
			right = mid;
	}

	return ( mp( v[right] == val, right ) );
}

struct BIT {
	vector<ll> data;
	ll size;
	BIT( ll n ) {
		size = n;
		data.assign( n + 1, 0 );
	};

	void add( ll i, ll v ) {
		while ( i < size ) {
			data[i] += v;
			i += i & -i;
		};
	}

	ll sum( ll i ) {
		ll res = 0;
		while ( i > 0 ) {
			res += data[i];
			i -= i & -i;
		};

		return ( res );
	}

	ll sum( ll i, ll j ) {
		return ( sum( j ) - sum( i - 1 ) );
	}
};

