struct node {
    int x, y;
    node (int xx = 0, int yy = 0) {
        x = xx;
        y = yy;
    }

    bool operator < (const node &another) const {
        if (x == another.x)
            return y < another.y;
        else
            return x < another.x;
    }
}point[MAXN];

struct BITree {
    int BIT[MAXN];

    void clear() {
        memset(BIT, 0, sizeof(BIT));
    }

    int lowbit(int key) {
        return key & (-key);
    }

    void modify(int place, int key) {
        for (; place <= n; place += lowbit(place)) {
            BIT[place] += key;
        }
    }

    int query(int place) {
        int tmp = 0;
        for (; place; place -= lowbit(place)) {
            tmp += BIT[place];
        }
        return tmp;
    }
}root;

