	int cnt = 0;
	for(auto &a:mp){
		a.second=cnt;
		cnt++;
	}

	vector<int> x(N,0);
	segtree<int> S1(x);
	for(int i=0;i<N;i++)x[i]=1;
	segtree<int> S2(x);

	int ans = mod(beki(2,N)*N);
	for(int i=0;i<N;i++){
		S2.update(mp[V[i].second],0);
		int RU = S2.query(mp[V[i].second],N);
		int RD = S2.query(0,mp[V[i].second]);
		int LU = S1.query(mp[V[i].second],N);
		int LD = S1.query(0,mp[V[i].second]);

		ans = mod(ans - beki(2,RU+RD));
		ans = mod(ans - beki(2,RU+LU));
		ans = mod(ans - beki(2,LU+LD));
		ans = mod(ans - beki(2,RD+LD));

		ans = mod(ans + beki(2,RU));
		ans = mod(ans + beki(2,RD));
		ans = mod(ans + beki(2,LU));
		ans = mod(ans + beki(2,LD));

		S1.update(mp[V[i].second],1);

		ans = mod(ans-1);

	}
	if(N==1)ans = 1;
	cout<<ans<<endl;


