const int MOD = 998244353;
const int maxn = 2e5 + 5;
int Bit[maxn], A[maxn], n;
pair<int, int> p[maxn];

void Update(int i) {
    while(i <= n) {
        Bit[i]++;
        i += i&(-i);
    }
}
int Getsum(int i) {

    int res = 0;
    while(i) {
        res += Bit[i];
        i -= i&(-i);
    }
    return res;
}

int main() {

    scanf("%d", &n);
    for(int i = 0; i < n; i++)
        scanf("%d%d", &p[i].first, &p[i].second);

    sort(p, p+n);
    for(int i = 0; i < n; i++) {
        p[i].first = p[i].second;
        p[i].second = i;
    }

    sort(p, p+n);
    A[0] = 1;
    for(int i = 1; i <= n; i++) {
        A[i] = A[i-1]<<1;
        if(A[i] >= MOD) A[i] -= MOD;
    }
    int ans = 0;
    for(int i = 0; i < n; i++) {

        int t = Getsum(p[i].second+1);
        int a = A[t], b = A[p[i].second-t], c = A[i-t], d = A[n-1-(i+p[i].second-t)];
        ans = ((long long)(a+d-1)*(b+c-1)%MOD + ans) % MOD;
        Update(p[i].second+1);
    }

    ans = ((long long)n*A[n] - ans) % MOD;
    printf("%d", (ans+MOD)%MOD);
	return 0;
}

