template <typename T>
struct BIT{
	vector<T> v;
	int n;

	const T init_value = 0;

	BIT(int sz){
		n=sz+1;
		v.resize(n,init_value);
	}

	BIT(vector<T> &x){
		n=x.size()+1;
		v.resize(n,init_value);

		for(int i=0;i<x.size();i++){
			add(i,x[i]);
		}

	}

	void add(int x,T val){
		x++;
		while(x < n){
			v[x] = func(v[x],val);
			x += x & (-x);
		}
	}

	//区間[0,r)におけるクエリ処理
	T query(int r){
		T ret = init_value;
		r++;

		while(r>0){
			ret = func(v[r],ret);
			r -= r & (-r);
		}

		return ret;
	}

	T query(int l,int r){
		return mod(query(r-1) - query(l-1));
	}

	T func(T a,T b){
		return mod(a+b);
	}

};

