struct BIT{
private:
  vector<ll> node;
  ll siz;
public:
  BIT(ll n){
    siz=n;
    node.resize(n+1,0);
  }
  void add(ll pos,ll x){
    while(pos<=siz){
      node[pos]+=x;
      pos+=pos&(-pos);
    }
  }
  ll sum(ll pos){
    ll res=0;
    while(pos>0){
      res+=node[pos];
      pos-=pos&(-pos);
    }
    return res;
  }
};
