template<typename T>
struct SegmentTree{
private:
    int n;
    T E;
    vector<T> node;
    inline void updatef(T& x,T& y){
        x = y;
    }
    inline T queryf(T& x,T& y){
        return x+y;
    }

public:
    SegmentTree(int sz,T E_):E(E_){
        n=1;
        while(n<sz)n<<=1;
        node.resize(2*n-1,E);
    }

    SegmentTree(vector<T>& A,T E_):E(E_){
        int sz=A.size();
        n=1;
        while(n<sz)n<<=1;
        node.resize(2*n-1,E);
        rep(i,sz)node[i+n-1]=A[i];
        for(int i=n-2;i>=0;--i){
            node[i]=queryf(node[2*i+1], node[2*i+2]);
        }
    }
    void update(int k,T x){
        k+=n-1;
        updatef(node[k],x);
        while(k>0){
            k=(k-1)/2;
            node[k]=queryf(node[2*k+1], node[2*k+2]);
        }
    }
       //[a,b)での和を返す
    T get(int a,int b,int k=0,int l=0,int r=-1){
        if(r<0)r=n;
        if(r<=a||b<=l)return E;
        if(a<=l&&r<=b)return node[k];
        T xl=get(a,b,2*k+1,l,(l+r)/2);
        T xr=get(a,b,2*k+2,(l+r)/2,r);
        return queryf(xl, xr);
    }
};

ll powmod(ll n,ll k){
    ll ret = 1;
    while(k){
        if(k&1)ret=ret*n%mod;
        n=n*n%mod;
        k>>=1;
    }
    return ret;
}
int main(){
    int n;
    cin>>n;
    int x[n],y[n];
    vector<int> xs,ys;
    rep(i,n){
        cin>>x[i]>>y[i];
        xs.push_back(x[i]);
        ys.push_back(y[i]);
    }
    sort(xs.begin(),xs.end());
    sort(ys.begin(),ys.end());
    rep(i,n){
        x[i]=lower_bound(xs.begin(), xs.end(),x[i])-xs.begin();
        y[i]=lower_bound(ys.begin(), ys.end(),y[i])-ys.begin();
    }
    vector<int> ord(n);
    iota(ord.begin(),ord.end(),0);
    vector<int> lu(n),ld(n),ru(n),rd(n);
    SegmentTree<int> sg(n,0);
    sort(ord.begin(),ord.end(),[&](int i, int j){
        return x[i]<x[j];
    });
    for(auto i : ord){
        lu[i]=sg.get(0,y[i]);
        ld[i]=sg.get(y[i],n);
        sg.update(y[i],1);
    }
    rep(i,n)sg.update(i,0);
    reverse(ord.begin(),ord.end());
    for(auto i : ord){
        ru[i]=sg.get(0,y[i]);
        rd[i]=sg.get(y[i],n);
        sg.update(y[i],1);
    }
    ll ans = 0;
    rep(i,n){
        ans+=powmod(2,n);
        ans+=mod-powmod(2,lu[i]+ld[i]);
        ans+=mod-powmod(2,ru[i]+rd[i]);
        ans+=mod-powmod(2,lu[i]+ru[i]);
        ans+=mod-powmod(2,ld[i]+rd[i]);
        ans+=powmod(2,lu[i]);
        ans+=powmod(2,ld[i]);
        ans+=powmod(2,ru[i]);
        ans+=powmod(2,rd[i]);
        ans+=mod-1;
    }
    cout<<ans%mod<<endl;
    return 0;
}

