  }

  // x-first
  sort(ps.begin(), ps.end(), [](const N &l, const N &r) {
    if (l.x == r.x)
      return l.y < r.y;
    return l.x < r.x;
  });
  ll bef = -1;
  vector<int> buf;
  auto xr = sumrmq(n);
  for (int i = 0; i < n; i++) {
    if (bef != xmp[ps[i].x]) {
      for (auto &j : buf) {
        xr.update(j, xr.query(j, j + 1) + 1);
      }
      buf.clear();
    }
    ul[ps[i].i] = xr.query(0, ymp[ps[i].y]);
    dl[ps[i].i] = xr.query(ymp[ps[i].y] + 1, n);
    buf.push_back(ymp[ps[i].y]);
    bef = xmp[ps[i].x];
  }

  // x-rev-first
  bef = -1;
  buf.clear();
  auto yr = sumrmq(n);
  sort(ps.begin(), ps.end(), [](const N &l, const N &r) {
    if (l.x == r.x)
      return l.y < r.y;
    return l.x > r.x;
  });
  for (int i = 0; i < n; i++) {
    if (bef != xmp[ps[i].x]) {
      for (auto &j : buf) {
        yr.update(j, yr.query(j, j + 1) + 1);
      }
      buf.clear();
    }
    ur[ps[i].i] = yr.query(0, ymp[ps[i].y]);
    dr[ps[i].i] = yr.query(ymp[ps[i].y] + 1, n);
    buf.push_back(ymp[ps[i].y]);
    bef = xmp[ps[i].x];
  }

  sort(xs.begin(), xs.end());
  sort(ys.begin(), ys.end());
