    t %= P;
    t += (cmp.power(2, u) - 1 + P) % P;
    t %= P;
    t += (cmp.power(2, d) - 1 + P) % P;
    t %= P;
    t += P - cmp.power(2, ul[ps[i].i]) + 1;
