        if (y.at(j) < y.at(i)) {
          D = (D * 2) % p;
        } else if (y.at(i) < y.at(j)) {
          A = (A * 2) % p;
        }
      }
    }
//    cout << "A = " << A << ", B = " << B << ", C = " << C << ", D = " << D << endl;

    ans += (A * B * C * D) % p; //P_i ∊ T
    ans += ((A - 1) * (B - 1) * (C - 1) * (D - 1)) % p;//以下P_i ∉ T
    ans += ((A - 1) * (B - 1) * (C - 1)) % p;
    ans += ((A - 1) * (B - 1) * (D - 1)) % p;
    ans += ((A - 1) * (C - 1) * (D - 1)) % p;
    ans += ((B - 1) * (C - 1) * (D - 1)) % p;
    ans += ((A - 1) * (C - 1)) % p;
    ans += ((B - 1) * (D - 1)) % p;
//    cout << "ans = " << ans<< endl << endl;
  }

  cout << ans;
}

