    }
    sort(X, X + N), sort(Y, Y + N);

    p2[0] = 1; 
    rep(i,N){
        p2[i + 1] = p2[i] * 2;
        if (p2[i + 1] > MOD) p2[i + 1] -= MOD;
    }

    BIT<ll> bl(N), br(N);
    rep(i,N){
        ll nx = lower_bound(X, X + N, R[i].x) - X, ny = lower_bound(Y, Y + N, R[i].y) - Y;
        R[i] = {nx, ny};
        br.add(ny);
    }

