    rep(i,N){
        ll nx = R[i].x, ny = R[i].y, lc = i, rc = N - i - 1;
        br.add(ny, -1);
        (ans += p2[N - 1]) %= MOD; // 点Tを含む任意の集合

        ll cll = (p2[bl.sum(ny)] - 1), cbb = (p2[rc - br.sum(ny)] - 1), clb = (p2[lc - bl.sum(ny)] - 1), cbl = (p2[br.sum(ny)] - 1);
        ll C1 = (cll * cbb) % MOD, C2 = (clb * cbl) % MOD;
        (ans += C1 + C2 + (C1 * (clb + cbl)) % MOD + (C2 * (cll + cbb)) % MOD + C1 * C2 % MOD) %= MOD;
        bl.add(ny);
    }

    cout << ans << endl;
}

