ll mod_pow(ll x, ll p, ll M = MOD) {
  ll a = 1;
  while (p) {
    if (p % 2)
      a = a*x%M;
    x = x*x%M;
    p /= 2;
  }
  return a;
}


template <typename T>
class SegmentTree {
public:
  using F = function<T(T&, T&)>;
  int n;
  vector<T > dat;
  T e; // 単位元
  F query_func;
  F update_func;

  SegmentTree(vector<T> a, F query_func, F update_func, T e) :n(a.size()), query_func(query_func), update_func(update_func), e(e) {
    dat.resize(4 * n);
    init(0, 0, n, a);
  }

  void init(int k, int l, int r, vector<T> &a) {
    if (r - l == 1) {
      dat[k] = a[l];
    }
    else {
      int lch = 2 * k + 1, rch = 2 * k + 2;
      init(lch, l, (l + r) / 2, a);
      init(rch, (l + r) / 2, r, a);
      dat[k] = query_func(dat[lch], dat[rch]);
    }
  }

  //k番目の値をaに変更
  void update(int k, T a, int v, int l, int r) {
    if (r - l == 1) {
      dat[v] = update_func(dat[v], a);
    }
    else {
      if (k < (l + r) / 2)
        update(k, a, 2 * v + 1, l, (l + r) / 2);
      else {
        update(k, a, 2 * v + 2, (l + r) / 2, r);
      }
      dat[v] = query_func(dat[v * 2 + 1], dat[v * 2 + 2]);
    }
  }


  //[a,b)の最小値を求める
  //後ろのほうの引数は計算の簡単のための引数
  //kは接点の番号,l,rはその接点が[l,r)に対応していることを表す
  //従って、外からはquery(a,b,0,0,n)としてよぶ
  T query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) {
      return e;
    }
    if (a <= l && r <= b) {
      return dat[k];
    }
    else {
      T ul = query(a, b, k * 2 + 1, l, (l + r) / 2);
      T ur = query(a, b, k * 2 + 2, (l + r) / 2, r);
      return query_func(ul, ur);
    }
  }
};

int f1(int a, int b) {return a + b;}
int f2(int a, int b) {return a + b;}

int main() {
  int n;
  cin >> n;
  vi x(n), y(n);
  map<int, int> mpx, mpy;
  rep (i, n) {
    cin >> x[i] >> y[i];
    mpx[x[i]] = 0;
    mpy[y[i]] = 0;
  }

  int cnt = 0;
  for (auto itr = mpx.begin(); itr != mpx.end(); itr++) {
    mpx[itr->first] = cnt;
    cnt++;
  }
  cnt = 0;
  for (auto itr = mpy.begin(); itr != mpy.end(); itr++) {
    mpy[itr->first] = cnt;
    cnt++;
  }

  vector<pii> xy(n);
  rep (i, n) {
    xy[i] = pii(mpx[x[i]], mpy[y[i]]);
  }
  sort(all(xy));

  vl d1(n), d2(n), d3(n), d4(n);
  SegmentTree<int> seg(vi(n, 0), f1, f2, 0);
  rep (i, n) {
    int y = xy[i].second;
    d1[i] = seg.query(0, y, 0, 0, seg.n);
    d2[i] = seg.query(y + 1, seg.n, 0, 0, seg.n);
    seg.update(y, 1, 0, 0, seg.n);
  }
  seg = SegmentTree<int>(vi(n, 0), f1, f2, 0);
  rrep (i, n) {
    int y = xy[i].second;
    d3[i] = seg.query(0, y, 0, 0, seg.n);
    d4[i] = seg.query(y + 1, seg.n, 0, 0, seg.n);
    seg.update(y, 1, 0, 0, seg.n);
  }

  ll ans = 0;
  rep (i, n) {
    ans += mod_pow(2, n - 1);
    ll add = mod_pow(2, n - 1);
    add -= mod_pow(2, d1[i] + d2[i]);
    add -= mod_pow(2, d2[i] + d4[i]);
    add -= mod_pow(2, d4[i] + d3[i]);
    add -= mod_pow(2, d3[i] + d1[i]);
    add %= MOD;
    add += mod_pow(2, d1[i]);
    add += mod_pow(2, d2[i]);
    add += mod_pow(2, d3[i]);
    add += mod_pow(2, d4[i]);
    add %= MOD;
    add -= 1;
    (ans += add) %= MOD;
  }

  ans = (ans + MOD) % MOD;
  cout << ans << endl;
}

