int bs(int u) {
    int dau = 0, cuoi = SZ(b)-1;
    while (dau <= cuoi) {
        int mid = (dau + cuoi) >> 1;
        if (b[mid] > u) cuoi = mid-1;
        else dau = mid+1;
    }
    return cuoi;
