        int rig = n - i;
        int lef = i - 1;
        //cout << upper << ' ' << lower << ' ' << lef << ' ' << rig << endl;
        ll p = (mu[upper] + mu[lower] + mu[rig] + mu[lef]) % MODBASE;
        res[i] = (res[i] - p + MODBASE) % MODBASE;
    }
    ll kq = 0;
    // FOR(i,1,n) cout << res[i] << ' ';
    // cout << endl;
    FOR(i,1,n) kq = (kq + res[i]) % MODBASE;
    cout << kq;
    return 0;
}

