        ll upright=useg.query(id[p.x]+1,n);
        ll downright=dseg.query(id[p.x]+1,n);

        ll mi=f(upleft+downleft)+f(upright+downright)+f(upleft+upright)+f(downleft+downright);
        mi%=mod;
        mi+=mod-f(upleft)+mod-f(upright)+mod-f(downleft)+mod-f(downright);
        mi%=mod;
        ans+=mod-mi;
        ans%=mod;

        useg.update(id[p.x],0);
        dseg.update(id[p.x],1);
    }
    cout<<ans<<endl;
    return 0;
}

