void merge (int l,int r) {
	if (l==r) {
		return;
	} else {
		int mid=(l+r)/2,k=l,i=l,j=mid+1;
		merge(l,mid);
		merge(mid+1,r);
		while (i<=mid&&j<=r) {
			if (p[i].second<p[j].second) {cnt[p[i].id][2]+=j-mid-1,cnt[p[i].id][3]+=r-j+1;tp[k++]=p[i++];
			} else {cnt[p[j].id][0]+=i-l,cnt[p[j].id][1]+=mid-i+1;tp[k++]=p[j++];}
		}
		while (i<=mid) {cnt[p[i].id][2]+=j-mid-1;tp[k++]=p[i++];}
		while (j<=r) {cnt[p[j].id][0]+=i-l;tp[k++]=p[j++];}
		for (int ii=l;ii<=r;ii++) {p[ii]=tp[ii];}
	}
	return;
}
