class Count2D{
public:
  Int n;
  vector<vector<Int> > dat;

  Count2D(){}
  Count2D(Int n_){
    n=1;
    while(n < n_) n*=2;
    dat.resize(2*n-1);
  }

  //n_ := x軸方向に確保する要素の個数
  //xは0 <= x < n_である必要がある。yはいくつでも大丈夫
  //O(n * log(n))
  Count2D(Int n_,vector<pair<Int,Int> > A){ //x, y
    n=1;
    while(n < n_) n*=2;
    dat.resize(2*n-1);

    for(auto a:A){
      Int x,y; tie(x,y) = a;
      assert(0 <= x && x < n_);
      dat[x+n-1].push_back(y);
    }

    function<void(Int)> init=[&](Int k){
      if(k >= n-1) {sort(dat[k].begin(),dat[k].end());return;}
      init(k*2+1), init(k*2+2);

      const auto &a = dat[k*2+1], &b = dat[k*2+2];
      auto &c = dat[k];
      Int i = 0, j = 0;
      while(i < (Int)a.size() || j < (Int)b.size()){
        if(i == (Int)a.size()) c.push_back(b[j++]);
        else if(j == (Int)b.size()) c.push_back(a[i++]);
        else if(a[i] < b[j]) c.push_back(a[i++]);
        else c.push_back(b[j++]);
      }
    };
    init(0);
  }

  // O(nlog(n))
  void update(Int x, Int y){
    assert(0 <= x && x < n);
    auto insert = [&](vector<Int> &A, Int a){
      A.push_back(a);
      Int idx = (Int)A.size()-1;
      while(idx && A[idx-1] > A[idx]) swap(A[idx-1],A[idx]),idx--;
    };

    x += n-1;
    insert(dat[x], y);
    while(x>0) x=(x-1)/2, insert(dat[x],y);
  }

  Int x, X, y, Y;
  Int count(Int k, Int l, Int r){
    if(r <= x || X <= l) return 0;
    if(x <= l && r <= X){
      Int a = lower_bound(dat[k].begin(), dat[k].end(), y) - dat[k].begin();
      Int b = upper_bound(dat[k].begin(), dat[k].end(), Y) - dat[k].begin();
      return b - a;
    }
    Int vl=count(k*2+1, l, (l+r)/2);
    Int vr=count(k*2+2, (l+r)/2, r);
    return vl + vr;
  }

  //[x,X)かつ[y,Y)の点の数を求める count(x,X,y,Y,0,0,n)
  // O(log(n) * log(n))
  Int count(Int x, Int X, Int y, Int Y){
    assert(x <= X && y <= Y);
    assert(0 <= x && x <= n);
    assert(0 <= X && X <= n);
    this->x = x;
    this->X = X;
    this->y = y;
    this->Y = Y;
    return count(0, 0, n);
  }
};


Int pow2(Int x){
  static Int mem[300000];
  if(x == 0) return 1;
  if(mem[x] != 0) return mem[x];
  return mem[x] = 2 * pow2(x - 1) % mod;
}

Int add(Int a, Int b){
  a = a % mod + mod;
  b = b % mod + mod;
  return (a + b) % mod;
}

