    for(int i=n-1; i>=0; --i){
        int Y = h[i];
        R[i][0] = t.query(0,Y);
        R[i][1] = t.query(Y+1,n);
        t.add(Y, 1);
    }

    ll ans = 0;
    rep(i,n){
        // not include p[i]
        rep(lm,1<<2)rep(rm,1<<2){
            bool valid = false;
            rep(j,2){
                if((lm>>j&1) && (rm>>(!j)&1)) valid = true;
            }
            if(!valid) continue;

            ll add = 1;
            rep(j,2){
                if(lm>>j&1) (add *= (p2[L[i][j]]-1+mod)) %= mod;
                if(rm>>j&1) (add *= (p2[R[i][j]]-1+mod)) %= mod;
            }
            (ans += add) %= mod;
        }

        // include p[i]
        (ans += p2[n-1]) %= mod;
    }
    cout << ans << "\n";
    return 0;
}

