template<typename T>
struct BIT {
  int n;
  vector<T> d;
  BIT(int n=0):n(n),d(n+1) {}
    //末尾の要素(i&-i)をたす→一つ上の階層なので、要素の更新の時に使える
  void add(int i, T x=1) {
    for (i++; i <= n; i += i&-i) {
      d[i] += x;
    }
  }
     //末尾の要素(i&-i)を引く→一つ上の一つ左の階層なので、要素の総和をとる時に使える
  T sum(int i) {
    T x = 0;
    for (i++; i; i -= i&-i) {
      x += d[i];
    }
    return x;
  }
	T sum(int l, int r) {
    return sum(r-1) - sum(l-1);
  }
};

mint calc(ll a, ll b, ll c, ll d){
	mint ans=0;

	mint a1=mint(2).pow(a);
	mint b1=mint(2).pow(b);
	mint c1=mint(2).pow(c);
	mint d1=mint(2).pow(d);

	ans+=(a1-1)*b1*(c1-1)*d1;
	ans+=a1*(b1-1)*c1*(d1-1);
	ans-=(a1-1)*(b1-1)*(c1-1)*(d1-1);
	ans+=a1*b1*c1*d1;

	return ans;
}

