constexpr ll MOD = 998244353;

ll mod_pow(ll base, ll p) {
	ll res = 1;
	while (p > 0) {
		if (p & 1)(res *= base) %= MOD;
		(base *= base) %= MOD;
		p >>= 1;
	}
	return res;
}

ll red_area(ll N) {
	ll res = 0;
	rep(i, N) {
		res += 2 * (mod_pow(2, i) - 1);
		res += 2 * (mod_pow(2, N - 1 - i) - 1);
		res %= MOD;
	}
	return res;
}

ll sum(vector<ll>& bit, ll i) {
	i++;
	ll s = 0;
	while (i > 0) {
		s += bit[i];
		i -= i & -i;
	}
	return s;
}
void add(vector<ll>& bit, ll i, ll x) {
	i++;
	while (i < bit.size()) {
		bit[i] += x;
		i += i & -i;
	}
}

ll blue_area(vector<pair<ll, ll>>& xys, vector<ll> ys) {
	const ll N = xys.size();
	map<ll, ll> mp;
	rep(i, N)mp[ys[i]] = i;

	ll res = 0;
	vector<ll> bit(N + 1, 0);
	rep(i, N) {
		ll y = xys[i].second;
		ll point = sum(bit, mp[y]);
		res += mod_pow(2, point) - 1;
		res += mod_pow(2, i - point) - 1;
		res %= MOD;
		add(bit, mp[y], 1);
	}

	fill(bit.begin(), bit.end(), 0);
	for (int i = N - 1; i >= 0; i--) {
		ll y = xys[i].second;
		ll point = sum(bit, mp[y]);
		res += mod_pow(2, point) - 1;
		res += mod_pow(2, (N - 1 - i) - point) - 1;
		res %= MOD;
		add(bit, mp[y], 1);
	}
	return res;
}

int main()
{
	ll N;
	cin >> N;

	vector<ll> xs, ys;
	vector<pair<ll, ll>> xys;
	rep(i, N) {
		ll x, y;
		cin >> x >> y;
		xs.push_back(x);
		ys.push_back(y);
		xys.push_back({ x,y });
	}
	sort(xs.begin(), xs.end());
	sort(ys.begin(), ys.end());
	sort(xys.begin(), xys.end());

	ll total = (N*(mod_pow(2, N) - 1)) % MOD;
	ll ignore = red_area(N) - blue_area(xys, ys);
	ll res = (total - ignore) % MOD;
	res = (res + MOD) % MOD;

	cout << res << endl;
	return 0;
}

