int N;
point points[200005];
int UL[200005]; int UR[200005];
int DL[200005]; int DR[200005];
int two[200005];

const int mod = 998244353;

void add(int &ans, int dod) {
    ans = (ans % mod + dod % mod) % mod;
}

int mul(long long a, long long b, long long c, long long d) {
    long long a1 = (two[a] % mod + mod - 1) % mod;
    long long b1 = (two[b] % mod + mod - 1) % mod;
    long long c1 = (two[c] % mod + mod - 1) % mod;
    long long d1 = (two[d] % mod + mod - 1) % mod;
    return (a1 * b1) % mod * c1 % mod * d1 % mod;
}

int mul(long long a, long long b, long long c) {
    long long a1 = (two[a] % mod + mod - 1) % mod;
    long long b1 = (two[b] % mod + mod - 1) % mod;
    long long c1 = (two[c] % mod + mod - 1) % mod;
    return (a1 * b1) % mod * c1 % mod;
}

int mul(long long a, long long b) {
    long long a1 = (two[a] % mod + mod - 1) % mod;
    long long b1 = (two[b] % mod + mod - 1) % mod;
    return (a1 * b1) % mod;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin >> N;
    for(int i = 1; i <= N; i++)
        cin >> points[i].x >> points[i].y;

    sort(points + 1, points + N + 1);

    ordered_set s;

    int j = 1;
    for(int i = 1; i <= N; i++) {
        while(j <= N && points[i].y == points[j].y)
            s.insert(points[j++].x);
        int ord = s.order_of_key(points[i].x);
        UL[i] = ord;
        UR[i] = s.size() - ord - 1;
    }

    s.clear();
    j = N;
    for(int i = N; i >= 1; i--) {
        while(j >= 1 && points[i].y == points[j].y)
            s.insert(points[j--].x);
        int ord = s.order_of_key(points[i].x);
        DL[i] = ord;
        DR[i] = s.size() - ord - 1;
    }

    two[0] = 1;
    for(int i = 1; i <= N; i++)
        two[i] = (two[i - 1] * 2LL) % mod;

    int ans = 0;
    for(int i = 1; i <= N; i++) {
//        cerr << "(" << points[i].x << ", " << points[i].y << ")" << endl;
//        cerr << UL[i] << " " << UR[i] << endl;
//        cerr << DL[i] << " " << DR[i] << endl;
//        add(ans, ((two[UL[i]] + mod - 1) * 1LL * (two[DR[i]] + mod - 1)) % mod);
        add(ans, mul(UL[i], DR[i]));
        add(ans, mul(DL[i], UR[i]));
        add(ans, mul(UL[i],UR[i], DR[i]));
        add(ans, mul(UR[i],DR[i], DL[i]));
        add(ans, mul(DR[i],DL[i], UL[i]));
        add(ans, mul(DL[i],UL[i], UR[i]));

        add(ans, mul(DL[i], UL[i],DR[i], UR[i]));

        add(ans, two[N - 1]);
//        cerr << " := " << ans << endl << endl;
    }
    cout << ans << endl;
}
