struct SegT2d {
	int H, W;
	vector< vector< int > > dat;
	SegT2d() {}
	SegT2d(vector< vector< int > > &f) {
		H = W = 1;
		while (H < (int)f.size())
			H <<= 1;
		while (W < (int)f[0].size())
			W <<= 1;
		dat.assign(2 * H - 1, vector< int >(2 * W - 1, 0));
		init(f);
	}
	void init(vector< vector< int > > &f) {
		for (int i = 0; i < (int)f.size(); i++)
			for (int j = 0; j < (int)f[0].size(); j++)
				dat[i + H - 1][j + W - 1] = f[i][j];
		for (int i = 2 * H - 2; i > H - 2; i--)
			for (int j = W - 2; j >= 0; j--)
				dat[i][j] = (dat[i][2 * j + 1] + dat[i][2 * j + 2]);
		for (int i = H - 2; i >= 0; i--)
			for (int j = 0; j < 2 * W - 1; j++)
				dat[i][j] = (dat[2 * i + 1][j] + dat[2 * i + 2][j]);
	}
	int get(int li, int lj, int ri, int rj) { return get_h(li, lj, ri, rj, 0, H, 0); }
	int get_h(int li, int lj, int ri, int rj, int si, int ti, int k) {
		if (ri <= si or ti <= li)
			return 0;
		if (li <= si and ti <= ri)
			return get_w(lj, rj, 0, W, k, 0);
		const int mi = (si + ti) / 2;
		return (get_h(li, lj, ri, rj, si, mi, 2 * k + 1) + get_h(li, lj, ri, rj, mi, ti, 2 * k + 2));
	}
	int get_w(int lj, int rj, int sj, int tj, int i, int k) {
		if (rj <= sj or tj <= lj)
			return 0;
		if (lj <= sj and tj <= rj)
			return dat[i][k];
		const int mj = (sj + tj) / 2;
		return (get_w(lj, rj, sj, mj, i, 2 * k + 1) + get_w(lj, rj, mj, tj, i, 2 * k + 2));
	}
};
int compress(vector< int > &x) {
	vector< int > xs = x;
	int N = x.size();
	sort(xs.begin(), xs.end());
	xs.erase(unique(xs.begin(), xs.end()), xs.end());
	for (int i = 0; i < N; i++) {
		x[i] = lower_bound(xs.begin(), xs.end(), x[i]) - xs.begin();
	}
	return xs.size();
}
ll gcd(ll a, ll b) {
	if (b == 0)
		return a;
	else
		return gcd(b, a % b);
}
ll extgcd(ll a, ll b, ll &x, ll &y) {
	int d = a;
	if (b != 0) {
		d = extgcd(b, a % b, y, x);
		y -= (a / b) * x;
	} else {
		x = 1;
		y = 0;
	}
	return d;
}
ll factorial(ll x) {
	if (x == 1)
		return 1;
	else
		return x * factorial(x - 1);
}
ll Mfactorial(ll x, ll m) {
	ll ret = 1;
	for (ll i = 1; i <= x; i++) {
		ret *= i;
		ret %= m;
	}
	return ret;
}
vector< int > MfactTable(int n, int m) {
	vector< int > ret(n + 1);
	ret[0] = 1;
	int tmp = 1;
	for (int i = 1; i <= n; i++) {
		tmp *= i;
		tmp %= m;
		ret[i] = tmp;
	}
	return ret;
}
int Minverse(int a, int m) {
	int x, y;
	extgcd(a, m, x, y);
	return (m + x % m) % m;
}
int McombSmall(int n, int k, int m) {
	//O(n)
	int ret = Mfactorial(n, m);
	ret *= Minverse(Mfactorial(k, m), m);
	ret %= m;
	ret *= Minverse(Mfactorial(n - k, m), m);
	return ret % m;
}
int McombFromFactTable(vector< int > &T, int n, int k, int m) {
	if (k > n)
		return 0;
	int ret = T[n];
	ret *= Minverse(T[k], m);
	ret %= m;
	ret *= Minverse(T[n - k], m);
	return ret % m;
}
ll pow(ll x, int n) {
	if (n == 0)
		return 1;
	ll ret = (n & 1) ? x : 1;
	ll a = pow(x, n / 2);
	return ret * a * a;
}
ll Mpow(ll x, int n, int m) {
	if (n == 0)
		return 1;
	ll ret = (n & 1) ? x : 1;
	ll a = Mpow(x, n / 2, m);
	return (((ret * a) % m) * a) % m;
}
vector< vector< int > > combTable(int N) {
	vector< vector< int > > ret(N + 1, vector< int >(N + 1));
	for (int i = 0; i <= N; i++)
		for (int j = 0; j <= i; j++) {
			if (j == 0 || j == i)
				ret[i][j] = 1;
			else
				ret[i][j] = ret[i - 1][j - 1] + ret[i - 1][j];
		}
	return ret;
}
