constexpr ll MOD = 998224353;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll n;
  cin>>n;
  vector<tuple<ll,ll>> vpx, vpy;
  ll off = 1000000000;
  REP(i,n) {
    ll x,y;
    cin>>x>>y;
    x += off;
    y += off;
    vpx.emplace_back(x,y);
    vpy.emplace_back(y,x);
  }
  vecll p2(n+1);
  p2[0] = 1;
  REP(i,n) {
    p2[i+1] = p2[i] * 2 % MOD;
  }
  sort(ALL(vpx));
  sort(ALL(vpy));
  BIT bit;
  ll ans = 0;
  REP(i,n) {
    auto&&[x,y] = vpx[i];
    ll up = lower_bound(ALL(vpy), make_tuple(y, -1)) - begin(vpy);
    ll left = i;
    ll right = n - i - 1;
    ll down = n - up - 1;
    //cerr<<up<<" "<<left<<" "<<right<<" "<<down<<endl;
    ll up_left = bit.query(up-1);
    ll up_right = up - up_left;
    ll down_left = left - up_left;
    ll down_right = right - up_right;
    ll tmp = p2[up] + p2[down] + p2[left] + p2[right];
    tmp %= MOD;
    tmp += MOD - p2[up_left];
    tmp += MOD - p2[up_right];
    tmp += MOD - p2[down_left];
    tmp += MOD - p2[down_right];
    tmp %= MOD;
    //cerr<<tmp<<endl;
    ans += p2[n] + MOD - tmp;
    ans %= MOD;
    bit.update(up,1);
  }
  ans += MOD - n;
  ans %= MOD;
  cout<<ans<<endl;
  return 0;
}

