void build(int l, int r, int i) {
	if (l + 1 == r) {
		zb[i] = 1;
		return;
	}
	int mi = (l + r) / 2;
	build(l, mi, i * 2);
	build(mi, r, i * 2 + 1);
	zb[i] = zb[i * 2] + zb[i * 2 + 1];
}

void f1(int a, int l, int r, int i) {
	za[i]++;
	if (a == l && a + 1 == r)
		return;
	int mi = (l + r) / 2;
	if (a < mi)
		f1(a, l, mi, i * 2);
	else
		f1(a, mi, r, i * 2 + 1);
}

void f2(int a, int l, int r, int i) {
	zb[i]--;
	if (a == l && a + 1 == r)
		return;
	int mi = (l + r) / 2;
	if (a < mi)
		f2(a, l, mi, i * 2);
	else
		f2(a, mi, r, i * 2 + 1);
}

int qa(int a, int b, int l, int r, int i) {
	if (a == l && b == r)
		return za[i];
	int mi = (l + r) / 2, re = 0;
	if (a < mi)
		re = qa(a, min(mi, b), l, mi, i * 2);
	if (mi < b)
		re += qa(max(mi, a), b, mi, r, i * 2 + 1);
	return re;
}

int qb(int a, int b, int l, int r, int i) {
	if (a == l && b == r)
		return zb[i];
	int mi = (l + r) / 2, re = 0;
	if (a < mi)
		re = qb(a, min(mi, b), l, mi, i * 2);
	if (mi < b)
		re += qb(max(mi, a), b, mi, r, i * 2 + 1);
	return re;
}

