void calc() {
    sort(p, p + n);
    vector<int> v;

    for (int i = 0; i < n; ++i)
        v.emplace_back(p[i].y);

    sort(begin(v), end(v));
    v.resize(unique(begin(v), end(v)) - begin(v));
    fenwick f(v.size());

    for (int i = 0; i < n; ++i) {
        ans -= pw[i];
        ans += pw[f.get(lower_bound(begin(v), end(v), p[i].y) - begin(v))];
        f.upd(lower_bound(begin(v), end(v), p[i].y) - begin(v), 1);
    }
}

void solve() {
    pw[0] = 1;
    for (int i = 0; i < n; pw[++i] = 2 * pw[i - 1] % M) { }
