    for (int i = 0; i < n; swap(p[i].x *= -1, p[i].y), ++i) { }
    calc();
    for (int i = 0; i < n; p[i].x *= -1, p[i].y *= -1, ++i) { }
    calc();
    cout << (M + ans % M) % M << endl;
}

