void F(int &a) {
	a=lower_bound(e+1,e+tot+1,a)-e;
}
int tr[maxn*2];
void add(int x) {
	for (;x<=tot;x+=x&(-x)) tr[x]++;
}
int query(int x) {
	int res=0;
	for (;x>0;x-=x&(-x)) res+=tr[x];
	return res;
}
int main() {
