		e[++tot]=d[i].y;
	}
	sort(e+1,e+tot+1);
	tot=unique(e+1,e+tot+1)-e-1;
	for (int i=1;i<=n;i++)
		F(d[i].x),F(d[i].y);
	//for (int i=1;i<=n;i++)
	//	printf("%d %d\n",d[i].x,d[i].y);
	//printf("\n");
	mi[0]=1;
	for (int i=1;i<=n;i++)
		mi[i]=mi[i-1]*2%mod;
