		cnt[d[i].x]++;
	for (int i=1;i<=tot;i++)
		s1[i]=s1[i-1]+cnt[i];
	for (int i=tot;i>=1;i--)
		s2[i]=s2[i+1]+cnt[i];
	for (int i=1;i<=n;i++)
		ans[i]+=mi[s1[d[i].x-1]]+mi[s2[d[i].x+1]];
	memset(cnt,0,sizeof(cnt));
	for (int i=1;i<=n;i++)
		cnt[d[i].y]++;
	for (int i=1;i<=tot;i++)
		s1[i]=s1[i-1]+cnt[i];
	for (int i=tot;i>=1;i--)
		s2[i]=s2[i+1]+cnt[i];
	for (int i=1;i<=n;i++)
		ans[i]+=mi[s1[d[i].y-1]]+mi[s2[d[i].y+1]],
		ans[i]%=mod;
	sort(d+1,d+n+1,cmp);
	int tmp;
	for (int i=1;i<=n;i++) {
		tmp=query(d[i].y);
		ans[d[i].id]-=mi[tmp]+mi[i-1-tmp];
		add(d[i].y);
	}
	memset(tr,0,sizeof(tr));
	reverse(d+1,d+n+1);
	for (int i=1;i<=n;i++) {
		tmp=query(d[i].y);
		ans[d[i].id]-=mi[tmp]+mi[i-1-tmp];
		add(d[i].y);
	}
	for (int i=1;i<=n;i++) {
		ans[i]=(ans[i]%mod+mod)%mod;
		s+=mi[n]-ans[i]-1,s%=mod;
		//printf("%d %lld\n",i,ans[i]);
	}
	printf("%lld\n",s);
	return 0;
}

