        cur = u1 + u2 + (j-k);
        minun(ans,p2[cur]-1);
        ///completely below
        cur = d1 + d2 + (k-i);
        minun(ans,p2[cur]-1);
        ///completely left
        minun(ans,p2[i-1]-1);
        ///completely right
        minun(ans,p2[n-j]-1);
        ///shitty four corners
        ///left-up
        plusle (ans,p2[u2]-1);
        ///left down
        plusle(ans,p2[d2]-1);
