class Solver {
 public:
  int n;
  vector<int> x, y;
  BIT<int> l2r, r2l;
  Solver(LL n) : n(n), x(n), y(n), l2r(n), r2l(n){};

  void solve() {
    for (int i = 0; i < n; ++i) {
      cin >> x[i] >> y[i];
    }
    vector<int> X(x), Y(y);
    sort(X.begin(), X.end());
    X.erase(unique(X.begin(), X.end()), X.end());
    sort(Y.begin(), Y.end());
    Y.erase(unique(Y.begin(), Y.end()), Y.end());
    for (int i = 0; i < n; ++i) {
      x[i] = distance(X.begin(), lower_bound(X.begin(), X.end(), x[i]));
      y[i] = distance(Y.begin(), lower_bound(Y.begin(), Y.end(), y[i]));
    }
    vector<int> ix(n), iy(n);
    for (int i = 0; i < n; ++i) {
      ix[x[i]] = i;
      iy[y[i]] = i;
    }
    vector<int> lu(n), ld(n), ru(n), rd(n);
    for (int i = 0; i < n; ++i) {
      int id = ix[i];
      int yfromid = y[id];
      ld[id] = l2r.sum(yfromid);
      lu[id] = i - ld[id];
      l2r.add(yfromid, 1);
    }
    for (int i = 0; i < n; ++i) {
      int id = ix[n - 1 - i];
      int yfromid = y[id];
      rd[id] = r2l.sum(yfromid);
      ru[id] = i - rd[id];
      r2l.add(yfromid, 1);
    }
    Modint<> ans(0);
    for (int i = 0; i < n; ++i) {
      int l = x[i];
      int r = n - 1 - l;
      int d = y[i];
      int u = n - 1 - d;
      auto two = Modint<>(2);
      Modint<> tmp = two.mpow(n) - 1;
      tmp -= two.mpow(l) + two.mpow(r) + two.mpow(d) + two.mpow(u);
      tmp += two.mpow(ld[i]) + two.mpow(lu[i]) + two.mpow(rd[i]) + two.mpow(ru[i]);
      ans += tmp;
    }
    cout << ans << endl;
  }
};

