const ll MOD = 998244353;
const ll INF = 1LL << 60;

ll mod_pow(ll a, ll n) {
	if (n == 0) return 1;
	if (n % 2 == 0) {
		ll tmp = mod_pow(a, n / 2);
		return (tmp * tmp) % MOD;
	}
	return (a * mod_pow(a, n - 1)) % MOD;
}

struct BIT {
	vector<ll> bit;
	int size;

	BIT(int n) :size(n) {
		bit.resize(size + 1);
		fill(bit.begin(), bit.end(), 0);
	}

	ll sum(int i) {
		i++;
		ll s = 0;
		while (i > 0) {
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}

	void add(int i, ll x) {
		i++;
		while (i <= size) {
			bit[i] += x;
			i += i & -i;
		}
	}
};

int main() {
	int N;
	cin >> N;

	vector<P> ps;
	vector<int> vx, vy;
	for (int i = 0; i < N; i++) {
		int x, y;
		cin >> x >> y;
		ps.emplace_back(x, y);
		vx.push_back(x);
		vy.push_back(y);
	}
	sort(ps.begin(), ps.end());
	sort(vx.begin(), vx.end());
	sort(vy.begin(), vy.end());
	for (int i = 0; i < N; i++) {
		ps[i].first = lower_bound(vx.begin(), vx.end(), ps[i].first) - vx.begin();
		ps[i].second = lower_bound(vy.begin(), vy.end(), ps[i].second) - vy.begin();
	}
	BIT bit(N);
	ll ans = 0;
	for (int i = 0; i < N; i++) {
		ll sum = (mod_pow(2, ps[i].first) + MOD - 1) % MOD;
		(sum += (mod_pow(2, N - ps[i].first - 1) + MOD - 1) % MOD) %= MOD;
		(sum += (mod_pow(2, ps[i].second) + MOD - 1) % MOD) %= MOD;
		(sum += (mod_pow(2, N - ps[i].second - 1) + MOD - 1) % MOD) %= MOD;
		int a = bit.sum(ps[i].second);
		int b = ps[i].second - a;
		int c = ps[i].first - a;
		int d = N - 1 - a - b - c;
		(sum += MOD - (mod_pow(2, a) + MOD - 1) % MOD) %= MOD;
		(sum += MOD - (mod_pow(2, b) + MOD - 1) % MOD) %= MOD;
		(sum += MOD - (mod_pow(2, c) + MOD - 1) % MOD) %= MOD;
		(sum += MOD - (mod_pow(2, d) + MOD - 1) % MOD) %= MOD;
		ll x = (mod_pow(2, N) + MOD - 1) % MOD;
		(x += MOD - sum) %= MOD;
		(ans += x) %= MOD;
		bit.add(ps[i].second, 1);
	}
	cout << ans << endl;
}

