void upd(int i, int l=0, int r=n-1, int id=1)
{
	if(l == r)
	{
		seg[id] = 1;
		return ;
	}
	int mid = (l+r)>>1;
	if(i <= mid) upd(i, l, mid, id*2);
	else upd(i, mid+1, r, id*2+1);
	seg[id] = seg[id*2]+seg[id*2+1];
}
int query(int x, int y, int l=0, int r=n-1, int id=1)
{
	if(l >= x && r <= y) return seg[id];
	if(l > y || r < x) return 0;
	int mid = (l+r)>>1;
	return query(x, y, l, mid, id*2) + query(x, y, mid+1, r, id*2+1);
}
