			i.second = t++;
		}
		t = 0;
		for(auto &i : vy) {
			i.second = t++;
		}
	}
	for(auto &pt : pts) {
		pt.first = vx[pt.first];
		pt.second = vy[pt.second];
	}
	std::sort(pts.begin(), pts.end());
	{
		// go
		FenwickTree<int> tree;
		tree.init(n + 2);
		for(int i = 0; i < n; i++) {
			int x = pts[i].first, y = pts[i].second;
			freq[i][0] = tree.qry(y);
			freq[i][1] = tree.qry(n + 2) - freq[i][0];
			tree.upd(y + 1, 1);
		}
	}
	{
		// back
		FenwickTree<int> tree;
		tree.init(n + 2);
		for(int i = n-1; i >= 0; i--) {
			int x = pts[i].first, y = pts[i].second;
			freq[i][2] = tree.qry(y);
			freq[i][3] = tree.qry(n + 2) - freq[i][2];
			freq[i][4] = 1;
			tree.upd(y + 1, 1);
		}
	}
	int ans = 0;
	std::vector<int> two(n + 1, 1);
	for(int i = 1; i <= n; i++) {
		two[i] = two[i-1] * 2 % MOD;
	}
	for(int i = 0; i < n; i++) {
		// answer with itself
		ans = (ans + two[n-1]) % MOD;
		// answer without itself with 4 corners
		long long cur = 1;
		for(int j = 0; j < 4; j++) cur = cur * (two[freq[i][j]] - 1) % MOD;
		ans = (ans + (int) cur) % MOD;
		// answer with 3 corners
		for(int k = 0; k < 4; k++) {
			cur = 1;
			for(int j = 0; j < 4; j++) {
				if(j != k) {
					cur = cur * (two[freq[i][j]] - 1) % MOD;
				}
			}
			ans = (ans + (int) cur) % MOD;
		}
		// answer with 2 corners
		for(int k = 0; k < 2; k++) {
			int j = k;
			cur = 1;
			cur = cur * (two[freq[i][j]] - 1) % MOD;
			j ^= 3;
			cur = cur * (two[freq[i][j]] - 1) % MOD;
			ans = (ans + (int) cur) % MOD;
		}
	}
	std::cout << ans << '\n';
}

