  ft(int n) : s(n) {}
  void resize(int n) {
    s.clear();
    s.resize(n);
  }
  void update(int pos, int dif) { // a[pos] += dif
    for (; pos < (int)s.size(); pos |= pos + 1) s[pos] += dif;
