void add(int x)
{
  for (int i = x; i <= n; i += i & -i)
    tree[i]++;
}

int get(int x)
{
  int res = 0;
  for (int i = x; i; i -= i & -i)
    res += tree[i];
  return res;
}

void compress()
{
  map<int, int> x, y;
  for (int i = 0; i < n; i++)
  {
    x[a[i].first] = 0;
    y[a[i].second] = 0;
  }

  int id = 0;
  for (auto u : x)
    x[u.first] = ++id;
  id = 0;
  for (auto u : y)
    y[u.first] = ++id;

  for (int i = 0; i < n; i++)
    a[i] = {x[a[i].first], y[a[i].second]};
}

int main()
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  cin >> n;
  for (int i = 0; i < n; i++)
    cin >> a[i].first >> a[i].second;
  compress();
  sort(a, a + n);

  int p2[200200] = {0};
  for (int i = 1; i <= n; i++)
    p2[i] = (p2[i - 1] * 2 + 1) % BASE;

  long long ans = 0;
  for (int i = 0; i < n; i++)
  {
    int x = a[i].first, y = a[i].second;
    ans = (ans + p2[n]) % BASE;
    ans = (ans - p2[x - 1] + BASE) % BASE;
    ans = (ans - p2[n - x] + BASE) % BASE;
    ans = (ans - p2[y - 1] + BASE) % BASE;
    ans = (ans - p2[n - y] + BASE) % BASE;
    ans = (ans + p2[get(y - 1)]) % BASE;
    ans = (ans + p2[i - get(y)]) % BASE;
    add(y);
  }

  for (int i = 0; i < n; i++)
    a[i].first = n - a[i].first;
  sort(a, a + n);
  memset(tree, 0, sizeof tree);
  for (int i = 0; i < n; i++)
  {
