int main() {

  int n; cin >> n;
  lint maxVal = -INF;
  set<lint> st;
  vector<pair<lint, lint>> vp(n);
  for (int i = 0; i < n; i++) {
    lint x, y; cin >> x >> y;
    st.insert(x);
    st.insert(y);
    vp[i] = {x, y};
  }

  map<lint, lint> zip;
  lint zipVal = 0;
  for (auto x : st) {
    zip[x] = zipVal;
    maxVal = max(maxVal, zipVal);
    zipVal++;
  }

  for (int i = 0; i < n; i++) {
    vp[i].first = zip[vp[i].first];
    vp[i].second = zip[vp[i].second];
  }

  sort(ALL(vp));

  using T = lint;  // type T
  using E = lint;  // type E
  auto f = [](T a, T b){ // return type T value
    return a + b;
  };
  auto g = [](T a, E b){ // return type T value
    return a + b;  // return b;
  };
  T ti = 0;  // identify element
  SegmentTree<T, E, decltype(f), decltype(g)> sgLeft(f, g, ti);  // don't change
  SegmentTree<T, E, decltype(f), decltype(g)> sgRight(f, g, ti);  // don't change
  sgLeft.build(vector<lint> (maxVal + 1, 0));   // 初期配列を代入
  sgRight.build(vector<lint> (maxVal + 1, 0));   // 初期配列を代入

  // 全ての点を足しこむ
  for (int i = 0; i < n; i++) {
    lint x, y;
    tie(x, y) = vp[i];
    sgRight.update(y, 1);
  }

  lint ans = 0;

  // x 座標が小さい順に処理
  for (int i = 0; i < n; i++) {
    lint x, y;
    tie(x, y) = vp[i];

    // 無条件に 2^{n - 1} を足しこむ
    ans += modpow(2, n - 1);
    ans %= MOD;

    // 点 (x, y) を含むような集合の個数を ans に足しこむ
    lint A = sgLeft.query(y + 1, maxVal + 1);
    lint B = sgLeft.query(0, y);
    lint C = sgRight.query(y + 1, maxVal + 1);
    lint D = sgRight.query(0, y);
    // cerr << A << " " << B << " " << C << " " << D << endl;

    ans += (modpow(2, A) - 1 + MOD) * (modpow(2, D) - 1 + MOD) % MOD * modpow(2, n - A - D - 1) % MOD;
    ans %= MOD;

    // cerr << "AD = " << (modpow(2, A) - 1 + MOD) * (modpow(2, D) - 1 + MOD) % MOD << endl;

    ans += (modpow(2, B) - 1 + MOD) * (modpow(2, C) - 1 + MOD) % MOD * modpow(2, n - B - C - 1) % MOD;
    ans %= MOD;

    // cerr << "BC = " << (modpow(2, B) - 1 + MOD) * (modpow(2, C) - 1 + MOD) % MOD << endl;

    lint sub = (modpow(2, A) - 1 + MOD) % MOD;
    sub *= (modpow(2, B) - 1 + MOD) % MOD;
    sub %= MOD;
    sub *= (modpow(2, C) - 1 + MOD) % MOD;
    sub %= MOD;
    sub *= (modpow(2, D) - 1 + MOD) % MOD;
    sub %= MOD;

    // cerr << "sub = " << sub << endl;
    // cerr << "ans = " << ans << endl;

    ans += (MOD - sub) % MOD;
    ans %= MOD;
    // cerr << "ans = " << ans << endl;

    // セグ木の更新処理
    sgLeft.update(y, 1);
    sgRight.update(y, -1);
  }

  cout << ans << endl;

  return 0;
}

