class binary_indexed_tree {
private:

	int m_size;
	vector<T>m_vec;

public:

	binary_indexed_tree(int size)
		:m_size(size)
	{
		m_vec.resize(m_size);
	}

	void add(int a, const T& w) { for (int x = a; x <= m_size; x += (x & -x)) m_vec[x] += w; }

	T sum(int a) const {
		T res{};
		for (int x = a; x > 0; x -= (x & -x)) res += m_vec[x];
		return res;
	}

};

