struct Fp {
  int64_t x;
  Fp() : x(0) {}
  Fp(int y) : x(y >= 0 ? y % MOD : (MOD - (-y) % MOD) % MOD) {}

  Fp &operator+=(const Fp &p) {
    x = (x + p.x) % MOD;
    return *this;
  }
  Fp &operator-=(const Fp &p) {
    x = (x + MOD - p.x) % MOD;
    return *this;
  }
  Fp &operator*=(const Fp &p) {
    x = x * p.x % MOD;
    return *this;
  }
  Fp operator-() const { return Fp(-x); }
  Fp operator+(const Fp &rhs) const { return Fp(*this) += rhs; }
  Fp operator-(const Fp &rhs) const { return Fp(*this) -= rhs; }
  Fp operator*(const Fp &rhs) const { return Fp(*this) *= rhs; }
  Fp operator+(const int y) const { return Fp(*this) += Fp(y); }
  Fp operator-(const int y) const { return Fp(*this) -= Fp(y); }
  Fp operator*(const int y) const { return Fp(*this) *= Fp(y); }
};

Fp modpow(int a, int k) {
  // a ** k 
  if (k == 0) return Fp(1);
  if (k % 2 == 1) {
    Fp half = modpow(a, k / 2);
    return half * half * a;
  }else {
    Fp half = modpow(a, k / 2);
    return half * half;
  }
}

