        auto yc = y;
        std::sort(yc.begin(), yc.end());
        yc.erase(std::unique(yc.begin(), yc.end()), yc.end());
        for (int i = 0; i < yc.size(); i++) { zip[yc[i]] = i; }
    }
    for (int i = 0; i < n; i++) { y[i] = zip[y[i]]; }
    std::vector<int> inds(n);
    std::iota(inds.begin(), inds.end(), 0);
    std::sort(inds.begin(), inds.end(), [&](int i, int j) { return x[i] < x[j]; });
    {
        auto xc = x, yc = y;
        for (int i = 0; i < n; i++) { x[i] = xc[inds[i]], y[i] = yc[inds[i]]; }
    }
    wavelet_matrix<17> wm(y.begin(), y.end());
    mint ans = 0;
    for (int i = 0; i < n; i++) {
        const int left       = i;
        const int right      = n - i - 1;
        const int lower      = y[i];
        const int upper      = n - y[i] - 1;
        const int leftlower  = wm.range_freq(0, i, 0, y[i]);
        const int leftupper  = wm.range_freq(0, i, y[i], n);
        const int rightlower = wm.range_freq(i + 1, n, 0, y[i]);
        const int rightupper = wm.range_freq(i + 1, n, y[i], n);
        assert(leftlower + leftupper + rightlower + rightupper == n - 1);
        mint sum = pow[n] - 1;
        sum -= (pow[left] + pow[right] + pow[lower] + pow[upper]);
        sum += (pow[leftlower] + pow[rightlower] + pow[rightupper] + pow[leftupper]);
        SHOW(i, sum);
        ans += sum;
    }
    std::cout << ans << std::endl;
    return 0;
}

