class BIT{
private:
    //[1,n]
    vector<int> bit;
    int n;

public:
    BIT(){}
    BIT(int size){
        n = size;
        bit = vector<int>(n+1,0);
    }
    //[0,i)のsum（内部実装は[1,i]）
    int sum(int i){
        int s = 0;
        while(i > 0){
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }

    void add(int i, int x){
        while(i <= n){
            bit[i] += x;
            i += i & -i;
        }
    }
    void show(){
        for(int i = 1; i <= n; i++){
            cout << " " << bit[i];
        }
        cout << endl;
    }
};

int beki[200005];

int g(int a, int b, int c, int d){
    int ret = 1;
    ret *= a;
    ret %= MOD;
    ret *= b;
    ret %= MOD;
    ret *= c;
    ret %= MOD;
    ret *= d;
    ret %= MOD;
    return ret;
}

int f(int a, int b, int c, int d){
    vi num(4);
    num[0] = a;
    num[1] = b;
    num[2] = c;
    num[3] = d;
    vi o(4),ox(4);
    rep(i,4){
        ox[i] = beki[num[i]];
        o[i] = (ox[i] - 1 + MOD) % MOD;
    }
    int ret = 0;
    ret += g(ox[0],o[1],o[2],ox[3]);
    ret %= MOD;
    ret += g(o[0],ox[1],ox[2],o[3]);
    ret %= MOD;
    ret -= g(o[0],o[1],o[2],o[3]);
    ret %= MOD;
    ret += g(ox[0],ox[1],ox[2],ox[3]);
    ret %= MOD;
    return ret;
}

