}

mint perm(mint n, mint k){
    return fac[n.x]/fac[n.x-k.x];
}

template<typename T> struct Binary_Indexed_Tree{
    vector<T> bit;
    //要素数N(0-indexed)のBITを構築
    Binary_Indexed_Tree(int N){
        bit.assign(N+1, 0);
    }
    //i番目の要素にx加える
    void add(int i, T x){
        for(i++; i < bit.size(); i += (i & -i)) bit[i] += x;
    }
    //sum(i)で[0,i)の和を取得
    T sum(int i){
        T res = 0;
        for(i = i; i > 0; i -= (i & -i)) res += bit[i];
        return res;
    }
    //query(l,r)で[l,r)の和を取得
    T query(int l, int r){
        return sum(r) - sum(l);
    }
    //初期化する
    void clear(){
        fill(bit.begin(), bit.end(), 0);
    }
};

