        ans += pw2[N - 1] - 1;
        ans -= pw2[X[i]] + pw2[Y[i]] + pw2[N - X[i] - 1] + pw2[N - Y[i] - 1];
        int pa = 0;
        for(int j = Y[i]; j > 0; j -= j & -j) {
            pa += bit[j];
        }
        for(int j = Y[i] + 1; j <= N; j += j & -j)
            bit[j]++;
        int pb = X[i] - pa;
        int pc = Y[i] - pa;
        int pd = N - 1 - pa - pb - pc;
        ans += pw2[pa] + pw2[pb] + pw2[pc] + pw2[pd];
    }
    cout << ans << endl;

    return 0;
}

