const int INF = 0;
// class
class SegmentTree2D {
public:
  SegmentTree2D(int x, int y);
  void update(int x, int y, int value);
  int query(int min_x, int min_y, int max_x, int max_y) const;
private:
  inline int merge(int l, int r) const;
  int update(int low_x, int low_y, int high_x, int high_y, int index, int x, int y, int value, int depth);
  int query(int low_x, int low_y, int high_x, int high_y, int index, int min_x, int min_y, int max_x, int max_y, int depth) const;
  int size_x_, size_y_;
  std::vector<int> node_;
};
// method
SegmentTree2D::SegmentTree2D(int x, int y) : size_x_(x), size_y_(y) {
  while(x & x - 1) x += x & -x;
  while(y & y - 1) y += y & -y;
  node_.assign(x * y << 2, INF);
}
inline int SegmentTree2D::merge(int l, int r) const {return l + r;}
// O(log(x) * log(y))
void SegmentTree2D::update(int x, int y, int value) {
  update(0, 0, size_x_ - 1, size_y_ - 1, 0, x, y, value, 0);
}
int SegmentTree2D::update(int low_x, int low_y, int high_x, int high_y, int index, int x, int y, int value, int depth) {
  if(x < low_x || high_x < x || y < low_y || high_y < y) return node_[index];
  if(low_x == high_x && low_y == high_y) return node_[index] = value;
  int middle_x = (low_x + high_x) >> 1;
  int middle_y = (low_y + high_y) >> 1;
  // x軸方向に割れないとき
  if(low_x == high_x) {
    int l = update(low_x, low_y, high_x, middle_y, (index << 1) + 1, x, y, value, depth ^ 1);
    int h = update(low_x, middle_y + 1, high_x, high_y, (index << 1) + 2, x, y, value, depth ^ 1);
    return node_[index] = merge(l, h);
  }
  // y軸方向に割れないとき
  if(low_y == high_y) {
    int l = update(low_x, low_y, middle_x, high_y, (index << 1) + 1, x, y, value, depth ^ 1);
    int h = update(middle_x + 1, low_y, high_x, high_y, (index << 1) + 2, x, y, value, depth ^ 1);
    return node_[index] = merge(l, h);
  }
  // 前回y軸方向に割ったとき
  if(depth) {
    int l = update(low_x, low_y, high_x, middle_y, (index << 1) + 1, x, y, value, depth ^ 1);
    int h = update(low_x, middle_y + 1, high_x, high_y, (index << 1) + 2, x, y, value, depth ^ 1);
    return node_[index] = merge(l, h);
  // 前回x軸方向に割ったとき
  } else {
    int l = update(low_x, low_y, middle_x, high_y, (index << 1) + 1, x, y, value, depth ^ 1);
    int h = update(middle_x + 1, low_y, high_x, high_y, (index << 1) + 2, x, y, value, depth ^ 1);
    return node_[index] = merge(l, h);
  }
}
// O(log(max_x - min_x) * log(min_y - max_y) * log(max_x - min_x) * log(min_y - max_y))
int SegmentTree2D::query(int min_x, int min_y, int max_x, int max_y) const {
  return query(0, 0, size_x_ - 1, size_y_ - 1, 0, min_x, min_y, max_x, max_y, 0);
}
int SegmentTree2D::query(int low_x, int low_y, int high_x, int high_y, int index, int min_x, int min_y, int max_x, int max_y, int depth) const {
  if(max_x < low_x || high_x < min_x || max_y < low_y || high_y < min_y) return INF;
  if(min_x <= low_x && high_x <= max_x && min_y <= low_y && high_y <= max_y) return node_[index];
  int middle_x = (low_x + high_x) >> 1;
  int middle_y = (low_y + high_y) >> 1;
  if(low_x == high_x) {
    int l = query(low_x, low_y, high_x, middle_y, (index << 1) + 1, min_x, min_y, max_x, max_y, depth ^ 1);
    int h = query(low_x, middle_y + 1, high_x, high_y, (index << 1) + 2, min_x, min_y, max_x, max_y, depth ^ 1);
    return merge(l, h);
  }
  if(low_y == high_y) {
    int l = query(low_x, low_y, middle_x, high_y, (index << 1) + 1, min_x, min_y, max_x, max_y, depth ^ 1);
    int h = query(middle_x + 1, low_y, high_x, high_y, (index << 1) + 2, min_x, min_y, max_x, max_y, depth ^ 1);
    return merge(l, h);
  }
  if(depth) {
    int l = query(low_x, low_y, high_x, middle_y, (index << 1) + 1, min_x, min_y, max_x, max_y, depth ^ 1);
    int h = query(low_x, middle_y + 1, high_x, high_y, (index << 1) + 2, min_x, min_y, max_x, max_y, depth ^ 1);
    return merge(l, h);
  } else {
    int l = query(low_x, low_y, middle_x, high_y, (index << 1) + 1, min_x, min_y, max_x, max_y, depth ^ 1);
    int h = query(middle_x + 1, low_y, high_x, high_y, (index << 1) + 2, min_x, min_y, max_x, max_y, depth ^ 1);
    return merge(l, h);
  }
}

