		p[i].FI = p[i].SE;
		p[i].SE = i;
	}
	sort(ALL(p));

	SegmentTree<int> st(n, OP(A + B), 0);

	MI ans = n * (MI(2) ^ n);
	inc(i, n) {
		int j = p[i].SE;
		int v = st.fold_ID(0, j);
		st.apply(j, AP(A++));

		MI a = MI(2) ^ (v);
		MI b = MI(2) ^ (i - v);
		MI c = MI(2) ^ (j - v);
		MI d = MI(2) ^ (n - 1 - (i + j - v));

		ans -= (a + d - 1) * (b + c - 1);
	}

	cout << ans << endl;

	return 0;
}

