    for (ll j = 0; j < 4; ++j) {
      sum = (sum * pattern.at(j)) % mod;
    }
    temp -= sum;
    if (temp < 0) {
      temp += mod;
    }
    ans += temp;
    // cout << ans << "\n";
  }
  cout << ans << "\n";
