ll pow(ll n, ll k) {
    ll res = 1;
    while (k) {
        if (k&1) res = res*n%MOD;
        n = n*n%MOD;
        k >>= 1;
    }
    return res;
}

ll calc(int n) {
    ll count = 4ll * MOD + pow(2, N) - 1;
    REP (i,4) {
        count -= pow(2, (quad[n][i] + quad[n][(i+1)%4])) - 1;
        count += pow(2, quad[n][i]) - 1;
    }
    return count % MOD;
}

ll solve() {
    REP (i, N) {
        xs.PB(MP(X[i], i));
        ys.PB(MP(Y[i], i));
    }
    sort(ALL(xs)); sort(ALL(ys));
    REP (i, N) {
        X[xs[i].second] = i+1;
        Y[ys[i].second] = i+1;
    }
    REP (i, N) xy.PB(MP(X[i], Y[i]));
    sort(ALL(xy));

    BIT bitL(MAX), bitR(MAX);
    REP (i, N) {
        quad[i][0] = bitL.sum(xy[i].second);
        quad[i][1] = i - quad[i][0];
        bitL.add(xy[i].second, 1);

        quad[N-i-1][2] = bitR.sum(MAX-xy[N-i-1].second);
        quad[N-i-1][3] = i - quad[N-i-1][2];
        bitR.add(MAX-xy[N-i-1].second, 1);
    }
    REP (i, N) {
        ll s = 0;
        REP (j, 4) s += quad[i][j];
        assert(s == N-1);
    }

    ll ans = 0;
    REP (i, N) ans = (ans + calc(i)) % MOD;
    return ans;
}

