int N, X[200002], Y[200002];

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N;
	map<int, int> mpx, mpy;
	rep(i, N) {
		cin >> X[i] >> Y[i];
		mpx[X[i]] = 1; mpy[Y[i]] = 1;
	}
	int cnt = 1;
	for (auto a : mpx) {
		mpx[a.first] = cnt++;
	}
	cnt = 1;
	for (auto a : mpy) {
		mpy[a.first] = cnt++;
	}
	vector<pii> coordinates(N);
	rep(i, N) {
		coordinates[i] = { mpx[X[i]],mpy[Y[i]] };
	}
	SORT(coordinates);

	ll mod = 998244353;
	ll ans = 0;

	BIT bit1(N), bit2(N);
	rep(i, N)bit2.add(i + 1, 1);
	int count = 0;
	for (auto a : coordinates) {

		int y = a.second;

		ll b = bit1.sum(y - 1);
		ll c = count - b;
		ll d = bit2.sum(y - 1);
		ll e = N - count-1 - d;

		ans += mod_pow(2, N - 1, mod);
		ans %= mod;
		ans += ((((mod + mod_pow(2, b, mod) - 1) % mod)*((mod + mod_pow(2, e, mod) - 1) % mod))%mod*mod_pow(2, c, mod)) % mod*mod_pow(2, d, mod) % mod;
		ans += (((mod + mod_pow(2, c, mod) - 1) % mod)*((mod + mod_pow(2, d, mod) - 1) % mod))%mod*mod_pow(2, b, mod) % mod*mod_pow(2, e, mod) % mod;
		ans += mod;
		ans -= ((((mod + mod_pow(2, b, mod) - 1) % mod)*((mod + mod_pow(2, c, mod) - 1) % mod))%mod*((mod + mod_pow(2, d, mod) - 1) % mod))%mod*((mod + mod_pow(2, e, mod) - 1) % mod);
		bit1.add(y, 1);
		bit2.add(y, -1);
		count++;
		ans %= mod;
	}
	P(ans%mod);
	return 0;


}

