struct BIT {
  vector<vector<ll> > array;
  int n, m;
  BIT(int _n, int _m)
  : array(_n + 1, vector<ll>(_m + 1)), n(_n), m(_m) {}
  // [1, 1]から[x, y]までの累積和
  ll sum(int x, int y) {
    ll s = 0;
    for (int i = x; i > 0; i -= i & -i) {
      for (int j = y; j > 0; j -= j & -j) {
        s += array[i][j];
      }
    }
    return s;
  }
  ll sum(int x1, int y1, int x2, int y2) {
    return sum(x2, y2) - sum(x1 - 1, y2) - sum(x2, y1 - 1) + sum(x1 - 1, y1 - 1);
  }
  void add(int x, int y, ll k) {
    for (int i = x; i <= n; i += i & -i) {
      for (int j = y; j <= m; j += j & -j) {
        array[i][j] += k;
      }
    }
  }
  void out() {
    rep(i, n + 1) { rep(j, m + 1) cout << array[i][j] << " "; cout << endl; }
  }
};
// BIT で mod とってたら遅い

void solve() {
  int n;
  cin >> n;
  vector<int> x(n), y(n);
  rep(i, n) cin >> x[i] >> y[i];
  vector<int> x2 = x, y2 = y;
  sort(all(x2));
  sort(all(y2));

  BIT bit(n, n);
  rep(i, n) {
    int it = lb(x2, x[i]);
    int it2 = lb(y2, y[i]);
    bit.add(it + 1, it2 + 1, 1);
  }
  ll ans = 0;
  rep(i, n) {
    vector<int> v(4);
    int it = lb(x2, x[i]), it2 = lb(y2, y[i]);
    v[0] = it;
    v[1] = it2;
    rep(j, 2) v[2 + j] = n - 1 - v[j];
    // cout << v << endl;
    ll tmp = 0;
    rep(j, 4) (tmp += modpow(2, v[j], mod)) %= mod;

    v = vector<int>(4, 0);
    v[0] = bit.sum(it, it2);
    v[1] = it - v[0];
    v[2] = it2 - v[0];
    v[3] = bit.sum(n, n) - bit.sum(n, it2 + 1) - bit.sum(it + 1, n) + bit.sum(it + 1, it2 + 1);
    // cout << v << endl;
    rep(j, 4) (tmp += mod - modpow(2, v[j], mod)) %= mod;
    (ans += modpow(2, n, mod) - 1 - tmp) %= mod;
    // cout << ans << endl;
  }
  cout << ans << endl;
}

