template <class T>
struct compressor {
  vector<T> xs;
  void put(const T &x) {
    xs.push_back(x);
  }
  void compress() {
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
  }
  int get(const T &x) const {
    return distance(xs.begin(), lower_bound(xs.begin(), xs.end(), x));
  }
  int size() const {
    return xs.size();
  }
};

template <class T>
struct fenwick_tree {
  vector<T> x;
  fenwick_tree(int n)
      : x(n + 1) {
  }
  void add(int k, T a) {
    for (++k; k < x.size(); k += k & -k) x[k] += a;
  }
  T sum(int k) {
    T s = 0;
    for (; k > 0; k &= k - 1) s += x[k];
    return s;
  }
  int lower_bound(T a) {
    if (a <= 0) return 0;
    int k = x.size() - 1;
    for (int s : {1, 2, 4, 8, 16}) k |= (k >> s);
    for (int p = ++k; p > 0; p >>= 1, k |= p)
      if (k < x.size() && x[k] < a)
        a -= x[k];
      else
        k ^= p;
    return k + 1;
  }
};

mint solve(vector<point_t> &points) {
  sort(points.begin(), points.end());
  compressor<int> zip;
  for (auto &p : points) zip.put(p.y);
  zip.compress();
  fenwick_tree<int> bit(zip.size());
  mint res = 0;
  for (auto &p : points) {
    int y = zip.get(p.y);
    int c = bit.sum(y);
    res += mint(2) ^ c;
    bit.add(y, 1);
  }
  return res;
}

int main() {
#ifdef DEBUG
