#endif
  int N;
  while (cin >> N) {
    vector<point_t> points(N);
    for (auto &p : points) cin >> p.x >> p.y;
    auto rot90 = [](auto &points) {
      for (auto &p : points) {
        int nx = -p.y;
        int ny = p.x;
        p.x = nx;
        p.y = ny;
      }
    };
    mint pw = mint(2) ^ N;
    mint res = (pw - 1) * (mint(N) - 4);
    for (int t = 0; t < 4; t++) {
      res += solve(points);
      rot90(points);
    }
    cout << res.value() << endl;
  }
  return 0;
}

