               // bit[x][y] += w;
               log[ipair(x, y)] += w;
            }
         }
      }
      // [1, a] x [1, b]
      T sum(int a, int b) {
         T ret = 0;
         for (int x = a; x > 0; x -= x & -x) {
            for (int y = b; y > 0; y -= y & -y) {
               // ret += bit[x][y];
               ret += log[ipair(x, y)];
            }
         }
         return ret;
      }

