      T sum2(int a1, int a2, int b1, int b2) {
         T ret = 0;
         ret += sum(a2, b2);
         ret -= sum(a2, b1 - 1);
         ret -= sum(a1 - 1, b2);
         ret += sum(a1 - 1, b1 - 1);
         return ret;
      }
