ll f(ll a, ll b, ll c, ll d, vl& pow2) {
  ll res = 0;
  vl num = {a, b, c, d};
  vl o(4), ox(4);
  rep(i, 4) {
    ox[i] = pow2[num[i]];
    o[i] = ox[i] - 1;
  }
  res = (res + ox[0] * o[1] * o[2] * ox[3]) % MOD;
  res = (res + o[0] * ox[1] * ox[2] * o[3]) % MOD;
  res = (res + MOD - o[0] * o[1] * o[2] * o[3]) % MOD;
  res = (res + ox[0] * ox[1] * ox[2] * ox[3]) % MOD;
  return res;
}

class SegTree {
 private:
  const ll def_val_ = 0;
  vl val_;
  ll n_;

  ll comp(ll l, ll r) { return l + r; }

  ll getr(ll x, ll y, ll k, ll l, ll r) {
    if (y <= l || r <= x) return def_val_;
    if (x <= l && r <= y) return val_[k];
    auto vl = getr(x, y, 2 * k + 1, l, (l + r) / 2);
    auto vr = getr(x, y, 2 * k + 2, (l + r) / 2, r);
    return comp(vl, vr);
  }

 public:
  SegTree(ll size) {
    n_ = 1;
    while (n_ < size) n_ *= 2;
    val_ = vl(2 * n_, def_val_);
  }

  void update(ll i, ll v) {
    i += (n_ - 1);
    val_[i] = v;
    while (i > 0) {
      i = (i - 1) / 2;
      val_[i] = comp(val_[2 * i + 1], val_[2 * i + 2]);
    }
  }

  // get XXX value between [x,y)
  ll getRange(ll x, ll y) { return getr(x, y, 0, 0, n_); }
};

ll cnt(ll x, vl& pow2) {
  if (x == 0)
    return 1;
  else
    return pow2[x] - 1;
}

