// Mod int
// cf. https://www.youtube.com/watch?v=1Z6ofKN03_Y
struct mint {
  ll x;
  mint(ll x = 0) : x((x + MOD) % MOD) {}
  mint& operator+= (const mint a) {
    if ((x += a.x) >= MOD) x %= MOD;
    return *this;
  }
  mint operator+ (const mint a) const {
    mint res(*this);
    return res += a;
  }
  mint& operator-= (const mint a) {
    if ((x += MOD - a.x) >= MOD) x %= MOD;
    return *this;
  }
  mint operator- (const mint a) const {
    mint res(*this);
    return res -= a;
  }
  mint& operator*= (const mint a) {
    (x *= a.x) %= MOD;
    return *this;
  }
  mint operator* (const mint a) const {
    mint res(*this);
    return res *= a;
  }
  mint pow(ll t) const {
    if (!t) { return 1; }
    mint a = pow(t >> 1);
    a *= a;
    if (t & 1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(MOD-2);
  }
  mint& operator/= (const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/ (const mint a) const {
    mint res(*this);
    return res /= a;
  }
};

template<typename T>
struct BIT {
  int n;
  vector<T> d;

  BIT(int n) : n(n), d(n+1) {}
  void add(int i, T x) {
    for (i++; i <= n; i += i & -i) {
      d[i] += x;
    }
  }
  T sum(int i) {
    T x = 0;
    for (i++; i; i -= i & -i) {
      x += d[i];
    }
    return x;
  }
};

// target point is not included
// + o|x + x|o - o|o
//   x|o   o|x   o|o
// target point is included
// + x|x
//   x|x
mint f(int a, int b, int c, int d) {
  mint a2 = mint(2).pow(a);
  mint b2 = mint(2).pow(b);
  mint c2 = mint(2).pow(c);
  mint d2 = mint(2).pow(d);
  mint res = 0;
  res += a2 * (b2-1) * (c2-1) * d2;
  res += (a2-1) * b2 * c2 * (d2-1);
  res -= (a2-1) * (b2-1) * (c2-1) * (d2-1);
  res += a2 * b2 * c2 * d2;
  return res;
}

int main(int argc, char** argv) {
