  // Compress x
  {
    map<int, int> mp;
    rep(i, N) { mp[p[i].first] = 0; }
    int j = 1;
    for (auto && x : mp) { x.second = j++; }
    rep(i, N) { p[i].first = mp[p[i].first]; }
  }
  // Compress y
  {
    map<int, int> mp;
    rep(i, N) { mp[p[i].second] = 0; }
    int j = 1;
    for (auto && x : mp) { x.second = j++; }
    rep(i, N) { p[i].second = mp[p[i].second]; }
  }

  sort(all(p)); // sorted by increasing order of x
  vector<int> a(N); // left lower
  vector<int> b(N); // left upper
  vector<int> c(N); // right lower
  vector<int> d(N); // right upper

  // from left to right
  {
    BIT<ll> bit(N);
    rep(i, N) {
      a[i] = bit.sum(p[i].second);
      b[i] = i - a[i];
      bit.add(p[i].second, 1);
