  // from right to left
  reverse(all(p)); // sorted by decreasing order of x
  {
    BIT<ll> bit(N);
    rep(i, N) {
      c[i] = bit.sum(p[i].second);
      d[i] = i - c[i];
      bit.add(p[i].second, 1);
    }
  }
  reverse(all(c));
  reverse(all(d));

  mint ans = 0;
  rep(i, N) {
    ans += f(a[i], b[i], c[i], d[i]);
  }
  cout << ans.x << endl;
}

