typedef pair<long,long> pll;

class SegmentTree{
private:
	vector<long> a;
	int n, m, h;
public:
	SegmentTree(int _n): n(_n){
		m = 1; h = 1;
		while (m < n){
			m <<= 1;
			h++;
		}
		a.resize(2*m+1, 0);
	}
	void update(int idx){
		int i = m + idx - 1;
		for (int i=m+idx-1; i > 0; i=(i-1)/2){
			a[i]++;
		}
		a[0]++;
	}
	// [p,q)
	long get(int p, int q){
		return query(p, q, 0, 0, m);
	}
	long query(int p, int q, int k, int l, int r){
		if (r <= p || q <= l) return 0;
		if (p <= l && r <= q) return a[k];
		else{
			int vl = query(p, q, k*2+1, l, (l+r)/2);
			int vr = query(p, q, k*2+2, (l+r)/2, r);
			return vl+vr;
		}
	}
	void print(){
		for (int i = 0, j = 0; i < h; ++i){
			for (int k = 0; k < (1 << i); k++, j++){
				printf("%d ", a[j]);
			}
			printf("\n");
		}
	}
	void clear(){
		fill(a.begin(), a.end(), 0);
	}
};

long pow2(int n){
	if (n == 0) return 1;
	else if (n % 2 == 1) return (pow2(n-1)*2)%MOD;
	else{
		long t = pow2(n/2);
		return (t*t)%MOD;
	}
}

