		lr[i] = tree.get(0, y);
		tree.update(y);
	}

	ans = (pow2(n-1) * n) % MOD;
	for (int i = 0; i < n; ++i){
		long bur = pow2(ur[i]);
		long bul = pow2(ul[i]);
		long blr = pow2(lr[i]);
		long bll = pow2(ll[i]);
		tmp = ((((((bur - 1)*(bll - 1)) % MOD)*bul) % MOD)*blr) % MOD;
		ans = (ans + tmp) % MOD;
		tmp = ((((((bul - 1)*(blr - 1)) % MOD)*bur) % MOD)*bll) % MOD;
		ans = (ans + tmp) % MOD;
		tmp = ((((((bur - 1)*(bll - 1)) % MOD)*(bul - 1)) % MOD)*(blr - 1)) % MOD;
		ans = (ans + (MOD - tmp)) % MOD;
	}
	cout << ans;
}

