int pw[N];

void init() {
	pw[0] = 1;
	for (int i = 1; i < N; i++) {
		pw[i] = mul(pw[i - 1], 2);
	}
}

int cnt_bad(vector<int> p) {
	int ans = 0;
	for (auto t : p) {
		ans = add(ans, pw[t] - 1);
	}
	for (int i = 0; i < 4; i++) {
		int c = pw[p[i] + p[(i + 1) % 4]];
		c = sub(c, pw[p[i]]);
		c = sub(c, pw[p[(i + 1) % 4]]);
		c = add(c, 1);
		ans = add(ans, c);
	}
	return ans;
}

struct Fenw {
	int n;
	vector<int> f;

	void add(int x, int c) {
		for (int i = x; i < n; i = i | (i + 1)) {
			f[i] += c;
		}
	}

	int sum(int x) {
		int ans = 0;
		for (int i = x; i >= 0; i = (i & (i + 1)) - 1) {
			ans += f[i];
		}
		return ans;
	}

	Fenw(int n_) {
		n = n_;
		f.resize(n);
	}
};

void zip(vector<int> &a) {
	vector<int> sn = a;
	sort(sn.begin(), sn.end());
	sn.resize(unique(sn.begin(), sn.end()) - sn.begin());
	for (auto &t : a) {
		t = lower_bound(sn.begin(), sn.end(), t) - sn.begin();
	}
}

