	for (auto t : ind) {
		rp.add(y[t], 1);
	}
	int ans = 0;
	for (int i = 0; i < n; i++) {
		if (i > 0) lp.add(y[ind[i - 1]], 1);
		rp.add(y[ind[i]], -1);
		vector<int> p(4);
