constexpr ulint maxInt = 998244353;

template<size_t num>
struct Pof2{
  ulint val[num];
  constexpr Pof2():val(){
    val[0] = 1;
    repr(i, 1, num){
      val[i] = (val[i-1]*2)%maxInt;
    }
  }
  constexpr int operator[](size_t i)const{
    return val[i];
  }
};

constexpr int maxN = 500;

constexpr auto pof2 = Pof2<maxN + 1>();

vector<point> p;

array<int, maxN> yMinNum;
array<int, maxN> yMaxNum;

ulint S(int i, int N){

  if( i == 0 || i == N-1){
    return pof2[N-1];
  }
  ulint pn, pN, pm, pM;
  pn = pof2[yMinNum[i]];
  pM = pof2[i-yMinNum[i]];
  pN = pof2[yMaxNum[i]];
  pm = pof2[(N-1-i)-yMaxNum[i]];
  int common = pof2[N-1]%maxInt;
  int without1 = ( (pn-1ULL)*( (pM*pm)%maxInt )%maxInt )*(pN-1ULL)%maxInt;
  int without2 = ((pM-1ULL)*(without1==0?pn*pN:(pn+pN-1) )%maxInt)*(pm-1ULL)%maxInt;

  return (common
       + without1
       + without2)%maxInt;
}

int main() {
