    yMaxNum[i] = count_if(p.begin()+i+1, p.end(), [&](auto e){return e.y > p[i].y;});
  }
  lint sumS = 0;
  rep(i,N){
    sumS = (sumS + S(i, N))%maxInt;
  }
  printline(sumS);
}

