#include <bits/stdc++.h>
using namespace std;
const int N = 2*(int)1e5+5, mod = 998244353;
pair<int,int> pts[N];
set<int> xc, yc;
unordered_map<int, int> xm, ym;
int n, sg[4*N];

void updt(int node, int l, int r, int x) {
	if(l > x || r < x) return;
	if(l==r && l==x) {
		sg[node]++;
		return;
	}
	int mid = (l+r)/2;
	updt(2*node, l, mid, x);
	updt(2*node+1, mid+1, r, x);
	sg[node] = sg[2*node]+sg[2*node+1];
}

int quer(int node, int l, int r, int ll, int rr) {
	if(l>rr||r<ll) return 0;
	if(l>=ll&&r<=rr) {
		return sg[node];
	}
	int mid = (l+r)/2;
	int q1 = quer(2*node, l, mid, ll, rr);
	int q2 = quer(2*node+1, mid+1, r, ll, rr);
	return q1 + q2;
}

int bin_pow(int x, int y) {
	int ret = 1;
	while(y > 0) {
		if(y&1) ret = ret * x % mod;
		x = x * x % mod;
		y >>= 1;
	}
	return ret;
}

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0);
	cin >> n;
	for(int i=0; i<n; i++) {
		int x, y;
		cin >> x >> y;
		xc.insert(x);
		yc.insert(y);
		pts[i] = make_pair(x, y);
	}
	int c = 0;
	for(auto &x : xc) {
		xm[x] = c;
		c++;
	}
	c = 0;
	for(auto &y : yc) {
		ym[y] = c;
		c++;
	}
	for(int i=0; i<n; i++) {
		pts[i].first = xm[pts[i].first];
		pts[i].second = ym[pts[i].second];
	}
	sort(pts, pts+n);
	int ans = 0;
	for(int i=0; i<n; i++) {
		ans += bin_pow(2, n);
		int left = pts[i].first;
		int right = n-pts[i].first-1;
		int lower = pts[i].second;
		int upper = n-pts[i].second-1;
		int lower_left = quer(1, 0, n-1, 0, pts[i].second);
		int lower_right = lower - lower_left;
		int upper_left = left - lower_left;
		int upper_right = upper - upper_left;
		ans -= bin_pow(2, left) + bin_pow(2, right) + bin_pow(2, lower) + bin_pow(2, upper);
		ans += bin_pow(2, upper_left) + bin_pow(2, upper_right) + bin_pow(2, lower_left) + bin_pow(2, lower_right);
		ans--;
		ans %= mod;
		updt(1, 0, n-1, pts[i].second);
	}
	cout << ans;
	return 0;
}

