template <class T>
struct segment_tree {
  vector<T> data;
  T default_value;

  segment_tree(int size, T default_value) { //default_valueと親にまとめる演算子を持つので、実はモノイドを要素にしている
    int n = 2 * pow(2, ceil(log2(size))) - 1;
    data.assign(n, default_value);
    this->default_value = default_value;
  }

  int leaf_size() {
    return (data.size() + 1) / 2;
  }

  int not_leaf_size() {
    return leaf_size() - 1;
  }

  void set(int n, T value) {
    int i = not_leaf_size() + n;
    data[i] = value;

    while (i > 0) {
      i = (i-1)/2;
      int l_child = 2*i+1;
      int r_child = 2*i+2;
      data[i] = data[l_child] + data[r_child]; //TODO: 親の計算方法もコンストラクタで渡したい
    }
  }

  int get(int l, int r) {
    return _get(l, r, 0, 0, leaf_size() - 1);
  }

  int _get(int l, int r, int i, int il, int ir) {
    if (r < il || ir < l) {
      return default_value;
    }
    if (l <= il && ir <= r) {
      return data[i];
    }

    int l_child = 2*i+1;
    int r_child = 2*i+2;
    int mid_bound = (il + ir + 1)/2 - 1;

    return _get(l, r, l_child, il, mid_bound) + //TODO: 親の計算方法もコンストラクタで渡したい
      _get(l, r, r_child, mid_bound + 1, ir);
  }

  void dump() {
    int row_count = 1;
    for (int row = 0; row < data.size(); row++) {
      cout << data[row] << " ";

      if (row_count == row + 1) {
        cout << endl;
        row_count = row_count * 2 + 1;
      }
    }
  }
};

