#define rep(i, n) for(UL i = 0; i < (n); i++)

class RAQ {
public:
	struct Node {
		UL sum, buf;
		Node(UL s, UL b) : sum(s), buf(b) {}
	};
	vector<Node> node;
	UL N;
	UL n;
	void init(UL n) {
		N = 1;
		while (N < n)N <<= 1;
		this->n = n;
		node.assign(N * 2 - 1, Node(0, 0));
	}
	UL query(UL a, UL b, UL l = 0, UL r = -1, UL i = 0) {
		if (r == -1) r = N;
		if (b <= l || r <= a) return 0;
		if (a <= l && r <= b) return node[i].sum;
		int rag = min(r, b) - max(l, a);
		return query(a, b, l, (l + r) / 2, i * 2 + 1) + query(a, b, (l + r) / 2, r, i * 2 + 2) + node[i].buf * rag;
	}
	void update(UL a, UL b, UL v, UL l = 0, UL r = -1, UL i = 0) {
		if (r == -1) r = N;
		if (b <= l || r <= a) return;
		if (a <= l && r <= b) { node[i].buf += v; node[i].sum += v * (r - l); return; }

		update(a, b, v, l, (l + r) / 2, i * 2 + 1);
		update(a, b, v, (l + r) / 2, r, i * 2 + 2);

		node[i].sum = node[i * 2 + 1].sum + node[i * 2 + 2].sum + node[i].buf * (r - l);
	}

};

