    {
        vector<pair<long, long>> p(N);
        for(auto& i : p)cin >> i.first >> i.second;
        sort(p.begin(), p.end());
        vector<unsigned long> idx(N);
        iota(idx.begin(), idx.end(), 0UL);
        sort(idx.begin(), idx.end(), [&p](auto i, auto j){return p[i].second < p[j].second;});
        for(unsigned long i = 0; i < N; ++i)perm[idx[i]] = i;
    }

    constexpr unsigned long MOD = 998244353;
    vector<unsigned long> binary(N + 1);
    binary[0] = 1;
    for(unsigned long i = 0; i < N; ++i)binary[i + 1] = binary[i] * 2 - (binary[i] > 499122176) * MOD;

    vector<unsigned long> fenwick_tree(N);
    auto que = [&fenwick_tree, &N](unsigned long i){
        unsigned long r = i;
        unsigned long ret{fenwick_tree[i]};
        while(i &= i + 1)ret += fenwick_tree[--i];
        i = r;
        while(i < N){
            ++fenwick_tree[i];
            i |= i + 1;
        }
        return ret;
    };

    vector<unsigned long> coef(N + 1);
    for(unsigned long i = 0; i < N; ++i){
        auto q = que(perm[i]);
        ++coef[q];
        ++coef[i - q];
        ++coef[perm[i] - q];
        ++coef[N - i - perm[i] + q - 1];
    }

    cout << inner_product(binary.begin(), binary.end(), coef.begin(), (N + MOD - 4) * (binary[N] - 1) % MOD, plus<>(), [&MOD](auto a, auto b){return a * b % MOD;}) % MOD << endl;
