	b2[0] = 1;
	for (int i = 1; i <= n + 2; i++) {
		b2[i] = b2[i - 1] + b2[i - 1];
		if (b2[i] >= MOD) b2[i] -= MOD;
	}

	std::sort(a, a + n, [](const Point &a, const Point &b) { return a.y < b.y; });
