const int MOD = 998244353;

using Int = Modint<MOD>;

Int pow(Int e, long x)
{
    Int res = 1, tmp = e;
    while (x > 0)
    {
        if (x & 1)
            res *= tmp;
        tmp *= tmp;
        x >>= 1;
    }
    return res;
}

template <typename T>
struct BIT
{
    int N, K;
    vector<T> bit;

    BIT(int X)
    {
        bit = vector<T>(X + 1, 0);
        N = X + 1;
        K = pow(2, (int)(log(X) / log(2)));
    }

    void add(int idx, T w)
    {
        for (int x = idx; x <= N; x += x & -x)
        {
            bit[x] += w;
        }
    }

    T sum(int idx)
    {
        T res = 0;
        for (int x = idx; x > 0; x -= x & -x)
            res += bit[x];
        return res;
    }

    int lb(T w)
    {
        int k = K, idx = 0;

        while (k > 0)
        {
            if (idx + k <= N && w > bit[idx + k])
            {
                w -= bit[idx + k];
                idx += k;
            }
            k >>= 1;
        }

        return idx + 1;
    }

    void chmax(int idx, T w)
    {
        for (int x = idx; x <= N; x += x & -x)
        {
            bit[x] = max(bit[x], w);
        }
    }

    T getmax(int idx)
    {
        T res = numeric_limits<T>::min();
        for (int x = idx; x > 0; x -= x & -x)
            res = max(res, bit[x]);
        return res;
    }
};

