//------------------------------- Solver ------------------------------------//

void solve()
{
    int n;
    cin >> n;
    akari<pair<int, int>> ps(n), xs(n), ys(n);
    for (int i = 0; i < n; i++)
    {
        cin >> ps[i].first >> ps[i].second;
        xs[i] = make_pair(ps[i].first, i);
        ys[i] = make_pair(ps[i].second, i);
    }
    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());
    for (int i = 0; i < n; i++)
    {
        ps[ys[i].second].second = i;
    }
    sort(ps.begin(), ps.end());
    Int ans = n;
    BIT<int> bit(n + 1);
    for (int i = 0; i < n; i++)
    {
        ans += pow(Int(2), n - 1) - 1;
        int y = ps[i].second;
        akari<int> cs(4);
        cs[0] = bit.sum(y + 1), cs[1] = i - cs[0];
        bit.add(y + 1, 1);
        cs[3] = y - cs[0], cs[2] = n - 1 - i - cs[3];
        for (int s = 1; s < 16; s++)
        {
            if (!((s & 0b1010) == 0b1010) && !((s & 0b0101) == 0b0101))
            {
                continue;
            }
            Int res = 1;
            for (int j = 0; j < 4; j++)
            {
                if (s >> j & 1)
                {
                    res *= pow(Int(2), cs[j]) - 1;
                }
            }
            //cout << bitset<4>(s) << ' ' << res << endl;
            ans += res;
        }
    }
    cout << ans << endl;
}

int main()
{
    solve();
    return 0;
}

