template<typename T = int> class BIT {
public:
    int n;
    vector<T> dat;
    BIT(int n) : n(n) { dat.assign(n, 0); }
    // [0, k)
    T sum(int k) {        if (k >= n) k = n - 1;        T ret = 0;        for (int x = k - 1; x >= 0; x = (x & (x + 1)) - 1) {            ret += dat[x];        }        return ret;    }
    // [l, r)
    T sum(int l, int r) { return sum(r) - sum(l); }
    T get(int l, int r) { return sum(r) - sum(l); }
    T get(int k) { return sum(k); }
    T operator[](int k) {        assert(0 <= k && k < n);        return sum(k + 1) - sum(k);    }
    T operator()(int k) { return sum(k); }
    T operator()(int l, int r) { return sum(l, r); }
    //0 index
    void add(int k, T val = 1) { for (int x = k; x < n; x |= x + 1)dat[x] += val; }
    void operator+=(int k) { add(k, 1); }
    void operator-=(int k) { add(k, -1); }
    void update(int k, T val = 0) { add(k, -operator[](k) + val); }
    void del(int k) { update(k, 0); }
    void clear() { fill(dat, 0); }
    void debu() {
#ifdef _DEBUG
        vi res;        rep(i, min(10, n)) {            res.push_back(operator[](i));        }        deb(res);
#endif
    }
    //合計がw以上となる最小のxを返す
    //閉区間
    int lower_bound(int w) {        if (w <= 0) return -1;        int x = 0;        int k = 1;        while ((k << 1) <= n) k <<= 1;        for (; k > 0; k >>= 1) {            if (x + k <= n && dat[x + k - 1] < w) {                w -= dat[x + k - 1];                x += k;            }        }        return x;    }
};
//自分より大きい個数
template<class T> int cou_big(const vector<T> &b) {    int n = sz(b);    int size = max(b);    assert(size < 1e8);    BIT<int> bt(size + 3);    int cou = 0;    rer(i, n - 1) {        cou += bt.get(b[i]);        bt.add(b[i], 1);    }    return cou;}
template<class T> int cou_big_back( vector<T> &b) {    rev(b);    int ret = cou_big(b);    rev(b);    return ret;}
//自分以上の個数
template<class T> int cou_big_eq(const vector<T> &b) {    int n = sz(b);    int size = max(b);    assert(size < 1e8);    BIT<int> bt(size + 3);    int cou = 0;    rer(i, n - 1) {        cou += bt.get(b[i] + 1);        bt.add(b[i], 1);    }    return cou;}
template<class T> int cou_big_eq_back( vector<T> &b) {    rev(b);    int ret = cou_big_eq(b);    rev(b);    return ret;}
//自分より小さい個数
template<class T> int cou_small(const vector<T> &b) {    int n = sz(b);    int size = max(b);    assert(size < 1e8);    BIT<int> bt(size + 3);    int cou = 0;    rep(i, n) {        cou += bt.get(b[i]);        bt.add(b[i], 1);    }    return cou;}
template<class T> int cou_small_back( vector<T> &b) {    rev(b);    int ret = cou_small(b);    rev(b);    return ret;}
//自分より小さい個数
template<class T> int cou_small_eq(const vector<T> &b) {    int n = sz(b);    int size = max(b);    assert(size < 1e8);    BIT<int> bt(size + 3);    int cou = 0;    rep(i, n) {        cou += bt.get(b[i] + 1);        bt.add(b[i], 1);    }    return cou;}
template<class T> int cou_small_eq_back( vector<T> &b) {    rev(b);    int ret = cou_small_eq(b);    rev(b);    return ret;}
//自分より大きい個数
template<class T> int cou_big_minus(const vector<T> &b) {    int n = sz(b);    int miv = b[0], mav = b[0];    rep(i, 1, n) {        if (b[i] < miv)miv = b[i];        if (b[i] > mav)mav = b[i];    }    int add = max(0, -miv);    int size = mav + add + 3;    assert(size < 1e8);    BIT<int> bt(size);    int cou = 0;    rer(i, n - 1) {        cou += bt.get(b[i] + add);        bt.add(b[i] + add, 1);    }    return cou;}
