template<class T> class BIT2 {

      int N, M;
      map<ipair, T> log;
   public:
      // x, y
      void init(int W, int H, T a) {
         N = H;
         M = W;
         // bit.resize(NMAX);
         // for (int i = 0; i < NMAX; i++) bit[i].resize(NMAX);
         // bit.assign(NMAX, vector<T>(NMAX, a));
         // fill(bit[0], bit[M], a);
      }

      void add(int a, int b, T w) {
         for (int x = a; x <= M; x += x & -x) {
            for (int y = b; y <= N; y += y & -y) {
               // bit[x][y] += w;
               log[ipair(x, y)] += w;
            }
         }
      }
      // [1, a] x [1, b]
      T sum(int a, int b) {
         T ret = 0;
         for (int x = a; x > 0; x -= x & -x) {
            for (int y = b; y > 0; y -= y & -y) {
               // ret += bit[x][y];
               ret += log[ipair(x, y)];
            }
         }
         return ret;
      }

      // [a1, a2] x [b1, b2]
      T sum2(int a1, int a2, int b1, int b2) {
         T ret = 0;
         ret += sum(a2, b2);
         ret -= sum(a2, b1 - 1);
         ret -= sum(a1 - 1, b2);
         ret += sum(a1 - 1, b1 - 1);
         return ret;
      }
};

