class Bit {
	std::vector<int> _vec;
public:
	Bit(const int size) : _vec(size, 0) {}
	int operator[](int position) const {
		int result = 0;
		while (position >= 0) {
			result += _vec[position];
			position -= ~position & (position + 1);
		}
		return result;
	}
	void clear() {
		std::fill(_vec.begin(), _vec.end(), 0);
	}
	void increment(int position) {
		while (position < _vec.size()) {
			++_vec[position];
			position += ~position & (position + 1);
		}
	}
	void decremenet(int position) {
		while (position < _vec.size()) {
			--_vec[position];
			position += ~position & (position + 1);
		}
	}
};
