	long long int result = power[n - 1] * n % mod;
	for (auto i = 0; i < n; ++i) {
		auto p = points[i];
		higher_bit.decremenet(p.y);
		auto right_down = higher_bit[p.y];
		auto right_up = (n - i - 1) - higher_bit[p.y];
		auto left_down = lower_bit[p.y];
		auto left_up =  i - lower_bit[p.y];
		result += ((power[right_down] - 1) * (power[right_up] - 1) % mod) * ((power[left_down] - 1) * (power[left_up] - 1) % mod) % mod;
		result += ((power[right_up] - 1) % mod) * ((power[left_down] - 1) * (power[left_up] - 1) % mod) % mod;
		result += ((power[right_down] - 1) % mod) * ((power[left_down] - 1) * (power[left_up] - 1) % mod) % mod;
		result += ((power[right_down] - 1) * (power[right_up] - 1) % mod) * ((power[left_up] - 1) % mod) % mod;
		result += ((power[right_down] - 1) * (power[right_up] - 1) % mod) * ((power[left_down] - 1) % mod) % mod;
		result += ((power[right_up] - 1) % mod) * ((power[left_down] - 1) % mod) % mod;
		result += ((power[right_down] - 1) % mod) * ((power[left_up] - 1) % mod) % mod;
		result %= mod;
		lower_bit.increment(p.y);
	}
	std::cout << (result % mod + mod) % mod << std::endl;
}

