    sort(ALL(vx));
    vx.erase(unique(ALL(vx)), vx.end());
    REP(i, n) x[i] = lower_bound(ALL(vx), x[i]) - vx.begin();
    // セグ木構築
    vector<vector<ll>> v(vx.size());
    REP(i, n) v[x[i]].push_back(y[i]);
    REP(i, vx.size()) sort(ALL(v[i]));
    segTreeRangeFreq seg(v);

    mint ret = mint(2).pow(n-1) * n;
    REP(i, n) {
        vector<ll> cnt(8);
        // x < x[i], y < y[i]
        cnt[0] = seg.query(0, x[i], y[i]-1);
        // x < x[i], y > y[i]
        cnt[1] = seg.query(0, x[i], INF) - cnt[0];
        // x > x[i], y < y[i]
        cnt[2] = seg.query(x[i]+1, vx.size(), y[i]-1);
        // x > x[i], y > y[i]
        cnt[3] = seg.query(x[i]+1, vx.size(), INF) - cnt[2];
        // x = x[i], y < y[i]
        cnt[4] = lower_bound(ALL(v[x[i]]), y[i])-v[x[i]].begin();
        // x = x[i], y > y[i]
        cnt[5] = v[x[i]].size()-cnt[4]-1;
        // x < x[i], y = y[i]
        cnt[6] = seg.query(0, x[i]-1, y[i]) - seg.query(0, x[i]-1, y[i]-1);
        // x > x[i], y = y[i]
        cnt[7] = seg.query(x[i]+1, vx.size(), y[i]) - seg.query(x[i]+1, vx.size(), y[i]-1);

