// FenwickTree (0 - indexed)
template<class T>
class FenwickTree {
    int n;
    std::vector<T> data;
public:
    FenwickTree(int n) : n(n), data(n + 1) {}

    // [0, i)の区間和を取得する
    T sum(int i) {
        T s = 0;
        for (; i > 0; i -= i & -i)s += data[i];
        return s;
    }

    // [l, r)の区間和を取得する
    T sum(int l, int r) { return sum(r) - sum(l); }

    // 要素iにxを加算する
    void add(int i, T x) { for (i++; i <= n; i += i & -i)data[i] += x; }
};

