    sort(pts.begin(),pts.end());


    // initially, all points are on right
    for (auto p: pts) {
	upd(bitR, p.second,1);
    }


    ll res = n*pw(2,n-1)%mod; // every point is in 2^(n-1) subsets


    for (auto p: pts) {
	ll y = p.second;
	upd(bitR, y, -1);

	ll Q1 = above(bitR, y);
	ll Q2 = above(bitL, y);
	ll Q3 = below(bitL, y);
