	ll d24 = (pw(2,Q2)-1)*(pw(2,Q4)-1)%mod;
	ll d13 = (pw(2,Q1)-1)*(pw(2,Q3)-1)%mod;
	ll d1234 = d24*d13%mod;

	ll cur = (pw(2,Q1+Q3)*d24%mod + pw(2,Q2+Q4)*d13%mod - d1234)%mod;

	add(res, cur);
	upd(bitL, y, +1);
    }


    res %= mod;
    res += mod;
    res %= mod;
    cout<<res<<endl;


