vector<ll> divisor(ll n){
    vector<ll> res(0);
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}

//Range Sum Query
const ll N_ = (1 << 18);
ll seg[2*N_-1];

void init_seg(){
  rep(i, 2*N_-1) seg[i] = 0;
}

void add(ll k, ll x){
  k += N_-1;
  seg[k] += x;
  while(k > 0){
    k = (k-1)/2;
    seg[k] = seg[2*k+1] + seg[2*k+2];
  }
}

ll get_sum(ll x, ll y, ll k = 0, ll left = 0, ll right = N_){
  if(right <= x || y <= left) return 0;
  if(x <= left && right <= y) return seg[k];
  ll mid = (left + right) / 2;
  ll l = get_sum(x, y, 2*k+1, left, mid);
  ll r = get_sum(x, y, 2*k+2, mid, right);
  return l + r;
}

ll N;
vector<pair<ll, ll>> xy;
void solve(){
  cin >> N;
  xy.resize(N);
  rep(i, N) cin >> xy[i].f >> xy[i].s;
  sort(xy.begin(), xy.end());
  vector<ll> xs, ys;
  rep(i, N){
    xs.pb(xy[i].f);
    ys.pb(xy[i].s);
  }
  sort(xs.begin(), xs.end());
  sort(ys.begin(), ys.end());
  xs.erase(unique(xs.begin(), xs.end()), xs.end());
  ys.erase(unique(ys.begin(), ys.end()), ys.end());
  rep(i, N){
    xy[i].f = lower_bound(xs.begin(), xs.end(), xy[i].f) - xs.begin();
    xy[i].s = lower_bound(ys.begin(), ys.end(), xy[i].s) - ys.begin();
  }

  vector<ll> lu(N), ld(N), ru(N), rd(N);
  rep(i, N){
    ld[i] = get_sum(0, xy[i].s);
    lu[i] = get_sum(xy[i].s+1, N_);
    add(xy[i].s, 1);
  }
  init_seg();
  revrep(i, N){
    rd[i] = get_sum(0, xy[i].s);
    ru[i] = get_sum(xy[i].s+1, N_);
    add(xy[i].s, 1);
  }

  ll ans = 0;
  rep(i, N){
    ans += pow_mod(2, N-1);
    ans %= MOD;
    ll ulu = pow_mod(2, lu[i]) - 1;
    ll uld = pow_mod(2, ld[i]) - 1;
    ll uru = pow_mod(2, ru[i]) - 1;
    ll urd = pow_mod(2, rd[i]) - 1;

    //四つ
    ans += ulu * uld % MOD * uru % MOD * urd % MOD;
    ans %= MOD;

    //三つ
    ans += ulu * uld % MOD * uru % MOD;
    ans %= MOD;
    ans += ulu * uld % MOD * urd % MOD;
    ans %= MOD;
    ans += ulu * uru % MOD * urd % MOD;
    ans %= MOD;
    ans += uld * uru % MOD * urd % MOD;
    ans %= MOD;

    //二つ
    ans += ulu * urd % MOD;
    ans %= MOD;
    ans += uld * uru % MOD;
    ans %= MOD;
  }
  cout << ans << endl;
}


int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
}

