const ll MOD = 998244353;
ll n, ans;
vll x, y, idx, idx2, t;

ll query(ll l, ll r, ll v, ll tl, ll tr) {
    if (l > r) {
        return 0;
    }
    if (l == tl && r == tr) {
        return t[v];
    }
    ll tm = (tl + tr) / 2;
    return query(l, min(r, tm), v * 2, tl, tm) + query(max(l, tm + 1), r, v * 2 + 1, tm + 1, tr);
}

void update(ll pos, ll v, ll tl, ll tr) {
    t[v]++;
    if (tl != tr) {
        ll tm = (tl + tr) / 2;
        if (pos <= tm) {
            update(pos, 2 * v, tl, tm);
        } else {
            update(pos, 2 * v + 1, tm + 1, tr);
        }
    }
}

ll bin_exp(ll b, ll e, ll mod = MOD) {
    ll ret = 1;
    while (e > 0) {
        if (e & 1) {
            (ret *= b) %= MOD;
        }
        (b *= b) %= MOD;
        e >>= 1;
    }
    return ret;
}

int main() {
    fast_io; cout_precision;
    cin >> n;
    x.resize(n); y.resize(n);
    idx.resize(n); idx2.resize(n);
    for (ll i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        idx[i] = i; idx2[i] = i;
    }
    sort(idx.begin(), idx.end(), [&](const ll &l, const ll &r) {
        if (y[l] != y[r]) {
            return y[l] < y[r];
        } else {
            return l < r;
        }
    });
    for (ll i = 0; i < n; i++) {
        idx2[idx[i]] = i;
    }
    sort(idx.begin(), idx.end(), [&](const ll &l, const ll &r) {
        if (x[l] != x[r]) {
            return x[l] < x[r];
        } else {
            return y[l] < y[r];
        }
    });
    t.resize(3 * n);
    ans = 0;
    for (ll i = 0, q1, q2, q3, q4; i < n; i++) {
        q3 = query(0, idx2[idx[i]], 1, 0, n - 1);
        q2 = i - q3;
        q4 = idx2[idx[i]] - q3;
        q1 = n - i - 1 - q4;
        (ans += bin_exp(2, n)) %= MOD;
        (ans -= bin_exp(2, q1 + q2)) %= MOD;
        (ans -= bin_exp(2, q2 + q3)) %= MOD;
        (ans -= bin_exp(2, q3 + q4)) %= MOD;
        (ans -= bin_exp(2, q4 + q1)) %= MOD;
        (ans += bin_exp(2, q1)) %= MOD;
        (ans += bin_exp(2, q2)) %= MOD;
        (ans += bin_exp(2, q3)) %= MOD;
        (ans += bin_exp(2, q4)) %= MOD;
        (ans -= 1) %= MOD;
        update(idx2[idx[i]], 1, 0, n - 1);
    }
    cout << (ans + MOD) % MOD << endl;
}

