  map<int, int> map_x, map_y;
  {
    auto it = set_x.begin();
    for (auto i = 0; i < N; i++)
    {
      map_x[*it] = i;
      ++it;
    }
  }
  {
    auto it = set_y.begin();
    for (auto i = 0; i < N; i++)
    {
      map_y[*it] = i;
      ++it;
    }
  }
  for (auto i = 0; i < N; i++)
  {
    get<0>(V[i]) = map_x[get<0>(V[i])];
    get<1>(V[i]) = map_y[get<1>(V[i])];
  }
  sort(V.begin(), V.end());
#if DEBUG == 1
  for (auto e : V)
  {
    cerr << "(" << get<0>(e) << ", " << get<1>(e) << ")" << endl;
  }
