const int MOD = 998244353;

template<class T> class BIT {
	static const int n = ten(5) * 3;
	T bit[n + 1];
public:
	BIT() {}
	T sum(int i) {
		T s = 0;
		while (i > 0) { s += bit[i]; i -= i & -i; }
		return s;
	}
	void add(int i, T x) {
		while (i <= n) { bit[i] += x; i += i & -i; }
	}
};

BIT<int> lb, rb;

ll pws[ten(5) * 3];

void init() {
	pws[0] = 1;
	FOR(i, ten(5) * 2 + 20) pws[i + 1] = pws[i] * 2 % MOD;
}

int main() {
	init();

	int n; reader(n);
	vector<Pii> vp(n);
	FOR(i, n) {
		reader(vp[i].first, vp[i].second);
	}
	sort(vp.begin(), vp.end());
	{
		vector<int> a(n);
		FOR(i, n) a[i] = vp[i].second;
		sort(a.begin(), a.end());
		FOR(i, n) {
			vp[i].first = i + 1;
			vp[i].second = lower_bound(a.begin(), a.end(), vp[i].second) - a.begin() + 1;
		}
	}
	FOR(i, n) rb.add(i + 1, 1);
	ll ans = 0;
	for (auto& kv : vp) {
		int cur = kv.second;
		rb.add(cur, -1);

		int o = lb.sum(cur);
		int p = kv.first - 1 - o;
		int q = rb.sum(cur);
		int r = n - 1 - o - p - q;

		ll cc = pws[o + p] + pws[p + r] + pws[r + q] + pws[q + o] - pws[o] - pws[p] - pws[q] - pws[r];
		ans = (ans + pws[n] - cc - 1) % MOD;
		lb.add(cur, 1);
	}
	ans = (ans % MOD + MOD) % MOD;
	writerLn(ans);

	return 0;
}

#include<bits/stdc++.h>
using namespace std;

const long long MOD=998244353;

template<class Abel> struct BIT{
    vector<Abel> dat;
    long long n;
    Abel unity;

    BIT(long long n_origin, Abel SUM_UNITY):dat(n_origin +1,SUM_UNITY), n(n_origin), unity(SUM_UNITY){}

    Abel sum_from_first(long long i){//[1,i]
        Abel s=0;
        while(i>0){
            s+=dat[i];
            i-= (i&(-i));
        }
        return s;
    }

    Abel sum(long long i, long long j){//[i,j)
        if(i>=j) return unity;
        Abel vl = sum_from_first(i-1);
        Abel vr = sum_from_first(j-1);
        return vr-vl;
    }

    void add(long long i, Abel x){
        while(i <= n){
            dat[i] += x;
            i += (i&(-i));
        }
    }

    long long BIT_lower_bound(long long L, long long R, Abel val){//[L,R)
        long long M;
        while(L<R-1){
            M=(L+R)/2;
            if(sum_from_first(M)==val&&sum_from_first(M-1)==val){
                R=M;
            }else if(sum_from_first(M)>val){
                R=M;
            }else{
                L=M;
            }
        }
        return L;
    }
};

