        for_x_sort.push_back(make_pair(x,y));
    }
    sort(for_x_sort.begin(),for_x_sort.end());
    long long yza[N+1];
    for(i=0; i<N; i++){
        y=for_x_sort[i].second;
        yza[i+1]=y;
    }
    BIT<long long> BIT_left(N,0), BIT_right(N,0);
    long long LU[N+1], LD[N+1], RU[N+1], RD[N+1];
    for(i=1; i<=N; i++){
        LD[i]=BIT_left.sum(1,yza[i]);
        LU[i]=BIT_left.sum(yza[i]+1,N+1);
        BIT_left.add(yza[i],1);
    }
    for(i=N; i>=1; i--){
        RD[i]=BIT_right.sum(1,yza[i]);
        RU[i]=BIT_right.sum(yza[i]+1,N+1);
        BIT_right.add(yza[i],1);
    }
    long long nibeki[N+1];
    nibeki[0]=1;
    for(i=1; i<=N; i++){
        nibeki[i]=nibeki[i-1]*2;
        nibeki[i]%=MOD;
    }
    long long ans;
    ans=N-4+MOD;
    ans%=MOD;
    ans*=(nibeki[N]-1);
    ans%=MOD;
    for(i=1; i<=N; i++){
        ans+=nibeki[LU[i]];
        ans%=MOD;
        ans+=nibeki[LD[i]];
        ans%=MOD;
        ans+=nibeki[RU[i]];
        ans%=MOD;
        ans+=nibeki[RD[i]];
        ans%=MOD;
    }

    //output
    cout << ans << endl;
    system("pause");
    return 0;
}

