const int maxnode = 1000000 + 5;

int psz;
struct Node {
  int key, siz;
  Node *ch[2];
  void update() { siz = ch[0]->siz + ch[1]->siz + 1; }
} pool[maxnode], *null = new Node();

Node *new_node(int k) {
  Node *i = pool + psz++;
  i->key = k, i->siz = 1, i->ch[0] = i->ch[1] = null;
  return i;
}

class SBT {
  Node *root;

  void rotate(Node *&u, int d) {
    Node *v = u->ch[d ^ 1];
    u->ch[d ^ 1] = v->ch[d];
    v->ch[d] = u;
    v->siz = u->siz;
    u->update();
    u = v;
  }

  void maintain(Node *&u, int d) {
    if (u == null) return;
    if (u->ch[d]->ch[d]->siz > u->ch[d ^ 1]->siz)
      rotate(u, d ^ 1);
    else if (u->ch[d]->ch[d ^ 1]->siz <= u->ch[d ^ 1]->siz)
      return;
    else
      rotate(u->ch[d], d), rotate(u, d ^ 1);
    maintain(u->ch[0], 0);
    maintain(u->ch[1], 1);
    maintain(u, 0);
    maintain(u, 1);
  }

  void insert(Node *&u, int k) {
    if (u == null) {
      u = new_node(k);
      return;
    }
    // if (u->key == k) return false;
    int d = (k > u->key);
    insert(u->ch[d], k);
    maintain(u, d), u->update();
  }

  void erase(Node *&u, int k) {
    if (u == null) return;
    if (u->key == k) {
      if (u->ch[1] == null) {
        u = u->ch[0];
        return;
      }
      if (u->ch[0] == null) {
        u = u->ch[1];
        return;
      }
      Node *v = u->ch[1];
      while (v->ch[0] != null) v = v->ch[0];
      u->key = v->key;
      erase(u->ch[1], v->key);
      u->update();
      return;
    }
    erase(u->ch[k > u->key], k);
    u->update();
  }

 public:
  SBT() : root(null) { null->ch[0] = null->ch[1] = null; }
  int size() { return root->siz; }
  bool empty() { return root == null; }
  void clear() { root = null; }
  void insert(int k) { insert(root, k); }
  void erase(int k) { erase(root, k); }
  int rank(int k) {
    int ret = 0;
    for (Node *u = root; u != null;) {
      if (k > u->key) ret += u->ch[0]->siz + 1;
      u = u->ch[k > u->key];
    }
    return ret;
  }
  int select(int k) {
    for (Node *u = root; u != null;) {
      int t = u->ch[0]->siz;
      if (t == k) return u->key;
      u = u->ch[k > t], k -= (t < k ? t + 1 : 0);
    }
    return inf;
  }
};

const int maxn = 200000 + 5;
const int mod = 998244353;

int n;
int x[maxn], y[maxn];
int vx[maxn], vy[maxn];

SBT c[maxn];

void update(int i, int y) {
  for (; i <= n; i += i & -i) c[i].insert(y);
}

int query(int i, int y) {
  int ret = 0;
  for (; i; i -= i & -i) ret += c[i].rank(y);
  return ret;
}

int pow_mod(int a, int b) {
  int ret = 1;
  for (; b; a = (LL)a * a % mod, b >>= 1)
    if (b & 1) ret = (LL)ret * a % mod;
  return ret;
}

int main() {
  scanf("%d", &n);
  rep(i, n) {
    scanf("%d%d", &x[i], &y[i]);
    vx[i] = x[i], vy[i] = y[i];
  }
  sort(vx, vx + n);
  sort(vy, vy + n);
  rep(i, n) {
    x[i] = lower_bound(vx, vx + n, x[i]) - vx + 1;
    y[i] = lower_bound(vy, vy + n, y[i]) - vy + 1;
    update(x[i], y[i]);
  }
  int tot = (pow_mod(2, n) - 1 + mod) % mod, ret = 0;
  rep(i, n) {
    int now = tot;
    now = (now - (pow_mod(2, x[i] - 1) - 1) + mod) % mod;
    now = (now - (pow_mod(2, n - x[i]) - 1) + mod) % mod;
    now = (now - (pow_mod(2, y[i] - 1) - 1) + mod) % mod;
    now = (now - (pow_mod(2, n - y[i]) - 1) + mod) % mod;
    int ld = query(x[i] - 1, y[i]);
    now = (now + pow_mod(2, ld) - 1) % mod;
    int rd = y[i] - 1 - ld;
    now = (now + pow_mod(2, rd) - 1) % mod;
    int lu = x[i] - 1 - ld;
    now = (now + pow_mod(2, lu) - 1) % mod;
    int ru = n - y[i] - lu;
    now = (now + pow_mod(2, ru) - 1) % mod;
    ret = (ret + now) % mod;
  }
  printf("%d\n", ret);

  return 0;
}

