/*-------------------------------------------------*/
long long mod_inv(long long a, long long mod = MOD) {
  a %= mod;
  if (__gcd(a, mod) != 1) return -1;
  long long b = mod, x = 1, y = 0;
  while (b > 0) {
    long long tmp = a / b;
    a -= tmp * b;
    swap(a, b);
    x -= tmp * y;
    swap(x, y);
  }
  x %= mod;
  if (x < 0) x += mod;
  return x;
}

const int MAX = 10000000;
long long fact[MAX + 1], fact_inv[MAX + 1];
void nCk_init(int val = MAX, long long mod = MOD) {
  fact[0] = 1;
  FOR(i, 1, val + 1) fact[i] = fact[i - 1] * i % mod;
  fact_inv[val] = mod_inv(fact[val], mod);
  for (int i = val; i > 0; --i) fact_inv[i - 1] = fact_inv[i] * i % mod;
}

long long nCk(int n, int k, long long mod = MOD) {
  if (n < 0 || n < k || k < 0) return 0;
  return fact[n] * fact_inv[k] % mod * fact_inv[n - k] % mod;
}

long long mod_pow(long long base, long long exponent, long long mod = MOD) {
  base %= mod;
  long long res = 1;
  while (exponent > 0) {
    if (exponent & 1) (res *= base) %= mod;
    (base *= base) %= mod;
    exponent >>= 1;
  }
  return res;
}

template <typename Abelian>
struct BIT2D {
  BIT2D(int height_, int width_, const Abelian UNITY = 0) : height(height_), width(width_), UNITY(UNITY) {
    ++height;
    ++width;
    dat.assign(height, vector<Abelian>(width, UNITY));
  }

  void add(int y, int x, Abelian value) {
    for (int i = y; i < height; i += i & -i) {
      for (int j = x; j < width; j += j & -j) {
        dat[i][j] += value;
      }
    }
  }

  Abelian sum(int y, int x) {
    Abelian res = UNITY;
    for (int i = y; i > 0; i -= i & -i) {
      for (int j = x; j > 0; j -= j & -j) {
        res += dat[i][j];
      }
    }
    return res;
  }

  Abelian sum(int y1, int x1, int y2, int x2) {
    return sum(y2, x2) - sum(y2, x1 - 1) - sum(y1 - 1, x2) + sum(y1 - 1, x1 - 1);
  }

private:
  int height, width;
  const Abelian UNITY;
  vector<vector<Abelian> > dat;
};

