}


struct UF {
	int n;
	vi d;
	UF() {}
	UF(int n) :n(n), d(n, -1) {}
	int root(int v) {
		if (d[v] < 0) return v;
		return d[v] = root(d[v]);
	}
	bool same(int a, int b) {
		return root(a) == root(b);
	}
	bool unite(int x, int y) {
		x = root(x); y = root(y);
		if (x == y) return false;
		if (size(x) < size(y)) swap(x, y);
		d[x] += d[y];
		d[y] = x;
		return true;
	}
	int size(int v) { return -d[root(v)]; }
};

struct Fibonacci {

	vvll fib;
	Fibonacci() {
		fib.resize(2, vll(2));
		fib[0][0] = 1; fib[0][1] = 1;
		fib[1][0] = 1; fib[1][1] = 0;
	}

	vvll mul(vvll &A, vvll &B) {
		vvll C(2, vll(2));
		rep(i, 2) {
			rep(k, 2) {
				rep(j, 2) {
					C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
				}
			}
		}
		return C;
	}

	ll pow(ll n) {
		vvll A = fib;
		vvll B(2, vll(2));
		rep(i, 2) {
			B[i][i] = 1;
		}
		while (n > 0) {
			if (n & 1)B = mul(B, A);
			A = mul(A, A);
			n >>= 1;
		}
		return B[1][0];
	}

};



vector<int> divisor(int n) {
	if (n == 1) return{};
	vi res;
	for (int i = 1; i*i <= n; i++) {
		if (n%i == 0) {
			res.emplace_back(i);
			if (i != 1 && i != n / i)res.emplace_back(n / i);
		}
	}
	return res;
}

struct Bellmanford {
	int n;
	struct edge {
		int from, to, cost;
	};
	vector<edge> E;
	vi d;
	Bellmanford(int n) :n(n), d(n) {
		E.resize(n);
	}
	void add_edge(int x, int y, int cost) {
		edge e;
		e.from = x; e.to = y; e.cost = cost;
		E.push_back(e);
	}
	void shortest_path(int s) {
		rep(i, n)d[i] = INF;
		d[s] = 0;
		while (true) {
			bool update = false;
			for (auto e : E) {
				if (d[e.from] != INF && d[e.to] > d[e.from] + e.cost) {
					d[e.to] = d[e.from] + e.cost;
					update = true;
				}
			}
			if (!update) break;
		}
	}
};
struct Dijkstra {
	int n;
	struct edge {
		int to; ll cost;
	};
	vector<vector<edge>> G;
	vll d;
	Dijkstra(int n) :n(n), d(n) {
		G.resize(n);
	}
	void add_edge(int x, int y, ll cost) {
		edge e;
		e.to = y; e.cost = cost;
		G[x].push_back(e);
	}
	void shortest_path(int s) {
		rep(i, n)d[i] = 100000000000000000;
		d[s] = 0;
		priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> que;
		que.push(make_pair(0, s));

		while (!que.empty()) {
			pii p = que.top(); que.pop();
			int v = p.second;
			if (d[v] < p.first) continue;
			for (auto e : G[v]) {
				if (d[e.to] > d[v] + e.cost) {
					d[e.to] = d[v] + e.cost;
					que.push(make_pair(d[e.to], e.to));
				}
			}
		}
	}
};

struct SegmentTree {
	int n;
	vector<ll> data;
	SegmentTree(int n_) {
		n = 1;
		while (n < n_) n *= 2;
		data = vector<ll>(2 * n - 1, 0);
	}

	void update(int idx, ll val) {//0-indexed
		idx += n - 1;
		//data[idx] += val;
		data[idx] = max(data[idx], val);
		while (idx > 0) {
			idx = (idx - 1) / 2;
			//data[idx] += val;
			data[idx] = max(data[idx], val);
		}
	}
	ll query(int a, int b) {// [a,b)
		return query_seg(a, b, 0, 0, n);
	}
	ll query_seg(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) return 0;
		if (a <= l && r <= b)return data[k];
		else {
			//return query_seg(a, b, k * 2 + 1, l, (l + r) / 2) + query_seg(a, b, k * 2 + 2, (l + r) / 2, r);
			return max(query_seg(a, b, k * 2 + 1, l, (l + r) / 2), query_seg(a, b, k * 2 + 2, (l + r) / 2, r));

		}
	}
};

struct LazySegmentTree {
	int n;
	vector<ll> data, lazy;
	LazySegmentTree(int n_) {
		n = 1;
		while (n < n_) n *= 2;
		data = vector<ll>(2 * n-1, 0);
		lazy = vector<ll>(2 * n-1, 0);
	}

	void eval(int k, int l, int r) {
		if (lazy[k] != 0) {
			data[k] += lazy[k]/(r-l);
		}
		if (r - l > 1) {
			lazy[2 * k + 1] += lazy[k]/2;
			lazy[2 * k + 2] += lazy[k]/2;
		}
		lazy[k] = 0;
	}
	void update(int a, int b, int val, int k, int l, int r){
		eval(k, l, r);
		if (r <= a || b <= l) return;
		if (a <= l && r <= b) {
			lazy[k] += (r - l)*val;
			eval(k, l, r);
		}
		else {
			update(a, b, val, 2 * k + 1, l, (l + r) / 2);
			update(a, b, val, 2 * k + 2, (l + r) / 2, r);
			data[k] = min(data[2 * k + 1], data[2 * k + 2]);
		}
	}
	void update(int a, int b, int val) {
		return update(a, b, val, 0, 0, n);
	}
	ll query(int a, int b) {// [a,b)
		return query_seg(a, b, 0, 0, n);
	}
	ll query_seg(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) return INF;
		eval(k, l, r);
		if (a <= l && r <= b)return data[k];
		else {
			//return query_seg(a, b, k * 2 + 1, l, (l + r) / 2) + query_seg(a, b, k * 2 + 2, (l + r) / 2, r);
			return min(query_seg(a, b, k * 2 + 1, l, (l + r) / 2), query_seg(a, b, k * 2 + 2, (l + r) / 2, r));

		}
	}
};

struct Trie {
	Trie *next[26];

	Trie() {
		fill(next, next + 26, (Trie *)0);
	}

	void insert(char *s) {
		if (*s == '\0') return;
		if (this->next[*s - 'a'] == NULL) {
			this->next[*s - 'a'] = new Trie();
		}
		this->next[*s - 'a']->insert(s + 1);
	}

	bool find(char *s) {
		if (*s == '\0') return true;
		if (this->next[*s - 'a'] == NULL) {
			return false;
		}
		return this->next[*s - 'a']->find(s + 1);
	}
};

