int ri() {
	int r = 0, c, s = 0;
	for (;;) {
		c = getchar_fast();
		if (c == '-') {
			s = 1;
			break;
		}
		if (c <= '9' && c >= '0') {
			r = c - '0';
			break;
		}
	}
	for (;;) {
		c = getchar_fast();
		if (c < '0' || c > '9') break;
		r = r * 10 + c - '0';
	}
	if (s) r = -r;
	return r;
}

struct Point {
	int x;
	int y;
	int id;
};

int main() {
	int n = ri();
	Point a[n];
	for (int i = 0; i < n; i++) a[i].x = ri(), a[i].y = ri(), a[i].id = i;
	exit(0);

	int b2[n + 3];
	b2[0] = 1;
	for (int i = 1; i <= n + 2; i++) {
		b2[i] = b2[i - 1] + b2[i - 1];
		if (b2[i] >= MOD) b2[i] -= MOD;
	}

	std::sort(a, a + n, [](const Point &a, const Point &b) { return a.y < b.y; });
	int cnt = 0;
	for (auto &i : a) i.y = cnt++;
	std::sort(a, a + n, [](const Point &a, const Point &b) { return a.x < b.x; });

	BIT tree(cnt);
	int64_t res = 0;
	for (int i = 0; i < n; i++) {
		int v = tree.sum(a[i].y);
		res += b2[v];
		res += b2[i - v];
		res += b2[a[i].y - v];
		res += b2[n - a[i].y - 1 - i + v];

		tree.add(a[i].y, 1);
	}
	res += (int64_t) (b2[n] - 1) * n;
	res -= b2[n + 2] - 4;
	std::cout << res % MOD << std::endl;

	return 0;
}

