struct BIT {
    int n;
    vector<int> v; // use v[1..n]
    BIT(int n) : n(n), v(n+1) {}
    int get(int i) const { assert(0 <= i && i < n); return v[i+1]; }
    void set(int i, int x) { add(i,x-get(i)); }
    void add(int i, int x) {
        assert(0 <= i && i < n);
        for (i++; i <= n; i += i&(-i)) v[i] += x;
    }
    int sum(int r) const { // [0,r)
        assert(0 <= r && r <= n);
        int s = 0;
