//1点更新,区間和
class SegmentTree {
public:
    SegmentTree(ll n) {
        n_ = (ll)pow(2, ceil(log2(n)));
        nodes_.resize(2 * n_ - 1, 0);
    }

    void update(ll x, ll diff) {
        nodes_[x + n_ - 1] += diff;
        for (ll i = (x + n_ - 2) / 2; i > 0; i = (i - 1) / 2) {
            nodes_[i] = nodes_[2 * i + 1] + nodes_[2 * i + 2];
        }
    }

    ll getSum(ll a, ll b, ll k = 0, ll l = 0, ll r = -1) {
        if (r < 0) {
            r = n_;
        }
        if (r <= a || b <= l) {
            return 0;
        }
        if (a <= l && r <= b) {
            return nodes_[k];
        }
        ll lv = getSum(a, b, 2 * k + 1, l, (l + r) / 2);
        ll rv = getSum(a, b, 2 * k + 2, (l + r) / 2, r);
        return lv + rv;
    }

private:
    //2のべき乗
    ll n_;
    vector<ll> nodes_;
};


ll MODpow(ll n, ll m, ll mod) {
    ll result = 1;
    while (m) {
        if (m % 2 == 1) {
            result *= n;
            result %= mod;
        }

        m /= 2;
        n *= n;
        n %= mod;
    }

    return result;
}

int main() {
    ll N;
    cin >> N;
    struct Point {
        ll x, y;
    };
    vector<Point> points(N);
    for (Point& p : points) {
        cin >> p.x >> p.y;
    }

    //座標圧縮
    {
        set<ll> x_st, y_st;
        for (const Point& p : points) {
            x_st.insert(p.x);
            y_st.insert(p.y);
        }
        map<ll, ll> x_mp, y_mp;
        ll num = 0;
        for (const auto& e : x_st) {
            x_mp[e] = num++;
        }
        num = 0;
        for (const auto& e : y_st) {
            y_mp[e] = num++;
        }
        for (Point& p : points) {
            p.x = x_mp[p.x];
            p.y = y_mp[p.y];
        }
    }

    //x順でソート
    sort(points.begin(), points.end(), [](Point& lhs, Point& rhs){
        return lhs.x < rhs.x;
    });

    constexpr ll MAX = 2e5;
    SegmentTree before(MAX + 1), after(MAX + 1);
    for (const Point& p : points) {
        after.update(p.y, 1);
    }

    //i番目の点から見て各象限にある点の個数
    vector<vector<ll>> num(N, vector<ll>(4, 0));

    constexpr ll MOD = 998244353;

    ll ans = 0;

    for (const Point& p : points) {
        //右上
        ll num1 = after.getSum(p.y + 1, MAX + 1);
        ll pat1 = (MODpow(2, num1, MOD) + MOD - 1) % MOD;

        //左上
        ll num2 = before.getSum(p.y + 1, MAX + 1);
        ll pat2 = (MODpow(2, num2, MOD) + MOD - 1) % MOD;

        //左下
        ll num3 = before.getSum(0, p.y);
        ll pat3 = (MODpow(2, num3, MOD) + MOD - 1) % MOD;

        //右下
        ll num4 = after.getSum(0, p.y);
        ll pat4 = (MODpow(2, num4, MOD) + MOD - 1) % MOD;

        //自分を含む
        (ans += MODpow(2, N - 1, MOD)) %= MOD;

        //自分を含まない
        (ans += pat1 * pat3 % MOD * MODpow(2, num2 + num4, MOD) % MOD) %= MOD;
        (ans += pat2 * pat4 % MOD * MODpow(2, num1 + num3, MOD) % MOD) %= MOD;

        //重複を除く
        (ans += MOD - pat1 * pat2 % MOD * pat3 % MOD * pat4 % MOD) %= MOD;

        //更新
        before.update(p.y, 1);
        after.update(p.y, -1);
    }

    cout << ans << endl;
}

