    }

    IntegerIterator &operator++() {
        ++value;
        return *this;
    }

    IntegerIterator operator++(int) {
        IntegerIterator copy = *this;
        ++value;
        return copy;
    }

    IntegerIterator &operator--() {
        --value;
        return *this;
    }

    IntegerIterator operator--(int) {
        IntegerIterator copy = *this;
        --value;
        return copy;
    }

    T operator*() const {
