struct custom_hash {
    static uint64_t splitmix64(uint64_t x) {
        // http://xorshift.di.unimi.it/splitmix64.c
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    size_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = std::chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(x + FIXED_RANDOM);
    }
};


using namespace std;

class FEnclosedPoints {
    const int MOD = 998244353;

    void compress(vector<int> &A) {
        vector<int> B = A;
        sort(B.begin(), B.end());
        B.resize(unique(B.begin(), B.end()) - B.begin());
        for (int &x: A) {
            x = upper_bound(B.begin(), B.end(), x) - B.begin();
        }
    }

    template<typename T>
    struct Fenwick_Tree {
        vector<T> trees;
        vector<int> coords;

        Fenwick_Tree() {}

        inline unsigned int compress(int const &coord) {
            return upper_bound(coords.begin(), coords.end(), coord) - coords.begin();
        }

        inline void fake_update(int const &pos) {
            coords.push_back(pos);
        }

        inline void compile() {
            sort(coords.begin(), coords.end());
            coords.erase(unique(coords.begin(), coords.end()), coords.end());
            trees.resize(coords.size());
        }

        inline T q(int const &pos) {
            T ret = T();
            for (unsigned int x = compress(pos); x; x -= (x & -x)) {
                ret += trees[x - 1];
            }
            return ret;
        }

        inline T qq(int const &l, int const &r) {
            return q(r) - q(l - 1);
        }

        inline void up(int const &pos, T const &val) {
            for (unsigned int x = compress(pos); x <= trees.size(); x += (x & -x)) {
                trees[x - 1] += val;
            }
        }
    };

    template<typename T>
    struct Fenwick_Tree_2D {
        vector<Fenwick_Tree<T>> trees;
        vector<int> coords;
        vector<pair<int, int>> ups;

        Fenwick_Tree_2D() {}

        inline unsigned int compress(int const &coord) {
            return upper_bound(coords.begin(), coords.end(), coord) - coords.begin();
        }

        inline void fake_update(pair<int, int> const &pos) {
            coords.push_back(pos.first);
            ups.push_back(pos);
        }

        inline void compile() {
            sort(coords.begin(), coords.end());
            coords.erase(unique(coords.begin(), coords.end()), coords.end());
            trees.resize(coords.size());
            for (auto &e:ups) {
                for (unsigned int x = compress(e.first); x <= trees.size(); x += x & (-x)) {
                    trees[x - 1].fake_update(e.second);
                }
            }
            ups.clear();
            for (auto &e:trees) e.compile();
        }

        inline T q(pair<int, int> const &pos) {
            T ret = T();
            int newpos = pos.second;
            for (unsigned int x = compress(pos.first); x; x -= (x & -x)) {
                ret += trees[x - 1].q(newpos);
            }
            return ret;
        }

        inline void up(pair<int, int> const &pos, T const &val) {
            int newpos = pos.second;
            for (unsigned int x = compress(pos.first); x <= trees.size(); x += (x & -x)) {
                trees[x - 1].up(newpos, val);
            }
        }
    };

    int nx, ny;
//    vector<unordered_map<int, int, custom_hash>> bit;

//    void update(int x, int y) {
