//        int res = 0;
//        for (; x; x -= x & (-x)) {
//            for (int y2 = y; y2; y2 -= y2 & (-y2)) {
//                if (bit[x].count(y2)) {
//                    res += bit[x][y2];
//                }
//            }
//        }
//        return res;
//    }

    Fenwick_Tree_2D<int> ft;

    int query(int x1, int y1, int x2, int y2) {
        return ft.q({x2, y2}) - ft.q({x1 - 1, y2}) - ft.q({x2, y1 - 1}) + ft.q({x1 - 1, y1 - 1});
    }

public:
    void solve(std::istream &in, std::ostream &out) {
        int n;
        in >> n;
        vector<int> X(n), Y(n), P2(n + 1);
        P2[0] = 1;
        for (int i: range(n)) {
            in >> X[i] >> Y[i];
            P2[i + 1] = 2 * P2[i] % MOD;
        }
        compress(X);
        compress(Y);
        nx = *max_element(X.begin(), X.end()) + 1;
        ny = *max_element(Y.begin(), Y.end()) + 1;
        int mx = nx - 1, my = ny - 1;
        for (int i: range(n)) {
            ft.fake_update({X[i], Y[i]});
        }
        ft.compile();
        for (int i: range(n)) {
            ft.up({X[i], Y[i]}, 1);
        }
        long long res = 0;
        for (int i: range(n)) {
            res += P2[query(1, 1, mx, my)];
            res -= P2[query(1, 1, X[i] - 1, my)];
            res -= P2[query(X[i] + 1, 1, mx, my)];
            res -= P2[query(1, 1, mx, Y[i] - 1)];
            res -= P2[query(1, Y[i] + 1, mx, my)];
            res += P2[query(1, 1, X[i] - 1, Y[i] - 1)];
            res += P2[query(X[i] + 1, 1, mx, Y[i] - 1)];
            res += P2[query(1, Y[i] + 1, X[i] - 1, my)];
            res += P2[query(X[i] + 1, Y[i] + 1, mx, my)];
            res--;
        }
        res = (res % MOD + MOD) % MOD;
        out << res << "\n";
    }

    void setup() {}
};


