	SegmentTree<ll> segleft(N, addlambda, 0LL);
	SegmentTree<ll> segright(N, addlambda, 0LL);
	rep(i,N){
		segright.set(i,1);
	}
	segright.build();

	debug(xy);

	Modint ans=Modint(2).pow(N-1)*N;
	debug(ans);
	rep(i,N){
		//ll cx=compx.get(xy[i].first);
		ll cy=compy.get(xy[i].second);
		Modint a=segleft.query(cy+1,N);
		Modint b=segleft.query(0,cy);
		Modint c=segright.query(cy+1,N);
		Modint d=segright.query(0,cy);
		Modint ad=(Modint(2).pow(a)-1)*(Modint(2).pow(d)-1)*Modint(2).pow(N-a-d-1);
		Modint bc=(Modint(2).pow(b)-1)*(Modint(2).pow(c)-1)*Modint(2).pow(N-b-c-1);
		Modint abcd=(Modint(2).pow(a)-1)*(Modint(2).pow(b)-1)*(Modint(2).pow(c)-1)*(Modint(2).pow(d)-1);
		Modint t=ad+bc-abcd;
		ans+=t;

		segright.update(cy,0);
		segleft.update(cy,1);
		debug(cy,a,b,c,d,ad,bc,abcd,t);
	}

	p(ans);
}

