  seg.init(n);
  FOR(i, 0, n){
    int j = lower_bound(z, z+n, p[i].se)-z;
    DL[i] = seg.query(0, j);
    UL[i] = i-DL[i];
    seg.update(j, 1);
  }
  seg.init(n);
  FORR(i, n-1, 0){
    int j = lower_bound(z, z+n, p[i].se)-z;
    DR[i] = seg.query(0, j);
    UR[i] = n-1-i-DR[i];
    seg.update(j, 1);
  }
  ll ans = modPow(2, n, MOD)*n%MOD-n;
  FOR(i, 0, n){
    ll ul = modPow(2, UL[i], MOD);
    ll dl = modPow(2, DL[i], MOD);
    ll ur = modPow(2, UR[i], MOD);
    ll dr = modPow(2, DR[i], MOD);
    ans += ul+dl+ur+dr - (ul*ur+dl*dr+ul*dl+ur*dr) % MOD;
  }
  cout << (ans%MOD+MOD)%MOD << endl;
}

