const int MOD = 998244353;

const int M = 1 << 20;
int seg[M * 2 - 1];

void init() {    
    for(int i = 0; i < M * 2 - 1; i++) seg[i] = 0;
}

void add(int p, int k, int l, int r) {
    if(r - l == 1) seg[k] += 1;
    else {
        int m = (l + r) / 2;
        if(p < m) add(p, k * 2 + 1, l, m);
        else add(p, k * 2 + 2, m, r);
        seg[k] = seg[k * 2 + 1] + seg[k * 2 + 2];
    }
}

int sum(int a, int b, int k, int l, int r) {
    if(a <= l && r <= b) return seg[k];
    else {
        int m = (l + r) / 2;
        int s = 0;
        if (a < m) s += sum(a, b, k * 2 + 1, l, m);
        if (m < b) s += sum(a, b, k * 2 + 2, m, r);
        return s;
    }
}

P p[200000];
vector<int> xcomp;
vector<int> ycomp;

long long LU[200000];
long long LD[200000];
long long RU[200000];
long long RD[200000];

long long pow[200001];

int main() {
    int n, i;
    scanf("%d", &n);

    xcomp.clear();
    ycomp.clear();
    for(int i = 0; i < n; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        p[i] = P(x, y);
        xcomp.push_back(x);
        ycomp.push_back(y);
    }

    sort(xcomp.begin(), xcomp.end());
    sort(ycomp.begin(), ycomp.end());
    for(int i = 0; i < n; i++) {
        p[i] = P(
            lower_bound(xcomp.begin(), xcomp.end(), p[i].first) - xcomp.begin(),
            lower_bound(ycomp.begin(), ycomp.end(), p[i].second) - ycomp.begin()
        );
    }

    init();
    sort(p, p + n);
    for(int i = 0; i < n; i++) {
        int y = p[i].second;
        LU[i] = sum(0, y, 0, 0, M);
        LD[i] = sum(y, M, 0, 0, M);
        add(y, 0, 0, M);
    }

    init();
    for(int i = n - 1; i >= 0; i--) {
        int y = p[i].second;
        RU[i] = sum(0, y, 0, 0, M);
        RD[i] = sum(y, M, 0, 0, M);
        add(y, 0, 0, M);
    }

    pow[0] = 0;
    for(int i = 1; i <= n; i++) pow[i] = (pow[i - 1] * 2 + 1) % MOD;

    long long ans = (n * pow[n]) % MOD;
    for(int i = 0; i < n; i++) {
        ans -= pow[LU[i] + RU[i]] + pow[RU[i] + RD[i]]
                + pow[RD[i] + LD[i]] + pow[LD[i] + LU[i]];
        ans += pow[LU[i]] + pow[RU[i]] + pow[RD[i]] + pow[LD[i]];
        ans %= MOD;
    }

    printf("%lld\n", (ans + MOD) % MOD);
    return 0;
}

