        vector<T> trees;
        vector<int> coords;

        Fenwick_Tree() {}

        inline unsigned int compress(int const &coord) {
            return upper_bound(coords.begin(), coords.end(), coord) - coords.begin();
        }

        inline void fake_update(int const &pos) {
            coords.push_back(pos);
        }

        inline void compile() {
            sort(coords.begin(), coords.end());
            coords.erase(unique(coords.begin(), coords.end()), coords.end());
            trees.resize(coords.size());
        }

        inline T q(int const &pos) {
            T ret = T();
            for (unsigned int x = compress(pos); x; x -= (x & -x)) {
                ret += trees[x - 1];
            }
            return ret;
        }

        inline T qq(int const &l, int const &r) {
            return q(r) - q(l - 1);
        }

        inline void up(int const &pos, T const &val) {
            for (unsigned int x = compress(pos); x <= trees.size(); x += (x & -x)) {
                trees[x - 1] += val;
            }
        }
