template<typename T>
struct segtree{
	int n;
	vector<T> dat;
	T ZERO;
	function<T(T,T)> func;//要素と要素をマージする関数

	segtree(int n_, function<T(T,T)> func_, T zero):func(func_), ZERO(zero){
	  n = 1;
	  while(n < n_)n*=2;
	  dat.resize(2*n);
	  for(int i = 0;i < 2*n;i++)dat[i] = ZERO;
	}

	void update(int k, T a){
	  k += n - 1;dat[k] = a;
	  while(k > 0){
		k = (k-1)/2;
		dat[k] = func(dat[k*2+1],dat[k*2+2]);
	  }
	}

	void set(int k, T a) {
		k += n - 1;dat[k] = a;
	}

	void build(){
		for(int i = n - 2;i >= 0;i--){
			dat[i] = func(dat[2 * i + 1], dat[2 * i + 2]);
		}
	}

	T get(int k){return dat[k+n-1];}

	T que(int a,int b){
		T L = ZERO,R = ZERO;
		int A = a + n - 1;
		int B = b + n - 1;
		while(A < B){
			if((A & 1) == 0)L = func(L,dat[A++]);
            if((B & 1) == 0)R = func(dat[--B],R);
            A = A >> 1;
            B = B >> 1;
		}
		return func(L,R);
	}
};

void compression(vector<P> &v){
	int n = v.size();
	vector<ll> x(n);
	vector<ll> y(n);
	REP(i, n) {
		x[i] = v[i].FI;
		y[i] = v[i].SE;
	}

	sort(ALL(x));
	sort(ALL(y));
	x.erase(unique(ALL(x)), x.end());
	x.erase(unique(ALL(y)), y.end());

	REP(i, n){
		v[i].FI = lower_bound(ALL(x), v[i].FI) - x.begin();
		v[i].SE = lower_bound(ALL(y), v[i].SE) - y.begin();
	}
}

ll twoPow[222222];

int main(){
	cin.tie(0);cout.tie(0);ios::sync_with_stdio(false);

	twoPow[0] = 1;
	REP(i, 222222 - 1)twoPow[i+1] = twoPow[i] * 2 % MOD;

	int n;cin >> n;
	vector<P> v(n);
	REP(i, n)cin >> v[i].FI >> v[i].SE;
	compression(v);

	segtree<ll> seg(n, [](ll a, ll b){return a + b;}, 0);

	sort(ALL(v));

	ll ans = twoPow[n-1] * n % MOD;
	REP(i, n){
		ll xy = seg.que(0, v[i].SE);
		ll Xy = v[i].SE - xy;
		ll xY = seg.que(v[i].SE, n);
		ll XY = (n - v[i].SE - 1) - xY;
		REP(j, (1 << 4)){
			ll tmp = 1;
			if(j & (1 << 0))tmp = (tmp * (twoPow[xy] + MOD - 1)) % MOD;
			if(j & (1 << 1))tmp = (tmp * (twoPow[Xy] + MOD - 1)) % MOD;
			if(j & (1 << 2))tmp = (tmp * (twoPow[xY] + MOD - 1)) % MOD;
			if(j & (1 << 3))tmp = (tmp * (twoPow[XY] + MOD - 1)) % MOD;
			if(((j & 9) == 9) || ((j & 6) == 6)){
				ans = (ans + tmp) % MOD;
			}
		}

		seg.update(v[i].SE, 1);
	}

	cout << ans << endl;

	return 0;
}

