int query(int index)
{
	int res = 0;
	for (; index > 0; index -= index & -index)
		res += bit[index];
	return res;
}
void update(int index)
{
	for (; index <= y.size(); index += index & -index)
		++bit[index];
}
ll modpow(ll power)
{
	ll base = 2, res = 1;
	while (power) {
		if (power & 1)
			res = res * base % mod;
		base = base * base % mod;
		power /= 2;
	}
	return res;
}
