template <typename T>
struct BIT {
    vector<T> bit;
    // 単位元
    const T neutral = 0;
    // 要素数
    int n;
    BIT(int n_ = 1e5) { init(n_); }
    void init(int sz) { 
        n=1; while(n < sz) n*=2;
        bit.assign(n+1, neutral); 
    }
    void update(int i, T w) {
        for(int x=i+1; x<bit.size(); x += x&-x) bit[x] += w;
    }
    // [0,i]
    T query(int i) {
        T ret = neutral;
        for(int x=i+1; x>0; x -= x&-x) ret += bit[x];
        return ret;
    }
    // 合計がw以上の最小の位置
    int lower_bound(T w) {
        int x = 0;
        for(int k=n; k>0; k>>=1) {
            if(x+k <= n && bit[x+k] < w) {
                w -= bit[x+k];
                x += k;
            }
        }
        return x;
    }
};

int main(void) {
    ll n;
    cin >> n;
    vector<ll> x(n), y(n);
    REP(i, n) cin >> x[i] >> y[i];

    vector<ll> xs(x), ys(y);
    sort(ALL(xs)); xs.erase(unique(ALL(xs)), xs.end());
    sort(ALL(ys)); ys.erase(unique(ALL(ys)), ys.end());
    REP(i, n) {
        x[i] = lower_bound(ALL(xs), x[i]) - xs.begin();
        y[i] = lower_bound(ALL(ys), y[i]) - ys.begin();
    }

    vector<vector<PII>> xy(n), yx(n);
    REP(i, n) {
        xy[x[i]].emplace_back(y[i], i);
        yx[y[i]].emplace_back(x[i], i);
    }

    vector<ll> l(n), r(n), u(n), d(n);
    ll cnt = 0;
    REP(i, n) {
        cnt += xy[i].size();
        for(auto j: xy[i]) l[j.second] = cnt;
    }
    cnt = 0;
    REP(i, n) {
        cnt += yx[i].size();
        for(auto j: yx[i]) d[j.second] = cnt;
    }
    cnt = 0;
    for(ll i=n-1; i>=0; --i) {
        cnt += xy[i].size();
        for(auto j: xy[i]) r[j.second] = cnt;
    }
    cnt = 0;
    for(ll i=n-1; i>=0; --i) {
        cnt += yx[i].size();
        for(auto j: yx[i]) u[j.second] = cnt;
    }

    vector<ll> lu(n), ld(n), ru(n), rd(n);
    BIT<ll> bit(n);
    REP(i, n) {
        for(auto j: xy[i]) bit.update(j.first, 1);
        for(auto j: xy[i]) {
            ld[j.second] = bit.query(j.first);
            lu[j.second] = bit.query(n-1) - (j.first==0?0:bit.query(j.first-1));
        }
    }
    bit.init(n);
    for(ll i=n-1; i>=0; --i) {
        for(auto j: xy[i]) bit.update(j.first, 1);
        for(auto j: xy[i]) {
            rd[j.second] = bit.query(j.first);
            ru[j.second] = bit.query(n-1) - (j.first==0?0:bit.query(j.first-1));
        }
    }

    mint ans = 0;
    REP(i, n) {
        mint ret = mint(2).pow(n) - 1;
        ret -= mint(2).pow(l[i]-1) + mint(2).pow(r[i]-1) + mint(2).pow(u[i]-1) + mint(2).pow(d[i]-1);
        ret += mint(2).pow(lu[i]-1) + mint(2).pow(ld[i]-1) + mint(2).pow(ru[i]-1) + mint(2).pow(rd[i]-1);
        ans += ret;
    }
    cout << ans << endl;

    return 0;
}

