ll MOD = 998244353;

// g = eGCD(a, b, s, t)  --->  sa + tb = g
constexpr ll eGCD(ll a, ll b, ll& s, ll& t) {
  if (a == 0) {
    s = 0;
    t = 1;
    return b;
  }
  ll u = 0;
  ll g = eGCD(b % a, a, t, u);
  s = u - (b / a) * t;
  return g;
}

constexpr ll gcd(ll a, ll b) {
  ll dummy1 = 0;
  ll dummy2 = 0;
  return eGCD(a, b, dummy1, dummy2);
}

struct Fp {
  ll val;

  Fp(ll t = 0) :
    val(t < 0 ? MOD + t % MOD : t >= MOD ? t % MOD : t) {}

  Fp& operator +=(const Fp& t) {
    val += t.val;
    if (val >= MOD) val -= MOD;
    return *this;
  }

  Fp& operator -=(const Fp& t) {
    val -= t.val;
    if (val < 0) val += MOD;
    return *this;
  }

  Fp& operator *=(const Fp& t) {
    val = (val * t.val) % MOD;
    return *this;
  }

  Fp inv() const {
    if (val == 0) {
      cerr << "inv() is called for zero." << endl;
      exit(1);
    }
    ll u = 0;
    ll v = 0;
    eGCD(val, MOD, u, v);
    return Fp(u);
  }

  Fp& operator /=(const Fp& t) {
    return (*this) *= t.inv();
  }

  Fp operator +(const Fp& t) const { return Fp(val) += t; }
  Fp operator -(const Fp& t) const { return Fp(val) -= t; }
  Fp operator *(const Fp& t) const { return Fp(val) *= t; }
  Fp operator /(const Fp& t) const { return Fp(val) /= t; }
  Fp operator -() const { return Fp(-val); }

  bool operator ==(const Fp& t) const { return val == t.val; }
  bool operator !=(const Fp& t) const { return val != t.val; }

  operator ll() const { return val; }

};

template <class T>
class BIT {
  int size; // the number of slots
  vector<T> vec; // from 1 to size

public:

  BIT(int s) : size(s), vec(s+1) {}

  void add(int i, T x) {
    while (i <= size) {
      vec.at(i) += x;
      i += (i & (-i));
    }
  }

  T sum(int i) {
    T res = (T)0;
    while (i >= 1) {
      res += vec.at(i);
      i -= (i & (-i));
    }
    return res;
  }

};

template <class T>
void coordCompress(vector<T>& x) {
  int n = x.size();
  vector<T> ord(n);
  iota(ord.begin(), ord.end(), 0);
  sort(ord.begin(), ord.end(),
       [&](int p, int q) { return x.at(p) < x.at(q); });
  T value = 0;
  for (int i = 0; i < n; i++) {
    T nextValue = (i+1 < n && x.at(ord.at(i)) != x.at(ord.at(i+1)))
                  ? value + 1 : value;
    x.at(ord.at(i)) = value;
    value = nextValue;
  }
}

vector<Fp> pow2;
void fillPow(int N) {
  pow2.resize(N+1);
  pow2.at(0) = 1;
  for (int i = 1; i <= N; i++) {
    pow2.at(i) = pow2.at(i-1) * (Fp)2;
  }
}
Fp pow(int n) { return pow2.at(n); }

