	BIT() {}
	void init(int n) {
		size = n;
		for (int i = 1; i <= n; i++) dat[i] = 0;
	}
	void add(int i, int x) {
		i++;
		while (i <= size) {
			dat[i] += x;
			i += i & -i;
		}
	}//0-indexed
	int query(int i) {
		i++;
		int sum = 0;
		while (i > 0) {
			sum += dat[i];
			i -= i & -i;
		}
		return sum;
	}//0-indexed
};//size, 0-indexed
