/// kD-tree
// k次元空間に散らばるn個の点について、range(...)に含む点のリストをqueryできる。
// 3次元整数格子点を考えるのであれば、KDTree<int,3> を使う。
template <class T, size_t K>
struct KDTree
{
	typedef array<T, K> PT;
	vector<PT> p_;
	vector<int> tree_{};

	static constexpr unsigned int msb(unsigned int v) { REP(i, 5) v |= v >> (1 << i); return (v >> 1) + 1; }
	KDTree(int n) : p_(n), tree_(msb(p_.size()) << 1, -1) { }

	PT& operator [] (int index) { return p_[index]; }

	void build()
	{
		vector<int> work(p_.size());
		iota(allof(work), 0);
		build_internal(work, 0, 1, 0, work.size());
	}

	int range(PT s, PT e)
	{
		int ret = 0;
		range_internal(ret, s, e, 0, 1, 0, p_.size());
		return ret;
	}

private:
	void build_internal(vector<int>& w, int depth, int i, int l, int r)
	{
		if (r - l == 0) { return; }

		int d = depth % K;
		int m = (r - l - 1) / 2 + l;
		nth_element(w.begin() + l, w.begin() + m, w.begin() + r, COMP(a, b, p_[a][d] < p_[b][d]));
		tree_[i] = w[m];
		build_internal(w, depth + 1, i * 2, l, m);
		build_internal(w, depth + 1, i * 2 + 1, m + 1, r);
	}

	void range_internal(int& ret, PT s, PT e, int depth, int i, int l, int r)
	{
		if (r - l == 0) { return; }

		PT p = p_[tree_[i]];
		bool inRange = true;
		REP(i, K) { inRange &= p[i] >= s[i] && p[i] < e[i]; }
		if (inRange) { ret++; }

		int d = depth % K;
		int m = (r - l - 1) / 2 + l;
		if (p[d] >= s[d]) { range_internal(ret, s, e, depth + 1, i * 2, l, m); }
		if (p[d] < e[d]) { range_internal(ret, s, e, depth + 1, i * 2 + 1, m + 1, r); }
	}
};

/// 座圧 座標圧縮
template <class T>
struct CoordinateCompression
{
	map<T, int> comp{};
	vector<T> decomp{};
	vector<T> init(const vector<T>& orig)
	{
		decomp = orig;
		//decomp.push_back(numeric_limits<T>::min());
		//decomp.push_back(numeric_limits<T>::max());
		sort(allof(decomp));
		decomp.erase(unique(allof(decomp)), decomp.end());
		REP(i, decomp.size()) { comp[decomp[i]] = i; }
		vector<T> ret(orig.size());
		REP(i, orig.size()) { ret[i] = comp[orig[i]]; }
		return ret;
	}
	size_t size() { return decomp.size(); }
	T operator[](int x) { return decomp[x]; } ///< 圧縮後の値xはもともと何の値だったのか？
};
template <class T>
struct CoordinateCompression2D
{
	CoordinateCompression<T> Xs, Ys;

	template <class P>
	vector<P> init(const vector<P>& orig)
	{
		size_t N = orig.size();
		vector<T> x(N); REP(i, N) { x[i] = orig[i].x; } x = Xs.init(x);
		vector<T> y(N); REP(i, N) { y[i] = orig[i].y; } y = Ys.init(y);
		vector<P> ret(N); REP(i, N) { ret[i] = { x[i], y[i] }; }
		return ret;
	}
	struct size2D { size_t x, y; };
	size2D size() { return { Xs.size(), Ys.size() }; }

	template <class P>
	P operator[](P p) { return { Xs[p.x], Ys[p.y] }; }
};

struct P
{
	int x, y;
};


// modを法としたxのy乗を求める。(繰り返し二乗法)
inline llong modPow(llong x, llong y, llong mod)
{
	llong r = 1;
	for (; y > 0; y >>= 1)
	{
		if (y & 1) { r = r * x % mod; }
		x = x * x % mod;
	}
	return r;
}

