void solve()
{
	READ(int, N);

	std::vector<P> Ps;
	REP(i, N)
	{
		READ(int, x, y);
		Ps.push_back({ x,y });
	}
	Ps = CoordinateCompression2D<int>().init(Ps);
	KDTree<int, 2> kDTree(N);
	REP(i,N)
	{
		kDTree[i] = { Ps[i].x, Ps[i].y };
	}
	kDTree.build();

	const llong mod = 998244353;

	llong ans = 0;
	REP(i, N)
	{
		P p = Ps[i];

		llong lt = kDTree.range({ 0,       0       }, { p.x,      p.y });
		llong rt = kDTree.range({ p.x + 1, 0       }, { INF(int), p.y });
		llong lb = kDTree.range({ 0,       p.y + 1 }, { p.x,      INF(int) });
		llong rb = kDTree.range({ p.x + 1, p.y + 1 }, { INF(int), INF(int) });

		llong a = 0;
		a += modPow(2, lt + rt, mod) - 1;
		a += modPow(2, rt + rb, mod) - 1;
		a += modPow(2, rb + lb, mod) - 1;
		a += modPow(2, lb + lt, mod) - 1;
		a -= modPow(2, lt, mod) - 1;
		a -= modPow(2, rt, mod) - 1;
		a -= modPow(2, rb, mod) - 1;
		a -= modPow(2, lb, mod) - 1;
		a = (a + mod) % mod;

		a = (modPow(2, N, mod) - 1) - a;

		ans += a;
		ans %= mod;
	}
	WRITE(ans);

}

