struct BIT0{
    vector<int> data;
    BIT0(int n): data(n + 1){ }
    void add(int idx, int num){
        // idx = max(0, min((int)data.size() - 1, idx));
        idx++;
        for(; idx < (int)data.size(); idx += idx & -idx){
            data[idx] += num;
        }
    }
    int sum(int idx){
        // idx = max(0, min((int)data.size() - 1, idx));
        idx++;
        int ret = 0;
        for(; idx; idx -= idx & -idx){
            ret += data[idx];
        }
        return ret;
    }
};

