    for(int i=0; i<n; ++i)
    {
        a[xs[i].second].first = i;
        a[ys[i].second].second = i;
    }

    sort(a.begin(), a.end());
    int ans=0;
    vector<int>fwd(n, 0), bwd(n, 0);
    BIT *ft = new BIT(n);
    for(int i=n-1; i>=0; --i)
    {
        fwd[i] = ft->sum(a[i].second, n - 1);
        ft->add(1, a[i].second);
    }
    ft = new BIT(n);
    for(int i=0; i<n; ++i)
    {
        bwd[i] = ft->sum(0, a[i].second);
        ft->add(1, a[i].second);
    }
    for(int i=0; i<n; ++i)
    {
        int ne=powr(2, fwd[i])-1;
        int nw=powr(2, i-bwd[i])-1;
        int se=powr(2, n-1-i-fwd[i])-1;
        int sw=powr(2, bwd[i])-1;
        // cout<<ne<<' '<<nw<<" "<<se<<" "<<sw<<"\n";
        int tmp = (ne*sw)%mod;
        tmp = (tmp + (nw * se) % mod) % mod;
        tmp = (tmp + (se * (nw * sw) % mod) % mod) % mod;
        tmp = (tmp + (se * (ne * sw) % mod) % mod) % mod;
        tmp = (tmp + (ne * (sw * nw) % mod) % mod) % mod;
        tmp = (tmp + (ne * (se * nw) % mod) % mod) % mod;
        tmp = (tmp + ((ne * nw) % mod) * ((se * sw) % mod) % mod) % mod;
        tmp = (2*tmp)%mod;
        tmp = (tmp + (ne + nw)%mod)%mod;
        tmp = (tmp + (se + sw)%mod)%mod;

        tmp = (tmp + (ne * nw) % mod) % mod;
        tmp = (tmp + (nw * sw) % mod) % mod;
        tmp = (tmp + (sw * se) % mod) % mod;
        tmp = (tmp + (se * ne) % mod) % mod;

        tmp = (tmp + 1)%mod;
        ans=(ans+tmp)%mod;
        // cout<<tmp<<"\n";
    }
    ans=(ans+mod)%mod;
    cout<<ans;
}

