    rep(i, ps.size()){
        cnt[i][2] = bit1.query(ps[i].y - 1);
        cnt[i][1] = mint(i) - cnt[i][2];
        bit1.update(ps[i].y, 1);

        cnt[n - i - 1][3] = bit2.query(ps[n - 1 - i].y - 1);
        cnt[n - i - 1][0] = mint(i) - cnt[n - 1 - i][3];
        bit2.update(ps[n - i - 1].y, 1);
    }

    mint answer = 0;
    rep(i, n)
        answer += func(cnt[i]);

    prl(answer);
}

