/**
 *  mod による操作ライブラリ
 */
#define ANS_MOD (998244353LL)
const SQWORD mod = ANS_MOD;
struct mint {
    SQWORD x;
    mint(SQWORD x=0) : x((x % mod + mod) % mod) {}
    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-= (const mint a) {
        x += (mod - a.x);
        if (x >= mod) {
            x -= mod;
        }
        return *this;
    }
    mint& operator*= (const mint a) {
        (x *= a.x);
        x %= mod;
        return *this;
    }
    mint operator+ (const mint a) const {
        mint res(*this);
        return (res+=a);
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return (res-=a);
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return (res*=a);
    }
    mint pow(SQWORD t) const {
        if (0 == t) {
            return 1;
        }
        mint a = pow(t>>1);
        a *= a;
        if (t & 1) {
            a *= *this;
        }
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod-2);
    }
    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
};

