	vector<ll> twos(5*1e5); twos[0] = 1LL;
	for(ll i = 1; i < sz(twos); i++) (twos[i] = twos[i - 1] * 2) %= P;

	ll n; cin >> n;
	vector<pair<ll, ll> > p(n);
	for(ll i = 0; i < n; i++) {
