	}
	sort(all(p));
	for(ll i = 0; i < n; i++) {
		swap(p[i].first, p[i].second);
		p[i].second = i;
	}
	sort(all(p));

	ll res = 0;
	ordered_set X;
	for(ll i = 0; i < n; i++) {
		X.insert(p[i].second);
		ll lb = X.order_of_key(p[i].second);
		ll l = p[i].second, b = p[i].first;
		ll r = n - l - 1, u = n - b - 1;
		ll rb = b - lb, ru = r - rb, lu = l - lb;
