		((cur -= twos[lu]) += P) %= P;
		((cur -= twos[ru]) += P) %= P;
		((cur -= twos[rb]) += P) %= P;
		((cur -= twos[lb]) += P) %= P;
		(res += twos[n] - cur - 1) %= P;
	}
	cout << res << endl;
}

