// K-Dimensional Tree
template<typename T, typename Point = std::vector<T>> class KDTree {
 public:
  KDTree(int K, std::vector<Point> P) : K(K), ROOT(build(P, 0, P.size(), 0)) {
    // 個数用
    Point l(K), h(K);
    for(auto k=0; k<K; ++k) l[k] = (*std::min_element(begin(P), end(P), Compare(k)))[k];
    for(auto k=0; k<K; ++k) h[k] = (*std::max_element(begin(P), end(P), Compare(k)))[k];
    std::function<void(const std::unique_ptr<Node>&, Point, Point, int)> dfs = [&](const auto& n, auto l, auto h, auto k) {
      n->low=l; n->high=h; n->size=1;
      auto nl=l, nh=h; auto nk=(k+1)%K;
      if(n->lchild) {nh[nk]=n->lchild->point[nk]; dfs(n->lchild,nl,h,nk); n->size+=n->lchild->size;}
      if(n->rchild) {nl[nk]=n->rchild->point[nk]; dfs(n->rchild,l,nh,nk); n->size+=n->rchild->size;}
    };
    dfs(ROOT, l, h, 0);
  }
  int query(const Point& a, const Point& b) const {return query(a, b, ROOT, 0);}
 private:
  struct Node {
    Point point;
    std::unique_ptr<Node> lchild, rchild;
    // 個数用
    int size; Point low, high;
  };
  struct Compare {
    Compare(int k) : k(k) {}
    bool operator()(const Point& lhs, const Point& rhs) const {return lhs[k] < rhs[k];}
    int k;
  };
  std::unique_ptr<Node> build(std::vector<Point>& P, int l, int h, int k) const {
    if(!(l < h)) return nullptr;
    auto m = (l + h) / 2;
    std::sort(begin(P)+l, begin(P)+h, Compare(k));
    auto res = std::make_unique<Node>();
    res->point  = P[m];
    res->lchild = build(P, l,   m, (k+1)%K);
    res->rchild = build(P, m+1, h, (k+1)%K);
    return res;
  };
  int query(const Point& a, const Point& b, const std::unique_ptr<Node>& n, int k) const {
    if(!n) return 0;
    // 個数用
    auto ok = true;
    for(auto k=0; k<K; ++k) if(Compare(k)(n->low,a) || Compare(k)(b,n->high)) ok = false;
    if(ok) return n->size;
    // 列挙用
    auto res = 1;
    for(auto k=0; k<K; ++k) if(Compare(k)(n->point,a) || Compare(k)(b,n->point)) res = 0;
    if(a[k] <= n->point[k]) res += query(a, b, n->lchild, (k+1)%K);
    if(n->point[k] <= b[k]) res += query(a, b, n->rchild, (k+1)%K);
    return res;
  }
  int K;
  std::unique_ptr<Node> ROOT;
};

using LL = long long;
const LL M = 998244353;

LL power(LL m, LL n) {
  if(!n) return 1;
  return (n & 1) ? (power(m, n - 1) * m % M) : power(m * m % M, n >> 1);
}

int main() {
  int N;
  cin >> N;
  vector<vector<int>> P(N, vector<int>(2));
  for(auto& i: P) cin >> i[0] >> i[1];

  KDTree<int> kdtree(2, P);

  LL ans = 0;
  const int INF = 1e9+1;
  for(const auto& p: P) {
    // T に含まれる場合
    ans += power(2, N-1);
    ans %= M;
    // T に含まれない場合
    LL ur = kdtree.query({p[0], -INF}, {INF, p[1]}) - 1;
    LL ll = kdtree.query({-INF, p[1]}, {p[0], INF}) - 1;
    LL ul = kdtree.query({-INF, -INF}, {p[0]-1, p[1]-1});
    LL lr = kdtree.query({p[0]+1, p[1]+1}, {INF, INF});
    LL urll = (power(2,ur)-1) * (power(2,ll)-1) % M;
    LL ullr = (power(2,ul)-1) * (power(2,lr)-1) % M;
    ans += urll * power(2,N-1-ur-ll) % M;
    ans %= M;
    ans += ullr * power(2,N-1-ul-lr) % M;
    ans %= M;
    assert(0<=N-1-ur-ll-ul-lr);
    ans += M - (urll * ullr % M) * power(2,N-1-ur-ll-ul-lr) % M;
    ans %= M;
  }
  cout << ans << endl;
}

