    for (int i=1; i<=n; i++) cin >> a[i], sum += a[i];
    for (int i=1; i<=2000000; i++){
        if (sum % i) continue;
        int s = 0, cnt = 0;
        for (int j=1; j<=n; j++) b[j] = a[j] % i;
        sort(b+1, b+1+n);
        int lol = s / i;
        for (int j=n; j && lol; j--, lol--) cnt += i - b[j];
        if (cnt <= k) ans = i;
    }
    cout << ans;
    return 0;
}

