// Binary Indexed Tree (Fenwick Tree)
// https://youtu.be/lyHk98daDJo?t=7960
template<typename T>
struct BIT {
	int n;
	vector<T> d;
	BIT(int n = 0) :n(n), d(n + 1) {}
	void add(int i, T x = 1) {
		for (i++; i <= n; i += i & -i) {
			d[i] += x;
		}
	}
	T sum(int i) {
		T x = 0;
		for (i++; i; i -= i & -i) {
			x += d[i];
		}
		return x;
	}
	T sum(int l, int r) {
		return sum(r - 1) - sum(l - 1);
	}
};
int main() {
	int N;
	cin >> N;
	vector<pair<int, int>>X(N);
	map<int, int>sx;
	map<int, int>sy;
	for (int i = 0; i < N; ++i) {
		cin >> X[i].first >> X[i].second;
		sx[X[i].first] = 0;
		sy[X[i].second] = 0;
	}
	int count = 0;
	for (auto s : sx) {
		sx[s.first] = count;
		count++;
	}
	count = 0;
	for (auto s : sy) {
		sy[s.first] = count;
		count++;
	}
	for (int i = 0; i < N; ++i) {
		X[i].first = sx[X[i].first];
		X[i].second = sy[X[i].second];
	}

	mint ans = 0;
	sort(X.begin(),X.end());
	BIT<int> bit_bef(N), bit_aft(N);
	for (int i = 0; i < N; i++) bit_aft.add(i, 1);
	for (int i = 0; i < N; i++) {
		bit_aft.add(X[i].second, -1);
		mint m0 = ((mint)2).pow(bit_bef.sum(X[i].second));
		mint m1 = ((mint)2).pow(i - bit_bef.sum(X[i].second));
		mint m2 = ((mint)2).pow(bit_aft.sum(X[i].second));
		mint m3 = ((mint)2).pow(N - i - 1 - bit_aft.sum(X[i].second));
		ans += (m0 - 1)*(m3 - 1)*m1*m2;
		ans += (m1 - 1)*(m2 - 1)*m0*m3;
		ans -= (m0 - 1)*(m3 - 1)*(m1 - 1)*(m2 - 1);
		ans += ((mint)2).pow(N - 1);
		bit_bef.add(X[i].second, 1);
	}
	cout << ans << endl;
	return 0;
}

