/**
 * http://hos.ac/slides/20140319_bit.pdf
 */
class BinaryIndexedTree {
 private:
  vector<ll> bit;
  ull size;

 public:
  explicit BinaryIndexedTree(ull size) : bit(size + 1, 0), size(size) {}

  /**
   * @param i
   * @param value
   */
  void add(ull i, ll value) {
    for (ull x = i; x < size; x |= x + 1) {
      bit[x] += value;
    }
  }

  /**
   * [0, i) の合計
   * @param i
   */
  ll sum(ull i) {
    ll ret = 0;
    for (ll x = i - 1; x >= 0; x = (x & (x + 1)) - 1) {
      ret += bit[x];
    }
    return ret;
  }
};

/**
 * values を 1 以上の整数に圧縮したベクタを生成する
 * @tparam T
 * @param values
 */
template<typename T>
vector<ll> compress(vector<T> &values) {
  vector<ll> ret(values.size());
  vector<pair<T, ull>> V(values.size());

  rep (i, values.size()) {
    V[i] = make_pair(values[i], i);
  }
  sort(V.begin(), V.end());

  ll cnt = 1;
  T prev = V[0].first;
  for (const auto &vi : V) {
    T v;
    ll i;
    tie(v, i) = vi;

    if (prev != v) cnt++;
    ret[i] = cnt;
    prev = v;
  }
  return ret;
}

/**
 * x ** y % mod
 * @param x
 * @param y
 * @param mod
 */
ll mod_pow(ll x, ll y, ll mod) {
  ll ret = 1;
  while (y > 0) {
    if (y & 1) {
      ret = ret * x % mod;
    }
    x = x * x % mod;
    y >>= 1;
  }
  return ret;
}

