    ll c = (pow2[LL[i]] - 1) * (pow2[GG[i]] - 1) % MOD * (pow2[LG[i]] - 1) % MOD * (pow2[GL[i]] - 1) % MOD;
    ans += r + a + b - c + MOD;
    ans %= MOD;
  }
  cout << ans << endl;
}

