template<class T, int MAX_N>
struct BIT {
  int N, K; T B[MAX_N];
  void init(int n) {N=n;REP(i,n)B[i]=0;for(K=1;(K<<1)<N;K<<=1);}
  void add(int x, T w) { for (; x<N; x|=x+1) B[x]+=w; }
  T sum(int a) const { T r=0; for (int x=a-1; x>=0; x=(x&(x+1))-1) r+=B[x]; return r; }
  T sum(int a, int b) const { return sum(b)-sum(a); }
  int lb(T w) { int x=0; for(int k=K; k; k>>=1) if (x+k<=N && B[x+k-1]<w) w-=B[x+k-1], x+=k; return x; }
  friend ostream& operator<<(ostream&o, const BIT<T, MAX_N> &bit) {  REP(i,bit.N) o << (i?",":"") << bit.sum(i, i+1); o << endl; return o; }
};

