int main() {
  int n;
  while (cin >> n) {
    vector<int> xs,ys;
    REP(i,n) {
      input(p[i].first,p[i].second);
      xs.push_back(p[i].first);
      ys.push_back(p[i].second);
    }
    sort(p,p+n);
    sort(ALL(xs));
    sort(ALL(ys));
    REP(i,n) {
      p[i].first = lower_bound(ALL(xs), p[i].first) - xs.begin();
      p[i].second = lower_bound(ALL(ys), p[i].second) - ys.begin();
    }
    bit.init(n);
    REP(i,n) {
      ld[i] = bit.sum(p[i].second);
      lu[i] = i - ld[i];
      bit.add(p[i].second, 1);
    }
    bit.init(n);
    REPR(i,n) {
      rd[i] = bit.sum(p[i].second);
      ru[i] = (n-i-1) - rd[i];
      bit.add(p[i].second, 1);
    }
    // REP(i,n) {
