      mint b = two.pow(ld[i]+ru[i]) - (two.pow(ld[i]) - 1) * (two.pow(ru[i]) - 1);
      mint a2 = (two.pow(lu[i]) - 1) * (two.pow(rd[i]) - 1) * b;
      mint a3 = two.pow(n-1);
      ans += a1 + a2 + a3;
    }
