// 10^5 * 10^5 になるから 2 次元 BIT は無理
// 右上, 右下, 左上, 左下の個数が欲しい
// 左は, x 昇順でわかる

struct BIT { // 0 indexed
  int n;
  vector<ll> bit;
  BIT(int n) : n(n) { bit.resize(n); }
  BIT(vector<ll> v) {
    n = sz(v);
    bit.resize(n);
    rep(i, n) add(i, v[i]);
  }
  void add(int a, ll w) { for (int x = a; x < n; x |= x + 1) bit[x] += w; }
  ll sum(int a) { // [0, a)
    ll ret = 0;
    for (int x = a - 1; x >= 0; x = (x & (x + 1)) - 1) ret += bit[x];
    return ret;
  }
  ll sum(int a, int b) { return sum(b) - sum(a); } // [a, b)
};

void solve() {
  int n;
