  // 上, 下, 左, 右各々だけの集合の個数
  // 左上, 左下, 右上, 右下だけの集合の個数が重複
  rep(i, n) {
    vector<int> v(4);
    int it = lb(x2, x[i]), it2 = lb(y2, y[i]);
    v[0] = it;
    v[1] = it2;
    rep(j, 2) v[2 + j] = n - 1 - v[j];
    rep(j, 4) (ans += modpow(2, v[j], mod)) %= mod;
    // cerr << i << " " << ans << endl;
  }
  // x 昇順, 左がわかる
  vector<pii> v(n);
  rep(i, n) v[i] = pii(x[i], y[i]);
  sort(all(v));

  rep(_, 2) {
    BIT bit(n); // y 
    rep(i, n) {
      int it = lb(y2, v[i].S);
      int tmp = bit.sum(it);
      (ans += mod - modpow(2, tmp, mod)) %= mod; // 1 周目は左下, 2 周目は右下
      (ans += mod - modpow(2, i - tmp, mod)) %= mod; // debuged
      bit.add(it, 1);
    }
    reverse(all(v));
  }
  cout << (n * (modpow(2, n, mod) + mod - 1) - ans + mod) % mod << endl;
}

