int main() {
    using namespace std;
    FastIn::Scanner in;
    unsigned long N;
    in.scan(N);
    vector<unsigned long> perm(N);
    {
        vector<pair<long, long>> p(N), q(N);
        for(auto& i : p)in.scan(i.first, i.second);
        rsort(p.begin(), p.end());
        for(unsigned long i = 0; i < N; ++i)q[i] = {p[i].second, i};
        rsort(q.begin(), q.end());
        transform(q.cbegin(), q.cend(), perm.begin(), [](auto i){return i.second;});
    }

    constexpr unsigned long MOD = 998244353;
    vector<unsigned long> binary(N + 1);
    binary[0] = 1;
    for(unsigned long i = 0; i != N; ++i)binary[i + 1] = binary[i] * 2 - (binary[i] > 499122176) * MOD;

    vector<unsigned long> fenwick_tree(N + 1);
    auto que = [&fenwick_tree, &N](unsigned long i){
        unsigned long r = i;
        unsigned long ret{fenwick_tree[i]};
        while(i &= i + 1)ret += fenwick_tree[--i];
        i = r;
        while(i < N){
            ++fenwick_tree[i];
            i |= i + 1;
        }
        return ret;
    };

    vector<unsigned long> coef(N + 1);
    coef[N] = N + MOD - 4;
    for(unsigned long i = 0; i != N; ++i){
        auto q = que(perm[i]);
        ++coef[q];
        ++coef[i - q];
        ++coef[perm[i] - q];
        ++coef[N - i - perm[i] + q - 1];
    }

    cout << inner_product(binary.begin(), binary.end(), coef.begin(), 4 + MOD - N) % MOD << endl;
    return 0;
}

