void to_unique(vector<int>& data) {
  sort(data.begin(), data.end());
  auto unique_end = unique(data.begin(), data.end());
  data.erase(unique_end, data.end());
}

int mod = 998244353;

int pow_mod(int a, int b, int mod) {
  int result = 1;
  int x = a;

  for (;b > 0;b /= 2) {
    if (b%2 == 1) {
      result = result * x % mod;
    }

    x = x * x % mod;
  }

  return result;
}

int main() {

  int n;
  cin >> n;
  vector<point> points(n);

  int x,y;
  for (int i = 0; i < n; i++) {
    cin >> x >> y;
    points[i] = {x, y, i};
  }

  // 長方形ごとに、取りうる部分集合を計算する
  // x,yの領域を計算するので、nC2 * nC2でo(n**4)の計算量

  vector<point> points_ordered_by_x(points);
  sort(points_ordered_by_x.begin(), points_ordered_by_x.end(), [](point a, point b){return a.x < b.x;});

  vector<point> points_ordered_by_y(points);
  sort(points_ordered_by_y.begin(), points_ordered_by_y.end(), [](point a, point b){return a.y < b.y;});

  int result = n; // 先に要素1の分足しとく
  for(int x_left = 0; x_left < n; x_left++) {
    for (int x_right = n-1; x_right > x_left; x_right--) {
      vector<point> ys;
      const auto& x_left_point = points_ordered_by_x[x_left];
      const auto& x_right_point = points_ordered_by_x[x_right];
      for (const auto& y : points_ordered_by_y) {
        if (x_left_point.x <= y.x && y.x <= x_right_point.x) {
          ys.push_back(y);
        }
      }

      for (int y_left = 0; y_left < ys.size() - 1; y_left++) {
        for (int y_right = ys.size() - 1; y_right > y_left; y_right--) {
          int points_count = y_right - y_left + 1;

          vector<int> outer_points {
            points_ordered_by_x[x_left].i, points_ordered_by_x[x_right].i,
            ys[y_left].i, ys[y_right].i
          };
          to_unique(outer_points);

          int inner_points_count = points_count - outer_points.size(); 

          // cout << x_left << " " << x_right << " " << y_left << " " << y_right << " " << inner_points_count << endl;

          // 長方形がこのサイズである部分集合は、内部点のon/offの組み合わせ数分だけ存在する
          // 1部分集合当たりの点数は同じなので
          result += pow_mod(2, inner_points_count, mod) * points_count % mod;

          // cout << result << endl;

          if (ys[y_right].i == points_ordered_by_x[x_left].i ||
              ys[y_right].i == points_ordered_by_x[x_right].i) {
            // y_rightがxの端である場合、進むとxの幅が変わってしまうので、これ以上は処理しない
            // cout << "y_right break" << endl;
            break;
          }
        }

        if (ys[y_left].i == points_ordered_by_x[x_left].i ||
            ys[y_left].i == points_ordered_by_x[x_right].i) {
            // cout << "y_left break" << endl;
          break;
        }
      }
    }
  }

  cout << result << endl;

  return 0;
}

