ll up[2][MAX],down[2][MAX];

void upd(ll i,bool b){
	if(b == 1) i = inf - i;
	for(; i < inf; i += (i&(-i))){
		bit[b][i]++;
	}
}

ll get(ll i,bool b){
	ll ans = 0;
	if(b == 1) i = inf - i;
	for(; i > 0 ; i -= (i&(-i))){
		ans += bit[b][i];
	}
	return ans;
}

ll qpow (ll x,ll y){
	if(y < 0)return 0;
	if(y == 0)return 1;
	ll temp = qpow(x,y/2);
	temp = (temp * temp)%mod;
	if(y&1)
		return (temp * x)%mod;
	return temp;
}

ll calc(ll x,ll y){
	return ((mod + qpow(2,x + y) - (qpow(2,x) + qpow(2,y))%mod)%mod + 1)%mod;
}

bool cmp(P x, P y){return x.x < y.x;}

int main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n;
	cin>>n;
	for(int i = 0; i < n ; i++)cin>>a[i].x>>a[i].y,a[i].y += bias;

	sort(a,a+n,cmp);

	ll ans = 0;
	for(int i = 0; i < n ; i++){
		up[0][i] = get(a[i].y ,1);
		down[0][i] = get(a[i].y ,0);
		upd(a[i].y ,1);
		upd(a[i].y ,0);
	}
	bit[0].clear();
	bit[1].clear();

	for(int i = n -1 ; i >= 0; i -- ){
		up[1][i] = get(a[i].y ,1);
		down[1][i] = get(a[i].y ,0);
		upd(a[i].y, 1);
		upd(a[i].y, 0);
	}

	for(int i = 0; i < n ; i++){
		// cout<<down[0][i]<<" "<<up[0][i]<<" "<<down[1][i]<<" "<<up[1][i]<<endl;
		ll temp = 0;
		temp += (qpow(2,down[0][i]) - 1);
		temp += (qpow(2,down[1][i]) - 1);
		temp += (qpow(2,up[0][i]) - 1);
		temp += (qpow(2,up[1][i]) - 1);

		temp += calc(down[1][i],up[1][i]);
		temp += calc(down[0][i],up[0][i]);
		temp += calc(up[1][i],up[0][i]);
		temp += calc(down[1][i],down[0][i]);
		temp = (temp + mod)%mod;		
		ans += (qpow(2,n) - temp - 1 + 3LL * mod)%mod;

	}
	cout<<ans<<" ";
	return 0;
}

