void init(int n)
{

    m = 1;

    while (m < n)
        m *= 2;

    node.resize(m * 2 - 1);
}

void add(int y)
{
    y += m - 1;
    node[y]++;

    while (y > 0)
    {
        y = (y - 1) / 2;
        node[y]++;
    }
}

int get(int a, int b, int k = 0, int l = 0, int r = m)
{

    if (r <= a || b <= l)
        return 0;

    if (a <= l && r <= b)
        return node[k];

    int lv = get(a, b, 2 * k + 1, l, (l + r) / 2);
    int rv = get(a, b, 2 * k + 2, (l + r) / 2, r);

    return lv + rv;
}

