int N;long long base=998244353LL;

long long topow(int x) {
  if (x==0) return 1;
  else {
    if (x%2==0) return topow(x/2)*topow(x/2)%base;
    else return 2*topow(x-1)%base;
  }
}

long long operator*(pll x,pll y) {
  long long xx=((topow(x.first)-1)%base)*((topow(y.second)-1)%base)%base;
  long long yy=((topow(x.second)-1)%base)*((topow(y.first)-1)%base)%base;
  long long zz=topow(N-1)%base;
  long long ww=(((topow(x.first)-1)%base)*((topow(y.second)-1)%base)%base)*(((topow(x.second)-1)%base)*((topow(y.first)-1)%base)%base)%base;
  return (xx*topow(N-1-x.first-y.second)%base+yy*topow(N-1-x.second-y.first)%base+zz-ww)%base;
}

int main() {
  cin >> N;
  vector<pll> A(N);map<long long,int> M1,M2;
  for (int i=0;i<N;i++) {
    cin >> A[i].first >> A[i].second;
  }
  vector<pll> B=A;
  sort(A.begin(),A.end());
  for (int i=0;i<N;i++) {
    M1[A[i].first]=i;
  }
  for (int i=0;i<N;i++) {
    A[i].first=B[i].second;
    A[i].second=B[i].first;
  }
  sort(A.begin(),A.end());
  for (int i=0;i<N;i++) {
    M2[A[i].first]=i;
  }
  for (int i=0;i<N;i++) {
    B[i].first=M1[B[i].first];
    B[i].second=M2[B[i].second];
  }
  sort(B.begin(),B.end());
  vector<int> X(N,0);
  for (int i=0;i<N;i++) {
    int j=B[i].second;long long low=0LL;
    while (j>0) {
      int lsb=(j & -1*j);
      low+=X[j-1];
      j-=lsb;
    }
    long long high=i-low;A[i]=make_pair(low,high);
    int k=B[i].second+1;
    while (k<=N) {
      int lsb=(k & -1*k);
      X[k-1]++;
      k+=lsb;
    }
  }
  vector<pll> C(N);vector<int> Y(N,0);
  for (int i=N-1;i>=0;i--) {
    int j=B[i].second;long long low=0LL;
    while (j>0) {
      int lsb=(j & -1*j);
      low+=Y[j-1];
      j-=lsb;
    }
    long long high=N-1-i-low;C[i]=make_pair(low,high);
    int k=B[i].second+1;
    while (k<=N) {
      int lsb=(k & -1*k);
      Y[k-1]++;
      k+=lsb;
    }
  }
  long long ans=0LL;
  for (int i=0;i<N;i++) {
    ans+=A[i]*C[i];
    ans%=base;
  }
  cout << ans << endl;
}

