typedef pair<int, int> P;

struct SegTree {
    vector<long long> value;
    int M;

    SegTree(int n, int x = 0) {
        M = 1;
        while(M < n) M *= 2;
        value = vector<long long>(M * 2 - 1, x);
    }

    void clear(int x = 0) {
        for(int i = 0; i < M * 2 - 1; i++) value[i] = x;
    }

    void add(int p, long long x, int k = 0, int l = 0, int r = -1) {
        if(r == -1) r = M;

        if(r - l == 1) value[k] += x;    
        else {
            int m = (l + r) / 2;
            if(p < m) add(p, x, k * 2 + 1, l, m);
            else add(p, x, k * 2 + 2, m, r);

            value[k] = value[k * 2 + 1] + value[k * 2 + 2];
        }
    }

    long long sum(int a, int b, int k = 0, int l = 0, int r = -1) {
        if(r == -1) r = M;

        if(a <= l && r <= b) return value[k];
        else {
            int m = (l + r) / 2;
            long long s = 0;
            if (a < m) s += sum(a, b, k * 2 + 1, l, m);
            if (m < b) s += sum(a, b, k * 2 + 2, m, r);
            return s;
        }
    }
};

vector<int> compress(vector<int> x) {
    vector<int> axis(x);

    sort(axis.begin(), axis.end());

    for(int i = 0; i < x.size(); i++) {
        x[i] = lower_bound(axis.begin(), axis.end(), x[i]) - axis.begin();
    }

    return x;
}

const int MOD = 998244353;

P p[200000];
vector<int> x;
vector<int> y;

long long LU[200000];
long long LD[200000];
long long RU[200000];
long long RD[200000];

long long pow[200001];

int main() {
    int n, i;
    scanf("%d", &n);

    x = vector<int>(n);
    y = vector<int>(n);
    for(int i = 0; i < n; i++) {
        scanf("%d %d", &x[i], &y[i]);
    }    

    x = compress(x);
    y = compress(y);
    for(int i = 0; i < n; i++) p[i] = P(x[i], y[i]);

    sort(p, p + n);
    SegTree seg = SegTree(n);
    for(int i = 0; i < n; i++) {
        int y = p[i].second;
        LU[i] = seg.sum(0, y);
        LD[i] = seg.sum(y, n);
        seg.add(y, 1);
    }

    seg.clear();
    for(int i = n - 1; i >= 0; i--) {
        int y = p[i].second;
        RU[i] = seg.sum(0, y);
        RD[i] = seg.sum(y, n);
        seg.add(y, 1);
    }

    pow[0] = 0;
    for(int i = 1; i <= n; i++) pow[i] = (pow[i - 1] * 2 + 1) % MOD;

    long long ans = (n * pow[n]) % MOD;
    for(int i = 0; i < n; i++) {
        ans -= pow[LU[i] + RU[i]] + pow[RU[i] + RD[i]]
                + pow[RD[i] + LD[i]] + pow[LD[i] + LU[i]];
        ans += pow[LU[i]] + pow[RU[i]] + pow[RD[i]] + pow[LD[i]];
        ans %= MOD;
    }

    printf("%lld\n", (ans + MOD) % MOD);
    return 0;
}

