using namespace std;
int mypow(int x, int y) {
	if (!y)return 1;
	if (y % 2)return mypow(x, y - 1) * x % mod;
	int memo = mypow(x, y / 2);
	return memo * memo % mod;
}
class lazySegTree {
	int n, node[500010] = {}, lazy[500010] = {};
	bool clearf[500010] = {};
public:
	lazySegTree(int n_) {
		n = 1;
		while (n < n_)n *= 2;
	}
	void clear() {
		rep(i, 500010)node[i] = lazy[i] = clearf[i] = 0;
	}
	void eval(int k, int l, int r) {
		if (lazy[k] != 0) {
			node[k] += lazy[k];
			if (r - l > 1) {
				lazy[2 * k + 1] += lazy[k] / 2;
				lazy[2 * k + 2] += lazy[k] / 2;
			}
			lazy[k] = 0;
		}
	}
	void add(int a, int b, int x, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = n;
		eval(k, l, r);
		if (b <= l || r <= a)return;
		if (a <= l && r <= b) {
			lazy[k] += (r - l) * x;
			eval(k, l, r);
		}
		else {
			add(a, b, x, 2 * k + 1, l, (l + r) / 2);
			add(a, b, x, 2 * k + 2, (l + r) / 2, r);
			node[k] = node[2 * k + 1] + node[2 * k + 2];
		}
	}
	int getsum(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = n;
		eval(k, l, r);
		if (b <= l || r <= a)return 0;
		if (a <= l && r <= b)return node[k];
		int vl = getsum(a, b, 2 * k + 1, l, (l + r) / 2);
		int vr = getsum(a, b, 2 * k + 2, (l + r) / 2, r);
		return vl + vr;
	}
};
