int main() {
    using namespace std;
    unsigned long N;
    scanf("%lu", &N);
    vector<unsigned long> perm(N);
    {
        vector<pair<long, long>> p(N);
        for(auto& i : p)scanf("%lu%lu", &i.first, &i.second);
        sort(p.begin(), p.end());
        for(unsigned long i = 0; i < N; ++i)p[i] = {p[i].second, i + 1};
        sort(p.begin(), p.end());
        transform(p.cbegin(), p.cend(), perm.begin(), [](auto i){return i.second;});
    }

    constexpr unsigned long MOD = 998244353;
    vector<unsigned long> binary(N + 1);
    unsigned long n = binary[0] = 1;
    generate(binary.begin() + 1, binary.end(), [&n](){if(n >= MOD)n -= MOD;return n <<= 1;});


    vector<unsigned long> fenwick_tree(N + 1);
    auto que = [&fenwick_tree, &N](unsigned long i){
        unsigned long s{0}, j{i};
        while(i){
            s += fenwick_tree[i];
            i -= i & -i;
        }
        while(j <= N){
            ++fenwick_tree[j];
            j += j & -j;
        }
        return s;
    };

    vector<unsigned long> coef(N + 1);
    coef[N] = N + MOD - 4;
    for(unsigned long i = 0; i != N; ++i){
        auto p = perm[i], q = que(p);
        ++coef[q];
        ++coef[i - q];
        ++coef[p - q - 1];
        ++coef[N - i - p + q];
    }

    cout << inner_product(binary.begin(), binary.end(), coef.begin(), 4 + MOD - N) % MOD << endl;
    return 0;
}

