class SegmentTree {
public:
    int N; //要素数
    vector<ll> dat;

    SegmentTree(int n_) {
        N = 1;
        while (N < n_) N *= 2;
        dat.assign(2 * N - 1, 0);
    }

    void update(int k, int a) { //k番目(0-indexed)をaに変更
        k += N - 1; //一番下
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2; //1つ上がる
            //更新
            dat[k] = dat[k * 2 + 1] + dat[k * 2 + 2]; //
        }
    }

    //[a, b)の値（最小値/和/etc.）を求める
    //kは節点の番号、l, rはその節点が[l,r)に対応づいていることを表す
    //外からはquery(a, b)と呼ぶ

    int query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = N;
        if (r <= a || b <= l) return 0;
        //[a, b)が[l,r)を完全に含む
        if (a <= l && r <= b) return dat[k];
        else {
            int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return vl + vr; //
        }
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << setprecision(20) << setiosflags(ios::fixed);

    int n;
    cin >> n;
    ll x[200010], y[200010];

    vector<pll> vx, vy;

    rep(i, n) {
        cin >> x[i] >> y[i];
        vx.push_back(MP(x[i], i));
        vy.push_back(MP(y[i], i));
    }

    sort(all(vx));
    sort(all(vy));

    rep(i, n) {
        x[vx[i].second] = i;
        y[vy[i].second] = i;
    }

    pll dot[200010];
    rep(i, n) dot[i].first = x[i], dot[i].second = y[i];
    sort(dot, dot + n);

    SegmentTree sg_front(n), sg_back(n);
    ll LU[200010], LD[200010], RU[200010], RD[200010];

    rep(i, n) {
        LD[i] = sg_front.query(0, dot[i].second);
        LU[i] = sg_front.query(dot[i].second, n);
        sg_front.update(dot[i].second, 1);
    }

    for (int i = n - 1; i >= 0; --i) {
        RD[i] = sg_back.query(0, dot[i].second);
        RU[i] = sg_back.query(dot[i].second, n);
        sg_back.update(dot[i].second, 1);
    }

    mint sum = 0;

    rep(i, n) {
        sum += (modpow(2, LU[i]) - 1) * (modpow(2, RD[i]) - 1) * modpow(2, LD[i] + RU[i]);
        sum += (modpow(2, LD[i]) - 1) * (modpow(2, RU[i]) - 1) * modpow(2, LU[i] + RD[i]);
        sum -= (modpow(2, LU[i]) - 1) * (modpow(2, RD[i]) - 1) * (modpow(2, LD[i]) - 1) * (modpow(2, RU[i]) - 1);
        sum += modpow(2, n - 1);
    }

    cout << sum << endl;
    return 0;
}

