#define MAX 222222


struct BinaryIndexed {
  ll num;
  vll bit;

  BinaryIndexed(ll x = MAX) {
    num = x;
    bit.resize(x + 1, 0);
  }

  ll sum(ll i) {
    ll ret = 0;
    while (i > 0) {
      ret += bit[i];
      i -= i & -i;
    }
    return ret;
  }

  void add(ll i, ll x) {
    if (i == 0) cout << "access 0 index" << endl;
    while (i <= num) {
      bit[i] += x;
      i += i & -i;
    }
  }
};

vll fac, inv, invfac;
void comb_set(ll x = MAX) {
  fac.resize(x + 1, 0);
  invfac.resize(x + 1, 0);
  inv.resize(x + 1, 0);
  fac[0] = inv[1] = invfac[0] = 1;
  FOR(i, 1, x + 1) (fac[i] = fac[i - 1] * i) %= mod;
  FOR(i, 2, x + 1) (inv[i] = (mod - mod / i) * inv[mod%i]) %= mod;
  FOR(i, 1, x + 1) (invfac[i] = invfac[i - 1] * inv[i]) %= mod;
}
ll comb(ll x, ll y) {
  if (x < y) return 0;
  return fac[x] * invfac[x - y] % mod * invfac[y] % mod;
}
ll mod_pow(ll x, ll y) {
  ll ret = 1;
  while (y > 0) {
    if (y & 1) ret = (x*ret) % mod;
    x = (x*x) % mod;
    y >>= 1;
  }
  return ret;
}


