	rep(i, n) {
		x[i] = p[i].first;
		y[i] = p[i].second;
	}
	vector<int> c1(n), c2(n), c3(n), c4(n);
	segtree<int> seg1(n, RSQ);
	rep(i, n) {
		c1[i] = seg1.get(y[i] + 1, n + 1);
		c3[i] = seg1.get(0, y[i]);
		seg1.add(y[i], 1);
	}
	segtree<int> seg2(n, RSQ);
	for (int i = n - 1; i >= 0; i--) {
		c2[i] = seg2.get(y[i] + 1, n + 1);
		c4[i] = seg2.get(0, y[i]);
		seg2.add(y[i], 1);
	}
	ll ans = modpow(2, n - 1)*n%mod;
	rep(i, n) {
		ans += (modpow(2, c1[i]) - 1)*(modpow(2, c4[i]) - 1) % mod*modpow(2, c2[i]) % mod*modpow(2, c3[i]) % mod;
		ans += (modpow(2, c2[i]) - 1)*(modpow(2, c3[i]) - 1) % mod*modpow(2, c1[i]) % mod*modpow(2, c4[i]) % mod;
		ans -= (modpow(2, c1[i]) - 1)*(modpow(2, c4[i]) - 1) % mod*(modpow(2, c2[i]) - 1) % mod*(modpow(2, c3[i]) - 1) % mod;
	}
	cout << (ans % mod + mod) % mod << '\n';
}

