using ll = long long;
const ll MOD = 998244353;

const int MAXN = 2.1e5;
int N;
pair<int, int> P[MAXN];
int p2[MAXN];

int bit[MAXN];
void update(int a) {
  for (a++; a <= N; a += (a & (-a))) {
    bit[a] ++;
  }
}
int query(int a) {
  int r = 0;
  for (a++; a > 0; a -= (a & (-a))) {
    r += bit[a];
  }
  return r;
}

int main() {
  ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
  cin >> N;
  for (int i = 0; i < N; i++) cin >> P[i].first >> P[i].second;
  p2[0] = 0;
  for (int i = 1; i <= N; i++) p2[i] = (p2[i-1]*2+1)%MOD;

  vector<int> xs, ys;
  for (int i = 0; i < N; i++) xs.push_back(P[i].first), ys.push_back(P[i].second);
  sort(xs.begin(), xs.end());
  //xs.resize(unique(xs.begin(), xs.end()) - xs.begin());
  sort(ys.begin(), ys.end());
  //ys.resize(unique(ys.begin(), ys.end()) - ys.begin());
  for (int i = 0; i < N; i++) {
    P[i].first = int(lower_bound(xs.begin(), xs.end(), P[i].first) - xs.begin());
    P[i].second = int(lower_bound(ys.begin(), ys.end(), P[i].second) - ys.begin());
  }
  sort(P, P + N);

  ll ans = 0;
  for (int i = 0; i < N; i++) {
    int quad = query(P[i].second);
    update(P[i].second);
    ans += p2[N] - p2[P[i].first] - p2[N-1-P[i].first] - p2[P[i].second] - p2[N-1-P[i].second] + p2[quad] + p2[P[i].first - quad] + p2[P[i].second - quad] + p2[N-1-quad-(P[i].first-quad)-(P[i].second-quad)];
  }
  ans %= MOD;
  if (ans < 0) ans += MOD;
  cout << ans << '\n';
}

