template<typename T>
vector<T> CoordinateCompression(vector<T> &x){
    vector<T> y = x, ret(SZ(x));
    sort(ALL(y));
    y.erase(unique(ALL(y)), y.end());
    rep(i, SZ(x)){
        ret[i] = lower_bound(ALL(y), x[i]) - y.begin();
    }
    return ret;
}

