template<typename T>
struct BIT {
	int n;
	vector<T> d;
	BIT(int n = 0) : n(n), d(n + 1) {}
	void add(int i, T x = 1) {
		++i;
		while (i <= n) {
			d[i] += x;
			i += i & -i;
		}
	}
	T sum(int i) {
		++i;
		T x = 0;
		while (i > 0) {
			x += d[i];
			i -= i & -i;
		}
		return x;
	}
};

ll f(int a, int b, int c, int d) {
	ll res = 0;
	vector<int> num = {a, b, c, d};
	vector<ll> o(4), ox(4);
	for (int i = 0; i < 4; i++) {
		ox[i] = ((ll) pow(2, num[i])) % mod;
		o[i] = ox[i] - 1;
	}
	ll v = ((ox[0] % mod) * (o[1] % mod)) % mod;
	ll w = (v * (o[2] % mod)) % mod;
	ll x = (w * (ox[3] % mod)) % mod;
	res += x;
	res %= mod;
	v = ((o[0] % mod) * (ox[1] % mod)) % mod;
	w = (v * (ox[2] % mod)) % mod;
	x = (w * (o[3] % mod)) % mod;
	res += x;
	res %= mod;
	v = ((o[0] % mod) * (o[1] % mod)) % mod;
	w = (v * (o[2] % mod)) % mod;
	x = (w * (o[3] % mod)) % mod;
	res -= x;
	res %= mod;
	v = ((ox[0] % mod) * (ox[1] % mod)) % mod;
	w = (v * (ox[2] % mod)) % mod;
	x = (w * (ox[3] % mod)) % mod;
	res += x;
	res %= mod;
	return res;
}

