// FenwickTree (0 - indexed)
// T: 可換モノイド
template<typename T>
class FenwickTree {
    const int n;
    const T ZERO;
    std::vector<T> data;
public:
    // 要素数を指定し、全要素0で初期化
    FenwickTree(int n, T ZERO) : n(n), ZERO(ZERO), data(n + 1, ZERO) {}

    // 元となるstd::vectorを用意して初期化
    FenwickTree(std::vector<T> source, T ZERO) : n(source.size()), ZERO(ZERO), data(n + 1) {
        std::copy(source.begin(), source.end(), data.begin() + 1);
        for (int i = 1; i < n; i++) data[i + (i & -i)] += data[i];
    }

    // [0, i)の区間和を取得
    T getSum(int i) const {
        T ret = ZERO;
        for (i; i > 0; i -= i & -i)ret += data[i];
        return ret;
    }

    // 要素iにxを加算
    void add(int i, T x) { for (i++; i <= n; i += i & -i)data[i] += x; }

    // 以下、T: 可換群

    // [l, r)の区間和を取得
    T getSum(int l, int r) const {
        return getSum(r) - getSum(l);
    }

    // [0, i)の区間和がx以上となる最小のiを取得 (区間和の単調性が必要)
    int getLowerBound(T x) const {
        if (x <= ZERO) return 0;
        int i = 0, r = 1;
        while (r < n) r <<= 1;
        for (int k = r; k > 0; k >>= 1) {
            if (i + k <= n && data[i + k] < x) {
                x -= data[i + k];
                i += k;
            }
        }
        return i + 1;
    }
};

// 二次元FenwickTree (0 - indexed)
// T: 可換モノイド
template<typename T>
class TwoDimFenwickTree {
    const int n, m;
    const T ZERO;
    std::vector<std::vector<T>> data;
public:
    // 要素数を指定し、全要素0で初期化
    TwoDimFenwickTree(int n, int m, T ZERO) : n(n), m(m), ZERO(ZERO), data(n + 1, std::vector<T>(m + 1, ZERO)) {}

    // [(0, 0), (i, j))の矩形和を取得
    T getSum(int i, int j) const {
        T ret = 0;
        for (; i > 0; i -= i & -i)for (int j2 = j; j2 > 0; j2 -= j2 & -j2)ret += data[i][j2];
        return ret;
    }

    // 要素(i, j)にxを加算
    void add(int i, int j, T x) {
        for (i++; i <= n; i += i & -i)for (int j2 = j + 1; j2 <= m; j2 += j2 & -j2)data[i][j2] += x;
    }

    // 以下、T: 可換群

    // [(y1, x1), (y2, x2))の矩形和を取得
    T getSum(int y1, int x1, int y2, int x2) const {
        return getSum(y2, x2) - getSum(y2, x1) - getSum(y1, x2) + getSum(y1, x1);
    }
};

