template<typename T>
struct BIT {
private:
    vector<T> array;
    const int n;

public:
    BIT(int _n) :array(_n + 1, 0), n(_n) {};

    //1番目からi番目までの累積和
    T sum(int i) {
        T s = 0;
        while (i > 0) {
            s += array[i];
            i -= i & -i;//LSB減算
        }
        return s;
    }

    //[i,j]の要素の和
    T sum(int i, int j) {
        T ret_i = sum(i - 1);
        T ret_j = sum(j);
        return ret_j - ret_i;
    }

    //i番目に要素xを追加する
    void add(int i, T x) {
        while (i <= n) {
            array[i] += x;
            i += i & -i;//LSB加算
        }
    }
};

/* compress
    (X1,Y1),(X2,Y2)という二点で表されるもの（長方形や直線など）について、行か列の片方（X1とX2 or Y1とY2）を座標圧縮する（副作用）
    返り値: ソートされ重複要素を除いた値
    計算量: O(n log n)
*/
template <typename T>
vector<T> compress(vector<T>& C1, vector<T>& C2) {
    vector<T> vals, VALS;
    int N = (int)C1.size();
    for (int i = 0; i < N; i++) {
        for (T d = 0; d < 1; d++) {  // その位置と、一つ隣を確保(隣を確保しないと空白が埋まってしまうことがある)
            T tc1 = C1[i] + d;
            T tc2 = C2[i] + d;
            vals.push_back(tc1);
            VALS.push_back(tc2);
        }
    }
    // ソート
    sort(vals.begin(), vals.end());
    sort(VALS.begin(), VALS.end());
    // 隣り合う重複を削除(unique), 末端のゴミを削除(erase)
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    VALS.erase(unique(VALS.begin(), VALS.end()), VALS.end());
    for (int i = 0; i < N; i++) {
        C1[i] = lower_bound(vals.begin(), vals.end(), C1[i]) - vals.begin();
        C2[i] = lower_bound(VALS.begin(), VALS.end(), C2[i]) - VALS.begin();
    }
    return vals;
}

ll modpow(ll a, ll b, ll mod) {
    ll res = 1;
    while (b) {
        if (b & 1)res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}


