    long long a2 = mod_pow2(a);
    long long b2 = mod_pow2(b);
    long long c2 = mod_pow2(c);
    long long d2 = mod_pow2(d);
    ans += (((((a2*b2)%mod)*c2)%mod)*d2)%mod;
    ans += ((((((a2-1)*(d2-1))%mod)*b2)%mod)*c2)%mod;
    ans += ((((a2+d2-1)*(b2-1))%mod)*(c2-1))%mod;
