        ll rt = N - 1 - (ld + lt + rd);
        bit.add(yi + 1, 1);

        ll t[4] = {ld, lt, rt, rd};

        ans += P[N - 1] + (P[N - 1] - 1);
        REP(j, 4) {
            ll m = P[t[j] + t[(j + 1) % 4]] - 1 - (P[t[j]] - 1);
