	ll res = n * (p2[n]-1) % MOD;
	FOR(i,0,n) res = (res - 4*(p2[i]-1)) % MOD;
	FOR(flip,0,2) {
		vl is(n);
		iota(all(is),0);
		sort(all(is),[&](ll i, ll j) { return x[i] < x[j]; });
		FOR(rot,0,2) {
			bit B(n);
			for (ll i: is) {
				ll cnt = B.get(y[i]);
				res = (res + p2[cnt]-1) % MOD;
				B.add(y[i],1);
			}
			reverse(all(is));
		}
		FOR(i,0,n) y[i] = n-1-y[i];
	}

	if (res < 0) res += MOD;
	cout << res << endl;
}

