ll modpow(ll n,ll k){
  if(k == 1){
    return n;
  }else if(k == 0){
    return 1;
  }else if(k%2==0){
    ll memo = modpow(n,k/2)%MOD;
    return memo*memo%MOD;
  }else{
    return n * modpow(n,k-1)%MOD;
  }
}

int main(){

  ll n;cin>>n;
  vector<LP> xy;
  vector<LP> yx;
  vector<ll> vx;
  vector<ll> vy;
  vector<ll> v;
  ll C[n];
  ll ans = 0;

    ll modp[n+1];
    modp[0] = 1;
    modp[1] = 2;
    for(int i=2;i<=n;i++){
      modp[i] = modp[i-1] * 2;
      modp[i] %= MOD;
    }

  REP(i,n){
    ll x,y;
    cin>>x>>y;
    LP lp;
    lp.first = x;
    lp.second = y;
    xy.pb(lp);
    lp.first = y;
    lp.second = x;
    yx.pb(lp);
    vx.pb(x);
    vy.pb(y);
  }
  VSORT(xy);
  VSORT(yx);
  VSORT(vx);
  VSORT(vy);

  REP(i,n){
    LP lp = xy[i];
    if(i==0){
      C[i] = 0;
      v.pb(lp.second);
    }else{
      auto Iter = upper_bound(v.begin(),v.end(),lp.second);
      C[i] = Iter - v.begin();
      v.insert(Iter,lp.second);
    }
  }


  REP(i,n){
    LP lp = xy[i];
    ll a,b,c,d;
    c = C[i];
    auto Iter = lower_bound(vx.begin(),vx.end(),lp.first);
    b = (ll)(Iter - vx.begin()) - c;
    auto Iter2 = lower_bound(vy.begin(),vy.end(),lp.second);
    d = (ll)(Iter2 - vy.begin()) - c;
    a = n - 1 - b - c - d;
    //cout<<"ji "<<a<<" "<<b<<" "<<c<<" "<<d<<endl;
    ll ac = (modp[a]-1) * (modp[c]-1) % MOD;
    ac = ac * modp[b+d] % MOD;
    ll bd = (modp[b]-1) * (modp[d]-1) % MOD;
    bd = bd * modp[a+c] % MOD;
    ll abcd = (modp[a]-1) * (modp[c]-1) % MOD;
    abcd = abcd * (modp[b]-1) % MOD;
    abcd = abcd * (modp[d]-1) % MOD;
    ans = (ans + (ac + bd - abcd) ) % MOD;

    //自分含む
    ll zibun = modp[n-1]%MOD;
    ans = (ans + zibun) %MOD;
  }

  cout<<ans<<endl;



  return 0;
}

