template <class T> class Compress {
	vector<T> v;
	bool flag = false;

public:
	Compress() {}
	template <class U> Compress(const U& a) {
		add(a);
	}
	Compress& add(const T& a) {
		flag = false;
		v.push_back(a);
		return *this;
	}
	template <class U> Compress& add(const vector<U>& a) {
		flag = false;
		for (const auto& i : a) add(i);
		return *this;
	}
	template <class U> Compress& add(const initializer_list<U>& a) {
		flag = false;
		for (const auto& v : a) add(v);
		return *this;
	}
	template <class U> Compress& operator<<(const U& a) {
		add(a);
		return *this;
	}
	void build() {
		sort(v.begin(), v.end());
		v.erase(unique(v.begin(), v.end()), v.end());
		flag = true;
	}
	int operator()(const T& x) const {
		assert(flag);
		return lower_bound(v.begin(), v.end(), x) - v.begin();
	}
	vector<int> operator()(const vector<T>& x) const {
		assert(flag);
		vector<int> res;
		res.reserve(x.size());
		for (const T& i : x) res.push_back(lower_bound(v.begin(), v.end(), i) - v.begin());
		return res;
	}
	int size() const {
		assert(flag);
		return v.size();
	}
	const vector<T>& operator*() const {
		assert(flag);
		return v;
	}
	const T& operator[](int i) const {
		assert(flag);
		return v[i];
	}
};

template <class T> class BinaryIndexedTree {
	int n, n2;
	vector<T> a;

public:
	BinaryIndexedTree(int n_) : n(n_), n2(1), a(n_ + 1) {
		while (n2 < n) n2 *= 2;
		n2 /= 2;
	}
	T operator()(int i) const {  // [0, i]
		assert(0 < ++i);
		T res = 0;
		for (; i > 0; i -= i & -i) res += a[i];
		return res;
	}
	T operator()(int i, int j) const {  // [i, j]
		return operator()(j) - (i ? operator()(i - 1) : 0);
	}
	T operator[](int i) const {
		return operator()(i, i);
	}
	void add(int i, T x) {
		assert(0 < ++i);
		for (; i <= n; i += i & -i) a[i] += x;
	}
	int lower_bound(T k) const {
		if (k <= 0) return 0;
		int res = 0;
		for (int i = n2; i > 0; i /= 2) {
			if (res + i <= n && a[res + i] < k) {
				k -= a[res + i];
				res += i;
			}
		}
		return res;
	}
	vector<int> debug() const {
		vector<int> res(n);
		for (int i = 0; i < n; ++i) res[i] = operator()(i, i);
		return res;
	}
};

