	for(auto it=m.bg;it!=m.ed;it++) it->b=sub++;

	rep(i,N) p[i].b=m[p[i].b];
	sort(all(p));

	ll ans=N*power(2,N-1,MOD);
	ans%=MOD;
	rep(i,N){
		// p[i]を見る
		// 見る前にrightを減らす
		right.add(p[i].b,-1);

		// 見る
		/*
				A|B
		 p[i].b ---
				D|C
		*/
		ll A=left.sum(p[i].b-1),B=right.sum(p[i].b-1),C=right.sum(N)-right.sum(p[i].b),D=left.sum(N)-left.sum(p[i].b);

		ll A2=power(2,A,MOD)-1,B2=power(2,B,MOD)-1,C2=power(2,C,MOD)-1,D2=power(2,D,MOD)-1;
		ans+=(((A2*C2)%MOD)*power(2,B+D,MOD))%MOD;
		ans%=MOD;
		ans+=(((B2*D2)%MOD)*power(2,A+C,MOD))%MOD;
		ans%=MOD;
		ll tmp=(A2*B2)%MOD;
		tmp*=C2;
		tmp%=MOD;
		tmp*=D2;
		tmp%=MOD;
		ans-=tmp;
		if(ans<0) ans+=MOD;
		ans%=MOD;

		// 見た後にleftを増やす
		left.add(p[i].b,1);
	}
