  vector<vector<ll>> quadrant(N, vector<ll>(4));
  for (ll i = 0; i < N; ++i) {
    ll x = XY.at(i).first, y = XY.at(i).second;
    ll index = lower_bound(Y.begin(), Y.end(), y) - Y.begin();
    ll temp = query(index, index + 1);
    quadrant.at(i).at(1) = i - temp;
    quadrant.at(i).at(2) = temp;
    update(index + 1, N);
  }

  dat = vector<ll>(2 * MAX_N - 1, 0);
  lazy = vector<ll>(2 * MAX_N - 1, 0);
  for (ll i = N - 1; i >= 0; --i) {
    ll x = XY.at(i).first, y = XY.at(i).second;
    ll index = lower_bound(Y.begin(), Y.end(), y) - Y.begin();
    ll temp = query(index, index + 1);
    quadrant.at(i).at(0) = (N - 1 - i) - temp;
    quadrant.at(i).at(3) = temp;
    update(index + 1, N);
  }
  // for (ll i = 0; i < N; ++i) {
  //   cout << quadrant.at(i).at(0) << ' ' << quadrant.at(i).at(1) << ' ' << quadrant.at(i).at(2) << ' ' << quadrant.at(i).at(3) << "\n";
  // }
  ll ans = 0;
  ll mod = 998244353;
  ans = modpow(2, N - 1, mod) * N % mod;
  for (ll i = 0; i < N; ++i) {
    vector<ll> pattern(4, 0);
    for (ll j = 0; j < 4; ++j) {
      pattern.at(j) = modpow(2, quadrant.at(i).at(j), mod) - 1;
      if (pattern.at(j) < 0) {
        pattern.at(j) += mod;
      }
    }
    ll temp = ((pattern.at(0) * pattern.at(2) % mod) * modpow(2, quadrant.at(i).at(1) + quadrant.at(i).at(3), mod) % mod) + ((pattern.at(1) * pattern.at(3) % mod) * modpow(2, quadrant.at(i).at(0) + quadrant.at(i).at(2), mod) % mod);
    ll sum = 1;
    for (ll j = 0; j < 4; ++j) {
      sum = (sum * pattern.at(j)) % mod;
    }
    temp -= sum;
    if (temp < 0) {
      temp += mod;
    }
    ans += temp;
