template<typename T> struct tree{
	using bound_t = int;
	const bound_t left_bound = 0;
	const bound_t right_bound = 500100;
	using tnode = node<T>;
	tnode * root;
	tree<T>(){
		root = NULL;
	}
	tnode * update(tnode * cur, bound_t l, bound_t r, bound_t pos, T v){
		if(cur == NULL) cur = new tnode();
		if(l == r) cur->value = cur->value + v;
		else{
			bound_t mid = (l + r)>>1;
			if(pos <= mid) cur->left = update(cur->left, l, mid, pos, v);
			else cur->right = update(cur->right, mid + 1, r, pos, v);
			cur->value = (cur->left ? cur->left->value : T(0)) + (cur->right ? cur->right->value : T(0));
		}
		return cur;
	}
	void update(bound_t pos, T v){
		root = update(root, left_bound, right_bound, pos, v);
	}
	T query(tnode * cur, bound_t l, bound_t r, bound_t x, bound_t y){
		if(cur == NULL || l > y || r < x) return T(0);
		if(x <= l && r <= y) return cur->value;
		bound_t mid = (l + r) >> 1;
		T le = query(cur->left, l, mid, x, y);
		T ri = query(cur->right, mid + 1, r, x, y);
		return le + ri;
	}
	T query(bound_t x, bound_t y){
		return query(root, left_bound, right_bound, x, y);
	}
};
