struct Fenwick {
    // Fenwick tree on 1, .., n. (1-indexed)
    int n;
    vector<int> xs;
    Fenwick(int n): n(n), xs(n+1, 0) {}
    void add(int i, int v) { // a[i] += v
        while (i <= n) {
            xs[i] += v;
            i += i & (-i);
        }
    }
    int get(int i) { // return a[1] + .. + a[i]
        int sum = 0;
        while (i > 0) {
            sum += xs[i];
            i -= i & (-i);
        }
        return sum;
    }
};

int main() {
