    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());
    for (int i = 0; i < n; ++i) {
        f_x[xs[i]] = i;
        f_y[ys[i]] = i+1; // y coordinates are 1-indexed.
    }
    for (Point& point : points) {
        point.x = f_x[point.x];
        point.y = f_y[point.y];
    }
    sort(points.begin(), points.end());
    Fenwick visited(n);
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        Point& p = points[i];
        // we get a, b, c, d like this 
        // a | b
        // -----
        // c | d
        int c = visited.get(p.y);
        int a = i - c;
        // a + b == n - p.y
        int b = n - p.y - a;
        // c + d == p.y - 1
        int d = p.y - 1 - c;
        long long outside = (pow2[a+b]-1) + (pow2[b+d]-1) + (pow2[d+c]-1) + (pow2[c+a]-1) - (pow2[a]-1) - (pow2[b]-1) - (pow2[c]-1) - (pow2[d]-1);
        long long from_others = (pow2[n-1]-1) - outside;
        long long total = from_others + pow2[n-1];
        total = (total % prime + prime) % prime;
        sum = (sum + total) % prime;
        visited.add(p.y, 1);
    }
    cout << sum << endl;
    return 0;
}

