struct Points2D {
	struct SegTree {
		int n;
		std::vector<int> data;
		SegTree (int n_) {
			for (n = 1; n < n_; n <<= 1);
			data.resize(n << 1);
		}
		void add(int i, int val) {
			for (i += n; i; i >>= 1) data[i] += val;
		}
		int sum(int l, int r) {
			int res = 0;
			for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
				if (r & 1) res += data[--r];
				if (l & 1) res += data[l++];
			}
			return res;
		}
	};
	std::vector<std::pair<int, int> > pts;
	struct Query {
		int x1;
		int x2;
		int y1;
		int y2;
		int *res;
	};
	std::vector<Query> queries;
	void add(std::pair<int, int> pt) { pts.push_back(pt); }
	void add(int x, int y) { pts.push_back({x, y}); }
	void query(Query query) { queries.push_back(query); }
	void query(int x1, int x2, int y1, int y2, int *res) { queries.push_back({x1, x2, y1, y2, res}); }
	void calculate() {
		std::vector<int> xs, ys;
		for (auto i : pts) xs.push_back(i.first), ys.push_back(i.second);
		std::sort(xs.begin(), xs.end());
		xs.erase(std::unique(xs.begin(), xs.end()), xs.end());
		std::sort(ys.begin(), ys.end());
		ys.erase(std::unique(ys.begin(), ys.end()), ys.end());
		for (auto &i : pts) {
			i.first = std::lower_bound(xs.begin(), xs.end(), i.first) - xs.begin();
			i.second = std::lower_bound(ys.begin(), ys.end(), i.second) - ys.begin();
		}
		for (auto &i : queries) {
			i.x1 = std::lower_bound(xs.begin(), xs.end(), i.x1) - xs.begin();
			i.x2 = std::lower_bound(xs.begin(), xs.end(), i.x2) - xs.begin();
			i.y1 = std::lower_bound(ys.begin(), ys.end(), i.y1) - ys.begin();
			i.y2 = std::lower_bound(ys.begin(), ys.end(), i.y2) - ys.begin();
		}

		int sz = queries.size();
		for (int i = 0; i < sz; i++) {
			*queries[i].res = 0;
			queries.push_back({queries[i].x1, queries[i].x2, queries[i].y2, 1, queries[i].res});
			queries[i].y2 = -1;
		}
		std::sort(pts.begin(), pts.end(), [] (auto &a, auto &b) { return a.second < b.second; });
		std::sort(queries.begin(), queries.end(), [] (Query &a, Query &b) { return a.y1 < b.y1; });
		int n = pts.size();
		int head = 0;
		SegTree tree(xs.size());
		for (auto &i : queries) {
			while (head < n && pts[head].second < i.y1) tree.add(pts[head++].first, 1);
			*i.res += i.y2 * tree.sum(i.x1, i.x2);
		}
	}
};

