    BIT(int n) {
        N = 1;
        while (N < n) N *= 2;
        N *= 2;

        data = vector<ll>(N+1);
    }

    void add(int i, ll x) {
        for (int k = i; k <= N; k += k&-k) data[k] += x;
    }

