        for (int i = n - 1; i >= 0; i--) {
            P p = points[i];
            int left = segmentTree.query(0, p.second);
            int right = segmentTree.query(p.second + 1, n);
            segmentTree.add(p.second, 1);

            counts[i][2] = left;
            counts[i][3] = right;
        }
    }

    mint ans = 0;
    rep(i, n) {

        // urdl
