        int sum = 0;
        while (i > 0) {
            sum += a[i];
            i -= i & -i;
        }
        return sum;
    }

    pii query(int i) {
        pii res;
        res.first = query_util(i);
        res.second = query_util(n) - res.first;
        return res;
    }

