        swap(a,c);
        swap(b,d);
        reverse(all(a));
        reverse(all(b));
        reverse(all(c));
        reverse(all(d));
    }
    int ans = 0;
    beki[0] = 1;
    rep(i,n)beki[i+1] = beki[i]*2 % MOD;

    rep(i,n){
        ans += f(a[i],b[i],c[i],d[i]);
        ans %= MOD;
    }
    cout << ans << endl;
}

