template<class T> class BIT{
private:
  ll n;
  vector<T> node;
  function<T(T,T)> dot;
  T e;
public:
  BIT(vector<T>&& A,function<T(T,T)> dot,T e):dot(dot),e(e){
    n=A.size();
    node.resize(n+1);
    rep(i,n) node[i+1]=A[i];
    rep(i,1,n+1){
      ll j=i+(i&-i);
      if(j<=n) node[j]=dot(node[i],node[j]);
    }
  }
