const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n;
vl xcs, ycs, xs, ys;
ll p2[MAX_N + 100];

points compress2D(vl xs, vl ys){
    /*
    NOTE
    ----
    Add the corner points if required
    */
    vl xcs = compress(xs), ycs = compress(ys);
    map<ll, ll> xd = dict(xcs), yd = dict(ycs);
    points ps(n);

    rep(i, n) 
        xs[i] = xd[xs[i]], ys[i] = yd[ys[i]];

    rep(i, n) 
        ps[i] = {xs[i], ys[i]};

    sort(all(ps));

    return ps;
}

ll prod_mod(ll a, ll b, ll c, ll d){
    return ((a * b) % MOD * (c * d) % MOD) % MOD;
}

ll func(ll n_ll, ll n_ul, ll n_lr, ll n_ur){
    ll ret = 0;
    vl num = {n_ll, n_ul, n_lr, n_ur};
    vl o(4), ox(4);
    rep(i, 4) ox[i] = p2[num[i]], o[i] = (ox[i] - 1 + MOD) % MOD;

    ll diag1 = prod_mod(ox[0], o[1], o[2], ox[3]);
    ll diag2 = prod_mod(o[0], ox[1], ox[2], o[3]);
    ll all_o = prod_mod(o[0], o[1], o[2], o[3]);
    ll tot = prod_mod(ox[0], ox[1], ox[2], ox[3]);

    // canceling out the duplication by subtracting all_o
    // tot is the number of pairs that includes the target point itself
    ret = tot + (diag1 + diag2 - all_o) + MOD;
    assert(ret >= 0);
    return ret % MOD;
}

void solve(){
    xs = ys = vl(n); p2[0] = 1;
    rep(i, n) in2(xs[i], ys[i]);
    rep(i, n + 10) p2[i + 1] = (p2[i] * 2) % MOD;
    points ps = compress2D(xs, ys);

    vl v_ll(n), v_ul(n), v_lr(n), v_ur(n);
    rep(_, 2){
        BIT bit(n);
        rep(i, n){
            v_ll[i] = bit.query(ps[i].y);
            v_ul[i] = i - v_ll[i];
            bit.update(ps[i].y, 1);
        }

        reverse(all(ps));
        swap(v_ll, v_lr); swap(v_ul, v_ur);
        reverse(all(v_ll)); reverse(all(v_lr));
        reverse(all(v_ul)); reverse(all(v_ur));
    }

    rep(i, n) 
        (answer += func(v_ll[i], v_ul[i], v_lr[i], v_ur[i])) %= MOD;
    prl(answer);
}

int main(void){
    in1(n);
    // assert(k <= 100000);
    solve();
    return 0;
}

