#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int maxn = 2e5 + 5;
int Bit[maxn], A[maxn], n;
pair<int, int> P[maxn];

void Update(int i) {

    while(i <= n) {
        Bit[i]++;
        i += i&(-i);
    }
}
int Getsum(int i) {

    int res = 0;
    while(i) {
        res += Bit[i];
        i -= i&(-i);
    }
    return res;
}

int main() {

    scanf("%d", &n);
    for(int i = 0; i < n; i++)
        scanf("%d%d", &P[i].first, &P[i].second);

    sort(P, P+n);
	for(int i = 0; i < n; i++) {
        P[i].first = P[i].second;
        P[i].second = i;
	}
	sort(P, P+n);
    A[0] = 1;
	for(int i = 1; i <= n; i++) {
        A[i] = A[i-1]<<1;
        if(A[i] >= MOD) A[i] -= MOD;
	}

	int ans = (long long)n*A[n]%MOD;
	for(int i = 0; i < n; i++) {

        int j = P[i].second, k = Getsum(j);
        int a = A[k], b = A[i-k], c = A[j-k], d = A[n-1-(i+j-k)];
        ans = (ans-(long long)(a+d-1)*(b+c-1)%MOD) % MOD;
        Update(j+1);
	}
	if(ans < 0) ans += MOD;
	printf("%d", ans);
	return 0;
}

