const long MOD = 998244353;

long pw(int x) {
    long res = 1;
    long a = 2;
    while (x > 0) {
        if (x & 1) {
            res *= a;
            res %= MOD;
        }
        a *= a;
        a %= MOD;
        x /= 2;
    }
    return res;
}

void add(int &a, int b) {
    a += b;
    a %= MOD;
//    cout << "!!! " << b << "\n";
}

vector<int> f;

void init(int n) {
    f.assign(n + 1, 0);
}

long sum(int r) { // exclusive
    if (r == 0)
        return 0;
    r--;
    long result = 0;
    for (; r >= 0; r = (r & (r + 1)) - 1)
        result += f[r];
    return result;
}

void inc(int i) {
    for (; i < f.size(); i = (i | (i + 1)))
        f[i]++;
}

