                for (int j = i-1; j >= 0; j--) {
                    if (xprev != xy[j].first) break;
                    f.add(ycompress[xy[j].second], 1);
                }
                xprev = xy[i].first;
            }
            int yc = ycompress[xy[i].second];
            int s = f.sum(yc-1);
            int t = f.sum(f.N) - f.sum(yc);
            ans += two[s] + two[t] - 2;
            ans %= mod;
        }
    }

    {   // down
        reverse(xy.begin(), xy.end());
        Fenwick<int> f(ycompress.size());
        int xprev = xy.front().first;
        for (int i = 0; i < n; i++) {
            if (xprev != xy[i].first) {
                for (int j = i-1; j >= 0; j--) {
                    if (xprev != xy[j].first) break;
                    f.add(ycompress[xy[j].second], 1);
                }
                xprev = xy[i].first;
            }
            int yc = ycompress[xy[i].second];
            int s = f.sum(yc-1);
            int t = f.sum(f.N) - f.sum(yc);
            ans += two[s] + two[t] - 2;
            ans %= mod;
        }
    }

    cout << ans << endl;
    return 0;
}

