// 座標圧縮
map<int, int> compress(vector<int> &x, bool sorted = false) {
  map<int, int> comp;
  if (!sorted) sort(x.begin(), x.end());
  x.erase(unique(x.begin(), x.end()), x.end());
  for (int i = 0; i < x.size(); i++) comp[x.at(i)] = i;
  return comp;
}

// Segment-Tree
struct SegmentTree {
  int n;
  vector<int> dat;

  SegmentTree(int _n) {
    init(_n);
  }

  void init(int _n) {
    n = 1;
    while (n < _n) n *= 2;
    dat.assign(2 * n - 1, 0);
  }

  // i番目の値にxを加算
  void add(int i, int x) {
    i += n - 1; // 葉のノード
    dat[i] += x;
    while (i > 0) { // 更新
      i = (i - 1) / 2;
      dat[i] = dat[2 * i + 1] + dat[2 * i + 2];
    }
  }

  // [a, b)の和
  // k:ノードの番号 [l, r)がkに対応づいている
  // query(a, b, 0, 0, n)と呼ぶ
  int query(int a, int b, int k = 0, int l = 0, int r = -1) {
    if (r == -1) r = n;
    if (r <= a || b <= l) return 0;
    if (a <= l && r <= b) return dat[k];
    else {
      int vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
      int vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
      return vl + vr;
    }
  }
};

// 繰り返し自乗法(x^nをmで割った余り) O(logn)
ll power(ll x, ll n, ll m) {
  ll res = 1;
  if (n > 0) {
    res = power(x, n / 2, m);
    if (n % 2 == 0) res = (res * res) % m;
    else res = (((res * res) % m) * x) % m;
  }
  return res;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  vector<pair<int, int>> v(n);
  vector<int> keep(n);
  for (int i = 0; i < n; i++) {
    cin >> v[i].first >> v[i].second;
    keep[i] = v[i].second;
  }

  sort(v.begin(), v.end());

  map<int, int> mp = compress(keep);

  vector<ll> lu(n), ld(n), ru(n), rd(n); // i番目の点より左上, 左下, 右上, 右下にある点の個数
  SegmentTree stl(n), str(n);
  for (int i = 0; i < n; i++) {
    lu[i] = stl.query(mp[v[i].second] + 1, n);
    ld[i] = stl.query(0, mp[v[i].second]);
    stl.add(mp[v[i].second], 1);
  }
  for (int i = n - 1; i >= 0; i--) {
    ru[i] = str.query(mp[v[i].second] + 1, n);
    rd[i] = str.query(0, mp[v[i].second]);
    str.add(mp[v[i].second], 1);
  }

  ll ans = ((power(2, n, MOD) - 1) * n) % MOD;
  for (int i = 0; i < n; i++) {
    ll keep = 0;
    keep += power(2, lu[i] + ld[i], MOD) - 1;
    keep += power(2, ld[i] + rd[i], MOD) - 1;
    keep += power(2, rd[i] + ru[i], MOD) - 1;
    keep += power(2, ru[i] + lu[i], MOD) - 1;
    keep -= power(2, lu[i], MOD) - 1;
    keep -= power(2, ld[i], MOD) - 1;
    keep -= power(2, rd[i], MOD) - 1;
    keep -= power(2, ru[i], MOD) - 1;
    keep %= MOD;
    ans -= keep;
  }

  ans = ((ans % MOD) + MOD) % MOD;

  cout << ans << '\n';
}

