    modint ans = 0;
    BinaryIndexedTree<int> bit(N), rbit(N);
    vector<ll> dpd(N),dpu(N),rdpd(N), rdpu(N);
    rep(i, 0, N){
        dpd[i] = bit.sum(P[i].second);
        dpu[i] = i - dpd[i];
        bit.add(P[i].second, 1);
    }
    rrep(i, 0, N){
        rdpd[i] = rbit.sum(P[i].second);
        rdpu[i] = N - 1 - i - rdpd[i];
        rbit.add(P[i].second, 1);
    }
    ans = mod_pow<ll>(2, N - 1, mod) * N;
    rep(i, 0, N){
        ans += (mod_pow<ll>(2, dpd[i], mod) - 1) * (mod_pow<ll>(2, rdpu[i], mod) - 1) % mod
         * (mod_pow<ll>(2, dpu[i], mod) + mod_pow<ll>(2, rdpd[i], mod));
        //cerr << ans << " ";
        ans += (mod_pow<ll>(2, dpu[i], mod) - 1) * (mod_pow<ll>(2, rdpd[i], mod) - 1) % mod 
        * (mod_pow<ll>(2, dpd[i] , mod) + mod_pow<ll>(2, rdpu[i] , mod));
        //cerr << ans << endl;
    }

    cout << ans - 1 << endl;

    return 0;
}

