ll func(ll lu,ll ld,ll ru,ll rd){

	ll all[4],not_zero[4];
	all[0] = POW[lu],all[1] = POW[ld],all[2] = POW[ru],all[3] = POW[rd];
	for(int i = 0; i < 4; i++){

		not_zero[i] = all[i]-1;
		if(not_zero[i] < 0){
			not_zero[i] += MOD;
		}
	}

	//対象の点を選ぶ場合
	ll ret = 1;
	for(int i = 0; i < 4; i++){

		ret *= all[i];
		ret %= MOD;
	}

	//対象の点を選ばない場合
	ll add = (not_zero[0]*not_zero[3])%MOD;
	add *= all[1];
	add %= MOD;
	add *= all[2];
	add %= MOD;

	ret += add;
	ret %= MOD;

	add = (not_zero[1]*not_zero[2])%MOD;
	add *= all[0];
	add %= MOD;
	add *= all[3];
	add %= MOD;

	ret += add;
	ret %= MOD;

	add = 1;
	for(int i = 0; i < 4; i++){

		add *= not_zero[i];
		add %= MOD;
	}

	ret -= add;
	if(ret < 0){

		ret += MOD;
	}

	return ret;
}



