      int d = bit.sum(yi);
      int c = bit.sum(n) - d;
      memo[xi][0] *= mpw2[c] * (mpw2[d] - 1);
      memo[xi][1] *= (mpw2[c] - 1) * mpw2[d];
      memo[xi][2] *= (mpw2[c] - 1) * (mpw2[d] - 1);
      bit.add(yi, 1);
    }
  }
  mint ans = 0;
  for(const auto& p : ps) {
    int x, y;
    tie(x, y) = p;
    int xi = mpx[x], yi = mpy[y];
    ans += mpw2[n-1];
    ans += memo[xi][0];
    ans += memo[xi][1];
    ans -= memo[xi][2];
  }
  cout << ans << '\n';
}
int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(0);
  answer();
  return 0;
}

