    while (x >= 1)
    {
        seg[x]++;
        x /= 2;
    }
}

int csum (int x)
{
    int ans = 0;
    x += P;
    while (x > 1)
    {
        if (x % 2 == 1)
            ans += seg[x-1];
        x /= 2;
    }
    return ans;
}

