  for (int i = n-1; i >= 0; i--) {
    point p = points[i];

    point_count[i][4] = point_count_from_right.get(0, p.y);
    point_count[i][1] = point_count_from_right.get(p.y, n);

    point_count_from_right.set(p.y, 1);
  }

  // 各点ごとに計算
  for (int i = 0; i < n; i++) {
    // 1.
    // 自分が部分集合に入っていないのに内部に含まれるのは、点pから見て第2・4象限に点がある場合と、第1・3象限に点がある場合
    calc_mod<int> c1 = calc_mod<int>(point_count[i][1], MOD);
    calc_mod<int> c2 = calc_mod<int>(point_count[i][2], MOD);
    calc_mod<int> c3 = calc_mod<int>(point_count[i][3], MOD);
    calc_mod<int> c4 = calc_mod<int>(point_count[i][4], MOD);

    // 点が1以上ある場合の数は2**点数-1
    c1 = case_count(c1);
    c2 = case_count(c2);
    c3 = case_count(c3);
    c4 = case_count(c4);

    // 重複を避けるため、パターンごとに計算
    int inner_patterns[]{
      // 2象限のみにある場合
      0b1010,
      0b0101,
      // 3象限
      0b1110,
      0b1101,
      0b1011,
      0b0111,
      // 4象限
      0b1111
    };

    for (const auto& inner_pattern : inner_patterns) {
      result +=
        (c1.pow((inner_pattern >> 3) & 1)) *
        (c2.pow((inner_pattern >> 2) & 1)) *
        (c3.pow((inner_pattern >> 1) & 1)) *
        (c4.pow((inner_pattern >> 0) & 1));
    }

    // 2.
    // 部分集合に含まれるのは、2**n-1 (自分以外は含まれる/含まれないどちらでもいい)
    result += calc_mod<int>(2, MOD).pow(n-1);
  }

  cout << result.n << endl;

  return 0;
}

