	p2[0] = 1;
	for (int i = 1; i < MN; ++i) {
		p2[i] = p2[i - 1] * 2 % MOD;
	}

	rep(i, N) {
		ll a = (p2[num[i][0]] + p2[num[i][3]] - 1) % MOD;
		ll b = (p2[num[i][1]] + p2[num[i][2]] - 1) % MOD;

		ll v = (p2[N] - a * b) % MOD;
		if (v < 0) v += MOD;
		ans = (ans + v) % MOD;
	}

	cout << ans << endl;
	return 0;
}

