//-------------------------------------------------------------------
int M=1;
std::vector<int> seg, seg2;
void init(int N){
  while(M<N) M*=2;
  M=M*2-1;
  for(int i=0;i<M;i++) {
    seg.push_back(0);
    seg2.push_back(0);
  }
}
void update(ll k, int mode){
  k+=(M+1)/2-1;
  (mode==0?seg[k]:seg2[k]) ++;
  while(k>0){
    k = (k-1)/2;
    (mode==0?seg[k]:seg2[k]) = (mode==0?seg[k*2+1]:seg2[k*2+1]) + (mode==0?seg[k*2+2]:seg2[k*2+2]);
  }
}
ll query(int a, int b, int l, int r, int k, int mode){
  if(r<=a||b<=l) return 0;
  if(a<=l&&r<=b) return (mode==0?seg[k]:seg2[k]);
  ll A = query(a, b, l, (l+r)/2, k*2+1, mode);
  ll B = query(a, b, (l+r)/2, r, k*2+2, mode);
  return A+B;
}
