  for(int i=0;i<N;i++)  std::cin >> xy[i][0] >> xy[i][1];
  sort(xy.begin(), xy.end(), [](std::vector<ll> a, std::vector<ll> b){return a[1]<b[1];});
  for(int i=0;i<N;i++) convert.emplace(xy[i][1], convert.size());
  sort(xy.begin(), xy.end());
  init(N);
  vvl data = vv(N, 4, 0, ll);
  for(int i=0;i<N;i++){
    data[i][0] = query(0, convert.at(xy[i][1]), 0, (M+1)/2, 0, 0);
    data[i][1] = query(convert.at(xy[i][1]), N, 0, (M+1)/2, 0, 0);
    update(convert.at(xy[i][1]), 0);
  }
  for(int i=N-1;i>=0;i--){
    data[i][2] = query(0, convert.at(xy[i][1]), 0, (M+1)/2, 0, 1);
    data[i][3] = query(convert.at(xy[i][1]), N, 0, (M+1)/2, 0, 1);
    update(convert.at(xy[i][1]), 1);
  }
  std::vector<ll> p2(N+1, 1);
  for(int i=1;i<=N;i++) p2[i] = (p2[i-1]*2)%P;
  for(int i=0;i<N;i++){
    ll a = (p2[data[i][0]] + p2[data[i][3]]-1)%P;
    ll b = (p2[data[i][2]] + p2[data[i][1]]-1)%P;
    ll v = (p2[N]-a*b)%P;
    if(v<0) v=v+P;
    ans = (ans+v)%P;
  }
  std::cout << ans << '\n';
  return 0;
}

