struct SegTree{
    int v[(1 << 20)];
    private :
    void add(int p, int L, int R, int V)
    {
        if (p + 1 <= L || R <= p)
            return;
        if (L + 1 == R)
        {
            v[V]++;
            return;
        }
        long long M = (L + R) / 2;
        add(p, L, M, 2 * V + 1);
        add(p, M, R, 2 * V + 2);
        v[V] = v[2 * V + 1] + v[2 * V + 2];
    }
    long long summ(int l, int r, int L, int R, int V)
    {
        if (r <= L || R <= l)
            return 0;
        if (l <= L && R <= r)
            return v[V];
        int M = (L + R) / 2;
        return summ(l, r, L, M, 2 * V + 1) + summ(l, r, M, R, 2 * V + 2);
    }
    public :
    long long summ(int l, int r)
    {
        return summ(l, r, 0, n, 0);
    }
    void add(int p)
    {
        add(p, 0, n, 0);
    }
};

map<int, int> xx, yy;
