void pro(vector<pair<int, int> > xy)
{
    //cout << "EEE" << endl << endl;
    sort(xy.begin(), xy.end());
    SegTree ST;
    fill(ST.v, ST.v + (1 << 20), 0);
    for (int i = 0; i < xy.size(); i++)
    {
        int x = xy[i].first;
        int j = i;
        while (j + 1 < xy.size() && xy[j + 1].first == x)
            j++;
        for (int k = i; k <= j; k++)
        {
            //cout << "EE " << ST.summ(0, n) << endl;
            dels.push_back(ST.summ(0, n));
            adds.push_back(ST.summ(0, xy[k].second));
        }
        for (int k = i; k <= j; k++)
        {
            ST.add(xy[k].second);
        }
        i = j;
    }
    return;
}

