long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (int i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % MOD;
		inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}

// 二項係数計算
long long COM(int n, int k) {
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
ll add(ll x, ll y) {
	x += y;
	if (x >= MOD) return x - MOD;
	return x;
}
ll sub(ll x, ll y) {
	x -= y;
	if (x < 0) return x + MOD;
	return x;
}
ll mult(ll x, ll y) {
	return (x * y) % MOD;
}
ll bin_pow(ll x, ll p) {
	if (p == 0) return 1;
	if (p & 1) return mult(x, bin_pow(x, p - 1));
	return bin_pow(mult(x, x), p / 2);
}


typedef pair<Val, Val>P;

WaveletMatrix wm;
void solve() {
	int N; cin >> N;
	vector<Val>X(N), Y(N);
	vector<int>X32(N),Y32(N);
	vector<P>points(N);
	map<int, int>mp;
	set<int>st;
	REP(i, N) {
		int x, y; cin >> x >> y;
		X32[i] = x, Y32[i] = y;
		st.insert(x); st.insert(y);
		//points[i] = {(Val)x,(Val)y};
	}
	int id = 0;
	for (auto x : st) {
		mp[x] = id++;
	}
	REP(i, N) {
		points[i].first = (Val)mp[X32[i]];
		points[i].second = (Val)mp[Y32[i]];
	}
	VSORT(points);
	Val mx = 0;
	REP(i, N) {
		X[i] = points[i].first;
		Y[i] = points[i].second;
		mx = max(mx, Y[i]);
	}
	wm.init(Y);
	ll ans = 0;
	ll sum = sub(bin_pow(2, N), 1);

	REP(i, N) {
		Val x = points[i].first, y = points[i].second;
		//DEBUG(x); DEBUG(y);
		int idX = lb(X, x) - X.begin();
		//DEBUG(idX);
		int A = wm.rangefreq(idX + 1, N, y, mx+1);
		//print("A");
		int B = wm.rangefreq(idX + 1, N, 0, y);
		int C = wm.rangefreq(0, idX, y, mx+1);
		int D = wm.rangefreq(0, idX, 0, y);
		//print("ok");
		//DEBUG(A);
		//DEBUG(B);
		//DEBUG(C);
		//DEBUG(D);
		int cA = sub(bin_pow(2, A), 1);
		int cB = sub(bin_pow(2, B), 1);
		int cD = sub(bin_pow(2, C), 1);
		int cC = sub(bin_pow(2, D), 1);
		ll tmp = cA + cB + cC + cD + cA * cB % MOD + cB * cC % MOD + cC * cD % MOD + cD * cA % MOD;
		tmp %= MOD;
		//DEBUG(tmp);
		ans += sub(sum, tmp);
	}
	print(ans);
}


