    res += (ox[0]*o[1] %MOD)*(o[2]*ox[3]%MOD);
    res %= MOD;
    res += (o[0]*ox[1]%MOD)*(ox[2]*o[3]%MOD);
    res %= MOD;
    res -= (o[0]*o[1]%MOD)*(o[2]*o[3]%MOD);
    res %= MOD;
    res += (ox[0]*ox[1]%MOD)*(ox[2]*ox[3]%MOD);
    res %= MOD;

    return res;
}

