// modを法としたxのy乗を求める。(繰り返し二乗法)
inline llong modPow(llong x, llong y, llong mod)
{
	llong r = 1;
	for (; y > 0; y >>= 1)
	{
		if (y & 1) { r = r * x % mod; }
		x = x * x % mod;
	}
	return r;
}

