	REP(i,N)
	{
		kDTree[i] = { Ps[i].x, Ps[i].y };
	}
	kDTree.build();

	const llong mod = 998244353;

	llong ans = 0;
	REP(i, N)
	{
		P p = Ps[i];

		llong lt = kDTree.range({ 0,       0       }, { p.x,      p.y }).size();
		llong rt = kDTree.range({ p.x + 1, 0       }, { INF(int), p.y }).size();
		llong lb = kDTree.range({ 0,       p.y + 1 }, { p.x,      INF(int) }).size();
		llong rb = kDTree.range({ p.x + 1, p.y + 1 }, { INF(int), INF(int) }).size();

		llong a = 0;
		a += modPow(2, lt + rt, mod) - 1;
		a += modPow(2, rt + rb, mod) - 1;
		a += modPow(2, rb + lb, mod) - 1;
		a += modPow(2, lb + lt, mod) - 1;
		a -= modPow(2, lt, mod) - 1;
		a -= modPow(2, rt, mod) - 1;
		a -= modPow(2, rb, mod) - 1;
		a -= modPow(2, lb, mod) - 1;
		a = (a + mod) % mod;

		a = (modPow(2, N, mod) - 1) - a;

		ans += a;
		ans %= mod;
	}
	WRITE(ans);

}

