struct fentree {
  vector<int> bit;  // binary indexed tree
  int n;

  fentree(int n) {
    this->n = n;
    bit.assign(n, 0);
  }

  fentree(vector<int> a) : fentree(a.size()) {
    for (size_t i = 0; i < a.size(); i++) 
      add(i, a[i]);
  }

  int sum(int r) {
    if (r < 0) return 0;
    int ret = 0;
    for (; r >= 0; r = (r & (r + 1)) - 1)
      ret += bit[r];
    return ret;
  }

  void add(int idx, int delta) {
    for (; idx < n; idx = idx | (idx + 1))
      bit[idx] += delta;
  }
};

const int mod = 998244353;

void add(int &x, int y) {
  x += y;
  if (x >= mod)
    x -= mod;
}

int sub(int x, int y) {
  x -= y;
  if (x < 0)
    x += mod;
  return x;
}

int mult(int x, int y) {
  return (1LL * x * y) % mod;
}

int powmod(long long a, long long b) {
  long long res = 1;
  a %= mod;
  assert(b >= 0);
  for ( ; b; b >>= 1) {
    if (b & 1)
      res = res * a %mod;
    a = a * a % mod;
  }
  return (int) res;
}

