struct pbds_sum {
    //@formatter:off
    template<typename T = int> class BIT {
    public:
        int n;        vector<T> dat;        BIT(int n) : n(n) { dat.assign(n, 0); }        T sum(int k) {            if (k >= n) k = n - 1;            T ret = 0;            for (int x = k - 1; x >= 0; x = (x & (x + 1)) - 1) { ret += dat[x]; }            return ret;        }        T sum(int l, int r) { return sum(r) - sum(l); }        T get(int l, int r) { return sum(r) - sum(l); }        T get(int k) { return sum(k); }        T operator[](int k) {            assert(0 <= k && k < n);            return sum(k + 1) - sum(k);        }        T operator()(int k) { return sum(k); }        T operator()(int l, int r) { return sum(l, r); }        void add(int k, T val = 1) { for (int x = k; x < n; x |= x + 1)dat[x] += val; }        void update(int k, T val = 0) { add(k, -operator[](k) + val); }        void del(int k) { update(k, 0); }        void clear() { fill(dat, 0); }        void debu() {
#ifdef _DEBUG
            vi res;            rep(i, min(10ll, n)) { res.push_back(operator[](i)); }            deb(res);
#endif
        }
        int lower_bound(int w) {            if (w <= 0) return -1;            int x = 0;            int k = 1;            while ((k << 1) <= n) k <<= 1;            for (; k > 0; k >>= 1) {                if (x + k <= n && dat[x + k - 1] < w) {                    w -= dat[x + k - 1];                    x += k;                }            }            return x;        }
    };
    BIT<int> bco, bsu;
    umapi v_i;
    vi i_v;
    int count = 0;
    //クエリの順番が分かってる場合の高速化はとりあえずしない(十分高速なため)
    //クエリの順番が入れ替わってもいいようにする
    pbds_sum(vi &a) : bco(sz(a) + 3), bsu(sz(a) + 3) {        vi b = a;        b.push_back(linf + 100);        i_v = compress(b);        rep(i, sz(a)) { v_i[a[i]] = b[i]; }    }
    pbds_sum(vi &a, vi &b) : bco(sz(a) + sz(b) + 3), bsu(sz(a) + sz(b) + 3) {        vi c = a;        vi d = b;        c.push_back(linf + 100);        d.push_back(linf + 100);        i_v = compress(c, d);        rep(i, sz(a)) {            v_i[a[i]] = c[i];            v_i[b[i]] = d[i];        }    }
    pbds_sum(vi &a, vi &b, vi &c) : bco(sz(a) + sz(b) + sz(c) + 3), bsu(sz(a) + sz(b) + sz(c) + 3) {        vi d = a;        vi e = b;        vi f = c;        d.push_back(linf + 100);        e.push_back(linf + 100);        f.push_back(linf + 100);        i_v = compress(d, e, f);        rep(i, sz(a)) {            v_i[a[i]] = d[i];            v_i[b[i]] = e[i];            v_i[c[i]] = f[i];        }    }
    void add(int v, int c = 1) {count += c;        int ind = v_i[v];        bco.add(ind, c);        bsu.add(ind, v * c);    }
    void operator+=(int v){int c=1;        count += c;        int ind = v_i[v];        bco.add(ind, c);        bsu.add(ind, v * c);    }
    //開区間
    int sum() {return bsu.sum(inf);    }
    int sum(int rv) {        int i = (std::lower_bound(all(i_v), rv) - i_v.begin());        return bsu.sum(i);    }
    //半開区間 l rは存在しない値でもいい
    int sum(int l, int r) { return sum(r) - sum(l); }
    //クエリ候補全ての中でのi
    int sum_it(int li, int ri) {return bsu.sum(ri) - bsu.sum(li);}
    //[l番目からr)番目の合計(種類数ではなく重複込みの番号)
    //r個の合計
    int sum_order(int r) {        int rti = bco.lower_bound(r + 1);        int res = bsu.sum(rti);        if (rti != bco.n) {            int l = bco.sum(rti);            res += (r - l) * i_v[rti];        }        return res;    }
    //右からr個の合計
    int sum_order_r(int r) {        int a = bsu.sum(0, inf);        int b = sum_order(count - r);        return a - b;    }
    /*@formatter:off*/
    int sum_order(int l,int r){return sum_order(r)-sum_order(l);}
    int cou(int rv) {int i = (std::lower_bound(all(i_v), rv) - i_v.begin());return bco.sum(i);}
    //半開区間 l rは存在しない値でもいい
    int cou(int l, int r) { return cou(r) - cou(l); }
    int cou_it(int ri) {        return bco.sum(ri);    }
    int cou_it(int li, int ri) {        return bco.sum(ri) - bco.sum(li);    }
    //k番目の要素を返す
    int find_by_order(int k) {        int i = bco.lower_bound(k + 1);        if (i >= sz(i_v)) {            cerr << "find_by_order(" << k << ") k >=" << sz(i_v) << endl;            exit(0);        }        return i_v[i];    }
    //vは何番目に入るか
    int order_of_key(int v) {        v = *std::lower_bound(all(i_v), v);        int i = v_i[v];        return bco.sum(i);    }
    //中央値を返す (左寄り)
    int mid() { return find_by_order((count - 1) >> 1); }
    int mid(int lv, int rv) {        int lcou = cou(lv);        int rcou = cou(rv);        int wantk = lcou + ((rcou - lcou - 1) >> 1);        return find_by_order(wantk);    }
    int mid_it(int li, int ri) {        int lcou = bco.sum(li );        int rcou = bco.sum(ri );        int wantk = lcou + ((rcou - lcou - 1) >> 1);        return find_by_order(wantk);    }
    int mid_it(int ri) {        return mid_it(0, ri);    }
    //全要素との 最小の差の和をかえす (全要素の中央値との差の和)
    int min_dis() {        int mv = mid();        int mi = v_i[mv];        int lcou = bco.sum(mi);        int rcou = bco.sum(mi + 1, linf);        int lsum = mv * lcou - bsu.sum(mi);        int rsum = bsu.sum(mi + 1, linf) - mv * rcou;        return lsum + rsum;    }
    int min_dis(int lv, int rv) {        int li = (std::lower_bound(all(i_v), lv) - i_v.begin());        int ri = (std::lower_bound(all(i_v), rv) - i_v.begin());        int mv = mid_it(li, ri);        int mi = v_i[mv];        int lcou = cou_it(li, mi);        int rcou = cou_it(mi, ri);        return mv * lcou - sum_it(li, mi) + sum_it(mi, ri) - mv * rcou;    }
    int min_dis_i(int li, int ri) {        int mv = mid_it(li, ri);        int mi = v_i[mv];        int lcou = cou_it(li, mi);        int rcou = cou_it(mi, ri);        return mv * lcou - sum_it(li, mi) + sum_it(mi, ri) - mv * rcou;    }
    //vをc個消す
    void erase(int v, int c = 1) {        int ind = v_i[v];        if(bco[ind] < c){            if(count ==0){                cerr<<"all is empty. count == 0"<< endl;            }            assert(bco[ind] < c);        }        count -= c;        bco.add(ind, -c);        bsu.add(ind, v * -c);    }
    void operator-=(int v){erase(v);}
    int lower_bound(int v) {        v = *std::lower_bound(all(i_v), v);        int i = v_i[v];        int needc = bco.sum(i) + 1;        i = bco.lower_bound(needc);        return i_v[i];    }
    int upper_bound(int v) { return lower_bound(v + 1); }
    void debu(){        bsu.debu();        bco.debu();        cerr<<""<<endl;    }
    //@formatter:on
};

