    for(int i=0; i<N; i++) {
        int x, y; scanf("%d%d", &x, &y);
        points[i] = make_tuple(x, y, i);
    }

    // x 座標の座圧
    int M = 0;
    map<ll, ll> cmpx;
    for(auto p : points) cmpx[ get<0>(p) ]++;
    for(auto &e : cmpx) e.second = M++;


    vector<ll> lu(N), rd(N), ld(N), ru(N);
    sort(points.begin(), points.end(), [&](Tuple a, Tuple b) {
            ll ax, ay, az; tie(ax, ay, az) = a;
            ll bx, by, bz; tie(bx, by, bz) = b;

            // y の小さい順 -> x の大きい順
            if(ay != by) return ay < by;
            return ax > bx;
        });

    auto f = [](ll a, ll b) { return a + b; };
    ll E = 0;

    {        
        SegmentTree<ll> seg(M, E, f, f);

        for(int i=0; i<N; i++) {
            ll x, y, k; tie(x, y, k) = points[i];

            // x 座標が自分以上のもの
            rd[k] = seg.query(cmpx[x], M);
            seg.update(cmpx[x], 1);
        }
    }

    sort(points.begin(), points.end(), [&](Tuple a, Tuple b) {
            ll ax, ay, az; tie(ax, ay, az) = a;
            ll bx, by, bz; tie(bx, by, bz) = b;

            // y の大きい順 -> x の小さい順
            if(ay != by) return ay > by;
            return ax < bx;
        });    
    {
        SegmentTree<ll> seg(M, E, f, f);

        for(int i=0; i<N; i++) {
            ll x, y, k; tie(x, y, k) = points[i];

            // x 座標が自分以下のもの
            lu[k] = seg.query(0, cmpx[x] + 1);
            seg.update(cmpx[x], 1);
        }
    }

    sort(points.begin(), points.end(), [&](Tuple a, Tuple b) {
            ll ax, ay, az; tie(ax, ay, az) = a;
            ll bx, by, bz; tie(bx, by, bz) = b;

            // y の大きい順 -> x の大きい順
            if(ay != by) return ay > by;
            return ax > bx;
        });    
    {
        SegmentTree<ll> seg(M, E, f, f);

        for(int i=0; i<N; i++) {
            ll x, y, k; tie(x, y, k) = points[i];

            // x 座標が自分以上のもの
            ru[k] = seg.query(cmpx[x], M);
            seg.update(cmpx[x], 1);
        }
    }

    sort(points.begin(), points.end(), [&](Tuple a, Tuple b) {
            ll ax, ay, az; tie(ax, ay, az) = a;
            ll bx, by, bz; tie(bx, by, bz) = b;

            // y の小さい順 -> x の小さい順
            if(ay != by) return ay < by;
            return ax < bx;
        });    
    {
        SegmentTree<ll> seg(M, E, f, f);

        for(int i=0; i<N; i++) {
            ll x, y, k; tie(x, y, k) = points[i];

            // x 座標が自分以下のもの
            ld[k] = seg.query(0, cmpx[x] + 1);
            seg.update(cmpx[x], 1);
        }
    }

    ll ans = 0;
    for(int i=0; i<N; i++) {
        // fprintf(stderr, "lu[%d] = %lld, rd[%d] = %lld, ld = %lld, ru = %lld\n", i, lu[i], i, rd[i], ld[i], ru[i]);

        ll sum = 0;

        // 自分を含む集合の数 (自分以外の選び方がどうでもよい)
        (sum += mod_pow(2, N-1)) %= MOD;

        ll x = lu[i], y = rd[i], z = ld[i], w = ru[i];
        ll px = (mod_pow(2, x) + MOD - 1) % MOD;
        ll py = (mod_pow(2, y) + MOD - 1) % MOD;
        ll pz = (mod_pow(2, z) + MOD - 1) % MOD;
        ll pw = (mod_pow(2, w) + MOD - 1) % MOD;

        ll sub = 0;
        (sub += px * py) %= MOD;
        (sub += px * py % MOD * pz) %= MOD;
        (sub += px * py % MOD * pw) %= MOD;
        (sub += px * py % MOD * pz % MOD * pw % MOD) %= MOD;

        (sub += pz * pw) %= MOD;
        (sub += pz * pw % MOD * px) %= MOD;
        (sub += pz * pw % MOD * py) %= MOD;

        // 自分は含まないが、他の 2 点によって含まれるものの数
        // 少なくとも 1 つの lu かつ少なくとも 1 つの rd
        // 自分以外の N-1 点に着目して、
        // lu だけ含まないもの・rd だけ含まないもの・どちらも含まないもの を引いたほうがいい？？

        (sum += sub) %= MOD;

        (ans += sum) %= MOD;
    }
    cout << ans << endl;
    return 0;
}

