  vll under_left(n);
  vll upper_left(n);

  vll under_right(n);
  vll upper_right(n);

  set<ll> yp;
  rep(i, n) {
    const auto& p = points[i];
    auto itr = yp.lower_bound(p.second);
    upper_left[i] = yp.size() - distance(yp.begin(), itr);
    under_left[i] = yp.size() - upper_left[i];
    yp.insert(p.second);
  }

  yp.clear();

  for (ll i = n - 1; i >= 0; i--) {
    const auto& p = points[i];
    auto itr = yp.lower_bound(p.second);
    upper_right[i] = yp.size() - distance(yp.begin(), itr);
    under_right[i] = yp.size() - upper_right[i];
    yp.insert(p.second);
  }

  vector<mint> p2(n + 1);
  p2[0] = 1;
  REP(i, n + 1) {
    p2[i] = p2[i - 1] * 2;
  }

  mint ans = 0;
  rep(i, n) {
    mint ptn = p2[n - 1];
    ptn += (p2[upper_left[i]] - 1) * (p2[under_right[i]] - 1) *
           (p2[n - 1 - upper_left[i] - under_right[i]] - (p2[under_left[i]] - 1) * (p2[upper_right[i]] - 1));
    ptn += (p2[under_left[i]] - 1) * (p2[upper_right[i]] - 1) * p2[n - 1 - under_left[i] - upper_right[i]];
    ans += ptn;
  }

  cout << ans << endl;

  return 0;
}

