  sort(yc.begin(), yc.end());

  map<int, int> mpx, mpy;
  int cur = 1;
  for (int i = 0; i < n; i++)
    mpx[xc[i]] = cur++;
  cur = 1;
  for (int i = 0; i < n; i++)
    mpy[yc[i]] = cur++;

