  ft = fentree(n + 1);
  for (int i = n - 1; i >= 0; i--) {
    int bawah = ft.sum(a[i][1]);
    a[i][2] = n - 1 - i - bawah;
    a[i][3] = n - 1 - i - a[i][2];
    ft.add(a[i][1], 1);
  }

  int ans = mult(n, powmod(2, n - 1));
  for (int i = 0; i < n; i++) {
