template<unsigned P> struct ModInt {
  using M = ModInt;
  unsigned v;
  ModInt() : v(0) {}
  ModInt(auto x) : v(x >= 0 ? x % P : (P - -x % P) % P) {}
  constexpr ModInt(unsigned v, int) : v(v) {}
  static constexpr unsigned p() { return P; }
  M operator+() const { return *this; }
  M operator-() const { return {v ? P - v : 0, 0}; }
  explicit operator bool() const noexcept { return v; }
  bool operator!() const noexcept { return !(bool)*this; }
  M operator*(M r) const { return M(*this) *= r; }
  M operator/(M r) const { return M(*this) /= r; }
  M operator+(M r) const { return M(*this) += r; }
  M operator-(M r) const { return M(*this) -= r; }
  bool operator==(M r) const { return v == r.v; }
  bool operator!=(M r) const { return !(*this == r); }
  M& operator*=(M r) { v = (uint64_t)v * r.v % P; return *this; }
  M& operator/=(M r) { return *this *= r.inv(); }
  M& operator+=(M r) { if ((v += r.v) >= P) v -= P; return *this; }
  M& operator-=(M r) { if ((v += P - r.v) >= P) v -= P; return *this; }
  M inv() const {
    int a = v, b = P, x = 1, u = 0;
    while (b) {
      int q = a / b;
      swap(a -= q * b, b);
      swap(x -= q * u, u);
    }
    assert(a == 1);
    return x;
  }
  M pow(auto n) const {
    if (n < 0) return pow(-n).inv();
    M res = 1;
    for (M a = *this; n; a *= a, n >>= 1) if (n & 1) res *= a;
    return res;
  }
  friend M operator*(auto l, M r) { return M(l) *= r; }
  friend M operator/(auto l, M r) { return M(l) /= r; }
  friend M operator+(auto l, M r) { return M(l) += r; }
  friend M operator-(auto l, M r) { return M(l) -= r; }
  friend ostream& operator<<(ostream& os, M r) { return os << r.v; }
  friend istream& operator>>(istream& is, M& r) { lint x; is >> x; r = x; return is; }
  friend bool operator==(auto l, M r) { return M(l) == r; }
  friend bool operator!=(auto l, M r) { return !(l == r); }
};
using Mint = ModInt<998244353>;

template<class T> struct FenwickTree {
  const int n;
  V<T> t;
  FenwickTree(int n) : n(n), t(n + 1) {}
  void add(int i, T x) { for (++i; i <= n; i += i & -i) t[i] += x; }
  T sum(int i) const {
    T s = 0;
    for (; i; i -= i & -i) s += t[i];
    return s;
  }
  T sum(int l, int r) const { return sum(r) - sum(l); }
};

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  int n; cin >> n;
  V<> x(n), y(n); for (int i = 0; i < n; ++i) cin >> x[i] >> y[i];
  {
    auto xs = x;
    sort(begin(xs), end(xs));
    xs.erase(unique(begin(xs), end(xs)), end(xs));
    for (auto&& e : x) e = lower_bound(begin(xs), end(xs), e) - begin(xs);
    auto ys = y;
    sort(begin(ys), end(ys));
    ys.erase(unique(begin(ys), end(ys)), end(ys));
    for (auto&& e : y) e = lower_bound(begin(ys), end(ys), e) - begin(ys);
  }

  V<> cx(n + 1), cy(n + 1);
  for (int i = 0; i < n; ++i) {
    ++cx[x[i]];
    ++cy[y[i]];
  }
  for (int i = n - 1; i >= 0; --i) {
    cx[i] += cx[i + 1];
    cy[i] += cy[i + 1];
  }

  V<> idx(n);
  iota(begin(idx), end(idx), 0);
  sort(begin(idx), end(idx), [&](int i, int j) { return make_pair(x[i], y[i]) < make_pair(x[j], y[j]); });
  FenwickTree<int> ftl(n), ftr(n);
  for (int e : y) ftr.add(e, 1);
  auto il = begin(idx), ir = begin(idx);

  auto fn = [](int m) -> Mint { return Mint(2).pow(m) - 1; };
  Mint res;
  for (int i : idx) {
    while (il != end(idx) and x[*il] < x[i]) {
      ftl.add(y[*il++], 1);
    }
    while (ir != end(idx) and x[*ir] <= x[i]) {
      ftr.add(y[*ir++], -1);
    }

    Mint curr = fn(n);
    curr -= fn(cx[x[i] + 1]);
    curr -= fn(n - cx[x[i]]);
    curr -= fn(cy[y[i] + 1]);
    curr -= fn(n - cy[y[i]]);
    curr += fn(ftl.sum(y[i]));
    curr += fn(ftl.sum(y[i] + 1, n));
    curr += fn(ftr.sum(y[i]));
    curr += fn(ftr.sum(y[i] + 1, n));
    res += curr;
  }
  cout << res << '\n';
}

