      seg_vec[i] = seg_func(seg_vec[i*2+1], seg_vec[i*2+2]);
    }
  }
  T query(int a, int b){
    return query_partial(a, b, 0, 0, nbin);
  }
};

long long mod_pow2(long long n){
  long long ans = 1, np = 2;
  while(n > 0){
    if(n&1) ans = (ans*np)%mod;
    np = (np*np)%mod;
    n >>= 1;
  }
  return ans;
}

