// 0-indexed
template <class T> class SegmentTreeSparse {
    long long size;
    T def;
    unordered_map<long long, T> data;
    function<T(T, T)> f;

  public:
    SegmentTreeSparse<T>(long long _size, T _def, function<T(T, T)> _f) : f(_f), def(_def), size(1) {
        while (size < _size) size <<= 1;
    }
    // bottom-up implementation
    // query for[l, r)
    T query(long long l, long long r) {
        l++, r++;
        T L = def, R = def;
        for (l += size, r += size; l < r; l >>= 1, r >>= 1) {
            if (l & 1) {
                if (data.end() != data.find(l)) L = f(L, data[l]);
                l++;
            }
            if (r & 1) {
                r--;
                if (data.end() != data.find(r)) R = f(data[r], R);
            }
        }
        return f(L, R);
    }
    void update(long long idx, T val) {
        idx += size + 1;
        data[idx] = val;
        while (idx >= 1) {
            idx >>= 1;
            bool findL = (data.end() == data.find(2 * idx));
            bool findR = (data.end() == data.find(2 * idx + 1));
            T lv = findL ? def : data[2 * idx];
            T rv = findR ? def : data[2 * idx + 1];
            data[idx] = f(lv, rv);
        }
    }
    T operator[](long long idx) {
        idx += size + 1;
        return (data.end() != data.find(idx)) ? data[idx] : def;
    }
};

