void compress(vector<int> &v) {
    vector<int> w(v);
    sort(w.begin(), w.end());
    for (int i=0; i<(int)v.size(); ++i) {
        v[i] = lower_bound(w.begin(), w.end(), v[i]) - w.begin();
    }
}

class BIT {
public:
    int n;
    vector<int> nodes;
    BIT(int n): n(n+1), nodes(n+1, 0) {}

    void add(int i, int v) {
        nodes[++i] += v;
        for (i+=i&(-i); i<=n; i+=i&(-i)) nodes[i] += v;
    }
    int sum(int i) {
        int res = nodes[++i];
        for (i-=i&(-i); i>0; i-=i&(-i)) res += nodes[i];
        return res;
    }
};

long long modpow(long long a, long long n) {
    if (n == 0) return 1;
    a %= mod;
    if (n % 2 == 0) {
        long long t = modpow(a, n/2);
        return (t * t) % mod;
    }
    return (modpow(a, n-1) * a) % mod;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    // rdfile("_input.txt");

