vi segsum;
ll N=1;
ll pow(ll a,ll p){
    a%=mod;
    if(p==0)return 1;
    if(p&1)return (a*pow(a,p-1))%mod;
    return (pow(a,p/2)*pow(a,p/2))%mod;
}
void update(ll i,ll x){
    i=N+i-1;
    segsum[i]=x;
    while(i>0){
        i=(i-1)/2;
        segsum[i]=segsum[i*2+1]+segsum[i*2+2];
    }
}
ll sum(ll a,ll b,ll k,ll l,ll r){
    if(r<=a||b<=l)return 0;
    if(a<=l&&r<=b)return segsum[k];
    ll c1=sum(a,b,k*2+1,l,(l+r)/2);
    ll c2=sum(a,b,k*2+2,(l+r)/2,r);
    return c1+c2;
}
vi so;
ll id(ll i){
    return lb(so,i);
}
int main(){
    ll n;cin>>n;
    vvi res(4,vi(n));
    while(N<n)N*=2;
    segsum=vi(N*2-1);
    vector<P> v(n);
    rep(i,n)cin>>v[i].fi>>v[i].se;
    so=vi(n);
    rep(i,n)so[i]=v[i].se;
    sort(all(so));
    sort(all(v));
    rep(i,n){
        update(id(v[i].se),segsum[id(v[i].se)+N-1]+1);
        res[1][i]=sum(0,id(v[i].se),0,0,N);
        res[0][i]=i-res[1][i];
    }
    segsum=vi(N*2-1);
    reverse(all(v));
    rep(i,n){
        update(id(v[i].se),segsum[id(v[i].se)+N-1]+1);
        res[3][n-1-i]=sum(0,id(v[i].se),0,0,N);
        res[2][n-1-i]=i-res[3][n-1-i];
    }
    ll ans=0;
    rep(i,n){
        ans+=pow(2,n-1);
        ans+=(pow(2,res[0][i])-1)*(pow(2,res[1][i])-1)%mod*(pow(2,res[2][i])-1)%mod*(pow(2,res[3][i])-1)%mod;
        ans+=(pow(2,res[0][i])-1)*(pow(2,res[1][i])-1)%mod*(pow(2,res[2][i])-1)%mod;
        ans+=(pow(2,res[0][i])-1)*(pow(2,res[1][i])-1)%mod*(pow(2,res[3][i])-1)%mod;
        ans+=(pow(2,res[0][i])-1)*(pow(2,res[3][i])-1)%mod*(pow(2,res[2][i])-1)%mod;
        ans+=(pow(2,res[3][i])-1)*(pow(2,res[1][i])-1)%mod*(pow(2,res[2][i])-1)%mod;
        ans+=(pow(2,res[2][i])-1)*(pow(2,res[1][i])-1)%mod;
        ans+=(pow(2,res[3][i])-1)*(pow(2,res[0][i])-1)%mod;
    }
    cout<<ans%mod<<endl;
}

