int cmp_y(const pair<int, int> &a, const pair<int, int> &b) {
	return a.second < b.second;
}

int main() {
	scanf("%d", &n);

	for(int i=0;i<n;i++)
		scanf("%d%d", &a[i].first, &a[i].second);

	sort(a, a+n, cmp_x);
	for(int i=0;i<n;i++) a[i].first = i+1;
	sort(a, a+n, cmp_y);
	for(int i=0;i<n;i++) a[i].second = i+1;

	pw[0] = 0;
	for(int i=1;i<=n;i++)
		pw[i] = ma.add(ma.mul(pw[i-1], 2), 1);

	int res = ma.mul(n, pw[n]);

	sort(a, a+n, cmp_x);
	b.max_val = n;
	b.clear();
	for(int i=0;i<n;i++) {
		res = ma.sub(res, pw[i]);
		res = ma.sub(res, pw[n-i-1]);

		res = ma.add(res, pw[b.query(1, a[i].second - 1)]);
		res = ma.add(res, pw[b.query(a[i].second + 1, n)]);
		b.add(a[i].second, 1);
	}
	b.clear();
	for(int i=n-1;i>=0;i--) {
		res = ma.add(res, pw[b.query(1, a[i].second - 1)]);
		res = ma.add(res, pw[b.query(a[i].second + 1, n)]);
		//printf("add: %d\n", a[i].second);
		b.add(a[i].second, 1);
	}

	sort(a, a+n, cmp_y);
	for(int i=0;i<n;i++) {
		res = ma.sub(res, pw[i]);
		res = ma.sub(res, pw[n-i-1]);
	}

	printf("%d\n", res);

	return 0;
}

