ll mod_pow(ll a, ll n) {
	if(n == 0) return 1;
	ll res = mod_pow(a, n / 2);
	if(n % 2 == 0) return res * res % mod;
	else return a * res % mod * res % mod;
}

ll invf(ll a) {
	return mod_pow(a, mod - 2);
}


void C_init(int n) {
	fac[0] = fac[1] = 1; inv[1] = 1;
	fiv[0] = fiv[1] = 1;
	rep(i, 2, n + 1) {
		fac[i] = fac[i - 1] * i % mod;
		inv[i] = mod - inv[mod % i] * (mod / i) % mod;
		fiv[i] = fiv[i - 1] * inv[i] % mod;
	}
}

ll C(int a, int b) { //assume a >= b
	if(a < b || a < 0 || b < 0) return 0;
	return fac[a] * fiv[b] % mod * fiv[a - b] % mod;
}


struct BIT { //0-origin!!! update and get just like lazy_segtree
	int n; vl bit0, bit1;
	void init(int mx) {
		n = mx;
		bit0 = vl(n + 1, 0); bit1 = vl(n + 1, 0);
	}
	BIT(int mx = 0) { init(mx); } 

	ll ga(vl& bit, int i) {
		ll s = 0;
		while(i > 0) { s += bit[i]; i -= i & -i; }
		return s;
	}
	void app(vl& bit, int i, ll x) {
		while(i <= n) { bit[i] += x; i += i & -i; }
	}
	void update(int a, int b, ll x) { //[a, b)
		a++;
		app(bit0, a, -x * (a - 1));
		app(bit1, a, x);
		app(bit0, b + 1, x * b);
		app(bit1, b + 1, -x);
	}
	ll get(int a, int b) { //[a, b)
		a++;
		return (ga(bit1, b) * b + ga(bit0, b)) 
			- (ga(bit1, a - 1) * (a - 1) + ga(bit0, a - 1));
	}
};

int N;
ll X[MAX_N], Y[MAX_N];

pl query[MAX_N];

ll cnt[MAX_N][4];

int fd(vl& vec, ll a) {
	return lower_bound(all(vec), a) - vec.begin();
}

void pre(int q) {
	vl vx, vy;
	rep(i, 0, N) {
		vx.pb(X[i]);
		vy.pb(Y[i]);
	}
	sort(all(vx));
	sort(all(vy));

	rep(i, 0, N) {
		int xid = fd(vx, X[i]);
		int yid = fd(vy, Y[i]);
		query[yid] = pl(xid, i);
	}

	BIT bit(N);

	rep(i, 0, N) {
		int idx = query[i].fst;
		int id = query[i].sec;
		cnt[id][q] = bit.get(0, idx);
		bit.update(idx, idx + 1, 1);
	}
}

void solve() {
	cin >> N;
	rep(i, 0, N) cin >> X[i] >> Y[i];
	rep(q, 0, 4) {
		pre(q);
		rep(i, 0, N) {
			ll x = X[i], y = Y[i];
			X[i] = -y;
			Y[i] = x;
		}
	}
	ll ans = 0;
	rep(i, 0, N) {
		// debug(i, vi(cnt[i], cnt[i] + 4));
		ll tmp = 0;
		ADD(tmp, mod_pow(2, N));
		ADD(tmp, mod - 1); // -1
		rep(q, 0, 4) {
			ADD(tmp, mod - mod_pow(2, cnt[i][q]) + 1);
		}
		rep(q, 0, 4) {
			int c0 = cnt[i][q], c1 = cnt[i][(q + 1) % 4];
			ADD(tmp, mod - (mod_pow(2, c0) - 1) * (mod_pow(2, c1) - 1) % mod);
		}
		ADD(ans, tmp);
	}
	cout << ans << "\n";
}

