int N, MOD = 998244353, cnt;
int BIT[200020], s[4][200020];
long pow2[200020];
vector<pair<int,int>> p;

// 集合すべて(2^n-1)　に対して　集合の中の個数　をもとめる。
// その個数は　それが含まれる集合分足される。
// ｎ個の座標について、それが含まれる集合を数えればよい。
// 自分より大きい、小さいx座標の点, y座標の点の数(4種類)を全ての点に対して数える。

void add(int i) {
    for(;i <= N; i += i & -i) BIT[i] += 1;
}

int sum(int i) {
    int ret = 0;
    for(;i > 0; i -= i & -i) ret += BIT[i];
    return ret;
}

int main() {
    cin >> N;
    p.resize(N);
    for(int i = 0; i < N; ++i) cin >> p[i].first >> p[i].second;
    map<int,int> x, y;

    // 座圧
    cnt = 0;
    for(int i = 0; i < N; ++i) x[p[i].first] = 0;
    for(auto itr = x.begin(); itr != x.end(); ++itr) itr->second = ++cnt;
    for(int i = 0; i < N; ++i) p[i].first = x[p[i].first];

    cnt = 0;
    for(int i = 0; i < N; ++i) y[p[i].second] = 0;
    for(auto itr = y.begin(); itr != y.end(); ++itr) itr->second = ++cnt;
    for(int i = 0; i < N; ++i) p[i].second = y[p[i].second];
    sort(p.begin(), p.end());

    // x座標　昇順
    // 今見てるのより(x, y) = (小　小)-s[0]　(小　大)-s[1]　（大　小）-s[2]　（大　大）-s[3]
    for(int i = 1; i <= N; ++i) BIT[i] = 0;
    for(int i = 0; i < N; ++i) {
        s[0][i] = sum(p[i].second);
        s[1][i] = i - s[0][i];
        add(p[i].second);
    }

    for(int i = 1; i <= N; ++i) BIT[i] = 0;
    for(int i = N-1; i >= 0; --i) {
        s[2][i] = sum(p[i].second);
        s[3][i] = (N-1-i) - s[2][i];
        add(p[i].second);
    }

    // calc 2^n
    pow2[0] = 1;
    for(int i = 1; i <= N; ++i) pow2[i] = pow2[i-1] * 2 % MOD;

    long ans = 0;
    for(int i = 0; i < N; ++i) {
        int tmp1[4], tmp2[4];
        for(int j = 0; j < 4; ++j) {
            tmp1[j] = pow2[s[j][i]]; // 位置jの点を選ぶか選ばないか未定
            tmp2[j] = tmp1[j] - 1; // 位置jの点を必ず選ぶ
        }
        ans = (ans + tmp2[0] * tmp1[1] % MOD * tmp1[2] % MOD * tmp2[3] % MOD) % MOD;
        ans = (ans + tmp1[0] * tmp2[1] % MOD * tmp2[2] % MOD * tmp1[3] % MOD) % MOD;
        ans = (ans - tmp2[0] * tmp2[1] % MOD * tmp2[2] % MOD * tmp2[3] % MOD + MOD) % MOD;
        ans = (ans + tmp1[0] * tmp1[1] % MOD * tmp1[2] % MOD * tmp1[3] % MOD) % MOD;
    }

    cout << ans;
    return 0;
}

