  }
  sort(ALL(x));
  x.erase(unique(ALL(x)), x.end());
  sort(ALL(y));
  y.erase(unique(ALL(y)), y.end());
  REP(i, n) {
    xy[i].first = lower_bound(ALL(x), xy[i].first) - x.begin();
    xy[i].second = lower_bound(ALL(y), xy[i].second) - y.begin();
  }
  sort(ALL(xy));
  long long ans = n * mod_pow(2, n - 1) % MOD;
  BIT<int> left(n), right(n);
  REP(i, n) right.add(i, 1);
  REP(i, n) {
    int x = xy[i].first, y = xy[i].second;
    right.add(y, -1);
    int lu = left.sum(y + 1, n - 1), ru = right.sum(y + 1, n - 1);
    int ld = left.sum(0, y - 1), rd = right.sum(0, y - 1);
    // cout << lu << ' ' << ru << ' ' << ld << ' ' << rd << '\n';
    (ans += (mod_pow(2, ld) - 1) * (mod_pow(2, ru) - 1) % MOD * mod_pow(2, lu + rd) % MOD) %= MOD;
    (ans += (mod_pow(2, lu) - 1) * (mod_pow(2, rd) - 1) % MOD * mod_pow(2, ru + ld) % MOD) %= MOD;
    ans -= (mod_pow(2, ld) - 1) * (mod_pow(2, ru) - 1) % MOD * (mod_pow(2, lu) - 1) % MOD * (mod_pow(2, rd) - 1) % MOD;
    (ans += MOD) %= MOD;
    left.add(y, 1);
  }
  cout << ans << '\n';
  return 0;
}

