Int get_sum(Int pos){
    if(pos < 0)return 0;
    pos++;
    Int sum = 0;
    while(pos){
        sum += bit[pos];
        pos -= pos & -pos;
    }
    return sum;
}

void add_val(Int pos, Int val){
    pos++;
    while(pos < 2016000){
        bit[pos] += val;
        pos += pos & -pos;
    }
}

Int mod_pow(Int x, Int a, Int m = MOD){
    if(a == 0)return 1;
    Int res = mod_pow(x, a / 2, m);
    res = res * res % m;
    if(a % 2)res *= x;
    return res % m;
}

Int inv(Int x, Int m = MOD){
    return mod_pow(x, m-2, m);
}


