            }
            if(c){
                ans += power(2, s, mod) * (c + 1) % mod - power(2, a + b, mod) * (2 * c + 1) % mod + mod;
            }
            ans += (b + 2) * power(2, s, mod) % mod;
            ans %= mod;
        }
    }
    cout << ans << endl;
}

