void solve() {
  int n;
  cin >> n;
  vector<pair<int, int>> xy;
  rep(i, n) {
    int x, y;
    cin >> x >> y;
    xy.emplace_back(x, y);
  }
  vi32 lstx;
  rep(i, n) lstx.emplace_back(xy[i].first);
  sort(all(lstx));
  vi32 lsty;
  rep(i, n) lsty.emplace_back(xy[i].second);
  sort(all(lsty));
  auto convx = [&](int x){
    int i = lower_bound(all(lstx), x) - lstx.begin();
    return i;
  };
  auto convy = [&](int y){
    int i = lower_bound(all(lsty), y) - lsty.begin();
    return i;
  };
  vector<vi32> sums(n + 1, vi32(n + 1));
  rep(i, n) {
    int x, y;
    tie(x, y) = xy[i];
    int wx = convx(x);
    int wy = convy(y);
    sums[wx + 1][wy + 1] = 1;
  }
  reps(i, n) reps(j, n) {
    sums[i][j] += sums[i-1][j] + sums[i][j-1] - sums[i-1][j-1];
  }
  vector<mint> pow2(n + 1);
  pow2[0] = 1;
  rep(i, n) pow2[i + 1] = pow2[i] * 2;

  mint ans = 0;
  rep(i, n) {
    int x, y;
    tie(x, y) = xy[i];
    int wx = convx(x);
    int wy = convy(y);

    int lu = sums[wx][wy];
    int ru = sums[wx][n] - sums[wx][wy];
    int ld = sums[n][wy] - sums[wx][wy];
    int rd = n - lu - ru - ld - 1;

    mint temp = pow2[n - 1];
    temp += (pow2[lu] - 1) * (pow2[rd] - 1) * pow2[ru] * pow2[ld];
    temp += (pow2[ru] - 1) * (pow2[ld] - 1) * pow2[lu] * pow2[rd];
    temp -= (pow2[lu] - 1) * (pow2[rd] - 1) * (pow2[ru] - 1) * (pow2[ld] - 1);
    ans += temp;
  }
  cout << ans << endl;
}

