        return res *= a;
    }
    mint pow(ll t) const { // mint(a).pow(t) tは余りとったりしたらあかん
        if (t == 0) return 1;
        mint a = pow(t >> 1); // 再帰
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    // 逆元
    mint inv() const {
        return pow(mod - 2);
    }
    mint& operator /= (const mint a) { // invを利用
        return (*this) *= a.inv();
    }
    mint operator / (const mint a) const {
        mint res(*this);
        return res /= a;
    }
};

template<typename T>
struct BIT {
    int n;
    vector<T> d;
    BIT(int n = 0) : n(n), d(n + 1) {}
    void add(int i, T x = 1) {
        // 0indexedの配列でindexが指定される BIT内では1indexed
        // 指定されたindexに1をたす
        for (i++; i <= n; i += i & -i) d[i] += x; // 最下位ビットを足していく
    }
    T sum(int i) {
        T x = 0;
        for (i++; i; i -= i & -i) x += d[i]; // 最下位ビットを落としてく
        return x; // 左端から指定されたindexまでの和
    }
};

// 右上、右下、左上、左下の点の個数
mint f (int a, int b, int c, int d) {
    mint res = 0;
    vector<int> num = {a, b, c, d};
    vector<mint> o(4), ox(4);
    rep(i, 4) {
        ox[i] = mint(2).pow(num[i]);
        o[i] = ox[i] - 1;
    }
    // 集合に自身を含まない
    res += ox[0] * o[1] * o[2] * ox[3];
    res += o[0] * ox[1] * ox[2] * o[3];
    res -= o[0] * o[1] * o[2] * o[3];

    res += ox[0] * ox[1] * ox[2] * ox[3]; // 集合に自身を含めば、あとの点はどうでもいい
    return res;
}

