    rep(i, n) cin >> v[i].F >> v[i].S;

    // 座標圧縮 x
    { // 変数とか生き残らせない
        map<int, int> mp;
        rep(i, n) mp[v[i].F] = 0; // key = x
        int j = 0;
        for (auto&& x : mp) x.S = j++; // && : 値書き換え(昇順に)
        rep(i, n) v[i].F = mp[v[i].F];
    }
    {
        map<int, int> mp;
        rep(i, n) mp[v[i].S] = 0; // key = x
        int j = 0;
        for (auto&& x : mp) x.S = j++; // && : 値書き換え(昇順に)
        rep(i, n) v[i].S = mp[v[i].S];
    }
    // なるほど、2次元のvector内で大小関係変えずに圧縮できた

    sort(all(v)); // xで

    vector<int> a(n), b(n), c(n), d(n); // ある点pに関して、4方向の領域

    rep(_, 2) {
        BIT<int> bit(n);
        rep(i, n) { // すべての点について
            // xに関して昇順に見てるからxが自分より小さいの
            b[i] = bit.sum(v[i].S); // yが自分より小さいの(BITに自分はまだ入ってない)
