            bit.add(v[i].S); // BITに自分(y)を入れる
        }
        reverse(all(v)); // xが大きい方から見る

        // まずcに送る
        // もう1回swapしてa, c元どおり
        swap(a, c);
        swap(b, d);
    }
    reverse(all(c));
    reverse(all(d));
    mint ans = 0;
    rep(i, n) ans += f(a[i], b[i], c[i], d[i]);
    out(ans.x);

}

