modint beki[200100];

void solve(){
  ini(N);
  vector<P> v(N); in(v);

  beki[0] = 1;
  for(int i = 1; i <= N ; i++) beki[i] = beki[i-1] * 2;

  vi unzip(N);
  rep(i , N) unzip[i] = v[i].se;
  compress<int> zip(unzip);
  rep(i , N) v[i].se = zip.get(v[i].se);

  sort(all(v));

  BIT<int> bit(N + 1);
  modint ans = 0;
  trc(v);
  rep(i , N){
    ans += beki[N - 1];

    int ld = bit.sum(v[i].se - 1);
    int lu = i - ld;
    int rd = v[i].se - ld;
    int ru = N - lu - ld - rd - 1;
    trc(i,lu,ld,rd,ru);
    assert(lu>=0&&ld>=0&&rd>=0&&ru>=0);
    ans += (beki[lu] - 1) * (beki[rd] - 1) * beki[ru+ld];
    ans += (beki[ru] - 1) * (beki[ld] - 1) * beki[lu+rd];
    ans-= (beki[lu] - 1) * (beki[rd] - 1)* (beki[ru] - 1) * (beki[ld] - 1) ;
    bit.add(v[i].se , 1);
  }
  out(ans);
}

