int solve(){
    sort(P.begin(),P.end(),[](pii a, pii b){return a.first < b.first;});
    for (int i = 0; i < N; i++) P[i].first = i;

    sort(P.begin(),P.end(),[](pii a, pii b){return a.second < b.second;});
    for (int i = 0; i < N; i++) P[i].second = i;

    map<pii,int> I;
    for (int i = 0; i < N; i++) I[P[i]] = i;

    SegmentTree<int> seg_LD(N+1, [](int a, int b){return a+b;}, 0);
    SegmentTree<int> seg_LU(N+1, [](int a, int b){return a+b;}, 0);
    SegmentTree<int> seg_RD(N+1, [](int a, int b){return a+b;}, 0);
    SegmentTree<int> seg_RU(N+1, [](int a, int b){return a+b;}, 0);
    vector<int> dp_LD(N,0);
    vector<int> dp_LU(N,0);
    vector<int> dp_RD(N,0);
    vector<int> dp_RU(N,0);
    // sort(P.begin(),P.end(),[](pii a, pii b){return a.second < b.second;});
    for (int i = 0; i < N; i++)
    {
        dp_RD[I[P[i]]] = seg_RD.query(P[i].first+1,N);
        dp_LD[I[P[i]]] = seg_LD.query(0,P[i].first);
        seg_RD.update(P[i].first, 1);
        seg_LD.update(P[i].first, 1);
    }
    // indexの情報が変わってる・・・
    sort(P.begin(),P.end(),[](pii a, pii b){return a.second > b.second;});
    for (int i = 0; i < N; i++)
    {
        dp_RU[I[P[i]]] = seg_RU.query(P[i].first+1,N);
        dp_LU[I[P[i]]] = seg_LU.query(0,P[i].first);
        seg_RU.update(P[i].first,1);
        seg_LU.update(P[i].first,1);
    }
    modint ans = 0;

    for (int i = 0; i < N; i++) {
        ans += modint(2).pow(N-1);
        ans += (modint(2).pow(dp_LD[i])-1)*(modint(2).pow(dp_RU[i])-1)*modint(2).pow(dp_LU[i])*modint(2).pow(dp_RD[i]);
        ans += (modint(2).pow(dp_LU[i])-1)*(modint(2).pow(dp_RD[i])-1)*modint(2).pow(dp_LD[i])*modint(2).pow(dp_RU[i]);
        ans -= (modint(2).pow(dp_LU[i])-1)*(modint(2).pow(dp_RD[i])-1)*(modint(2).pow(dp_LD[i])-1)*(modint(2).pow(dp_RU[i])-1);
        }
    cout << ans << endl;
    return 0;
}   

