	sort(s,s+n,cmpy);
	for(int i=0;i<n;i++){
		Add(ans,-(F2[i]-1));
		Add(ans,-(F2[n-1-i]-1));
	} 
	for(int i=0;i<n;i++){ 
		Add(ans,F2[bit.Query(s[i].x)]-1);//<x,<y
		Add(ans,F2[i-bit.Query(s[i].x)]-1);//>x,<y
		bit.Add(s[i].x);
	}
	bit.clear(); 
	for(int i=n-1;i>=0;i--){  
		Add(ans,F2[bit.Query(s[i].x)]-1);//<x,>y
		Add(ans,F2[n-1-i-bit.Query(s[i].x)]-1);//>x,>y;
		bit.Add(s[i].x); 
	} 
	cout<<ans<<endl; 
	return 0;
}

