const int MAX = 2e5+10;
const int MOD = 998244353;

int N;
ll X[MAX], Y [MAX], quad[MAX][4];
vii xs, ys, xy;

struct BIT {
    vector<ll> data;
    int N;

    BIT(int n) {
        N = 1;
        while (N < n) N *= 2;
        N *= 2;

        data = vector<ll>(N+1);
    }

    void add(int i, ll x) {
        for (int k = i; k <= N; k += k&-k) data[k] += x;
    }

    void update(int i, ll x) {
        add(i, x-get(i));
    }

    ll sum(int i) {
        ll res = 0;
        for (int k = i; k > 0; k -= k&-k) res += data[k];
        return res;
    }

    ll get(int i) {
        return sum(i) - sum(i-1);
    }
};

ll pow(ll n, ll k) {
    ll res = 1;
    while (k) {
        if (k&1) res = res*n%MOD;
        n = n*n%MOD;
        k >>= 1;
    }
    return res;
}

ll calc(int n) {
    ll count = 4ll * MOD + pow(2, N) - 1;
    REP (i,4) {
        count -= pow(2, (quad[n][i] + quad[n][(i+1)%4])) - 1;
        count += pow(2, quad[n][i]) - 1;
    }
    return count % MOD;
}

ll solve() {
    REP (i, N) {
        xs.PB(MP(X[i], i));
        ys.PB(MP(Y[i], i));
    }
    sort(ALL(xs)); sort(ALL(ys));
    REP (i, N) {
        X[xs[i].second] = i+1;
        Y[ys[i].second] = i+1;
    }
    REP (i, N) xy.PB(MP(X[i], Y[i]));
    sort(ALL(xy));

    BIT bitL(MAX), bitR(MAX);
    REP (i, N) {
        quad[i][0] = bitL.sum(xy[i].second);
        quad[i][1] = i - quad[i][0];
        bitL.add(xy[i].second, 1);

        quad[N-i-1][2] = bitR.sum(MAX-xy[N-i-1].second);
        quad[N-i-1][3] = i - quad[N-i-1][2];
        bitR.add(MAX-xy[N-i-1].second, 1);
    }

    ll ans = 0;
    REP (i, N) ans = (ans + calc(i)) % MOD;
    return ans;
}

int main() {
