        int32 b = i - a;
        int32 c = r.sum(1,p[i].second);
        int32 d = n - i - 1 - c;
        mint at = mint(2).pow(a) - 1;
        mint bt = mint(2).pow(b) - 1;
        mint ct = mint(2).pow(c) - 1;
