using Data = int;
const int len = 1 << 18;

struct BIT {
  vector<Data> data;
  BIT() : data(len, 0) {}
  void update(int i, Data value) {
    for (; i < len; i |= i+1) data[i] += value;
  }
  Data query(int i) {
    Data s = 0;
    for (; i >= 0; i = (i&i+1)-1) s += data[i];
    return s;
  }
};

ll p2m(ll i) {
  if (i == 0) return 1;
  if ((i%2) == 1) return (2*p2m(i-1))%MOD;
  ll h = p2m(i/2);
  return (h*h)%MOD;
}

int main()
{
  int n;
  cin>>n;
