    vt.emplace_back(x,y);
    vy.push_back(y);
  }
  sort(ALL(vt));
  sort(ALL(vy));
  ll sum = 0;
  BIT bit;
  REP(i,n) {
    int x,y;
    tie(x,y) = vt[i];
    int idx = lower_bound(ALL(vy), y) - begin(vy);
    int a = bit.query(idx);
    int c = i - a;
    int b = idx - a;
    int d = n-1-i-idx+a;
    sum += 2*p2m(n-1) + (MOD - p2m(b+d)) + (MOD - p2m(c+d))
      + (MOD - p2m(c+a)) + (MOD - p2m(a+b))
      + (p2m(a) + p2m(b) + p2m(c) + p2m(d))
      + (MOD - 1);
    sum %= MOD;
    bit.update(idx, 1);
  }
  cout<<sum<<endl;
  return 0;
}

