namespace NyaGadget
{
	/*** MOD ライブラリ ***/

	template<ll maxv> struct ModLL
	{
		ll x;

		// コンストラクタ
		ModLL() { x = 0; }
		ModLL(ll x_)
		{
			x = x_ % maxv + maxv;
			if (x >= maxv)
				x -= maxv;
		}

		// 符号
		ModLL operator + () const { return x; }
		ModLL operator - () const { return (-x < 0) ? maxv - x : -x; }

		// 加減乗除演算子
		ModLL& operator += (ModLL r)
		{
			if ((x += r.x) >= maxv)
				x -= maxv;
			return *this;
		}
		ModLL& operator -= (ModLL r)
		{
			if ((x -= r.x) < 0)
				x += maxv;
			return *this;
		}
		ModLL& operator *= (ModLL r)
		{
			x = (unsigned long long) x * r.x % maxv;
			return *this;
		}
		ModLL& operator /= (ModLL r)
		{
			x = x * ModLL::Inv(r.x, maxv) % maxv;
			return *this;
		}

		ModLL operator + (ModLL r) const { return ModLL(*this) += r; }
		ModLL operator - (ModLL r) const { return ModLL(*this) -= r; }
		ModLL operator * (ModLL r) const { return ModLL(*this) *= r; }
		ModLL operator / (ModLL r) const { return ModLL(*this) /= r; }

		// 比較演算子
		bool operator == (ModLL& r) const { return x == r.x; }
		bool operator != (ModLL& r) const { return x != r.x; }
		bool operator <  (ModLL& r) const { return x < r.x; }
		bool operator <= (ModLL& r) const { return x <= r.x; }
		bool operator >  (ModLL& r) const { return x > r.x; }
		bool operator >= (ModLL& r) const { return x >= r.x; }

		// 入出力演算子
		friend ostream& operator << (ostream& s, ModLL<maxv> a)
		{
			s << a.x;
			return s;
		}
		friend istream& operator >> (istream& s, ModLL<maxv>& a)
		{
			s >> a.x;
			return s;
		}

		// 累乗 a^{n}
		static ll Pow(ll a, ll n) {
			ll res = 1;
			while (n > 0) {
				if (n & 1) res = res * a % maxv;
				a = a * a % maxv;
				n >>= 1;
			}
			return res;
		}

		// 逆元 x^{-1} (主に除算演算子で使用)
		static ll Inv(ll a, ll m)
		{
			ll b = m, u = 1, v = 0;
			while (b)
			{
				ll t = a / b;
				a -= t * b; swap(a, b);
				u -= t * v; swap(u, v);
			}
			u %= m;
			return (u < 0) ? u + m : u;
		}
	};
}

namespace NyaGadget
{
	/*** 遅延評価セグメント木ライブラリ ***/

	template <class T> struct Vertex
	{	// 各頂点は対象閉区間[l,r]の合計値を持つ
		T value;        // 頂点の値
		long long lazy; // 遅延評価値
		long long l;    // 対象閉区間最小値
		long long r;    // 対象閉区間最大値
	};

	template <class T> struct LazySegmentTree
	{
		vector<Vertex<T>> tree;

		/**
		@brief コンストラクタ
		@note
		 初期値0で[0,n]を処理する木を作る
		**/
		LazySegmentTree(long long n)
		{
			long long tsize = 2 * (long long)pow(2, ceil(log2(n))) - 1;
			tree.resize(tsize);

			long long depth = 1;
			long long range = tsize / 2;
			tree[0] = { 0, 0, 0, range };
			for (long long i = 1; i < tsize; i++)
			{	// 各ノードの区間範囲を設定する
				tree[i] = { 0, 0, tree[i - 1].l + range + 1, tree[i - 1].r + range + 1 };

				if (i == pow(2, depth) - 1)
				{
					depth++;
					range /= 2;
					tree[i] = { 0, 0, 0, range };
				}
			}
		}

		/**
		@brief コンストラクタ
		@note
		 初期値を配列vで与えて木を作る。
		**/
		LazySegmentTree(vector<T>& v)
		{
			long long tsize = 2 * (long long)pow(2, ceil(log2(Size(v)))) - 1;
			tree.resize(tsize);

			long long depth = 1;
			long long range = tsize / 2;
			tree[0] = { 0, 0, 0, range };
			for (long long i = 1; i < tsize; i++)
			{	// 各ノードの区間範囲を設定する
				tree[i] = { 0, 0, tree[i - 1].l + range + 1, tree[i - 1].r + range + 1 };

				if (i == pow(2, depth) - 1)
				{
					depth++;
					range /= 2;
					tree[i] = { 0, 0, 0, range };
				}
			}

			for (long long i = 0; i < (long long)v.size(); i++)
				tree[i + tsize / 2].value = v[i];
			for (long long i = tsize / 2 - 1; -1 < i; i--)
				tree[i].value = tree[i * 2 + 1].value + tree[i * 2 + 2].value;
		}

		/**
		@brief 区間に対して加算処理をする関数
		@param l 加算する区間の左端
		@param r 加算する区間の右端
		@param v 加算する値
		@param vi 頂点インデックス
		@note
		 [l, r]の区間にvを加算する
		**/
		void Add(long long l, long long r, T v, long long vi = 0)
		{
			Propagate(vi);

			// 完全に加算区間範囲外のとき枝刈り
			if (r < tree[vi].l || tree[vi].r < l)
				return;

			if (l <= tree[vi].l && tree[vi].r <= r)
			{	// 加算区間に全範囲が含まれる
				tree[vi].lazy += (tree[vi].r - tree[vi].l + 1) * v;
				Propagate(vi);
			}
			else
			{	// 加算区間に一部範囲が含まれる
				Add(l, r, v, 2 * vi + 1);
				Add(l, r, v, 2 * vi + 2);
				tree[vi].value = tree[2 * vi + 1].value + tree[2 * vi + 2].value;
			}
		}

		/**
		@brief 伝搬関数
		@note
		 頂点viの遅延評価を伝搬させる。
		**/
		void Propagate(long long vi)
		{
			if (tree[vi].lazy != 0)
			{
				tree[vi].value += tree[vi].lazy;

				if (1 <= tree[vi].r - tree[vi].l)
				{	// 子ノードが存在する
					tree[2 * vi + 1].lazy += tree[vi].lazy / 2;
					tree[2 * vi + 2].lazy += tree[vi].lazy / 2;
				}
				tree[vi].lazy = 0;
			}
		}

		/**
		@brief 区間合計値を取得する関数
		@note
		 [l,r]の合計値を取得して返す
		**/
		void RangeSum(long long l, long long r, T& sum, long long vi = 0)
		{
			if (r < l)
			{
				sum = 0;
				return;
			}

			Propagate(vi);
			if (vi == 0) sum = tree[vi].value;
			if (tree[vi].l == l && tree[vi].r == r) return;

			vi *= 2;
			if (tree[vi + 1].r < l)
			{
				sum -= tree[vi + 1].value;
				RangeSum(l, r, sum, vi + 2);
			}
			else if (r < tree[vi + 2].l)
			{
				sum -= tree[vi + 2].value;
				RangeSum(l, r, sum, vi + 1);
			}
			else
			{
				RangeSum(l, tree[vi + 1].r, sum, vi + 1);
				RangeSum(tree[vi + 2].l, r, sum, vi + 2);
			}
		}
	};
}

using namespace NyaGadget;
using mll = ModLL<998244353>;

struct DIM2
{
	ll x = 0;
	ll y = 0;
	ll xrank = 0;
	ll yrank = 0;
};

auto SortX = [](const DIM2& l, const DIM2& r)
{	// 降順は演算子>, 昇順は演算子<, if順の優先でソートされる
	return l.x < r.x;
};

auto SortY = [](const DIM2& l, const DIM2& r)
{	// 降順は演算子>, 昇順は演算子<, if順の優先でソートされる
	return l.y < r.y;
};


int main(void)
{
	ll N; cin >> N;
	vt<DIM2> grid(N); each(i, e, grid) cin >> e->x >> e->y;

	sort(all(grid), SortY);
	each(i, e, grid) e->yrank = i;
	sort(all(grid), SortX);
	each(i, e, grid) e->xrank = i;

	LazySegmentTree<ll> lstl(N), lstr(N);
	each(i, e, grid) lstr.Add(e->yrank, e->yrank, 1);

	vvt<ll> count(4);
	each(i, e, grid)
	{
		ll test = 0;
		lstr.Add(e->yrank, e->yrank, -1);
		lstl.RangeSum(e->yrank, N-1, test); count[0].push_back(test);
		lstl.RangeSum(0, e->yrank, test); count[1].push_back(test);
		lstr.RangeSum(e->yrank, N-1, test); count[2].push_back(test);
		lstr.RangeSum(0, e->yrank, test); count[3].push_back(test);
		lstl.Add(e->yrank, e->yrank, 1);
	}

	mll ans;
	rep(i, 0, N)
	{	// 包除原理
		vt<mll> o(4), ox(4);
		rep(j, 0, 4)
		{
			ox[j] = mll::Pow(2, count[j][i]);
			o[j] = ox[j] - 1;
		}

		ans += o[0] * ox[1] * ox[2] * o[3];
		ans += ox[0] * o[1] * o[2] * ox[3];
		ans -= o[0] * o[1] * o[2] * o[3];
		ans += ox[0] * ox[1] * ox[2] * ox[3];
	}

	cout << ans;
	return 0;
}

