template<typename T = int> vector<T> Zalgo( const string &S ) {
	T N = (T)S.size();
	vector<T> res(N);
	res[0] = N;
	T i = 1, j = 0;
	while ( i < N ) {
		while (i+j < N && S[j] == S[i+j]) ++j;
		res[i] = j;
		if ( j == 0 ) { ++i; continue; }
		int k = 1;
		while ( i + k < N && k + res[k] < j ) res[i + k] = res[k], ++k;
		i += k, j -= k;
	}
	return ( res );
}

void replace( string &s, string t, string r ) {
	string::size_type p = 0;
	while ( ( p = s.find( t, p ) ) != string::npos ) {
		s.replace( p, t.length(), r );
		p += r.length();
	}
}

template<typename T> auto binsearch_idx( vector<T> &v, T val ) {
	ll left = -1, right = v.size();
	while ( abs( right - left ) > 1 )
	{
		ll mid = ( left + right ) / 2;
		if ( val > v[mid] )
			left = mid;
		else
			right = mid;
	}

	return ( mp( v[right] == val, right ) );
}

struct BIT {
	vector<ll> data;
	ll size;
	BIT( ll n ) {
		size = n;
		data.assign( n + 1, 0 );
	};

	void add( ll i, ll v ) {
		while ( i < size ) {
			data[i] += v;
			i += i & -i;
		};
	}

	ll sum( ll i ) {
		ll res = 0;
		while ( i > 0 ) {
			res += data[i];
			i -= i & -i;
		};

		return ( res );
	}

	ll sum( ll i, ll j ) {
		return ( sum( j ) - sum( i - 1 ) );
	}
};

int main()
{
	ll n; cin >> n;
	vector<Pll> p( n );
	rep( i, n ) cin >> p[i].F >> p[i].S;
	sort( ALL( p ), []( Pll a, Pll b ) { return ( a.S < b.S ); } );
	rep( i, n ) p[i].S = i;
	sort( ALL( p ), []( Pll a, Pll b ) { return ( a.F < b.F ); } );
	rep( i, n ) p[i].F = i;

	BIT b1( n + 1 ), b2( n + 1 );
	rep( i, n ) b1.add( p[i].S + 1, 1 );

	mint ans = 0;
	rep( i, n )
	{
		b1.add( p[i].S + 1, -1 );

		ll A = b1.sum( p[i].S + 1 );
		ll B = b1.sum( p[i].S + 1, n );
		ll C = b2.sum( p[i].S + 1 );
		ll D = b2.sum( p[i].S + 1, n );

		mint t = 2;
		mint an = modpow( t, A );
		mint bn = modpow( t, B );
		mint cn = modpow( t, C );
		mint dn = modpow( t, D );
		mint nn = modpow( t, n - 1 );

		ans += nn + ( an - 1 ) * ( dn - 1 ) * bn * cn;
		ans += an * dn * ( bn - 1 ) * ( cn - 1 );
		ans -= ( an - 1 ) * ( bn - 1 ) * ( cn - 1 ) * ( dn - 1 );
		b2.add( p[i].S + 1, 1 );
	}

	cout << ans << endl;

	return ( 0 );
}

