int n;

struct NODE {
    int x, y;
    inline bool operator < (const NODE &__) const {
        return x < __.x || (x == __.x && y < __.y);
    }
} node[N];
int X[N], Y[N], Cntx[N];
int A[N], B[N], C[N], D[N];

int c[N];
void Add(int x, int k) {
    for ( ; x <= n; x += x & -x) c[x] += k;
}
int Que(int x) {
    int res = 0;
    for ( ; x > 0; x -= x & -x) res += c[x];
    return res;
}

ll Ans = 0;
ll Pow(ll x, int k) {
    ll res = x, ans = 1;
    while (k) {
        if (k & 1) ans = ans * res % Mod;
        res = res * res % Mod, k >>= 1;
    }
    return ans;
}
ll Get(int x) {
    return ((Pow(2, x) - 1) % Mod + Mod) % Mod;
}
ll Solve(int x) {
    ll tmp = 0, a, b, c, d;
    // cout << node[x].x << " " << node[x].y  << endl;
    // cout << A[x] << " " << B[x] << " " << C[x] << " " << D[x] << endl;
    a = Get(A[x]), b = Get(B[x]), c = Get(C[x]), d = Get(D[x]);
    (tmp = a * d % Mod + b * c % Mod) %= Mod;
    (tmp += a * b % Mod * d % Mod + a * c % Mod * d % Mod) %= Mod;
    (tmp += a * b % Mod * c % Mod + b * d % Mod * c % Mod) %= Mod;
    (tmp += a * b % Mod * c % Mod * d % Mod) %= Mod;
    // cout << x << " " << tmp << endl;
    (tmp *= 2) %= Mod;
    (tmp += a + b + c + d) %= Mod;
    (tmp += a * b % Mod + a * c % Mod) %= Mod;
    (tmp += b * d % Mod + c * d % Mod) %= Mod;
    // cout << x << " " << tmp << endl;
    return tmp + 1;
}

int main() {
    n = read<int>();
    rep (i, 1, n)
        X[i] = node[i].x = read<int>(), Y[i] = node[i].y = read<int>();

    sort(X + 1, X + n + 1);
    sort(Y + 1, Y + n + 1);
    X[0] = unique(X + 1, X + n + 1) - X - 1;
    Y[0] = unique(Y + 1, Y + n + 1) - Y - 1;
    sort(node + 1, node + n + 1);

    rep (i, 1, n) {
        node[i].x = lower_bound(X + 1, X + X[0] + 1, node[i].x) - X;
        node[i].y = lower_bound(Y + 1, Y + Y[0] + 1, node[i].y) - Y;
    }

    rep (i, 1, n) {
        A[i] = Que(node[i].y - 1);
        B[i] = i - A[i] - 1;
        Add(node[i].y, 1);
    }

    memset(c, 0, sizeof c);
    dep (i, n, 1) {
        C[i] = Que(node[i].y - 1);
        D[i] = n - i - C[i];
        Add(node[i].y, 1);
    }

    rep (i, 1, n) Ans += Solve(i);

    cout << Ans << endl;
    return 0;
}

