using mll = ModLL<998244353>;

struct DIM2
{
	ll x = 0;
	ll y = 0;
	ll xrank = 0;
	ll yrank = 0;
};

auto SortX = [](const DIM2& l, const DIM2& r)
{	// 降順は演算子>, 昇順は演算子<, if順の優先でソートされる
	return l.x < r.x;
};

auto SortY = [](const DIM2& l, const DIM2& r)
{	// 降順は演算子>, 昇順は演算子<, if順の優先でソートされる
	return l.y < r.y;
};


int main(void)
{
	ll N; cin >> N;
	vt<DIM2> grid(N); each(i, e, grid) cin >> e.x >> e.y;

	sort(all(grid), SortY);
	each(i, e, grid) e.yrank = i;
	sort(all(grid), SortX);
	each(i, e, grid) e.xrank = i;

	LazySegmentTree<ll> lstl(N+nyan), lstr(N+nyan);
	each(i, e, grid) lstr.Add(e.yrank, e.yrank, 1);

	vvt<ll> count = VVT<ll>(4, 0);
	each(i, e, grid)
	{
		ll test = 0;
		lstl.Add(e.yrank, e.yrank, 1);
		lstl.RangeSum(e.yrank, N, test); count[0].push_back(test);
		lstl.RangeSum(0, e.yrank-1, test); count[1].push_back(test);
		lstr.RangeSum(e.yrank+1, N, test);count[2].push_back(test);
		lstr.RangeSum(0, e.yrank, test); count[3].push_back(test);
		lstr.Add(e.yrank, e.yrank, -1);
	}

	mll ans;
	rep(i, 0, N)
	{	// 包除原理
		mll test0 = mll::Pow(2, count[0][i]) - 1;
		mll test1 = mll::Pow(2, count[1][i]) - 1;
		mll test2 = mll::Pow(2, count[2][i]) - 1;
		mll test3 = mll::Pow(2, count[3][i]) - 1;

		mll test = 0;
		test = test0 * test3; test = (0 < test.x) ? test - 1 : 0;
		ans += test;
		test = test1 * test2; test = (0 < test.x) ? test - 1 : 0;
		ans += test;
	}

	mll testN = mll::Pow(2, N) - 1;
	ans -= testN;
	cout << ans;
	return 0;
}

