int bit[MAXN];
void update(int a) {
  for (a++; a <= N; a += (a & (-a))) {
    bit[a] ++;
  }
}
int query(int a) {
  int r = 0;
  for (a++; a > 0; a -= (a & (-a))) {
    r += bit[a];
  }
  return r;
}

