  p2[0] = 0;
  for (int i = 1; i <= N; i++) p2[i] = (p2[i-1]*2+1)%MOD;

  vector<int> xs, ys;
  for (int i = 0; i < N; i++) xs.push_back(P[i].first), ys.push_back(P[i].second);
