    x[i] = whole(lower_bound, cx, x[i]) - cx.begin() + 1;
    y[i] = whole(lower_bound, cy, y[i]) - cy.begin() + 1;
    ps.emplace_back(x[i], y[i]);
  }

  whole(sort, ps);

  fenwick_tree< int > bit_l(N), bit_r(N);
  range(i, 0, N) {
    bit_r.add(i + 1, 1);
  }

  mod_int< mod > ans, m2(2);

  for (auto p : ps) {
    bit_r.add(p.second, -1);

    mod_int< mod > a4(bit_r.get_sum(p.second)), a1(bit_r.get_sum(N) - a4);
    mod_int< mod > a3(bit_l.get_sum(p.second)), a2(bit_l.get_sum(N) - a3);
    a1 = pow(m2, a1);
    a2 = pow(m2, a2);
    a3 = pow(m2, a3);
    a4 = pow(m2, a4);

    ans += pow(m2, N) - (a1 * a2 + a2 * a3 + a3 * a4 + a4 * a1 - a1 - a2 - a3 - a4 + mod_int< mod >(1));

    bit_l.add(p.second, 1);
  }

  cout << ans << endl;
}

