template<typename T> T comb(ll n, ll k){
	T ret = 1;
	for(ll i=1;i<=k;i++) ret = ret * T(n - k + i) / T(i);
	return ret;
}


template<typename T> class Compressor{
	/*
		座標圧縮用 主に下の使い方をする
		newX = Compressor<ll>(x).compress(x);
	*/
public:
	vector<T> toValue;
	map<T, ll> toIndex;
	Compressor(const vector<T> &xs){
		toValue = xs;
		sort(toValue.begin(), toValue.end());
		for(int i=0;i<toValue.size();i++){
			toIndex.insert(make_pair(toValue[i], i));
		}
	}
	vector<ll> compress(const vector<T> &xs){
		vector<ll> ret;
		for(T x : xs) ret.push_back(toIndex.at(x));
		return ret;
	}
};

