	vector<pair<T, ll>> withIdx;
	for(int i=0;i<xs.size();i++) withIdx.push_back(make_pair(xs[i], i));
	sort(withIdx.begin(), withIdx.end());
	vector<ll> ret;
	for(auto p : withIdx) ret.push_back(p.second);
	return ret;
}

