struct SegmentTree{
private:
    int n;
    vector<int> node;
public:
    SegmentTree(const int sz){
        n=1;
        while(n<sz)n*=2;
        node.resize(2*n-1);
    }
    void update(int a,int x){
        a+=n-1;
        node[a]=x;
        while(a>0){
            a=(a-1)/2;
            node[a]=node[2*a+1]+node[2*a+2];
        }
    }
    int get(int a,int b=-1,int k=0,int l=0,int r=-1){
        if(b==-1)b=n;
        if(r==-1)r=n;
        if(b<=l||r<=a)return 0;
        if(a<=l&&r<=b){
            return node[k];
        }
        else{
            return get(a,b,2*k+1,l,(l+r)/2)+get(a,b,2*k+2,(l+r)/2,r);
        }
    }
};

ll modpow(ll x,ll n){
    ll res=1;
    while(n>0){
        if(n&1)res=res*x%MOD;
        x=x*x%MOD;
        n>>=1;
    }
    return res;
}

