        p[i]={x,i};
        q[i]={y,i};
    }
    sort(p,p+n);
    sort(q,q+n);
    int x[n],y[n];
    for(int i=0;i<n;i++){
        x[p[i].second]=i;
        y[q[i].second]=i;
    }
    pair<int,int> pos[n];
    for(int i=0;i<n;i++){
        pos[i]={x[i],y[i]};
    }
    sort(pos,pos+n);
    int ss[n],sg[n],gs[n],gg[n];
    SegmentTree segl(n),segg(n);
    for(int i=0;i<n;i++){
        ss[i]=segl.get(0,pos[i].second);
        sg[i]=segl.get(pos[i].second);
        segl.update(pos[i].second,1);
    }
    for(int i=n-1;i>=0;i--){
        gs[i]=segg.get(0,pos[i].second);
        gg[i]=segg.get(pos[i].second);
        segg.update(pos[i].second,1);
    }
    ll ans=0;
    for(int i=0;i<n;i++){
        ll a=modpow(2,ss[i]);
        ll b=modpow(2,sg[i]);
        ll c=modpow(2,gs[i]);
        ll d=modpow(2,gg[i]);
        ll e=((a-1)*(d-1))%MOD;
        ll f=((b-1)*(c-1))%MOD;
        ll g=(a*d)%MOD;
        ll h=(b*c)%MOD;
        ans=(ans+e*h)%MOD;
        ans=(ans+f*g)%MOD;
        ans=(ans-e*f)%MOD;
    }
    ans=(ans+n*modpow(2,n-1))%MOD;
    ans=(ans+MOD)%MOD;
    cout<<ans<<endl;
}

