        mint to = mpow(b, n - 1);
        to += (mpow(b, c1) - 1LL) * (mpow(b, c4) - 1LL) * mpow(b, c2 + c3);
        to += (mpow(b, c2) - 1LL) * (mpow(b, c3) - 1LL) * mpow(b, c1 + c4);
        to -= (mpow(b, c1) - 1LL) * (mpow(b, c4) - 1LL) * (mpow(b, c2) - 1LL) *
              (mpow(b, c3) - 1LL);
        ans += to;
        b1.add(ix, 1);
    }
    cout << ans.val << endl;
}

