typedef long long ll;
typedef complex<double> Vec;

ll N;
const ll MOD = 998244353;
vector<ll> Pow;
vector<ll> Y;
vector<pair<ll, ll>> XY;
map<ll, ll> IY;
ll R;

void prepare() {
  Pow.push_back(0);
  for (ll i = 1; i <= N; ++i) {
    Pow.push_back((Pow.back() * 2 + 1) % MOD);
  }
}

vector<ll> BIT;
void init() {
  BIT.clear();
  BIT.resize(N + 1);
}
void add(ll i, ll x) {
  ++i;
  for (; i <= N; i += i & -i) BIT[i] += x;
}
ll sum(ll i) {
  ++i;
  ll res = 0;
  for (; i > 0; i -= i & -i) res += BIT[i];
  return res;
}
void solve() {
  R = N * Pow[N] % MOD;
  for (ll i = 0; i < N; ++i) {
    (R += MOD - 2 * (Pow[i] + Pow[N - 1 - i]) % MOD) %= MOD;
  }
  for (ll mode = 0; mode < 2; ++mode) {
    init();
    for (ll cnt = 0; cnt < N; ++cnt) {
      ll y = XY[mode == 0 ? cnt : N - 1 - cnt].second;
      ll i = IY.at(y);
      ll left = sum(i);
      ll right = cnt - left;
      assert(left >= 0 && right >= 0);
      (R += Pow[left]) %= MOD;
      (R += Pow[right]) %= MOD;
      add(i, 1);
    }
  }
}

int main() {
  cin >> N;
  prepare();
  for (ll i = 0; i < N; ++i) {
