		auto iter3=lower_bound(yd.begin(),yd.end(),d[i].second);
		left=i;
		right=n-1-i;
		down=iter3-yd.begin();
		up=n-1-down;
		long long minus=0,dou=0;
		if(i==0){
			minus=(mod+mypow(n-1)-1)%mod;
		} else {
