    sort(begin(y),end(y));
    vector<P> point(N);
    for(int i=0; i<N; ++i) {
        point[x[i].second].first = i;
        point[y[i].second].second = i;
    }
    sort(begin(point), end(point));

    SegTree<int> done(N, 0, plus<int>(), plus<int>());
    SegTree<int> undone(N, 0, plus<int>(), plus<int>());
    for(int i=0; i<N; ++i) undone.change(i, 1);

    int res = 0;
    powtwoinit(N);
    for(P p : point) {
        int y = p.second;
        done.change(y, 1);
        undone.change(y, -1);

        vector<int> num(4);
        num[0] = undone.query(y + 1, N);
        num[1] = done.query(y + 1, N);
        num[2] = done.query(0, y);
        num[3] = undone.query(0, y + 1);

        long long tmp = powtwo[N] - 1;
        for(int i=0; i<4; ++i) {
            tmp = (tmp - powtwo[num[i] + num[(i + 1) % 4]] + MOD) % MOD;
            tmp = (tmp + powtwo[num[i]]) % MOD;
        }
        res = (res + tmp) % MOD;
    }
