        p.insert(A[i]);
        q.insert(B[i]);
    }
    ll X=p.size()+2,Y=q.size()+2;
    int cnt=1;
    for(auto a:p) x[a]=++cnt;
    cnt=1;
    for(auto a:q) y[a]=++cnt;
    BIT2D<int> BIT(X,Y);
    rep(i,0,N){
        BIT.add(x[A[i]],y[B[i]],1);
    }
    ll ans=0;
    rep(i,0,N){
        ans+=modpow(2,N,MOD)-1;
        ans-=modpow(2,BIT.query(1,1,x[A[i]]-1,Y),MOD)-1;
        ans-=modpow(2,BIT.query(x[A[i]]+1,1,X,Y),MOD)-1;
        ans-=modpow(2,BIT.query(1,1,X,y[B[i]]-1),MOD)-1;
        ans+=modpow(2,BIT.query(1,1,x[A[i]]-1,y[B[i]]-1),MOD)-1;
        ans+=modpow(2,BIT.query(x[A[i]]+1,1,X,y[B[i]]),MOD)-1;
