typedef pair<long,long> pll;

class SegmentTree{
private:
	vector<long> a;
	int n, m, h;
public:
	SegmentTree(int _n): n(_n){
		m = 1; h = 1;
		while (m < n){
			m <<= 1;
			h++;
		}
		a.resize(2*m+1, 0);
	}
	void update(int idx){
		int i = m + idx - 1;
		for (int i=m+idx-1; i > 0; i=(i-1)/2){
			a[i]++;
		}
		a[0]++;
	}
	// [p,q)
	long get(int p, int q){
		return query(p, q, 0, 0, m);
	}
	long query(int p, int q, int k, int l, int r){
		if (r <= p || q <= l) return 0;
		if (p <= l && r <= q) return a[k];
		else{
			int vl = query(p, q, k*2+1, l, (l+r)/2);
			int vr = query(p, q, k*2+2, (l+r)/2, r);
			return vl+vr;
		}
	}
	void print(){
		for (int i = 0, j = 0; i < h; ++i){
			for (int k = 0; k < (1 << i); k++, j++){
				printf("%d ", a[j]);
			}
			printf("\n");
		}
	}
	void clear(){
		fill(a.begin(), a.end(), 0);
	}
};

long pow2(int n){
	if (n == 0) return 1;
	else if (n % 2 == 1) return (pow2(n-1)*2)%MOD;
	else{
		long t = pow2(n/2);
		return (t*t)%MOD;
	}
}

int n;
long x, y, ans, tmp;
vector<pll> xy;
vector<long> ur, ul, ll, lr, bin;

int main(){
	cin >> n;
	for (int i = 0; i < n; ++i){
		cin >> x >> y;
		xy.emplace_back(x, y);
	}
	sort(xy.begin(), xy.end(), [](pll a, pll b){return a.second < b.second;});
	for (int i = 0; i < n; ++i) xy[i].second = i;
	sort(xy.begin(), xy.end(), [](pll a, pll b){return a.first < b.first;});

	SegmentTree tree(n);
	ur.resize(n);
	ul.resize(n);
	ll.resize(n);
	lr.resize(n);

	for (int i = 0; i < n; ++i){
		y = xy[i].second;
		ul[i] = tree.get(y+1, n);
		ll[i] = tree.get(0, y);
		tree.update(y);
	}
	tree.clear();
	for (int i = n-1; i >= 0; --i){
		y = xy[i].second;
		ur[i] = tree.get(y+1, n);
		lr[i] = tree.get(0, y);
		tree.update(y);
	}

	bin.resize(n); bin[0] = 1;
	for (int i = 0; i < n-1; ++i) bin[i+1] = (bin[i]*2) % MOD;

	ans = (bin[n-1] * n) % MOD;
	for (int i = 0; i < n; ++i){
		long bur = bin[ur[i]];
		long bul = bin[ul[i]];
		long blr = bin[lr[i]];
		long bll = bin[ll[i]];
		tmp = ((((((bur - 1)*(bll - 1)) % MOD)*bul) % MOD)*blr) % MOD;
		ans = (ans + tmp) % MOD;
		tmp = ((((((bul - 1)*(blr - 1)) % MOD)*bur) % MOD)*bll) % MOD;
		ans = (ans + tmp) % MOD;
		tmp = ((((((bur - 1)*(bll - 1)) % MOD)*(bul - 1)) % MOD)*(blr - 1)) % MOD;
		ans = (ans + (MOD - tmp)) % MOD;
	}
	cout << ans;
}

