constexpr int P = 998244353;

ll powmod(ll n, ll k) {
    ll r = 1, t = n % P;
    for (; k != 0; k /= 2) {
        if (k & 1) r = r * t % P;
        t = t * t % P;
    }
    return r;
}
ll inv(ll n) {
    return powmod(n, P - 2);
}

struct A {
    bool operator<(const A& a) const {
        return x < a.x;
    }
    int x, y;
};

struct BIT {
    BIT(int n) : b(n + 1), n(n) {}
    void add(int i, int v) {
        for (int k = i + 1; k <= n; k += k & -k) b[k] += v;
    }
    int sum(int k) {
        int s = 0;
        for (; k > 0; k -= k & -k) s += b[k];
        return s;
    }
    vector<int> b;
    int n;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<A> a(n);
    vector<pair<int, int>> p(n);
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        a[i] = { x, 0 };
        p[i] = { y, i };
    }

    sort(p.begin(), p.end());
    for (int i = 0; i < n; i++) {
        a[p[i].second].y = i;
    }
    sort(a.begin(), a.end());

    BIT b0(n), b1(n);
    for (int i = 0; i < n; i++) {
        b1.add(a[i].y, 1);
    }

    vector<int> b(n + 1);
    b[0] = 1;
    for (int i = 0; i < n; i++) {
        b[i + 1] = b[i] * 2 % P;
    }

    ll r = 0;
    for (int i = 0; i < n; i++) {
        b1.add(a[i].y, -1);

        int k00 = b0.sum(a[i].y);
        int k01 = i - k00;
        int k10 = b1.sum(a[i].y);
        int k11 = (n - 1 - i) - k10;

        r += (ll)(b[k11] + b[k00] - 1) * (b[k10] + b[k01] - 1) % P;

        b0.add(a[i].y, 1);
    }

    r = (b[n] * n - r) % P;
    if (r < 0) r += P;

    cout << r << endl;

    return 0;
}

