		X.pb(pp.x);
		Y.pb(pp.y);
	}
	sort(all(X));
	sort(all(Y));
	sort(all(points));
	for (auto &pp : points) {
		pp.x = lower_bound(X.begin(), X.end(), pp.x) - X.begin();
		pp.y = lower_bound(Y.begin(), Y.end(), pp.y) - Y.begin();
	}

	vector<ll> cnt1(N, 0); // x > xi and y > yi
	vector<ll> cnt2(N, 0); // x > xi and y < yi
	vector<ll> cnt3(N, 0); // x < xi and y > yi
	vector<ll> cnt4(N, 0); // x < xi and y < yi

	BIT<ll> bit1(N + 5);
	for (int i=0; i<N; i++) {
		auto pp = points[i];
		cnt3[i] = bit1.sum(pp.y+1, N);
		cnt4[i] = bit1.sum(0, pp.y-1);
		debug(i, cnt3[i], cnt4[i]);
		bit1.add(pp.y, +1);		
	}

	BIT<ll> bit2(N + 5);
	for (int i=N-1; i>=0; i--) {
		auto pp = points[i];
		cnt1[i] = bit2.sum(pp.y+1, N);
		cnt2[i] = bit2.sum(0, pp.y-1);
		debug(i, cnt1[i], cnt2[i]);
		bit2.add(pp.y, +1);		
	}

	ll ans = 0;
	for (int i=0; i<N; i++) {
		auto mm = [](ll p) { return p - 1; };
		ans = mod(ans + mod(mod(pow2[cnt1[i]]*pow2[cnt2[i]])*mod(pow2[cnt3[i]]*pow2[cnt4[i]])));
		ans = mod(ans + mod(mod((pow2[cnt1[i]] - 1)*(pow2[cnt2[i]] - 1)*mod((pow2[cnt3[i]] - 1)*(pow2[cnt4[i]] - 1)))));
		ans = mod(ans + mod(mod(mm(pow2[cnt3[i]])*mm(pow2[cnt1[i]]))*mm(pow2[cnt2[i]])));
		ans = mod(ans + mod(mod(mm(pow2[cnt1[i]])*mm(pow2[cnt2[i]]))*mm(pow2[cnt4[i]])));
		ans = mod(ans + mod(mod(mm(pow2[cnt2[i]])*mm(pow2[cnt4[i]]))*mm(pow2[cnt3[i]])));
		ans = mod(ans + mod(mod(mm(pow2[cnt4[i]])*mm(pow2[cnt3[i]]))*mm(pow2[cnt1[i]])));
		ans = mod(ans + mod(mm(pow2[cnt4[i]])*mm(pow2[cnt1[i]])));
		ans = mod(ans + mod(mm(pow2[cnt3[i]])*mm(pow2[cnt2[i]])));
	}

	cout<<ans<<endl;
}

