		Y[i] = lower_bound(GY.begin(), GY.end(), Y[i]) - GY.begin(); Y[i]++; LY[Y[i]]++;
		R[X[i]].push_back(i);
	}
	for (int i = 1; i <= GX.size(); i++) LX[i] += LX[i - 1];
	for (int i = 1; i <= GY.size(); i++) LY[i] += LY[i - 1];

	Z1.init(N + 2);
	for (int i = 1; i <= N; i++) {
		for (int j = 0; j < R[i].size(); j++) {
			P1[R[i][j]] = Z1.sum(Y[R[i][j]] - 1);
