	Z2.init(N + 2);
	for (int i = N; i >= 1; i--) {
		for (int j = 0; j < R[i].size(); j++) {
			P3[R[i][j]] = Z2.sum(Y[R[i][j]] - 1);
			P4[R[i][j]] = Z2.sum(N + 1) - Z2.sum(Y[R[i][j]]);
