		ans -= power[P3[i]]; ans += mod; ans %= mod;
		ans -= power[P4[i]]; ans += mod; ans %= mod;
		ans += power[0]; ans += mod; ans %= mod;
	}
	cout << (1LL * N * power[N] - ans + mod) % mod << endl;
	return 0;
}

