int ask(int l, int r){
  l += lim;
  r += lim;
  int cc = 0;
  while(l <= r){
    if(l % 2 == 1) cc += tree[l ++ ];
    if(r % 2 == 0) cc += tree[r -- ];
    l /= 2;
    r /= 2;
  }
  return cc;
}

