	for (int i = 0; i < n; i++) a[i].x = ri(), a[i].y = ri(), a[i].id = i;

	std::sort(a, a + n, [](const Point &a, const Point &b) { return a.y < b.y; });
	int cnt = 0;
	int last = -1;
	for (auto &i : a) {
		if (i.y != last) {
			last = i.y;
			i.y_comped = cnt++;
		} else i.y_comped = cnt;
	}

	std::sort(a, a + n, [](const Point &a, const Point &b) { return a.x < b.x; });

	SegTree forward(cnt), back(cnt);
	for (auto &i : a) back.add(i.y_comped, 1);

	mint res = 0;
	for (auto &i : a) {
		back.add(i.y_comped, -1);

		res -= (mint(2) ^ back.sum(0, back.n));
		res -= (mint(2) ^ forward.sum(0, forward.n));
		res += (mint(2) ^ forward.sum(0, i.y_comped));
		res += (mint(2) ^ forward.sum(i.y_comped + 1, forward.n));
		res += (mint(2) ^ back.sum(0, i.y_comped));
		res += (mint(2) ^ back.sum(i.y_comped + 1, back.n));

		forward.add(i.y_comped, 1);
	}
	res -= (mint(2) ^ (n + 1)) - 2;
	res += ((mint(2) ^ n) - 1) * n;
	std::cout << res << std::endl;

	return 0;
