        a = ((((POW[RU] - 1) * (POW[LD] - 1)) % MOD2) * (((POW[RD]) * (POW[LU])) % MOD2) ) % MOD2;
        b = ((((POW[RU]) * (POW[LD])) % MOD2) * (((POW[RD] - 1) * (POW[LU] - 1)) % MOD2) ) % MOD2;
        c = ((((POW[RU] - 1) * (POW[LD] - 1)) % MOD2) * (((POW[RD]-1) * (POW[LU]-1)) % MOD2) ) % MOD2;
        ans = (ans + a + b - c + MOD2) % MOD2;
        Left.add(P[i].S, 1);
    }

    cout << ans << endl;


}

