    vector<T> d;

};

template<class T>
struct ModInt {
    T x;
    ModInt(T x = 0) :x(x% mod) {}
    ModInt& operator+=(const ModInt a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    ModInt& operator-=(const ModInt a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }
    ModInt& operator*=(const ModInt a) {
        (x *= a.x) %= mod;
        return *this;
    }
    ModInt operator+(const ModInt a) const {
        ModInt res(*this);
        return res += a;
    }
    ModInt operator-(const ModInt a) const {
        ModInt res(*this);
        return res -= a;
    }
    ModInt operator*(const ModInt a) const {
        ModInt res(*this);
        return res *= a;
    }
    ModInt pow(T t) const {
        if (!t) return 1;
        ModInt a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    ModInt inv() const {
        return pow(mod - 2);
    }
    ModInt& operator/=(const ModInt a) {
        return (*this) *= a.inv();
    }
    ModInt operator/(const ModInt a) const {
        ModInt res(*this);
        return res /= a;
    }
};
using mint = ModInt<long long>;

using P = pair<int, int>;
int n;
void solve() {
    mod = 998244353;

    cin >> n;

    vector<P> p(n);
    rep(i, n)
        cin >> p[i].first >> p[i].second;

    all(sort, p);

    rep(i, n)
        p[i].first = i;

    {
        map<int, int> mp;
        rep(i, n)
            mp[p[i].second] = i;
        int j = 0;
        for (auto&& x : mp)
            p[x.second].second = j++;
    }

    vector<int> a(n), b(n), c(n), d(n);
    {
        auto f = [](vector<int>& a, vector<int>& b, vector<P>& p) {
            BIT<int> bit(n);
            rep(i, n) {
                a[i] = bit.sum(p[i].second);
                b[i] = i - a[i];
                bit.add(p[i].second);
            }
        };

        f(a, b, p);
        all(reverse, p);
        f(c, d, p);
        all(reverse, p);
        all(reverse, c);
        all(reverse, d);
    }

    mint ans = 0;
    rep(i, n) {
        vector<int> x{ a[i],b[i],c[i],d[i] };
        vector<mint> pows(4);

        rep(i, 4)
            pows[i] = mint(2).pow(x[i]);

        ans += (pows[0] - 1) * pows[1] * pows[2] * (pows[3] - 1);
        ans += pows[0] * (pows[1] - 1) * (pows[2] - 1) * pows[3];
        ans -= (pows[0] - 1) * (pows[1] - 1) * (pows[2] - 1) * (pows[3] - 1);
        ans += pows[0] * pows[1] * pows[2] * pows[3];
    }

    cout << ans.x << endn;

}


