int main(int argc, const char * argv[]) {
    ios_base::sync_with_stdio(false);
    int N;
    cin >> N;
    vector<pair<int, int>> P(N);
    for (int n = 0; n < N; ++n) {
        int x, y;
        cin >> x >> y;
        P[n] = {x, y};
    }
    sort(P.begin(), P.end());
    vector<int> Ind(N);
    iota(Ind.begin(), Ind.end(), 1);
    sort(Ind.begin(), Ind.end(), [&](int l, int r){return P[l-1].second < P[r-1].second;});

    vector<vector<int>> A(4, vector<int>(N));
    vector<int> BIT(N+1);
    auto Add = [&](int n) {
        while (n <= N) {
            ++BIT[n];
            n += n&-n;
        }
    };
    auto Sum = [&](int n) {
        int s = 0;
        while (n > 0) {
            s += BIT[n];
            n -= n&-n;
        }
        return s;
    };
    for (int n = 0; n < N; ++n) {
        int nSum = Sum(Ind[n]);
        A[0][n] = n-nSum;
        A[1][n] = nSum;
        Add(Ind[n]);
    }
    BIT.assign(N+1, 0);
    for (int n = N-1; n >= 0; --n) {
        int nSum = Sum(Ind[n]);
        A[2][n] = nSum;
        A[3][n] = (N-1-n)-nSum;
        Add(Ind[n]);
    }

    vector<ll> Pow2(N+1);
    Pow2[0] = 1;
    for (int n = 1; n <= N; ++n) Pow2[n] = (Pow2[n-1]<<1) % MOD;
    ll Res = 0;
    for (int n = 0; n < N; ++n) {
        ll Tmp = Pow2[N] - 1;
        for (int k = 0; k < 4; ++k) {
            Tmp = (Tmp - Pow2[A[k][n]+A[(k+1)%4][n]]) % MOD;
            Tmp = (Tmp + Pow2[A[k][n]]) % MOD;
        }
        Res = (Res + Tmp) % MOD;
    }
    cout << Res << endl;

    return 0;
}

