int n;
int leup[222222], lelo[222222], riup[222222], rilo[222222];
vector<P>point;
struct BIT {
	vector<int>bit;
	BIT(int x) {
		bit.resize(x + 1);
		rep(i, x + 1)bit[i] = 0;
	}
	int sum(int x) {
		int s = 0;
		while (x > 0) {
			s += bit[x]; x -= x & -x;
		}
		return s;
	}
	void add(int x, int y) {
		while (x < bit.size()) {
			bit[x] += y; x += x & -x;
		}
	}
};
void compress(vector<P>& v) {
	vector<int>x, y;
	for (P p : v) {
		x.push_back(p.first); y.push_back(p.second);
	}
	sort(all(x)); sort(all(y));
	x.erase(unique(all(x)), x.end()); y.erase(unique(all(y)), y.end());
	for (P& p : v) {
		p.first = lower_bound(all(x), p.first) - x.begin(); p.first++;
		p.second = lower_bound(all(y), p.second) - y.begin(); p.second++;
	}
}
signed main() {
	cin >> n;
	point.resize(n);
	rep(i, n)cin >> point[i].first >> point[i].second;
	sort(all(point)); compress(point);

	//X座標が小さい方から
	{
		BIT bit(n);
		rep(i, n) {
			lelo[i] = bit.sum(point[i].second);
			leup[i] = i - lelo[i];
			bit.add(point[i].second, 1);
		}
	}
	//X座標が大きい方から
	{
		BIT bit(n);
		for (int i = n - 1; i >= 0; i--) {
			rilo[i] = bit.sum(point[i].second);
			riup[i] = (n - 1 - i) - rilo[i];
			bit.add(point[i].second, 1);
		}
	}
	//計算
	int ans = 0;
	rep(i, n) {
		int p = mod_pow(2, lelo[i]) + mod_pow(2, riup[i]) - 1; p %= mod;
		int q = mod_pow(2, leup[i]) + mod_pow(2, rilo[i]) - 1; q %= mod;
		ans += mod_pow(2, n) - p * q % mod + mod; ans %= mod;
	}
	cout << ans << endl;
}

