long long modpow(long long a, long long n) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}
template <class Abel> struct BIT {
    const Abel UNITY_SUM = 0;                       // to be set
    vector<Abel> dat;

    // [1, n]
    BIT(int n) : dat(n + 1, UNITY_SUM) { }
    void init(int n) { dat.assign(n + 1, UNITY_SUM); }

    // a is 1-indexed]
    inline void add(int a, Abel x) {a++;
        for (int i = a; i < (int)dat.size(); i += i & -i)
            dat[i] = dat[i] + x;
    }

    // [1, a], a is 1-indexed
    inline Abel sum(int a) {a++;
        Abel res = UNITY_SUM;
        for (int i = a; i > 0; i -= i & -i)
            res = res + dat[i];
        return res;
    }
};

ll calc(ll a,ll b,ll c,ll d,ll n){
	a = modpow(2LL,a);
	d = modpow(2LL,d);
	a += d - 1;
	b = modpow(2LL,b);
	c = modpow(2LL,c);
	b += c - 1;
	a %= mod;
	b %= mod;
	a *= b;
	a %= mod;
	ll ret = modpow(2LL,n) - a;
	ret %= mod;
	ret += mod;
	ret %= mod;
	return ret;
}
