#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef complex<double> Vec;

ll N;
const ll MOD = 998244353;
vector<ll> Pow;
vector<ll> Y;
vector<pair<ll, ll>> XY;
map<ll, ll> IY;
ll R;

void prepare() {
  Pow.push_back(0);
  for (ll i = 1; i <= N; ++i) {
    Pow.push_back((Pow.back() * 2 + 1) % MOD);
  }
}

vector<ll> BIT;
void add(ll i, ll x) {
  for (; i <= N; i += i & -i) BIT[i] += x;
}
ll sum(ll i) {
  ll res = 0;
  for (; i > 0; i -= i & -i) res += BIT[i];
  return res;
}
void solve() {
  R = N * Pow[N] % MOD;
  for (ll i = 0; i < N; ++i) {
    (R += MOD - 2 * (Pow[i] + Pow[N - 1 - i]) % MOD) %= MOD;
  }
  for (ll i = 0; i < 2; ++i) {
    BIT.clear();
    BIT.resize(N + 1);
    for (ll cnt = 0; cnt < N; ++cnt) {
      ll y = XY[i == 0 ? cnt : N - 1 - cnt].second;
      ll i = IY.at(y) + 1;
      ll left = sum(i);
      ll right = cnt - left;
      assert(left >= 0 && right >= 0);
      (R += Pow[left]) %= MOD;
      (R += Pow[right]) %= MOD;
      add(i, 1);
    }
  }
}

int main() {
  cin >> N;
  prepare();
  for (ll i = 0; i < N; ++i) {
    ll x, y;
    cin >> x >> y;
    Y.push_back(y);
    XY.push_back(make_pair(x, y));
  }
  sort(Y.begin(), Y.end());
  for (ll i = 0; i < N; ++i) {
    IY[Y[i]] = i;
  }
  sort(XY.begin(), XY.end());
  solve();
  cout << R << endl;
  return 0;
}

