    for (size_t i = 0; i < n; ++i) {
      size_t j = enc.at(xy[i].second);
      st.modify(j, 1);
      c[i][1] = st.accumulate(j+1, n);
      c[i][2] = st.accumulate(0, j);
    }
  }
  {
    basic_segment_tree<range_sum_single_add<int>> st(n);
    for (size_t i = n; i--;) {
      size_t j = enc.at(xy[i].second);
      st.modify(j, 1);
      c[i][3] = st.accumulate(0, j);
      c[i][0] = st.accumulate(j+1, n);
    }
  }

  mi res = 0;
  mi two = 2;
  for (size_t i = 0; i < n; ++i) {
    int x1 = c[i][0];
    int x2 = c[i][1];
    int x3 = c[i][2];
    int x4 = c[i][3];

    res += two.pow(x1+x2+x3+x4+1) - 1;

    mi y1 = two.pow(x1) - 1;
    mi y2 = two.pow(x2) - 1;
    mi y3 = two.pow(x3) - 1;
    mi y4 = two.pow(x4) - 1;
    res -= y1 + y2 + y3 + y4;
    res -= y1*y2 + y2*y3 + y3*y4 + y4*y1;
  }

  printf("%jd\n", res.get());
}

