        cin >> x >> y;
        xy[i] = make_pair(x, y);
        ys[i] = y;
    }
    map<int, int> mp;
    sort(ys.begin(), ys.end());
    for(int y : ys) mp[y] = mp.size() + 1;
    for(auto &z : xy){
        z = make_pair(z.first, mp[z.second]);
    }
    sort(xy.begin(), xy.end());

    FenwickTree<int> A(N+10), B(N+10);
    A.add(xy[0].second, 1);
    REP(i, 1, N) B.add(xy[i].second, 1);
    long long ans = 0;
    for(int i=1; i<N-1; i++){
        int y = xy[i].second;
        B.add(y, -1);

        int a0 = A.get(y);
        int b0 = A.get(N+10) - a0;
        int b1 = B.get(y);
        int a1 = B.get(N+10) - b1;
        long long a0pow = bipow(2, a0);
        long long a1pow = bipow(2, a1);
        long long b0pow = bipow(2, b0);
        long long b1pow = bipow(2, b1);
        long long tmp0 = ((a0pow-1)*(a1pow-1))%MOD;
        long long tmp1 = ((b0pow-1)*(b1pow-1))%MOD;
        long long tmp2 = (tmp0 * tmp1) % MOD;
        tmp0 = (tmp0 * b0pow) % MOD;
        tmp0 = (tmp0 * b1pow) % MOD;
        tmp1 = (tmp1 * a0pow) % MOD;
        tmp1 = (tmp1 * a1pow) % MOD;
        long long tmp4 = (tmp0 + tmp1) % MOD;
        tmp4 += MOD - tmp2;
        tmp4 %= MOD;
        ans = (ans + tmp4) % MOD;

        A.add(y, 1);
    }
    ans += (N * bipow(2, N-1)) % MOD;
    ans %= MOD;
    cout << ans << endl;
    return 0;
}

