using E = LL;
const auto fs = [](S l, S r) {return S{l.v + r.v, l.size + r.size};};
const auto fa = [](S l, E r) {return S{l.v + r * l.size, l.size};};
const auto fe = [](E l, E r) {return l + r;};
const auto es = S(0, 1);
const auto ee = E(0);

LL power(LL m, LL n) {
  if(!n) return 1;
  return (n & 1) ? (power(m, n - 1) * m % M) : power(m * m % M, n >> 1);
}

int main() {
  struct Point {LL x, y, ul, ur, ll, lr;};
  int N;
  cin >> N;
  vector<Point> P(N);
  for(auto& i: P) cin >> i.x >> i.y;

  sort(begin(P), end(P), [](auto& l, auto& r){
    if(l.x != r.x) return l.x < r.x;
    return l.y < r.y;
  });
  SegmentTreeDLP<S,E> rsq(-INF, INF, fs,fa,fe,es,ee);
  for(auto& p: P) {
    p.ll = rsq.query(-INF,  p.y+1).v;
    p.ul = rsq.query(p.y+1, INF).v;
    rsq.set(p.y, 1);
  }

  sort(begin(P), end(P), [](auto& l, auto& r){
    if(l.x != r.x) return l.x > r.x;
    return l.y > r.y;
  });
  rsq = SegmentTreeDLP<S,E>(-INF, INF, fs,fa,fe,es,ee);
  for(auto& p: P) {
    p.ur = rsq.query(p.y,  INF).v;
    p.lr = rsq.query(-INF, p.y).v;
    rsq.set(p.y, 1);
  }

  LL ans = 0;
  for(auto& p: P) {
    (ans += power(2,N-1)) %= M;
    auto urll = (power(2,p.ur)-1) * (power(2,p.ll)-1) % M;
    auto ullr = (power(2,p.ul)-1) * (power(2,p.lr)-1) % M;
    (ans += urll * power(2,N-1-p.ur-p.ll) % M) %= M;
    (ans += ullr * power(2,N-1-p.ul-p.lr) % M) %= M;
    (ans += M - (urll*ullr%M) * power(2,N-1-p.ur-p.ll-p.ul-p.lr)%M) %= M;
  }
  cout << ans << endl;
}

