struct BIT {
  int sz;
  vi node;
  BIT(int n): sz(n+1), node(vi(n+1)) {}

  void add(int idx, int val) {
    idx++;
    while(idx < sz) {
      node[idx] += val;
      idx += idx & -idx;
    }
  }

  int sum(int idx) {
    idx++;
    int res = 0;
    while(idx) {
      res += node[idx];
      idx -= idx & -idx;
    }
    return res;
  }

};



