        sort(p.begin(), p.begin() + N);
        transform(p.cbegin(), p.cbegin() + N, perm.begin(), [](auto i){return i.second;});
    }

    constexpr unsigned long MOD = 998244353;
    array<unsigned long, maxN> binary;
    unsigned long n = binary[0] = 1;
    generate(binary.begin() + 1, binary.end(), [&n](){if(n >= MOD)n -= MOD;return n <<= 1;});

    array<unsigned int, maxN> fenwick_tree{};
    auto que = [&fenwick_tree, &N](unsigned int i){
        unsigned int s{0}, j{i};
        while(i){
            s += fenwick_tree[i];
            i -= i & -i;
        }
        while(j <= N){
            ++fenwick_tree[j];
            j += j & -j;
        }
        return s;
    };

    array<unsigned int, maxN> coef{};
    coef[N] = N + MOD - 4;
    for(unsigned int i = 0; i != N; ++i){
        auto p = perm[i], q = que(p);
        ++coef[q];
        ++coef[i - q];
        ++coef[p - q - 1];
        ++coef[N - i - p + q];
    }

    cout << inner_product(binary.begin(), binary.begin() + N + 1, coef.begin(), 4 + MOD - N) % MOD << endl;
    return 0;
}

