template <typename T=int>
struct Fenwick {
    int n;
    vector<T> v;

    Fenwick(int size = 100005) : n(size), v(n+1, 0) {}
    inline void add(int p, T val) {
        for (; p <= n; p += (p&-p)) { v[p] += val; }
    }
    inline T query(int p) {
        T tmp = 0;
        for (; p > 0; p -= (p&-p)) { tmp += v[p]; }
        return tmp;
    }
    inline T query(int l, int r) {
        return query(r) - query(l-1);
    }
};

template <typename T=int>
struct Compress {
    map<T, int> id;
    vector<T> num;

    Compress(vector<T> v) {
        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());
        num = v;
        for (int i = 0; i < (int)num.size(); i++) {
            id[num[i]] = i;
        }
    }

    inline int get_id(T x) {
        assert(id.count(x));
        return id[x];
    }
    inline T get_num(int i) {
        assert(0 <= i && i < num.size());
        return num[i];
    }
};

struct Point {
    int x, y;
    Point() {}
};

void solve() {
    int n; cin >> n;
    vector<Point> a(n);
    for (auto& p: a) {
        cin >> p.x >> p.y;
    }
    sort(a.begin(), a.end(), [](auto& u, auto& v){
            return u.x < v.x;
            });
    vector<int> Y(n);
    for (int i = 0; i < n; i++) {
        Y[i] = a[i].y;
    }
    Compress<int> cy(Y);
    Fenwick<int> pre(n), suf(n);
    vector<array<int,4>> cnt(n);
    for (int i = 0; i < n; i++) {
        int y = cy.get_id(a[i].y)+1;
        int les = pre.query(y);
        cnt[i][0] = les;
        cnt[i][1] = i - les;
        pre.add(y, 1);
    }
    for (int i = n-1; i >= 0; i--) {
        int y = cy.get_id(a[i].y)+1;
        int les = suf.query(y);
        cnt[i][2] = les;
        cnt[i][3] = n-i-1 - les;
        suf.add(y, 1);
    }

    vector<mint> pw(n+1);
    pw[0] = 1;
    for (int i = 1; i <= n; i++) {
        pw[i] = 2 * pw[i-1];
    }
    mint res = 0;
    for (int i = 0; i < n; i++) {
        mint a = pw[cnt[i][0]];
        mint b = pw[cnt[i][1]];
        mint c = pw[cnt[i][2]];
        mint d = pw[cnt[i][3]];

        res += (a-1)*(d-1)*b*c + (b-1)*(c-1)*a*d - (a-1)*(b-1)*(c-1)*(d-1);
        res += pw[n-1];
    }
    cout << res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    solve();
    cout << endl;
}

