signed main(){
  int N;cin>>N;
  std::vector<int> x(N),y(N);
  for(int i=0;i<N;i++)cin>>x[i]>>y[i];
  typedef pair<int,int> P;
  std::vector<P> v(N);
  for(int i=0;i<N;i++)v[i]=P(x[i],y[i]);
  sort(v.begin(),v.end());
  map<int,int> mx,my;//mxはデバッグする時にあると楽
  for(int i=0;i<N;i++)mx[x[i]]=my[y[i]]=0;
  int cnt=0;for(auto &p:my)p.second=++cnt;
  cnt=0;for(auto &p:mx)p.second=++cnt;
  BIT<int> b1(223456,0),b2(223456,0);
  std::vector<int> ru(N,0),rd(N,0),lu(N,0),ld(N,0);
  for(int i=0;i<N;i++){
    ld[i]=b1.sum(my[v[i].second]);
    lu[i]=i-ld[i];
    b1.add(my[v[i].second],1);
  }
  for(int i=N-1;i>=0;i--){
    rd[i]=b2.sum(my[v[i].second]);
    ru[i]=N-1-i-rd[i];
    b2.add(my[v[i].second],1);
  }
  int ans=0;
  for(int i=0;i<N;i++){
    int a=pw(2,lu[i]),b=pw(2,ru[i]),c=pw(2,ld[i]),d=pw(2,rd[i]);
    ans+=(((b-1)*(c-1)%MOD)*((a*d)%MOD))%MOD;ans%=MOD;
    ans+=((a-1)*(d-1))%MOD*(b+c-1)%MOD;ans%=MOD;
  }
  ans+=pw(2,N-1)*N%MOD;ans%=MOD;
  cout<<ans<<endl;
}

