template <class T> struct BIT_{
	vector<T> v; ll N;
	BIT_(){}
	BIT_(ll N) { Init(N); }
	void Init(ll N) { v.resize(N+1); this->N = N; }
	void add(ll i, T x) { for (i++; i<=N; i+=i&(-i)) v[i]+=x; }
	T sum(ll i) { T s=0;  for (i++; i>0; i-=i&(-i)) s+=v[i];  return s; }
	T sum(ll i, ll j) { return sum(j)-sum(i-1); }
	ll lower_bound(T s){
		ll i=0;
		for (ll l=Upper2N(N-1); l>0; l>>=1)  if (i+l<=N && v[i+l]<s) s-=v[i+=l];
		return i;
	}
	void Dump() { REP(i, N) cerr <<setw(3)<< i << " " <<setw(5)<< sum(i, i) << '\n'; }
};
using BIT = BIT_<ll>;


void solve()
{
	ll N;  cin >> N;
	vector<pair<ll, ll>> XY = cinv2<ll, ll>(N);

	map<ll, ll> mpx;
	map<ll, ll> mpy;
	rep(i, 0, N-1){
		ll x; ll y;  tie(x, y) = XY[i];
		mpx[x]=0;
		mpy[y]=0;
	}
	{
		ll cnt=0;
		EACH(e, mpx) e.second = cnt++;
	}
	{
		ll cnt=0;
		EACH(e, mpy) e.second = cnt++;
	}
	EACH(e, XY){
		e.first = mpx[e.first];
		e.second= mpy[e.second];
	}

	sort(ALL(XY));

	BIT bitr(N), bitl(N);
	EACH(e, XY){
		bitr.add(e.second, 1);
	}

	mll ans = 0;
	rep(i, 0, N-1){
		ll x; ll y;  tie(x, y) = XY[i];
		bitr.add(y, -1);
		ll D = bitr.sum(0, y);
		ll C = bitr.sum(y, N-1);
		ll B = bitl.sum(0, y);
		ll A = bitl.sum(y, N-1);

		ans += POW(mll(2), N)-1 - (
			  POW(mll(2), A+B)-1
			+ POW(mll(2), A+C)-1
			+ POW(mll(2), B+D)-1
			+ POW(mll(2), C+D)-1
			- POW(mll(2), A)+1
			- POW(mll(2), B)+1
			- POW(mll(2), C)+1
			- POW(mll(2), D)+1);

		bitl.add(y, 1);
	}
	cout << ans << '\n';
}

