using Size = int;
template<typename T> class Compression {
 public:
  Compression(const std::vector<T>& list) : value_(list) {
    std::sort(begin(value_), end(value_));
    value_.erase(std::unique(begin(value_), end(value_)), end(value_));
    for(Size i = 0; i < value_.size(); ++i) index_[value_[i]] = i;
  }
  Size size() const {return value_.size();}
  Size index(const T& v) const {return index_.at(v);}
  T operator[](const Size i) const {return value_.at(i);}
 private:
  std::unordered_map<T, Size> index_;
  std::vector<T> value_;
};

#include<vector>
template<typename T> class SegmentTree {
 public:
  SegmentTree(int n) : n(size(n)), dat(size(n) << 1), laz(size(n) << 1) {}
  void add(int a, int b, T v) {add(a, b, v, 1, 0, n);}
  T sum(int a, int b) {return sum(a, b, 1, 0, n);}
 private:
  constexpr int size(int n) const {return n & (n - 1) ? size(n + (n & -n)) : n;}
  inline int lchild(int k) const {return (k << 1);}
  inline int rchild(int k) const {return (k << 1) | 1;}
  inline void propagate(int k, int l, int r) {
    if(k < n) {
      laz[lchild(k)] += laz[k];
      laz[rchild(k)] += laz[k];
    }
    dat[k] += (r - l) * laz[k];
    laz[k] = 0;
  }
  T add(int a, int b, T v, int k, int l, int r) {
    propagate(k, l, r);
    if(b <= l || r <= a) return dat[k];
    if(a <= l && r <= b) return dat[k] + (r - l) * (laz[k] = v);
    auto m = (l + r) >> 1;
    auto vl = add(a, b, v, lchild(k), l, m);
    auto vr = add(a, b, v, rchild(k), m, r);
    return dat[k] = vl + vr;
  }
  T sum(int a, int b, int k, int l, int r) {
    propagate(k, l, r);
    if(b <= l || r <= a) return 0;
    if(a <= l && r <= b) return dat[k];
    auto m = (l + r) >> 1;
    auto vl = sum(a, b, lchild(k), l, m);
    auto vr = sum(a, b, rchild(k), m, r);
    return vl + vr;
  }
  int n;
  std::vector<T> dat, laz;
};

