    return l.y < r.y;
  });
  SegmentTree<int> rsq(C.size());
  for(auto& p: P) {
    p.ll = rsq.sum(C.index(-INF),  C.index(p.y)+1);
    p.ul = rsq.sum(C.index(p.y)+1, C.index(INF));
    rsq.add(C.index(p.y), C.index(p.y)+1, 1);
  }

  sort(begin(P), end(P), [](auto& l, auto& r){
    if(l.x != r.x) return l.x > r.x;
    return l.y > r.y;
  });
  rsq = SegmentTree<int>(C.size());
  for(auto& p: P) {
    p.ur = rsq.sum(C.index(p.y),  C.index(INF));
    p.lr = rsq.sum(C.index(-INF), C.index(p.y));
    rsq.add(C.index(p.y), C.index(p.y)+1, 1);
  }

  LL ans = 0;
  for(auto& p: P) {
    (ans += power(2,N-1)) %= M;
    auto urll = (power(2,p.ur)-1) * (power(2,p.ll)-1) % M;
    auto ullr = (power(2,p.ul)-1) * (power(2,p.lr)-1) % M;
    (ans += urll * power(2,N-1-p.ur-p.ll) % M) %= M;
    (ans += ullr * power(2,N-1-p.ul-p.lr) % M) %= M;
    (ans += M - (urll*ullr%M) * power(2,N-1-p.ur-p.ll-p.ul-p.lr)%M) %= M;
  }
  cout << ans << endl;
}

