struct fenwick {
    int n;
    vector<int> F;

    fenwick(int n) : n(n), F(vector<int>(n)) { }

    void upd(int i, int x) {
        for (; i < n; i |= i + 1) F[i] += x;
    }

    int get(int r) {
        int res = 0;

        for (; r >= 0; r &= r + 1, --r)
            res += F[r];

        return res;
    }
