    sort(p, p + n);
    vector<int> v;

    for (int i = 0; i < n; ++i)
        v.emplace_back(p[i].y);

    sort(begin(v), end(v));
    v.resize(unique(begin(v), end(v)) - begin(v));
    fenwick f(v.size());

    for (int i = 0; i < n; ++i) {
        ans -= pw[i];
