using namespace std;

class bit{
    private:
        vector<int> values;
        int length;

    public:
        bit(int length){
            values = vector<int>(length + 1, 0);
            this -> length = length;
        }
        void add(int index, int value){
            for(int i = index; i <= length; i += i & -i){
                values[i] += value;
            }
        }
        int sum(int n){
            int ret = 0;

            for(int i = n; i > 0; i -= i & -i){
                ret += values[i];
            }
            return ret;
        }
};

llint mod_pow(llint a, llint n, llint p){
    if (n == 0) {
        return 1;
    } else if (n % 2 == 0) {
        llint d = mod_pow(a, n / 2, p);

        return (d * d) % p;
    } else {
        return (a * mod_pow(a, n - 1, p)) % p;
    }
}
int main(){
    int N;

    cin >> N;

    vector<pair<int, int>> xy(N);

    for(int i = 0; i < N; i ++){
        int x, y;

        cin >> x >> y;

        xy[i] = make_pair(x, y);
    }
    sort(xy.begin(), xy.end());

    vector<pair<int, int>> yi(N);

    for(int i = 0; i < N; i ++){
        yi[i] = make_pair(xy[i].second, i + 1);
    }
    sort(yi.begin(), yi.end(), greater<pair<int, int>>());

    vector<llint> A(N), B(N), C(N), D(N);
    bit b(N), c(N);

    for(int i = 0; i < N; i ++){
        b.add(yi[i].second, 1);

        A[i] = mod_pow(2, b.sum(N) - b.sum(yi[i].second), P);
        B[i] = mod_pow(2, b.sum(yi[i].second) - 1, P);
    }
    for(int i = N - 1; i >= 0; i --){
        c.add(yi[i].second, 1);

        C[i] = mod_pow(2, c.sum(yi[i].second) - 1, P);
        D[i] = mod_pow(2, c.sum(N) - c.sum(yi[i].second), P);
    }
    llint ans = 0;

    for(int i = 0; i < N; i ++){
        llint temp;

        temp = A[i];
        temp = (temp * B[i]) % P;
        temp = (temp * C[i]) % P;
        temp = (temp * D[i]) % P;
        ans = (ans + temp) % P;

        temp = A[i] - 1;
        temp = (temp * (B[i] - 1)) % P;
        temp = (temp * (C[i] - 1)) % P;
        temp = (temp * (D[i] - 1)) % P;
        ans = (ans + temp) % P;

        temp = A[i] - 1;
        temp = (temp * (C[i] - 1)) % P;
        temp = (temp * (B[i] + D[i] - 1)) % P;
        ans = (ans + temp) % P;

        temp = B[i] - 1;
        temp = (temp * (D[i] - 1)) % P;
        temp = (temp * (A[i] + C[i] - 1)) % P;
        ans = (ans + temp) % P;
    }
    cout << ans << endl;
}

