struct mint {
    long long x;
    mint(long long x=0):x((x%MOD+MOD)%MOD){}
    mint operator-() const { return mint(-x);}
    mint& operator+=(const mint a) {
        if ((x += a.x) >= MOD) x -= MOD;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += MOD-a.x) >= MOD) x -= MOD;
    	return *this;
    }
    mint& operator*=(const mint a) {
    	(x *= a.x) %= MOD;
    	return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(long long t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
    	if (t&1) a *= *this;
        return a;
    }
    // for prime MOD
    mint inv() const {
        return pow(MOD-2);
    }
    mint& operator/=(const mint a) {
    	return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
};

template<typename T>
struct BIT{
    private:
        using Func = function<T(T, T)>;

        int n;
        vector<T> node;

        T init_v;
        Func func;

    public:

        BIT(vector<T> a, Func _func, T _init_v) {
            n = a.size() + 1;
            init_v = _init_v;
            func = _func;

            node.resize(n, init_v);
            for(int i=1; i<n; i++) if((i+(i&-i)) < n) node[i+(i&-i)] = func(node[i+(i&-i)], node[i]);
        }

        BIT() {}

        void add(int pos, T v) {
            // 1-indexed
            while(pos < n){
                node[pos] = func(node[pos], v);
                pos += pos & -pos;
            }
        }

        T sum(int pos){
            // 1-indexed
            T res = init_v;
            while(pos > 0){
                res = func(res, node[pos]);
                pos = pos & (pos-1);
            }
            return res;
        }
};

vector<int> compress(vector<int> &v){
    int N = v.size(), mn = 1000000000;
    vector<int> res(N);
    vector<pair<int,int>> a(N);
    for(int i=0; i<N; ++i){
        a[i].first = v[i];
        a[i].second = i;
        mn = min(mn, v[i]);
    }
    sort(a.begin(), a.end());

    int prev = mn-1, n = -1;
    for(int i=0; i<N; ++i){
        if(a[i].first == prev) res[a[i].second] = n;
        else{
            n++;
            prev = a[i].first;
            res[a[i].second] = n;
        }
    }

    return res;
}

int main(void){
    auto f = [](int a, int b){return a+b;};
    ll N; cin >> N;
    VI x(N), y(N); REP(i,N) cin >> x[i] >> y[i];
    x = compress(x); y = compress(y);
    VI y2x(N); REP(i,N) y2x[y[i]] = x[i];
    SORT(y);

    BIT<int> bit(VI(N,0), f, 0);
    mint ans;
    vector<mint> p(N+1); p[0] = 1; REP(i,N) p[i+1] = p[i]*2;
    REP(i,N){
        int xx = y2x[y[i]];
        int t = bit.sum(xx+1);
        ll ort[5];
        ort[0] = N-1-xx-i+t; ort[1] = xx-t;  ort[2] = t; ort[3] = i-t; ort[4] = ort[0];
        mint rmv(1);
        REP(j,4) if(ort[j] > 0) rmv += p[ort[j]]-1;
        REP(j,4) if(ort[j]>0 && ort[j+1]>0) rmv += (p[ort[j]]-1)*(p[ort[j+1]]-1);
        ans += p[N]-rmv;
        bit.add(xx+1, 1);
    }

    cout << ans.x << en;
    return 0;
}

