using namespace std;
typedef long long ll;

struct BIT
{
  vector<ll> bit;
  int M;
  BIT(int n){
    M = n;
    bit.resize(M+1);
    rep(i, bit.size()){bit[i]= 0;}
  }

  void add(int a, ll x) { // aを +x  aは 1-indexed
    if (a > M) return;
    bit[a] += x;
    add(a+(a&-a), x); //真上の階層すべてに足す
  }

  ll sum(int a) { // [1,a] 1-indexed
    if (!a) return 0; // 0 のときは0
    return bit[a] + sum(a-(a&-a)); //(a&-a) 最後の1のビットだけ立つ 区間の長さに等しい
  } // 左上のものをすべて足す

  ll sum(int a,int b){ // [a,b] 1-indexed
    return sum(b) - sum(a-1);
  }

  ll get(ll k){ // k-th number 1-indexed 二分探索
    //k-1までが全部入るresの1つ後を求める。
    ll res=0; // kがたまるまでresを増やす。
    ll N=1; while(N <= M) N*=2;
    for(int i=N/2; i>0; i/=2 ){
      if(res + i <= M and bit[res+i] <k){
        k = k-bit[res+i];
        res+=i;
      }
    }
    return res+1; // 1-indexed resまでは新kまでが全部入る
  }

};

ll modpow(ll a, ll n, ll mod=MOD){ // a^n % MOD の計算
  ll res = 1;
  while (n > 0){
    if(n & 1) res = res * a % mod;
    a = a * a  % mod;
    n >>= 1;
  }
  return res;
}


void Main(){

  ll N; cin>>N;

  vector<pair<ll,ll>> ve(N);

  rep(i,N){
    cin>>ve[i].first>>ve[i].second;
  }

  SORT(ve);

  vector<ll> x(N);
  vector<ll> y(N);

  rep(i,N){
    x[i]=ve[i].first;
    y[i]=ve[i].second;
  }

  vector<ll> xcomp,ycomp; //圧縮後のx,y
  vector<ll> valx=x,valy=y;//VALSにaをコピー
  SORT(valx);
  SORT(valy);
  rep(i,N){
    xcomp.emplace_back(lower_bound(ALL(valx), x[i]) -valx.begin());
    ycomp.emplace_back(lower_bound(ALL(valy), y[i]) -valy.begin());
  }

  ll ans=0;

  BIT bis(N+1); //小さい方から。x< かつy<を調べる
  BIT bib(N+1); //大きい方から。

  rep(i,N){
    bib.add(i+1,1);
  }

  ll xs[N],xb[N],ys[N],yb[N];

  rep(i,N){
    // 点ごとに見る。 iがそれ以下かつyがそれ以下から1個以上 逆からも1個以上のときカウント modpow(2, 数1)*modpow(2, 数2) + modpow(2, N-1)
    xs[i]=bis.sum(ycomp[i]);
    xb[i]=i-xs[i];

    bis.add(ycomp[i]+1,1);

    ys[i]=bib.sum(ycomp[i]);
    yb[i]=(N-i-1)-ys[i];

    bib.add(ycomp[i]+1,-1);
  }

  rep(i,N){

    ll A=( (modpow(2,xs[i]) - 1 ) * (modpow(2,yb[i]) -1)%MOD);
    ll B=( (modpow(2,xb[i]) - 1 ) * (modpow(2,ys[i]) -1)%MOD);

    ans=(ans+(A*modpow(2,xb[i]+ys[i])%MOD) + (B*modpow(2,xs[i]+yb[i])%MOD)-(A*B%MOD)+MOD)%MOD;

  }

  ans=(ans+N*modpow(2,N-1))%MOD;

  cout<< ans <<"\n";
}

//-----------------------------------
int main(){
  cin.tie(nullptr);
  ios_base::sync_with_stdio(false);
  cout << fixed << setprecision(15);
  Main();
}
