    map<int, int> x_zip;
    vi x_unzip(N);
    compress(x, x_zip, x_unzip);

    // y 座標の昇順にソート
    vPi point(N);
    rep(i, N) {
        point[i] = mp(y[i], x_zip[x[i]]);
    }
    sort(all(point));

    BIT bit(N);
    ModInt<MOD> ans = 0;

    rep(i, N) {
        // 現在注目している点の座標を取得
        int px = point[i].second;
        int py = point[i].first;

        // 左下、右下、左上、右上の点の数を計算
        int ld = bit.sum(px);
        int rd = i - ld;
        int lu = px - ld;
        int ru = N - 1 - ld - rd - lu;

        // 現在注目している点がカウントされる回数を包除原理で計算して足す
        ans += powMod(2, N, MOD) - 1;
        ans -= powMod(2, ld + rd, MOD) - 1;
        ans -= powMod(2, lu + ru, MOD) - 1;
        ans -= powMod(2, ld + lu, MOD) - 1;
        ans -= powMod(2, rd + ru, MOD) - 1;
        ans += powMod(2, ld, MOD) - 1;
        ans += powMod(2, rd, MOD) - 1;
        ans += powMod(2, lu, MOD) - 1;
        ans += powMod(2, ru, MOD) - 1;

        // BIT に現在注目している点を追加
        bit.add(px, 1);
    }
    cout << ans << endl;

    return 0;
}

