	}

	sort(all(p));
	for(ll i = 0; i < n; i++) {
		swap(p[i].first, p[i].second);
		p[i].second = i;
	}
	sort(all(p));
	for(ll i = 0; i < n; i++) {
		swap(p[i].first, p[i].second);
		p[i].second = i;
	}
	sort(all(p));

	ll res = 0;
	ordered_set X;
	for(ll i = 0; i < n; i++) {
		X.insert(p[i].second);
		ll lb = X.order_of_key(p[i].second);
		ll l = p[i].second, b = p[i].first;
		ll r = n - l - 1, u = n - b - 1;
		ll rb = b - lb, ru = r - rb, lu = l - lb;
		assert(lu == u - ru);
		ll cur = 0;
		(cur += twos[l]) %= P;
		(cur += twos[r]) %= P;
		(cur += twos[b]) %= P;
		(cur += twos[u]) %= P;
		((cur -= twos[lu]) += P) %= P;
		((cur -= twos[ru]) += P) %= P;
		((cur -= twos[rb]) += P) %= P;
		((cur -= twos[lb]) += P) %= P;
		(res += twos[n] - cur) %= P;
	}
	cout << res << endl;
}

