void go()
{
	int n,i,x,y;
	ll ans;
	while(read(n))
	{
		tr.init(n,n);
		dx.init();
		dy.init();
		for(i=1;i<=n;i++)
		{
			read(a[i].fi,a[i].se);
			dx.add(a[i].fi);
			dy.add(a[i].se);
		}
		dx.work();
		dy.work();
		for(i=1;i<=n;i++)
		{
			x=dx.get_pos(a[i].fi);
			y=dy.get_pos(a[i].se);
			tr.upd(x,y,x,y,1);
		}
		ans=0;
		for(i=1;i<=n;i++)
		{
			x=dx.get_pos(a[i].fi);
			y=dy.get_pos(a[i].se);
			tr.upd(x,y,x,y,-1);

			add(ans,pow2(2,n));

			add(ans,-pow2(2,tr.ask(1,y,n,n)));
			add(ans,-pow2(2,tr.ask(1,1,n,y)));
			add(ans,-pow2(2,tr.ask(1,1,x,n)));
			add(ans,-pow2(2,tr.ask(x,1,n,n)));

			add(ans,pow2(2,tr.ask(1,1,x,y)));
			add(ans,pow2(2,tr.ask(1,y,x,n)));
			add(ans,pow2(2,tr.ask(x,y,n,n)));
			add(ans,pow2(2,tr.ask(x,1,n,y)));

			add(ans,-1);

			tr.upd(x,y,x,y,1);
		}
		printf("%lld\n",ans);
	}
}

