template <class Abel> struct BIT {
private:
	vector<Abel> node; int n;
    Abel UNITY_SUM = 0; //to be set
public:
	BIT(int n_) {
		n = n_; node.resize(n, UNITY_SUM);
	}
	//0-indexed
	void add(int a, Abel w) {
		for (int i = a; i < n; i |= i + 1)node[i] += w;
	}
	//[0,a)
	Abel sum(int a) {
		Abel ret = UNITY_SUM;
		for (int i = a - 1; i >= 0; i = (i&(i + 1)) - 1)ret += node[i];
		return ret;
	}
	//[a,b)
	Abel sum(int a, int b) {
		return sum(b) - sum(a);
	}
    //debug
    void print() {
        for(int i = 0; i < n; ++i) cout << sum(i, i + 1) << ",";
        cout << endl;
    }
};

void solve() {
	int n; cin >> n;
    vector<int> x(n), y(n);
    vector<P> p(n);
    rep(i, n) {
        cin >> x[i] >> y[i];
        p[i] = make_pair(x[i], y[i]);
    }
    sort(all(x)); sort(all(y));
    // x.erase(unique(all(x)), x.end());
    // y.erase(unique(all(y)), y.end());
    map<int, int> mpx, mpy;
    int k = 0;
    for(auto&X : x) {
        mpx[X] = k; ++k;
    }
    k = 0;
    for(auto&Y : y) {
        mpx[Y] = k; ++k;
    }
    sort(all(p));
    rep(i, n) {
        p[i] = make_pair(mpx[p[i].fr], mpy[p[i].sc]);
    }
    mint ans = 0;
    BIT<int> bit_bef(n), bit_aft(n);
    rep(i, n) {
        bit_bef.add(p[i].sc, 1);
    }
    rep(i, n) {
        int Y = p[i].sc;
        bit_bef.add(Y, -1);
        int a = bit_aft.sum(Y, n);
        int b = bit_aft.sum(0, Y);
        int c = bit_bef.sum(Y, n);
        int d = bit_bef.sum(0, Y);
        mint res = (modpow((mint)2, a) - 1) * (modpow((mint)2, d) - 1) * modpow((mint)2, b + c);
        res += (modpow((mint)2, b) - 1) * (modpow((mint)2, c) - 1) * modpow((mint)2, a + d);
        res += (modpow((mint)2, b) - 1) * (modpow((mint)2, c) - 1) * (modpow((mint)2, a) - 1) * (modpow((mint)2, d) - 1);
        ans += res;
        bit_aft.add(Y, 1);
    }
    cout << ans << endl;
}

