template <typename T>
struct BinaryIndexedTree {
    vector<T> data;

    BinaryIndexedTree(int sz) { data.assign(++sz, 0); }

    T sum(int k) {
        T ret = 0;
        for (++k; k > 0; k -= k & -k) ret += data[k];
        return (ret);
    }

    void add(int k, T x) {
        for (++k; k < data.size(); k += k & -k) data[k] += x;
    }
};

template <typename T = int>
struct BaseSegmentTree2D {
    int sz;
    vector<BinaryIndexedTree<T>> seg;
    virtual T f(T, T) = 0;
    virtual T g(BinaryIndexedTree<T>& bit, int, int) = 0;
    virtual void h(BinaryIndexedTree<T>& bit, int, T) = 0;

    const T identity = 0;
    vector<vector<int>> LL, RR;
    vector<vector<int>> beet;
    // lower_bound高速化(複数回クエリ用)
    vector<int> memo;

    BaseSegmentTree2D(int n) {
        sz = 1;
        while (sz < n) sz <<= 1;
        beet.resize(2 * sz);
        LL.resize(2 * sz);
        RR.resize(2 * sz);
        memo.assign(202021, -1);
    }

    void update(int a, int x, T z, int k, int l, int r) {
        if (r <= a || a + 1 <= l) return;
        if (a <= l && r <= a + 1) return h(seg[k], x, z);
        update(a, LL[k][x], z, 2 * k + 0, l, (l + r) >> 1);
        update(a, RR[k][x], z, 2 * k + 1, (l + r) >> 1, r);
        h(seg[k], x, z);
    }

    void update(int x, int y, T z) {
        if (memo[y] == -1) memo[y] = lower_bound(begin(beet[1]), end(beet[1]), y) - begin(beet[1]);
        y = memo[y];
        update(x, y, z, 1, 0, sz);
    }

    T query(int a, int b, int x, int y, int k, int l, int r) {
        if (a >= r || b <= l) return identity;
        if (a <= l && r <= b) return g(seg[k], x, y);
        return f(query(a, b, LL[k][x], LL[k][y], 2 * k + 0, l, (l + r) >> 1),
                 query(a, b, RR[k][x], RR[k][y], 2 * k + 1, (l + r) >> 1, r));
    }

    T query(int a, int b, int x, int y) {
        if (memo[x] == -1) memo[x] = lower_bound(begin(beet[1]), end(beet[1]), x) - begin(beet[1]);
        if (memo[y] == -1) memo[y] = lower_bound(begin(beet[1]), end(beet[1]), y) - begin(beet[1]);
        x = memo[x];
        y = memo[y];
        return query(a, b, x, y, 1, 0, sz);
    }

    void build() {
        for (int k = (int)beet.size() - 1; k >= sz; k--) {
            sort(begin(beet[k]), end(beet[k]));
            beet[k].erase(unique(begin(beet[k]), end(beet[k])), end(beet[k]));
        }
        for (int k = sz - 1; k > 0; k--) {
            beet[k].resize(beet[2 * k + 0].size() + beet[2 * k + 1].size());
            merge(begin(beet[2 * k + 0]), end(beet[2 * k + 0]), begin(beet[2 * k + 1]), end(beet[2 * k + 1]),
                  begin(beet[k]));
            beet[k].erase(unique(begin(beet[k]), end(beet[k])), end(beet[k]));
            LL[k].resize(beet[k].size() + 1);
            RR[k].resize(beet[k].size() + 1);
            int tail1 = 0, tail2 = 0;
            for (int i = 0; i < beet[k].size(); i++) {
                while (tail1 < beet[2 * k + 0].size() && beet[2 * k + 0][tail1] < beet[k][i]) ++tail1;
                while (tail2 < beet[2 * k + 1].size() && beet[2 * k + 1][tail2] < beet[k][i]) ++tail2;
                LL[k][i] = tail1, RR[k][i] = tail2;
            }
            LL[k][beet[k].size()] = (int)beet[2 * k + 0].size();
            RR[k][beet[k].size()] = (int)beet[2 * k + 1].size();
        }
        for (int k = 0; k < beet.size(); k++) {
            seg.emplace_back(BinaryIndexedTree<T>(beet[k].size()));
        }
    }

    // build前にクエリする位置を登録しておく
    void preupdate(int x, int y) { beet[x + sz].push_back(y); }
};

template <typename T>
struct SegmentTree2D : BaseSegmentTree2D<T> {
    T f(T x, T y) { return x + y; }
    T g(BinaryIndexedTree<T>& bit, int x, int y) { return bit.sum(y - 1) - bit.sum(x - 1); };
    void h(BinaryIndexedTree<T>& bit, int x, T y) { return bit.add(x, y); }
    SegmentTree2D(int n) : BaseSegmentTree2D<T>(n) {}
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    const int MAX = 202020;
    SegmentTree2D<int> seg(MAX);
    vector<pair<int, int>> ps;
    map<int, int> mpx, mpy;

    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        mpx[a], mpy[b];
        ps.emplace_back(a, b);
    }
    int N = 0;
    for (auto& p : mpx) p.second = N++;
    N = 0;
    for (auto& p : mpy) p.second = N++;
    for (int i = 0; i < n; i++) {
        ps[i].first = mpx[ps[i].first];
        ps[i].second = mpy[ps[i].second];
        seg.preupdate(ps[i].first, ps[i].second);
    }

    seg.build();
    for (int i = 0; i < n; i++) {
        seg.update(ps[i].first, ps[i].second, 1);
    }

    mint ans = 0;
    mint all = pow(mint(2), n) - 1;
    for (int i = 0; i < n; i++) {
        mint tmp = all;
        int x = ps[i].first, y = ps[i].second;
        int t = seg.query(0, MAX, y + 1, MAX);
        int b = seg.query(0, MAX, 0, y);
        int l = seg.query(0, x, 0, MAX);
        int r = seg.query(x + 1, MAX, 0, MAX);
        int tl = seg.query(0, x, y + 1, MAX);
        int tr = seg.query(x + 1, MAX, y + 1, MAX);
        int bl = seg.query(0, x, 0, y);
        int br = seg.query(x + 1, MAX, 0, y);
        tmp -= pow(mint(2), t);
        tmp -= pow(mint(2), b);
        tmp -= pow(mint(2), l);
        tmp -= pow(mint(2), r);
        tmp += pow(mint(2), tl);
        tmp += pow(mint(2), tr);
        tmp += pow(mint(2), bl);
        tmp += pow(mint(2), br);
        ans += tmp;
    }

    cout << ans << endl;
}

