typedef tuple<ll, ll, ll> iii;
typedef vector<ll> vi;
typedef vector<ii> vii;
typedef vector<iii> viii;
typedef vector<vi> vvi;
typedef vector<vii> vvii;
#define REP(i,n) for (ll i = 0; i < n; ++i)
#define REPR(i,n) for (ll i = n-1; i >= 0; --i)
#define FOR(i,m,n) for (int i = m; i < n; ++i)
#define FORR(i,m,n) for (ll i = n-1; i >= m; --i)
#define FORE(x,xs) for (const auto& x : xs)
#define PB push_back
#define MP make_pair
#define MT make_tuple
#define ALL(v) v.begin(), v.end()

const int MAX = 2e5+10;
const int MOD = 998244353;

int N;
int X[MAX], Y [MAX], quad[MAX][4];
vii xs, ys, xy;

struct BIT {
    vector<ll> data;
    int N;

    BIT(int n) {
        N = 1;
        while (N < n) N *= 2;
        N *= 2;

        data = vector<ll>(N+1);
    }

    void add(int i, ll x) {
        for (int k = i; k <= N; k += k&-k) data[k] += x;
    }

    void update(int i, ll x) {
        add(i, x-get(i));
    }

    ll sum(int i) {
        ll res = 0;
        for (int k = i; k > 0; k -= k&-k) res += data[k];
        return res;
    }

    ll get(int i) {
        return sum(i) - sum(i-1);
    }
};

ll pow(ll n, ll k) {
    ll res = 1;
    while (k) {
        if (n&1) res = res*n%MOD;
        n = n*n%MOD;
        k >> 1;
    }
    return res;
}

int calc(int n) {
    ll count = 4ll * MOD + pow(2, N) - 1;
    REP (i,4) {
        count -= pow(2, (quad[n][i] + quad[n][(i+1)%4])) - 1;
        count += pow(2, quad[n][i]) - 1;
    }
    return count % MOD;
}

int solve() {
    REP (i, N) {
        xs.PB(MP(X[i], i)); ys.PB(MP(Y[i], i));
    }
    sort(ALL(xs)); sort(ALL(ys));
    REP (i, N) {
        X[xs[i].second] = i+1;
        Y[ys[i].second] = i+1;
    }
    REP (i, N) xy.PB(MP(X[i], Y[i]));
    sort(ALL(xy));

    BIT bitL(MAX), bitR(MAX);
    REP (i, N) {
        quad[i][0] = bitL.sum(xy[i].second);
        quad[i][1] = i - quad[i][0];
        bitL.add(xy[i].second, 1);

        quad[N-i-1][2] = bitR.sum(MAX-xy[N-i-1].second);
        quad[N-i-1][3] = i - quad[N-i-1][2];
        bitR.add(MAX-xy[N-i-1].second, 1);
    }

    ll ans = 0;
    REP (i, N) ans += calc(i);
    return ans % MOD;
}

int main() {
    cin >> N;
    REP (i, N) cin >> X[i] >> Y[i];
    cout << solve() << endl;
}

#include<bits/stdc++.h>
#define mod 998244353
#define M 200007
using namespace std;
struct mo{
	int x,y;
}a[M];
int n,X[M],Y[M],c[M];
long long ans,pre[507]={1};
bool Mo(mo x,mo y){
	return x.y<y.y;
}
void add(int x){
	while(x<M)c[x]++,x+=x&-x;
}
int query(int x){
	int res=0;
	while(x)res+=c[x],x-=x&-x;
	return res;
}
int main() {
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
		pre[i]=pre[i-1]*2%mod;
	for(int i=1;i<=n;i++)
		scanf("%d%d",&a[i].x,&a[i].y),X[i]=a[i].x,Y[i]=a[i].y;
	sort(X+1,X+n+1),sort(Y+1,Y+n+1);
	for(int i=1;i<=n;i++){
		a[i].x=lower_bound(X+1,X+n+1,a[i].x)-X;
		a[i].y=lower_bound(Y+1,Y+n+1,a[i].y)-Y;	
	}
	ans=n*(pre[n]-1)%mod;
	for(int i=1;i<=n;i++){
		ans=(ans-pre[i]+2+mod)%mod;
		ans=(ans-pre[n-i+1]+2+mod)%mod;
	}
	sort(a+1,a+n+1,Mo);
	for(int i=1;i<=n;i++){
		int p=query(a[i].x);
		ans=(ans+pre[p]-1)%mod;
		ans=(ans+pre[i-p-1]-1)%mod;
		add(a[i].x);
	}
	memset(c,0,sizeof c);
	for(int i=n;i>=1;i--){
		int p=query(a[i].x);
		ans=(ans+pre[p]-1)%mod;
		ans=(ans+pre[n-i-p]-1)%mod;
		add(a[i].x);
	}
	printf("%lld\n",ans);
	return 0;
}

