int bs(int u) {
    int dau = 0, cuoi = SZ(b)-1;
    while (dau <= cuoi) {
        int mid = (dau + cuoi) >> 1;
        if (b[mid] > u) cuoi = mid-1;
        else dau = mid+1;
    }
    return cuoi;
}

void update(int k, int l, int r, int u) {
    if (l > r || r < u || u < l) return;
    if (l == r) {
        t[k] = 1;
        return;
    }
    int m = (l + r) >> 1;
    if (u <= m) update(k * 2, l, m, u);
    else update(k * 2 + 1, m + 1, r, u);
    t[k] = t[k * 2] + t[k * 2 + 1];
}

int get(int k, int l, int r, int u, int v) {
    if (r < u || v < l || l > r) return 0;
    if (u <= l && r <= v) return t[k];
    int m = (l + r) >> 1;
    return get(k*2, l, m, u, v) + get(k*2+1, m+1, r, u, v);
}

