const ll mod = 998244353;
const ll INF = 1000000000000;
ll N, a[200010], b[200010], c[200010], d[200010], x[200010], y[200010], bit[200010], Y_Coordinates[200010], ans;
vector<ll> X_Order, Y_Order;
map<ll, ll> X_Compression, Y_Compression;

ll pow_mod(ll x, ll y)
{
	if (y == 0) return 1;
	if (y % 2 == 1)
	{
		return pow_mod(x, y - 1) * x % mod;
	}
	else
	{
		ll half = pow_mod(x, y / 2);
		return half * half % mod;
	}
}

ll sum(ll i)
{
	ll s = 0;
	while (i > 0)
	{
		s += bit[i];
		i -= i & -i;
	}
	return s;
}

void add(ll i, ll x)
{
	while (i <= N)
	{
		bit[i] += x;
		i += i & -i;
	}
}

int main()
{
	cin >> N;
	for (int i = 1; i <= N; i++)
	{
		cin >> x[i] >> y[i];
		X_Order.push_back(x[i]);
		Y_Order.push_back(y[i]);
	}

	sort(X_Order.begin(), X_Order.end());
	sort(Y_Order.begin(), Y_Order.end());

	for (int i = 0; i < N; i++)
	{
		X_Compression[X_Order[i]] = i + 1;
		Y_Compression[Y_Order[i]] = i + 1;
	}

	for (int i = 1; i <= N; i++)
	{
		x[i] = X_Compression[x[i]];
		y[i] = Y_Compression[y[i]];
		Y_Coordinates[x[i]] = y[i];
	}

	for (int i = 1; i <= N; i++)
	{
		a[i] = sum(Y_Coordinates[i]);
		b[i] = i - 1 - a[i];
		add(Y_Coordinates[i], 1);
	}

	for (int i = 0; i <= N + 1; i++)
	{
		bit[i] = 0;
	}

	for (int i = N; i >= 1; i--)
	{
		c[i] = sum(Y_Coordinates[i]);
		d[i] = N - i - c[i];
		add(Y_Coordinates[i], 1);
	}

	for (int i = 1; i <= N; i++)
	{
		(ans += pow_mod(2, N) - 1) %= mod;
		(ans += mod - pow(2, a[i] + b[i]) + 1) %= mod;
		(ans += mod - pow(2, b[i] + d[i]) + 1) %= mod;
		(ans += mod - pow(2, c[i] + d[i]) + 1) %= mod;
		(ans += mod - pow(2, c[i] + a[i]) + 1) %= mod;
		(ans += pow(2, a[i]) - 1) %= mod;
		(ans += pow(2, b[i]) - 1) %= mod;
		(ans += pow(2, c[i]) - 1) %= mod;
		(ans += pow(2, d[i]) - 1) %= mod;
	}

	cout << ans << endl;

	int www;
	cin >> www;
}

