      //4
      ans += (mint::power(2,k1)-1) * (mint::power(2,k2)-1) * (mint::power(2,k3)-1) * (mint::power(2,k4)-1) * mint::power(2,cs+1);

      //3
      ans += (
              (mint::power(2,k1)-1) * (mint::power(2,k2)-1) * (mint::power(2,k3)-1) +
              (mint::power(2,k1)-1) * (mint::power(2,k2)-1) * (mint::power(2,k4)-1) +
              (mint::power(2,k1)-1) * (mint::power(2,k3)-1) * (mint::power(2,k4)-1) +
              (mint::power(2,k2)-1) * (mint::power(2,k3)-1) * (mint::power(2,k4)-1)
