        (mint::power(2,k3)-1) * (mint::power(2,k4)-1) * (mint::power(2,cs+1) - (1 + (mint::power(2,c3)-1))) + 
        (mint::power(2,k4)-1) * (mint::power(2,k1)-1) * (mint::power(2,cs+1) - (1 + (mint::power(2,c4)-1))) +
        (mint::power(2,k1)-1) * (mint::power(2,k3)-1) * mint::power(2,cs+1) + 
        (mint::power(2,k2)-1) * (mint::power(2,k4)-1) * mint::power(2,cs+1);

      //1
      ans +=
        (mint::power(2,k1)-1) * (mint::power(2,cs+1) - (1 + (mint::power(2,c1)-1) + (mint::power(2,c4)-1))) +
        (mint::power(2,k2)-1) * (mint::power(2,cs+1) - (1 + (mint::power(2,c2)-1) + (mint::power(2,c1)-1))) +
