      //0
      ans += mint::power(2,cs) + (mint::power(2,cs) - (1 + (mint::power(2,c1)-1) + (mint::power(2,c2)-1) + (mint::power(2,c3)-1) + (mint::power(2,c4)-1)));

      seg2.update(y,1);
    }

