struct fenwick {
    int n;
    vector<int> F;

    fenwick(int n) : n(n), F(vector<int>(n)) { }

    void upd(int i, int x) {
        for (; i < n; i |= i + 1) F[i] += x;
    }

    int get(int r) {
        int res = 0;

        for (; r >= 0; r &= r + 1, --r)
            res += F[r];

        return res;
    }
};

int n;
long long ans;
long long pw[N];
pair<int, int> p[N];

bool read() {
    if (!(cin >> n))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> p[i].x >> p[i].y;

    return true;
}

void calc() {
    sort(p, p + n);
    vector<int> v;

    for (int i = 0; i < n; ++i)
        v.emplace_back(p[i].y);

    sort(begin(v), end(v));
    v.resize(unique(begin(v), end(v)) - begin(v));
    fenwick f(size(v));

    for (int i = 0; i < n; ++i) {
        ans -= pw[i];
        ans += pw[f.get(lower_bound(begin(v), end(v), p[i].y) - begin(v))];
        f.upd(lower_bound(begin(v), end(v), p[i].y) - begin(v), 1);
    }
}

void solve() {
    pw[0] = 1;
    for (int i = 0; i <= n; pw[++i] = 2 * pw[i] % M) { }
    ans = n * (pw[n] - 1);
    calc();
    for (int i = 0; i < n; p[i].x *= -1, p[i].y *= -1, ++i) { }
    calc();
    for (int i = 0; i < n; swap(p[i].x *= -1, p[i].y), ++i) { }
    calc();
    for (int i = 0; i < n; p[i].x *= -1, p[i].y *= -1, ++i) { }
    calc();
    cout << (M + ans % M) % M << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

