	int x,y,id;
	bool operator <(const Point &t)const {
		if(x!=t.x) return x<t.x;
		return y<t.y;
	}
}p[N];
int a[N],n;
int A[N],B[N],s[N];
int quick_pow(int x,int y) {
	int ans=1;
	while(y) {
		if(y&1) ans=1LL*ans*x%MD;
		y>>=1;
		x=1LL*x*x%MD;
	}
	return ans;
}
void update(int pos) {
	for(int i=pos;i<=n;i+=(i&-i)) 
		s[i]++;
}
int query(int pos) {
	int ans=0;
	for(int i=pos;i;i-=(i&-i))
		ans+=s[i];
	return ans;
}
int cal(int a,int b,int c,int d) {
	//printf("%d %d %d %d\n",a,b,c,d);
	a=quick_pow(2,a),b=quick_pow(2,b),c=quick_pow(2,c),d=quick_pow(2,d);
	return (1LL*(a-1)*b%MD*c%MD*(d-1)%MD+1LL*a*(b-1)%MD*(c-1)%MD*d%MD-1LL*(a-1)*(b-1)%MD*(c-1)%MD*(d-1)%MD)%MD;
}
int main() {
	scanf("%d",&n);
	for(int i=0;i<n;i++) scanf("%d%d",&p[i].x,&p[i].y),a[i]=p[i].y;
	sort(p,p+n),sort(a,a+n);
	for(int i=0;i<n;i++) p[i].id=lower_bound(a,a+n,p[i].y)-a,p[i].id=n-p[i].id;
	//for(int i=0;i<n;i++) printf("%d %d %d\n",p[i].x,p[i].y,p[i].id);
	for(int i=0;i<n;i++) {
		A[i]=query(p[i].id);
		update(p[i].id);
	}
	for(int i=1;i<=n;i++) s[i]=0;
	for(int i=n-1;i>=0;i--) {
		B[i]=query(p[i].id);
		update(p[i].id);
	}
	int ans=0;
	for(int i=0;i<n;i++) {
		ans=(ans+quick_pow(2,n-1))%MD;
		ans=(ans+cal(A[i],B[i],i-A[i],n-i-1-B[i]))%MD;
	}
	printf("%d\n",(ans+MD)%MD);
	return 0;
}

