const int128_t MOD = 998244353;
const int MAX_N = 2e5 + 10;
int N;
int64_t x[MAX_N], y[MAX_N];

int x_ord[MAX_N], y_ord[MAX_N];
Combi_Num cn(MAX_N, MOD);

Range_Query<ADD_SUM> rq1(MAX_N);
Range_Query<ADD_SUM> rq2(MAX_N);


int main(int argc, char **argv) {
    std::cin >> N;
    std::vector<int> vec;
    rep (i, 1, N) {
        std::cin >> x[i] >> y[i];
        vec.push_back(i);
    }

    rq1.update(0, N - 1, 1);
    rq2.update(0, N - 1, 1);

    std::sort(vec.begin(), vec.end(), [&](int i, int j){
        return x[i] < x[j];
    });

    rep (i, 0, N - 1) {
        x_ord[vec[i]] = i;
    }

    std::sort(vec.begin(), vec.end(), [&](int i, int j){
        return y[i] < y[j];
    });

    rep (i, 0, N - 1) {
        y_ord[vec[i]] = i;
    }

    std::sort(vec.begin(), vec.end(), [&](int i, int j){
        return x[i] < x[j];
    });

    int128_t ret = 0;
    rep (i, 0, N - 1) {
        //int tmp = y_ord[vec[i]] + 1;
        int128_t B = rq2.query(y_ord[vec[i]] + 1, N - 1);
        int128_t A = rq1.query(y_ord[vec[i]] + 1, N - 1) - B;
        int128_t D = N - i - 1 - B;
        int128_t C = N - 1 - A - B - D;

        //std::cout << i << " " << vec[i] << " " << y_ord[vec[i]] << std::endl;
        //std::cout << A << " " << B << " " << C << " " << D << std::endl;

        int128_t tmp = pow_mod(2, N - 1, MOD);
        int128_t tmp2 = pow_mod(2, A + B, MOD) + pow_mod(2, A + C, MOD) + pow_mod(2, B + D, MOD) + pow_mod(2, C + D, MOD);
        tmp2 -= pow_mod(2, A, MOD) + pow_mod(2, B, MOD) + pow_mod(2, C, MOD) + pow_mod(2, D, MOD);
        tmp2 += 1;

        ret = (ret + tmp + (tmp - tmp2) + MOD * 10) % MOD;

        //std::cout << ret << std::endl;

        rq2.update_spot(y_ord[vec[i]], -1);
    }

    std::cout << ret << std::endl;

    return 0;
}

#include<bits/stdc++.h>
