typedef long long ll;

const int N = 200010;
const int MOD = 998244353;

struct point {
  int x, y;
  point() {}
};

int ft[N];

int mul(int a, int b) {
  return (ll) a * b % MOD;
}

int add(int a, int b) {
  return (a + b) % MOD;
}

int sub(int a, int b) {
  return ((a - b) % MOD + MOD) % MOD;
}

void inc(int i) {
  while (i < N) {
    ++ft[i];
    i += i & -i;
  }
}

int get(int i) {
  int sum = 0;
  while (i) {
    sum += ft[i];
    i -= i & -i;
  }
  return sum;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n;
  cin >> n;
  vector<point> P(n);
  map<int, int> fake;
  for (point &p : P) {
    cin >> p.x >> p.y;
    fake[p.y];
  }
  int id = 0;
  for (auto &f : fake) {
    f.second = ++id;
  }
  vector<int> pw(n + 1, 1);
  for (int i = 1; i <= n; ++i) {
    pw[i] = mul(pw[i - 1], 2);
  }
  for (int i = 0; i <= n; ++i) {
    pw[i] = sub(pw[i], 1);
  }
  sort(P.begin(), P.end(), [&](const point &a, const point &b) {
    return a.x < b.x;
  });
  int asw = mul(n, pw[n]);
  for (int i = 0; i < n; ++i) {
    asw = sub(asw, pw[i]);
    asw = sub(asw, pw[n - i - 1]);
    int j = fake[P[i].y];
    int u = get(j);
    asw = add(asw, pw[u]);
    asw = add(asw, pw[i - u]);
    inc(j);
  }
  fill(ft, ft + N, 0);
  for (int i = n - 1; i >= 0; --i) {
    int j = fake[P[i].y];
    int u = get(j);
    asw = add(asw, pw[u]);
    asw = add(asw, pw[n - i - u - 1]);
    inc(j);
  }
  sort(P.begin(), P.end(), [&](const point &a, const point &b) {
    return a.y < b.y;
  });
  for (int i = 0; i < n; ++i) {
    asw = sub(asw, pw[i]);
    asw = sub(asw, pw[n - i - 1]);
  }
  cout << asw << endl;
  return 0;
}

