    vi x_unzip(N);
    compress(x, x_zip, x_unzip);
    vPi point(N);
    rep(i, N) {
        point[i] = mp(y[i], x_zip[x[i]]);
    }
    sort(all(point));
    SegTree<int> st(N, 0, [](int a, int b) { return a + b; },
                    [](int a, int b) { return a + b; });
    ll ans = 0;
    rep(i, N) {
        int px = point[i].second;
        int py = point[i].first;
        int ld = st.query(0, px);
        int rd = i - ld;
        int lu = px - ld;
        int ru = N - 1 - ld - rd - lu;
        st.change(px, 1);

        ll add = 0;
        add += powMod(2, N - 1, MOD) + powMod(2, N - 1, MOD) - 1;
        add += (MOD - (powMod(2, ld + rd, MOD) + MOD - 1) % MOD) % MOD;
        add += (MOD - (powMod(2, lu + ru, MOD) + MOD - 1) % MOD) % MOD;
        add += (MOD - (powMod(2, ld + lu, MOD) + MOD - 1) % MOD) % MOD;
        add += (MOD - (powMod(2, rd + ru, MOD) + MOD - 1) % MOD) % MOD;
        add += (powMod(2, ld, MOD) + MOD - 1) % MOD;
        add += (powMod(2, rd, MOD) + MOD - 1) % MOD;
        add += (powMod(2, lu, MOD) + MOD - 1) % MOD;
        add += (powMod(2, ru, MOD) + MOD - 1) % MOD;
        add %= MOD;
        ans = (ans + add) % MOD;
    }
    cout << ans << endl;

    return 0;
}

