int num[800020];

int build(int i,int l,int r){
    if (l==r){
        num[i]=0;return 0;
    }
    build(i*2,l,(l+r)/2);build(i*2+1,(l+r)/2+1,r);
    num[i]=0;
}
int query(int i,int l,int r,int ql,int qr){
    if (l>=ql && r<=qr){
        return num[i];
    }
    if (qr<=(l+r)/2)
        return query(i*2,l,(l+r)/2,ql,qr);
    if (ql>(l+r)/2)
        return query(i*2+1,(l+r)/2+1,r,ql,qr);
    return query(i*2,l,(l+r)/2,ql,(l+r)/2)+query(i*2+1,(l+r)/2+1,r,(l+r)/2+1,qr);
}
int addt(int i,int l,int r,int tmp){
    if (l==r) {
        num[i]++;return 0;
    }
    if (tmp>(l+r)/2) addt(i*2+1,(l+r)/2+1,r,tmp);
    else addt(i*2,l,(l+r)/2,tmp);
    num[i]=num[i*2]+num[i*2+1];
}

long long pow(long long base,long long tmp){
    long long t_ans=1;
    while (tmp){
        if (tmp%2) t_ans*=base;
        t_ans%=mod;
        base*=base;base%=mod;
        tmp/=2;
    }
    t_ans-=1;
    return t_ans;
}
long long check(long long ans){
    while (ans<0) ans+=mod;
    ans%=mod;return ans;
}

