#define M 200005
#define mo 998244353
#define lowbit(x) x&-x
using namespace std;
long long Pow[M];
int n,B[M<<1],len,C[M<<1];
void Add(int x){
	while(x<=n*2){
		C[x]++;
		x+=lowbit(x);
	}
}
int query(int x){
	int res=0;
	while(x){
		res+=C[x];
		x-=lowbit(x);
	}
	return res;
}
struct ll{
	int x,y;
}A[M];
bool cmpx(ll a,ll b){
	return a.x<b.x;
}
int main(){
	scanf("%d",&n);
	Pow[0]=1;
	for(int i=1;i<=n;i++)Pow[i]=Pow[i-1]*2%mo;
	for(int i=1;i<=n;i++)scanf("%d%d",&A[i].x,&A[i].y),B[++len]=A[i].x,B[++len]=A[i].y;
	sort(B+1,B+len+1);
	len=unique(B+1,B+len+1)-B-1;
	long long ans=1ll*n*(Pow[n]-1)%mo;
	for(int i=1;i<=n;i++){
		A[i].x=lower_bound(B+1,B+len+1,A[i].x)-B;
		A[i].y=lower_bound(B+1,B+len+1,A[i].y)-B;
		ans=(ans-Pow[i-1]+1+mo)%mo;
		ans=(ans-Pow[i-1]+1+mo)%mo;
		ans=(ans-Pow[n-i]+1+mo)%mo;
		ans=(ans-Pow[n-i]+1+mo)%mo;
	}
	sort(A+1,A+n+1,cmpx);
	for(int i=1;i<=n;i++){
		int k=query(A[i].y);
		ans=(ans+Pow[k]-1)%mo;//<x,<y
		ans=(ans+Pow[i-k-1]-1)%mo;//<x,>y
		Add(A[i].y);
	}
	memset(C,0,sizeof(C));
	for(int i=n;i>=1;i--){
		int k=query(A[i].y);
		ans=(ans+Pow[k]-1)%mo;
		ans=(ans+Pow[n-i-k]-1)%mo;
		Add(A[i].y);
	}
	printf("%lld\n",ans);
	return 0;
}

