const ll DAT_SIZE=265000;

struct Segment_tree{
	// セグメント木
	ll data[DAT_SIZE],datb[DAT_SIZE];

	// [a,b)にxを加算する
	// kは節点の番号で、区間[l,r)に対応する
	void add(ll a,ll b,ll x,ll k,ll l,ll r){
		if(a<=l && r<=b){
			data[k]+=x;
		}
		else if(l<b && a<r){
			datb[k]+=(min(b,r)-max(a,l))*x;
			add(a,b,x,k*2+1,l,(l+r)/2);
			add(a,b,x,k*2+2,(l+r)/2,r);
		}
	}

	// [a,b)の和を計算する
	// kは節点の番号で、区間[l,r)に対応する
	ll sum(ll a,ll b,ll k,ll l,ll r){
		if(b<=l || r<=a){
			return 0;
		}
		else if(a<=l && r<=b){
			return data[k]*(r-l)+datb[k];
		}
		else{
			ll res=(min(b,r)-max(a,l))*data[k];
			res+=sum(a,b,k*2+1,l,(l+r)/2);
			res+=sum(a,b,k*2+2,(l+r)/2,r);
			return res;
		}
	}
};

int main(){
	ll N; cin>>N;
	Segment_tree left;
	Segment_tree right;
	rep1(i,N) right.add(i,i+1,1,1,1,N+1);
	vector<P> p(N);
	map<ll,ll> m;
	rep(i,N){
		ll x,y; cin>>x>>y;
		p[i]=P(x,y);
		m[y]=0;
	}
	ll sub=1;
	for(auto it=m.bg;it!=m.ed;it++) it->b=sub++;

	rep(i,N) p[i].b=m[p[i].b];
	sort(all(p));

	ll ans=N*power(2,N-1,MOD);
	ans%=MOD;
	rep(i,N){
		// p[i]を見る
		// 見る前にrightを減らす
		right.add(p[i].b,p[i].b+1,-1,1,1,N+1);

		// 見る
		/*
				A|B
		 p[i].b ---
				D|C
		*/
		ll A=left.sum(1,p[i].b,1,1,N+1),B=right.sum(1,p[i].b,1,1,N+1),C=right.sum(p[i].b+1,N+1,1,1,N+1),D=left.sum(p[i].b+1,N+1,1,1,N+1);

		ll A2=power(2,A,MOD)-1,B2=power(2,B,MOD)-1,C2=power(2,C,MOD)-1,D2=power(2,D,MOD)-1;
		ans+=(((A2*C2)%MOD)*power(2,B+D,MOD))%MOD;
		ans%=MOD;
		ans+=(((B2*D2)%MOD)*power(2,A+C,MOD))%MOD;
		ans%=MOD;
		ll tmp=(A2*B2)%MOD;
		tmp*=C2;
		tmp%=MOD;
		tmp*=D2;
		tmp%=MOD;
		ans-=tmp;
		if(ans<0) ans+=MOD;
		ans%=MOD;

		// 見た後にleftを増やす
		left.add(p[i].b,p[i].b+1,1,1,1,N+1);
	}
	cout<<ans;
}

