using namespace std;

const long long int N = 200005;
const long long int MOD = 998244353;
long long int x[N], y[N];
long long int power[N];
int tree[N][2];
int revert[N];

struct block{
  long long int value;
  int index;
};

bool compare(block Block1, block Block2){
  return Block1.value < Block2.value;
}

block x_block[N], y_block[N];

void update(int val, int index, int k, int n){
  while(index <=n){
    tree[index][k] += val;
    index += index & (-index);
  }
}

int query(int index, int k){
  int sum = 0;
  while(index > 0){
    sum += tree[index][k];
    index -= index & (-index);
  }

  return sum;
}

int main(){
  int n;
  long long int sum = 0;
  cin >> n;
  for (int i = 1; i <= n; ++i){
    cin >> x[i] >> y[i];
    x_block[i].value = x[i];
    x_block[i].index = i;
    y_block[i].value = y[i];
    y_block[i].index = i;
  }

  sort(x_block + 1, x_block + n + 1, compare);
  sort(y_block + 1, y_block + n + 1, compare);

  for (int i = 1; i <= n; ++i){
      revert[y_block[i].index] = i;
  }


  power[0] = 1;
  for (int i = 1; i <=n; ++i){
    update(1, i, 1, n);
    power[i] = power[i - 1] * 2 % MOD;
  }

  for (int i = 1; i <=n; ++i){
    int index = revert[x_block[i].index];
    update(-1, index, 1, n);
    int zone3 = query(index, 0);
    int zone2 = i - 1 - zone3;

    int zone4 = query(index, 1);
    int zone1 = n - i - zone4;
    update(1, index, 0, n);

    sum = (sum + power[n - 1]) % MOD;
    sum = (sum + (((power[zone1] - 1) * (power[zone3] - 1) % MOD) * power[zone2] % MOD) * power[zone4] % MOD) % MOD;
    sum = (sum + (((power[zone2] - 1) * (power[zone4] - 1) % MOD) * power[zone1] % MOD) * power[zone3] % MOD) % MOD;
    sum = (sum + MOD - (((power[zone1] - 1) * (power[zone3] - 1) % MOD) * (power[zone2] - 1) % MOD) * (power[zone4] - 1) % MOD) % MOD;
  }

  cout << sum <<endl;
  return 0;
}

