typedef long long ll;
const ll MOD=998244353;
struct mint{
  ll x;
  mint(ll x=0):x(x%MOD){}
  mint& operator+=(const mint a){
    if((x+=a.x)>=MOD) x-=MOD;
    return *this;
  }
  mint& operator-=(const mint a){
    if((x += MOD-a.x)>=MOD) x-=MOD;
    return *this;
  }
  mint& operator*=(const mint a){
    (x*=a.x)%=MOD;
    return *this;
  }
  mint operator+(const mint a) const{
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const{
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const{
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const{
    if(!t) return 1;
    mint a = pow(t>>1);
    a*=a;
    if(t&1) a*=*this;
    return a;
  }

  //for prime mod
  mint inv() const{
    return pow(MOD-2);
  }
  mint& operator/=(const mint a){
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const{
    mint res(*this);
    return res/=a;
  }
};

const int NMAX=200010;
template <class X>
class BIT{
  X bit[NMAX];
  int n;
public:
  BIT(int N);
  X sum(int i);
  void add(int i,X x);
};
template <class X>
BIT<X>::BIT(int N){
  n=N;
  for(int i=0;i<N;i++){
    bit[i]=0;
  }
}
template <class X>
X BIT<X>::sum(int i){//iまでの和=bit[0]+...+bit[i]
  X s=0;
  while(i>0){
    s+=bit[i];
    i-=i&(-i);//最後の1bitを引く(ex.0110なら0010を引く)
  }
  return s;
}
template <class X>
void BIT<X>::add(int i,X x){//bit[i]+=x
  while(i<=n){
    bit[i]+=x;
    i+=i&(-i);//最後の1bitを足す
  }
}
