const ll mod = 998244353;

void bitadd(ll a,ll w, vector<ll>& bit){

    ll x = a;
    if (a == 0){
        exit(1);
    }
    while (x <= (bit.size()-1)){
        bit[x] += w;
        x += (x & (-x));
    }

    return;
}

ll bitsum(ll a,vector<ll>& bit){

    ll ret = 0;
    ll x = a;
    if (a == 0){
        exit(1);
    }
    while (x > 0){
        ret += bit[x];
        x -= (x & (-x));
    }

    return ret;
}

int main(){

