        ll psy = i_to_psy[ind];

        bitadd(psy,-1,YetBIT);

        ll L = N - loop - 1;
        ll R = loop;
        ll ul = bitsum(psy,YetBIT);
        ll ur = bitsum(psy,AftBIT);

        ll U = ul+ur;
        ll D = N-U-1;

        ll dl = L - ul;
        ll dr = R - ur;

        ll now = ((powlis[ul]+powlis[ur]+powlis[dl]+powlis[dr]-4) - (powlis[U]+powlis[D]+powlis[L]+powlis[R]-4));
        now %= mod;
        ans += now;
        ans %= mod;

        bitadd(psy,1,AftBIT);
    }

