const int MOD = 998244353;

struct FenwickTree {
    int n;
    std::vector<int> v;

    FenwickTree(int n) : v(n + 1) {
        this->n = n;
    }

    void add(int a, int x) {
        for (int i = a; i <= n; i += i & -i) v[i] += x;
    }

    int sum(int a) {
        int res = 0;
        for (int i = a; i > 0; i -= i & -i) res += v[i];
        return res;
    }
};

int main() {
    int N;
    std::cin >> N;

    std::vector<std::pair<int, int>> v(N);
    for (int i = 0; i < N; i++) {
        int x, y;
        std::cin >> x >> y;
        v[i] = std::make_pair(x, y);
    }

    std::sort(v.begin(), v.end(), [](auto p1, auto p2) {
        return p1.second < p2.second;
    });
    for (int i = 0; i < N; i++)
        v[i].second = i;

    std::sort(v.begin(), v.end());
    for (int i = 0; i < N; i++)
        v[i].first = i;

    std::vector<int> p(N + 1);
    p[0] = 1;
    for (int i = 0; i < N; i++) p[i + 1] = p[i] * 2 % MOD;

    FenwickTree ft(N);

    int ans = 0;
    for (int i = 0; i < N; i++) {
        int ld = ft.sum(v[i].second);
        int lu = i - ld;
        int rd = v[i].second - ld;
        int ru = N - ld - lu - rd - 1;

        ans = (ans + (p[N] - 1)) % MOD;

        ans = (ans - (p[ld + lu] - 1) + MOD) % MOD;
        ans = (ans - (p[lu + ru] - 1) + MOD) % MOD;
        ans = (ans - (p[ru + rd] - 1) + MOD) % MOD;
        ans = (ans - (p[ld + rd] - 1) + MOD) % MOD;

        ans = (ans + (p[ld] - 1)) % MOD;
        ans = (ans + (p[lu] - 1)) % MOD;
        ans = (ans + (p[rd] - 1)) % MOD;
        ans = (ans + (p[ru] - 1)) % MOD;

        ft.add(v[i].second + 1, 1);
    }
    std::cout << ans << "\n";
}

