      x[i]++;
      y[i] = find(ys.begin(), ys.end(), y[i]) - ys.begin();
      y[i]++;
   }

   BIT<int> bitL, bitR;
   bitL.init(N + 1, 0);
   bitR.init(N + 1, 0);
   for (int i = 0; i < N; i++) {
      bitR.add(y[i], 1);
   }
