struct tree_node{
    int l,r;
    int num;
};
tree_node T[maxn*3];
void maketree(int p,int l,int r){
    T[p].l=l;T[p].r=r;
    T[p].num=0;
    if(l==r){return;}
    int m=(l+r)/2;
    maketree(p*2,l,m);
    maketree(p*2+1,m+1,r);
}
int insert(int p,int x){
    if(T[p].l==T[p].r /*&& T[p].l==x*/){
        T[p].num+=1;
        return 0;
    }
    int m=(T[p].l+T[p].r)/2;
    T[p].num+=1;
    if(x<=m){
        return insert(p*2,x);
    }else{
        return insert(p*2+1,x)+T[p*2].num;
    }
}

const int MOD=998244353;
int p2[maxn];
void initp2(){
    p2[0]=1;
    for(int i=1;i<n;++i)
        p2[i]=(p2[i-1]*2)%MOD;
}
int p(int i){
    return p2[i];
}
int mul(int a,int b,int c,int d){
    ll r=a;
    r=(r*b)%MOD;
    r=(r*c)%MOD;
    r=(r*d)%MOD;
    return r;
}
int calc(int a,int b,int c,int d){
    /*
    对于某个点P,计算它被覆盖到的次数 in {所有可能性}
    若P被选 则一定被覆盖 情况数=2^(n-1)
    若P不被选 情况数=|BD都至少有1点|+|AC都至少有1点|-|BDAC都至少有1点|;
        |至少有1点|=总情况数-"所以点都不选"这唯一的情况
    |BD都至少有1点|=(2^B - 1)*(2^D -1)*(2^A)*(2*C);
    AC类似
    */
    int ret;
    ret=p(n-1);
    ret=(ret+mul(p(b),p(d),p(a)-1,p(c)-1))%MOD;
    ret=(ret+mul(p(a),p(c),p(b)-1,p(d)-1))%MOD;
    ret=(ret-mul(p(a)-1,p(b)-1,p(c)-1,p(d)-1)+MOD)%MOD;
    return ret;
}

bool cmp_x(point a,point b){return a.x<b.x;}
bool cmp_y(point a,point b){return a.y<b.y;}
int solve(){
    sort(D+1,D+n+1,cmp_x);
    for(int i=1;i<=n;++i){
        D[i].ix=i;
    }
    sort(D+1,D+n+1,cmp_y);
    int a,b,c=0,d=0;
    initp2();
    maketree(1,1,n);
    int sum=0;
    for(int i=1;i<=n;++i){
        c=insert(1,D[i].ix);
        d=i-1-c;// i-1 equals c+d
        b=D[i].ix-1-c;// ix-1 equals b+c
        a=n-D[i].ix-d;// n-ix equals a+d
        sum=(sum+calc(a,b,c,d))%MOD;
    }
    return sum;
}
int main(){
    init();
    cout<<solve()<<endl;
    return 0;
}

#include<functional>
#include<iostream>
#include<memory>
template<typename S, typename E = S> class SegmentTreeDLP {
 public:
  using Size = long long;
  using FS = std::function<S(S, S)>;
  using FA = std::function<S(S, E)>;
  using FE = std::function<E(E, E)>;
  SegmentTreeDLP(Size L, Size R, FS fs, FA fa, FE fe, const S& es, const E& ee) : L(L), R(R), fs(fs), fa(fa), fe(fe), es(es), ee(ee), root(std::make_unique<Node>(es,ee)) {}
  void set(Size a, const S& x) {set(a, x, root, L, R);}
  void update(Size a, Size b, const E& x) {update(a, b, x, root, L, R);}
  S query(Size a, Size b) {return query(a, b, root, L, R);}
  Size lower_bound(Size a, Size b, const std::function<bool(S)>& check) {return lower_bound(a, b, check, root, L, R);}
  void debug() {std::cout << "segtree: size " << L << " to " << R << std::endl; traverse(root, 0, L, R);}
  void traverse(const auto& node, Size d, Size l, Size r) {
    if(not node->lchild || not node->rchild) return;
    propagate(node);
    auto m = (l + r) / 2;
    if(l+1!=r) traverse(node->rchild, d + 1, m, r);
    for(auto i = 0; i < d; ++i) std::cout << "    ";
    std::cout << "[" << l << "," << r << ") ";
    std::cout << node->val << std::endl;
    if(l+1!=r) traverse(node->lchild, d + 1, l, m);
  }
 private:
  struct Node {
    S val;
    E laz;
    Node *lchild, *rchild;
    Node(const S& val, const E& laz) : val(val), laz(laz), lchild(nullptr), rchild(nullptr) {}
  };
  inline S reflect(const auto& n) {return n->laz==ee ? n->val : fa(n->val, n->laz);}
  inline void propagate(const auto& n) {
    if(n->lchild == nullptr) n->lchild = new Node(es, ee);
    if(n->rchild == nullptr) n->rchild = new Node(es, ee);
    if(n->laz == ee) return;
    n->lchild->laz = fe(n->lchild->laz, n->laz);
    n->rchild->laz = fe(n->rchild->laz, n->laz);
    n->val = reflect(n);
    n->laz = ee;
  }
  inline void recalc(const auto& n) {n->val = fs(reflect(n->lchild), reflect(n->rchild));}
  void set(Size a, const S& x, const auto &n, Size l, Size r) {
    propagate(n);
    if(l+1 == r) {
      n->val = x;
      return;
    }
    auto m = (l + r) / 2;
    if(a < m) set(a, x, n->lchild, l, m);
    else      set(a, x, n->rchild, m, r);
    recalc(n);
  }
  void update(Size a, Size b, const E& x, const auto &n, Size l, Size r) {
    propagate(n);
    if(b <= l || r <= a) return;
    if(a <= l && r <= b) {
      n->laz = fe(n->laz, x);
      propagate(n);
      return;
    }
    auto m = (l + r) / 2;
    update(a, b, x, n->lchild, l, m);
    update(a, b, x, n->rchild, m, r);
    recalc(n);
  }
  S query(Size a, Size b, const auto &n, Size l, Size r) {
    propagate(n);
    if(b <= l || r <= a) return es;
    if(a <= l && r <= b) return reflect(n);
    auto m = (l + r) / 2;
    auto vl = query(a, b, n->lchild, l, m);
    auto vr = query(a, b, n->rchild, m, r);
    return fs(vl, vr);
  }
  Size lower_bound(Size a, Size b, const auto& check, const auto& node, Size l, Size r) {
    propagate(node);
    if(b <= l || r <= a) return R;
    if(!check(reflect(node))) return R;
    if(l + 1 == r) return l;
    auto m = (l + r) / 2;
    auto i = lower_bound(a, b, check, node->lchild, l, m);
    if(i != R) return i;
    return lower_bound(a, b, check, node->rchild, m, r);
  }
  Size L, R;
  std::unique_ptr<Node> root;
  FS fs;
  FA fa;
  FE fe;
  S es;
  E ee;
};

#include<bits/stdc++.h>
using namespace std;

using LL = long long;

const LL M = 998244353;
const LL INF = 1e9+1;

struct S {
  LL v, size;
  S(LL v, LL size = 1) : v(v), size(size) {}
  bool operator==(const S& o) const {return v != o.v;}
  friend ostream& operator<<(ostream& os, const S& s) {return os << s.v;}
};
using E = LL;
const auto fs = [](const S& l, const S& r) {return S{l.v + r.v, l.size + r.size};};
const auto fa = [](const S& l, const E& r) {return S{l.v + r * l.size, l.size};};
const auto fe = [](const E& l, const E& r) {return l + r;};
const auto es = S(0, 1);
const auto ee = E(0);

LL power(LL m, LL n) {
  if(!n) return 1;
  return (n & 1) ? (power(m, n - 1) * m % M) : power(m * m % M, n >> 1);
}

int main() {
  struct Point {LL x, y, ul, ur, ll, lr;};
  int N;
  cin >> N;
  vector<Point> P(N);
  for(auto& i: P) cin >> i.x >> i.y;

  sort(begin(P), end(P), [](auto& l, auto& r){
    if(l.x != r.x) return l.x < r.x;
    return l.y < r.y;
  });
  SegmentTreeDLP<S,E> rsq(-INF, INF, fs,fa,fe,es,ee);
  for(auto& p: P) {
    p.ll = rsq.query(-INF,  p.y+1).v;
    p.ul = rsq.query(p.y+1, INF).v;
    rsq.set(p.y, 1);
  }

  sort(begin(P), end(P), [](auto& l, auto& r){
    if(l.x != r.x) return l.x > r.x;
    return l.y > r.y;
  });
  rsq = SegmentTreeDLP<S,E>(-INF, INF, fs,fa,fe,es,ee);
  for(auto& p: P) {
    p.ur = rsq.query(p.y,  INF).v;
    p.lr = rsq.query(-INF, p.y).v;
    rsq.set(p.y, 1);
  }

  LL ans = 0;
  for(auto& p: P) {
    (ans += power(2,N-1)) %= M;
    auto urll = (power(2,p.ur)-1) * (power(2,p.ll)-1) % M;
    auto ullr = (power(2,p.ul)-1) * (power(2,p.lr)-1) % M;
    (ans += urll * power(2,N-1-p.ur-p.ll) % M) %= M;
    (ans += ullr * power(2,N-1-p.ul-p.lr) % M) %= M;
    (ans += M - (urll*ullr%M) * power(2,N-1-p.ur-p.ll-p.ul-p.lr)%M) %= M;
  }
  cout << ans << endl;
}

