struct mint
{
	lint n;
	mint() :n(0) {}
	mint(lint a) { n = (a < 0) ? (mod - ((-a) % mod)) : (a % mod); }
	mint& operator+=(mint a) { (n += a.n) %= mod;			return *this; }
	mint& operator-=(mint a) { ((n += mod) -= a.n) %= mod;	return *this; }
	mint& operator*=(mint a) { (n *= a.n) %= mod;			return *this; }
	mint& operator%=(mint a) { n %= a.n;					return *this; }
	mint& operator++() { (n += 1) %= mod;				return *this; }
	mint& operator--() { (n += (mod - 1)) %= mod;		return *this; }
};

mint operator+(mint a, mint b) { return a += b; }
mint operator-(mint a, mint b) { return a -= b; }
mint operator*(mint a, mint b) { return a *= b; }

vector<mint> invtbl, finvtbl, facttbl;

mint factMod(lint n) {
	if (n == 0) { return 1; }
	mint ans = 1;
	while (n > 1) { ans *= n; n--; }
	return ans;
}
mint powMod(mint x, lint y) {
	if (x.n <= 1) { return x; }
	mint tmp = y > 1 ? powMod(x, y / 2) : 1;
	return tmp * tmp * ((y % 2 == 0) ? 1 : (x));
}
mint modinv(mint n) { return powMod(n, mod - 2); }
void preCalcInv(lint up) {
	invtbl.resize(up + 1);	invtbl[1] = 1;
	repb(a, 2, up)
		invtbl[a] = invtbl[a] = mod - invtbl[mod % a] * (mod / a);
}

mint& operator/=(mint& a, mint b) { a *= (b.n < invtbl.size()) ? invtbl[b.n] : modinv(b); return a; }
mint operator/(mint a, mint b) { return a /= b; }

template<class It, class ...T>
void sort2(It begin, It end, T ...p)
{
	using val_t = remove_reference_t<decltype(*begin)>;

	sort(begin, end, [p...](const val_t& a, const val_t& b) {
		bool neq[] = { (a.*p != b.*p)... };
		bool sg[] = { (a.*p < b.*p)... };

		rep(i, sizeof...(p))
			if (neq[i])
				return sg[i];
		return false;
	});
}

template<class T>
struct BIT {
	lint n;
	T neutral;
	vect<T> v;

	BIT(lint _n, T _neutral = 0) : n(_n), neutral(_neutral), v(n, neutral) {}

	using FT = T(T, T);
	FT* un, * dun;

	void add(lint i, lint val) {
		i++;
		while (i <= n) {
			v[i - 1] += val;
			i += i & -i;
		}
	}

	void update(lint i, T val) {
		add(i, dun(val, query(i, i + 1)));
	}

	T query_impl(lint r) {
		T ans = neutral;
		while (r > 0) {
			ans = un(ans, v[r - 1]);
			r -= r & -r;
		}
		return ans;
	}

	T query(lint l, lint r) {
		return dun(query_impl(r), query_impl(l));
	}

};

template<class T>
struct BITs : public BIT<T> {
	BITs(lint n) : BIT<T>(n, T(0)) {
		this->un = [](T a, T b) { return a + b; };
		this->dun = [](T a, T b) { return a - b; };
	}
};


