const int MOD = 998244353;

int n, bitL[200005], bitR[200005];
long long power[200005];
pair<int, int> pts[200005];

int query(int i, int *bit) {
    int ret = 0;
    for (; i>0; i-=i&-i)
        ret += bit[i];
    return ret;
}

void update(int i, int val, int *bit) {
    for (; i<=n; i+=i&-i)
        bit[i] += val;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    cin >> n;
    for (int i=0; i<n; i++)
        cin >> pts[i].first >> pts[i].second;

    power[0] = 1;
    for (int i=1; i<=n; i++)
        power[i] = power[i-1] * 2 % MOD;

    sort(pts, pts + n, [] (const pair<int, int> &a, const pair<int, int> &b) {
        return a.second < b.second;
    });
    for (int i=0; i<n; i++) {
        pts[i].second = i + 1;
        update(i + 1, 1, bitR);
    }
    sort(pts, pts + n);

    long long ret = 0;
    for (int i=0; i<n; i++) {
        update(pts[i].second, -1, bitR);
        int bottomL = query(pts[i].second, bitL), bottomR = query(pts[i].second, bitR);
        ret += ((power[n] - power[i] - power[n - i - 1] - power[bottomL + bottomR] - power[n - bottomL - bottomR - 1]
            + power[bottomL] + power[bottomR] + power[i - bottomL] + power[n - i - bottomR - 1] - 1) % MOD + MOD) % MOD;
        if (ret >= MOD)
            ret -= MOD;
        update(pts[i].second, 1, bitL);
    }
    cout << ret << "\n";

    return 0;
}

