struct BIT {
	int N;
	using TYPE = int;
	std::vector<TYPE> bit;
	BIT() : N(0) {}
	BIT(int n) : N(n), bit(N + 1, 0) {}
	BIT(int n, TYPE init) : N(n), bit(N + 1, init) {}

	// bit[i] += w;
	void add(int i, TYPE w) {
		for (int x = ++i; x <= N; x += x & -x) bit[x] += w;
	}
	// return sum [0, i);
	TYPE sum(int i) {
		TYPE res = 0;
		for (int x = i; x > 0; x -= x & -x) res += bit[x];
		return res;
	}
	// return sum [i, j);
	TYPE sum(int i, int j) {
		return sum(j) - sum(i);
	}
	const TYPE& operator[](const int& i) const {
		return bit[i];
	}
};

int p2[200005];

signed main() {
	INIT;

	VAR(int, n);
	VEC_ROW(int, n, x, y);

	p2[0] = 1;
	REP(i, 200004) p2[i + 1] = p2[i] * 2 % MOD;

	int ans = n * (p2[n] - 1);

	{
		std::map<int, int> map;
		REP(i, n) map[x[i]];
		int t = 0;
		for (auto& p : map) p.second = t++;
		REP(i, n) x[i] = map[x[i]];
	}
	V<int> inv(n);
	{
		std::map<int, int> map;
		REP(i, n) map[y[i]];
		int t = 0;
		for (auto& p : map) p.second = t++;
		REP(i, n) {
			y[i] = map[y[i]];
			inv[y[i]] = i;
		}
	}

	REP(i, n) {
		const int L = x[i];
		const int R = n - 1 - L;
		const int D = y[i];
		const int U = n - 1 - D;

		(ans -= p2[L]) %= MOD;
		(ans -= p2[R]) %= MOD;
		(ans -= p2[D]) %= MOD;
		(ans -= p2[U]) %= MOD;
	}

	{
		BIT bit(n);
		REP(i, n) {
			int id = inv[i];
			(ans += p2[bit.sum(x[id])]) %= MOD;
			(ans += p2[bit.sum(x[id] + 1, n)]) %= MOD;
			bit.add(x[id], 1);
		}
	}
	{
		BIT bit(n);
		RREP(i, n) {
			int id = inv[i];
			(ans += p2[bit.sum(x[id])]) %= MOD;
			(ans += p2[bit.sum(x[id] + 1, n)]) %= MOD;
			bit.add(x[id], 1);
		}
	}
	if (ans < 0) ans += MOD;
	OUT(ans)BR;

	return 0;
}

