struct custom_hash {
    static uint64_t splitmix64(uint64_t x) {
        // http://xorshift.di.unimi.it/splitmix64.c
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    size_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = std::chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(x + FIXED_RANDOM);
    }
};


using namespace std;

class FEnclosedPoints {
    const int MOD = 998244353;

    void compress(vector<int> &A) {
        vector<int> B = A;
        sort(B.begin(), B.end());
        B.resize(unique(B.begin(), B.end()) - B.begin());
        for (int &x: A) {
            x = upper_bound(B.begin(), B.end(), x) - B.begin();
        }
    }

    int nx, ny;
    vector<unordered_map<int, int, custom_hash>> bit;

    void update(int x, int y) {
        for (; x < nx; x += x & (-x)) {
            for (int y2 = y; y2 < ny; y2 += y2 & (-y2)) {
                bit[x][y2]++;
            }
        }
    }

    int query(int x, int y) {
        int res = 0;
        for (; x; x -= x & (-x)) {
            for (int y2 = y; y2; y2 -= y2 & (-y2)) {
                if (bit[x].count(y2)) {
                    res += bit[x][y2];
                }
            }
        }
        return res;
    }

    int query(int x1, int y1, int x2, int y2) {
        return query(x2, y2) - query(x1 - 1, y2) - query(x2, y1 - 1) + query(x1 - 1, y1 - 1);
    }

public:
    void solve(std::istream &in, std::ostream &out) {
        int n;
        in >> n;
        vector<int> X(n), Y(n), P2(n + 1);
        P2[0] = 1;
        for (int i: range(n)) {
            in >> X[i] >> Y[i];
            P2[i + 1] = 2 * P2[i] % MOD;
        }
        compress(X);
        compress(Y);
        nx = *max_element(X.begin(), X.end()) + 1;
        ny = *max_element(Y.begin(), Y.end()) + 1;
        int mx = nx - 1, my = ny - 1;
        bit.resize(nx);
        for (int i: range(n)) {
            update(X[i], Y[i]);
        }
        long long res = 0;
        for (int i: range(n)) {
            res += P2[query(1, 1, mx, my)];
            res -= P2[query(1, 1, X[i] - 1, my)];
            res -= P2[query(X[i] + 1, 1, mx, my)];
            res -= P2[query(1, 1, mx, Y[i] - 1)];
            res -= P2[query(1, Y[i] + 1, mx, my)];
            res += P2[query(1, 1, X[i] - 1, Y[i] - 1)];
            res += P2[query(X[i] + 1, 1, mx, Y[i] - 1)];
            res += P2[query(1, Y[i] + 1, X[i] - 1, my)];
            res += P2[query(X[i] + 1, Y[i] + 1, mx, my)];
            res--;
        }
        res = (res % MOD + MOD) % MOD;
        out << res << "\n";
    }

    void setup() {}
};


int main() {
    std::ios_base::sync_with_stdio(false);
    FEnclosedPoints solver;
    solver.setup();
    std::istream &in(std::cin);
    std::ostream &out(std::cout);
    in.tie(nullptr);
    out << std::fixed;
    out.precision(20);
    solver.solve(in, out);
    return 0;
}

