using namespace std;

/* constant */

const int MAX_N = 200000;
const int MOD = 998244353;

/* typedef */

typedef long long ll;
typedef pair<int,int> pii;

template <typename T, const int MAX_N>
struct BIT {
  int n;
  T bits[MAX_N + 1];
  BIT() {}

  void init(int _n) {
    n = _n;
    memset(bits, 0, sizeof(bits));
  }

  T sum(int x) {
    T s = 0;
    while (x > 0) {
      s += bits[x];
      x -= (x & -x);
    }
    return s;
  }

  void add(int x, T v) {
    while (x <= n) {
      bits[x] += v;
      x += (x & -x);
    }
  }
};

/* global variables */

int xs[MAX_N], ys[MAX_N], sxs[MAX_N], sys[MAX_N];
pii ps[MAX_N];
int e2s[MAX_N + 1], qs[MAX_N][4], bs[4];
BIT<int,MAX_N> bit;

/* subroutines */

/* main */

int main() {
  int n;
  scanf("%d", &n);

  for (int i = 0; i < n; i++) {
    scanf("%d%d", xs + i, ys + i);
    sxs[i] = xs[i], sys[i] = ys[i];
  }
  sort(sxs, sxs + n);
  sort(sys, sys + n);

  for (int i = 0; i < n; i++) {
    int px = lower_bound(sxs, sxs + n, xs[i]) - sxs;
    int py = lower_bound(sys, sys + n, ys[i]) - sys;
    ps[i] = pii(px, py);
  }
  sort(ps, ps + n);

  e2s[0] = 1;
  for (int i = 0; i < n; i++) e2s[i + 1] = e2s[i] * 2 % MOD;

  bit.init(n);
  for (int i = 0; i < n; i++) {
    int py = ps[i].second + 1;
    int q = bit.sum(py);
    qs[i][0] = q;
    qs[i][1] = i - q;
    bit.add(py, 1);
  }

  bit.init(n);
  for (int i = n - 1; i >= 0; i--) {
    int py = ps[i].second + 1;
    int q = bit.sum(py);
    qs[i][2] = q;
    qs[i][3] = n - 1 - i - q;
    bit.add(py, 1);
  }

  /*
  for (int i = 0; i < n; i++) {
    printf("%d(%d,%d)", i, ps[i].first, ps[i].second);
    for (int j = 0; j < 4; j++) printf(" %d", qs[i][j]);
    putchar('\n');
  }
  */

  int sum = 0;
  for (int i = 0; i < n; i++) {
    sum = (sum + e2s[n - 1]) % MOD;

    for (int bits = 0; bits < 1 << 4; bits++) {
      for (int j = 0; j < 4; j++) bs[j] = ((bits >> j) & 1);
      if ((bs[0] || bs[1]) && (bs[2] || bs[3]) &&
	  (bs[0] || bs[2]) && (bs[1] || bs[3])) {
	int c = 1;
	for (int j = 0; j < 4; j++)
	  if (bs[j])
	    c = (ll)c * ((e2s[qs[i][j]] + MOD - 1) % MOD) % MOD;
	sum = (sum + c) % MOD;
      }
    }
  }

  printf("%d\n", sum);
  return 0;
}

