lint powmod(lint x, lint n){
  lint ret = 1;
  while(n > 0){
    if(n&1) ret *= x, ret %= mod, n -= 1;
    else x *= x, x %= mod, n >>= 1;
  }
  return ret;
}

template<class T> struct SegTree{
  int n;
  vector<T> node;

  SegTree(int n_){
    n = 1;
    while(n < n_) n *= 2;
    node.resize(n*2-1, 0);
  }

  void update(int i, T val){
    i += n - 1;
    node[i] += val;
    while(i > 0){
        i = (i-1) / 2;
        node[i] = node[i*2+1] + node[i*2+2];
    }
  }

  T getsum(int a, int b, int i, int l, int r){
    if(r<=a || b<=l) return 0;
    if(a<=l && r<=b) return node[i];
    T vl = getsum(a, b, i*2+1, l, (l+r)/2);
    T vr = getsum(a, b, i*2+2, (l+r)/2, r);
    return vl + vr;
  }
};

