template<typename Monoid>
class SegTree {

//半開区間!!!!!!!!!!!!!!!
public:
    int p = 2;
    vector<Monoid> node;
    using Func = function<Monoid(Monoid,Monoid)>;
    Func pick; Monoid init;//操作と単位元

    SegTree(vector<Monoid> A, Func f, Monoid m) {
        pick = f; init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    //1点更新
    void update(int i, Monoid v) {
        for (node[(i+=p)-1] = v; i >>= 1;) {
            node[i-1] = pick(node[i*2-1], node[i*2]);
        }
    }

    //1点加算
    void add(int i, Monoid v) {
        update(i, this[i] + v);
    }

    int getval(int start,int end,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = p;
        if (r <= start || end <= l) {return init;}
        if (start <= l && r <= end) {return node[k];}
        int L,R;
        L = getval(start,end,k*2+1,l,(l+r)/2);
        R = getval(start,end,k*2+2,(l+r)/2,r);
        return {pick(L,R)};
    }

    inline Monoid operator [] (int i) {
        return node[i+p-1];
    }
};

bool solve() {
    mod = 998244353;
    int n; cin >> n;
    vi x(n),y(n);
    REP (i,n) cin >> x[i] >> y[i];

    vi vec(n);
    iota(all(vec),0);

    sort(all(vec),[&](int i, int j){
        return x[i] < x[j];
    });
    REP (i,n) x[vec[i]] = i;

    sort(all(vec),[&](int i, int j){
        return y[i] < y[j];
    });
    REP (i,n) y[vec[i]] = i;

    SegTree<int> seg1(vi(n,0), [](int a, int b) {return a + b;},0);

    sort(all(vec), [&] (int i, int j) {
        return x[i] < x[j];
    });

    vector<int> cnt1(n), cnt2(n);
    REP (i,n) {
        int j = vec[i]; //i番目に大きいxのindex
        cnt1[j] = i - seg1.getval(0, y[j]);
        cnt2[j] = i - cnt1[j];
        seg1.update(y[j],1);
    }

    SegTree<int> seg2(vi(n,0), [](int a, int b) {return a + b;},0);

    sort(all(vec), [&](int i, int j){
        return (y[i] < y[j]);
    });

    vector<int> cnt3(n), cnt4(n);
    REP (i,n) {
        int j = vec[i];
        cnt3[j] = i - seg2.getval(0,x[j]);
        cnt4[j] = i - cnt3[j];
        seg2.update(x[j],1);
    }

    int ans = 0;
    REP (i,n) {
        // 0 1
        // 2 3
        int cnt[4];
        cnt[0] = cnt1[i];
        cnt[2] = cnt2[i];
        cnt[3] = cnt3[i];
        cnt[1] = n - 1 - (cnt[0]+cnt[2]+cnt[3]);
        ans += POW(2,n-1);
        ans += (POW(2,cnt[0])-1) * (POW(2,cnt[3])-1) % mod * POW(2,cnt[1]) % mod * POW(2,cnt[2]) % mod;
        ans += (POW(2,cnt[1])-1) * (POW(2,cnt[2])-1) % mod * POW(2,cnt[0]) % mod * POW(2,cnt[3]) % mod;
        ans += mod;
        ans -= (POW(2,cnt[1])-1) * (POW(2,cnt[2])-1) % mod * (POW(2,cnt[0])-1) % mod * (POW(2,cnt[3])-1) % mod;
        ans %= mod;
    }
    cout << ans << endl;
}

