    sort(compressed.begin(), compressed.end());
    for (int ctr1 = 0; ctr1 < n; ++ctr1)
        rev.emplace(compressed[ctr1], ctr1);

    ll rez = subs(fpow(2, n), 1) * n % MOD;
    rez = (rez + count(points, rev, n)) % MOD;
    reverse(points.begin(), points.end());
    rez = (rez + count(points, rev, n)) % MOD;

