struct FenwickTree {
  static const int SIZE = 1 << 17;
  int n, tree[SIZE + 1];

 public:
  FenwickTree(int n_) {
    n = n_;
    for (int i = 0; i < n + 1; i++) tree[i] = 0;
  }
  void add(int i, int value) {
    for (; i < n; i |= i + 1) tree[i] += value;
  }
