bool base_y(const Point &p1, const Point &p2) { return p1.y == p2.y ? p1.x < p2.x : p1.y < p2.y; }

struct StaticKdTree {
	using It = vector<Point>::iterator;
	int n;
	vector<Point> ps;
	vector<Point> tree;
	StaticKdTree(const vector<Point> &ps) :n(ps.size()), ps(ps), tree(n) {
		build(0, n, true);
	}
	//平均 O(nlogn)
	void build(int l, int r, bool is_x_base) {
		if (l >= r)return;
		int m = (l + r) / 2;
		It first = ps.begin() + l,
			nth = ps.begin() + m,
			last = ps.begin() + r;
		//平均 O(r-l)
		if (is_x_base)
			nth_element(first, nth, last);
		else
			nth_element(first, nth, last, base_y);
		tree[m] = *nth;
		build(l, m, !is_x_base);
		build(m + 1, r, !is_x_base);
	}
	bool inrange(const Point &p, int sx, int sy, int tx, int ty) {
		return sx <= p.x&&p.x <= tx && sy <= p.y&&p.y <= ty;
	}
	int query(int sx, int sy, int tx, int ty) {
		return query(0, n, true, sx, sy, tx, ty);
	}
	int query(int l, int r, bool is_x_base, int sx, int sy, int tx, int ty) {
		//dump(l, r, is_x_base, sx, sy, tx, ty);
		if (l >= r)return 0;
		int m = (l + r) / 2;
		Point p = tree[m];
		//dump(p);
		int ret = 0;
		if (is_x_base) {
			if (tx < p.x) {
				ret += query(l, m, !is_x_base, sx, sy, tx, ty);
			}
			else if (p.x < sx) {
				ret += query(m + 1, r, !is_x_base, sx, sy, tx, ty);
			}
			else {
				if (inrange(p, sx, sy, tx, ty))ret++;
				ret += query(l, m, !is_x_base, sx, sy, tx, ty);
				ret += query(m + 1, r, !is_x_base, sx, sy, tx, ty);
			}
		}
		else {
			if (ty < p.y) {
				ret += query(l, m, !is_x_base, sx, sy, tx, ty);
			}
			else if (p.y < sy) {
				ret += query(m + 1, r, !is_x_base, sx, sy, tx, ty);
			}
			else {
				if (inrange(p, sx, sy, tx, ty))ret++;
				ret += query(l, m, !is_x_base, sx, sy, tx, ty);
				ret += query(m + 1, r, !is_x_base, sx, sy, tx, ty);
			}
		}
		return ret;
	}
};

template<int MOD>
struct ModInt {
	static const int kMod = MOD;
	unsigned x;
	ModInt() :x(0) {}
	ModInt(signed x_) { x_ %= MOD; if (x_ < 0)x_ += MOD; x = x_; }
	ModInt(signed long long x_) { x_ %= MOD; if (x_ < 0)x_ += MOD; x = x_; }
	int get()const { return (int)x; }
	ModInt &operator+=(ModInt m) { if ((x += m.x) >= MOD)x -= MOD; return *this; }
	ModInt &operator-=(ModInt m) { if ((x += MOD - m.x) >= MOD)x -= MOD; return *this; }
	ModInt &operator*=(ModInt m) { x = (unsigned long long)x*m.x%MOD; return *this; }
	ModInt &operator/=(ModInt m) { return *this *= m.inverse(); }
	ModInt operator+(ModInt m)const { return ModInt(*this) += m; }
	ModInt operator-(ModInt m)const { return ModInt(*this) -= m; }
	ModInt operator*(ModInt m)const { return ModInt(*this) *= m; }
	ModInt operator/(ModInt m)const { return ModInt(*this) /= m; }
	ModInt operator-()const { return ModInt(MOD - (signed)x); }
	bool operator==(ModInt m)const { return x == m.x; }
	bool operator!=(ModInt m)const { return x != m.x; }
	ModInt inverse()const {
		signed a = x, b = MOD, u = 1, v = 0;
		while (b) {
			signed t = a / b;
			a -= t * b; swap(a, b);
			u -= t * v; swap(u, v);
		}
		if (u < 0)u += MOD;
		return ModInt(u);
	}
};
template<int MOD>
ostream &operator<<(ostream &os, const ModInt<MOD> &m) { return os << m.x; }
template<int MOD>
