	rep(i,1,n)x[i] = {a[i].x,i};
	sort(x+1,x+n+1,[](dat a,dat b){return a.val<b.val;});
	rep(i,1,n)a[x[i].id].x = i;
	rep(i,1,n)x[i] = {a[i].y,i};
	sort(x+1,x+n+1,[](dat a,dat b){return a.val<b.val;});
	rep(i,1,n)a[x[i].id].y = i;
