	calc(ld);
	rep(i,1,n)a[i].y=n+1-a[i].y;
	calc(lu);
	rep(i,1,n)a[i].x=n+1-a[i].x;
	calc(ru);
	rep(i,1,n)a[i].y=n+1-a[i].y;
	calc(rd);
	//rep(i,1,n)cout<<ld[i]<<" "<<lu[i]<<" "<<rd[i]<<" "<<ru[i]<<endl;

	LL ans = pw2[n-1] * n % P;
	rep(i,1,n){
		LL tmp = (pw(ld[i])-1) * (pw(ru[i])-1) % P * pw(lu[i]) % P * pw(rd[i]) % P;
		tmp += pw(ld[i]) * pw(ru[i]) % P * (pw(lu[i])-1) % P * (pw(rd[i])-1) % P;
		tmp -= (pw(ld[i])-1) * (pw(ru[i])-1) % P * (pw(lu[i])-1) % P * (pw(rd[i])-1) % P;
		ans = (ans + tmp + P*10) % P;
		//cout<<i<<" "<<tmp<<endl;
	}
	cout<<ans<<endl;
	return 0;
}

