        return x < __.x || (x == __.x && y < __.y);
    }
} node[N];
int X[N], Y[N], Cntx[N];
int A[N], B[N], C[N], D[N];

int c[N];
void Add(int x, int k) {
    for ( ; x <= n; x += x & -x) c[x] += k;
}
int Que(int x) {
    int res = 0;
    for ( ; x > 0; x -= x & -x) res += c[x];
    return res;
}

ll Ans = 0;
ll Pow(ll x, int k) {
    ll res = x, ans = 1;
    while (k) {
        if (k & 1) ans = ans * res % Mod;
        res = res * res % Mod, k >>= 1;
    }
    return ans;
}
ll Get(int x) {
    return ((Pow(2, x) - 1) % Mod + Mod) % Mod;
}
ll Solve(int x) {
    ll tmp = 0, a, b, c, d;
    // cout << node[x].x << " " << node[x].y  << endl;
    // cout << A[x] << " " << B[x] << " " << C[x] << " " << D[x] << endl;
    a = Get(A[x]), b = Get(B[x]), c = Get(C[x]), d = Get(D[x]);
    (tmp = a * d % Mod + b * c % Mod) %= Mod;
    (tmp += a * b % Mod * d % Mod + a * c % Mod * d % Mod) %= Mod;
    (tmp += a * b % Mod * c % Mod + b * d % Mod * c % Mod) %= Mod;
    (tmp += a * b % Mod * c % Mod * d % Mod) %= Mod;
    // cout << x << " " << tmp << endl;
    (tmp *= 2) %= Mod;
    (tmp += a + b + c + d) %= Mod;
    (tmp += a * b % Mod + a * c % Mod) %= Mod;
    (tmp += b * d % Mod + c * d % Mod) %= Mod;
    // cout << x << " " << tmp << endl;
    return tmp + 1;
}

