    rep (i, 1, n) {
        node[i].x = lower_bound(X + 1, X + X[0] + 1, node[i].x) - X;
        node[i].y = lower_bound(Y + 1, Y + Y[0] + 1, node[i].y) - Y;
    }

    rep (i, 1, n) {
        A[i] = Que(node[i].y - 1);
        B[i] = i - A[i] - 1;
        Add(node[i].y, 1);
    }

    memset(c, 0, sizeof c);
    dep (i, n, 1) {
        C[i] = Que(node[i].y - 1);
        D[i] = n - i - C[i];
        Add(node[i].y, 1);
    }

    rep (i, 1, n) (Ans += Solve(i)) %= Mod;

    cout << Ans << endl;
    return 0;
}

