	pair<int, int> ypoint[n];
	for(int i = 0; i < n; ++i) {
		int x, y; cin >> x >> y;
		xpoint[i] = {x, y};
		ypoint[i] = {y, x};
	}
	sort(xpoint, xpoint + n);
	sort(ypoint, ypoint + n);
	for(int i = 0; i < n; ++i) {
		X[xpoint[i].first] = i;
	}
	int t[n][4] = {};
	SegmentTree<int> segsmall(n, 0, [](int a, int b){return a+b;});
	for(int i = 0; i < n; ++i) {
		int x, y;
		tie(y, x) = ypoint[i];
		x = X[x];
		t[i][2] = segsmall.get(0, x);
		t[i][3] = i - t[i][2];
		segsmall.replace(x, 1);
	}
	SegmentTree<int> seglarge(n, 0, [](int a, int b){return a + b;});
	for(int i = n - 1; i >= 0; --i) {
		int x, y;
		tie(y, x) = ypoint[i];
		x = X[x];
		t[i][1] = seglarge.get(0, x);
		t[i][0] = (n - 1 - i) - t[i][1];
		seglarge.replace(x, 1);
	}
	mint ans = 0;
	for(int i = 0; i < n; ++i) {
		for(int mask = 0; mask < (1 << 4); ++mask) {
			mint tmp = 1;
			for(int j = 0; j < 4; ++j) {
				if(mask >> j & 1) {
					mint x = 2;
					tmp *= x.pow(t[i][j]) - 1;
				}
			}
			const int _02 = 0b0101;
			const int _13 = 0b1010;
			if((mask & _02) == _02 or (mask & _13) == _13) {
				tmp *= 2;
			}
			ans += tmp;
		}
	}
	cout << ans << '\n';
	return 0;
}

