template<typename T> // T: type of cost
struct BIT {
	int n;
	vector<T> array; // ワーク用配列。BITの各要素を記録する
	BIT(int n = 0) :n(n), array(n + 1) {}
	void add(int i, T x = 1) {
		for (i++; i <= n; i += i & -i) {
			array[i] += x;
		}
	}
	T sum(int i) {
		T x = 0;
		for (i++; i; i -= i & -i) {
			x += array[i];
		}
		return x;
	}
};
