mint f2(int ax, int bx, int cx, int dx) {
	mint a = mint(2).pow(ax)-1;
	mint b = mint(2).pow(bx) - 1;
	mint c = mint(2).pow(cx) - 1;
	mint d = mint(2).pow(dx) - 1;
	mint res = 0;
	res = a + b + c + d;
	res += a * b + a * c + a * d + b * c + b * d + c * d;
	res += a * b*c*2 + a * b*d*2 + b * c*d*2 + a * c*d*2;
	res += a * d + b * c;
	res += a * b*c*d * 2;
	res += 1;
	return res;
}
