template <std::uint_fast64_t Modulus = 1000000007ULL> class Modint {
  using u64 = std::uint_fast64_t;

public:
  u64 a;

  constexpr Modint(const u64 x = 0) noexcept : a(x % Modulus) {}
  constexpr u64 &value() noexcept { return a; }
  constexpr const u64 &value() const noexcept { return a; }
  constexpr Modint operator+(const Modint rhs) const noexcept { return Modint(*this) += rhs; }
  constexpr Modint operator-(const Modint rhs) const noexcept { return Modint(*this) -= rhs; }
  constexpr Modint operator*(const Modint rhs) const noexcept { return Modint(*this) *= rhs; }
  constexpr Modint operator/(const Modint rhs) const noexcept { return Modint(*this) /= rhs; }
  constexpr Modint &operator+=(const Modint rhs) noexcept {
    a += rhs.a; if (a >= Modulus) a -= Modulus;
    return *this;
  }
  constexpr Modint &operator-=(const Modint rhs) noexcept {
    if (a < rhs.a) { a += Modulus; } a -= rhs.a;
    return *this;
  }
  constexpr Modint &operator*=(const Modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr Modint &operator/=(Modint rhs) noexcept {
    u64 exp = Modulus - 2;
    while (exp) {
      if (exp % 2) *this *= rhs;
      rhs *= rhs; exp /= 2;
    }
    return *this;
  }
  Modint pow(u64 exp) {
    Modint<Modulus> ret = 1, x = this->a;
    while(exp > 0) {
        if (exp & 1) ret *= x;
        x *= x; exp >>= 1;
    }
    return ret;
  }
};

template <std::uint_fast64_t Modulus> std::ostream& operator<<(std::ostream& os, const Modint<Modulus>& obj) { os << obj.value(); return os; }
template <std::uint_fast64_t Modulus> std::istream& operator>>(std::istream& is, Modint<Modulus>& obj) { std::uint_fast64_t a; is >> a; obj = Modint<Modulus>(a); return is; }

