            const int y = P[i].second;
            B[i] = query(y,n,n);
            D[i] = query(0,y+1,n);
            add(y,1,n);
        }
        int ans = 0;
        FOR(i,0,n) {
            const LL a = pw[A[i]];
            const LL b = pw[B[i]];
            const LL c = pw[C[i]];
            const LL d = pw[D[i]];
            /* select */
            ans += a * b % mod * c % mod * d % mod;
            ans %= mod;
            /* not select */
            ans += (a-1) * (b-1) % mod * c % mod * d % mod;
            ans %= mod;
            ans += (c-1) * (d-1) % mod * a % mod * b % mod;
            ans %= mod;
            /* IEP */
            ans -= (a-1) * (b-1) % mod * (c-1) % mod * (d-1) % mod;
            ans %= mod;
        }
        ans += mod;
        ans %= mod;
        cout << ans << endl;
    }
    return 0;
}

