int build(int l, int r) {
	int v = nn();
	if (l == r) return v;
	int m = (l + r) >> 1;
	d[v].l = build(l, m), d[v].r = build(m + 1, r);
	return v;
}
int inc(int v, int i, int l, int r) {
	if (l == r) {
		int kek = nn();
		d[kek].sum = d[v].sum + 1;
		return kek;
	}
	int root = nn();
	d[root].l = d[v].l, d[root].r = d[v].r;
	int m = (l + r) >> 1;
	if (i <= m) d[root].l = inc(d[v].l, i, l, m);
	else d[root].r = inc(d[v].r, i, m + 1, r);
	d[root].sum = d[d[root].l].sum + d[d[root].r].sum;
	return root;
}
int get(int v, int l, int r, int vl, int vr) {
	if (l > r || vl > r || vr < l) return 0;
	if (l <= vl && vr <= r) return d[v].sum;
	int vm = (vl + vr) >> 1;
	return get(d[v].l, l, r, vl, vm) + get(d[v].r, l, r, vm + 1, vr);
}
