bool cmp(pi &a, pi &b){
    return a.se < b.se;
}

void build(int nd, int s, int e){
    t[nd].v = 0;
    if(s == e)
        return;
    int md = (s + e) >> 1;
    t[nd].le = ++c;
    t[nd].ri = ++c;
    build(t[nd].le, s, md);
    build(t[nd].ri, md + 1, e);
}

void upd(int cur, int pre, int s, int e, int id){
    if(s == e){
        t[cur].v++;
        return;
    }    
    int md = (s + e) >> 1;
    if(id <= md){
        t[cur].le = ++c;
        t[cur].ri = t[pre].ri;
        upd(t[cur].le, t[pre].le, s, md, id);
    }
    else{
        t[cur].le = t[pre].le;
        t[cur].ri = ++c;
        upd(t[cur].ri, t[pre].ri, md + 1, e, id);
    }
    t[cur].v = t[t[cur].le].v + t[t[cur].ri].v;
}

int query(int cur, int pre, int s, int e, int l, int r){
    if(s > r || e < l)
        return 0;
    if(s >= l && e <= r)
        return t[cur].v - t[pre].v;
    int md = (s + e) >> 1;
    return query(t[cur].le, t[pre].le, s, md, l, r)
            + query(t[cur].ri, t[pre].ri, md + 1, e, l, r);
}

ll power(int a, int b){
    ll ans = 1;
    while(b){
        if(b&1)
            ans = (1LL*ans*a) % mod;
        a = (1LL*a*a) % mod;
        b >>= 1;
    }
    return ans;
}

