long long solve() {
  // compress
  vector<long long> lst;
  // x
  for(int i = 0; i < n; ++i) lst.push_back(v[i].fi);
  sort(lst.begin(), lst.end());
  lst.erase(unique(lst.begin(), lst.end()), lst.end());
  for(int i = 0; i < lst.size(); ++i) mp[lst[i]] = i;
  for(int i = 0; i < n; ++i) v[i].fi = mp[v[i].fi];
  // y
  lst.clear();
  for(int i = 0; i < n; ++i) lst.push_back(v[i].se);
  sort(lst.begin(), lst.end());
  lst.erase(unique(lst.begin(), lst.end()), lst.end());
  for(int i = 0; i < lst.size(); ++i) mp[lst[i]] = i;
  for(int i = 0; i < n; ++i) v[i].se = mp[v[i].se];
  // prepair
  for(int i = 0; i < 2; ++i)
    for(int j = 0; j < 2; ++j) memo[i][j].assign(n, 0);
  BIT<long long> bit(n);
  for(int i = 0; i < n; ++i) {
    memo[0][0][i] = bit.calcsum(v[i].se + 1);
    memo[0][1][i] = bit.calcsumw(v[i].se + 1, n);
    bit.add(v[i].se + 1, 1);
  }

  bit = BIT<long long>(n);
  for(int i = n - 1; i >= 0; --i) {
    memo[1][0][i] = bit.calcsum(v[i].se + 1);
    memo[1][1][i] = bit.calcsumw(v[i].se + 1, n);
    bit.add(v[i].se + 1, 1);
  }

  long long ans = 0;
  for(int i = 0; i < n; ++i) {
    // use v[i]
    (ans += modpow(2, n - 1)) %= MOD;
    // not use v[i]
    {
      long long sum = 0;
      // use memo[0][0]
      long long now = 0, bad = 0;
      now = (modpow(2, memo[0][0][i]) - 1 + MOD) % MOD;
      bad = (modpow(2, memo[1][0][i]) +
             modpow(2, memo[0][1][i]) - 1 + MOD) %
            MOD;
      (now *=
       (modpow(2, n - 1 - memo[0][0][i]) - bad + MOD) %
       MOD) %= MOD;
      sum = now;
      // not use memo[0][0]
      now = (modpow(2, memo[1][0][i]) - 1 + MOD) % MOD;
      (now *= (modpow(2, memo[0][1][i]) - 1 + MOD) % MOD) %=
          MOD;
      (now *= modpow(2, memo[1][1][i])) %= MOD;
      (sum += now) %= MOD;
      (ans += sum) %= MOD;
    }
  }
  return ans;
}

