int main(){
	ll N; cin>>N;
	BIT left(N);
	BIT right(N);
	rep1(i,N) right.add(i,1);
	vector<P> p(N);
	map<ll,ll> m;
	rep(i,N){
		ll x,y; cin>>x>>y;
		p[i]=P(x,y);
		m[y]=0;
	}
	ll sub=1;
	for(auto it=m.bg;it!=m.ed;it++) it->b=sub++;

	rep(i,N) p[i].b=m[p[i].b];
	sort(all(p));

	ll ans=N*power(2,N-1,MOD);
	ans%=MOD;
	rep(i,N){
		// p[i]を見る
		// 見る前にrightを減らす
		right.add(p[i].b,-1);

		// 見る
		/*
				A|B
		 p[i].b ---
				D|C
		*/
		ll A=left.sum(p[i].b-1),B=right.sum(p[i].b-1),C=right.sum(N)-right.sum(p[i].b),D=left.sum(N)-left.sum(p[i].b);
		ans+=((((power(2,A,MOD)-1)*(power(2,C,MOD)-1))%MOD)*power(2,B+D,MOD))%MOD;
		ans%=MOD;
		ans+=((((power(2,B,MOD)-1)*(power(2,D,MOD)-1))%MOD)*power(2,A+C,MOD))%MOD;
		ans%=MOD;
		ans-=((((((power(2,A,MOD)-1)*(power(2,B,MOD)-1))%MOD)*(power(2,C,MOD)-1))%MOD)*(power(2,D,MOD)-1))%MOD;
		if(ans<0) ans+=MOD;
      	ans%=MOD;

		// 見た後にleftを増やす
		left.add(p[i].b,1);
	}
	cout<<ans;
}

