template<class Val>
vector<Val> compress(vector<Val> &u, vector<Val> &v) {
    vector<Val> a = u;
    for (int b : v) a.push_back(b);
    sort(a.begin(), a.end());
    a.erase(unique(all(a)), a.end());
    for (int &b : u)
        b = (int)(lower_bound(all(a), b) - a.begin());
    for (int &b : v)
        b = (int)(lower_bound(all(a), b) - a.begin());
    return a;
}

template<class Val>
struct BinaryIndexedTree {
    int n;
    vector<Val> t;
    BinaryIndexedTree() {}
    BinaryIndexedTree(int _n) :n(_n + 1), t(_n + 1) {}
    void add(int k, Val val) {
        k++;
        while (k < n) {
            t[k] += val;
            k += (k&-k);
        }
    }
    void set(int k, Val val) {
        add(k, -sum(k, k + 1));
        add(k, val);
    }
    Val sum(int k) {
        Val r = 0;
        while (k > 0) {
            r += t[k];
            k -= (k&-k);
        }
        return r;
    }
    Val sum(int l, int r) {
        return sum(r) - sum(l);
    }
};

template<class S, class T>
void psort(vector<S> &u, vector<T> &v, bool isGreater = false) {
    int n = (int)u.size();
    vector<pair<S, T>> vecP(n);
    for (int i = 0; i < n; ++i) {
        vecP[i].first = u[i];
        vecP[i].second = v[i];
    }
    if (isGreater) {
        sort(vecP.rbegin(), vecP.rend());
    } else {
        sort(vecP.begin(), vecP.end());
    }
    for (int i = 0; i < n; ++i) {
        u[i] = vecP[i].first;
        v[i] = vecP[i].second;
    }
}

template<int MOD>
class ModInt {
public:
    ModInt() :value(0) {}
    ModInt(long long val) :value((int)(val<0 ? MOD + val % MOD : val % MOD)) { }

    ModInt& operator+=(ModInt that) {
        value = value + that.value;
        if (value >= MOD)value -= MOD;
        return *this;
    }
    ModInt& operator-=(ModInt that) {
        value -= that.value;
        if (value<0)value += MOD;
        return *this;
    }
    ModInt& operator*=(ModInt that) {
        value = (int)((long long)value * that.value % MOD);
        return *this;
    }
    ModInt &operator/=(ModInt that) {
        return *this *= that.inverse();
    }
    ModInt operator+(ModInt that) const {
        return ModInt(*this) += that;
    }
    ModInt operator-(ModInt that) const {
        return ModInt(*this) -= that;
    }
    ModInt operator*(ModInt that) const {
        return ModInt(*this) *= that;
    }
    ModInt operator/(ModInt that) const {
        return ModInt(*this) /= that;
    }
    ModInt pow(long long k) const {
        ModInt n = *this, res = 1;
        while (k) {
            if (k & 1)res *= n;
            n *= n;
            k >>= 1;
        }
        return res;
    }
    ModInt inverse() const {
        long long a = value, b = MOD, u = 1, v = 0;
        while (b) {
            long long t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        return ModInt(u);
    }
    int toi() const { return value; }

private:
    int value;
};
typedef ModInt<998244353> mint;
ostream& operator<<(ostream& os, const mint& x) {
    os << x.toi();
    return os;
}

void solve() {
    int N;
    cin >> N;
    vi X(N), Y(N);
    rep(i, N) {
        cin >> X[i] >> Y[i];
    }
    int M = sz(compress(X, Y));
    psort(X, Y);

    BinaryIndexedTree<int> lesX(M), greX(M);
    rep(i, N) {
        greX.add(Y[i], 1);
    }

    auto f = [&](int k) {
        return mint(2).pow(k) - 1;
    };

    mint ans, TOTAL = f(N);
    rep(i, N) {
        greX.add(Y[i], -1);
        mint val = TOTAL;
        val -= f(lesX.sum(M)) + f(greX.sum(M));
        val -= f(lesX.sum(Y[i]) + greX.sum(Y[i]));
        val -= f(lesX.sum(Y[i], M) + greX.sum(Y[i], M));
        val += f(lesX.sum(Y[i])) + f(greX.sum(Y[i]));
        val += f(lesX.sum(Y[i], M)) + f(greX.sum(Y[i], M));
        lesX.add(Y[i], 1);
        ans += val;
    }
    cout << ans << endl;
}

