class BIT {
public:
    int n;
    vector<int> nodes;
    BIT(int n): n(n+1), nodes(n+1, 0) {}

    void add(int i, int v) {
        nodes[++i] += v;
        for (i+=i&(-i); i<=n; i+=i&(-i)) nodes[i] += v;
    }
    int sum(int i) {
        int res = nodes[++i];
        for (i-=i&(-i); i>0; i-=i&(-i)) res += nodes[i];
        return res;
    }
};

