        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    vector<int> tl(n), bl(n);
    {
        BIT bit(2*n);
        for (int i=0; i<n; ++i) {
            bl[i] = bit.sum(p[i].y);
            tl[i] = i - bl[i];
            bit.add(p[i].y, 1);
        }
    }
    vector<int> tr(n), br(n);
    {
        BIT bit(2*n);
        for (int i=n-1; i>=0; --i) {
            br[i] = bit.sum(p[i].y);
            tr[i] = (n-1-i) - br[i];
            bit.add(p[i].y, 1);
