typedef pair<int, int> pii;
typedef map<int, int> mii;

const int Z = 998244353;

void upd(int bit[], int n, int x) {
    for (; x <= n; x += x & -x) {
        bit[x]++;
    }
}

int qry(int bit[], int x) {
    int r = 0;
    for (; x; x -= x & -x) {
        r += bit[x];
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    pii xy[n];
    for (int i = 0; i < n; i++) {
        cin >> xy[i].first >> xy[i].second;
    }
    sort(xy, xy+n);

    int a[n];
    for (int i = 0; i < n; i++) {
        a[i] = xy[i].second;
    }

    mii xx;
    for (int i = 0; i < n; i++) {
        xx[a[i]] = 0;
    }

    int q = 0;
    for (auto p : xx) {
        xx[p.first] = ++q;
    }

    for (int i = 0; i < n; i++) {
        a[i] = xx[a[i]];
    }

    int l[n], r[n], u[n], d[n], lu[n], ru[n], ld[n], rd[n];

    int bit[n+1];
    memset(bit, 0, sizeof(bit));
    for (int i = 0; i < n; i++) {
        ld[i] = qry(bit, a[i]);
        lu[i] = i - ld[i];
        upd(bit, n, a[i]);
    }

    memset(bit, 0, sizeof(bit));
    for (int i = n - 1; i >= 0; i--) {
        rd[i] = qry(bit, a[i]);
        ru[i] = n - 1 - i - rd[i];
        upd(bit, n, a[i]);
    }

    int p2[n+1];
    for (int i = 0; i <= n; i++) {
        p2[i] = i == 0 ? 1 : p2[i-1] * 2 % Z;
    }

    int ans = 0;
    for (int i = 0; i < n; i++) {
        l[i] = i;
        r[i] = n - 1 - i;
        u[i] = lu[i] + ru[i];
        d[i] = ld[i] + rd[i];

        ans = (0ll + ans + p2[n] - 1
              - p2[l[i]] - p2[r[i]] - p2[u[i]] - p2[d[i]]
              + p2[lu[i]] + p2[ld[i]] + p2[ru[i]] + p2[rd[i]]) % Z;
    }

    cout << ans << endl;

    return 0;
}

