struct tree_node{
    int l,r;
    int num;
};
tree_node T[maxn*3];
void maketree(int p,int l,int r){
    T[p].l=l;T[p].r=r;
    T[p].num=0;
    if(l==r){return;}
    int m=(l+r)/2;
    maketree(p*2,l,m);
    maketree(p*2+1,m+1,r);
}
int insert(int p,int x){
    if(T[p].l==T[p].r /*&& T[p].l==x*/){
        T[p].num+=1;
        return 0;
    }
    int m=(T[p].l+T[p].r)/2;
    T[p].num+=1;
    if(x<=m){
        return insert(p*2,x);
    }else{
        return insert(p*2+1,x)+T[p*2].num;
    }
}

