                //printf("%d %d %d\n",i,j,cur);
                ans += cur;if(ans >= mod) ans -= mod;
            }
        }
        ans += pw[n - 1];if(ans >= mod) ans -= mod;
    }
    printf("%d\n",ans);
    return 0;
}

