void solve() {
  ll N;
  cin >> N;

  auto ps = vector<pair<ll, ll>>(N);

  rep(i, 0, N) {
    ll x, y;
    cin >> x >> y;
    ps[i] = pair<ll, ll>(x, y);
  }

  {
    // y の座標圧縮
    vector<ll> ys(N);
    rep(i, 0, N) { ys[i] = ps[i].second; }

    sort(ys.begin(), ys.end());

    rep(i, 0, N) {
      ps[i].second =
          lower_bound(ys.begin(), ys.end(), ps[i].second) - ys.begin();
    }
  }

  sort(ps.begin(), ps.end());

  vector<ll> lu(N), ld(N), ru(N), rd(N);

  {
    Fenwick bit(N);

    rep(i, 0, ps.size()) {
      auto p = ps[i];
      ld[i] = bit.sum(p.second);
      lu[i] = bit.sum(N) - ld[i];
      bit.add(p.second, 1);
    }
  }

  {
    Fenwick bit(N);

    for (ll i = ps.size() - 1; i >= 0; i--) {
      auto p = ps[i];
      rd[i] = bit.sum(p.second);
      ru[i] = bit.sum(N) - rd[i];
      bit.add(p.second, 1);
    }
  }

  mint res = 0;

  rep(i, 0, ps.size()) {
    // E: Exist, A: Any
    mint luA = modpow(mint(2), lu[i]);
    mint luE = luA - 1;
    mint ldA = modpow(mint(2), ld[i]);
    mint ldE = ldA - 1;
    mint ruA = modpow(mint(2), ru[i]);
    mint ruE = ruA - 1;
    mint rdA = modpow(mint(2), rd[i]);
    mint rdE = rdA - 1;

    // その点自身を含まない場合
    res += luE * ldA * ruA * rdE;
    res += luA * ldE * ruE * rdA;
    res -= luE * ldE * ruE * rdE;

    // その点自身を含む場合
    res += luA * ldA * ruA * rdA;
  }

  cout << res << endl;
}

