template<class T>
class BIT {
	vector<T> bit;
	int n;

public:
	BIT(int size) :
		bit(vector<int>(size, 0)), n(size) {}

	T sum(int i) {
		++i;
		if (i > n) {
			//cout << "illegal label in sum" << endl;
			return 0;
		}
		T s = 0;
		while (i > 0) {
			s += bit[i - 1];
			i -= i & -i;
		}
		return s;
	}

	void add(int i, T x) {
		++i;
		if (i > n) {
			//cout << "illegal label in add" << endl;
			return;
		}
		while (i <= n) {
			bit[i - 1] += x;
			i += i & -i;
		}
	}
};

