constexpr ll MOD = 998244353;

ll modpow(ll a, ll n, ll m) {
	ll res = 1;
	while (n) {
		if (n & 1)res = res * a % m;
		a = a * a%m; n >>= 1;
	}
	return res;
}

void solve(){
  int n; cin >> n;
  V<P> v(n);
  FOR(i,0,n) cin >> v[i].sd >> v[i].fs;
  sort(ALL(v));
  FOR(i,0,n) {v[i].fs = i; swap(v[i].fs, v[i].sd);}
  sort(ALL(v));
  FOR(i,0,n) {v[i].fs = i;}
  //coutn(v);
  V<ll> twos(n+10); twos[0] = 1;
  FOR(i,0,n+5) twos[i+1]=(twos[i]<<1)%MOD;
  ll ans = twos[n-1];
  (ans *= n) %= MOD;
  //seg.build();
  FOR(i,0,n){
    int a, b, c, d, e, f; ll tmp = 1;
    a = seg.query(0,v[i].sd);
    e = v[i].sd;
    f = v[i].fs;
    b = e - a;
    c = n - f - b - 1;
    d = f - a;
    //couts(a); couts(b); couts(c); couts(d);
    seg.update(v[i].sd,1);
    (tmp *= (twos[a]))%=MOD;
    (tmp *= (twos[b]))%=MOD;
    (tmp *= (twos[c]))%=MOD;
    (tmp *= (twos[d]))%=MOD;
    (tmp += MOD-1)%=MOD;
    (tmp += MOD-(twos[a]-1))%=MOD;
    (tmp += MOD-(twos[b]-1))%=MOD;
    (tmp += MOD-(twos[c]-1))%=MOD;
    (tmp += MOD-(twos[d]-1))%=MOD;
    (tmp += MOD-(twos[a]-1)*(twos[b]-1)%MOD)%=MOD;
    (tmp += MOD-(twos[c]-1)*(twos[d]-1)%MOD)%=MOD;
    (tmp += MOD-(twos[a]-1)*(twos[d]-1)%MOD)%=MOD;
    (tmp += MOD-(twos[b]-1)*(twos[c]-1)%MOD)%=MOD;
    (ans += tmp) %= MOD;
  }
  couts(ans);
}

