struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x((x%Mod+Mod)%Mod){}
  mint operator-() const { return mint(-x);}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= Mod) x -= Mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += Mod-a.x) >= Mod) x -= Mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= Mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(Mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
  friend ostream& operator<<(ostream& os, const mint& a);
};
ostream& operator<<(ostream& os, const mint& a)
{
  os << a.x;
  return os;
}
struct combination {
  vector<mint> fact, ifact;
  combination(int n):fact(n+1),ifact(n+1) {
    assert(n < Mod);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i-1]*i;
    ifact[n] = fact[n].inv();
    for (int i = n; i >= 1; --i) ifact[i-1] = ifact[i]*i;
  }
  mint operator()(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n]*ifact[k]*ifact[n-k];
  }
};

struct BIT{
  using T = ll;
  vector<T> data;
  T UNIT;
  int n;

  BIT(int n,T a) : n(n), UNIT(a){
    data.resize(n+1,UNIT);
  }

  T sum (int i){
    int s = 0;
    i++;
    while(i > 0){
      s += data[i];
      i -= i & -i;
    }
    return s;
  }

  void add(int i, T x){
    i++;
    while(i <= n){
      data[i] += x;
      i += i & -i;
    }
  }
  T range(int r, int l){
    return sum(r) - sum(l-1);
  }

  int lower_bound(T w){
    if(w <= 0)return 0;
    int x = 0;
    int pos = 1, N = n+1;
    while(pos * 2 <= N){
      pos *= 2;
    }
    for(int k = pos;k>0;k /= 2){
      if(x + k <= N && data[x + k] <= w){
        w -= data[x + k];
        x += k;
      }
    }
    return x + 1;
  }
};
