	while(c <= '9' && c >= '0') x = x * 10 + c - '0' , c = getchar();
	return f? -x : x;
}

int *tree , *pow2;
void add(int x)
{
	for( ; x <= n ; x += x & -x)
		tree[x] ++;
}
int ask(int x)
{
	int res = 0;
	for( ; x ; x ^= x & -x)
		res += tree[x];
	return res;
}

bool cmp(const point &a , const point &b)
{
	return a.x < b.x;
}

