constexpr ll mod = 998244353;
ll modpow(ll a, ll b)
{
    if (b == 0)
    {
        return 1;
    }
    if (b & 1)
    {
        return (a * modpow(a, b - 1)) % mod;
    }
    else
    {
        auto half = modpow(a, b / 2);
        return (half * half) % mod;
    }
}

