// 長さ fw.size() - 1 の列の累積和を管理
vector<int> fw;

// initialize with 0
void fw_init_0(int size)
{
    fw.resize(size + 1);
    fw.assign(size + 1, 0);
}

// 0-based
void fw_add(int i, int x)
{
    i++;
    while (i < fw.size())
    {
        fw[i] += x;
        i += i & -i;
    }
}

// 0-based, sum of [0,i)
int fw_sum1(int i)
{
    int ret = 0;
    while (i >= 1)
    {
        ret += fw[i];
        i -= i & -i;
    }
    return ret;
}

// 0-based, sum of [l,r)
int fw_sum(int l, int r)
{
    return fw_sum1(r) - fw_sum1(l);
}

