		cin >> p[i].first >> p[i].second;
		Y[i] = p[i].second;
	}
	sort(all(p));
	sort(all(Y));

	BIT<int>unused(N);
	BIT<int>used(N);
	for (int i = 0; i < N; i++) {
		int ind = lower_bound(all(Y), p[i].second) - Y.begin();
		unused.plus(ind,1);
	}

	mint ans = 0;
	for (int i = 0; i < N; i++) {
		int ind = lower_bound(all(Y), p[i].second) - Y.begin();
		int a = unused.sum_between(ind + 1, N - 1);
		int b = used.sum_between(ind + 1, N - 1);
		int c = used.sum_between(0, ind - 1);
		int d = unused.sum_between(0,ind-1);
		ans += modpow(2,N-1);
		mint num1 = (modpow(2,a)-1) * (modpow(2,c)-1) * modpow(2,b) * modpow(2,d);
		mint num2 = (modpow(2, b) - 1) * (modpow(2, d) - 1) * modpow(2, a)*modpow(2, c);
		mint num3 = (modpow(2, a)-1)*(modpow(2, b)-1)*(modpow(2, c)-1)*(modpow(2, d)-1);
		ans += num1 + num2 - num3;
		unused.plus(ind, -1);
		used.plus(ind, 1);
	}
	puts(ans.x);

	return 0;
}

