	REP(i, a.size()) {
		if (now_minnest > a[i].real()) {
			now_minnest = a[i].real();
			now_itr = i;
		}
	}
	ans.push_back(now_itr);
	complex<double> ba(0, 1);
	while (true) {
		int now_go = 0;
		double now_min = 0;
		double now_length = 0;
		int starter = ans[ans.size() - 1];
		for (int i = 0; i < a.size(); ++i) {
			if (i != starter) {
				double goa = angles(ba, a[i] - a[starter]);
				if (goa - now_min >= eps || (abs(goa - now_min) <= eps && (abs(a[i] - a[starter]) - now_length) >= eps)) {
					now_min = goa;
					now_go = i;
					now_length = abs(a[i] - a[starter]);
				}
			}
		}
		if (now_go == ans[0]) break;
		ans.push_back(now_go);
		ba = complex<double>(a[now_go] - a[starter]);
	}
	return ans;
}
long long powing(long long A, long long B) {
	long long ans = 1;
	while (B != 0) {
		if (B % 2 == 1) {
			ans *= A;
			ans %= MOD;
		}
		A *= A;
		A %= MOD;
		B /= 2;
	}
	return ans;
}
long long cnt[4][300000] = {};
long long seg_tree[seg_size * 4];
long long seg_find(long long now, long long n_l, long long n_r, long long w_l, long long w_r) {
	if (w_l <= n_l && n_r <= w_r) return seg_tree[now];
	if (w_r <= n_l || n_r <= w_l) return 0;
	return seg_find(now * 2, n_l, (n_l + n_r) / 2, w_l, w_r) + seg_find(now * 2 + 1, (n_l + n_r) / 2, n_r, w_l, w_r);
}
long long seg_set(long long now) {
	seg_tree[now] = seg_tree[now * 2] + seg_tree[now * 2 + 1];
	if (now != 1) seg_set(now / 2);
	return 0;
}
int main() {
	int n;
	cin >> n;
	vector<pair<int, int>> inputs;
	map<int, int> X, Y;
	REP(i, n) {
		int a, b;
		cin >> a >> b;
		X[a] = 1;
		Y[b] = 1;
		inputs.push_back(make_pair(a, b));
	}
	int tmp = 0;
	for (auto i = X.begin(); i != X.end(); ++i) {
		i->second = tmp;
		tmp++;
	}
	tmp = 0;
	for (auto i = Y.begin(); i != Y.end(); ++i) {
		i->second = tmp;
		tmp++;
	}
	REP(i, n) {
		inputs[i] = make_pair(X[inputs[i].first], Y[inputs[i].second]);
	}
	sort(inputs.begin(), inputs.end());
	for (int i = 0; i < inputs.size(); ++i) {
		int go = inputs[i].second;
		cnt[0][i] = seg_find(1, 0, seg_size, 0, go);
		cnt[1][i] = i - cnt[0][i];
		seg_tree[(seg_size + go)]++;
		seg_set((seg_size + go) / 2);
	}
	REP(i, seg_size * 4) {
		seg_tree[i] = 0;
	}
	for (int i = inputs.size()-1; i >= 0; --i) {
		int go = inputs[i].second;
		cnt[3][i] = seg_find(1, 0, seg_size, 0, go);
		cnt[2][i] = ((int)inputs.size()-1 - i) - cnt[3][i];
		seg_tree[(seg_size + go)]++;
		seg_set((seg_size + go) / 2);
	}
	long long ans = n * powing(2, n - 1LL);
	ans %= MOD;
	for (int i = 0; i < n; ++i) {
		REP(j, 4) {
			cnt[j][i] = powing(2, cnt[j][i]) - 1LL;
		}
		ans += cnt[0][i] * cnt[2][i];
		ans %= MOD;
		ans += cnt[1][i] * cnt[3][i];
		ans %= MOD;
		for (int q = 0; q < 4; ++q) {
			long long nya = 1;
			for (int j = 0; j < 3; ++j) {
				nya *= cnt[(q + j) % 4][i];
				nya %= MOD;
			}
			ans += nya;
		}
		long long geko = 1;
		REP(j, 4) {
			geko *= cnt[j][i];
			geko %= MOD;
		}
		ans += geko;
		ans %= MOD;
	}
	cout << ans << endl;
	return 0;
}

