const int MN = 2e5 + 5, LN = 17, MOD = 998244353, INF = 0x3f3f3f3f, BSZ = 320;
int N;
map<int, int> mpx, mpy;
int cnt[MN][4];
int bit[MN];
ll p2[MN];

void upd(int i, int v) {
    for (; i < MN; i += i & -i) bit[i] += v;
}

int qry(int i) {
    int ret = 0;
    for (; i > 0; i -= i & -i) ret += bit[i];
    return ret;
}

int main() {
    ios_base::sync_with_stdio(0), cin.tie(0);
    cin >> N;
    p2[0] = 1;
    for (int i = 1; i <= N; i++) p2[i] = (p2[i - 1] * 2) % MOD;
    vector<int> xs, ys;
    vector<pii> point;
    for (int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        xs.push_back(x);
        ys.push_back(y);
        point.emplace_back(x, y);
    }
    sort(all(xs));
    xs.erase(unique(all(xs)), xs.end());
    sort(all(ys));
    ys.erase(unique(all(ys)), ys.end());
    for (int i = 0; i < xs.size(); i++) mpx[xs[i]] = i + 1;
    for (int i = 0; i < ys.size(); i++) mpy[ys[i]] = i + 1;
    for (pii &p : point) p.first = mpx[p.first], p.second = mpy[p.second];
    sort(all(point));
    for (int i = 0; i < N; i++) {
        int y = point[i].second;
        cnt[i][0] = qry(y - 1);
        cnt[i][1] = i - qry(y);
        upd(y, 1);
    }
    memset(bit, 0, sizeof(bit));
    reverse(all(point));
    for (int i = 0; i < N; i++) {
        int y = point[i].second;
        cnt[N - i - 1][2] = qry(y - 1);
        cnt[N - i - 1][3] = i - qry(y);
        upd(y, 1);
    }
    ll ret = 0;
    for (int i = 0; i < N; i++) {
        ll v = 0;
        (v += (p2[cnt[i][0]] - 1) * (p2[cnt[i][3]] - 1) % MOD * p2[cnt[i][1]] % MOD * p2[cnt[i][2]] % MOD) %= MOD;
        (v += (p2[cnt[i][1]] - 1) * (p2[cnt[i][2]] - 1) % MOD * p2[cnt[i][0]] % MOD * p2[cnt[i][3]] % MOD) %= MOD;
        ll minus = (p2[cnt[i][0]] - 1) * (p2[cnt[i][3]] - 1) % MOD * (p2[cnt[i][1]] - 1) % MOD * (p2[cnt[i][2]] - 1) % MOD;
        (v += p2[N - 1]) %= MOD;
        v = (v - minus + MOD + MOD) % MOD;
        ret = (ret + v) % MOD;
    }
    cout << ret << '\n';
    return 0;
}

#include<vector>
