using Size = int;
template<typename T> class Compression {
 public:
  Compression(const std::vector<T>& list) : value_(list) {
    std::sort(begin(value_), end(value_));
    value_.erase(std::unique(begin(value_), end(value_)), end(value_));
    for(Size i = 0; i < value_.size(); ++i) index_[value_[i]] = i;
  }
  Size size() const {return value_.size();}
  Size index(const T& v) const {return index_.at(v);}
  T operator[](const Size i) const {return value_.at(i);}
 private:
  std::unordered_map<T, Size> index_;
  std::vector<T> value_;
};

// 1-indexed, [l, r)
// construct: O(X * Y)
// update:    O(log X log Y)
// query:     O(log^2 X log^2 Y)
#include<functional>
#include<vector>
template<typename T> class RangeTree {
 public:
  using Size = long long;
  using F = std::function<T(T, T)>;
  RangeTree(Size X, Size Y, const T& E = 0, F merge=[](T l, T r){return l + r;}) : X(X), Y(Y), dat(size(X, Y), E), E(E), merge(merge) {}
  void update(Size x, Size y, const T& v) {update(x, y, v, 0, 0, X, Y, 1, false);}
  T query(Size minx, Size miny, Size maxx, Size maxy) const {return query(minx, miny, maxx, maxy, 0, 0, X, Y, 1, false);}
 private:
  constexpr Size size(Size n) const {return n & (n - 1) ? size(n + (n & -n)) : n;}
  constexpr Size size(Size x, Size y) const {return (size(x) * size(y)) << 3;}
  inline Size lchild(Size n) const {return (n << 1) + 0;}
  inline Size rchild(Size n) const {return (n << 1) + 1;}
  T update(Size x, Size y, const T& v, Size lx, Size ly, Size hx, Size hy, Size n, bool odd) {
    if(x<lx || hx<=x || y<ly || hy<=y) return dat[n];
    if(1+lx==hx && 1+ly==hy)           return dat[n] = v;
    auto nlx=lx, nly=ly, nhx=hx, nhy=hy;
    if(odd) nly = nhy = (ly + hy) >> 1;
    else    nlx = nhx = (lx + hx) >> 1;
    auto l = update(x, y, v, lx, ly, nhx, nhy, lchild(n), !odd);
    auto h = update(x, y, v, nlx, nly, hx, hy, rchild(n), !odd);
    return dat[n] = merge(l, h);
  }
  T query(Size minx, Size miny, Size maxx, Size maxy, Size lx, Size ly, Size hx, Size hy, Size n, bool odd) const {
    if(maxx<=lx || hx<=minx || maxy<=ly || hy<=miny) return E;
    if(minx<=lx && hx<=maxx && miny<=ly && hy<=maxy) return dat[n];
    auto nlx=lx, nly=ly, nhx=hx, nhy=hy;
    if(odd) nly = nhy = (ly + hy) >> 1;
    else    nlx = nhx = (lx + hx) >> 1;
    auto l = query(minx, miny, maxx, maxy, lx, ly, nhx, nhy, lchild(n), !odd);
    auto h = query(minx, miny, maxx, maxy, nlx, nly, hx, hy, rchild(n), !odd);
    return merge(l, h);
  }
  Size X, Y;
  F merge;
  T E;
  std::vector<T> dat;
};

#include<bits/stdc++.h>
using namespace std;

using LL = long long;
const LL M = 998244353;

LL power(LL m, LL n) {
  if(!n) return 1;
  return (n & 1) ? (power(m, n - 1) * m % M) : power(m * m % M, n >> 1);
}

int main() {
  struct Point {int x, y;};
  const int INF = 2e9;

  int N;
  cin >> N;
  vector<Point> P(N);
  for(auto& i: P) cin >> i.x >> i.y;

  vector<int> v{-INF, INF};
  for(auto& i: P) v.emplace_back(i.x), v.emplace_back(i.y);
  Compression C(v);

  RangeTree<int> T(C.size(), C.size());
  for(auto& i: P) T.update(C.index(i.x), C.index(i.y), 1);
  LL ans = 0;
  for(const auto& p: P) {
    // T に含まれる場合
    ans += power(2, N-1);
    ans %= M;
    // T に含まれない場合
    auto x=C.index(p.x),  y=C.index(p.y);
    auto l=C.index(-INF), h=C.index(INF);
    LL lr = T.query(x, l, 1+h, 1+y) - 1;
    LL ul = T.query(l, y, 1+x, 1+h) - 1;
    LL ll = T.query(l, l, 1+x-1, 1+y-1);
    LL ur = T.query(x+1, y+1, 1+h, 1+h);
    LL urll = (power(2,ur)-1) * (power(2,ll)-1) % M;
    LL ullr = (power(2,ul)-1) * (power(2,lr)-1) % M;
    ans += urll * power(2,N-1-ur-ll) % M;
    ans %= M;
    ans += ullr * power(2,N-1-ul-lr) % M;
    ans %= M;
    ans += M - (urll * ullr % M) * power(2,N-1-ur-ll-ul-lr) % M;
    ans %= M;
  }
  cout << ans << endl;
}

