#include <bits/stdc++.h>
using namespace std;

constexpr int64_t mod = 998244353;
template<typename Tp>
class binary_indexed_tree{
    vector<Tp> tree;
    int depth;

public:
    binary_indexed_tree(size_t n){
        for(depth=0;(1<<depth)<n;depth++);
        tree.resize(1ULL<<depth);
    }

    void add(size_t pos, Tp value){
        pos++;
        for(;pos<=(1<<depth);pos+=pos&-pos){
            tree[pos-1] += value;
        }
    }

    Tp sum(size_t pos){
        pos++;
        int64_t s = 0;
        for(;pos>0;pos-=pos&-pos){
            s += tree[pos-1];
        }

        return s;
    }

    Tp sum(size_t left, size_t right){
        return sum(right-1) - sum(left-1);
    }
};

int64_t mpow(int64_t x, int64_t y){
    if(y == 0) return 1;
    if(y == 1) return x % mod;
    if(y%2 == 0) return mpow(x*x%mod, y/2);
    return mpow(x*x%mod, y/2) % mod * x % mod;
}

int main(){
    int n;
    cin >> n;
    pair<int,int> pts[200000];
    for(int i=0;i<n;i++){
        int x, y;
        cin >> x >> y;
        pts[i] = {x, y};
    }
    sort(pts, pts+n, [](const auto& x, const auto& y){ return x.second < y.second; });
    for(int i=0;i<n;i++) pts[i].second = i;
    sort(pts, pts+n);
    for(int i=0;i<n;i++) pts[i].first = i;

    binary_indexed_tree<int> bit_y(n);
    int ul[200000] = {0};
    for(int i=0;i<n;i++){
        ul[i] = i - bit_y.sum(pts[i].second);
        bit_y.add(pts[i].second, 1);
    }

    int64_t ans = 0;
    for(int i=0;i<n;i++){
        int64_t a, b, c, d;
        a = ul[i];  b = n - bit_y.sum(pts[i].second) - a;
        c = i - a;  d = n - (a + b + c) - 1;
        ans = (ans + mpow(2, a) + mpow(2, b) + mpow(2, c) + mpow(2, d) - 3) % mod;
        ans = (ans + (mpow(2, a) - 1) * (mpow(2, b) - 1) % mod + (mpow(2, b) - 1) * (mpow(2, d) - 1) % mod + 
            (mpow(2, d) - 1) * (mpow(2, c) - 1) % mod + (mpow(2, c) - 1) * (mpow(2, a) - 1) % mod) % mod;
        ans = (ans + 2 * (mpow(2, a) - 1) * (mpow(2, d) - 1) % mod * mpow(2, b) % mod * mpow(2, c) % mod +
            2 * (mpow(2, b) - 1) * (mpow(2, c) - 1) % mod * mpow(2, a) % mod * mpow(2, d) % mod -
            2 * (mpow(2, a) - 1) * (mpow(2, d) - 1) % mod * (mpow(2, b) - 1) % mod * (mpow(2, c) - 1) % mod + mod) % mod;
    }

    cout << ans << endl;
    return 0;
}

