inline void add(int x,int val){for(int i=x;i<=n;i+=i&(-i)) c[i]+=val;}
inline int q(int x){int res=0; for(int i=x;i;i-=i&-i) res+=c[i]; return res;}

inline bool cmp1(node a,node b){return a.x<b.x;}
inline bool cmp2(node a,node b){return a.y<b.y;}

inline ll pw(ll a,ll b)
{
	ll ans=1,base=a;
	while(b)
	{
		if(b&1) ans=(ans*base)%mod;
		base=(base*base)%mod; b>>=1;
	}
	return ans;
}

inline ll M(ll a,ll b){return (a*b)%mod;}

inline ll gs(int i)
{
	ll a=pw(2,p[i].a),b=pw(2,p[i].b),c=pw(2,p[i].c),d=pw(2,p[i].d);
	ll p1=M(M(M(c,d),a-1),b-1);
	ll p2=M(M(M(a,b),c-1),d-1);
	ll p3=M(M(M(a-1,b-1),c-1),d-1);
	return (p1+p2-p3+mod)%mod;
}

inline ll g2(int x)
{
	int cnt=0;
	while(x) {if(x&1) cnt++; x>>=1;}
	return cnt;
}

