template<typename T>
class FenwickTree {
    const int n;
    std::vector<T> data;

public:
    FenwickTree(int count) : n(count), data(count, 0) { ; }

    void add(int pos, const T &value) {
        assert(0 <= pos && pos < n);
        for (int i = pos; i < n; i |= i + 1) data[i] += value;
    }

    // 区間 [0, pos) 番目の範囲の和を求める．(pos = 0 のときは 0 を返す．)
    T sum(int pos) const {
        assert(0 <= pos && pos <= n);
        T res = 0;
        for (int i = pos - 1; i >= 0; i = (i & (i + 1)) - 1) {
            res += data[i];
        }
        return res;
    }

    // 区間 [l, r) 番目の範囲の和を求める．(l = r のときは 0 を返す．)
    T sum(int l, int r) const {
        assert(0 <= l && l <= r && r <= n);
        return sum(r) + (-sum(l));
    }

    using value_type = T;
    using update_type = T;
};

template<class T>
class Compress {
private:
    vector<T> data;

public:
    Compress(const vector<T> &vec) : data(vec) {
        sort(data.begin(), data.end());
        data.erase(unique(data.begin(), data.end()), data.end());
    }

    T get(int k) {
        assert(k >= 0 && k < data.size());
        return data[k];
    }

    typename vector<T>::iterator lower_bound(const T &t) {
        return ::lower_bound(data.begin(), data.end(), t);
    }

    typename vector<T>::iterator upper_bound(const T &t) {
        return ::upper_bound(data.begin(), data.end(), t);
    }

    int lb_index(const T &t) {
        return lower_bound(t) - data.begin();
    }

    int ub_index(const T &t) {
        return upper_bound(t) - data.begin();
    }

    size_t size() {
        return data.size();
    }
};

void solve(long long N, std::vector<long long> x, std::vector<long long> y) {


    mInt ans = 0;

    vector<Query> qs;

    vector<ll> ycmp;
    auto rect = [&](ll x1, ll x2, ll y1, ll y2, ll id, ll p, ll q) {
        assert(x1 < x2);
        assert(y1 < y2);
        qs.push_back({x1 - 1, y1, y2, id, p, q, -1});
        qs.push_back({x2, y1, y2, id, p, q, 1});
        ycmp.push_back(y1);
        ycmp.push_back(y2);
    };

    auto add = [&](ll x, ll y) {
        Query q;
        q.x = x;
        q.y1 = y;
        q.t = 0;
        qs.push_back(q);
        ycmp.push_back(y);
    };
    for (int i = 0; i < N; i++) {
        //cout << x[i] << "," << y[i] << endl;
        add(x[i], y[i]);
    }

    Compress<ll> cmp(ycmp);
    FenwickTree<ll> bit(cmp.size());

    for (int i = 0; i < x.size(); i++) {
        rect(-1e18, x[i], -1e8, y[i], i, 1, 1);
        rect(x[i] + 1, 1e18, -1e8, y[i], i, 0, 1);
        rect(-1e18, x[i], y[i] + 1, 1e18, i, 1, 0);
        rect(x[i] + 1, 1e18, y[i] + 1, 1e18, i, 0, 0);
    }
    sort(qs.begin(), qs.end());


    for (auto q : qs) {
        if (q.t == 1) {
            dpc[q.id][q.p][q.q] += q.coef * bit.sum(cmp.lb_index(q.y1), cmp.lb_index(q.y2));
        } else {
            bit.add(cmp.lb_index(q.y1), 1);
        }
    }

    for (int i = 0; i < x.size(); i++) {
//        ll dp[2][2] = {};
//        for (int j = 0; j < y.size(); j++) {
//            if (i != j) {
//                dp[x[j] - x[i] < 0][y[j] - y[i] < 0]++;
//            }
//        }
//        cout << dpc[i][0][0] << " " << dp[0][0] << endl;
//        cout << dpc[i][0][1] << " " << dp[0][1] << endl;
//        cout << dpc[i][1][0] << " " << dp[1][0] << endl;
//        cout << dpc[i][1][1] << " " << dp[1][1] << endl;
//        cout << endl;

        ans += (mInt(2) ^ (dpc[i][0][0] + dpc[i][0][1])) - 1;
        ans += (mInt(2) ^ (dpc[i][0][1] + dpc[i][1][1])) - 1;
        ans += (mInt(2) ^ (dpc[i][1][1] + dpc[i][1][0])) - 1;
        ans += (mInt(2) ^ (dpc[i][1][0] + dpc[i][0][0])) - 1;

        ans -= (mInt(2) ^ (dpc[i][1][0])) - 1;
        ans -= (mInt(2) ^ (dpc[i][0][1])) - 1;
        ans -= (mInt(2) ^ (dpc[i][1][1])) - 1;
        ans -= (mInt(2) ^ (dpc[i][0][0])) - 1;
    }


    mInt overall = 0;
    for (int i = 0; i < N; i++) {
        overall += ((mInt(2) ^ N) - 1);
    }
    overall -= ans;
//    cerr << "HO" << endl;
    cout << (ll) overall << endl;

};


