template <uint MD>
struct ModInt {
    using M = ModInt;
    const static M G;
    uint v;
    ModInt(ll _v = 0) { set_v(_v % MD + MD); }
    M& set_v(uint _v) {
        v = (_v < MD) ? _v : _v - MD;
        return *this;
    }
    explicit operator bool() const { return v != 0; }
    M operator-() const { return M() - *this; }
    M operator+(const M& r) const { return M().set_v(v + r.v); }
    M operator-(const M& r) const { return M().set_v(v + MD - r.v); }
    M operator*(const M& r) const { return M().set_v(ull(v) * r.v % MD); }
    M operator/(const M& r) const { return *this * r.inv(); }
    M& operator+=(const M& r) { return *this = *this + r; }
    M& operator-=(const M& r) { return *this = *this - r; }
    M& operator*=(const M& r) { return *this = *this * r; }
    M& operator/=(const M& r) { return *this = *this / r; }
    bool operator==(const M& r) const { return v == r.v; }
    M pow(ll n) const {
        M x = *this, r = 1;
        while (n) {
            if (n & 1)
                r *= x;
            x *= x;
            n >>= 1;
        }
        return r;
    }
    M inv() const { return pow(MD - 2); }
    friend ostream& operator<<(ostream& os, const M& r) { return os << r.v; }
};
using Mint = ModInt<MOD>;

int N;
struct P {
    int x, y;
};

vector<P> V;
int A[202020], B[202020], C[202020], D[202020];

void solve() {
    Mint ans = 0;
    Compress<int> CX, CY;
    FOR(N) {
        CX.add(V[i].x);
        CY.add(V[i].y);
    }
    CX.build();
    CY.build();
    FOR(N) {
        V[i].x = CX.get(V[i].x);
        V[i].y = CY.get(V[i].y);
        //cerr << i << " " << V[i].x << " " << V[i].y << endl;
    }
    sort(all(V), [](P a, P b) { return a.x < b.x; });
    SegmentTree<int> seg(N, [](itn a, int b) { return a + b; }, 0);
    seg.build();
    FOR(x, N) {
        A[x] = seg.query(0, V[x].y);
        B[x] = x - A[x];
        seg.update(V[x].y, 1);
    }
    FOR(x, N) {
        seg.update(x, 0);
    }
    for (int x = N - 1; x >= 0; x--) {
        C[x] = seg.query(0, V[x].y);
        D[x] = seg.query(V[x].y, N);
        seg.update(V[x].y, 1);
    }
    FOR(N) {
        int a = A[i], b = B[i], c = C[i], d = D[i];
        //cerr << a << " " << b << " " << c << " " << d << endl;
        Mint tmp = 0;
        Mint two = 2;
        Mint aa = two.pow(a);
        Mint bb = two.pow(b);
        Mint cc = two.pow(c);
        Mint dd = two.pow(d);
        tmp += (aa - 1) * (bb - 1) * (cc - 1) * dd;
        tmp += (bb - 1) * (cc - 1) * dd;
        tmp += (aa - 1) * (dd - 1) * bb;
        tmp += (aa - 1) * (dd - 1) * (cc - 1);
        tmp += two.pow(N - 1);
        ans += tmp;
    }
    cout << ans << endl;
}

