/// 座圧 座標圧縮
template <class T>
struct CoordinateCompression
{
	map<T, int> comp{};
	vector<T> decomp{};
	vector<T> init(const vector<T>& orig)
	{
		decomp = orig;
		//decomp.push_back(numeric_limits<T>::min());
		//decomp.push_back(numeric_limits<T>::max());
		sort(allof(decomp));
		decomp.erase(unique(allof(decomp)), decomp.end());
		REP(i, decomp.size()) { comp[decomp[i]] = i; }
		vector<T> ret(orig.size());
		REP(i, orig.size()) { ret[i] = comp[orig[i]]; }
		return ret;
	}
	size_t size() { return decomp.size(); }
	T operator[](int x) { return decomp[x]; } ///< 圧縮後の値xはもともと何の値だったのか？
};
template <class T>
struct CoordinateCompression2D
{
	CoordinateCompression<T> Xs, Ys;

	template <class P>
	vector<P> init(const vector<P>& orig)
	{
		size_t N = orig.size();
		vector<T> x(N); REP(i, N) { x[i] = orig[i].x; } x = Xs.init(x);
		vector<T> y(N); REP(i, N) { y[i] = orig[i].y; } y = Ys.init(y);
		vector<P> ret(N); REP(i, N) { ret[i] = { x[i], y[i] }; }
		return ret;
	}
	struct size2D { size_t x, y; };
	size2D size() { return { Xs.size(), Ys.size() }; }

	template <class P>
	P operator[](P p) { return { Xs[p.x], Ys[p.y] }; }
};


// modを法としたxのy乗を求める。(繰り返し二乗法)
inline llong modPow(llong x, llong y, llong mod)
{
	llong r = 1;
	for (; y > 0; y >>= 1)
	{
		if (y & 1) { r = r * x % mod; }
		x = x * x % mod;
	}
	return r;
}


/// 2分セグメント木。RMQとかが解ける。
template<class T, class TParentFunc>
struct SegTreeT
{
	int size;
	vector<T> tree;
	TParentFunc parent;
	T initialValue;
	static constexpr unsigned int msb(unsigned int v) { REP(i, 5) v |= v >> (1 << i); return (v >> 1) + 1; }

	SegTreeT(int count, TParentFunc parentBuilder, T initialFill)
		: size(msb(count - 1) << 1)
		, tree(size * 2)
		, parent(parentBuilder)
		, initialValue(initialFill)
	{
		fill(partof(tree, size, size + size), initialFill);
		rebuild();
	}

	// []を使うと更新されないのでrebuildすること。数が少なければupdateの方がよい。
	T& operator[](int i) { return tree[i + size]; }
	void rebuild() { RREP(i, size) { tree[i] = parent(tree[i * 2], tree[i * 2 + 1]); } }

	void update(int index, T value)
	{
		tree[index + size] = value;
		for (int i = (index + size) / 2; i > 0; i /= 2)
			tree[i] = parent(tree[i * 2], tree[i * 2 + 1]);
	}

	T query(int s, int e, int i, int l, int r, T value)
	{
		if (r <= s || e <= l) return value;
		if (s <= l && r <= e) return parent(value, tree[i]);
		value = query(s, e, i * 2, l, (l + r) / 2, value);
		value = query(s, e, i * 2 + 1, (l + r) / 2, r, value);
		return value;
	}

	T query(int begin, int end, T initialValue) { return query(begin, end, 1, 0, size, initialValue); }
	T query(int begin, int end) { return query(begin, end, initialValue); }
};

template<class T, class TParentFunc = const T & (*)(const T&, const T&)>
auto SegTree(int N, TParentFunc f = min, T initialValue = INF(T))
{
	return SegTreeT<T, TParentFunc>(N, f, initialValue);
}

