void solve()
{
	READ(int, N);

	struct P
	{
		int x, y;
		int lt, lb, rt, rb;
	};

	std::vector<P> Ps;
	REP(i, N)
	{
		READ(int, x, y);
		Ps.push_back({ x,y });
	}
	Ps = CoordinateCompression2D<int>().init(Ps);
	std::sort(allof(Ps), COMP(a, b, a.x != b.x ? a.x < b.x : a.y < b.y));

	{
		auto seg = SegTree(N, plus<>(), 0);
		REP(i, N)
		{
			Ps[i].lt = seg.query(0, Ps[i].y);
			Ps[i].lb = seg.query(Ps[i].y + 1, N);
			seg.update(Ps[i].y, 1);
		}
	}

	{
		auto seg = SegTree(N, plus<>(), 0);
		RREP(i, N)
		{
			Ps[i].rt = seg.query(0, Ps[i].y);
			Ps[i].rb = seg.query(Ps[i].y + 1, N);
			seg.update(Ps[i].y, 1);
		}
	}

	const llong mod = 998244353;
	llong ans = 0;
	REP(i, N)
	{
		P p = Ps[i];

		llong a = 0;
		a += modPow(2, p.lt + p.rt, mod) - 1;
		a += modPow(2, p.rt + p.rb, mod) - 1;
		a += modPow(2, p.rb + p.lb, mod) - 1;
		a += modPow(2, p.lb + p.lt, mod) - 1;
		a -= modPow(2, p.lt, mod) - 1;
		a -= modPow(2, p.rt, mod) - 1;
		a -= modPow(2, p.rb, mod) - 1;
		a -= modPow(2, p.lb, mod) - 1;
		a = (a + mod) % mod;

		a = (modPow(2, N, mod) - 1) - a;

		ans += a;
		ans %= mod;
	}
	WRITE(ans);

}

