vector<int> X, Y;
SegmentTree rsqL, rsqR;

LL queryL(int i, int j){
	return power(2, rsqL.sum(i, j))-1+MOD;
}

LL queryR(int i, int j){
	return power(2, rsqR.sum(i, j))-1+MOD;
}

int main(){
	scanf("%d", &N);
	for(int i=0; i<N; i++){
		scanf("%d%d", &P[i].first, &P[i].second);
		X.PB(P[i].first);
