		P[i].first = lower_bound(X.begin(), X.end(), P[i].first) - X.begin();
		P[i].second = lower_bound(Y.begin(), Y.end(), P[i].second) - Y.begin();
	}
	sort(P, P+N);
	rsqL.init(N);
	rsqR.init(N);
	rsqR.update(0, N, 1);

	LL ans = 0;
	for(int i=0; i<N; i++){
