		LL ld = queryL(0, P[i].second);
		LL lu = queryL(P[i].second+1, N);
		LL rd = queryR(0, P[i].second);
		LL ru = queryR(P[i].second+1, N);

		// P exclusive (* 2 means the case inclusive)
		ans += ld * ru * 2;
		ans %= MOD;
		ans += ld * ru % MOD * lu * 2;
		ans %= MOD;
		ans += ld * ru % MOD * rd * 2;
		ans %= MOD;
		ans += ld * ru % MOD * lu % MOD * rd * 2;
		ans %= MOD;

