ll pow2(ll n) {
  static ll memo[200000];
  if (memo[n]!=0)
    return memo[n];

  if (n==0) {
    return memo[n] = 1;
  } else if (n%2 == 0) {
    ll x = pow2(n/2);
    return memo[n] = x * x;
  } else {
    return memo[n] = pow2(n-1) * 2;
  }
}

