map<int, int> xs;
int fent[N];

void clr() {
        for (int i = 1; i <= n; i++)
                fent[i] = 0;
}

void add(int i) {
        while (i <= n) {
                fent[i]++;
                i += i & (-i);
        }
}

int sma(int i) {
        int sol = 0;
        while (i) {
                sol += fent[i];
                i -= i & (-i);
        }
        return sol;
}

