                x[i] = xs[x[i]];
        for (int it = 1; it <= n; it++) {
                int i = ord[it];
                p11[i] = sma(x[i]);
                p22[i] = it - 1 - p11[i];
                add(x[i]);
        }
        clr();
        for (int it = n; it >= 1; it--) {
                int i = ord[it];
                p33[i] = n - it - sma(x[i]);
