ll mod = 998244353;
ll exp_to_pow[200005];

void make_exp_to_pow(void)
{
    ll val = 1LL;
    rep (i, 200005) {
        exp_to_pow[i] = val;
        val *= 2LL;
        val %= mod;
    }

    debug_printf("---- exp_to_pow\n"); debug_print(exp_to_pow, 10);
}

ll exp_to_pow_decr(ll exp, ll decr)
{
    ll ret = exp_to_pow[exp] - decr;
    if (ret < 0LL) ret += mod;
    return ret;
}

void normalize_sort(V<t2> &xylist)
{
    V<t2> yxlist;
    for (auto xy : xylist) {
        ll x = get<0>(xy);
        ll y = get<1>(xy);
        yxlist.pb(t2(y, x));
    }
    sort(yxlist);

    xylist.clear();

    rep (i0, yxlist.size()) {
        ll i = i0 + 1LL;
        ll x = get<1>(yxlist[i0]);
        xylist.pb(t2(x, i));
    }
    sort(xylist);

    debug_printf("---- xylist\n"); debug_print(xylist);
}

ll solve(ll n, ll x, ll y, BIT &left_bit, BIT &right_bit)
{
    right_bit.add(y, -1LL);

    ll left_under = left_bit.sum(y);
    ll left_upper = left_bit.sum(n) - left_under;
    ll right_under = right_bit.sum(y);
    ll right_upper = right_bit.sum(n) - right_under;
    debug_printf("left_under=%lld left_upper=%lld "
                 "right_under=%lld right_upper=%lld\n",
                 left_under, left_upper, right_under, right_upper);

    left_bit.add(y, 1LL);

    ll ret0 = exp_to_pow_decr(left_under, 1LL) * exp_to_pow_decr(right_upper, 1LL);
    ret0 %= mod;
    ret0 *= exp_to_pow_decr(left_upper, 0LL);
    ret0 %= mod;

    ll ret1 = exp_to_pow_decr(left_upper, 1LL) * exp_to_pow_decr(right_under, 1LL);
    ret1 %= mod;
    ret1 *= exp_to_pow_decr(right_upper, 0LL);
    ret1 %= mod;

    ll ret2 = exp_to_pow_decr(left_under, 1LL) * exp_to_pow_decr(right_under, 1LL);
    ret2 %= mod;
    ret2 *= exp_to_pow_decr(left_upper + right_upper, 1LL);
    ret2 %= mod;

    ll ret3 = exp_to_pow_decr(n - 1LL, 0LL);

    ll ret = (ret0 + ret1 + ret2 + ret3) % mod;
    debug_printf("---- ret0=%lld ret1=%lld ret2=%lld ret3=%lld ret=%lld\n",
                 ret0, ret1, ret2, ret3, ret);
    return ret;
}

int _main()
{
    ll n; llin(n);
    V<t2> xylist; llinl2(xylist, n);

    make_exp_to_pow();
    normalize_sort(xylist);

    BIT left_bit = BIT(n, 0LL);
    BIT right_bit = BIT(n, 1LL);

    ll ans = 0LL;

    for (auto xy : xylist) {
        ans += solve(n, get<0>(xy), get<1>(xy), left_bit, right_bit);
        ans %= mod;
    }

    cout << ans;

    return 0;
}

