#include<bits/stdc++.h>
using namespace std;
#define ll long long 
int n,m;
const int N=2e5+100;
struct node
{
	ll x,y;
	bool operator<(const node &a)const 
	{
		return x<a.x;
	}
}p[N];
const int mod=998244353;
int c[N],ld[N],rd[N],lu[N],ru[N];
ll f[N],y[N];
void add(int x)
{
	while(x<=n)
	{
		c[x]+=1;
		x+=x&-x;
	}
}
int query(int x)
{
	int res=0;
	while(x)
	{
		res+=c[x];
		x-=x&-x;
	}
	return res;
}
ll A(ll &x,ll b)
{
	x=(x+b)%mod; 
}
ll D(ll &x,ll b)
{
	x=(x-b+mod)%mod;
}
int main()
{
	ios::sync_with_stdio(false);
	cin>>n;
	f[0]=1; 
	for(int i=1;i<=n;i++) 
	{
		cin>>p[i].x>>p[i].y;
		y[i]=p[i].y;
		f[i]=(f[i-1]<<1)%mod; 
	}
	sort(p+1,p+1+n);
	sort(y+1,y+n+1);
	for(int i=1;i<=n;i++) p[i].y=lower_bound(y+1,y+1+n,p[i].y)-y;
	for(int i=1;i<=n;i++)
	{

		ld[i]=query(p[i].y);
		lu[i]=i-ld[i]-1;
		add(p[i].y);
	} 
	memset(c,0,sizeof c);
	for(int i=n;i>=1;i--)
	{
		rd[i]=query(p[i].y);
		ru[i]=n-i-rd[i];
		add(p[i].y);
	}
	ll ans=0;
	for(int i=1;i<=n;i++)
	{
		A(ans,f[n-1]);//选i点 
		A(ans,f[n-1]-1);//不选i点
		D(ans,f[lu[i]+ld[i]]);//减去左上左下不合法的
		D(ans,f[ru[i]+rd[i]]);//右上右下
		D(ans,f[ru[i]+lu[i]]);//左上右上
		D(ans,f[ld[i]+rd[i]]);//左下右下
		A(ans,f[lu[i]]);//把多减的加上 
		A(ans,f[ld[i]]);
		A(ans,f[ru[i]]);
		A(ans,f[rd[i]]); 
	}
	cout<<ans<<endl;
	return 0; 
}

