int main() {
    using namespace std;
    constexpr unsigned long maxN = 200010;
    unsigned long N;
    scanf("%lu", &N);
    array<unsigned long, maxN> perm;
    {
        array<pair<long, long>, maxN> p;
        for(unsigned long i = 0; i < N; ++i)scanf("%lu%lu", &p[i].first, &p[i].second);
        sort(p.begin(), p.begin() + N);
        for(unsigned long i = 0; i < N; ++i)p[i] = {p[i].second, i + 1};
        sort(p.begin(), p.begin() + N);
        transform(p.cbegin(), p.cbegin() + N, perm.begin(), [](auto i){return i.second;});
    }

    constexpr unsigned long MOD = 998244353;
    array<unsigned long, maxN> binary;
    unsigned long n = binary[0] = 1;
    generate(binary.begin() + 1, binary.end(), [&n](){if(n >= MOD)n -= MOD;return n <<= 1;});

    array<unsigned long, maxN> fenwick_tree{};
    auto que = [&fenwick_tree, &N](unsigned long i){
        unsigned long s{0}, j{i};
        while (i) { s += fenwick_tree[i]; i -= i & -i; }
        while (j <= N) { ++fenwick_tree[j]; j += j & -j; }
        return s;
    };

    array<unsigned long, maxN> coef{};
    coef[N] = N + MOD - 4;
    for(unsigned long i = 0; i != N; ++i){
        auto p = perm[i], q = que(p);
        ++coef[q];
        ++coef[i - q];
        ++coef[p - q - 1];
        ++coef[N - i - p + q];
    }

    cout << inner_product(binary.begin(), binary.begin() + N + 1, coef.begin(), 4 + MOD - N) % MOD << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef complex<double> Vec;

ll N;
const ll MOD = 998244353;
vector<ll> Pow;
vector<ll> Y;
vector<pair<ll, ll>> XY;
map<ll, ll> IY;
ll R;

void prepare() {
  Pow.push_back(0);
  for (ll i = 1; i <= N; ++i) {
    Pow.push_back((Pow.back() * 2 + 1) % MOD);
  }
}

vector<ll> BIT;
void add(ll i, ll x) {
  for (; i <= N; i += i & -i) BIT[i] += x;
}
ll sum(ll i) {
  ll res = 0;
  for (; i > 0; i -= i & -i) res += BIT[i];
  return res;
}
void solve() {
  R = N * Pow[N] % MOD;
  for (ll i = 0; i < N; ++i) {
    (R += MOD - 2 * (Pow[i] + Pow[N - 1 - i]) % MOD) %= MOD;
  }
  BIT.resize(N + 1);
  for (ll cnt = 0; cnt < N; ++cnt) {
    ll y = XY[cnt].second;
    ll i = IY.at(y) + 1;
    ll left = sum(i);
    ll right = cnt - left;
    assert(left >= 0 && right >= 0);
    (R += Pow[left]) %= MOD;
    (R += Pow[right]) %= MOD;
    add(i, 1);
  }
  BIT.clear();
  BIT.resize(N + 1);
  for (ll cnt = 0; cnt < N; ++cnt) {
    ll y = XY[N - 1 - cnt].second;
    ll i = IY.at(y) + 1;
    ll left = sum(i);
    ll right = cnt - left;
    assert(left >= 0 && right >= 0);
    (R += Pow[left]) %= MOD;
    (R += Pow[right]) %= MOD;
    add(i, 1);
  }
}

int main() {
  cin >> N;
  prepare();
  for (ll i = 0; i < N; ++i) {
    ll x, y;
    cin >> x >> y;
    Y.push_back(y);
    XY.push_back(make_pair(x, y));
  }
  sort(Y.begin(), Y.end());
  for (ll i = 0; i < N; ++i) {
    IY[Y[i]] = i;
  }
  sort(XY.begin(), XY.end());
  solve();
  cout << R << endl;
  return 0;
}

