inline int getint(void) {
    reint x = 0, ch = getchar(), f = 0;
    for (; (ch < '0' || ch > '9') && ch != '-'; ch = getchar());
    if (ch == '-') f = 1, ch = getchar();
    for (; ch >= '0' && ch <= '9';
        x = (x << 1) + (x << 3) + (ch - '0'), ch = getchar());
    return f ? -x : x;
}

inline ll mod(ll num) {
    if (num < 0) num += MOD;
    if (num >= MOD) num -= MOD;
    return num;
}

struct BinaryIndexedTree {
    int li[SIZE];

    inline void clear(void) { memset(li, 0, sizeof li); return; }
    BinaryIndexedTree(void) { clear(); return; }
    inline int lowbit(coint num) { return num & (-num); }

    inline void modify(coint ind, coint k) {
        for (reint i = ind; i < SIZE; i += lowbit(i)) li[i] += k;
        return;
    }

    inline ll query(coint ind) {
        register ll res = 0;
        for (reint i = ind; i; i -= lowbit(i)) res += li[i];
        return res;
    }
};

