const int mod = 998244353;
const int MAXN = 200*1000+5;

int fen[MAXN];

int mul(int a, int b) { return 1LL * a * b % mod; }
int mpow(int a, int n) {
	if(n == 0) return 1;
	int x = mpow(a, n/2);
	x = mul(x, x);
	if(n % 2 == 1) x = mul(x, a);
	return x;
}
void add_self(int& a, int b) { a += b; if(a >= mod) a -= mod; }
void sub_self(int& a, int b) { a -= b; if(a < 0) a += mod; }

void upd(int i, int v) {
	for(; i < MAXN; i += i & -i) {
		add_self(fen[i], v);
	}
}

int get(int i) {
	int ans = 0;
	for(; i > 0; i -= i & -i) {
		add_self(ans, fen[i]);
	}
	return ans;
}

void compress(vector<pair<int, int>>& arr) {
	map<int, int> mp;
	int i = 1;
	for(auto p : arr) {
		mp[p.first] = -1;
	}
	for(auto& p : mp) {
		p.second = i++;
	}
	for(auto& p : arr) {
		p.first = mp[p.first];
	}
	i = 1;
	mp.clear();
	for(auto p : arr) {
		mp[p.second] = -1;
	}
	for(auto& p : mp) {
		p.second = i++;
	}
	for(auto& p : arr) {
		p.second = mp[p.second];
	}
}


