	for(int i = 0; i < n; i++) {
		add_self(ans, mpow(2, n));
		sub_self(ans, mpow(2, i));
		sub_self(ans, mpow(2, n-i-1));
		sub_self(ans, mpow(2, arr[i].second-1));
		sub_self(ans, mpow(2, n-arr[i].second));
		int bl = get(arr[i].second);
		int tl = i - bl;
		int br = arr[i].second-1-bl;
		int tr = n-1 - (bl + tl + br);
		add_self(ans, mpow(2, bl));
