struct BIT {
  int sz;
  vi node;
  BIT(int n): sz(n+1), node(vi(n+1)) {}

  void add(int idx, int val) {
    idx++;
    while(idx < sz) {
      node[idx] += val;
      idx += idx & -idx;
    }
  }

  int sum(int idx) {
    idx++;
    int res = 0;
    while(idx) {
      res += node[idx];
      idx -= idx & -idx;
    }
    return res;
  }

};

template< typename T >
T mod_pow(T x, T n, const T &p) {
  T ret = 1;
  while(n > 0) {
    if(n & 1) (ret *= x) %= p;
    (x *= x) %= p;
    n >>= 1;
  }
  return ret;
}



