        sl .add (Y[i]);
        sr .add (Y[i],-1);
        // a b
        // c d

        //真ん中を選ばない時
        calc(vi{a, d});
        calc(vi{b, c});
        calc(vi{a, b, c});
        calc(vi{a, b, d});
        calc(vi{a, c, d});
        calc(vi{b, c, d});
        calc(vi{a, b, c, d});

        //真ん中を選ぶ
        res += mpow(2, a + b + c + d);
    }

    cout << res << endl;
}

