class SegTree {
public:
    const int MAX_N = 1 << 17;
    int n;
    vector<ll> dat;
    const ll INITIAL_DAT = 0L;

    SegTree(int n_) {
        init(n_);
    }

    void init(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        dat = vector<ll>(2 * n);
        for (int i = 0; i < 2 * n - 1; ++i) dat[i] = INITIAL_DAT;
    }

    //どんなSegTreeを構築するか(デフォルトはRMQ)
    ll calc(ll vl, ll vr) {
        return vl + vr;
    }

    //k番目の値(0-indexed)をaに変更
    void update(int k, int a) {
        k += n - 1;
        dat[k] = a;
        //登りながら更新
        while (k > 0) {
            k = (k - 1) / 2;
//            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
            dat[k] = calc(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    //[a,b)の最小値を求める
    //kは接点の番号,l,rはその接点が[l,r)に対応づいていることを表す。
    //したがって、外からはquery(a,b,0,0,n)として呼ぶ。
    ll query(int a, int b, int k, int l, int r) {
        //[a,b)と[l,r)が交差しなければINITIAL_DAT
        if (r <= a || b <= l) return INITIAL_DAT;

        //[a,b)が[l,r)が交差しなければ、INT_MAX
        if (a <= l && r <= b) return dat[k];
        else {
            //そうでなければ、2つの子に対する処理,デフォルトは最小値
            ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return calc(vl, vr);
        }
    }

    //[a,b)の最小値を求める
    ll find(int a, int b) {
        return query(a, b, 0, 0, n);
    }
};

class Combination {

public:
    vector<ll> fact;

    Combination(int max_n) {
        //1 ~ n!までの階乗modを求める
        int n = max_n;
        vector<ll> fact(n + 1);
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        this->fact = fact;
    }

    template<typename T>
    //templateをつかってみｔか
    ll pow(T x, int y) {
        if (y == 0) return 1;
        if (y == 1) return x;
        if (y == 2) return (x * x) % MOD;
//        if (y % 2 == 1) return pow(x, y / 2) * pow(x, y / 2) % MOD;
        if (y % 2 == 1) return pow(pow(x, y / 2), 2) * x % MOD;
//        return pow(x, y / 2) * pow(x, y / 2) % MOD;
        return pow(pow(x, y / 2), 2) % MOD;
    }

    ll nCk(int n, int k) {
//        return (fact[n] * pow(fact[n-k],MOD-2) * pow(fact[k],MOD-2)) % MOD;
        return (((fact[n] * pow(fact[n - k], MOD - 2)) % MOD) * pow(fact[k], MOD - 2)) % MOD;
    }

    /**
     * x ^ -1を求める
     */
    template<typename T>
    ll inv(T x) {
        return pow(x, MOD - 2);
    }
};

class Solve {
public:
    int N;
    vector<int> x, y;


    void solve() {
        cin >> N;
        for (int i = 0; i < N; ++i) {
            int xx, yy;
            cin >> xx >> yy;
            x.push_back(xx);
            y.push_back(yy);
        }

        vector<int> xs = x, ys = y;
        sort(all(xs));
        sort(all(ys));

        vector<int> X, Y;
        for (int i = 0; i < N; ++i) {
            X.push_back(lower_bound(all(xs), x[i]) - xs.begin());
            Y.push_back(lower_bound(all(ys), y[i]) - ys.begin());
        }

        vector<int> lu(N), ld(N), rd(N), ru(N);

        SegTree lr(N), rl(N);

        // lr, du
        for (int i = 0; i < N; ++i) {
            lu[i] = lr.find(Y[i], N);
            ld[i] = lr.find(0, Y[i]);
            lr.update(Y[i], 1);
        }

        // rl, ud
        for (int i = N - 1; i >= 0; --i) {
            ru[i] = rl.find(Y[i], N);
            rd[i] = rl.find(0, Y[i]);
            rl.update(Y[i], 1);
        }

        ll ans = 0;
        Combination cmb(10);
        for (int i = 0; i < N; ++i) {
            ll tmp = cmb.pow(2, N - 1) % MOD;
            tmp += ((cmb.pow(2, lu[i]) - 1) * (cmb.pow(2, rd[i]) - 1) % MOD) * (cmb.pow(2, ld[i] + ru[i])) % MOD;
            tmp %= MOD;


            tmp += ((cmb.pow(2, ru[i]) - 1) * (cmb.pow(2, ld[i]) - 1) % MOD) * (cmb.pow(2, rd[i] + lu[i])) % MOD;
            tmp %= MOD;

            tmp -= ((cmb.pow(2, ru[i]) - 1) * (cmb.pow(2, ld[i]) - 1) % MOD) *
                   ((cmb.pow(2, lu[i]) - 1) * (cmb.pow(2, rd[i]) - 1) % MOD) % MOD;

            tmp %= MOD;
            if (tmp < 0) tmp += MOD;

            ans += tmp;
            ans %= MOD;
        }
        cout << ans << endl;


    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

