		pts[i].first = xm[pts[i].first];
		pts[i].second = ym[pts[i].second];
	}
	sort(pts, pts+n);
	int ans = 0;
	for(int i=0; i<n; i++) {
		ans += bin_pow(2, n);
		int left = pts[i].first;
		int right = n-pts[i].first-1;
		int lower = pts[i].second;
