		int upper_right = upper - upper_left;
		ans -= bin_pow(2, left) + bin_pow(2, right) + bin_pow(2, lower) + bin_pow(2, upper);
		ans += bin_pow(2, upper_left) + bin_pow(2, upper_right) + bin_pow(2, lower_left) + bin_pow(2, lower_right);
		ans--;
		while(ans<0)ans+=mod;
		ans %= mod;
		updt(1, 0, n-1, pts[i].second);
	}
	cout << ans;
	return 0;
}

