int mul(int a,int b,int c,int d){
    ll r=a;
    r=(r*b)%MOD;
    r=(r*c)%MOD;
    r=(r*d)%MOD;
    return r;
}
int calc(int a,int b,int c,int d){
//    printf("calc %d %d %d %d\n",a,b,c,d);
    int ret;
    ret=p(n-1);
    ret=(ret+mul(p(b),p(d),p(a)-1,p(c)-1))%MOD;
    ret=(ret+mul(p(a),p(c),p(b)-1,p(d)-1))%MOD;
    ret=(ret-mul(p(a)-1,p(b)-1,p(c)-1,p(d)-1)+MOD)%MOD;
    //printf("ret=%d\n",ret);
    return ret;
}

