class BIT {
  int n;
  vector<int> v;
public:
  BIT(int n) : n(n), v(n + 1) {}
  void add(int i) {
    for (++i; i <= n; i += i & -i) {
      ++v[i];
    }
  }
  int get(int r) {
    int sum = 0;
    for (; r > 0; r -= r & -r) {
      sum += v[r];
    }
    return sum;
  }
};

const long mod = 998244353;
struct Point {
  int x;
  int y;
  bool operator<(const Point& p) const {
    return x < p.x || x == p.x && y < p.y;
  }
};

int n;
Point ps[200000];
long bin[200001];

long corner() {
  BIT bit(n);
  sort(ps, ps + n);

  long sum = 0;
  for (int i = 0; i < n; ++i) {
    int j = ps[i].y;
    int cnt = bit.get(j);
    sum = (sum + bin[cnt]) % mod;
    bit.add(j);
  }
  return sum;
}

void compress() {
  map<int, int> mx;
  map<int, int> my;
  for (int i = 0; i < n; ++i) {
    int s = mx.size();
    int t = my.size();
    mx[ps[i].x];
    my[ps[i].y];
  }

  int cnt = 0;
  for (auto&& p : mx) p.second = cnt++;
  cnt = 0;
  for (auto&& p : my) p.second = cnt++;

  for (int i = 0; i < n; ++i) {
    ps[i].x = mx[ps[i].x];
    ps[i].y = my[ps[i].y];
  }
}

void pre() {
  bin[0] = 1;
  for (int i = 0; i < n; ++i) {
    bin[i + 1] = bin[i] * 2 % mod; 
  }
}

