    Int b2 = pow2(b) - 1;
    Int c2 = pow2(c) - 1;
    Int d2 = pow2(d) - 1;
    Int sum = pow2(N-1)-1 + pow2(N-1);
    sum = add(sum, -a2);
    sum = add(sum, -b2);
    sum = add(sum, -c2);
    sum = add(sum, -d2);
    sum = add(sum, -a2*b2);
    sum = add(sum, -b2*c2);
    sum = add(sum, -c2*d2);
    sum = add(sum, -d2*a2);
    ans = add(ans, sum);
  }
  cout<<ans<<endl;

  return 0;
}

