//約数の列挙O(√n)
vector<ll> divisor(ll n){
    vector<ll> res(0);
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}


//Range Sum Query
const ll N_ = (1 << 20);
ll seg[2*N_-1];

void init_seg(){
  rep(i, 2*N_-1) seg[i] = 0;
}

void add(ll k, ll x){
  k += N_-1;
  seg[k] += x;
  while(k > 0){
    k = (k-1)/2;
    seg[k] = seg[2*k+1] + seg[2*k+2];
  }
}

ll get_sum(ll x, ll y, ll k = 0, ll left = 0, ll right = N_){
  if(right <= x || y <= left) return 0;
  if(x <= left && right <= y) return seg[k];
  ll mid = (left + right) / 2;
  ll l = get_sum(x, y, 2*k+1, left, mid);
  ll r = get_sum(x, y, 2*k+2, mid, right);
  return l + r;
}

vector<pair<ll, ll>> compress(vector<pair<ll, ll>> xy){
  ll N = xy.size();
  vector<ll> xs, ys;
  rep(i, N){
    xs.pb(xy[i].f);
    ys.pb(xy[i].s);
  }
  sort(xs.begin(), xs.end());
  sort(ys.begin(), ys.end());
  rep(i, N){
    xy[i].f = lower_bound(xs.begin(), xs.end(), xy[i].f) - xs.begin();
    xy[i].s = lower_bound(ys.begin(), ys.end(), xy[i].s) - ys.begin();
  }
  return xy;
}

ll N;
vector<pair<ll, ll>> xy;
void solve(){
  cin >> N;
  xy.resize(N);
  rep(i, N) cin >> xy[i].f >> xy[i].s;
  xy = compress(xy);
  sort(xy.begin(), xy.end());
  vector<ll> leftdown(N), leftup(N), rightdown(N), rightup(N);
  rep(i, N){
    leftdown[i] = get_sum(0, xy[i].s);
    leftup[i] = get_sum(xy[i].s, 200010);
    add(xy[i].s, 1);
  }
  init_seg();
  revrep(i, N){
    rightdown[i] = get_sum(0, xy[i].s);
    rightup[i] = get_sum(xy[i].s, 200010);
    add(xy[i].s, 1);
  }

  mint pow2[200010];
  rep(i, 200010){
    if(i == 0) pow2[i] = 1;
    else pow2[i] = pow2[i-1] * 2;
  }


  /*
  1        5

      2

  3        4
  */
  mint ans = 0;
  rep(i, N){
    ll ld = leftdown[i], lu = leftup[i], rd = rightdown[i], ru = rightup[i];
    ans += pow2[N-1];
    ans += (pow2[ld] - 1) * (pow2[lu] - 1) * (pow2[rd] - 1) * (pow2[ru] - 1);
    ans += (pow2[ld] - 1) * (pow2[lu] - 1) * (pow2[rd] - 1);
    ans += (pow2[ld] - 1) * (pow2[lu] - 1) * (pow2[ru] - 1);
    ans += (pow2[ld] - 1) * (pow2[rd] - 1) * (pow2[ru] - 1);
    ans += (pow2[lu] - 1) * (pow2[rd] - 1) * (pow2[ru] - 1);
    ans += (pow2[ld] - 1) * (pow2[ru] - 1);
    ans += (pow2[lu] - 1) * (pow2[rd] - 1);
  }
  ans.get();
}

