   xs.erase(unique(xs.begin(), xs.end()), xs.end());
   sort(ys.begin(), ys.end());
   ys.erase(unique(ys.begin(), ys.end()), ys.end());

   for (int i = 0; i < N; i++) {
      x[i] = find(xs.begin(), xs.end(), x[i]) - xs.begin();
      x[i]++;
      y[i] = find(ys.begin(), ys.end(), y[i]) - ys.begin();
      y[i]++;
   }

   BIT2<int> bit2;
   bit2.init(N + 1, N + 1, 0);

   for (int i = 0; i < N; i++) {
      bit2.add(x[i], y[i], 1);
   }

   ll ans = 0;
   for (int i = 0; i < N; i++) {
      int LU = bit2.sum2(1, x[i] - 1, y[i] + 1, N);
      int RU = bit2.sum2(x[i] + 1, N, y[i] + 1, N);
      int LD = bit2.sum(x[i] - 1, y[i] - 1);
