      mul(tmp, llmodpow(2, RU));
      mul(tmp, llmodpow(2, LD));
      mul(tmp, llmodpow(2, RD));
      add(ans, tmp);
      tmp = llmodpow(2, LU) - 1;
      mul(tmp, llmodpow(2, RD) - 1);
      mul(tmp, llmodpow(2, RU));
      mul(tmp, llmodpow(2, LD));
      add(ans, tmp);
      tmp = llmodpow(2, RU) - 1;
      mul(tmp, llmodpow(2, LD) - 1);
      mul(tmp, llmodpow(2, LU));
      mul(tmp, llmodpow(2, RD));
      add(ans, tmp);
      tmp = llmodpow(2, LU) - 1;
      mul(tmp, llmodpow(2, RU) - 1);
      mul(tmp, llmodpow(2, LD) - 1);
      mul(tmp, llmodpow(2, RD) - 1);
      sub(ans, tmp);
   }
   ans %= MOD;
   if (ans < 0) ans += MOD; 
