    }
    BIT bitl(N+1),bitr(N+1);
    vector<pii> ps(N);
    for(int i = 0; i < N;i++){
        ps[i] = {x[i],y[i]};
        bitr.add(y[i],1);
    }
    sort(ps.begin(),ps.end());

    vector<ll> pow2(N+1);
    pow2[0] = 1;
    for(int i = 1; i <= N;i++){
        pow2[i] = pow2[i-1] * 2 % MOD;
    }


    for(auto p:ps){
        int x,y; tie(x,y) = p;

        bitr.add(y,-1);

        for(int b = 0; b < (1<<4);b++){
            bool twice = ((b&5)==5)||((b&10)==10);

            ll val = 1;

            for(int i = 0; i < 4;i++){
                ll cnt = 1;
                if((b>>i)&1){
                    switch (i) {
                        case 0:
                            cnt = bitr.sum(y+1,N);
                            break;
                        case 1:
                            cnt = bitl.sum(y+1,N);
                            break;
                        case 2:
                            cnt = bitl.sum(y-1);
                            break;
                        case 3:
                            cnt = bitr.sum(y-1);
                            break;
                        default:
                            break;
                    }
                }
                (val *= (pow2[cnt]-1))%=MOD;
            }
            if(twice) (val *= 2)%=MOD;
            (res += val)%=MOD;
        }        
        bitl.add(y,1);
    }
    return res;
}
