        rect(x[i] + 1, 1e18, -1e18, y[i], i, 0, 1);
        rect(-1e18, x[i], y[i] + 1, 1e18, i, 1, 0);
        rect(x[i] + 1, 1e18, y[i] + 1, 1e18, i, 0, 0);
    }
    sort(qs.begin(), qs.end());


    for (auto q : qs) {
        if (q.t == 1) {
            dpc[q.id][q.p][q.q] += q.coef * bit.sum(cmp.lb_index(q.y1), cmp.lb_index(q.y2));
        } else {
            bit.add(cmp.lb_index(q.y1), 1);
        }
    }

    for (int i = 0; i < x.size(); i++) {
