//        cout << dpc[i][1][1] << " " << dp[1][1] << endl;
//        cout << endl;

        ans += (mInt(2) ^ (dpc[i][0][0] + dpc[i][0][1])) - 1;
        ans += (mInt(2) ^ (dpc[i][0][1] + dpc[i][1][1])) - 1;
        ans += (mInt(2) ^ (dpc[i][1][1] + dpc[i][1][0])) - 1;
        ans += (mInt(2) ^ (dpc[i][1][0] + dpc[i][0][0])) - 1;

        ans -= (mInt(2) ^ (dpc[i][1][0])) - 1;
        ans -= (mInt(2) ^ (dpc[i][0][1])) - 1;
        ans -= (mInt(2) ^ (dpc[i][1][1])) - 1;
        ans -= (mInt(2) ^ (dpc[i][0][0])) - 1;
    }


    mInt overall = 0;
    for (int i = 0; i < N; i++) {
        overall += ((mInt(2) ^ N) - 1);
    }
    overall -= ans;
