  vector<tuple<ll,ll>> vt;
  for (ll i : range(n)) {
    ll x, y;
    cin>>x>>y;
    vt.emplace_back(x, y);
    vy.push_back(y);
  }
  sort(begin(vt), end(vt));
  sort(begin(vy), end(vy));
  BIT bit;
  using modint = ModIntMR<mod>;
  modint sum(0);
  for (ll i : range(n)) {
    ll x, y;
    tie(x, y) = vt[i];
    ll under = lower_bound(begin(vy), end(vy), y) - begin(vy);
    ll a = bit.query(under);
    ll b = under - a;
    ll d = i - a;
    ll c = n-1 - a - b - d;
    sum += modint(2) ^ n;
    sum -= modint(2) ^ (a+b);
    sum -= modint(2) ^ (b+c);
    sum -= modint(2) ^ (c+d);
    sum -= modint(2) ^ (d+a);
    sum += modint(2) ^ a;
    sum += modint(2) ^ b;
    sum += modint(2) ^ c;
    sum += modint(2) ^ d;
    sum -= modint(1);
    bit.update(under, 1);
  }
  cout << static_cast<ll>(sum) << endl;
