class BIT
{
public:
	vector<ll> bit;
	int M;

	BIT(int M) :
		bit(vector<ll>(M + 1, 0)), M(M) {}

	int sum(ll i) {
		if (!i) return 0;
		return bit[i] + sum(i - (i&-i));
	}

	void add(ll i, ll x) {
		if (i > M) return;
		bit[i] += x;
		add(i + (i&-i), x);
	}
};

