const int mod = 998244353;

int main(){
    int n;
    cin >> n;
    vector<pii> vp;
    vector<int> y;
    for(int i = 0; i < n; i++){
        int a, b;
        cin >> a >> b;
        vp.push_back({a,b});
        y.push_back(b);
    }
    sort(y.begin(), y.end());
    BIT bit(n);
    for(int i = 1; i <= n; i++) bit.add(i, 1);
    sort(vp.begin(), vp.end());
    vector<ll> fact(n+1, 2);    fact[0] = 0;
    for(int i = 2; i <= n; i++) fact[i] = fact[i-1]*2%mod;
    ll ans = 0;
    for(int i = 0; i < n; i++){
        int left = i;
        int right = n-1-left;
        int down = lower_bound(y.begin(),y.end(),vp[i].second)-y.begin();
        int up = n-1-down;
        bit.add(down+1, -1);
        (ans += fact[n-1]) %= mod;   // select vp[i]
        int scatt[2][2];
        scatt[1][1] = bit.sum(down+1);
        scatt[0][1] = bit.sum(n)-bit.sum(down+1);
        scatt[1][0] = down-scatt[1][1];
        scatt[0][0] = up-scatt[0][1];
        ll add = 0;
        bool all = true;
        for(int j = 0; j < 2; j++){
            for(int k = 0; k < 2; k++){
                all &= scatt[j][k]>0;
                bool valid = true;
                ll tmpadd = 1;
                for(int l = 0; l < 2; l++){
                    for(int m = 0; m < 2; m++){
                        if(l==j&&k==m)  continue;
                        valid &= scatt[l][m]>0;
                        tmpadd *= fact[scatt[l][m]]-1;
                        tmpadd %= mod;
                    }
                }
                if(valid)   (add += tmpadd) %= mod;
            }
        }
        if(scatt[0][0] > 0 && scatt[1][1])  (add += (fact[scatt[0][0]]-1)*(fact[scatt[1][1]]-1)%mod) %= mod;
        if(scatt[1][0] > 0 && scatt[0][1])  (add += (fact[scatt[1][0]]-1)*(fact[scatt[0][1]]-1)%mod) %= mod;
        if(all){
            ll tmp = 1;
            for(int j = 0; j < 2; j++){
                for(int k = 0; k < 2; k++){
                    (tmp *= fact[scatt[j][k]]-1) %= mod;
                }
            }
            (add += tmp) %= mod;
        }
        (ans += add) %= mod;
    }
    cout << ans << endl;
    return 0;
}

