template <typename T>
class BIT {
    using u32 = uint_fast32_t;
    // bit : 1-indexed,各要素の値を持つ
    vector<T> bit;
    u32 n;

   public:
    BIT(u32 N) {
        n = N;
        bit.assign(N + 1, 0);
    }

    // i番目の値にxを加える
    void add(u32 i, T x) {
        while (i <= n) {
            bit[i] += x;
            // i&-i : iの最右1bit
            i += i & -i;
        }
    }

    // a1～aiの総和を返す
    T sum(u32 i) {
        T s = 0;
        while (i > 0) {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }

    // ai～ajの総和を返す
    T range_sum(u32 i, u32 j) { return sum(j) - sum(i - 1); }
};

template <typename T, typename U>
T pow(T x, U n, T e = 1) {
    T res = e;
    while (n > 0) {
        if (n & 1) res *= x;
        x *= x;
        n >>= 1;
    }
    return res;
}

