int main() {
    int N;
    cin >> N;
    vector<Point> v(N);
    unordered_map<int, int> mp;
    for (int i = 0; i < N; i++) {
        cin >> v[i].x >> v[i].y;
    }
    sort(v.begin(), v.end(), [](Point &l, Point &r) { return l.y < r.y; });
    for (int i = 0; i < N; i++) mp[v[i].y] = i + 1;
    sort(v.begin(), v.end(), [](Point &l, Point &r) { return l.x < r.x; });

    BIT<int> ltree(N), rtree(N);
    for (int i = 0; i < N; i++) rtree.add(i + 1, 1);

    mint ans = 0;
    auto p2 = [](uint_fast32_t n) { return pow<mint, uint_fast32_t>(2, n); };
    auto g = [&](uint_fast32_t n) { return (n > 0 ? p2(n) - 1 : 0); };
    for (int i = 0; i < N; i++) {
        int s1, s2, s3, s4;
        int j = mp[v[i].y];

        ltree.add(j, 1);
        rtree.add(j, -1);

        s1 = j < N ? ltree.range_sum(j + 1, N) : 0;
        s2 = ltree.sum(j - 1);
        s3 = j < N ? rtree.range_sum(j + 1, N) : 0;
        s4 = rtree.sum(j - 1);
        ans += g(s2) * g(s3) * p2(s1 + s4) + g(s1) * g(s4) * p2(s2 + s3) -
               g(s1) * g(s2) * g(s3) * g(s4) + p2(N - 1);
    }
    cout << ans << endl;
    return 0;
}

