template<int mod> struct mint {
    long long x;
    mint(long long x = 0) : x(x % mod) {
    }

    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) {
            x -= mod;
        }
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += mod-a.x) >= mod) {
            x -= mod;
        }
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(long long t) const {
        if (!t) {
            return 1;
        }
        mint a = pow(t>>1);
        a *= a;
        if (t&1) {
            a *= *this;
        }
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod-2);
    }
    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
};

template <class T=long long> class CoordinateCompression {
public:
    int no = 0;
    std::unordered_map<T, int> zip;    // 元の値 -> 圧縮した値
    std::unordered_map<int, T> unzip;  // 圧縮した値 -> 元の値

    CoordinateCompression() {
    }

    CoordinateCompression(const std::vector<T> &v) {
        this->build(v);
    }

    CoordinateCompression(const std::set<T> &v) {
        this->build(v);
    }

    void build(const std::vector<T> &v) {
        std::set<T> s(v.begin(), v.end());
        this->build(s);
    }

    void build(const std::set<T> &s) {
        for (auto x : s) {
            this->zip[x] = this->no;
            this->unzip[this->no] = x;
            this->no++;
        }
    }
};

template <class T=long long> class FenwickTree {
public:
    const int n;
    std::vector<T> v;

    FenwickTree(int n) : n(n) {
        this->v.assign(n + 1, 0);
    }

    T access(int i) {
        return this->sum(i, i + 1);
    }

    // sum(v[0, i))
    T sum(int i) {
        assert(0 <= i && i <= this->n);

        T s = 0;
        i -= 1;
        while (i >= 0) {
            s += this->v[i];
            i = (i & (i + 1)) - 1;
        }
        return s;
    }

    // sum(v[left, right))
    T sum(int left, int right) {
        assert(left <= right);
        return this->sum(right) - this->sum(left);
    }

    // v[i] += x(0-origin)
    void add(int i, long long x) {
        assert(i < this->n);

        while (i < this->n) {
            this->v.at(i) += x;
            i |= i + 1;
        }
    }
};

// 各点について，左上，左下，右上，右下の点の数を求める
std::vector<tuple<int, int, int, int>> line_sweep(const vector<int> &y, const vector<int> &x) {
    const int N = y.size();
    vector<tuple<int, int, int, int>> ans(N);

    // 左上，左下
    {
        FenwickTree<LL> ft(N);
        for (int i = 0; i < N; ++i) {
            const auto num = ft.sum(y[i]);
            std::get<0>(ans[i]) = i - num;
            std::get<1>(ans[i]) = num;
            ft.add(y[i], 1);
        }
    }

    // 右上，右下
    {
        FenwickTree<LL> ft(N);
        for (int i = N - 1; i >= 0; --i) {
            const auto num = ft.sum(y[i]);
            std::get<2>(ans[i]) = (N - i - 1) - num;
            std::get<3>(ans[i]) = num;
            ft.add(y[i], 1);
        }
    }

    return ans;
}

const LL mod = 998244353;

// 点を含む部分集合の個数
mint<mod> f(int a, int b, int c, int d, int N) {
    mint<mod> ans = 0;

    vector<int> num = {a, b, c, d};
    FOR(b, 0, 1 << 4) {

        mint<mod> count = 1;
        bool up = false, down = false, left = false, right = false;
        FOR(i, 0, 4) {
            if (IS_BIT_ON(b, i)) {
                count *= (mint<mod>(2).pow(num[i]) - 1);
                if (i == 0) { up = left = true; }   // 左上
                if (i == 1) { down = left = true; } // 左下
                if (i == 2) { up = right = true; }  // 右上
                if (i == 3) { down = right = true; }// 右下
            }
        }
        if (up and down and left and right) {
            ans += count;
        }
    }

    ans += mint<mod>(2).pow(N - 1);
    return ans;
}

