static const int mod = 99824435;
typedef long long ll;

struct mint{
  ll x;
  mint(ll x=0):x(x%mod){}
  mint& operator+=(const mint a){
    if ((x += a.x) >= mod) {
      x -= mod;
    }
    return *this;
  }

  mint& operator-=(const mint a) {
    if ((x += mod - a.x) >= mod) {
      x -= mod;
    }
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const {
    if (!t) { return 1;}
    mint a = pow(t>>1);
    a *= a;
    if (t&1) {a *= *this; }
    return a;
  }
  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a){
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

struct Point {
  int x, y;
};

template<typename T>

struct BIT {
  int n;
  vector<T> d;
  BIT(int n=0):n(n), d(n+1){}
  void add(int i, T x=1) {
    for (i++; i <= n; i+=i&-i) {
      d[i]+=x;
    }
  }
  T sum(int i){
    T x = 0;
    for (i++; i; i -= i&-i) {
      x += d[i];
    }
    return x;
  }
};

bool cmp(const Point &a, const Point &b) {
  if (a.x == b.x) {
    return a.y > b.y;
  }
  return a.x > b.x;
}
mint f(int a, int b, int c, int d){
  mint res = 0;
  vector<int> num = {a, b, c, d};
  vector<mint> o(4), ox(4);
  for (int i = 0; i < 4; i++) {
    ox[i] = mint(2).pow(num[i]);
    o[i] = ox[i] - 1;
  }

  res += ox[0]*o[1]*o[2]*ox[3];
  res += o[0]*ox[1]*ox[2]*o[3];
  res -= o[0]*o[1]*o[2]*o[3];
  res += ox[0]*ox[1]*ox[2]*ox[3];

  return res;
}

int main() {
  int n;
  cin >> n;
  vector<Point> p(n);

  for (int i = 0; i < n; i++) {
    cin >> p[i].x >> p[i].y;
  }

  {//compress x
    map<int, int> mp;
    for (int i = 0; i < n; i++) {
      mp[p[i].x] = 0;
    }
    int j = 0;
    for (auto&& x : mp) {
      x.second = j++;
    }
    for (int i = 0; i < n; i++) {
      p[i].x = mp[p[i].x];
    }
  }

  {//compress y
    map<int, int> mp;
    for (int i = 0; i < n; i++) {
      mp[p[i].y] = 0;
    }
    int j = 0;
    for (auto&& x : mp) {
      x.second = j++;
    }
    for (int i = 0; i < n; i++) {
      p[i].y = mp[p[i].y];
    }
  }

  sort(p.begin(), p.end(), cmp);

  vector<int> a(n);
  vector<int> b(n);
  vector<int> c(n);
  vector<int> d(n);

  for (int _ = 0; _<2; _++) {
    {//calc a, b
      BIT<int> bit(n);
      for (int i=0;i<n;i++){
        a[i] = bit.sum(p[i].y);
        b[i] = i - a[i];
        bit.add(p[i].y);
      }
    }
    reverse(p.begin(), p.end());
    swap(a, c);
    swap(b, d);
    reverse(a.begin(), a.end());
    reverse(b.begin(), b.end());
    reverse(c.begin(), c.end());
    reverse(d.begin(), d.end());
  }
  mint ans = 0;
  for (int i = 0; i < n; i++) {
    ans += f(a[i], b[i], c[i], d[i]);
  }
  cout << ans.x << endl;
  return 0;
}

