vector<pair<ll,ll>> backet[DV][DV];

void solve()
{
	ll N;
	cin >> N;
	auto xy = cinv2(N);

	std::sort(xy.begin(), xy.end());
	REP(i, N) xy[i].first = i;
	std::sort(xy.begin(), xy.end(),
		[](auto &a, auto &b) {return a.second < b.second; }
	);
	REP(i, N) xy[i].second = i;

	ll B = N/DV+1;
	REP(i, N){
		ll x = xy[i].first;
		ll y = xy[i].second;
		backet[x/B][y/B].emplace_back(x, y);
	}

	vvll ac(DV, vll(DV) );
	ll zero;
	auto Ac = [&](ll x, ll y) -> ll &{
		if (x<0 || y<0) return zero;
		else return ac[x][y];
	};

	auto RectSum = [&](ll sx, ll sy, ll ex, ll ey){
		return Ac(ex, ey)-Ac(ex, sy-1)-Ac(sx-1, ey)+Ac(sx-1, sy-1);
	};

	REP(xx, DV) REP(yy, DV){
		Ac(xx, yy) = Ac(xx-1, yy) + Ac(xx, yy-1) - Ac(xx-1, yy-1)
			+ (ll)backet[xx][yy].size();
	}

	mll two = 2;
	mll I = two.pow(N) - 1;

	mll ans=0;
	REP(i, N){
		ll x = xy[i].first;
		ll y = xy[i].second;
		ll xx = x/B;
		ll yy = y/B;
		ll A, B, C, D;
		A = RectSum(xx+1,yy+1,  DV-1,  DV-1);
		B = RectSum(xx+1,   0,  DV-1,  yy-1);
		C = RectSum(0,   yy+1,  xx-1,  DV-1);
		D = RectSum(0,      0,  xx-1,  yy-1);

		REP(xxx, DV){
			ll yyy = yy;
			if (xxx == xx) continue;
			EACH(s, backet[xxx][yyy]){
				ll xxxx = s.first;
				ll yyyy = s.second;
				if (xxxx<x && yyyy<y) D++;
				else if (xxxx>x &&yyyy<y) B++;
				else if (xxxx<x && yyyy>y) C++;
				else if (xxxx>x &&yyyy>y) A++;
				else continue;
			}
		}
		REP(yyy, DV){
			ll xxx = xx;
			EACH(s, backet[xxx][yyy]){
				ll xxxx = s.first;
				ll yyyy = s.second;
				if (xxxx<x && yyyy<y) D++;
				else if (xxxx>x &&yyyy<y) B++;
				else if (xxxx<x && yyyy>y) C++;
				else if (xxxx>x &&yyyy>y) A++;
				else continue;
			}
		}

#if 0
			A=B=C=D=0;
			REP(xxx, 500) REP(yyy, 500){
			if      (xxx<xx && yyy<yy) D += (ll)backet[xxx][yyy].size();
			else if (xxx>xx && yyy<yy) B += (ll)backet[xxx][yyy].size();
			else if (xxx<xx && yyy>yy) C += (ll)backet[xxx][yyy].size();
			else if (xxx>xx && yyy>yy) A += (ll)backet[xxx][yyy].size();
			else{
				EACH(s, backet[xxx][yyy]){
					ll xxxx = s.first;
					ll yyyy = s.second;
					if      (xxxx<x && yyyy<y) D++;
					else if (xxxx>x && yyyy<y) B++;
					else if (xxxx<x && yyyy>y) C++;
					else if (xxxx>x && yyyy>y) A++;
					else continue;
				}
			}
		}
#endif
		mll II = two.pow(A+C) + two.pow(C+D) + two.pow(B+D) + two.pow(A+B)
			- two.pow(A) - two.pow(B) - two.pow(C) - two.pow(D);

		ans += (I-II);
	}
	cout << ans << '\n';
}

