        inter.emplace_back(x, y);
        y_gather[y].emplace_back(x);
    }
    for (auto& e: y_gather) sort(e.begin(), e.end());

    BinaryIndexedTree<int> bit_less(MX), bit_more(MX);
    for (auto& e: inter) bit_more.add(e.first, 1);

    ll res = 0;

    for (auto& ey: y_gather) {
        for (auto& x: ey) bit_more.add(x, -1);
        int t = ey.size();
        int l = 0, r = t - 1;
        for (auto& x: ey) {
            int A = bit_more.sum(0, x);
            int B = bit_more.sum(x + 1, MX);
            int C = bit_less.sum(0, x);
            int D = bit_less.sum(x + 1, MX);
            int AC = l;
            int BD = r;
            int AB = bit_more.sum(x, x + 1);
            int CD = bit_less.sum(x, x + 1);

            ll tmp = twos[N];

            tmp -= twos[A];
            tmp -= twos[B];
            tmp -= twos[C];
            tmp -= twos[D];
            tmp -= twos[AB];
            tmp -= twos[AC];
            tmp -= twos[BD];
            tmp -= twos[CD];

            tmp -= twos[A] * twos[B];
            tmp -= twos[B] * twos[D];
            tmp -= twos[D] * twos[C];
            tmp -= twos[C] * twos[A];

            tmp -= twos[A] * twos[AB];
            tmp -= twos[AB] * twos[B];
            tmp -= twos[B] * twos[BD];
            tmp -= twos[BD] * twos[D];
            tmp -= twos[D] * twos[CD];
            tmp -= twos[CD] * twos[C];
            tmp -= twos[C] * twos[AC];
            tmp -= twos[AC] * twos[C];

            tmp %= MOD;
            tmp += MOD;

            (res += tmp) %= MOD;

            ++l, --r;
        }
        for (auto& x: ey) bit_less.add(x, 1);
    }

    cout << res << endl;

}

