        while(N_ <= N)N_ <<= 1;
    }
    vector<unsigned long> perm(N);
    {
        vector<pair<long, long>> p(N), q(N);
        for(auto& i : p)in.scan(i.first, i.second);
        rsort(p.begin(), p.end());
        for(unsigned long i = 0; i < N; ++i)p[i] = {p[i].second, i};
        rsort(p.begin(), p.end());
        transform(p.cbegin(), p.cend(), perm.begin(), [](auto i){return i.second;});
    }

    constexpr unsigned long MOD = 998244353;
    vector<unsigned long> binary(N + 1), index(N + 1);
    unsigned long n = binary[0] = 1;
    generate(binary.begin() + 1, binary.end(), [&n](){if(n >= MOD)n -= MOD;return n <<= 1;});
    for(unsigned long i = 0; i < N; ++i)index[i] = i + N_ >> __builtin_ffsl(i + 1);

    vector<unsigned long> fenwick_tree(N_);
    auto que = [&fenwick_tree](unsigned long i){
        unsigned long s{fenwick_tree[i]}, j{0};
        while(i){
            if(j)s += fenwick_tree[i];
            else++fenwick_tree[i];
            j = i & 1;
            i >>= 1;
        }
        return s;
    };

    vector<unsigned long> coef(N + 1);
    coef[N] = N + MOD - 4;
    for(unsigned long i = 0; i != N; ++i){
        auto q = que(index[perm[i]]);
        ++coef[q];
        ++coef[i - q];
        ++coef[perm[i] - q];
        ++coef[N - i - perm[i] + q - 1];
    }

    cout << inner_product(binary.begin(), binary.end(), coef.begin(), 4 + MOD - N) % MOD << endl;
    return 0;
}

