  const auto add = [](mint &a, const mint b) { a += b - static_cast<mint>(1); };
  const auto sub = [](mint &a, const mint b) { a -= b - static_cast<mint>(1); };

  const usize n = scan<usize>();
  struct point_type {
    i32 x, y;
  };
  std::vector<point_type> s(n);
  std::vector<i32> ys(n);
  for (auto &p : s) {
    std::cin >> p.x >> p.y;
  }
  mint all = static_cast<mint>(1);
  for (const auto i : rep(0_z, n)) {
    ys[i] = s[i].y;
    all *= static_cast<mint>(2);
  }
  all -= static_cast<mint>(1);
  std::sort(ys.begin(), ys.end());
  const auto yi = [&ys](const i32 y) -> usize {
    return std::lower_bound(ys.cbegin(), ys.cend(), y) - ys.cbegin();
  };

  mint ans;

  {
    segment_tree<multi_monoid<mint>> seg(n);
    std::vector<point_type> ps = s;
    std::sort(ps.begin(), ps.end(), [](auto l, auto r) { return l.x < r.x; });
    for (const auto &p : ps) {
      ans += all;
      sub(ans, seg.fold(0_z, n));
      add(ans, seg.fold(0_z, yi(p.y)));
      add(ans, seg.fold(yi(p.y), n));
      seg.update(yi(p.y), [](auto) { return static_cast<mint>(2); });
    }
  }
  {
    segment_tree<multi_monoid<mint>> seg(n);
    std::vector<point_type> ps = s;
    std::sort(ps.begin(), ps.end(), [](auto l, auto r) { return l.x > r.x; });
    for (const auto &p : ps) {
      sub(ans, seg.fold(0_z, n));
      add(ans, seg.fold(0_z, yi(p.y)));
      add(ans, seg.fold(yi(p.y), n));
      seg.update(yi(p.y), [](auto) { return static_cast<mint>(2); });
    }
  }
  {
    std::vector<point_type> ps = s;
    std::sort(ps.begin(), ps.end(), [](auto l, auto r) { return l.y < r.y; });
    mint sum = static_cast<mint>(1);
    for (const auto &p : ps) {
      sub(ans, sum);
      sum *= static_cast<mint>(2);
    }
  }
  {
    std::vector<point_type> ps = s;
    std::sort(ps.begin(), ps.end(), [](auto l, auto r) { return l.y > r.y; });
    mint sum = static_cast<mint>(1);
    for (const auto &p : ps) {
      sub(ans, sum);
      sum *= static_cast<mint>(2);
    }
  }
  std::cout << ans.value() << std::endl;
}

