lli po(lli a,lli n)
{
    return pp[n];
    if(n==0)
        return 1;
    if(n&1)
        return (a*po(a,n-1))%mod;
    return po(a*a%mod,n/2);
}

void unq(vi &a)
{
    a.pb(-INF);
    a.pb(INF);
    sort(a.begin(),a.end());
    // a.resize(unique(a.begin(),a.end())-a.begin());
}

lli fnd(const vi &a,lli x)
{
    return lower_bound(a.begin(),a.end(),x)-a.begin();
}

lli query(map<lli,lli> &a,lli id,lli l,lli r,lli L,lli R)
{
    if(r<L||R<l)
        return 0;
    if(L<=l&&r<=R)
    {
        auto it=a.find(id);
        // dbg(id,a);
        if(it==a.end())
            return 0;
        return it->Y;
    }
    lli m=(l+r)/2;
    return query(a,2*id,l,m,L,R)+query(a,2*id+1,m+1,r,L,R);
}

lli query(lli id,lli l,lli r,lli L,lli R,lli ly,lli ry)
{
    if(r<L||R<l)
        return 0;
    if(L<=l&&r<=R)
        return query(f[id],1,0,N,ly,ry);
    lli m=(l+r)/2;
    return query(2*id,l,m,L,R,ly,ry)+query(2*id+1,m+1,r,L,R,ly,ry);
}

lli query(lli lx,lli rx,lli ly,lli ry)
{
    return query(1,0,N,lx,rx,ly,ry);
}

void add(map<lli,lli> &a,lli id,lli l,lli r,lli x)
{
    if(r<x||x<l)
        return;
    a[id]++;
    if(l==r)
        return;
    lli m=(l+r)/2;
    add(a,2*id,l,m,x);
    add(a,2*id+1,m+1,r,x);
}

