void read_vector(ll n, vl& v1, vl& v2, ll offset1 = 0, ll offset2 = 0){
    v1.resize(n); v2.resize(n);
    rep(i, n){
        in2(v1[i], v2[i]);
        v1[i] += offset1;
        v2[i] += offset2;
    }
