}

int main() {
	int n = ri();
	std::pair<int, int> a[n];
	for (int i = 0; i < n; i++) a[i].first = ri(), a[i].second = ri();

	std::set<int> s;
	for (int i = 0; i < n; i++) s.insert(a[i].second);
	std::map<int, int> comp;
	int cnt = 0;
	for (auto i : s) comp[i] = cnt++;
	std::sort(a, a + n);

	SegTree forward(cnt), back(cnt);
	for (auto &i : a) back.add(comp[i.second], 1);

	mint res = 0;
	for (auto &i : a) {
		back.add(comp[i.second], -1);

		res -= (mint(2) ^ back.sum(0, back.n));
		res -= (mint(2) ^ forward.sum(0, forward.n));
		res += (mint(2) ^ forward.sum(0, comp[i.second]));
		res += (mint(2) ^ forward.sum(comp[i.second] + 1, forward.n));
		res += (mint(2) ^ back.sum(0, comp[i.second]));
		res += (mint(2) ^ back.sum(comp[i.second] + 1, back.n));

		forward.add(comp[i.second], 1);
	}
	res -= (mint(2) ^ (n + 1)) - 2;
	res += ((mint(2) ^ n) - 1) * n;
	std::cout << res << std::endl;

	return 0;
}

