class BIT
{
public:
	vector<ll> bit;
	int M;

	BIT(int M) :
		bit(vector<ll>(M + 1, 0)), M(M) {}

	int sum(ll i) {
		if (!i) return 0;
		return bit[i] + sum(i - (i&-i));
	}

	void add(ll i, ll x) {
		if (i > M) return;
		bit[i] += x;
		add(i + (i&-i), x);
	}
};

bool comps(pair<ll, ll> x, pair<ll, ll> y) {
	return x.second < y.second;
}

ll c(ll n) {
	if (n == 0) { return 0;}

	ll x = c(n / 2);

	if (n % 2 == 0) {
		return ((x + 1)*(x + 1) - 1) % MOD;
	}

	return ((c(n - 1) + 1) * 2 - 1) % MOD;
}


