template<typename T>
struct BIT {
	int n;
	vector<T> d;
	BIT(int n = 0) : n(n), d(n + 1) {}
	void add(int i, T x = 1) {
		++i;
		while (i <= n) {
			d[i] += x;
			i += i & -i;
		}
	}
	T sum(int i) {
		++i;
		T x = 0;
		while (i > 0) {
			x += d[i];
			i -= i & -i;
		}
		return x;
	}
};

ll f(int a, int b, int c, int d) {
	ll res = 0;
	vector<int> num = {a, b, c, d};
	vector<ll> o(4), ox(4);
	for (int i = 0; i < 4; i++) {
		ox[i] = ((ll) pow(2, num[i])) % mod;
		o[i] = ox[i] - 1;
	}
	res += ((ox[0] % mod) * (o[1] % mod) * (o[2] % mod) * (ox[3] % mod)) % mod;
	res %= mod;
