void upd(int bit[], int n, int x) {
    for (; x <= n; x += x & -x) {
        bit[x]++;
    }
}

int qry(int bit[], int x) {
    int r = 0;
    for (; x; x -= x & -x) {
        r += bit[x];
    }
    return r;
