}

vector< vector<ll> > cnt_brute(vector<P>& v) {
    int n = v.size();
    vector< vector<ll> > cnt(n, vector<ll>(4, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j == i) continue;
            if (v[i].first == v[j].first) {
                if (v[i].second > v[j].second) {
                    cnt[i][0]++;
                    cnt[i][1]++;
                } else {
                    cnt[i][2]++;
                    cnt[i][3]++;
                }
            } else if (v[i].second == v[j].second) {
                if (v[i].first > v[j].first) {
                    cnt[i][0]++;
                    cnt[i][2]++;
                } else {
                    cnt[i][1]++;
                    cnt[i][3]++;
                }
            } else {
                int f1 = (v[i].first < v[j].first);
                int f2 = (v[i].second < v[j].second);
                cnt[i][f1 + f2 * 2]++;
            }
        }
    }
    return cnt;
}

ll calc(ll x) {
    if (x <= 0) return 0;
    return (modpow(2, x) + MOD - 1) % MOD;
}

