        }
    }

    vector< vector<int> > vs;
    vector<ll> left_cnt_y(n, 0), right_cnt_y(n, 0);
    for (auto& p : memo) {
        vs.push_back(p.second);
        ll sz = p.second.size();
        for (int i = 0; i < sz; i++) {
            left_cnt_y[p.second[i]] = i;
            right_cnt_y[p.second[i]] = sz - 1 - i;
        }
    }

    SegmentTree<ll> st(n, 0);
    vector< vector<ll> > cnt(n, vector<ll>(4, 0));
