            cnt[i][j] = calc(cnt[i][j]);
        }

        int mask1 = 2 + 4;
        int mask2 = 1 + 8;
        for (int j = 0; j < (1 << 4); j++) {
            if ((j & mask1) == mask1 || (j & mask2) == mask2) {
                ll hoge = 1;
                for (int k = 0; k < 4; k++) {
                    if (j & (1 << k)) {
                        (hoge *= cnt[i][k]) %= MOD;
                    }
                }
                (ans += hoge) %= MOD;
            }
        }

        (ans += pow2_1) %= MOD;
