		ans=(ans-pre[n-i+1]+2+mod)%mod;
	}
	sort(a+1,a+n+1,Mo);
	for(int i=1;i<=n;i++){
		int p=query(a[i].x);
		ans=(ans+pre[p]-1)%mod;
		ans=(ans+pre[i-p-1]-1)%mod;
		add(a[i].x);
	}
	memset(c,0,sizeof c);
	for(int i=n;i>=1;i--){
		int p=query(a[i].x);
		ans=(ans+pre[p]-1)%mod;
		ans=(ans+pre[n-i-p]-1)%mod;
		add(a[i].x);
	}
	printf("%lld\n",ans);
	return 0;
}

