        ans+=modpow(2,P[0],MOD)-1;
        ans+=modpow(2,P[2],MOD)-1;
        ans-=modpow(2,P[6]+P[7]+P[8],MOD)-1;
        ans+=modpow(2,P[6],MOD)-1;
        ans+=modpow(2,P[8],MOD)-1;
        ans%=MOD;
        if(ans<0) ans+=MOD;
    }
    cout<<ans<<endl;
}

