struct FenwickTree {
  vector<long long> v;
  int n;
  FenwickTree(int n) : n(n), v(n) {}
  void add(int i, long long x) {
    i++;
    while (i <= n) {
      v[i - 1] += x;
      i += i & -i;
    }
  }
  long long get(int i) {
    long long r = 0;
    while (i >= 1) {
      r += v[i - 1];
      i -= i & -i;
    }
    return r;
  }
};

void solve() {
  int n;
  cin >> n;
  vector<pair<int, int>> xy;
  rep(i, n) {
    int x, y;
    cin >> x >> y;
    xy.emplace_back(x, y);
  }
  vi32 lsty;
  rep(i, n) lsty.emplace_back(xy[i].second);
  sort(all(lsty));
  auto convy = [&](int y){
    int i = lower_bound(all(lsty), y) - lsty.begin();
    return i;
  };

  FenwickTree ft1(n), ft2(n);

  struct Coord {
    int lu, ru, ld, rd;
  };
  vector<Coord> coords(n);
  sort(all(xy));

  rep(i, n) {
    int x, y;
    tie(x, y) = xy[i];
    int c = ft1.get(convy(y));
    coords[i].lu = c;
    coords[i].ld = i - c;
    ft1.add(convy(y), 1);
  }
  rrep(i, n) {
    int x, y;
    tie(x, y) = xy[i];
    int c = ft2.get(convy(y));
    coords[i].ru = c;
    coords[i].rd = (n - i - 1) - c;
    ft2.add(convy(y), 1);
  }

  vector<mint> pow2(n + 1);
  pow2[0] = 1;
  rep(i, n) pow2[i + 1] = pow2[i] * 2;

  mint ans = 0;
  rep(i, n) {
    auto c = coords[i];
    mint temp = pow2[n - 1];
    temp += (pow2[c.lu] - 1) * (pow2[c.rd] - 1) * pow2[c.ru] * pow2[c.ld];
    temp += (pow2[c.ru] - 1) * (pow2[c.ld] - 1) * pow2[c.lu] * pow2[c.rd];
    temp -= (pow2[c.lu] - 1) * (pow2[c.rd] - 1) * (pow2[c.ru] - 1) * (pow2[c.ld] - 1);
    ans += temp;
  }
  cout << ans << endl;
}

