    vector<int> bit;
public:
    BinaryIndexedTree(int n_) {
        n = n_+10;
        bit = vector<int>(n,0);
    }

    void add(int a,int w) {
        for (int x = a;x <= n;x += x&-x) bit[x] += w;
    }

    int sum(int a) {
        int ret = 0;
        for (int x = a;x > 0;x -= x&-x) ret += bit[x];
        return ret;
    }

    void update(int a,int w) {
        int v = w-sum(a)+sum(a-1);
        add(a,v);
    }
};

