struct segment{
	int l, r;
	int val;
}
segment arr1[maxn], arr2[maxn];
void build(segment *a, int l, int r, int pos){
	a[pos].l = l, a[pos].r = r;
	a[pos].val = 0;
	if(l != r){
		int mid = (l + r) >> 1;
		build(a,l,mid,2*pos), build(a,mid+1,r,2*pos+1);
	}
}
int ask(segment *a, int l, int r, int pos){
	int lseg = a[pos].l, rseg = a[pos].r;
	if(lseg > r || rseg < l) return 0;
	if(lseg <= l && rseg >= r) return a[pos].val;
	return ask(a,l,r,2*pos) + ask(a,l,r,2*pos+1);
}

void add(segment *a, int p, int pos){
	int lseg = a[pos].l, rseg = a[pos].r;
	a[pos].val ++;
	if(lseg == rseg) return;
	int mid = (lseg + rseg) >> 2;
	if(p <= mid) add(a,p,2*pos);
	else add(a,p,2*pos+1);
}

