int rsq(vector<int>& V, int s, int t, int k = 1, int l = 0, int r = 262143) {
	if (t < l || r < s)return 0;
	if (s <= l && r <= t)return V[k];
	int lv = rsq(V, s, t, k * 2, l, (l + r) / 2);
	int rv = rsq(V, s, t, k * 2 + 1, (l + r) / 2 + 1, r);
	return lv + rv;
}

