  int N = nextInt();
  REP(i, N) {
    q[i].x = nextInt();
    q[i].y = nextInt();
    q[i].id = i;
  }
  vector<ll> left(N), right(N), upper(N), bottom(N);
  vector<ll> upper_left(N), upper_right(N), bottom_left(N), bottom_right(N);

  {
    vector<int> a(N);
    REP(i, N) a[i] = q[i].x;
    a = normalize(a);
    REP(i, N) q[i].x = a[i];

    BIT bit(N+10);
    REP(i, N) bit.add(q[i].x, 1);
    REP(i, N) left[i] = bit.range(q[i].x - 1);
    REP(i, N) right[i] = N - bit.range(q[i].x);
  }
  {
    vector<int> a(N);
    REP(i, N) a[i] = q[i].y;
    a = normalize(a);
    REP(i, N) q[i].y = a[i];

    BIT bit(N+10);
    REP(i, N) bit.add(q[i].y, 1);
    REP(i, N) bottom[i] = bit.range(q[i].y - 1);
    REP(i, N) upper[i] = N - bit.range(q[i].y);
  }

  {
    sort(q, q+N, [](const P&a, const P&b){ return a.x < b.x; });
    BIT bit(N+10);
    int i = 0, j = 0;
    for (int px = 0; px < N; px++) {
      while (i < N && q[i].x == px) {
        bottom_left[q[i].id] = bit.range(q[i].y - 1);
        upper_left[q[i].id] = j - bit.range(q[i].y);
        i++;
      }
      while (j < N && q[j].x == px) {
        bit.add(q[j].y, 1);
        j++;
      }
    }
  }

  {
    sort(q, q+N, [](const P&a, const P&b){ return a.x > b.x; });
    BIT bit(N+10);
    int i = 0, j = 0;
    for (int px = N; px >= 0; px--) {
      while (i < N && q[i].x == px) {
        bottom_right[q[i].id] = bit.range(q[i].y - 1);
        upper_right[q[i].id] = j - bit.range(q[i].y);
        i++;
      }
      while (j < N && q[j].x == px) {
        bit.add(q[j].y, 1);
        j++;
      }
    }
  }

  ll ans = N * (two[N]-1) % MOD;
  REP(i, N) {
    ll s = 0;
    s += two[bottom[i]];
    s += two[left[i]];
    s += two[upper[i]];
    s += two[right[i]];
    s -= two[bottom_left[i]];
    s -= two[bottom_right[i]];
    s -= two[upper_left[i]];
    s -= two[upper_right[i]];
    s = (s % MOD + MOD) % MOD;
    ans = (((ans - s) % MOD) + MOD) % MOD;
  }
  cout << ans << endl;
  return 0;
}

