lint fact[3000000];
void fact_init(lint n, lint m = mod) {
	if (3000000 <= n) return;
	fact[0] = fact[1] = 1;
	for (lint i = 2; i <= n; ++i) {
		fact[i] = i * fact[i - 1];
		if (m <= fact[i]) fact[i] %= m;
	}
}

lint modpow(lint x, lint n, lint m = mod) {
	lint res = 1;
	while (n > 0) {
		if (n & 1) {
			res *= x;
			if (m <= res) res %= m;
		}
		x *= x;
		if (m <= x) x %= m;
		n >>= 1;
	}
	return res;
}

lint intpow(lint x, lint n) {
	lint res = 1;
	while (n > 0) {
		if (n & 1) res *= x;
		x *= x;
		n >>= 1;
	}
	return res;
}

lint comb(lint n, lint r, lint m = mod) {
	if (r == 0 || r == n) return 1;
	lint res = fact[n] * modpow(fact[n - r], m - 2, m) % m * modpow(fact[r], m - 2, m) % m;
	return res < 0 ? res + m : res;
}

map<lint, lint> factring(lint n) {
	map<lint, lint> res;
	for (lint i = 2; i * i <= n; ++i) {
		while (n % i == 0) {
			n /= i;
			++res[i];
		}
	}
	if (n != 1) ++res[n];
	return res;
}

void coordinate_compression(vector<P>& vec) {
	map<int, int>mp_x, mp_y;
	for(const auto& [x, y] : vec) {
		mp_x[x]++;
		mp_y[y]++;
	}
	int cnt = 0;
	for (const auto& [key, unsed] : mp_x) {
		mp_x[key] = cnt;
		cnt++;
	}
	cnt = 0;
	for (const auto& [key, unused] : mp_y) {
		mp_y[key] = cnt;
		cnt++;
	}
	for(P& p: vec) {
		const auto& [x, y] = p;
		p = P(mp_x[x], mp_y[y]);
	}
	sort(All(vec));
}

template<class T>
class binary_indexed_tree {
private:

	int m_size;
	vector<T>m_vec;

public:

	binary_indexed_tree(int size)
		:m_size(size)
	{
		m_vec.resize(m_size);
	}

	void add(int a, T w) { for (int x = a; x <= m_size; x += (x & -x)) m_vec[x] += w; }

	T sum(int a) const {
		T res = T();
		for (int x = a; x > 0; x -= (x & -x)) res += m_vec[x];
		return res;
	}

};

