template <typename T>
class SegTree {
private:
    int n;
    vector<T> data;
    T id;
    function<T(T, T)> update;
    function<T(T, T)> merge;

    T _query(int a, int b, int k, int l, int r) {
        if(r <= a || b <= l) return id;
        if(a <= l && r <= b) return data[k];

        T vl = _query(a, b, 2 * k + 1, l, (l + r) / 2);
        T vr = _query(a, b, 2 * k + 2, (l + r) / 2, r);
        return merge(vl, vr);
    }

public:
    SegTree(int _n, T _id, function<T(T, T)> _update, function<T(T, T)> _merge)
    : id(_id), update(_update), merge(_merge) {
        n = 1;
        while(n < _n) n <<= 1;
        data = vector<T>(2 * n - 1, id);
    }

    void change(int k, T x) {
        k += n - 1;
        data[k] = update(data[k], x);
        while(k > 0) {
            k = (k - 1) / 2;
            data[k] = merge(data[2 * k + 1], data[2 * k + 2]);
        }
    }

    T query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }

    T operator[](int k) {
        return data[k + n - 1];
    }
};

const int MOD = 998244353;
static const int n_max = 200000;
int powtwo[n_max + 1];

void powtwoinit() {
    powtwo[0] = 1;
    for(int i=1; i<=n_max; ++i) {
        powtwo[i] = powtwo[i - 1] * 2 % MOD;
    }
}

int main() {
    int N;
    cin >> N;
    vector<P> x(N), y(N);
    for(int i=0; i<N; ++i) {
        int a, b;
        cin >> a >> b;
        x[i] = P(a, i);
        y[i] = P(b, i);
    }
    sort(begin(x), end(x));
    sort(begin(y),end(y));
    vector<P> point(N);
    for(int i=0; i<N; ++i) {
        point[x[i].second].first = i;
        point[y[i].second].second = i;
    }
    sort(begin(point), end(point));

    SegTree<int> done(N, 0, plus<int>(), plus<int>());
    SegTree<int> undone(N, 0, plus<int>(), plus<int>());
    for(int i=0; i<N; ++i) undone.change(i, 1);

    int res = 0;
    powtwoinit();
    for(P p : point) {
        int y = p.second;
        done.change(y, 1);
        undone.change(y, -1);

        vector<int> num(4);
        num[0] = undone.query(y + 1, N);
        num[1] = done.query(y + 1, N);
        num[2] = done.query(0, y);
        num[3] = undone.query(0, y + 1);

        long long tmp = powtwo[N] - 1;
        for(int i=0; i<4; ++i) {
            tmp = (tmp - powtwo[num[i] + num[(i + 1) % 4]] + MOD) % MOD;
            tmp = (tmp + powtwo[num[i]]) % MOD;
        }
        res = (res + tmp) % MOD;
    }
    cout << res << endl;
}

