    ans -= (mod2[LD[i]]*mod2[RD[i]])%MOD;
    ans -= (mod2[RD[i]]*mod2[RU[i]])%MOD;
    ans += mod2[RU[i]];
    ans += mod2[LU[i]];
    ans += mod2[LD[i]];
