            ll b1 = ((bit>>1) & 1);
            ll b2 = ((bit>>2) & 1);
            ll b3 = ((bit>>3) & 1);
            RT = b0 ? pow_mod[RT] - 1 : 1;
            RD = b1 ? pow_mod[RD] - 1 : 1;
            LT = b2 ? pow_mod[LT] - 1 : 1;
            LD = b3 ? pow_mod[LD] - 1 : 1;

            ll v = RT * RD % MOD;
            (v *= LT) %= MOD;
            (v *= LD) %= MOD;
            if((b0 && b3) || (b1 && b2)){
                v *= 2;
                v %= MOD;
            }
