BIT_T* bit;
int bitN;
void BITinit(int n)
{
    bitN = n;
    bit = (BIT_T*)malloc( (bitN+1)*sizeof(BIT_T));
}

void BITadd(int i,BIT_T val)
{
    for(;i<=bitN;i+=i&-i) bit[i]+=val;
}

BIT_T BITget(int i)
{
    BIT_T val = 0;
    for(;i;i-=i&-i) val += bit[i];
    return val;
}

void BITreset(void)
{
    memset(bit, 0, sizeof(BIT_T)*(bitN+1));
}

