void coordinate_comp(long long a[],long long n){
  long long i,c=1;
  sd dat[524288];
  for(i=0;i<n;i++){
    dat[i].val=a[i];
    dat[i].node=i;
  }
  qsort(dat,n,sizeof(dat[0]),sdsortfnc);
  a[dat[0].node]=c;
  for(i=1;i<n;i++){
    if(dat[i-1].val!=dat[i].val){c++;}
    a[dat[i].node]=c;
  }
}

long long bsize=524288;
long long sum(long long i,long long bit[]){
    long long s=0;
    while(i>0){
        s+=bit[i];
        i-=i&(-i);
    }
    return s;
}
void add(long long i,long long x,long long bit[]){
    while(i<=bsize){
        bit[i]+=x;
        i+=i&(-i);
    }
}

long long mul4(long long a,long long b,long long c,long long d){
  a*=b;a%=mod;
  c*=d;c%=mod;
  a*=c;a%=mod;
  return a;
}

int main(void){
  long long i,j,n,m,k,a,b,c,d,h,w,r=0,l,t;
  long long pod[524288];
  long long x[524288],y[524288];
  long long fbit[525252]={0},bbit[525252]={0};
  long long pow2[524288],p2m1[524288];
  scanf("%lld",&n);
  for(i=0;i<n;i++){
    scanf("%lld%lld",&x[i],&y[i]);
  }
  coordinate_comp(x,n);
  coordinate_comp(y,n);
  pow2[0]=1;
  p2m1[0]=0;
  for(i=0;i<n;i++){
    pod[x[i]]=y[i];
    add(i+1,1,fbit);
    pow2[i+1]=(pow2[i]*2)%mod;
    p2m1[i+1]=(mod+pow2[i+1]-1)%mod;
  }
  for(i=1;i<=n;i++){
    r+=pow2[n-1];
    add(pod[i],-1,fbit);
    // a | b
    //-------
    // c | d
    c=sum(pod[i],bbit);
    d=sum(pod[i],fbit);
    a=i-1-c;
    b=n-i-d;
    r+=mul4(p2m1[a],1,1,p2m1[d]);//ad
    r+=mul4(1,p2m1[b],p2m1[c],1);//bc
    r+=mul4(p2m1[a],p2m1[b],p2m1[c],1);//abc
    r+=mul4(p2m1[a],p2m1[b],1,p2m1[d]);//abd
    r+=mul4(p2m1[a],1,p2m1[c],p2m1[d]);//acd
    r+=mul4(1,p2m1[b],p2m1[c],p2m1[d]);//bcd
    r+=mul4(p2m1[a],p2m1[b],p2m1[c],p2m1[d]);//abcd
    r%=mod;
    add(pod[i],1,bbit);
  }
  printf("%lld\n",r);
  return 0;
}

