		BIT ys = new BIT(m);
		for(int i = 0; i < n; i++) {
			int above = ys.sum(m)-ys.sum(pts[i][1]+1);
			int below = ys.sum(pts[i][1]);
			regions[0][i] = above;
			regions[2][i] = below;
			ys.upd(pts[i][1]+1, 1);
		}
		Arrays.fill(ys.tree, 0);
		for(int i = n-1; i >= 0; i--) {
			int above = ys.sum(m)-ys.sum(pts[i][1]+1);
			int below = ys.sum(pts[i][1]);
			regions[1][i] = above;
			regions[3][i] = below;
			ys.upd(pts[i][1]+1, 1);
		}

		int[] pow2 = new int[n+1];
		pow2[0] = 1;
		for(int i = 1; i <= n; i++) {
			pow2[i] = (2*pow2[i-1])%MOD;
		}

		int res = 0;
		for(int i = 0; i < n; i++) {
			int add = 0;
			int A = regions[0][i], B = regions[1][i];
			int C = regions[2][i], D = regions[3][i];
			int v1 = mult(sub(pow2[A+B], 1), sub(pow2[C+D], 1));
			v1 = mult(2, v1);
			add = add(add, v1);
			add = add(add, sub(pow2[A+B], 1));
			add = add(add, sub(pow2[C+D], 1));
			add = add(add, 1);

			v1 = mult(sub(pow2[B], 1), sub(pow2[D], 1));
			add = sub(add, v1);

			v1 = mult(sub(pow2[A], 1), sub(pow2[C], 1));
			add = sub(add, v1);

			res = add(res, add);
		}

		out.println(res);

		out.close();
	}

	int mult(long a, long b) {
		return (int)(a*b%MOD);
	}

	int sub(int a, int b) {
		a -= b;
		if(a < 0) a += MOD;
		return a;
	}

	int add(int a, int b) {
		a += b;
		if(a >= MOD) a -= MOD;
		return a;
	}

	class BIT {
		int n, log;
		int[] tree;
		BIT(int a) {
			n = a;
			log = Integer.numberOfTrailingZeros(Integer.highestOneBit(n))+1;
			tree = new int[n+1];
		}
		int sum(int i) {
			int res = 0;
			while(i > 0) {
				res += tree[i];
				i -= i &-i;
			}
			return res;
		}
		void upd(int i, long v) {
			while(i <= n) {
				tree[i] += v;
				i += i & -i;
			}
		}
		int walk(long sum) {
			long cur = 0;
			int idx = 0;
			for(int i = log; i >= 0; i--) {
				if(idx+(1<<i) > n) continue;
				int nxt = idx+(1<<i);
				if(cur+tree[nxt] < sum) {
					cur += tree[nxt];
					idx = nxt;
				}
			}
			return idx+1;
		}
	}

