class ArrayLibs {
    public static int[] compress(int[] x) {
        int n = x.length;
        int[] sorted = Arrays.copyOf(x, n);
        Arrays.sort(sorted);
        int[] uniq = ArrayLibs.unique(sorted);

        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            res[i] = Arrays.binarySearch(uniq, x[i]);
        }
        return res;
    }

    private static int[] unique(final int[] sorted) {
        int cnt = 1;
        for (int i = 1; i < sorted.length; i++) {
            if (sorted[i] != sorted[i-1]) cnt++;
        }
        int[] res = new int[cnt];
        res[0] = sorted[0];
        for (int i = 1, cur = 1; i < sorted.length; i++) {
            if (sorted[i] != sorted[i-1]) {
                res[cur++] = sorted[i];
            }
        }
        return res;
    }

    public static void main(String[] args) {
        int[] x = new int[]{20,30,10,10,30};
        System.out.println(Arrays.toString(compress(x)));
    }
}

