                    tmp = (tmp * (IntegerUtils.power(2, a4[i], MiscUtils.MOD7) - 1)) % MiscUtils.MOD7;
                    tmp = (tmp * IntegerUtils.power(2, a3[i], MiscUtils.MOD7)) % MiscUtils.MOD7;
                    ans = (ans + tmp) % MiscUtils.MOD7;
                }
                {
                    long tmp = IntegerUtils.power(2, a1[i], MiscUtils.MOD7) - 1;
                    tmp = (tmp * (IntegerUtils.power(2, a2[i], MiscUtils.MOD7) - 1)) % MiscUtils.MOD7;
                    tmp = (tmp * (IntegerUtils.power(2, a3[i], MiscUtils.MOD7) - 1)) % MiscUtils.MOD7;
                    tmp = (tmp * (IntegerUtils.power(2, a4[i], MiscUtils.MOD7) - 1)) % MiscUtils.MOD7;
                    ans = (ans - tmp + MiscUtils.MOD7) % MiscUtils.MOD7;
                }
                ans = (ans + IntegerUtils.power(2, n - 1, MiscUtils.MOD7)) % MiscUtils.MOD7;
            }

            out.printLine(ans);
        }

        private void count(int n, List<IntIntPair> points, long[] a1, long[] a2) {
