import java.util.Arrays;
import java.util.Scanner;
import java.util.TreeSet;

public class Main {
	static Scanner sc = new Scanner(System.in);
	static final long MOD = 998244353;
	static long[] pow2;
	static int N;

	public static void main(String[] args) {
		N = sc.nextInt();
		pow2 = new long[N + 1];
		pow2[0] = 1;
		for (int i = 0; i < N; i++) {
			pow2[i + 1] = pow2[i] * 2;
			if (pow2[i + 1] >=MOD) pow2[i + 1] -= MOD;
		}
		for (int i = 0; i <= N; i++) {
			pow2[i] = pow2[i] - 1;
		}
		Point[] ps = new Point[N];
		for (int i = 0; i < N; i++) {
			int X = Integer.parseInt(sc.next());
			int Y = Integer.parseInt(sc.next());
			ps[i] = new Point(X, Y);
		}
		Arrays.sort(ps, (p1, p2) -> Integer.compare(p1.y, p2.y));
		for (int i = 0; i < N; i++) {
			ps[i].yi = i;
		}
		Arrays.sort(ps, (p1, p2) -> Integer.compare(p1.x, p2.x));
		long ans = count(ps);
		for (int i = 1; i < N; i++) {
			ans += pow2[i] * 4;
		}
		ans %= MOD;
		System.out.println((N * pow2[N] + MOD - ans) % MOD);
	}

	static long count(Point[] ps) {
		TreeSet<Integer> set = new TreeSet<>();
		long ret = 0;
		for (int i = 0; i < N; i++) {
			int upper = set.tailSet(ps[i].y).size();
			int lower = i - upper;
			int lower2 = ps[i].yi - lower;
			int upper2 = N - 1 - i - lower2;
			ret += MOD - pow2[upper];
			ret += MOD - pow2[lower];
			ret += MOD - pow2[upper2];
			ret += MOD - pow2[lower2];
			set.add(ps[i].y);
		}
		ret %= MOD;
		return ret;
	}

	static class Point {
		int x, y, yi;

		public Point(int x, int y) {
			this.x = x;
			this.y = y;
		}
	}
}

import java.util.*;

public class Main {
	Scanner sc;
	final int MOD = 998244353;
	int N;
	int[][] p;
	int[] pow2;

	int[] ylist;
	int ylistSize;

	public Main() {
		sc = new Scanner(System.in);
	}

	private void calc() {
		N = sc.nextInt();
		p = new int[N][2];
		for (int i = 0; i < N; i++) {
			p[i][0] = sc.nextInt();
			p[i][1] = sc.nextInt();
		}
		pow2 = new int[N+1];
		pow2[0] = 1;
		for (int i = 1; i < N+1; i++)
			pow2[i] = (pow2[i-1]*2)%MOD;
		ylist = new int[N];
		ylistSize = 0;

		Arrays.sort(p, (a,b) -> Integer.compare(a[1], b[1]));
		for (int i = 0; i < N; i++) p[i][1] = i;
		Arrays.sort(p, (a,b) -> Integer.compare(a[0], b[0]));
		for (int i = 0; i < N; i++) p[i][0] = i;

		int sum = (int) (((long)N-4)*(pow2[N]-1)%MOD);

		for (int i = 0; i < N; i++) {
			if (i == N/2) ylistSize = 0;
			boolean former = (i < N/2);
			int j = (former)?i:N-1+N/2-i;

			int yi = insertYPos(p[j][1]);
			int a1 = yi;
			int a2 = p[j][1] - a1;
			int a3 = (former)?p[j][0] - a1 : p[j][0] - a2;
			int a4 = N-1-p[j][1] - a3;

			int s = (pow2[a1] + pow2[a2])%MOD;
			s = (s + pow2[a3])%MOD;
			s = (s + pow2[a4])%MOD;
			sum = (sum + s)%MOD;
		}

		out(sum);
	}

	private int insertYPos(int y) {
		int yi = -1;
		int l = -1;
		int r = ylistSize;
		while (true) {
			yi = (l+r+2)/2-1;
			if (l == yi) break;
			if (ylist[yi] > y) r = yi;
			else l = yi;
		}
		if (yi < ylistSize) yi++;
		System.arraycopy(ylist, yi, ylist, yi+1, ylistSize - yi);
		ylist[yi] = y;
		ylistSize++;
		return yi;
	}

	private void out(Object o) {
		System.out.println(o);
		System.out.flush();
	}

	public static void main(String[] args) {
		Main m = new Main();
		m.calc();
	}

}

