 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        FEnclosedPoints solver = new FEnclosedPoints();
        solver.solve(1, in, out);
        out.close();
    }

    static class FEnclosedPoints {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] x = new int[n];
            int[] y = new int[n];
            in.readIntArrays(x, y);

            ArrayUtils.compress(x);
            ArrayUtils.compress(y);
            List<IntIntPair> points = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                points.add(new IntIntPair(x[i], y[i]));
            }
            Collections.sort(points);

            long[] a1 = new long[n];
            long[] a2 = new long[n];
            count(n, points, a1, a2);

            Collections.reverse(points);
            long[] a3 = new long[n];
            long[] a4 = new long[n];
            count(n, points, a3, a4);
            ArrayUtils.reverse(a3);
            ArrayUtils.reverse(a4);

            long ans = 0;
            for (int i = 0; i < n; i++) {
                {
                    long tmp = a1[i];
                    tmp = (tmp * (a2[i] - 1)) % MiscUtils.MODF;
                    tmp = (tmp * (a3[i] - 1)) % MiscUtils.MODF;
                    tmp = (tmp * a4[i]) % MiscUtils.MODF;
                    ans = (ans + tmp) % MiscUtils.MODF;
                }
                {
                    long tmp = a1[i] - 1;
                    tmp = (tmp * a2[i]) % MiscUtils.MODF;
                    tmp = (tmp * a3[i]) % MiscUtils.MODF;
                    tmp = (tmp * (a4[i] - 1)) % MiscUtils.MODF;
                    ans = (ans + tmp) % MiscUtils.MODF;
                }
                {
                    long tmp = a1[i] - 1;
                    tmp = (tmp * (a2[i] - 1)) % MiscUtils.MODF;
                    tmp = (tmp * (a3[i] - 1)) % MiscUtils.MODF;
                    tmp = (tmp * (a4[i] - 1)) % MiscUtils.MODF;
                    ans = (ans - tmp) % MiscUtils.MODF;
                }
                ans = (ans + IntegerUtils.power(2, n - 1, MiscUtils.MODF)) % MiscUtils.MODF;
            }

            out.printLine(ans);
        }

        private void count(int n, List<IntIntPair> points, long[] a1, long[] a2) {
            FenwickTree tree = new FenwickTree(n);
            for (int i = 0; i < n; i++) {
                int yy = points.get(i).second;
                a1[i] = IntegerUtils.power(2, tree.get(0, yy), MiscUtils.MODF);
                a2[i] = IntegerUtils.power(2, tree.get(yy, n), MiscUtils.MODF);
                tree.add(yy, 1);
            }
        }

    }

    static class IntArrayList extends IntAbstractStream implements IntList {
        private int size;
        private int[] data;

        public IntArrayList() {
            this(3);
        }

        public IntArrayList(int capacity) {
            data = new int[capacity];
        }

        public IntArrayList(IntCollection c) {
            this(c.size());
            addAll(c);
        }

        public IntArrayList(IntStream c) {
            this();
            if (c instanceof IntCollection) {
                ensureCapacity(((IntCollection) c).size());
            }
            addAll(c);
        }

        public IntArrayList(IntArrayList c) {
            size = c.size();
            data = c.data.clone();
        }

        public IntArrayList(int[] arr) {
            size = arr.length;
            data = arr.clone();
        }

        public int size() {
            return size;
        }

        public int get(int at) {
            if (at >= size) {
                throw new IndexOutOfBoundsException("at = " + at + ", size = " + size);
            }
            return data[at];
        }

        private void ensureCapacity(int capacity) {
            if (data.length >= capacity) {
                return;
            }
            capacity = Math.max(2 * data.length, capacity);
            data = Arrays.copyOf(data, capacity);
        }

        public void addAt(int index, int value) {
            ensureCapacity(size + 1);
            if (index > size || index < 0) {
                throw new IndexOutOfBoundsException("at = " + index + ", size = " + size);
            }
            if (index != size) {
                System.arraycopy(data, index, data, index + 1, size - index);
            }
            data[index] = value;
            size++;
        }

        public void removeAt(int index) {
            if (index >= size || index < 0) {
                throw new IndexOutOfBoundsException("at = " + index + ", size = " + size);
            }
            if (index != size - 1) {
                System.arraycopy(data, index + 1, data, index, size - index - 1);
            }
            size--;
        }

        public void set(int index, int value) {
            if (index >= size) {
                throw new IndexOutOfBoundsException("at = " + index + ", size = " + size);
            }
            data[index] = value;
        }

        public int[] toArray() {
            return Arrays.copyOf(data, size);
        }

    }

