import java.util.ArrayList;
import java.util.Comparator;
import java.util.Scanner;

public class Main {

	static final long mod = 998244353L;

	public static void main(String[] args) {
		Main mainObj = new Main();
		mainObj.solve();
	}

	void solve() {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();

		ArrayList<Coodinate> coodinateList = new ArrayList<>();
		for(int i = 0; i < n; i++) {
			int x = sc.nextInt();
			int y = sc.nextInt();
			coodinateList.add(new Coodinate(x,y,i));
		}

		sc.close();

		Comparator<Coodinate> yComparator = Comparator.comparing(Coodinate::getY);
		Comparator<Coodinate> xComparator = Comparator.comparing(Coodinate::getX);
		coodinateList.sort(yComparator);
		for(int i = 0; i < n; i++) {
			coodinateList.get(i).setY(i);
		}

		coodinateList.sort(xComparator);
		for(int i = 0; i < n; i++) {
			coodinateList.get(i).setX(i);
		}

		int[] firstQuadrant = new int[n];
		int[] secondQuadrant = new int[n];
		int[] thirdQuadrant = new int[n];
		int[] forthQuadrant = new int[n];

		// 平面走査する
		SumSegTree leftTree = new SumSegTree(n);
		// xの小さい方
		for(int i = 0; i < n; i++) {
			int numOfThirdQuadrant = leftTree.getValue(0, i, 0, 0, n);
			thirdQuadrant[i] = numOfThirdQuadrant;
			secondQuadrant[i] = i - numOfThirdQuadrant;

			Coodinate nowCoodinate = coodinateList.get(i);
			leftTree.upDate(nowCoodinate.getY(), 1);
		}

		SumSegTree rightTree = new SumSegTree(n);
		// xの大きい方
		for(int i = n - 1; i >= 0; i++) {
			int numOfForthQuadrant = rightTree.getValue(i, n, 0, 0, n);
			forthQuadrant[i] = numOfForthQuadrant;
			firstQuadrant[i] = (n - 1) - i - numOfForthQuadrant;

			Coodinate nowCoodinate = coodinateList.get(i);
			rightTree.upDate(nowCoodinate.getY(), 1);
		}

		long ans = 0;
		long[] powArr = new long[n+1];
		for(int i = 0 ; i < n; i++) {
			powArr[i] = -1;
		}
		for(int i = 0; i < n ;i++) {
			int first = firstQuadrant[i];
			int second = secondQuadrant[i];
			int third = thirdQuadrant[i];
			int forth = forthQuadrant[i];

			long firstPow,secondPow,thirdPow,forthPow;
			if(powArr[first] != -1) {
				firstPow = powArr[first];
			}else {
				firstPow = powWithMod(2, first);
				powArr[first] = firstPow;
			}

			if(powArr[second] != -1) {
				secondPow = powArr[second];
			}else {
				secondPow = powWithMod(2, second);
				powArr[second] = secondPow;
			}

			if(powArr[third] != -1) {
				thirdPow = powArr[third];
			}else {
				thirdPow = powWithMod(2, third);
				powArr[third] = thirdPow;
			}

			if(powArr[forth] != -1) {
				forthPow = powArr[forth];
			}else {
				forthPow = powWithMod(2, forth);
				powArr[forth] = forthPow;
			}

			ans += calcMod(calcMod(calcMod(firstPow*(secondPow-1))*thirdPow)*(forthPow - 1));
			ans += calcMod(calcMod(calcMod((firstPow-1)*secondPow)*(thirdPow - 1))*forthPow);
			ans -= calcMod(calcMod(calcMod((firstPow-1)*(secondPow - 1))*(thirdPow - 1))*(forthPow - 1));
			ans += calcMod(calcMod(calcMod(firstPow*secondPow)*thirdPow)*forthPow);
		}

		System.out.println(ans);
	}

	long calcMod(long value) {
		if(value < 0) {
			while(value > 0) {
				value += mod;
			}
			return value;
		}else {
			return value%mod;	
		}
	}

	long powWithMod(int base, int times) {
		long retValue = 1;
		for(int i = 0;i < times; i++) {
			retValue = calcMod(retValue*base);
		}
		return retValue;
	}

	class SumSegTree{
		int[] arr;
		int n;

		SumSegTree(int n){
			this.n = n;
			int arrSize = 1;
			while(n <= arrSize) {
				arrSize *= 2;
			}

			// 最初は和もvalueも0なので何もしない
			this.arr = new int[arrSize];
		}

		void upDate(int pos, int value) {
			int segIndex = pos + n - 1;
			int beforeValue = arr[segIndex];
			arr[segIndex] = value;

			int diff = value - beforeValue;
			while(segIndex > 0) {
				segIndex = (segIndex - 1)/2;
				arr[segIndex] = arr[segIndex] + diff;
			}
		}

		// a, b間の和を取得
		int getValue(int a, int b, int k, int l, int r) {

			if(r <= a || l <= b) {
				return 0;
			}
			if(a <= l && r <= b) {
				return arr[k];
			}

			return getValue(a, b, 2*k + 1, l, (l+r)/2) + getValue(a,b,2*k + 1, (l+r)/2, r);
		}
	}

	class Coodinate{
		int x;
		int y;
		int no;

		Coodinate(int x, int y, int no){
			this.x = x;
			this.y = y;
			this.no = no;
		}

		int getX() {
			return x;
		}

		int getY() {
			return y;
		}

		void setX(int x) {
			this.x = x;
		}

		void setY(int y) {
			this.y = y;
		}

		int getNo() {
			return no;
		}
	}
}

