public class Main {

    private static final int MOD = 998244353;

    public static void main(String[] args) {
        SimpleScanner scanner = new SimpleScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int n = scanner.nextInt();
        ArrayList<Point> points = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            points.add(new Point(x, y));
        }
        int[] leftTop = new int[n];
        int[] leftBottom = new int[n];
        int[] rightTop = new int[n];
        int[] rightBottom = new int[n];
        points.sort(Comparator.comparingInt(o -> -o.x));
        TreapWithOutRotation treap = new TreapWithOutRotation();
        for (int i = 0; i < n; ++i) {
            rightBottom[n - i - 1] = treap.getRank(points.get(i).y);
            rightTop[n - i - 1] = i - rightBottom[n - i - 1];
            treap.insert(points.get(i).y);
        }
        Collections.reverse(points);
        treap = new TreapWithOutRotation();
        for (int i = 0; i < n; ++i) {
            leftBottom[i] = treap.getRank(points.get(i).y);
            leftTop[i] = i - leftBottom[i];
//            writer.println(leftTop[i] + " " + leftBottom[i] + " " + rightTop[i] + " " + rightBottom[i]);
//            writer.flush();
            treap.insert(points.get(i).y);
        }
        long[] power2 = new long[n + 1];
        power2[0] = 1;
        for (int i = 1; i <= n; ++i)
            power2[i] = power2[i - 1] * 2 % MOD;
        long ans = 0;
        for (int i = 0; i < n; ++i) {
            ans = (ans + power2[n - 1]) % MOD;
            long t = (power2[leftTop[i]] - 1) * (power2[rightBottom[i]] - 1) % MOD * power2[leftBottom[i] + rightTop[i]] % MOD
                    + (power2[rightTop[i]] - 1) * (power2[leftBottom[i]] - 1) % MOD * power2[rightBottom[i] + leftTop[i]] % MOD
                    - (power2[leftTop[i]] - 1) * (power2[rightBottom[i]] - 1) % MOD * (power2[rightTop[i]] - 1) % MOD * (power2[leftBottom[i]] - 1) % MOD;
            t = (t + MOD) % MOD;
            ans = (ans + t) % MOD;
        }
        writer.println(ans);

        writer.close();
    }

    private static class Point {
        final int x, y;

        private Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    private static class TreapWithOutRotation {

        private Node root;
        private final int maxPriority;
        private Random random;

        private TreapWithOutRotation() {
            this(Integer.MAX_VALUE);
        }

        private TreapWithOutRotation(int maxPriority) {
            this.maxPriority = maxPriority;
            this.random = new Random();
        }

        private Node[] split(int key, Node node) {
            if (node == null)
                return new Node[]{null, null};
            if (key < node.key) {
                Node[] t = split(key, node.lChild);
                node.lChild = t[1];
                node.updateSize();
                return new Node[]{t[0], node};
            } else {
                Node[] t = split(key, node.rChild);
                node.rChild = t[0];
                node.updateSize();
                return new Node[]{node, t[1]};
            }
        }

        private Node merge(Node l, Node r) {
            if (l == null)
                return r;
            if (r == null)
                return l;
            if (l.priority > r.priority) {
                l.rChild = merge(l.rChild, r);
                l.updateSize();
                return l;
            } else {
                r.lChild = merge(l, r.lChild);
                r.updateSize();
                return r;
            }
        }

        private void insert(int key) {
            root = insert(key, random.nextInt(maxPriority), root);
        }

        private Node insert(int key, int priority, Node node) {
            if (node == null) {
                return new Node(key, priority, null, null);
            }
            if (priority > node.priority) {
                Node[] t = split(key, node);
                return new Node(key, priority, t[0], t[1]);
            }
            if (key < node.key) {
                node.lChild = insert(key, priority, node.lChild);
            } else if (key > node.key) {
                node.rChild = insert(key, priority, node.rChild);
            }
            node.updateSize();
            return node;
        }

        private int getRank(int key) {
            return getRank(key, root);
        }

        private int getRank(int key, Node node) {
            if (node == null)
                return 0;
            if (key < node.key)
                return getRank(key, node.lChild);
            if (key == node.key)
                return Node.getSize(node.lChild);
            return Node.getSize(node.lChild) + 1 + getRank(key, node.rChild);
        }

        private static class Node {
            private int key, priority, size;
            private Node lChild, rChild;

            private Node(int key, int priority, Node lChild, Node rChild) {
                this.key = key;
                this.priority = priority;
                this.lChild = lChild;
                this.rChild = rChild;
                this.size = getSize(lChild) + getSize(rChild) + 1;
            }

            private void updateSize() {
                size = getSize(lChild) + getSize(rChild) + 1;
            }

            private static int getSize(Node node) {
                return node == null ? 0 : node.size;
            }
        }
    }

    private static class SimpleScanner {

        private static final int BUFFER_SIZE = 10240;

        private Readable in;
        private CharBuffer buffer;
        private boolean eof;

        private SimpleScanner(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
            buffer = CharBuffer.allocate(BUFFER_SIZE);
            buffer.limit(0);
            eof = false;
        }


        private char read() {
            if (!buffer.hasRemaining()) {
                buffer.clear();
                int n;
                try {
                    n = in.read(buffer);
                } catch (IOException e) {
                    n = -1;
                }
                if (n <= 0) {
                    eof = true;
                    return '\0';
                }
                buffer.flip();
            }
            return buffer.get();
        }

        void checkEof() {
            if (eof)
                throw new NoSuchElementException();
        }

        char nextChar() {
            checkEof();
            char b = read();
            checkEof();
            return b;
        }

        String next() {
            char b;
            do {
                b = read();
                checkEof();
            } while (Character.isWhitespace(b));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append(b);
                b = read();
            } while (!eof && !Character.isWhitespace(b));
            return sb.toString();
        }

        int nextInt() {
            return Integer.valueOf(next());
        }

        long nextLong() {
            return Long.valueOf(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;

public class Main {
	Scanner sc;
	final int MOD = 998244353;
	int N;
	int[][] p;
	int[] pow2;

	List<Integer> ylist;

	public Main() {
		sc = new Scanner(System.in);
	}

	private void calc() {
		N = sc.nextInt();
		p = new int[N][2];
		for (int i = 0; i < N; i++) {
			p[i][0] = sc.nextInt();
			p[i][1] = sc.nextInt();
		}
		pow2 = new int[N];
		pow2[0] = 0;
		for (int i = 1; i < N; i++)
			pow2[i] = (pow2[i-1]*2+1)%MOD;
		ylist = new ArrayList<Integer>();

		Arrays.sort(p, (a,b) -> Integer.compare(a[1], b[1]));
		for (int i = 0; i < N; i++) p[i][1] = i;
		Arrays.sort(p, (a,b) -> Integer.compare(a[0], b[0]));
		for (int i = 0; i < N; i++) p[i][0] = i;

		int sum = 0;

		ylist = new ArrayList<Integer>();
		for (int i = 0; i < N; i++) {
			if (i == N/2) ylist.clear();
			boolean former = (i < N/2);
			int j = (former)?i:N-1+N/2-i;
			sum = (sum + pow2[N-1] + 1)%MOD;

			int a12 = p[j][1];
			int a34 = N-1-p[j][1];
			int a13 = p[j][0];
			int a24 = N-1-p[j][0];

			int a1 = insertYPos(ylist, p[j][1]);
			int a2 = a12 - a1;
			int a3 = (former)?a13-a1 : a13-a2;
			int a4 = a34 - a3;

			int s = (pow2[a12] + pow2[a34])%MOD;
			s = (s + pow2[a13])%MOD;
			s = (s + pow2[a24])%MOD;
			s = mod(s - pow2[a1], MOD);
			s = mod(s - pow2[a2], MOD);
			s = mod(s - pow2[a3], MOD);
			s = mod(s - pow2[a4], MOD);

			s = mod(pow2[N-1] - s, MOD);
			sum = (sum + s)%MOD;
		}

		out(sum);
	}

	private int mod(int a, int m) {
		return (a >= 0)?a:(a+m)%m;
	}

	private static int insertYPos(List<Integer> list, int y) {
		int yi = -1;
		int l = -1;
		int r = list.size();
		while (true) {
			yi = (l+r+2)/2-1;
			if (l == yi) break;
			if (list.get(yi) > y) r = yi;
			else l = yi;
		}
		if (yi < list.size()) yi++;
		list.add(yi, y);
		return yi;
	}

	private void out(Object o) {
		System.out.println(o);
		System.out.flush();
	}

	public static void main(String[] args) {
		Main m = new Main();
		m.calc();
	}

}

import java.util.Arrays;
import java.util.Scanner;
import java.util.TreeSet;

public class Main {
	static Scanner sc = new Scanner(System.in);
	static final long MOD = 998244353;
	static long[] pow2;
	static int N;

	public static void main(String[] args) {
		N = sc.nextInt();
		pow2 = new long[N + 1];
		pow2[0] = 1;
		for (int i = 0; i < N; i++) {
			pow2[i + 1] = pow2[i] * 2;
			if (pow2[i + 1] >=MOD) pow2[i + 1] -= MOD;
		}
		for (int i = 0; i <= N; i++) {
			pow2[i] = pow2[i] - 1;
		}
		Point[] ps = new Point[N];
		for (int i = 0; i < N; i++) {
			int X = Integer.parseInt(sc.next());
			int Y = Integer.parseInt(sc.next());
			ps[i] = new Point(X, Y);
		}
		Arrays.sort(ps, (p1, p2) -> Integer.compare(p1.x, p2.x));
		long ans = count(ps);
		for (int i = 0; i < N; i++) {
			ps[i].x *= -1;
		}
		for (int i = 0; i < N / 2; i++) {
			Point tmp = ps[i];
			ps[i] = ps[N - 1 - i];
			ps[N - 1 - i] = tmp;
		}
		ans += count(ps);
		for (int i = 1; i < N; i++) {
			ans += pow2[i] * 2;
		}
		ans %= MOD;
		System.out.println((N * pow2[N] + MOD - ans) % MOD);
	}

	static long count(Point[] ps) {
		TreeSet<Integer> set = new TreeSet<>();
		long ret = 0;
		for (int i = 0; i < N; i++) {
			int upper = set.tailSet(ps[i].y).size();
			int lower = i - upper;
			ret += pow2[i];
			ret += MOD - pow2[upper];
			ret += MOD - pow2[lower];
			set.add(ps[i].y);
		}
		ret %= MOD;
		return ret;
	}

	static class Point {
		int x, y;

		public Point(int x, int y) {
			this.x = x;
			this.y = y;
		}
	}
}

