    private static class SimpleScanner {

        private static final int BUFFER_SIZE = 10240;

        private Readable in;
        private CharBuffer buffer;
        private boolean eof;

        SimpleScanner(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
            buffer = CharBuffer.allocate(BUFFER_SIZE);
            buffer.limit(0);
            eof = false;
        }


        private char read() {
            if (!buffer.hasRemaining()) {
                buffer.clear();
                int n;
                try {
                    n = in.read(buffer);
                } catch (IOException e) {
                    n = -1;
                }
                if (n <= 0) {
                    eof = true;
                    return '\0';
                }
                buffer.flip();
            }
            return buffer.get();
        }

        void checkEof() {
            if (eof)
                throw new NoSuchElementException();
        }

        char nextChar() {
            checkEof();
            char b = read();
            checkEof();
            return b;
        }

        String next() {
            char b;
            do {
                b = read();
                checkEof();
            } while (Character.isWhitespace(b));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append(b);
                b = read();
            } while (!eof && !Character.isWhitespace(b));
            return sb.toString();
        }

        int nextInt() {
            return Integer.valueOf(next());
        }

        long nextLong() {
            return Long.valueOf(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
	Scanner sc;
	final int MOD = 998244353;
	int N;
	int[][] p;
	int[] pow2;

	List<Integer> ylist;

	public Main() {
		sc = new Scanner(System.in);
	}

	private void calc() {
		N = sc.nextInt();
		p = new int[N][2];
		for (int i = 0; i < N; i++) {
			p[i][0] = sc.nextInt();
			p[i][1] = sc.nextInt();
		}
		pow2 = new int[N];
		pow2[0] = 0;
		for (int i = 1; i < N; i++)
			pow2[i] = (pow2[i-1]*2+1)%MOD;
		ylist = new ArrayList<Integer>();

		Arrays.sort(p, (a,b) -> Integer.compare(a[1], b[1]));
		for (int i = 0; i < N; i++) p[i][1] = i;
		Arrays.sort(p, (a,b) -> Integer.compare(a[0], b[0]));
		for (int i = 0; i < N; i++) p[i][0] = i;

		int sum = 0;

		for (int i = 0; i < N; i++) {
			sum = (sum + pow2[N-1] + 1)%MOD;

			int a12 = p[i][1];
			int a34 = N-1-p[i][1];
			int a13 = p[i][0];
			int a24 = N-1-p[i][0];

			int a1 = insertYPos(ylist, p[i][1]);
			int a2 = a12 - a1;
			int a3 = a13 - a1;
			int a4 = a34 - a3;

			int s = (pow2[a12] + pow2[a34])%MOD;
			s = (s + pow2[a13])%MOD;
			s = (s + pow2[a24])%MOD;
			s = mod(s - pow2[a1], MOD);
			s = mod(s - pow2[a2], MOD);
			s = mod(s - pow2[a3], MOD);
			s = mod(s - pow2[a4], MOD);

			s = mod(pow2[N-1] - s, MOD);
			sum = (sum + s)%MOD;
		}

		out(sum);
	}

	private int mod(int a, int m) {
		return (a >= 0)?a:(a+m)%m;
	}

	private static int insertYPos(List<Integer> list, int y) {
		int yi = -1;
		int l = -1;
		int r = list.size();
		while (true) {
			yi = (l+r+2)/2-1;
			if (l == yi) break;
			if (list.get(yi) > y) r = yi;
			else l = yi;
		}
		if (yi < list.size()) yi++;
		list.add(yi, y);
		return yi;
	}

	private void out(Object o) {
		System.out.println(o);
		System.out.flush();
	}

	public static void main(String[] args) {
		Main m = new Main();
		m.calc();
	}

}

