	public MultiSetL factorization(long e) {
		MultiSetL ret = new MultiSetL();
		for(long i=2;i*i<=e;i++) {
			while(e%i==0) {
				ret.add(i);
				e /= i;
			}
		}
		if(e!=1)ret.add(e);
		return ret;
	}
