		long[] d = new long[n];
		BIT bit = new BIT(n + 1);
		for (int i = 0; i < n; i++) {
			int y = xy[i][1] + 1;
			a[i] = bit.sum(y);
			b[i] = i - a[i];
			bit.add(y, 1);
		}
		long[] t = a;
		a = c;
		c = t;

		t = b;
		b = d;
		d = t;
		bit = new BIT(n + 1);
		for (int i = n - 1; i >= 0; i--) {
			int y = xy[i][1] + 1;
			a[i] = bit.sum(y);
			b[i] = (n - 1 - i) - a[i];
			bit.add(y, 1);
		}

		long answer = 0;
		for (int i = 0; i < n; i++) {
			//System.out.printf("%d %d %d %d\n", a[i], b[i], c[i], d[i]);
			answer = (answer + f(a[i], b[i], c[i], d[i])) % M;
		}
		System.out.println(answer);
	}

	private static long pow(long x, long n, long M) {
		long a = 1;
		while (n > 0) {
			if ((n & 1) == 1) a = (a * x) % M;
			x = (x * x) % M;
			n >>= 1;
		}
		return a;
	}

	private static long f(long a, long b, long c, long d) {
		long result = 0;
		long[] abcd = {a, b, c, d};
		long[] o = new long[4];
		long[] ox = new long[4];
		for (int i = 0; i < 4; i++) {
			ox[i] = pow(2, abcd[i], M);
			o[i] = ox[i] - 1;
		}
		result += (((((ox[0] * o[1]) % M) * o[2]) % M) * ox[3]) % M;
		result += (((((o[0] * ox[1]) % M) * ox[2]) % M) * o[3]) % M;
		result -= (((((o[0] * o[1]) % M) * o[2]) % M) * o[3]) % M;
		if (result < 0) result += M;
		result += (((((ox[0] * ox[1]) % M) * ox[2]) % M) * ox[3]) % M;
		return result % M;
	}
}

