import java.util.*;

class Main {
	static final long M = 998244353;

	static class BIT {
		private int n;
		private int[] a;

		BIT(int _n) {
			n = _n + 1;
			a = new int[n];
		}

		public int sum(int i) {
			int s = 0;
			for (int index = i; index > 0; index -= (index & -index)) {
				s += a[index];
			}
			return s;
		}

		public void add(int i, int x) {
			for (int index = i; index < n; index += (index & -index)) {
				a[index] += x;
			}
		}
	}


	public static void main(String[] args) throws Exception {
		final Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int[][] xy = new int[n][2];
		NavigableMap<Integer, Integer> hx = new TreeMap<>();
		NavigableMap<Integer, Integer> hy = new TreeMap<>();
		for (int i = 0; i < n; i++) {
			xy[i][0] = sc.nextInt();
			xy[i][1] = sc.nextInt();
			hx.put(xy[i][0], 0);
			hy.put(xy[i][1], 0);
		}

		int index = 0;
		for (Integer i : hx.keySet()) hx.put(i, index++);
		index = 0;
		for (Integer i : hy.keySet()) hy.put(i, index++);

		for (int i = 0; i < n; i++) {
			xy[i][0] = hx.get(xy[i][0]);
			xy[i][1] = hy.get(xy[i][1]);
		}

		Arrays.sort(xy, (a, b) -> Integer.compare(a[0], b[0]));
		long[] a = new long[n];
		long[] b = new long[n];
		long[] c = new long[n];
		long[] d = new long[n];
		BIT bit = new BIT(n + 1);
		for (int i = 0; i < n; i++) {
			int y = xy[i][1] + 1;
			a[i] = bit.sum(y);
			b[i] = i - a[i];
			bit.add(y, 1);
		}
		long[] t = a;
		a = c;
		c = t;

		t = b;
		b = d;
		d = t;
		bit = new BIT(n + 1);
		for (int i = n - 1; i >= 0; i--) {
			int y = xy[i][1] + 1;
			a[i] = bit.sum(y);
			b[i] = (n - 1 - i) - a[i];
			bit.add(y, 1);
		}

		long answer = 0;
		for (int i = 0; i < n; i++) {
			//System.out.printf("%d %d %d %d\n", a[i], b[i], c[i], d[i]);
			answer = (answer + f(a[i], b[i], c[i], d[i])) % M;
		}
		System.out.println(answer);
	}

	private static long pow(long x, long n, long M) {
		long a = 1;
		while (n > 0) {
			if ((n & 1) == 1) a = (a * x) % M;
			x = (x * x) % M;
			n >>= 1;
		}
		return a;
	}

	private static long f(long a, long b, long c, long d) {
		long result = 0;
		long[] abcd = {a, b, c, d};
		long[] o = new long[4];
		long[] ox = new long[4];
		for (int i = 0; i < 4; i++) {
			ox[i] = pow(2, abcd[i], M);
			o[i] = ox[i] - 1;
		}
		result += (((((ox[0] * o[1]) % M) * o[2]) % M) * ox[3]) % M;
		result += (((((o[0] * ox[1]) % M) * ox[2]) % M) * o[3]) % M;
		result -= (((((o[0] * o[1]) % M) * o[2]) % M) * o[3]) % M;
		if (result < 0) result += M;
		result += (((((ox[0] * ox[1]) % M) * ox[2]) % M) * ox[3]) % M;
		return result % M;
	}
}

import java.util.*;
import java.util.stream.*;

public class Main {
	Scanner sc;
	final int MOD = 998244353;
	int N;
	int[][] p;
	int[] pow2;

	public Main() {
		sc = new Scanner(System.in);
	}

	private void calc() {
		N = sc.nextInt();
		p = new int[N][2];
		for (int i = 0; i < N; i++) {
			p[i][0] = sc.nextInt();
			p[i][1] = sc.nextInt();
		}
		pow2 = new int[N];
		pow2[0] = 0;
		for (int i = 1; i < N; i++)
			pow2[i] = (pow2[i-1]*2+1)%MOD;

		Arrays.sort(p, (a,b) -> Integer.compare(a[1], b[1]));
		for (int i = 0; i < N; i++) p[i][1] = i;
		Arrays.sort(p, (a,b) -> Integer.compare(a[0], b[0]));
		for (int i = 0; i < N; i++) p[i][0] = i;

		int sum = 0;

		for (int i = 0; i < N; i++) {
			sum = (sum + pow2[N-1] + 1)%MOD;

			int a12 = p[i][1];
			int a34 = N-1-p[i][1];
			int a13 = p[i][0];
			int a24 = N-1-p[i][0];
			int a1, a2, a3, a4;
			if (p[i][0] < N/2 && p[i][1] < N/2) {
				a1 = 0;
				for (int j = 0; j < i; j++)
					if (p[j][1] < p[i][1]) a1++;
				a2 = a12 - a1;
				a3 = a13 - a1;
				a4 = a34 - a3;
			} else if (p[i][0] >= N/2 && p[i][1] < N/2) {
				a2 = 0;
				for (int j = i+1; j < N; j++)
					if (p[j][1] < p[i][1]) a2++;
				a1 = a12 - a2;
				a3 = a13 - a1;
				a4 = a34 - a3;
			} else if (p[i][0] < N/2 && p[i][1] >= N/2) {
				a3 = 0;
				for (int j = 0; j < i; j++)
					if (p[j][1] > p[i][1]) a3++;
				a1 = a13 - a3;
				a2 = a12 - a1;
				a4 = a34 - a3;
			} else {
				a4 = 0;
				for (int j = i+1; j < N; j++)
					if (p[j][1] > p[i][1]) a4++;
				a3 = a34 - a4;
				a1 = a13 - a3;
				a2 = a12 - a1;
			}

			int s = (pow2[a12] + pow2[a34])%MOD;
			s = (s + pow2[a13])%MOD;
			s = (s + pow2[a24])%MOD;
			s = mod(s - pow2[a1], MOD);
			s = mod(s - pow2[a2], MOD);
			s = mod(s - pow2[a3], MOD);
			s = mod(s - pow2[a4], MOD);

			s = (pow2[N-1] - s)%MOD;
			sum = (sum + s)%MOD;
		}

		out(sum);
	}

	private int mod(int a, int m) {
		return (a >= 0)?a:(a+m)%m;
	}

	private void out(Object o) {
		System.out.println(o);
		System.out.flush();
	}

	public static void main(String[] args) {
		Main m = new Main();
		m.calc();
	}

}

