import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.TreeMap;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		int[] x = new int[n];
		int[] y = new int[n];
		for (int i = 0; i < n; i++) {
			String[] sa = br.readLine().split(" ");
			x[i] = Integer.parseInt(sa[0]);
			y[i] = Integer.parseInt(sa[1]);
		}
		br.close();

		zaatu(x);
		zaatu(y);
		Obj[] arr = new Obj[n];
		for (int i = 0; i < n; i++) {
			Obj o = new Obj();
			o.x = x[i];
			o.y = y[i];
			arr[i] = o;
		}
		Arrays.sort(arr, (o1, o2) -> o1.x - o2.x);

		int[] lol = new int[n];
		int[] hil = new int[n];
		BIT bit = new BIT(n);
		for (int i = 0; i < n; i++) {
			lol[i] = bit.sum(arr[i].y);
			hil[i] = i - lol[i];
			bit.add(arr[i].y, 1);
		}

		int[] lor = new int[n];
		int[] hir = new int[n];
		bit = new BIT(n);
		for (int i = 0; i < n; i++) {
			int ri = n - 1 - i;
			lor[ri] = bit.sum(arr[ri].y);
			hir[ri] = i - lor[ri];
			bit.add(arr[ri].y, 1);
		}

		int mod = 998244353;
		long ans = n * power(2, n - 1, mod) % mod;
		for (int i = 0; i < n; i++) {
			long val1 = power(2, lol[i], mod);
			long val2 = power(2, hil[i], mod);
			long val3 = power(2, lor[i], mod);
			long val4 = power(2, hir[i], mod);
			long val11 = (val1 - 1 + mod) % mod;
			long val21 = (val2 - 1 + mod) % mod;
			long val31 = (val3 - 1 + mod) % mod;
			long val41 = (val4 - 1 + mod) % mod;
			ans += val11 * val41 % mod * (val2 + val3) % mod;
			ans += val21 * val31 % mod * (val1 + val4) % mod;
			ans %= mod;
		}
		System.out.println(ans - 1);
	}

	static long power(long x, long n, int m) {
		if (n == 0) {
			return 1;
		}
		long val = power(x, n / 2, m);
		val = val * val % m;
		if (n % 2 == 1) {
			val = val * x % m;
		}
		return val;
	}

	static void zaatu(int[] a) {
		TreeMap<Integer, Integer> map = new TreeMap<>();
		for (int i = 0; i < a.length; i++) {
			map.put(a[i], null);
		}
		Integer[] arr = map.keySet().toArray(new Integer[0]);
		int cnt = 0;
		for (Integer i : arr) {
			cnt++;
			map.put(i, cnt);
		}
		for (int i = 0; i < a.length; i++) {
			a[i] = map.get(a[i]);
		}
	}

	static class BIT {
		int n;
		int[] arr;

		public BIT(int n) {
			this.n = n;
			arr = new int[n + 1];
		}

		void add(int idx, int val) {
			for (int i = idx; i <= n; i += i & -i) {
				arr[i] += val;
			}
		}

		int sum(int idx) {
			int sum = 0;
			for (int i = idx; i > 0; i -= i & -i) {
				sum += arr[i];
			}
			return sum;
		}
	}

	static class Obj {
		int x, y;
	}
}

import java.util.*;
import java.util.stream.*;

/**
 * 136-F Enclosed Points
 *
 * 考え方(9/12)
 * 集合Sの各点 p に対し、「何回重複してカウントされるか」を考える。
 * 総和 sum の中で点 p の寄与分(重複カウント分)は以下の通り考えられる。
 * (1) p が含まれる集合 T でカウントされる場合
 * (2) p が含まれない集合 T でカウントされる場合
 *
 * つねに T がすべての部分集合を渡ることに注意。
 * 
 * (1)での寄与分は、p が含まれる集合 T の場合の数であり、2^(N-1)
 * (2)での寄与分を考える。
 *   p がカウントされるためには、長方形領域の中に p がいればよい
 *   そのような集合 T の場合の数が寄与分である。
 *
 *   長方形領域の中に p がいる、とはどのような場合か。
 *           |
 *       1   |   2
 *           |
 *   --------p---------
 *           |
 *       3   |   4
 *           |
 *   上で、p のまわりに T が広がっている場合である。
 *   この逆(p がはじっこにあって長方形領域から外れる場合)は、
 *   (1,2)にしか T の元がない場合
 *   (1,3)にしか T の元がない場合
 *   (2,4)にしか T の元がない場合
 *   (3,4)にしか T の元がない場合
 *   これらの場合の数で重複してカウントしている場合、つまり
 *   (1)にしか T の元がない場合～(4)にしか T の元がない場合
 *   を引くと場合の数が出る。これを全体の場合の数から引けばよい。
 *   この場合の数は、Xi, Yi をそれぞれ小さい順に 0, 1, 2, ... ,N と番号を
 *   振りなおすと数えやすくなる。
 *   全体の場合の数は 2^(N-1)-1 (-1 とするのは、空集合を除くため)
 *   p=(xi, yi) とした場合、
 *   (1,2)にしか T の元がない場合 2^yi-1 (-1 は空集合を除くため)
 *   (1,3)                        2^xi-1
 *   (2,4)                        2^(N-1-xi)-1
 *   (3,4)                        2^(N-1-yi)-1
 *   同様に
 *   (1)にしか T の元がない場合 (1) にある点の数を a1 とすると、2^a1-1
 *   a1 は逐次カウントするが、xi が小さいものから順に yi を(昇順)挿入リストに
 *   入れていくと、リストに入れた index が a1 になる。
 *
 *   上のアルゴリズムで総和 sum は以下のようになる。
 *   sum = (N-4)(2^N-1)+ sigma(i=0,1, ... ,N-1, 2^(a1i)+2^(a2i)+2^(a3i)+2^(a4i))
 *
 * 例題コピー用
 *   (1) 3 -1 3 2 1 3 -2 (答え13)
 *   (2) 4 1 4 2 1 3 3 4 2 (答え34)
 *   (3) 10 19 -11 -3 -12 5 3 3 -15 8 -14 -9 -20 10 -9 0 2 -7 17 6 -6 (答え7222)
 */
public class Make {
	Scanner sc;
	final int MOD = 998244353;
	int N;
	int[][] p;
	int[] pow2;

	int[] ylist;
	int ylistSize;

//=============
// constructor
//
	public Make() {
		sc = new Scanner(System.in);
	}

//==================
// instance methods
//
	/**
	 * アルゴリズム本体
	 */
	private void calc() {
		N = sc.nextInt();
		p = new int[N][2]; // xpos:[][0], ypos:[][1]
		for (int i = 0; i < N; i++) {
			p[i][0] = sc.nextInt();
			p[i][1] = sc.nextInt();
		}
		// 2 のべきのテーブル pow2[i] = 2^i mod MOD
		pow2 = new int[N+1]; // 
		pow2[0] = 1;
		for (int i = 1; i < N+1; i++)
			pow2[i] = (pow2[i-1]*2)%MOD;
		// 既出 y 座標 の昇順リスト
		ylist = new int[N];
		ylistSize = 0;

		// 番号付け替え(ypos)
		Arrays.sort(p, (a,b) -> Integer.compare(a[1], b[1]));
		for (int i = 0; i < N; i++) p[i][1] = i;
		// 番号付け替え(xpos)
		Arrays.sort(p, (a,b) -> Integer.compare(a[0], b[0]));
		for (int i = 0; i < N; i++) p[i][0] = i;

		// 各点ごとに数値を計上していく
		int sum = (int) (((long)N-4)*(pow2[N]-1)%MOD);

		// 既出 y 座標 の昇順リスト
		for (int i = 0; i < N; i++) {
			if (i == N/2) ylistSize = 0;
			boolean former = (i < N/2);
			int j = (former)?i:N-1+N/2-i;

			// yi が p[i][1] の直前となる index を探す
			int yi = insertYPos(p[j][1]);
			//
			int a1 = yi;
			// a12 = p[j][1]
			int a2 = p[j][1] - a1;
			// a13 = p[j][0]
			int a3 = (former)?p[j][0] - a1 : p[j][0] - a2;
			// a34 = N-1-p[j][1]
			int a4 = N-1-p[j][1] - a3;

			int s = (pow2[a1] + pow2[a2])%MOD;
			s = (s + pow2[a3])%MOD;
			s = (s + pow2[a4])%MOD;
			sum = (sum + s)%MOD;
		}

		out(sum);
	}

	/**
	 * バイナリサーチにより、
	 * 指定された y 座標が list のどこに挿入されるべきか検索/挿入し、
	 * 挿入した index を返します。
	 */
	private int insertYPos(int y) {
		int yi = -1;
		int l = -1;
		int r = ylistSize;
		while (true) {
			yi = (l+r+2)/2-1;
			if (l == yi) break;
			if (ylist[yi] > y) r = yi;
			else l = yi;
		}
		if (yi < ylistSize) yi++;
		// yi の位置に値 y を挿入する。
		System.arraycopy(ylist, yi, ylist, yi+1, ylistSize - yi);
		ylist[yi] = y;
		ylistSize++;
		//list.add(yi, y);
		return yi;
	}

	private void out(Object o) {
		System.out.println(o);
		System.out.flush();
	}

//======
// main
//
	public static void main(String[] args) {
		Make m = new Make();
		m.calc();
	}

}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

public class Main {

	static final long mod = 998244353L;

	public static void main(String[] args) {
		Main mainObj = new Main();
		mainObj.solve();
	}

	void solve() {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();

		ArrayList<Coodinate> coodinateList = new ArrayList<>();
		for(int i = 0; i < n; i++) {
			int x = sc.nextInt();
			int y = sc.nextInt();
			coodinateList.add(new Coodinate(x,y,i));
		}

		sc.close();

		Comparator<Coodinate> yComparator = Comparator.comparing(Coodinate::getY);
		Comparator<Coodinate> xComparator = Comparator.comparing(Coodinate::getX);
		coodinateList.sort(yComparator);
		for(int i = 0; i < n; i++) {
			coodinateList.get(i).setY(i);
		}

		coodinateList.sort(xComparator);
		for(int i = 0; i < n; i++) {
			coodinateList.get(i).setX(i);
		}

		int[] firstQuadrant = new int[n];
		int[] secondQuadrant = new int[n];
		int[] thirdQuadrant = new int[n];
		int[] forthQuadrant = new int[n];

		// 平面走査する
		SumSegTree leftTree = new SumSegTree(n);
		// xの小さい方
		for(int i = 0; i < n; i++) {

			Coodinate nowCoodinate = coodinateList.get(i);

			int numOfThirdQuadrant = leftTree.getValue(0, nowCoodinate.getY(), 0, 0, -1);
			thirdQuadrant[i] = numOfThirdQuadrant;
			secondQuadrant[i] = i - numOfThirdQuadrant;

			leftTree.upDate(nowCoodinate.getY(), 1);
		}

		SumSegTree rightTree = new SumSegTree(n);
		// xの大きい方
		for(int i = n - 1; i >= 0; i--) {

			Coodinate nowCoodinate = coodinateList.get(i);

			int numOfForthQuadrant = rightTree.getValue(0, nowCoodinate.getY(), 0, 0, -1);
			forthQuadrant[i] = numOfForthQuadrant;
			//System.out.println(numOfForthQuadrant);
			firstQuadrant[i] = (n - 1) - i - numOfForthQuadrant;
			rightTree.upDate(nowCoodinate.getY(), 1);
		}

		long ans = 0;
		long[] powArr = new long[n+1];
		for(int i = 0 ; i < n; i++) {
			powArr[i] = -1;
		}
		for(int i = 0; i < n ;i++) {
			int first = firstQuadrant[i];
			int second = secondQuadrant[i];
			int third = thirdQuadrant[i];
			int forth = forthQuadrant[i];

			long firstPow,secondPow,thirdPow,forthPow;
			if(powArr[first] != -1) {
				firstPow = powArr[first];
			}else {
				firstPow = powWithMod(2, first);
				powArr[first] = firstPow;
			}

			if(powArr[second] != -1) {
				secondPow = powArr[second];
			}else {
				secondPow = powWithMod(2, second);
				powArr[second] = secondPow;
			}

			if(powArr[third] != -1) {
				thirdPow = powArr[third];
			}else {
				thirdPow = powWithMod(2, third);
				powArr[third] = thirdPow;
			}

			if(powArr[forth] != -1) {
				forthPow = powArr[forth];
			}else {
				forthPow = powWithMod(2, forth);
				powArr[forth] = forthPow;
			}

			ans = calcMod(ans + calcMod(calcMod(calcMod(firstPow*(secondPow-1))*thirdPow)*(forthPow - 1)));
			ans = calcMod(ans + calcMod(calcMod(calcMod((firstPow-1)*secondPow)*(thirdPow - 1))*forthPow));
			ans = calcMod(ans - calcMod(calcMod(calcMod((firstPow-1)*(secondPow - 1))*(thirdPow - 1))*(forthPow - 1)));
			ans = calcMod(ans + calcMod(calcMod(calcMod(firstPow*secondPow)*thirdPow)*forthPow));
		}

		System.out.println(ans);
	}

	long calcMod(long value) {
		if(value < 0) {
			while(value > 0) {
				value += mod;
			}
			return value;
		}else {
			return value%mod;	
		}
	}

	long powWithMod(int base, int times) {
		long retValue = 1;
		for(int i = 0;i < times; i++) {
			retValue = calcMod(retValue*base);
		}
		return retValue;
	}

	class SumSegTree{
		int[] arr;
		int n;
		int arrSize;

		SumSegTree(int n){
			this.n = n;
			arrSize = 1;
			while(n > arrSize) {
				arrSize *= 2;
			}

			// 最初は和もvalueも0なので何もしない
			this.arr = new int[arrSize*2 - 1];
		}

		void upDate(int pos, int value) {
			int segIndex = pos + arrSize - 1;
			int beforeValue = arr[segIndex];
			arr[segIndex] = value;

			int diff = value - beforeValue;
			while(segIndex > 0) {
				segIndex = (segIndex - 1)/2;
				arr[segIndex] = arr[segIndex] + diff;
			}
		}

		// a, b間の和を取得
		int getValue(int a, int b, int k, int l, int r) {

			if(r < 0) {
				r = arrSize;
			}

			if(r <= a || b <= l) {
				return 0;
			}
			if(a <= l && r <= b) {
				return arr[k];
			}

			return getValue(a, b, 2*k + 1, l, (l+r)/2) + getValue(a,b,2*k + 2, (l+r)/2, r);
		}
	}

	class Coodinate{
		int x;
		int y;
		int no;

		Coodinate(int x, int y, int no){
			this.x = x;
			this.y = y;
			this.no = no;
		}

		int getX() {
			return x;
		}

		int getY() {
			return y;
		}

		void setX(int x) {
			this.x = x;
		}

		void setY(int y) {
			this.y = y;
		}

		int getNo() {
			return no;
		}
	}
}

