            Arrays.fill(quadrantCount, 0);
        }
    }

    static int p2(int base) {
        if (base==0) return 1;
        if (base%2==0) {int temp = p2(base/2); return (temp*temp);}
        return 2*p2(base-1);
    }

    public static void main(String[] args) {
