        }

        long ans = 0;

        /*for (Point point: points){
            out.println("(" + point.x + " " + ", " + point.y + ")");
        }*/

        // for each point find, how many subsets it contributes to.
        for (Point point: points) {

            ans += p2(n);

            for (int i=0;i<4;i++) {
