//                out.printf("%d ", point.quadrantCount[i] + point.quadrantCount[(i+1)%4]);
            }
//            out.println();

            for (int i=0;i<4;i++) {
                ans += p2(point.quadrantCount[i]);
//                out.printf("%d ", point.quadrantCount[i]);
            }
//            out.println();

            ans--;

//            out.println(ans);
        }

        out.println(ans);
        out.close();

    }

