import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.BufferedWriter;
import java.util.InputMismatchException;
import java.io.IOException;
import java.util.Random;
import java.util.ArrayList;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.util.Collections;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        FEnclosedPoints solver = new FEnclosedPoints();
        solver.solve(1, in, out);
        out.close();
    }

    static class FEnclosedPoints {
        static final int MOD = 998244353;
        static final int MASK = (int) ((1L << 31) - 1);
        static final int OFFSET = 1 << 30;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            ArrayList<Long> al = new ArrayList<>();
            int[] x = new int[n];
            int[] y = new int[n];
            int[] p2 = new int[n + 1];
            p2[0] = 1;
            for (int i = 0; i < n; i++) {
                p2[i + 1] = 2 * p2[i];
                if (p2[i + 1] >= MOD) p2[i + 1] -= MOD;
                x[i] = in.nextInt() + OFFSET;
                y[i] = in.nextInt() + OFFSET;

                al.add(((long) x[i] << 31) + y[i]);
            }

            long ans = (n * 1L * p2[n - 1]) % MOD;

            ans += (n * 1L * (p2[n - 1] - 1)) % MOD;

            ans -= (4L * (p2[n] - n - 1 + MOD)) % MOD;

            ans %= MOD;
            ans += MOD;
            ans %= MOD;
            Collections.sort(al);
            TreapBST.Treap t1 = null;

            for (int i = 0; i < n; i++) {
                long v = al.get(i);
                int down1 = FEnclosedPoints.TreapBST.rank(t1, (int) (v & MASK));
                int up1 = i - down1;
                ans += p2[down1] - 1;
                ans += p2[up1] - 1;
                t1 = FEnclosedPoints.TreapBST.insert2(t1, (int) (v & MASK));
            }

            t1 = null;

            for (int i = n - 1; i >= 0; i--) {
                long v = al.get(i);
                int down1 = FEnclosedPoints.TreapBST.rank(t1, (int) (v & MASK));
                int up1 = n - 1 - i - down1;
//            out.println(i + " " + up1 + " " + down1 + " " + ((v & MASK) - OFFSET) + " " + ((v>>31)-OFFSET));
                ans += p2[down1] - 1;
                ans += p2[up1] - 1;
                t1 = FEnclosedPoints.TreapBST.insert2(t1, (int) (v & MASK));
            }
            ans %= MOD;
            ans += MOD;
            ans %= MOD;
            out.println(ans);
        }

        static class TreapBST {
            static Random random = new Random();

            static int getSize(TreapBST.Treap root) {
                return root == null ? 0 : root.size;
            }

            static TreapPair split(TreapBST.Treap root, int minRight) {
                if (root == null)
                    return new TreapPair(null, null);
                if (root.key >= minRight) {
                    TreapPair leftSplit = split(root.left, minRight);
                    root.left = leftSplit.right;
                    root.update();
                    leftSplit.right = root;
                    return leftSplit;
                } else {
                    TreapPair rightSplit = split(root.right, minRight);
                    root.right = rightSplit.left;
                    root.update();
                    rightSplit.left = root;
                    return rightSplit;
                }
            }

            static int rank(TreapBST.Treap root, int x) {
                if (root == null) return 0;
                if (root.key >= x) return rank(root.left, x);
                else return getSize(root.left) + 1 + rank(root.right, x);
            }

            static TreapBST.Treap insert2(TreapBST.Treap root, int key) { // alternative implementation
                return insert_(root, new Treap(key));
            }

            static TreapBST.Treap insert_(TreapBST.Treap root, TreapBST.Treap node) {
                if (root == null) {
                    return node;
                }
                if (root.prio < node.prio) {
                    TreapPair t = split(root, node.key);
                    node.left = t.left;
                    node.right = t.right;
                    node.update();
                    return node;
                }
                if (node.key < root.key) {
                    root.left = insert_(root.left, node);
                    root.update();
                    return root;
                } else {
                    root.right = insert_(root.right, node);
                    root.update();
                    return root;
                }
            }

            static class Treap {
                int key;
                long prio;
                TreapBST.Treap left;
                TreapBST.Treap right;
                int size;

                Treap(int key) {
                    this.key = key;
                    prio = random.nextLong();
                    size = 1;
                }

                void update() {
                    size = 1 + getSize(left) + getSize(right);
                }

            }

            static class TreapPair {
                TreapBST.Treap left;
                TreapBST.Treap right;

                TreapPair(TreapBST.Treap left, TreapBST.Treap right) {
                    this.left = left;
                    this.right = right;
                }

