    static class FEnclosedPoints {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] x = new int[n];
            int[] y = new int[n];
            in.readIntArrays(x, y);

            ArrayUtils.compress(x);
            ArrayUtils.compress(y);
            List<IntIntPair> points = IntStream.range(0, n).mapToObj(i -> new IntIntPair(x[i], y[i]))
                    .sorted()
                    .collect(Collectors.toList());

            long[] a1 = new long[n];
            long[] a2 = new long[n];
            count(n, points, a1, a2);

            Collections.reverse(points);
            long[] a3 = new long[n];
            long[] a4 = new long[n];
            count(n, points, a3, a4);
            ArrayUtils.reverse(a3);
            ArrayUtils.reverse(a4);

            long ans = 0;
            for (int i = 0; i < n; i++) {
                {
                    long tmp = a1[i];
                    tmp = (tmp * (a2[i] - 1)) % MiscUtils.MOD7;
                    tmp = (tmp * (a3[i] - 1)) % MiscUtils.MOD7;
                    tmp = (tmp * a4[i]) % MiscUtils.MOD7;
                    ans = (ans + tmp) % MiscUtils.MOD7;
                }
                {
                    long tmp = a1[i] - 1;
                    tmp = (tmp * a2[i]) % MiscUtils.MOD7;
                    tmp = (tmp * a3[i]) % MiscUtils.MOD7;
                    tmp = (tmp * (a4[i] - 1)) % MiscUtils.MOD7;
                    ans = (ans + tmp) % MiscUtils.MOD7;
                }
                {
                    long tmp = a1[i] - 1;
                    tmp = (tmp * (a2[i] - 1)) % MiscUtils.MOD7;
                    tmp = (tmp * (a3[i] - 1)) % MiscUtils.MOD7;
                    tmp = (tmp * (a4[i] - 1)) % MiscUtils.MOD7;
                    ans = (ans - tmp) % MiscUtils.MOD7;
                }
                ans = (ans + IntegerUtils.power(2, n - 1, MiscUtils.MOD7)) % MiscUtils.MOD7;
            }

            out.printLine(ans);
        }

        private void count(int n, List<IntIntPair> points, long[] a1, long[] a2) {
            FenwickTree tree = new FenwickTree(n);
            for (int i = 0; i < n; i++) {
                int yy = points.get(i).second;
                a1[i] = IntegerUtils.power(2, tree.get(0, yy), MiscUtils.MOD7);
                a2[i] = IntegerUtils.power(2, tree.get(yy, n), MiscUtils.MOD7);
                tree.add(yy, 1);
            }
        }

    }

