class Solver
{
    public void Solve(Scanner sc)
    {
        var N = sc.Int;
        ModInt res = ModInt.Pow(2, N - 1) * N;
        var XY = sc.ArrInt2D(N);
        var d = Compression(XY.Select(v => v[0]).ToArray());
        Array.Sort(XY, (a, b) => a[1] - b[1]);
        var seg = new BIT(N);
        var pow2 = new ModInt[N + 1];
        pow2[0] = 1;
        for (int i = 0; i < N; i++)
        {
            pow2[i + 1] = pow2[i] * 2;
        }
        foreach (var A in XY)
        {
            int x = d[A[0]];
            //第i象限にある点
            var p = new[] { N - x - 1 -(seg[N]- seg[x]), x - seg[x], seg[x], seg[N]-seg[x] };
            for (int j = 0; j < (1 << 4); j++)
            {
                if (((1 & j >> 0) == 0 || (1 & j >> 2) == 0) && ((1 & j >> 1) == 0 || (1 & j >> 3) == 0))
                    continue;
                ModInt now = 1;
                for (int k = 0; k < 4; k++)
                    if ((1 & j >> k) == 1)
                        now *=pow2[p[k]] - 1;
                res += now;
            }
            seg.add(x+1, 1);
        }
        WriteLine(res);
    }
    public static Dictionary<T, int> Compression<T>(IList<T> A, int d = 0, Comparison<T> cmp = null)
    {
        cmp = cmp ?? Comparer<T>.Default.Compare;
        var dic = new Dictionary<T, int>();
        var cp = A.ToArray();
        Array.Sort(cp, (a, b) => cmp(a, b));
        for (var i = 0; i < cp.Length; i++)
            if (!dic.ContainsKey(cp[i]))
                dic[cp[i]] = d++;
        return dic;
    }
}

