readonly struct Point : IEquatable<Point>, IComparable<Point>
{
    public readonly int x;
    public readonly int y;
    public Point(ConsoleReader cr) : this(cr, cr) { }
    public Point(int x, int y)
    {
        this.x = x;
        this.y = y;
    }

    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public void Deconstruct(out int v1, out int v2) { v1 = x; v2 = y; }
    public static implicit operator Point((int x, int y) tuple) => new Point(tuple.x, tuple.y);
    public double Distance(Point other) => Math.Sqrt(Distance2(other));
    private long Distance2(Point other)
    {
        var p = other - this;
        return (long)p.x * p.x + (long)p.y * p.y;
    }
    public long Inner(Point other) => (long)x * other.x + (long)y * other.y;
    public long Cross(Point other) => (long)x * other.y - (long)y * other.x;
    public static Point operator +(Point a, Point b) => new Point(a.x + b.x, a.y + b.y);
    public static Point operator -(Point a, Point b) => new Point(a.x - b.x, a.y - b.y);
    public int CompareTo(Point other)
    {
        var xd = this.x.CompareTo(other.x);
        if (xd != 0) return xd;
        return this.y.CompareTo(other.y);
    }

    public bool Equals(Point other) => this.x == other.x && this.y == other.y;
    public override bool Equals(object obj) => obj is Point && Equals((Point)obj);
    public override int GetHashCode() => HashCode.Combine(x, y);
    public override string ToString() => $"({x}, {y})";
}


[System.Diagnostics.DebuggerTypeProxy(typeof(BinaryIndexedTreeDebugView))]
class BinaryIndexedTree
{
    private int Operate(int v, int w) => v + w;
    public void Add(int i, int w)
    {
        for (++i; i < tree.Length; i += (i & -i))
            tree[i] = Operate(tree[i], w);
    }
    public int Sum(int toExclusive)
    {
        int res = 0;
        for (var i = toExclusive; i > 0; i -= (i & -i))
            res = Operate(res, tree[i]);
        return res;
    }

    public int Sum(int from, int toExclusive) => Sum(toExclusive) - Sum(from);
    public int LowerBound(int w)
    {
        if (w <= 0) return 0;
        int x = 0;
        for (int k = 1 << MSB(tree.Length - 1); k > 0; k >>= 1)
        {
            var nx = x + k;
            if (nx < tree.Length && tree[nx] < w)
            {
                x = nx;
                w -= tree[nx];
            }
        }
        return x;
    }

    private int[] tree;
    public int Length => tree.Length - 1;
    public int Slice(int from, int length) => Sum(from, from + length);

    public BinaryIndexedTree(int size)
    {
        tree = new int[size + 1];
    }
    public BinaryIndexedTree(int[] initArray) : this(initArray.Length)
    {
        Array.Copy(initArray, 0, tree, 1, initArray.Length);
        for (int i = 1; i < tree.Length; i++)
        {
            var ni = i + (i & -i);
            if (ni < tree.Length)
                tree[ni] = Operate(tree[i], tree[ni]);
        }
    }

    public class BinaryIndexedTreeDebugView
    {
        private BinaryIndexedTree bit;
        public BinaryIndexedTreeDebugView(BinaryIndexedTree bit)
        {
            this.bit = bit;
        }

        [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.RootHidden)]
        public string[] Tree
        {
            get
            {
                var res = new string[bit.tree.Length - 1];
                for (var i = 0; i < res.Length; i++)
                {
                    res[i] = $"data:{bit.tree[i + 1]} single:{bit.Sum(i, i + 1)}";
                }
                return res;
            }
        }
    }
}

using System;
using System.Linq;
using CompLib.Collections.Generic;
using CompLib.Mathematics;
using CompLib.Util;

public class Program
{
    private int N;
    private int[] X, Y;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        X = new int[N];
        Y = new int[N];
        for (int i = 0; i < N; i++)
        {
            X[i] = sc.NextInt();
            Y[i] = sc.NextInt();
        }

        int[] sortedByX = new int[N].Select((i, index) => index).ToArray();
        int[] sortedByY = new int[N].Select((i, index) => index).ToArray();

        Array.Sort(sortedByX, (l, r) => X[l].CompareTo(X[r]));
        Array.Sort(sortedByY, (l, r) => Y[l].CompareTo(Y[r]));
        int[] yy = new int[N];
        for (int i = 0; i < N; i++)
        {
            yy[sortedByY[i]] = i;
        }

        // iを含む集合が何通りか?
        // iを含まない集合が何通りか?

        ModInt ans = N * (ModInt.Pow(2, N) - 1);
        var st1 = new SegmentTree<int>((l, r) => l + r, 0);
        var st2 = new SegmentTree<int>((l, r) => l + r, 0);
        for (int i = 0; i < N; i++)
        {
            int j = N - 1 - i;
            int yi = yy[sortedByX[i]];
            int yj = yy[sortedByX[j]];
            // 上下左右
            ans -= (ModInt.Pow(2, i) - 1) * 4;
            // 左上
            ans += ModInt.Pow(2, st1.Query(0, yi)) - 1;
            // 右上
            ans += ModInt.Pow(2, st1.Query(yi + 1, N)) - 1;
            // 左下
            ans += ModInt.Pow(2, st2.Query(0, yj)) - 1;
            // 右下
            ans += ModInt.Pow(2, st2.Query(yj + 1, N)) - 1;

            st1[yi] = 1;
            st2[yj] = 1;
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

namespace CompLib.Collections.Generic
{
    using System;

    public class SegmentTree<T>
    {
        // 制約に合った2の冪
        private const int N = 1 << 21;
        private T[] _array;

        private T _identity;
        private Func<T, T, T> _operation;

        public SegmentTree(Func<T, T, T> operation, T identity)
        {
            _identity = identity;
            _operation = operation;
            _array = new T[N * 2];
            for (int i = 1; i < N * 2; i++)
            {
                _array[i] = _identity;
            }
        }

        /// <summary>
        /// A[i]をnに更新 O(log N)
        /// </summary>
        /// <param name="i"></param>
        /// <param name="n"></param>
        public void Update(int i, T n)
        {
            i += N;
            _array[i] = n;
            while (i > 1)
            {
                i /= 2;
                _array[i] = _operation(_array[i * 2], _array[i * 2 + 1]);
            }
        }

        private T Query(int left, int right, int k, int l, int r)
        {
            if (r <= left || right <= l)
            {
                return _identity;
            }

            if (left <= l && r <= right)
            {
                return _array[k];
            }

            return _operation(Query(left, right, k * 2, l, (l + r) / 2),
                Query(left, right, k * 2 + 1, (l + r) / 2, r));
        }

        /// <summary>
        /// A[left] op A[left+1] ... op A[right-1]を求める
        /// </summary>
        /// <param name="left"></param>
        /// <param name="right"></param>
        /// <returns></returns>
        public T Query(int left, int right)
        {
            return Query(left, right, 1, 0, N);
        }

        public T this[int i]
        {
            set { Update(i, value); }
            get { return _array[i + N]; }
        }
    }
}

// https://bitbucket.org/camypaper/complib
namespace CompLib.Mathematics
{
    #region ModInt

    /// <summary>
    /// [0,<see cref="Mod"/>) までの値を取るような数
    /// </summary>
    public struct ModInt
    {
        /// <summary>
        /// 剰余を取る値．
        /// </summary>
        public const long Mod = 998244353;

        /// <summary>
        /// 実際の数値．
        /// </summary>
        public long num;

        /// <summary>
        /// 値が <paramref name="n"/> であるようなインスタンスを構築します．
        /// </summary>
        /// <param name="n">インスタンスが持つ値</param>
        /// <remarks>パフォーマンスの問題上，コンストラクタ内では剰余を取りません．そのため，<paramref name="n"/> ∈ [0,<see cref="Mod"/>) を満たすような <paramref name="n"/> を渡してください．このコンストラクタは O(1) で実行されます．</remarks>
        public ModInt(long n)
        {
            num = n;
        }

        /// <summary>
        /// このインスタンスの数値を文字列に変換します．
        /// </summary>
        /// <returns>[0,<see cref="Mod"/>) の範囲内の整数を 10 進表記したもの．</returns>
        public override string ToString()
        {
            return num.ToString();
        }

        public static ModInt operator +(ModInt l, ModInt r)
        {
            l.num += r.num;
            if (l.num >= Mod) l.num -= Mod;
            return l;
        }

        public static ModInt operator -(ModInt l, ModInt r)
        {
            l.num -= r.num;
            if (l.num < 0) l.num += Mod;
            return l;
        }

        public static ModInt operator *(ModInt l, ModInt r)
        {
            return new ModInt(l.num * r.num % Mod);
        }

        public static implicit operator ModInt(long n)
        {
            n %= Mod;
            if (n < 0) n += Mod;
            return new ModInt(n);
        }

        /// <summary>
        /// 与えられた 2 つの数値からべき剰余を計算します．
        /// </summary>
        /// <param name="v">べき乗の底</param>
        /// <param name="k">べき指数</param>
        /// <returns>繰り返し二乗法により O(N log N) で実行されます．</returns>
        public static ModInt Pow(ModInt v, long k)
        {
            return Pow(v.num, k);
        }

        /// <summary>
        /// 与えられた 2 つの数値からべき剰余を計算します．
        /// </summary>
        /// <param name="v">べき乗の底</param>
        /// <param name="k">べき指数</param>
        /// <returns>繰り返し二乗法により O(N log N) で実行されます．</returns>
        public static ModInt Pow(long v, long k)
        {
            long ret = 1;
            for (k %= Mod - 1; k > 0; k >>= 1, v = v * v % Mod)
                if ((k & 1) == 1)
                    ret = ret * v % Mod;
            return new ModInt(ret);
        }

        /// <summary>
        /// 与えられた数の逆元を計算します．
        /// </summary>
        /// <param name="v">逆元を取る対象となる数</param>
        /// <returns>逆元となるような値</returns>
        /// <remarks>法が素数であることを仮定して，フェルマーの小定理に従って逆元を O(log N) で計算します．</remarks>
        public static ModInt Inverse(ModInt v)
        {
            return Pow(v, Mod - 2);
        }
    }

    #endregion

    #region Binomial Coefficient

    public class BinomialCoefficient
    {
        public ModInt[] fact, ifact;

        public BinomialCoefficient(int n)
        {
            fact = new ModInt[n + 1];
            ifact = new ModInt[n + 1];
            fact[0] = 1;
            for (int i = 1; i <= n; i++)
                fact[i] = fact[i - 1] * i;
            ifact[n] = ModInt.Inverse(fact[n]);
            for (int i = n - 1; i >= 0; i--)
                ifact[i] = ifact[i + 1] * (i + 1);
            ifact[0] = ifact[1];
        }

        public ModInt this[int n, int r]
        {
            get
            {
                if (n < 0 || n >= fact.Length || r < 0 || r > n) return 0;
                return fact[n] * ifact[n - r] * ifact[r];
            }
        }

        public ModInt RepeatedCombination(int n, int k)
        {
            if (k == 0) return 1;
            return this[n + k - 1, k];
        }
    }

    #endregion
}


