			X = x; Y = y;
		}
	}
	public void Solve(){

		var h = new HashSet<int>();
		for(int i=0;i<N;i++){
			h.Add(X[i]);
			h.Add(Y[i]);
		}
		var hl = h.ToList();
		hl.Sort();
		var di = new Dictionary<int,int>();
		for(int i=0;i<hl.Count;i++){
			di.Add(hl[i], i);
		}
		for(int i=0;i<N;i++){
			X[i] = di[X[i]];
			Y[i] = di[Y[i]];
		}

		mlong[] Pow2 = new mlong[N + 1];
		Pow2[0] = 1;
		for(int i=1;i<=N;i++) Pow2[i] = Pow2[i-1] * 2;


		Pair[] P = new Pair[N];
		for(int i=0;i<N;i++){
			P[i] = new Pair(X[i], Y[i]);
		}

		Array.Sort(P, (p, q) => p.X.CompareTo(q.X));

		int M = di.Count + 10;
		var BT0 = new BIT(M + 10);
		var BT1 = new BIT(M + 10);
		for(int i=0;i<N;i++) BT1.Add(P[i].Y + 1, 1);

