		for(int i=0;i<N;i++){
			BT1.Add(P[i].Y + 1, -1);
			mlong p0 = Pow2[N-1];


			int[] cc = new int[4];
			cc[0] = BT0.Sum(P[i].Y);
			cc[1] = BT0.Sum(M) - cc[0];
			cc[2] = BT1.Sum(P[i].Y);
			cc[3] = BT1.Sum(M) - cc[2];
//Console.WriteLine(String.Join(" ",cc));
			for(int t=0;t<(1<<4);t++){
				if(((t & 0x9) == 0x9) || ((t & 0x6) == 0x6)){
					mlong cnt = 1;
					for(int j=0;j<4;j++){
						if((t >> j) % 2 == 0) continue;
						cnt *= (Pow2[cc[j]] - 1);
					}
//Console.WriteLine("t;{0}, cnt:{1}",t,cnt);				
					p0 += cnt;
				}
			}
			prob += p0;
//Console.WriteLine(p0);
