    public override string ToString() => $"({x}, {y})";
}


[System.Diagnostics.DebuggerTypeProxy(typeof(BinaryIndexedTreeDebugView))]
class BinaryIndexedTree
{
    private int Operate(int v, int w) => v + w;
    public void Add(int i, int w)
    {
        for (++i; i < tree.Length; i += (i & -i))
            tree[i] = Operate(tree[i], w);
    }
    public int Sum(int toExclusive)
    {
        int res = 0;
        for (var i = toExclusive; i > 0; i -= (i & -i))
            res = Operate(res, tree[i]);
        return res;
    }

    public int Sum(int from, int toExclusive) => Sum(toExclusive) - Sum(from);
    public int LowerBound(int w)
    {
        if (w <= 0) return 0;
        int x = 0;
        for (int k = 1 << MSB(tree.Length - 1); k > 0; k >>= 1)
        {
            var nx = x + k;
            if (nx < tree.Length && tree[nx] < w)
            {
                x = nx;
                w -= tree[nx];
            }
        }
        return x;
    }

    private int[] tree;
    public int Length => tree.Length - 1;
    public int Slice(int from, int length) => Sum(from, from + length);

    public BinaryIndexedTree(int size)
    {
        tree = new int[size + 1];
    }
    public BinaryIndexedTree(int[] initArray) : this(initArray.Length)
    {
        Array.Copy(initArray, 0, tree, 1, initArray.Length);
        for (int i = 1; i < tree.Length; i++)
        {
            var ni = i + (i & -i);
            if (ni < tree.Length)
                tree[ni] = Operate(tree[i], tree[ni]);
        }
    }

    public class BinaryIndexedTreeDebugView
    {
        private BinaryIndexedTree bit;
        public BinaryIndexedTreeDebugView(BinaryIndexedTree bit)
        {
            this.bit = bit;
        }

        [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.RootHidden)]
        public string[] Tree
        {
            get
            {
                var res = new string[bit.tree.Length - 1];
                for (var i = 0; i < res.Length; i++)
                {
                    res[i] = $"data:{bit.tree[i + 1]} single:{bit.Sum(i, i + 1)}";
                }
                return res;
            }
        }
    }
}

using System;
using System.Linq;

class F
{
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var ps = new int[n].Select(_ => Console.ReadLine().Split().Select(int.Parse).ToArray()).OrderBy(p => p[0]).ToArray();

		var rs = ps.Select(p => p[1]).OrderBy(x => x).ToList();
		var ls = rs.Take(0).ToList();

		var c = MInt(n * MPow(2, n) - n);
		for (int i = 0; i < n; i++)
		{
			var v = ps[i][1];
			var ri = rs.BinarySearch(v);
			// Time Test
			//rs.RemoveAt(ri);
			var li = ~ls.BinarySearch(v);
			ls.Insert(li, v);

			c -= MPow(2, i) + MPow(2, n - 1 - i) + MPow(2, li + ri) + MPow(2, n - 1 - li - ri);
			c += MPow(2, li) + MPow(2, i - li) + MPow(2, ri) + MPow(2, n - 1 - i - ri);
			c = MInt(c);
		}
		Console.WriteLine(c);
	}

	const int M = 998244353;
	static long MPow(long b, long i)
	{
		for (var r = 1L; ; b = b * b % M)
		{
			if (i % 2 > 0) r = r * b % M;
			if ((i /= 2) < 1) return r;
		}
	}
	static long MInt(long x) => (x %= M) < 0 ? x + M : x;
}

