                c += Mod.Pow(2, (int)left.Sum(y, N) - 1) - 1;
                c += Mod.Pow(2, (int)right.Sum(y + 1) - 1) - 1;
                c += Mod.Pow(2, (int)left.Sum(y + 1) - 1) - 1;


                c -= Mod.Pow(2, (int)right.Sum(y, y + 1) - 1) - 1;
                c -= Mod.Pow(2, (int)left.Sum(y, y + 1) - 1) - 1;
                c -= Mod.Pow(2, j) - 1;
                c -= Mod.Pow(2, gp[i].Count - j - 1) - 1;


                res += c;
            }

            foreach (var y in gp[i])
                right.Add(y, -1);
        }


