            bitR.Add(ys[i], 1);
        }
        points.Sort(p => p.x);

        foreach (var p in points)
            Calc(p);
        return res;
    }
    void Calc(Point p)
    {
        bitR.Add(p.y, -1);
        int hidariue, hidarishita, migiue, migishita;
        {
