    {
        public class Point
        {
            public long x;
            public long y;

            // quadrant = 象限
            public long[] q = new long[5];
        }

        public IEnumerable<string> Solve()
        {
            var n = Scan;
            var x = new List<long>();
            var y = new List<long>();
            for (long i = 0; i < n; i++)
            {
                x.Add(Scan);
                y.Add(Scan);
            }
            var xx = x.Select((xxx, i) => new { xxx, i }).OrderBy(p => p.xxx).ToArray();
            var yy = y.Select((yyy, i) => new { yyy, i }).OrderBy(p => p.yyy).ToArray();
            var ps = new Point[n];
            for (long i = 0; i < n; i++)
            {
                ps[i] = new Point();
            }
            for (long i = 0; i < n; i++)
            {
                ps[xx[i].i].x = i;
                ps[yy[i].i].y = i;
            }
            ps = ps.OrderBy(xs => xs.x).ToArray();

            var bitPos = new Bit(n);
            foreach (var i in Loop(n))
            {
                var lower = bitPos.Sum(ps[i].y);
                ps[i].q[3] = lower;
                ps[i].q[2] = i - lower;

                bitPos.Add(ps[i].y, 1);
            }

            var bitNeg = new Bit(n);
            foreach (var i in Loop(n).Reverse())
            {
                var lower = bitNeg.Sum(ps[i].y);
                ps[i].q[4] = lower;
                ps[i].q[1] = (n - i - 1) - lower;

                bitNeg.Add(ps[i].y, 1);
            }

            var mod = new Mod(998244353);
            var res = 0L;
            foreach (var i in Loop(n))
            {
                var ox = ps[i].q.Select(qs => mod.Pow(2, qs)).ToList();
                var o = ox.Select(oo => mod.Sub(oo, 1)).ToList();

                var r13 = mod.Mul(ox[4], mod.Mul(ox[2], mod.Mul(o[1], o[3])));
                var r24 = mod.Mul(ox[3], mod.Mul(ox[1], mod.Mul(o[2], o[4])));
                var r1234 = mod.Mul(o[3], mod.Mul(o[1], mod.Mul(o[2], o[4])));
                var r0 = mod.Pow(2, n - 1);

                var r = mod.Add(r0, mod.Sub(mod.Add(r13, r24), r1234));

                res = mod.Add(res, r);
            }

            yield return res.ToString();
        }
    }

    class Bit
    {
        long length;
        long[] binaryIndexedTree;
        public Bit(long length)
        {
            this.length = length;
            binaryIndexedTree = new long[length + 1];
        }

        public void Add(long indexZeroBase, long additional)
        {
            // i += i & -i
            // 1が立っている最下位ビットを足す、の意味
            for (long i = indexZeroBase + 1; i <= length; i += i & -i)
            {
                binaryIndexedTree[i] += additional;
            }
        }

        public long Sum(long indexZeroBase)
        {
            long result = 0;

            // i += i & -i
            // 1が立っている最下位ビットを引く、の意味
            for (long i = indexZeroBase + 1; i > 0; i -= i & -i)
            {
                result += binaryIndexedTree[i];
            }

            return result;
        }
    }

