	{
		int N = GetInt();
		var list = new List<Data>();
		for(int i = 0; i < N; i++)
			list.Add(new Data(i, GetInt(), GetInt()));

		list.Sort((a, b) => a.Y - b.Y);
		var dict = new Dictionary<int, int>();
		for(int i = 0; i < N; i++)
			dict[list[i].Y] = i;

		var cnt = new long[N, 4];
		list.Sort((a, b) => a.X - b.X);

		var stl = new SegmentTree<long>(N, 0, (a, b) => a + b);
		for(int i = 0; i < N; i++)
		{
			int id = list[i].Id;
			int pos = dict[list[i].Y];
			cnt[id, 0] = stl.Query(0, pos);
			cnt[id, 1] = stl.Query(pos + 1, N);
			stl.Update(pos, 1);
		}

		var str = new SegmentTree<long>(N, 0, (a, b) => a + b);
		for(int i = N - 1; i >= 0; i--)
		{
			int id = list[i].Id;
			int pos = dict[list[i].Y];
			cnt[id, 2] = str.Query(0, pos);
			cnt[id, 3] = str.Query(pos + 1, N);
