		for(int i = 0; i < N; i++)
		{
			for(int j = 0; j < 4; j++)
				comb[i, j] = ModInt.ModPow(new ModInt(2), new ModInt(cnt[i, j])) - 1;
		}

		var ans = new ModInt(0);
		for(int i = 0; i < N; i++)
		{
			for(int s = 0; s < 16; s++)
			{
				var tmp = new ModInt(1);
				for(int j = 0; j < 4; j++)
				{
					if(contains(s, j))
						tmp *= comb[i, j];
				}

				if(contains(s, 0) && contains(s, 3))
					ans += tmp * 2;
				else if(contains(s, 1) && contains(s, 2))
					ans += tmp * 2;
				else
					ans += tmp;
			}
		}
