public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        N = cr;
        points = new Point[N];
        var xs = new int[N];
        var ys = new int[N];
        for (int i = 0; i < N; i++)
        {
            xs[i] = cr;
            ys[i] = cr;
        }
        xs = Compressed(xs);
        ys = Compressed(ys);
        bitL = new BinaryIndexedTree(N);
        bitR = new BinaryIndexedTree(N);
        for (int i = 0; i < N; i++)
        {
            points[i] = new Point(xs[i], ys[i]);
            bitR.Add(ys[i], 1);
        }
        points.Sort(p => p.x);

        foreach (var p in points)
            Calc(p);
        return res;
    }
    void Calc(Point p)
    {
        bitR.Add(p.y, -1);
        Mod hidariue, hidarishita, migiue, migishita;
        {
            int hidari = bitL.Sum(N);
            int migi = bitR.Sum(N);
            int hs = bitL.Sum(p.y);
            int ms = bitR.Sum(p.y);
            hidarishita = Mod.Pow(2, hs);
            migishita = Mod.Pow(2, ms);
            hidariue = Mod.Pow(2, hidari - hs);
            migiue = Mod.Pow(2, migi - ms);
        }
        res += Mod.Pow(2, N - 1);
        res += (hidarishita - 1) * (migiue - 1) * hidariue * migishita;
        res += (hidariue - 1) * (migishita - 1) * hidarishita * migiue;
        res -= (hidariue - 1) * (migishita - 1) * (hidarishita - 1) * (migiue - 1);
        bitL.Add(p.y, 1);
    }
    Mod.Factor factors = Mod.CreateFactor(1 + (int)1e5);
    Mod res;
    BinaryIndexedTree bitL;
    BinaryIndexedTree bitR;
    int N;
    Point[] points;
    static Dictionary<int, int> Compress(int[] orig) { var ox = new HashSet<int>(orig).ToArray().Sort(); var zip = new Dictionary<int, int>(); for (int i = 0; i < ox.Length; i++) zip[ox[i]] = i; return zip; }
    static int[] Compressed(int[] orig) { var res = new int[orig.Length]; var zip = Compress(orig); for (int i = 0; i < res.Length; i++) res[i] = zip[orig[i]]; return res; }
}

struct Point : IEquatable<Point>, IComparable<Point>
{
    public int x;
    public int y;
    public Point(int[] arr) : this(arr[0], arr[1]) { }
    public Point(int x, int y)
    {
        this.x = x;
        this.y = y;
    }

    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public void Deconstruct(out int v1, out int v2) { v1 = x; v2 = y; }
    public static implicit operator Point(Tuple<int, int> tuple) => new Point(tuple.Item1, tuple.Item2);
    public double Distance(Point other) => Math.Sqrt(Distance2(other));
    private long Distance2(Point other)
    {
        var p = other - this;
        return (long)p.x * p.x + (long)p.y * p.y;
    }
    public long Inner(Point other) => (long)x * other.x + (long)y * other.y;
    public long Cross(Point other) => (long)x * other.y - (long)y * other.x;
    public static Point operator +(Point a, Point b) => new Point(a.x + b.x, a.y + b.y);
    public static Point operator -(Point a, Point b) => new Point(a.x - b.x, a.y - b.y);
    public int CompareTo(Point other)
    {
        var xd = this.x.CompareTo(other.x);
        if (xd != 0) return xd;
        return this.y.CompareTo(other.y);
    }

    public bool Equals(Point other) => this.x == other.x && this.y == other.y;
    public override bool Equals(object obj) => obj is Point && Equals((Point)obj);
    public override int GetHashCode() => ((x << 5) + x) ^ y;
    public override string ToString() => $"({x}, {y})";
}

[System.Diagnostics.DebuggerTypeProxy(typeof(BinaryIndexedTreeDebugView))]
class BinaryIndexedTree
{
    public void Add(int i, int w)
    {
        for (++i; i < tree.Length; i += (i & -i))
            tree[i] += w;
    }
    public int Sum(int toExclusive)
    {
        int res = 0;
        for (var i = toExclusive; i > 0; i -= (i & -i))
            res += tree[i];
        return res;
    }
    public int Sum(int from, int toExclusive) => Sum(toExclusive) - Sum(from);

    private int[] tree;

    public BinaryIndexedTree(int size)
    {
        tree = new int[size + 1];
    }

    public class BinaryIndexedTreeDebugView
    {
        private BinaryIndexedTree bit;
        public BinaryIndexedTreeDebugView(BinaryIndexedTree bit)
        {
            this.bit = bit;
        }

        [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.RootHidden)]
        public string[] Tree
        {
            get
            {
                var res = new string[bit.tree.Length - 1];
                for (var i = 0; i < res.Length; i++)
                {
                    res[i] = $"real:{bit.tree[i + 1]} num:{bit.Sum(i, i + 1)}";
                }
                return res;
            }
        }
    }
}

struct Mod : IEquatable<Mod> { public const long mod = 998244353; public static readonly Mod invalid = new Mod(-1, false); public readonly long val; private Mod(long val, bool isValid) : this(val) { if (!isValid) this.val = val; } public Mod(long val) { this.val = val % mod; if (this.val < 0) this.val += mod; } public override bool Equals(object obj) => (obj is Mod) ? this == ((Mod)obj) : false; public bool Equals(Mod obj) => this == obj; public override int GetHashCode() => val.GetHashCode(); public override string ToString() => val.ToString(); public static implicit operator Mod(long x) => new Mod(x); public static Mod operator +(Mod x, Mod y) => (x.val + y.val) % mod; public static Mod operator -(Mod x, Mod y) => x.val >= y.val ? (x.val - y.val) % mod : (x.val - y.val) % mod + mod; public static Mod operator *(Mod x, Mod y) => (x.val * y.val) % mod; public static Mod operator /(Mod x, Mod y) => x * y.Inverse(); public static bool operator ==(Mod x, Mod y) => x.val == y.val; public static bool operator !=(Mod x, Mod y) => x.val != y.val; public Mod Inverse() { long a = val, b = mod, u = 1, v = 0; while (b > 0) { long t = a / b; var b2 = a - t * b; a = b; b = b2; var v2 = u - t * v; u = v; v = v2; } u %= mod; if (u < 0) u += mod; return u; } public static Mod Pow(Mod x, int y) { Mod res = 1; for (; y > 0; y >>= 1) { if ((y & 1) == 1) res *= x; x *= x; } return res; } public static Factor CreateFactor(int max) => new Factor(max); public class Factor { private readonly Mod[] fac, finv; public Factor(int max) { ++max; var inv = new Mod[max]; fac = new Mod[max]; finv = new Mod[max]; fac[0] = fac[1] = 1; finv[0] = finv[1] = 1; inv[1] = 1; for (var i = 2; i < max; i++) { fac[i] = fac[i - 1] * i; inv[i] = mod - inv[mod % i].val * (mod / i) % mod; finv[i] = finv[i - 1] * inv[i]; } } /** <summary>組み合わせ関数(二項係数)</summary> */ public Mod Combine(int n, int k) { if (n < k) return 0; if (n < 0 || k < 0) return 0; return fac[n] * finv[k] * finv[n - k]; } public Mod Factorial(int n) => fac[n]; public Mod FactorialInvers(int n) => finv[n]; } }

