internal partial class Solver {
    public void Run() {
        var n = ni();
        var x = new int[n];
        var y = new int[n];
        for (int i = 0; i < n; i++) {
            x[i] = ni();
            y[i] = ni();
        }
        var d = IndexDictionaryFactory.Create(x.Concat(y));
        const int mod = 998244353;
        ModInt.SetModValue(mod);
        var points = x.Zip(y, (X, Y) => new { X = d.GetIndex(X), Y = d.GetIndex(Y) })
            .ToArray();

        Array.Sort(points, (p1, p2) => p1.X.CompareTo(p2.X));

        var left = new BinaryIndexTree(d.Count);
        var right = new BinaryIndexTree(d.Count);

        foreach (var p in points) right.Add(p.Y, 1);

        ModInt ans = 0;

        foreach (var p in points) {
            right.Add(p.Y, -1);
            ModInt p00 = ModPow(2, left.Sum(0, p.Y), mod) - 1;
            ModInt p01 = ModPow(2, left.Sum(p.Y + 1, d.Count), mod) - 1;
            ModInt p10 = ModPow(2, right.Sum(0, p.Y), mod) - 1;
            ModInt p11 = ModPow(2, right.Sum(p.Y + 1, d.Count), mod) - 1;

            ModInt pattern = ModPow(2, n - 1, mod);
            pattern += p00 * p11;
            pattern += p01 * p10;
            pattern += p01 * p10 * p11;
            pattern += p00 * p10 * p11;
            pattern += p00 * p01 * p11;
            pattern += p00 * p01 * p10;
            pattern += p00 * p01 * p10 * p11;

            ans += pattern;

            left.Add(p.Y, 1);
        }

        cout.WriteLine(ans);
    }

    public struct ModInt {
        private static int mod = 0;
        private long value;

        public ModInt(long x) {
            value = x;
            Normalize();
        }

        private static long RegularMod(long x, int mod) {
            if (x >= mod) {
                if (x < 2 * mod) {
                    return x - mod;
                }

                return x % mod;
            }
            if (x >= 0) {
                return x;
            }

            x = mod - RegularMod(-x, mod);
            if (x == mod) {
                return 0;
            }

            return x;
        }

        public static void SetModValue(int m) {
            ModInt.mod = m;
        }

        private void Normalize() {
            value = RegularMod(value, mod);
        }

        public override string ToString() {
            return value.ToString();
        }

        public int ToInt() {
            return (int)value;
        }

        public static bool operator ==(ModInt c1, ModInt c2) {
            return c1.value == c2.value;
        }

        public static bool operator !=(ModInt c1, ModInt c2) {
            return !(c1 == c2);
        }

        public static ModInt operator +(ModInt x, ModInt y) {
            return new ModInt(x.value + y.value);
        }
        public static ModInt operator -(ModInt x, ModInt y) {
            return new ModInt(x.value - y.value);
        }
        public static ModInt operator *(ModInt x, ModInt y) {
            return new ModInt(x.value * y.value);
        }
        public static ModInt operator /(ModInt x, ModInt y) {
            return new ModInt(x.value * Inverse(y.value, mod));
        }

        private static long ExtendedGcd(long a, long b, ref long x, ref long y) {
            if (b == 0) {
                x = 1; y = 0;
                return a;
            } else {
                long d = ExtendedGcd(b, a % b, ref y, ref x);
                y -= a / b * x;
                return d;
            }
        }

        private static long Inverse(long a, long mod) {
            long x = 0, y = 0;
            if (ExtendedGcd(a, mod, ref x, ref y) == 1) {
                return (x + mod) % mod;
            } else {
                throw new Exception("Invalid inverse " + a + " " + mod);
            }
        }

