//
//配点 : 600 点 
//
//問題文
//2 次元平面上の N 個の点からなる集合 S があり、 i 番目の点の座標は ( x i , y i) です。 N 個の点の x 座標、 y 座標はそれぞれ相異なります。 
//S の空でない部分集合 T に対して f ( T) を、各辺が座標軸と平行であって T の点を全て含むような最小の長方形に含まれる点の個数として定義します。より正確には、
//f ( T) := T に含まれる点について x 座標の最小値と最大値を それぞれ a , b , そして y 座標の最小値と最大値をそれぞれ c , d としたとき、 a ≤ x i ≤ b かつ c ≤ y i ≤ d を満たす 1 ≤ i ≤ N の個数
//
//S の空でない全ての部分集合 T についての f ( T) の和を計算してください。答えは非常に大きくなることがあるので、 998244353 で割った余りを出力してください。 
//
//制約
//1 ≤ N ≤ 2 × 10 5
//− 10 9 ≤ x i , y i ≤ 10 9
//x i ≠ x j ( i ≠ j)
//y i ≠ y j ( i ≠ j)
//入力は全て整数である
//
//入力
//入力は以下の形式で標準入力から与えられる。
//
//N
//x 1 y 1 
//:
//x N y N
//
//出力
//S の空でない全ての部分集合 T についての f ( T) の和を 998244353 で割った余りを出力せよ。 

        public const string SiteName    = "AtCoder";
        public const string ContestName = "past-sample";
        public const string ProblemName = "O";

        public const long Mod = 998244353L;

        public long[] pows;

        /// <summary>
        /// 2^powsN までの配列を用意する
        /// </summary>
        public void InitPows(int powsN, long mod = 1000000007L)
        {
            pows    = new long[powsN + 1];
            pows[0] = 1;
            for (int i = 1; i <= powsN; i++)
            {
                pows[i] =  pows[i - 1] * 2;
                pows[i] %= mod;
            }
        }

        public void Solve()
        {
            int N = cin.ReadInt;

            Point[] P = new Point[N];

            for (int i = 0; i < N; i++)
            {
                P[i] = new Point(cin.ReadInt, cin.ReadInt);
            }

            // yの昇順でソート
            Array.Sort(P, (a, b) => a.Y - b.Y);

            // yの座標を [0, N - 1] に圧縮
            for (int i = 0; i < N; i++)
            {
                P[i].Y = i;
            }

            // xの昇順でソート
            Array.Sort(P, (a, b) => a.X - b.X);

            long[] belows = new long[N];

            var st = new SegTree<int>(N, 0, (a, b) => a + b, 0);

            // belows[i] : x座標の昇順でi番目までの点について、その点よりy座標が小さい点の数
            for (int i = 0; i < N; i++)
            {
                belows[i] = st.Query(0, P[i].Y);
                st.Update(P[i].Y, 1);
            }

            // afterBelows[i] : x座標の昇順でi番目より後の点について、その点よりy座標が小さい点の数
            long[] afterBelows = new long[N];
            for (int i = 0; i < N; i++)
            {
                afterBelows[i] = st.Query(0, P[i].Y) - belows[i];
            }

            long res = 0;

            InitPows(N, Mod);

            for (int i = 0; i < N; i++)
            {
                res += CalcCount(belows[i], i - belows[i], N - i - 1 - afterBelows[i], afterBelows[i]);
                res %= Mod;
            }

            cou.WriteLine(res);
        }

        /// <summary>
        /// b|c
        /// ---
        /// a|d
        /// それぞれの領域にある点の数から、場合の数を計算して返す
        /// </summary>
        public long CalcCount(long a, long b, long c, long d)
        {
            long[] nums = {a, b, c, d};

            long[] ok  = new long[4]; // 領域に点が存在する場合の数
            long[] any = new long[4]; // 領域に点が存在する場合と存在しない場合の数の和

            for (int i = 0; i < 4; i++)
            {
                any[i] =  pows[nums[i]]; // 2^a
                any[i] %= Mod;
                ok[i]  =  any[i] - 1; // 2^a -1 
                ok[i]  %= Mod;
            }

            long res = 0;

            // o|x   x|o   o|o
            // --- + --- - ---
            // x|o   o|x   o|o

            res += any[0] * ok[1] % Mod * any[2] % Mod * ok[3] % Mod;
            res %= Mod;
            res += ok[0] * any[1] % Mod * ok[2] % Mod * any[3] % Mod;
            res %= Mod;
            res -= ok[0] * ok[1] % Mod * ok[2] % Mod * ok[3] % Mod;
            res %= Mod;

            // 自分自身を選んでいる場合
            //res += any[0] * any[1] % Mod * any[2] % Mod * any[3] % Mod;   //こうやっても同じこと
            res += pows[a + b + c + d]; // つまり pows[N -1] = 2^(N-1) 
            res %= Mod;

            return res;
        }
    }

