			c -= MPow(2, i) + MPow(2, n - 1 - i) + MPow(2, li + ri) + MPow(2, n - 1 - li - ri);
			c += MPow(2, li) + MPow(2, i - li) + MPow(2, ri) + MPow(2, n - 1 - i - ri);
			c = MInt(c);
		}
		Console.WriteLine(c);
	}

