        public const string ContestName = "past-sample";
        public const string ProblemName = "O";

        public const long Mod = 998244353L;

        public long[] pows;

        /// <summary>
        /// 2^powsN までの配列を用意する
        /// </summary>
        public void InitPows(int powsN, long mod = 1000000007L)
        {
            pows    = new long[powsN + 1];
            pows[0] = 1;
            for (int i = 1; i <= powsN; i++)
            {
                pows[i] =  pows[i - 1] * 2;
                pows[i] %= mod;
            }
        }

        public void Solve()
        {
            int N = cin.ReadInt;

            Point[] P = new Point[N];

            for (int i = 0; i < N; i++)
            {
                P[i] = new Point(cin.ReadInt, cin.ReadInt);
            }

            // yの昇順でソート
            Array.Sort(P, (a, b) => a.Y - b.Y);

            // yの座標を [0, N - 1] に圧縮
            for (int i = 0; i < N; i++)
            {
                P[i].Y = i;
            }

            // xの昇順でソート
            Array.Sort(P, (a, b) => a.X - b.X);

            long[] belows = new long[N];

            var st = new SegTree<int>(N, 0, (a, b) => a + b, 0);

            // belows[i] : x座標の昇順でi番目までの点について、その点よりy座標が小さい点の数
            for (int i = 0; i < N; i++)
            {
                belows[i] = st.Query(0, P[i].Y);
                st.Update(P[i].Y, 1);
            }

            // afterBelows[i] : x座標の昇順でi番目より後の点について、その点よりy座標が小さい点の数
            long[] afterBelows = new long[N];
            for (int i = 0; i < N; i++)
            {
                afterBelows[i] = st.Query(0, P[i].Y) - belows[i];
            }

            long res = 0;

            InitPows(N);

            for (int i = 0; i < N; i++)
            {
                res += CalcCount(belows[i], i - belows[i], N - i - 1 - afterBelows[i], afterBelows[i]);
                res %= Mod;
            }

            cou.WriteLine(res);
        }

        /// <summary>
        /// b|c
        /// ---
        /// a|d
        /// それぞれの領域にある点の数から、場合の数を計算して返す
        /// </summary>
        public long CalcCount(long a, long b, long c, long d)
        {
            long[] nums = {a, b, c, d};

            long[] ok  = new long[4]; // 領域に点が存在する場合の数
            long[] any = new long[4]; // 領域に点が存在する場合と存在しない場合の数の和

            for (int i = 0; i < 4; i++)
            {
                any[i] =  pows[nums[i]]; // 2^a
                any[i] %= Mod;
                ok[i]  =  any[i] - 1; // 2^a -1 
                ok[i]  %= Mod;
            }

            long res = 0;

            // o|x   x|o   o|o
            // --- + --- - ---
            // x|o   o|x   o|o

            res += any[0] * ok[1] % Mod * any[2] % Mod * ok[3] % Mod;
            res %= Mod;
            res += ok[0] * any[1] % Mod * ok[2] % Mod * any[3] % Mod;
            res %= Mod;
            res -= ok[0] * ok[1] % Mod * ok[2] % Mod * ok[3] % Mod;
            res %= Mod;

            // 自分自身を選んでいる場合
            //res += any[0] * any[1] % Mod * any[2] % Mod * any[3] % Mod;   //こうやっても同じこと
            res += pows[a + b + c + d]; // つまり pows[N -1] = 2^(N-1) 
            res %= Mod;

            return res;
        }
    }

