        {
            X = x;
            Y = y;
        }

        public T1 X;
        public T2 Y;

        public int CompareTo(Pair<T1, T2> other)
        {
            if (ReferenceEquals(this, other)) return 0;
            if (ReferenceEquals(null, other)) return 1;
            var firstComparison = X.CompareTo(other.X);
            return firstComparison != 0 ? firstComparison : Y.CompareTo(other.Y);
        }

        public override string ToString() => $"({X}, {Y})";

        public bool Equals(Pair<T1, T2> other)
        {
            if (ReferenceEquals(null, other)) return false;
            if (ReferenceEquals(this, other)) return true;
            return EqualityComparer<T1>.Default.Equals(X, other.X) &&
                   EqualityComparer<T2>.Default.Equals(Y, other.Y);
        }

        public override bool Equals(object obj)
        {
            if (ReferenceEquals(null, obj)) return false;
            if (ReferenceEquals(this, obj)) return true;
            return obj.GetType() == this.GetType() && Equals((Pair<T1, T2>)obj);
        }

        public override int GetHashCode()
        {
            unchecked
            {
                return (EqualityComparer<T1>.Default.GetHashCode(X) * 397) ^
                       EqualityComparer<T2>.Default.GetHashCode(Y);
            }
        }
    }

    /// <summary>
    /// 
    /// SegmentTree
    /// 一点更新区間取得
    /// 可換
    /// 
    /// Dataは0始まりになっている
    /// ノードiの子ノードの番号は 2 * i + 1 / 2 * i + 2
    /// ノードiの親ノードの番号は (i - 1) / 2
    /// 
    ///        0
    ///    1       2
    ///  3   4   5   6
    ///
    /// ExValueは不正値 MergeがMinならInfに相当する 大体単位元にしておけばよいが問題に合わせる
    /// 
    /// </summary>
    public class SegTree<T>
    {
        int           TotalLength;
        T[]           Data;
        Func<T, T, T> Merge;
        T             ExValue;

        public SegTree(
            int length,
            Func<T, T, T> merge,
            T exValue)
        {
            Merge       = merge;
            ExValue     = exValue;
            TotalLength = 1;

            while (TotalLength < length) TotalLength *= 2;

            Data = new T[2 * TotalLength - 1];

            for (int i = 0; i < Data.Length; i++) Data[i] = exValue;
        }

        public SegTree(
            int length,
            T initialValue,
            Func<T, T, T> integrate,
            T exValue)
            : this(length, integrate, exValue)
        {
            for (int i = 0; i < length; i++)
            {
                Data[i + TotalLength - 1] = initialValue;
            }

            UpdateAll();
        }

        /// <summary>
        /// ツリーの更新なしに i番目の葉の値を更新する
        /// </summary>
        public void AssignWithoutUpdate(int i, T value)
        {
            Data[i + TotalLength - 1] = value;
        }

        /// <summary>
        /// i番目の葉の値を更新し、ツリーを更新する
        /// </summary>
        public void Update(int i, T value)
        {
            int now = i + TotalLength - 1;
            Data[now] = value;

            while (now > 0)
            {
                now = (now - 1) / 2;

                Data[now] = Merge(Data[now * 2 + 1], Data[now * 2 + 2]);
            }
        }

        public void UpdateAll()
        {
            for (int i = TotalLength - 2; i >= 0; i--)
            {
                Data[i] = Merge(Data[i * 2 + 1], Data[i * 2 + 2]);
            }
        }

        /// <summary>
        /// i番目の葉の値を取得する
        /// </summary>
        public T Look(int i)
        {
            return Data[i + TotalLength - 1];
        }

        /// <summary>
        /// [a, b) の区間に対するクエリについて答える
        /// </summary>
        public T Query(int a, int b)
        {
            return QueryInternal(a, b, 0, 0, TotalLength);
        }

        /// <summary>
        /// [a, b) の区間に対するクエリについて
        /// ノード i (区間 [l, r) 担当) が答える
        /// </summary>
        private T QueryInternal(int a, int b, int i, int l, int r)
        {
            if (r <= a || b <= l) return ExValue;
            if (a <= l && r <= b) return Data[i];

            T leftValue = QueryInternal(a, b, i * 2 + 1,
                l, (l + r) / 2);
            T rightValue = QueryInternal(a, b, i * 2 + 2,
                (l + r) / 2, r);

            return Merge(leftValue, rightValue);
        }
    }


