    readonly int dom = 998244353;
    bool chmax<T>(ref T a, T b) where T : IComparable<T> { if (a.CompareTo(b) < 0) { a = b; return true; } return false; }
    bool chmin<T>(ref T a, T b) where T : IComparable<T> { if (b.CompareTo(a) < 0) { a = b; return true; } return false; }

    void solve()
    {
        int N = cin.nextint;
        var P = new pair[N];
        for (int i = 0; i < N; i++)
        {
            P[i] = new pair(cin.nextint, cin.nextint);
        }
        Array.Sort(P);
        var co = new BinomialCoefficient(N);
        ModInt BASE = 0;
        for (int i = 1; i <= N; i++)
        {
            BASE += co[N, i] * i;
        }
        //var BASE = ModInt.Pow(2, N + 1) - N - 2;
        //WriteLine(BASE);

        var L = new Set<int>();
        var R = new Set<int>();

        for (int i = 0; i < N; i++)
        {
            R.Add(P[i].s);
        }
        for (int i = 0; i < N; i++)
        {
            R.Remove(P[i].s);

            var lsmall = L.LowerBound(P[i].s);
            var lbig = L.Count - lsmall;

            var rsmall = R.LowerBound(P[i].s);
            var rbig = R.Count - rsmall;

            //Write(lsmall + " " + lbig + " " + rsmall + " " + rbig + " " );

            var small = ModInt.Pow(2, lsmall + rsmall) - 1; //small1個以上
            var big = ModInt.Pow(2, lbig + rbig) - 1; //big一個以上
            var LL = (ModInt.Pow(2, lsmall) - 1) * (ModInt.Pow(2, rsmall) - 1);
            var RR = (ModInt.Pow(2, lbig) - 1) * (ModInt.Pow(2, rbig) - 1);

            var ADD = small * big - LL - RR;
            //WriteLine(ADD);
            BASE += (ADD);

            L.Add(P[i].s);
        }

        WriteLine(BASE);
    }

}
