    public struct ModInt {
        private static int mod = 0;
        private long value;

        public ModInt(long x) {
            value = x;
            Normalize();
        }

        private static long RegularMod(long x, int mod) {
            if (x >= mod) {
                if (x < 2 * mod) {
                    return x - mod;
                }

                return x % mod;
            }
            if (x >= 0) {
                return x;
            }

            x = mod - RegularMod(-x, mod);
            if (x == mod) {
                return 0;
            }

            return x;
        }

        public static void SetModValue(int m) {
            ModInt.mod = m;
        }

        private void Normalize() {
            value = RegularMod(value, mod);
        }

        public override string ToString() {
            return value.ToString();
        }

        public int ToInt() {
            return (int)value;
        }

        public static bool operator ==(ModInt c1, ModInt c2) {
            return c1.value == c2.value;
        }

        public static bool operator !=(ModInt c1, ModInt c2) {
            return !(c1 == c2);
        }

        public static ModInt operator +(ModInt x, ModInt y) {
            return new ModInt(x.value + y.value);
        }
        public static ModInt operator -(ModInt x, ModInt y) {
            return new ModInt(x.value - y.value);
        }
        public static ModInt operator *(ModInt x, ModInt y) {
            return new ModInt(x.value * y.value);
        }
        public static ModInt operator /(ModInt x, ModInt y) {
            return new ModInt(x.value * Inverse(y.value, mod));
        }

        private static long ExtendedGcd(long a, long b, ref long x, ref long y) {
            if (b == 0) {
                x = 1; y = 0;
                return a;
            } else {
                long d = ExtendedGcd(b, a % b, ref y, ref x);
                y -= a / b * x;
                return d;
            }
        }

        private static long Inverse(long a, long mod) {
            long x = 0, y = 0;
            if (ExtendedGcd(a, mod, ref x, ref y) == 1) {
                return (x + mod) % mod;
            } else {
                throw new Exception("Invalid inverse " + a + " " + mod);
            }
        }

        public static implicit operator ModInt(long x) {
            return new ModInt(x);
        }

        public override bool Equals(object obj) {
            if (obj == null) {
                return false;
            }
            return value.Equals(((ModInt)obj).value);
        }

        public override int GetHashCode() {
            return value.GetHashCode();
        }
    }
    public static long ModPow(long x, long n, long mod) {
        long t = x, ret = 1;
        while (n > 0) {
            if ((n & 1) != 0) {
                ret = (t * ret) % mod;
            }
            t = t * t % mod;
            n >>= 1;
        }
        return ret;
    }

    public class BinaryIndexTree {
        private readonly long[] array;
        public BinaryIndexTree(int size) {
            array = new long[size];
        }
        public long Sum(int begin, int end) {
            if (begin != 0) {
                return Sum(0, end) - Sum(0, begin);
            }

            long val = 0;
            end--;
            for (; end >= 0; end = (end & (end + 1)) - 1) {
                val += array[end];
            }

            return val;
        }

        public void Add(int k, long val) {
            for (; k < array.Length; k |= k + 1) {
                array[k] += val;
            }
        }

        /// <summary>return min pos where sum(A[0] .. A[pos]) >= w</summary>
        public int LowerBound(long w) {
            if (w <= 0) {
                return 0;
            }

            int x = 0, k = 1, N = array.Length;
            while ((k << 1) <= N) {
                k <<= 1;
            }

            for (; k > 0; k >>= 1) {
                if (x + k - 1 < N && array[x + k - 1] < w) {
                    w -= array[x + k - 1];
                    x += k;
                }
            }
            return (x == N) ? -1 : x;
        }
    }
    public class IndexDictionary<T> {
        private readonly Dictionary<T, int> _toIndex;
        private readonly T[] _array;

        public IndexDictionary(IEnumerable<T> source) : this(source, Comparer<T>.Default) { }

        public IndexDictionary(IEnumerable<T> source, IComparer<T> comparer) {
            _array = source.Distinct().ToArray();
            Array.Sort(_array, comparer);
            _toIndex = new Dictionary<T, int>(_array.Length);
            int index = -1;
            foreach (var x in _array) {
                _toIndex[x] = ++index;
            }
        }

        public int Count { get { return _array.Length; } }

        public T this[int index] { get { return _array[index]; } }

        public int GetIndex(T value) { return _toIndex[value]; }
    }

    public class IndexDictionaryFactory {
        public static IndexDictionary<T> Create<T>(IEnumerable<T> source) {
            return new IndexDictionary<T>(source);
        }
    }
}

