    class BIT
    {
        long[] bit0, bit1;  //1-indexed
        int n;
        public BIT(int n)
        {
            bit0 = new long[n + 1];
            bit1 = new long[n + 1];
            this.n = n;
        }

        public long Sum(int l, int r)
        {
            long ret = 0;
            ret += Sum(bit0, r) + Sum(bit1, r) * r;
            ret -= Sum(bit0, l - 1) + Sum(bit1, l - 1) * (l - 1);
            return ret;
        }

        long Sum(long[] bit, int i)
        {
            long s = 0;
            while (i > 0)
            {
                s += bit[i];
                i -= i & -i;
            }
            return s;
        }

        public void Add(int l, int r, int a)
        {
            Add(bit0, l, -a * (l - 1));
            Add(bit1, l, a);
            Add(bit0, r + 1, a * r);
            Add(bit1, r + 1, -a);
        }

        void Add(long[] bit, int i, int a)
        {
            while (i <= n)
            {
                bit[i] += a;
                i += i & -i;
            }
        }
    }

    class BIT2D
    {
        int H, W;
        long[,] bit;
        public BIT2D(int H_, int W_) { Init(H_, W_); }
        void Init(int H_, int W_)
        {
            H = H_ + 1;
            W = W_ + 1;

            bit = new long[H, W];
        }

        public void Add(int h, int w, long x)
        {
            for (int i = h; i < H; i += (i & -i))
            {
                for (int j = w; j < W; j += (j & -j))
                {
                    bit[i, j] += x;
                }
            }
        }
        // 1≦i≦h かつ 1≦j≦w
        public long Sum(int h, int w)
        {
            long s = 0;
            for (int i = h; i > 0; i -= (i & -i))
            {
                for (int j = w; j > 0; j -= (j & -j))
                {
                    s += bit[i, j];
                }
            }
            return s;
        }

        // h1≦i<h2 かつ w1≦j<w2
        public long Query(int h1, int w1, int h2, int w2)
        {
            return Sum(h2, w2) - Sum(h2, w1 - 1) - Sum(h1 - 1, w2) + Sum(h1 - 1, w1 - 1);
        }

        public void DrawBit2D(int mode = 0)
        {
            for (int i = 1; i < H; i++)
            {
                for (int j = 1; j < W; j++)
                {
                    if (mode == 0) Console.Write(Sum(i, j) + " ");
                    if (mode == 2) Console.Write(Query(i - 1, j - 1, i, j) + " ");
                }
                Console.WriteLine();
            }
        }
    }
