            y = y.Select(v => indexFromValueTableY[v]).ToArray();

            //二次元累積和
            int[,] comb = new int[N + 1, N + 1];
            for (int i = 0; i < N; i++)
            {
                comb[x[i] + 1, y[i] + 1] = 1;
            }

            for (int i = 0; i < N; i++)
            {
                for (int j = 0; j < N; j++)
                {
                    comb[i + 1, j + 1] += comb[i + 1, j] + comb[i, j + 1] - comb[i, j];
                }
            }

            //DrawMapforDebug(comb);

            //各星について総数を求める.
            long ans = 0;
            long all = ModPow(2, N, mod);
            for (int i = 0; i < N; i++)
            {
                //TLE予定
                int c1 = comb[N, N] - comb[N, y[i] + 1] - comb[x[i] + 1, N] + comb[x[i] + 1, y[i] + 1];
                int c2 = comb[x[i], N] - comb[x[i], y[i]];
                int c3 = comb[x[i], y[i]];
                int c4 = comb[N, y[i]] - comb[x[i], y[i]];

                long powRU = ModPow(2, c1, mod);
                long powLU = ModPow(2, c2, mod);
                long powLD = ModPow(2, c3, mod);
                long powRD = ModPow(2, c4, mod);

                long powU = ModPow(2, c1 + c2, mod);
                long powL = ModPow(2, c2 + c3, mod);
                long powD = ModPow(2, c3 + c4, mod);
                long powR = ModPow(2, c4 + c1, mod);

                long sum = (all + powRU + powLU + powLD + powRD - powU - powL - powD - powR - 1) % mod;

                ans = (ans + sum) % mod;
            }

            Console.WriteLine(ans);
        }

        /// <summary>
        /// a^n (mod p)
        /// nが非常に大きい時に有効
        /// </summary>
        /// <param name="a"></param>
        /// <param name="n"></param>
        /// <param name="mod"></param>
        /// <returns></returns>
        public static long ModPow(long a, long n, long p)
        {
            if (n == 0) return 1;
            if (n == 1) return a % p;
            if (n % 2 == 1) return (a * ModPow(a, n - 1, p)) % p;

            long t = ModPow(a, n / 2, p);
            return (t * t) % p;
        }
    }

