}

func (doubling *Doubling) init() {
	doubling.mod = int64(998244353)
	doubling.d = make([]int64, 31)
	doubling.d[0] = 2
	for i := 1; i < 31; i++ {
		doubling.d[i] = doubling.d[i-1] * doubling.d[i-1]
		doubling.d[i] %= doubling.mod
	}
}
func (doubling *Doubling) count(c int) int64 {
	var a int64
	a = 1
	for i := 0; i < 31; i++ {
		if c>>uint(i)&1 == 0 {
			continue
		}
		a *= doubling.d[i]
		a %= doubling.mod
	}
	return a
}

