type Fenwick struct {
	tree []int
}

func NewFenwick(n int) *Fenwick {
	f := &Fenwick{
		tree: make([]int, n),
	}

	return f
}

func (f *Fenwick) Sum(i int) int {
	sum := 0

	for i--; i >= 0; i = (i & (i + 1)) - 1 {
		sum += f.tree[i]
	}

	return sum
}

func (f *Fenwick) Add(i, n int) {
	for l := len(f.tree); i < l; i |= i + 1 {
		f.tree[i] += n
	}
}

type Pairs [][]int

func (p Pairs) Len() int {
	return len(p)
}

func (p Pairs) Less(x, y int) bool {
	return p[x][0] < p[y][0]
}

func (p Pairs) Swap(x, y int) {
	p[x], p[y] = p[y], p[x]
}

func PowM(a, e, m int) int {
	if a < 0 || e < 0 {
		panic(fmt.Sprintf("Pow was called for a < 0 or e < 0, a: %d, e: %d", a, e))
	}

	if e == 0 {
		return 1
	}

	if e%2 == 0 {
		half := Pow(a, e/2)
		return half * half % m
	}

	return a * Pow(a, e-1) % m
}

// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	N := io.NextInt()

	ps := make(Pairs, N)

	for i := 0; i < N; i++ {
		x := io.NextInt()
		y := io.NextInt()
		ps[i] = []int{x, y}
	}

	sort.Sort(ps)

	ys := make([]int, N)
	for i := range ps {
		ys[i] = ps[i][1]
	}
	sort.Ints(ys)

	// 座標圧縮
	for i := range ps {
		ps[i][1] = sort.SearchInts(ys, ps[i][1])
	}

	lu := make([]int, N)
	ld := make([]int, N)
	ru := make([]int, N)
	rd := make([]int, N)

	bit := NewFenwick(N)

	for i, p := range ps {
		lu[i] = bit.Sum(N) - bit.Sum(p[1])
		ld[i] = bit.Sum(p[1])
		bit.Add(p[1], 1)
	}

	bit = NewFenwick(N)

	for i := len(ps) - 1; i >= 0; i-- {
		p := ps[i]
		ru[i] = bit.Sum(N) - bit.Sum(p[1])
		rd[i] = bit.Sum(p[1])
		bit.Add(p[1], 1)
	}

	res := 0
	mod := 998244353
	for i := range ps {
		luExist := PowM(2, lu[i], mod) - 1
		luAny := PowM(2, lu[i], mod)
		ldExist := PowM(2, ld[i], mod) - 1
		ldAny := PowM(2, ld[i], mod)
		ruExist := PowM(2, ru[i], mod) - 1
		ruAny := PowM(2, ru[i], mod)
		rdExist := PowM(2, rd[i], mod) - 1
		rdAny := PowM(2, rd[i], mod)

		// その点を含まない場合
		res += luExist * ldAny % mod * ruAny % mod * rdExist % mod
		res += luAny * ldExist % mod * ruExist % mod * rdAny % mod
		res -= luExist * ldExist % mod * ruExist % mod * rdExist % mod
		res += mod
		res %= mod

		// その点を含む場合
		res += luAny * ldAny % mod * ruAny % mod * rdAny % mod
		res %= mod
	}

	io.Println(res)
}

func main() {
