func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)
	xx := make([]int, n)
	yy := make([]int, n)
	pp := make(Points, n)
	doubling := Doubling{}
	doubling.init()
	for i := 0; i < n; i++ {
		pp[i].x = getNextInt(scanner)
		pp[i].y = getNextInt(scanner)
		xx[i] = pp[i].x
		yy[i] = pp[i].y
	}

	sort.Sort(pp)
	sort.Ints(xx)
	sort.Ints(yy)

	xr := map[int]int{}
	yr := map[int]int{}
	for i := 0; i < n; i++ {
		xr[xx[i]] = i
		yr[yy[i]] = i
	}

	var ans int64
	seg := Segment{}
	seg.init(n)

	wholecnt := doubling.count(n) - 1

	for i := 0; i < n; i++ {
		seg.add(yr[pp[i].y], 1)
		// 左下にある個数
		ld := seg.rangesum(0, yr[pp[i].y])
		// 左上にある個数
		lu := seg.rangesum(yr[pp[i].y]+1, n)
		// 右下にある個数
		rd := yr[pp[i].y] - ld
		// 右上にある個数
		ru := n - 1 - rd - ld - lu

		current := int64(0)

		// 左にあるもの加算
		current += doubling.count(ld+lu) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod
		// 右にあるもの加算
		current += doubling.count(rd+ru) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod
		// 上にあるもの加算
		current += doubling.count(lu+ru) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod
		// 下にあるもの加算
		current += doubling.count(ld+rd) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod
		// 左下にあるもの減算
		current -= doubling.count(ld) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod
		// 左上にあるもの減算
		current -= doubling.count(lu) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod
		// 右下にあるもの減算
		current -= doubling.count(rd) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod
		// 右上にあるもの減算
		current -= doubling.count(ru) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod

		ans += wholecnt - current
		ans %= doubling.mod
		ans = (ans + doubling.mod) % doubling.mod
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

type Doubling struct {
	d   []int64
	mod int64
}

func (doubling *Doubling) init() {
	doubling.mod = int64(998244353)
	doubling.d = make([]int64, 31)
	doubling.d[0] = 2
	for i := 1; i < 31; i++ {
		doubling.d[i] = doubling.d[i-1] * doubling.d[i-1]
		doubling.d[i] %= doubling.mod
	}
}
func (doubling *Doubling) count(c int) int64 {
	var a int64
	a = 1
	for i := 0; i < 31; i++ {
		if c>>uint(i)&1 == 0 {
			continue
		}
		a *= doubling.d[i]
		a %= doubling.mod
	}
	return a
}

