		ru[i] = bit.Sum(N) - bit.Sum(p[1])
		rd[i] = bit.Sum(p[1])
		bit.Add(p[1], 1)
	}

	res := 0
	mod := 998244353
	for i := range ps {
		// E: Exist, A: Any
		luE := PowM(2, lu[i], mod) - 1
		luA := PowM(2, lu[i], mod)
		ldE := PowM(2, ld[i], mod) - 1
		ldA := PowM(2, ld[i], mod)
		ruE := PowM(2, ru[i], mod) - 1
		ruA := PowM(2, ru[i], mod)
		rdE := PowM(2, rd[i], mod) - 1
		rdA := PowM(2, rd[i], mod)

		// その点を含まない場合
		res += luE * ldA % mod * ruA % mod * rdE % mod
		res += luA * ldE % mod * ruE % mod * rdA % mod
		res -= luE * ldE % mod * ruE % mod * rdE % mod
		res += mod
		res %= mod

		// その点を含む場合
		res += luA * ldA % mod * ruA % mod * rdA % mod
		res %= mod
	}

	io.Println(res)
}

