	pp := make(Points, n)
	doubling := Doubling{}
	doubling.init()
	for i := 0; i < n; i++ {
		pp[i].x = getNextInt(scanner)
		pp[i].y = getNextInt(scanner)
		yy[i] = pp[i].y
	}

	sort.Sort(pp)
	sort.Ints(yy)

	yr := map[int]int{}
	for i := 0; i < n; i++ {
		yr[yy[i]] = i
	}

	var ans int64
	seg := Segment{}
	seg.init(n)

	wholecnt := doubling.count(n) - 1
	mod := doubling.mod

	for i := 0; i < n; i++ {
		rank := yr[pp[i].y]
		seg.add(rank, 1)
		// 左下にある個数
		ld := seg.rangesum(0, rank)
		// 左上にある個数
		lu := seg.rangesum(rank+1, n)
		// 右下にある個数
		rd := rank - ld
		// 右上にある個数
		ru := n - 1 - rd - ld - lu

		current := int64(0)

		// 左にあるもの加算
		current += doubling.count(ld+lu) - 1
		// 右にあるもの加算
		current += doubling.count(rd+ru) - 1
		// 上にあるもの加算
		current += doubling.count(lu+ru) - 1
		// 下にあるもの加算
		current += doubling.count(ld+rd) - 1
		// 左下にあるもの減算
		current -= doubling.count(ld) - 1
		// 左上にあるもの減算
		current -= doubling.count(lu) - 1
		// 右下にあるもの減算
		current -= doubling.count(rd) - 1
		// 右上にあるもの減算
		current -= doubling.count(ru) - 1

		ans += wholecnt - current
		ans %= mod
		ans = (ans + mod) % mod
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

type Doubling struct {
	d   []int64
	mod int64
}

func (doubling *Doubling) init() {
	doubling.mod = int64(998244353)
	doubling.d = make([]int64, 31)
	doubling.d[0] = 2
	for i := 1; i < 31; i++ {
		doubling.d[i] = doubling.d[i-1] * doubling.d[i-1]
		doubling.d[i] %= doubling.mod
	}
}
func (doubling *Doubling) count(c int) int64 {
	var a int64
	a = 1
	d := doubling.d
	mod := doubling.mod
	for i := 0; i < 31; i++ {
		if c>>uint(i)&1 == 0 {
			continue
		}
		a *= d[i]
		a %= mod
	}
	return a
}

