		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod
		// 上にあるもの加算
		current += doubling.count(lu+ru) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod
		// 下にあるもの加算
		current += doubling.count(ld+rd) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod
		// 左下にあるもの減算
		current -= doubling.count(ld) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod
		// 左上にあるもの減算
