		current = (current + doubling.mod) % doubling.mod
		// 右上にあるもの減算
		current -= doubling.count(ru) - 1
		current %= doubling.mod
		current = (current + doubling.mod) % doubling.mod

		ans += wholecnt - current
		ans %= doubling.mod
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

type Doubling struct {
