func PowM(a, e, m int) int {
	if a < 0 || e < 0 {
		panic(fmt.Sprintf("Pow was called for a < 0 or e < 0, a: %d, e: %d", a, e))
	}

	if e == 0 {
		return 1
	}

	if e%2 == 0 {
		half := PowM(a, e/2, m)
		return half * half % m
	}

	return a * PowM(a, e-1, m) % m
}

// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	N := io.NextInt()

	ps := make(Pairs, N)

	for i := 0; i < N; i++ {
		x := io.NextInt()
		y := io.NextInt()
		ps[i] = []int{x, y}
	}

	sort.Sort(ps)

	// y の座標圧縮
	ys := make([]int, N)
	for i := range ps {
		ys[i] = ps[i][1]
	}

	sort.Ints(ys)

	for i := range ps {
