	for i := len(ps) - 1; i >= 0; i-- {
		p := ps[i]
		rd[i] = bit.Sum(p[1])
		ru[i] = bit.Sum(N) - rd[i]
		bit.Add(p[1], 1)
	}

	res := 0
	mod := 998244353
	for i := range ps {
