package main

import (
	"bufio"
	"bytes"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Fenwick struct {
	tree []int
}

func NewFenwick(n int) *Fenwick {
	f := &Fenwick{
		tree: make([]int, n),
	}

	return f
}

// sum of [0, i)
func (f *Fenwick) Sum(i int) int {
	sum := 0

	for i--; i >= 0; i = (i & (i + 1)) - 1 {
		sum += f.tree[i]
	}

	return sum
}

func (f *Fenwick) Add(i, n int) {
	for l := len(f.tree); i < l; i |= i + 1 {
		f.tree[i] += n
	}
}

type Pairs [][]int

func (p Pairs) Len() int {
	return len(p)
}

func (p Pairs) Less(i, j int) bool {
	return p[i][0] < p[j][0]
}

func (p Pairs) Swap(i, j int) {
	p[i], p[j] = p[j], p[i]
}

func PowM(a, e, m int) int {
	p := a
	res := 1

	for i := 0; i < 32; i++ {
		if (e>>uint(i))&1 == 1 {
			res = (res * p) % m
		}
		p = (p * p) % m
	}

	return res
}

// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	N := io.NextInt()

	ps := make(Pairs, N)

	for i := 0; i < N; i++ {
		x := io.NextInt()
		y := io.NextInt()
		ps[i] = []int{x, y}
	}

	sort.Sort(ps)

	// y の座標圧縮
	ys := make([]int, N)
	for i := range ps {
		ys[i] = ps[i][1]
	}

	sort.Ints(ys)

	for i := range ps {
		ps[i][1] = sort.SearchInts(ys, ps[i][1])
	}

	lu := make([]int, N)
	ld := make([]int, N)
	ru := make([]int, N)
	rd := make([]int, N)

	bit := NewFenwick(N)

	for i, p := range ps {
		ld[i] = bit.Sum(p[1])
		lu[i] = bit.Sum(N) - ld[i]
		bit.Add(p[1], 1)
	}

	bit = NewFenwick(N)

	for i := len(ps) - 1; i >= 0; i-- {
		p := ps[i]
		rd[i] = bit.Sum(p[1])
		ru[i] = bit.Sum(N) - rd[i]
		bit.Add(p[1], 1)
	}

	res := 0
	mod := 998244353
	for i := range ps {
		// E: Exist, A: Any
		luA := PowM(2, lu[i], mod)
		luE := (luA - 1 + mod) % mod
		ldA := PowM(2, ld[i], mod)
		ldE := (ldA - 1 + mod) % mod
		ruA := PowM(2, ru[i], mod)
		ruE := (ruA - 1 + mod) % mod
		rdA := PowM(2, rd[i], mod)
		rdE := (rdA - 1 + mod) % mod

		// その点を含まない場合
		res += luE * ldA % mod * ruA % mod * rdE % mod
		res += luA * ldE % mod * ruE % mod * rdA % mod
		res -= luE * ldE % mod * ruE % mod * rdE % mod
		res += mod
		res %= mod

		// その点を含む場合
		res += luA * ldA % mod * ruA % mod * rdA % mod
		res %= mod
	}

	io.Println(res)
}

func main() {
	io := NewIo()
	defer io.Flush()
	solve(io, nil)
}

/* IO Helpers */

// Io combines reader, writer, & tokens as the state when processing the input
type Io struct {
	reader    *bufio.Reader
	writer    *bufio.Writer
	tokens    []string
	nextToken int
}

// NewIo creates Io with Stdin & Stdout
func NewIo() *Io {
	return &Io{
		reader: bufio.NewReader(os.Stdin),
		writer: bufio.NewWriter(os.Stdout),
	}
}

// Flush calls the writer's Flush
func (io *Io) Flush() {
	io.writer.Flush()
}

// NextLine returns the string from reader.ReadLine()
func (io *Io) NextLine() string {
	if io.nextToken < len(io.tokens) {
		panic("io.nextToken < len(io.tokens)")
	}

	var buffer bytes.Buffer

	for {
		line, isPrefix, err := io.reader.ReadLine()
		if err != nil {
			panic(err)
		}
		buffer.Write(line)
		if !isPrefix {
			break
		}
	}

	return buffer.String()
}

// NextLines returns []string from next n lines
func (io *Io) NextLines(n int) []string {
	res := make([]string, n)
	for i := 0; i < n; i++ {
		res[i] = io.NextLine()
	}
	return res
}

// Next returns the string token (partial string of the line divided by spaces)
func (io *Io) Next() string {
	if io.nextToken >= len(io.tokens) {
		line := io.NextLine()
		io.tokens = strings.Fields(line)
		io.nextToken = 0
	}

	res := io.tokens[io.nextToken]
	io.nextToken++
	return res
}

// NextStrings returns the []string from the next n tokens
func (io *Io) NextStrings(n int) []string {
	res := make([]string, n)
	for i := 0; i < n; i++ {
		res[i] = io.Next()
	}
	return res
}

