		// 右上にある個数
		ru := n - 1 - rd - ld - lu

		current := int64(0)

		// 左にあるもの加算
		current += doubling.count(ld+lu) - 1
		// 右にあるもの加算
		current += doubling.count(rd+ru) - 1
		// 上にあるもの加算
		current += doubling.count(lu+ru) - 1
		// 下にあるもの加算
		current += doubling.count(ld+rd) - 1
		// 左下にあるもの減算
		current -= doubling.count(ld) - 1
		// 左上にあるもの減算
