func pow(a int64,b int) int64 {
  p := a
  ret := int64(1)
  for i:=0;i<32;i++ {
    if (b>>uint(i))&1 == 1 { ret = (ret*p)%MOD }
    p = (p*p)%MOD
  }
  return ret
}

func compress(a []int) []int {
  n := len(a)
  b := make([]int,n)
  copy(b,a)
  sort.Ints(b)
  m := map[int]int{b[0]:0}
  v := 1
  for i:=1;i<n;i++ {
    if b[i] == b[i-1] { continue }
    m[b[i]] = v
    v++
  }
  c := make([]int,n)
  for i:=0;i<n;i++ { c[i] = m[a[i]] }
  return c
}

type FenwickTree struct { bit []int }
func NewFenwickTree(n int) FenwickTree { return FenwickTree{make([]int,n)} }
func(b FenwickTree) Add(i int,v int) {
  for x:=i+1;x<=len(b.bit);x+=x&-x { b.bit[x-1] += v }
}
func(b FenwickTree) Sum(i int) int {
  r := 0
  for x:=i+1;x>0;x-=x&-x { r += b.bit[x-1] }
  return r
}

type Input struct { reader *bufio.Reader }
func(i *Input) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := i.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(i *Input) NextInt() int {
  n,_ := strconv.Atoi(i.NextLine())
  return n
}
func(i *Input) NextInts() (int,int) {
  s := strings.Fields(i.NextLine())
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  return x,y
}

