def selectTarget(startIdx, maxIdx, depth):
    resultList = []
    idx = startIdx
    if depth != 0:
        while idx <= maxIdx - depth:
            chldRetList = selectTarget(idx + 1, maxIdx, depth - 1)
            #resultList.extend(list(map(list, zip([idx] * len(chldRetList), chldRetList))))
            #if type(chldRetList[0]) is list:
            #    print('#chain#')
            #    resultList = list(chain.from_iterable(resultList))
            if type(chldRetList[0]) is list:
                for chldRet in chldRetList[:]:
                    chldRet.insert(0, idx)
                    resultList.append(chldRet)
            else:
                resultList.extend(list(map(list, zip([idx] * len(chldRetList), chldRetList))))
            idx += 1
    else:
        while idx <= maxIdx:
            resultList.append(idx)
            idx += 1
    return resultList



