        res += (b2 - 1) * (b4 - 1) * b1 * b3

        res -= (b1 - 1) * (b3 - 1) * (b2 - 1) * (b4 - 1)

        res += b1 * b2 * b3 * b4

        res %= MOD
    print(res)
    return


