class SegmentTree:
    def __init__(self, length, init_value=None, aggfunc=min):
        self.length = length
        self.init_value = init_value
        self.aggfunc = aggfunc
        self.depth = ceil(log2(length))
        self.data = [init_value] * (2 ** (1 + self.depth) - 1)
        self.origin = 2 ** self.depth - 1

    def update(self, idx, value):
        i = idx + self.origin
        self.data[i] = value
        while i > 0:
            i = (i - 1) // 2
            new_value = self.aggfunc((self.data[i * 2 + 1], self.data[i * 2 + 2]))
            if self.data[i] != new_value:
                self.data[i] = new_value
            else:
                break

    def query(self, start, stop):
        return self._query(start, stop, 0, 0, 2 ** self.depth)

    def _query(self, start, stop, k, l, r):
        if (start <= l) & (r <= stop):
            return self.data[k]
        elif (r <= start) | (stop <= l):
            return self.init_value
        else:
            return self.aggfunc(
                (
                    self._query(start, stop, k * 2 + 1, l, (l + r) // 2),
                    self._query(start, stop, k * 2 + 2, (l + r) // 2, r),
                )
            )


