fn pow_m(x: i64, p: i64, m: i64) -> i64 {
    if p == 0 {
        1
    } else if p % 2 == 0 {
        let t = pow_m(x, p / 2, m);
        t * t % m
    } else {
        let t = pow_m(x, p / 2, m);
        t * t % m * x % m
    }
}

