        let o3 = ox3 - 1;
        let ox4 = pow_m(2, x_larger_y_smaller[i], big_int);
        let o4 = ox4 - 1;
        ans += ((o1 * o2) % big_int * (ox3 * ox4) % big_int) % big_int;
