#[derive(Debug)]
struct BIT{
    bit: Vec<i64>,
}

impl BIT{
    pub fn new(n: &usize) -> BIT{
        BIT{bit:vec![0;*n+1]}
    }
    pub fn add(&mut self, pos: &usize, val: &i64){
        let mut ind:i64 = *pos as i64 + 1;
        while ind < self.bit.len() as i64{
            self.bit[ind as usize] += *val;
            ind += ind & -ind;
        }
    }

    pub fn get(&self, pos: &usize)->i64{
        let mut ind:i64 = *pos as i64 + 1;
        let mut res = 0i64;
        while ind > 0{
            res += self.bit[ind as usize];
            ind -= ind & -ind;
        }
        res
    }
}

fn mod_pow(x: &i64, n: &i64, m: &i64) -> i64{
    if *n == 0{
        return 1;
    }
    if n % 2 == 0{
        let half = mod_pow(&x, &(n / 2), &m);
        return half * half % m;
    }
    else{
        let dec = mod_pow(&x, &(n-1), m);
        return dec * x % m;
    }
}

