struct FenwickTree {
    n: usize,
    a: Vec<i32>
}

impl FenwickTree {
    fn new(n: usize) -> FenwickTree {
        FenwickTree {
            n: n,
            a: vec![0; n + 1],
        }
    }
    fn add(&mut self, x: usize, v: i32) {
        let mut i = x;
        while i <= self.n {
            self.a[i] += v;
            i += i & (!i + 1);
        }
    }
    fn sum(&self, x: usize) -> i32 {
        let mut s = 0;
        let mut i = x;
        while i > 0 {
            s += self.a[i];
            i -= i & (!i + 1);
        }
        s
    }
}

fn run() {
    input! {
        n: usize,
        p: [(i32, i32); n],
    }
    let mut p = p;
    p.sort();
    for (i, v) in p.iter_mut().enumerate() {
        v.0 = (i + 1) as i32;
        let s = v.0;
        v.0 = v.1;
        v.1 = s;
    }
    p.sort();
    const MOD: u64 = 998244353;
    let pow2: Vec<u64> = (0..n).scan(1, |s, _| {let v = *s; *s *= 2; if *s >= MOD { *s -= MOD;} Some(v)}).collect();
    let mut l = FenwickTree::new(n);
    let mut r = FenwickTree::new(n);
    for i in 1..(n + 1) {
        r.add(i, 1);
    }
    let mut ans = (n as u64) * pow2[n - 1];
    for (i, p) in p.iter().enumerate() {
        let i = i as usize;
        let y = p.1 as usize;
        r.add(y, -1);
        let a = l.sum(y) as usize;
        let b = i - a;
        let c = r.sum(y) as usize;
        let d = (n - 1 - i) - c;
        ans += pow2[n - 1];
        ans += MOD - pow2[a + b];
        ans += MOD - pow2[a + c];
        ans += MOD - pow2[b + d];
        ans += MOD - pow2[c + d];
        ans += pow2[a];
        ans += pow2[b];
        ans += pow2[c];
        ans += pow2[d];
        ans += MOD - 1;
        l.add(y, 1);
    }
    ans %= MOD;
    println!("{}", ans);
}

