use std::rc::Rc;
enum KDNode {
    Leaf {
        x: i64,
        y: i64,
    },
    XNode {
        left: Rc<KDNode>,
        right: Rc<KDNode>,
        x: i64, // right
    },
    YNode {
        left: Rc<KDNode>,
        right: Rc<KDNode>,
        y: i64, // right
    },
}

impl KDNode {
    fn new(xs: &Vec<(i64, i64)>) -> Rc<KDNode> {
        KDNode::new_x(xs)
    }
    fn new_x(xs: &Vec<(i64, i64)>) -> Rc<KDNode> {
        let n = xs.len();
        if n == 1 {
            return Rc::new(KDNode::Leaf {
                x: xs[0].0,
                y: xs[0].1,
            });
        }
        let mut xs = xs.clone();
        xs.sort_by(|&x, &y| x.0.cmp(&y.0));
        let left = KDNode::new_y(&xs[0..n / 2].to_vec());
        let right = KDNode::new_y(&xs[n / 2..n].to_vec());
        Rc::new(KDNode::XNode {
            left: left,
            right: right,
            x: xs[n / 2].0,
        })
    }
    fn new_y(xs: &Vec<(i64, i64)>) -> Rc<KDNode> {
        let n = xs.len();
        if n == 1 {
            return Rc::new(KDNode::Leaf {
                x: xs[0].0,
                y: xs[0].1,
            });
        }
        let mut xs = xs.clone();
        xs.sort_by(|&x, &y| x.1.cmp(&y.1));
        let left = KDNode::new_x(&xs[0..n / 2].to_vec());
        let right = KDNode::new_x(&xs[n / 2..n].to_vec());
        Rc::new(KDNode::YNode {
            left: left,
            right: right,
            y: xs[n / 2].1,
        })
    }
    fn count(node: &Rc<KDNode>, lu: (i64, i64), rd: (i64, i64)) -> usize {
        match node.as_ref() {
            &KDNode::Leaf { x, y } => {
                if lu.0 <= x && x < rd.0 && lu.1 <= y && y < rd.1 {
                    1
                } else {
                    0
                }
            }
            &KDNode::XNode {
                ref left,
                ref right,
                x,
            } => {
                let mut res = 0;
                if lu.0 <= x {
                    res += KDNode::count(left, lu, rd);
                }
                if x <= rd.0 {
                    res += KDNode::count(right, lu, rd);
                }
                res
            }
            &KDNode::YNode {
                ref left,
                ref right,
                y,
            } => {
                let mut res = 0;
                if lu.1 <= y {
                    res += KDNode::count(left, lu, rd);
                }
                if y <= rd.1 {
                    res += KDNode::count(right, lu, rd);
                }
                res
            }
        }
    }
}

