/**
 * Segment Tree. This data structure is useful for fast folding on intervals of an array
 * whose elements are elements of monoid I. Note that constructing this tree requires the identity
 * element of I and the operation of I.
 * Verified by: yukicoder No. 259 (http://yukicoder.me/submissions/100581)
 *              AGC015-E (http://agc015.contest.atcoder.jp/submissions/1461001)
 */
struct SegTree<I, BiOp> {
    n: usize,
    dat: Vec<I>,
    op: BiOp,
    e: I,
}

impl<I, BiOp> SegTree<I, BiOp>
    where BiOp: Fn(I, I) -> I,
          I: Copy {
    pub fn new(n_: usize, op: BiOp, e: I) -> Self {
        let mut n = 1;
        while n < n_ { n *= 2; } // n is a power of 2
        SegTree {n: n, dat: vec![e; 2 * n - 1], op: op, e: e}
    }
    /* ary[k] <- v */
    pub fn update(&mut self, idx: usize, v: I) {
        let mut k = idx + self.n - 1;
        self.dat[k] = v;
        while k > 0 {
            k = (k - 1) / 2;
            self.dat[k] = (self.op)(self.dat[2 * k + 1], self.dat[2 * k + 2]);
        }
    }
    /* [a, b) (note: half-inclusive)
     * http://proc-cpuinfo.fixstars.com/2017/07/optimize-segment-tree/ */
    pub fn query(&self, mut a: usize, mut b: usize) -> I {
        let mut left = self.e;
        let mut right = self.e;
        a += self.n - 1;
        b += self.n - 1;
        while a < b {
            if (a & 1) == 0 {
                left = (self.op)(left, self.dat[a]);
            }
            if (b & 1) == 0 {
                right = (self.op)(self.dat[b - 1], right);
            }
            a = a / 2;
            b = (b - 1) / 2;
        }
        (self.op)(left, right)
    }
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        xy: [(i64, i64); n],
    }
    let mut xy = xy;
    xy.sort();
    let mut coord: Vec<_> = xy.iter().map(|&(_, y)| y).collect();
    coord.sort();
    let mut st = SegTree::new(n, |x, y| x + y, 0);
    let mut lft = vec![[0; 2]; n];
    let mut rgt = vec![[0; 2]; n];
    for i in 0..n {
        let idx = coord.binary_search(&xy[i].1).unwrap();
        lft[i][0] = st.query(0, idx);
        lft[i][1] = st.query(idx, n);
        st.update(idx, 1);
    }
    let mut st = SegTree::new(n, |x, y| x + y, 0);
    for i in (0..n).rev() {
        let idx = coord.binary_search(&xy[i].1).unwrap();
        rgt[i][0] = st.query(0, idx);
        rgt[i][1] = st.query(idx, n);
        st.update(idx, 1);
    }
    let mut tot = ModInt::new(0);
    for i in 0..n {
        let x = ModInt::new(2).pow(i as i64)
            + ModInt::new(2).pow((n - i - 1) as i64)
            - 1;
        let y = ModInt::new(2).pow((lft[i][0] + rgt[i][0]) as i64)
            + ModInt::new(2).pow((lft[i][1] + rgt[i][1]) as i64)
            - 1;
        let comb = ModInt::new(2).pow(lft[i][0] as i64)
            + ModInt::new(2).pow(rgt[i][0] as i64)
            + ModInt::new(2).pow(lft[i][1] as i64)
            + ModInt::new(2).pow(rgt[i][1] as i64)
            - 3;
        let whole = ModInt::new(2).pow(n as i64);
        tot += whole - x - y + comb;
    }
    puts!("{}\n", tot);
}

