fn main() {
    let n = read::<usize>();
    let big_int = 998244353i64;
    let mut points = vec![];
    for i in 0..n {
        let v = read_vec::<i64>();
        points.push((v[0], v[1]));
    }
    points.sort();
    let ys = points.iter().map(|p| p.1).collect::<Vec<_>>();
    let ys = argsort(&ys);
    debug!(ys);

    let mut seg = SegTree::new(n, 0i64, |a, b| a + b);

    let mut x_smaller_y_smaller = vec![0; n];
    let mut x_smaller_y_larger = vec![0; n];
    for i in 0..n {
        x_smaller_y_smaller[i] = seg.query(0, ys[i]);
        x_smaller_y_larger[i] = seg.query(ys[i], n);
        seg.update(ys[i], 1);
    }

    let mut seg = SegTree::new(n, 0i64, |a, b| a + b);
    let mut x_larger_y_smaller = vec![0; n];
    let mut x_larger_y_larger = vec![0; n];
    for i in (0..n).rev() {
        x_larger_y_smaller[i] = seg.query(0, ys[i]);
        x_larger_y_larger[i] = seg.query(ys[i], n);
        seg.update(ys[i], 1);
    }

    let mut ans = 0;
    for i in 0..n {
        assert_eq!(
            x_smaller_y_smaller[i]
                + x_larger_y_larger[i]
                + x_smaller_y_larger[i]
                + x_larger_y_smaller[i],
            n as i64 - 1
        );
        let ox1 = pow_m(2, x_smaller_y_smaller[i], big_int);
        let o1 = ox1 - 1;
        let ox2 = pow_m(2, x_larger_y_larger[i], big_int);
        let o2 = ox2 - 1;
        let ox3 = pow_m(2, x_smaller_y_larger[i], big_int);
        let o3 = ox3 - 1;
        let ox4 = pow_m(2, x_larger_y_smaller[i], big_int);
        let o4 = ox4 - 1;
        ans += ((o1 * o2) % big_int * (ox3 * ox4) % big_int) % big_int;
        ans %= big_int;
        ans += ((ox1 * ox2) % big_int * (o3 * o4) % big_int) % big_int;
        ans %= big_int;
        ans -= ((o1 * o2) % big_int * (o3 * o4) % big_int) % big_int;
        ans %= big_int;
        // debug!(ox1, ox2, ox3, ox4);
        ans += pow_m(2, n as i64 - 1, big_int);
        ans %= big_int;
        // debug!(ans);
    }
    println!("{}", (ans % big_int + big_int) % big_int);
}

fn pow_m(x: i64, p: i64, m: i64) -> i64 {
    if p == 0 {
        1
    } else if p % 2 == 0 {
        let t = pow_m(x, p / 2, m);
        t * t % m
    } else {
        let t = pow_m(x, p / 2, m);
        t * t % m * x % m
    }
}

