const MOD: usize = 998244353;

pub fn mod_pow(b: usize, p: usize) -> usize {
    if p == 0 {
        return 1;
    }
    let mut ret = mod_pow(b * b % MOD, p / 2) % MOD;
    if p % 2 == 1 {
        ret = ret * b % MOD;
    }
    ret
}
pub fn inv(a: usize) -> usize {
    mod_pow(a, MOD - 2)
}

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      mut xys: [(i64,i64); n],
    }
    let mut ys: Vec<_> = xys.iter().map(|v|v.1).collect();
    ys.sort();
    ys.dedup();
    xys.sort_by_key(|v|v.0);

    let m = ys.len();
    let mut bit = BIT::new(m);

    let mut points = vec![vec![0; 4]; n];
    for i in 0..n {
        let (_, y) = xys[i];
        let idx = ys.binary_search(&y).unwrap() + 1;

        let v0 = bit.range_sum(idx+1, m+1);
        let v2 = bit.range_sum(1, idx);

        points[i][0] = v0;
        points[i][2] = v2;

        bit.add(idx, 1);
    }

    for i in 0..n {
        let (_, y) = xys[i];
        let idx = ys.binary_search(&y).unwrap() + 1;

        let v0 = points[i][0];
        let v2 = points[i][2];

        let v1 = bit.range_sum(idx+1, m+1) - v0;
        let v3 = bit.range_sum(1, idx) - v2;

        points[i][1] = v1;
        points[i][3] = v3;
    }

    let mut ans = 0;
    for i in 0..n {
        let mut o = vec![0; 4];
        for j in 0..4 {
            o[j] = mod_pow(2, points[i][j]);
        }
        // a&&d || b&&c - a&&b&&c&&d
        let mut temp = 0;
        temp += (o[0]-1) %MOD * o[1]%MOD * o[2]%MOD * (o[3]-1);
        temp %= MOD;
        temp += o[0] * (o[1]-1)%MOD * (o[2]-1)%MOD * o[3];
        temp %= MOD;
        temp += MOD;
        temp -= (o[0]-1) * (o[1]-1)%MOD * (o[2]-1)%MOD * (o[3]-1);
        temp %= MOD;
        temp += o[0] * o[1]%MOD * o[2]%MOD * o[3];
        temp %= MOD;
        ans += temp;
        ans %= MOD;
    }
    puts!("{}\n", ans);
}

