use std::collections::HashMap;

fn pow(base: ModP, exp: usize) -> ModP {
    if exp == 0 { modp(1) } else {
        let half = pow(base, exp / 2);
        if exp % 2 == 0 {
            half * half
        } else {
            base * half * half
        }
    }
}

