        seg.update(ys[i], 1);
    }

    let mut seg = SegTree::new(n, 0i64, |a, b| a + b);
    let mut x_larger_y_smaller = vec![0; n];
    let mut x_larger_y_larger = vec![0; n];
    for i in (0..n).rev() {
        x_larger_y_smaller[i] = seg.query(0, ys[i]);
        x_larger_y_larger[i] = (n - 1 - i) as i64 - x_larger_y_smaller[i];
        seg.update(ys[i], 1);
    }

    let mut ans = 0;
    for i in 0..n {
        assert_eq!(
            x_smaller_y_smaller[i]
                + x_larger_y_larger[i]
                + x_smaller_y_larger[i]
