        let o2 = ox2 - 1;
        let ox3 = pow_m(2, x_smaller_y_larger[i], big_int);
        let o3 = ox3 - 1;
        let ox4 = pow_m(2, x_larger_y_smaller[i], big_int);
        let o4 = ox4 - 1;
        ans += ((o1 * o2) % big_int * (ox3 * ox4) % big_int) % big_int;
        ans %= big_int;
        ans += ((ox1 * ox2) % big_int * (o3 * o4) % big_int) % big_int;
        ans %= big_int;
        ans -= ((o1 * o2) % big_int * (o3 * o4) % big_int) % big_int;
        ans %= big_int;
        // debug!(ox1, ox2, ox3, ox4);
        ans += pow_m(2, n as i64 - 1, big_int);
        ans %= big_int;
        // debug!(ans);
    }
    println!("{}", (ans % big_int + big_int) % big_int);
}

fn pow_m(n: i64, mut p: i64, m: i64) -> i64 {
    let mut r = n;
    let mut ret = 1;
    while p > 0 {
        if p % 2 == 0 {
            r = r * r % m;
            p /= 2;
        } else {
            ret = ret * r % m;
            p -= 1;
        }
    }
    ret
}

