use std::rc::Rc;
enum KDNode {
    Leaf {
        x: i64,
        y: i64,
    },
    XNode {
        left: Rc<KDNode>,
        right: Rc<KDNode>,
        x: i64, // right
        n: usize,
        lu: (i64, i64),
        rd: (i64, i64),
    },
    YNode {
        left: Rc<KDNode>,
        right: Rc<KDNode>,
        y: i64, // right
        n: usize,
        lu: (i64, i64),
        rd: (i64, i64),
    },
}

impl KDNode {
    fn new(xs: &Vec<(i64, i64)>) -> Rc<KDNode> {
        KDNode::new_x(xs)
    }
    fn new_x(xs: &Vec<(i64, i64)>) -> Rc<KDNode> {
        let n = xs.len();
        if n == 1 {
            return Rc::new(KDNode::Leaf {
                x: xs[0].0,
                y: xs[0].1,
            });
        }
        let mut xs = xs.clone();
        xs.sort_by(|&x, &y| x.0.cmp(&y.0));
        let left = KDNode::new_y(&xs[0..n / 2].to_vec());
        let right = KDNode::new_y(&xs[n / 2..n].to_vec());
        let l = xs.iter().map(|&(x, _)| x).min().unwrap();
        let r = xs.iter().map(|&(x, _)| x).max().unwrap() + 1;
        let u = xs.iter().map(|&(_, y)| y).min().unwrap();
        let d = xs.iter().map(|&(_, y)| y).max().unwrap() + 1;
        Rc::new(KDNode::XNode {
            left: left,
            right: right,
            x: xs[n / 2].0,
            n: n,
            lu: (l, u),
            rd: (r, d),
        })
    }
    fn new_y(xs: &Vec<(i64, i64)>) -> Rc<KDNode> {
        let n = xs.len();
        if n == 1 {
            return Rc::new(KDNode::Leaf {
                x: xs[0].0,
                y: xs[0].1,
            });
        }
        let mut xs = xs.clone();
        xs.sort_by(|&x, &y| x.1.cmp(&y.1));
        let left = KDNode::new_x(&xs[0..n / 2].to_vec());
        let right = KDNode::new_x(&xs[n / 2..n].to_vec());
        let l = xs.iter().map(|&(x, _)| x).min().unwrap();
        let r = xs.iter().map(|&(x, _)| x).max().unwrap() + 1;
        let u = xs.iter().map(|&(_, y)| y).min().unwrap();
        let d = xs.iter().map(|&(_, y)| y).max().unwrap() + 1;
        Rc::new(KDNode::YNode {
            left: left,
            right: right,
            y: xs[n / 2].1,
            n: n,
            lu: (l, u),
            rd: (r, d),
        })
    }
    fn count(node: &Rc<KDNode>, lu: (i64, i64), rd: (i64, i64)) -> usize {
        let box_lu = match node.as_ref() {
            &KDNode::Leaf { x, y } => (x, y),
            &KDNode::XNode {
                left: _,
                right: _,
                x: _,
                n: _,
                lu,
                rd: _,
            } => lu,
            &KDNode::YNode {
                left: _,
                right: _,
                y: _,
                n: _,
                lu,
                rd: _,
            } => lu,
        };
        let box_rd = match node.as_ref() {
            &KDNode::Leaf { x, y } => (x + 1, y + 1),
            &KDNode::XNode {
                left: _,
                right: _,
                x: _,
                n: _,
                lu: _,
                rd,
            } => rd,
            &KDNode::YNode {
                left: _,
                right: _,
                y: _,
                n: _,
                lu: _,
                rd,
            } => rd,
        };
        if lu.0 <= box_lu.0 && lu.1 <= box_lu.1 && box_rd.0 <= rd.0 && box_rd.1 <= rd.1 {
            // eprintln!("hoge");
            return match node.as_ref() {
                &KDNode::Leaf { x: _, y: _ } => 1,
                &KDNode::XNode {
                    left: _,
                    right: _,
                    x: _,
                    n,
                    lu: _,
                    rd: _,
                } => n,
                &KDNode::YNode {
                    left: _,
                    right: _,
                    y: _,
                    n,
                    lu: _,
                    rd: _,
                } => n,
            };
        }
        if rd.0 <= box_lu.0 || rd.1 <= box_lu.1 {
            return 0;
        }
        if box_rd.0 <= lu.0 || box_rd.1 <= lu.1 {
            return 0;
        }
        match node.as_ref() {
            &KDNode::Leaf { x, y } => {
                if lu.0 <= x && x < rd.0 && lu.1 <= y && y < rd.1 {
                    1
                } else {
                    0
                }
            }
            &KDNode::XNode {
                ref left,
                ref right,
                x,
                n,
                lu: _,
                rd: _,
            } => {
                let mut res = 0;
                if lu.0 <= x {
                    res += KDNode::count(left, lu, rd);
                }
                if x <= rd.0 {
                    res += KDNode::count(right, lu, rd);
                }
                res
            }
            &KDNode::YNode {
                ref left,
                ref right,
                y,
                n,
                lu: _,
                rd: _,
            } => {
                let mut res = 0;
                if lu.1 <= y {
                    res += KDNode::count(left, lu, rd);
                }
                if y <= rd.1 {
                    res += KDNode::count(right, lu, rd);
                }
                res
            }
        }
    }
}

type Mod = Modular<Mod_998_244_353>;

use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        ps: [(i64,i64); n],
    }
    let tree = KDNode::new(&ps);
    // let inf = 1i64 << 60;
    let mut res = Mod::new(0);
    let one = Mod::new(1);
    let two = Mod::new(2);
    for i in 0..n {
        let lu = KDNode::count(&tree, (std::i64::MIN, std::i64::MIN), (ps[i].0, ps[i].1));
        let rd = KDNode::count(
            &tree,
            (ps[i].0 + 1, ps[i].1 + 1),
            (std::i64::MAX, std::i64::MAX),
        );
        res += two.pow((n - lu - rd - 1) as u64)
            * (two.pow((lu + rd) as u64) - two.pow(lu as u64) - two.pow(rd as u64) + Mod::new(1));
        let a = lu;
        let b = rd;
        // eprintln!("lu = {}, rd = {}", lu, rd);
        let lu = KDNode::count(
            &tree,
            (ps[i].0 + 1, std::i64::MIN),
            (std::i64::MAX, ps[i].1),
        );
        let rd = KDNode::count(
            &tree,
            (std::i64::MIN, ps[i].1 + 1),
            (ps[i].0, std::i64::MAX),
        );
        res += two.pow((n - lu - rd - 1) as u64)
            * (two.pow((lu + rd) as u64) - two.pow(lu as u64) - two.pow(rd as u64) + Mod::new(1));
        let c = lu;
        let d = rd;
        // eprintln!("lu = {}, rd = {}", lu, rd);
        res += two.pow((n - 1) as u64);
        res -= (two.pow(a as u64) - one)
            * (two.pow(b as u64) - one)
            * (two.pow(c as u64) - one)
            * (two.pow(d as u64) - one);
    }
    writeln!(buf, "{}", res.as_u32());
    buf
}

use mod_int::ModInt;
const MOD: usize = 998244353;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let mut x = vec![];
    let mut y = vec![];
    for _ in 0..n {
        x.push(sc.read::<i64>());
        y.push(sc.read::<i64>());
    }

    let mut xi = x.clone();
    xi.sort();
    xi.dedup();

    let x = x
        .into_iter()
        .map(|x| xi.binary_search(&x).unwrap())
        .collect::<Vec<_>>();

    let mut yi = y.clone();
    yi.sort();
    yi.dedup();

    let y = y
        .into_iter()
        .map(|y| yi.binary_search(&y).unwrap())
        .collect::<Vec<_>>();
    let mut xy = x.into_iter().zip(y.into_iter()).collect::<Vec<_>>();
    xy.sort();

    let mut top_right = vec![0; n];
    let mut top_left = vec![0; n];
    let mut bottom_right = vec![0; n];
    let mut bottom_left = vec![0; n];

    let mut bit = fenwick_tree::FenwickTree::new(n, 0);
    for i in 0..n {
        let (_, y) = xy[i];
        let lower = bit.sum(0, y);
        let upper = i - lower;
        top_left[i] = upper;
        bottom_left[i] = lower;
        bit.add(y, 1);
    }

    let mut bit = fenwick_tree::FenwickTree::new(n, 0);
    for i in (0..n).rev() {
        let (_, y) = xy[i];
        let lower = bit.sum(0, y);
        let upper = (n - 1 - i) - lower;
        top_right[i] = upper;
        bottom_right[i] = lower;
        bit.add(y, 1);
    }

    let mut ans = ModInt(2).pow(n - 1) * n;
    for i in 0..n {
        for mask in 0..(1 << 4) {
            let tl = mask & 1 != 0;
            let tr = mask & (1 << 1) != 0;
            let bl = mask & (1 << 2) != 0;
            let br = mask & (1 << 3) != 0;
            if (tl && br) || (tr && bl) {
                let mut add = ModInt(1);
                if tl {
                    add *= ModInt(2).pow(top_left[i]) - 1;
                }
                if tr {
                    add *= ModInt(2).pow(top_right[i]) - 1;
                }
                if bl {
                    add *= ModInt(2).pow(bottom_left[i]) - 1;
                }
                if br {
                    add *= ModInt(2).pow(bottom_right[i]) - 1;
                }
                ans += add;
            }
        }
    }

    println!("{}", ans.0);
}

