use std::rc::Rc;
enum KDNode {
    Leaf {
        x: i64,
        y: i64,
    },
    XNode {
        left: Rc<KDNode>,
        right: Rc<KDNode>,
        x: i64, // right
        n: usize,
    },
    YNode {
        left: Rc<KDNode>,
        right: Rc<KDNode>,
        y: i64, // right
        n: usize,
    },
}

impl KDNode {
    fn new(xs: &Vec<(i64, i64)>) -> Rc<KDNode> {
        KDNode::new_x(xs)
    }
    fn new_x(xs: &Vec<(i64, i64)>) -> Rc<KDNode> {
        let n = xs.len();
        if n == 1 {
            return Rc::new(KDNode::Leaf {
                x: xs[0].0,
                y: xs[0].1,
            });
        }
        let mut xs = xs.clone();
        xs.sort_by(|&x, &y| x.0.cmp(&y.0));
        let left = KDNode::new_y(&xs[0..n / 2].to_vec());
        let right = KDNode::new_y(&xs[n / 2..n].to_vec());
        Rc::new(KDNode::XNode {
            left: left,
            right: right,
            x: xs[n / 2].0,
            n: n,
        })
    }
    fn new_y(xs: &Vec<(i64, i64)>) -> Rc<KDNode> {
        let n = xs.len();
        if n == 1 {
            return Rc::new(KDNode::Leaf {
                x: xs[0].0,
                y: xs[0].1,
            });
        }
        let mut xs = xs.clone();
        xs.sort_by(|&x, &y| x.1.cmp(&y.1));
        let left = KDNode::new_x(&xs[0..n / 2].to_vec());
        let right = KDNode::new_x(&xs[n / 2..n].to_vec());
        Rc::new(KDNode::YNode {
            left: left,
            right: right,
            y: xs[n / 2].1,
            n: n,
        })
    }
    fn count(node: &Rc<KDNode>, lu: (i64, i64), rd: (i64, i64)) -> usize {
        KDNode::count_sub(
            node,
            lu,
            rd,
            (std::i64::MIN, std::i64::MIN),
            (std::i64::MAX, std::i64::MAX),
        )
    }
    fn count_sub(
        node: &Rc<KDNode>,
        lu: (i64, i64),
        rd: (i64, i64),
        box_lu: (i64, i64),
        box_rd: (i64, i64),
    ) -> usize {
        if lu.0 <= box_lu.0 && lu.1 <= box_lu.1 && box_rd.0 <= rd.0 && box_rd.1 <= rd.1 {
            return match node.as_ref() {
                &KDNode::Leaf { x: _, y: _ } => 1,
                &KDNode::XNode {
                    left: _,
                    right: _,
                    x: _,
                    n,
                } => n,
                &KDNode::YNode {
                    left: _,
                    right: _,
                    y: _,
                    n,
                } => n,
            };
        }
        if rd.0 <= box_lu.0 || rd.1 <= box_lu.1 {
            return 0;
        }
        if box_rd.0 <= lu.0 || box_rd.1 <= lu.1 {
            return 0;
        }
        match node.as_ref() {
            &KDNode::Leaf { x, y } => {
                if lu.0 <= x && x < rd.0 && lu.1 <= y && y < rd.1 {
                    1
                } else {
                    0
                }
            }
            &KDNode::XNode {
                ref left,
                ref right,
                x,
                n,
            } => {
                let mut res = 0;
                if lu.0 <= x {
                    res += KDNode::count_sub(left, lu, rd, box_lu, (x, box_rd.1));
                }
                if x <= rd.0 {
                    res += KDNode::count_sub(right, lu, rd, (x, box_lu.1), box_rd);
                }
                res
            }
            &KDNode::YNode {
                ref left,
                ref right,
                y,
                n,
            } => {
                let mut res = 0;
                if lu.1 <= y {
                    res += KDNode::count_sub(left, lu, rd, box_lu, (box_rd.0, y));
                }
                if y <= rd.1 {
                    res += KDNode::count_sub(right, lu, rd, (box_lu.0, y), box_rd);
                }
                res
            }
        }
    }
}

type Mod = Modular<Mod_998_244_353>;

use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        ps: [(i64,i64); n],
    }
    let tree = KDNode::new(&ps);
    let inf = 1i64 << 60;
    let mut res = Mod::new(0);
    let one = Mod::new(1);
    let two = Mod::new(2);
    for i in 0..n {
        let lu = KDNode::count(&tree, (-inf, -inf), (ps[i].0, ps[i].1));
        let rd = KDNode::count(&tree, (ps[i].0 + 1, ps[i].1 + 1), (inf, inf));
        res += two.pow((n - lu - rd - 1) as u64)
            * (two.pow((lu + rd) as u64) - two.pow(lu as u64) - two.pow(rd as u64) + Mod::new(1));
        let a = lu;
        let b = rd;
        // eprintln!("lu = {}, rd = {}", lu, rd);
        let lu = KDNode::count(&tree, (ps[i].0 + 1, -inf), (inf, ps[i].1));
        let rd = KDNode::count(&tree, (-inf, ps[i].1 + 1), (ps[i].0, inf));
        res += two.pow((n - lu - rd - 1) as u64)
            * (two.pow((lu + rd) as u64) - two.pow(lu as u64) - two.pow(rd as u64) + Mod::new(1));
        let c = lu;
        let d = rd;
        // eprintln!("lu = {}, rd = {}", lu, rd);
        res += two.pow((n - 1) as u64);
        res -= (two.pow(a as u64) - one)
            * (two.pow(b as u64) - one)
            * (two.pow(c as u64) - one)
            * (two.pow(d as u64) - one);
    }
    writeln!(buf, "{}", res.as_u32());
    buf
}

const MOD: i64 = 998244353;

fn main() {
	let mut s = String::new();
	use std::io::Read;
	std::io::stdin().read_to_string(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let mut ys = Vec::with_capacity(n);
	let mut coord = Vec::with_capacity(n);
	for _ in 0..n {
		let x: i32 = s.next().unwrap().parse().unwrap();
		let y: i32 = s.next().unwrap().parse().unwrap();
		ys.push(y);
		coord.push((x, y));
	}
	ys.sort();
	coord.sort();
	for (_, y) in coord.iter_mut() {
		let i = ys.binary_search(y).unwrap();
		*y = i as i32;
	}

	let mut cnt = vec![[0; 4]; n];
	{
		let mut bit = BIT::new(n);
		for (i, &(_, y)) in coord.iter().enumerate() {
			let y = y as usize;
			let bt = bit.sum(y);
			let tp = i as u32 - bt;
			cnt[i][0] += bt;
			cnt[i][1] += tp;
			bit.add(y, 1);
		}
	}
	{
		let mut bit = BIT::new(n);
		for (i, &(_, y)) in coord.iter().rev().enumerate() {
			let y = y as usize;
			let bt = bit.sum(y);
			let tp = i as u32 - bt;
			cnt[n - 1 - i][2] += bt;
			cnt[n - 1 - i][3] += tp;
			bit.add(y, 1);
		}
	}

	fn some(cnt: u32) -> i64 {
		pow_mod(2, cnt, MOD) + MOD - 1
	}
	fn any(cnt: u32) -> i64 {
		pow_mod(2, cnt, MOD)
	}
	let mut ans = 0;
	for t in cnt.into_iter() {
		let a = some(t[0]) * some(t[3]) % MOD * any(t[1] + t[2]) % MOD;
		let b = some(t[1]) * some(t[2]) % MOD * any(t[0] + t[3]) % MOD;
		let ab = (some(t[0]) * some(t[1]) % MOD) * (some(t[2]) * some(t[3]) % MOD) % MOD;
		ans = (ans + any(t[0] + t[1] + t[2] + t[3]) + a + b + MOD - ab) % MOD;
	}
	println!("{}", ans);
}

pub fn pow_mod<T, U>(a: T, mut b: U, modulus: T) -> T
where
	T: num::PrimInt,
	U: num::PrimInt + num::Integer + num::Unsigned,
{
	let mut r = T::one();
	let mut a = a % modulus;
	while b > U::zero() {
		if b.is_odd() {
			r = r * a % modulus;
		}
		a = a * a % modulus;
		b = b / (U::one() + U::one());
	}
	r
}

pub struct BIT<T> {
	data: Vec<T>,
}

impl<T> BIT<T>
where
	T: Clone + Default + std::ops::Add<Output = T>,
{
	pub fn new(n: usize) -> Self {
		Self {
			data: vec![T::default(); n],
		}
	}

	pub fn construct(a: Vec<T>) -> Self {
		let mut a = a;
		for i in 0..a.len() {
			if i | (i + 1) >= a.len() {
				continue;
			}
			let v = a[i].clone();
			a[i | (i + 1)] = a[i | (i + 1)].clone() + v;
		}
		Self { data: a }
	}

	pub fn sum(&self, i: usize) -> T {
		let mut r = T::default();
		let mut i = i;
		while i > 0 {
			r = r + self.data[i - 1].clone();
			i &= i - 1;
		}
		r
	}

	pub fn add(&mut self, i: usize, value: T) {
		let mut i = i;
		while i < self.data.len() {
			self.data[i] = self.data[i].clone() + value.clone();
			i |= i + 1;
		}
	}
}

static MOD: isize = 998244353;

#[derive(Debug)]
struct FenwickTree {
    n: usize,
    bit: Vec<isize>,
}

impl FenwickTree {
    fn new(n: usize) -> Self {
        FenwickTree {
            n: n,
            bit: vec![0; n],
        }
    }

    // [0, i)
    fn sum(&self, i: usize) -> isize {
        let mut s = 0;
        let mut i = i as isize;
        while i > 0 {
            i -= 1;
            s += self.bit[i as usize];
            i &= i + 1;
        }
        s
    }

    fn add(&mut self, i: usize, x: isize) {
        let mut i = i;
        while i < self.n {
            self.bit[i] += x;
            i |= i + 1;
        }
    }
}

fn solve(xys: Vec<(isize, isize)>) -> isize {
    let n = xys.len() as isize;
    let mut p2 = vec![0 as isize; 200002];
    p2[0] = 1;
    for x in 1..p2.len() {
        p2[x] = (p2[x - 1] * 2) % MOD;
    }

    let mut sortedx = xys.iter().map(|&(x, _)| x).collect::<Vec<_>>();
    sortedx.sort();

    let mut sortedy = xys.iter().map(|&(_, y)| y).collect::<Vec<_>>();
    sortedy.sort();

    let mut compressed = vec![(0, 0); xys.len()];
    for (i, &(x, y)) in xys.iter().enumerate() {
        let ix = sortedx.binary_search(&x).unwrap() as isize;
        let iy = sortedy.binary_search(&y).unwrap() as isize;
        compressed[i] = (ix, iy);
    }

    compressed.sort_by_key(|&(x, _)| x);

    let mut lft = FenwickTree::new(xys.len());
    let mut rft = FenwickTree::new(xys.len());
    for i in 0..xys.len() {
        rft.add(i, 1);
    }

    let mut ans = 0;

    for (x, y) in compressed {
        let r3 = lft.sum(y as usize) as usize;
        let r2 = (x - r3 as isize) as usize;
        let r4 = rft.sum(y as usize) as usize;
        let r1 = (n - x - 1 - r4 as isize) as usize;

        let pr1 = p2[r1] - 1;
        let pr2 = p2[r2] - 1;
        let pr3 = p2[r3] - 1;
        let pr4 = p2[r4] - 1;

        // 各象限と自身のみ
        ans += pr1 + pr2 + pr3 + pr4;
        ans %= MOD;

        // 隣り合う象限と自身
        ans += if r1 > 0 && r2 > 0 {
            (pr1 * pr2) % MOD
        } else {
            0
        } + if r2 > 0 && r3 > 0 {
            (pr2 * pr3) % MOD
        } else {
            0
        } + if r3 > 0 && r4 > 0 {
            (pr3 * pr4) % MOD
        } else {
            0
        } + if r4 > 0 && r1 > 0 {
            (pr4 * pr1) % MOD
        } else {
            0
        };
        ans %= MOD;

        // r1+r3, r2+r4 (自身を含む場合と含まない場合で２倍)
        ans += if r1 > 0 && r3 > 0 {
            (pr1 * pr3) * 2 % MOD
        } else {
            0
        } + if r2 > 0 && r4 > 0 {
            (pr2 * pr4) * 2 % MOD
        } else {
            0
        };
        ans %= MOD;

        // 3象限を含む場合
        ans += if r1 > 0 && r2 > 0 && r3 > 0 {
            (((pr1 * pr2) % MOD) * pr3 * 2) % MOD
        } else {
            0
        } + if r2 > 0 && r3 > 0 && r4 > 0 {
            (((pr2 * pr3) % MOD) * pr4 * 2) % MOD
        } else {
            0
        } + if r3 > 0 && r4 > 0 && r1 > 0 {
            (((pr3 * pr4) % MOD) * pr1 * 2) % MOD
        } else {
            0
        } + if r4 > 0 && r1 > 0 && r2 > 0 {
            (((pr4 * pr1) % MOD) * pr2 * 2) % MOD
        } else {
            0
        };
        ans %= MOD;

        // 全て含む場合(自身を含む場合と含まない場合で２倍)
        ans += if r1 > 0 && r2 > 0 && r3 > 0 && r4 > 0 {
            (((((pr1 * pr2) % MOD) * pr3) % MOD) * pr4 * 2) % MOD
        } else {
            0
        };
        ans %= MOD;

        lft.add(y as usize, 1);
        rft.add(y as usize, -1);
    }

    ans += n;
    ans %= MOD;

    ans
}

