use std::io::Write;
use modint::*;

fn run() {
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    input! {
        n: usize,
        p: [(i32, i32); n],
    }
    let mut p = p;
    p.sort();
    for (i, v) in p.iter_mut().enumerate() {
        v.0 = (i + 1) as i32;
        let s = v.0;
        v.0 = v.1;
        v.1 = s;
    }
    p.sort();
    let mut l = segment_tree::PURQ::new(n + 2, 0, |x, y| x + y);
    let mut r = segment_tree::PURQ::new(n + 2, 0, |x, y| x + y);
    for (_, y) in p.iter() {
        r.update(*y as usize, 1);
    }
    let mut ans = ModInt::pow(ModInt(2), (n - 1) as u32) * ModInt(n as u32);
    for (x, y) in p {
        let y = y as usize;
        r.update(y as usize, 0);
        let a = l.find(0, y);
        let b = l.find(y, n + 2);
        let c = r.find(0, y);
        let d = r.find(y, n + 2);
        ans += ModInt::pow(ModInt(2), (n - 1) as u32);
        ans -= ModInt::pow(ModInt(2), (a + b) as u32);
        ans -= ModInt::pow(ModInt(2), (a + c) as u32);
        ans -= ModInt::pow(ModInt(2), (b + d) as u32);
        ans -= ModInt::pow(ModInt(2), (c + d) as u32);
        ans += ModInt::pow(ModInt(2), a as u32);
        ans += ModInt::pow(ModInt(2), b as u32);
        ans += ModInt::pow(ModInt(2), c as u32);
        ans += ModInt::pow(ModInt(2), d as u32);
        ans -= ModInt(1);
        l.update(y as usize, 1);
    }
    println!("{}", ans);
}

