use std::collections::HashMap;
use std::iter::repeat;

fn main() {
    read!(n = usize);
    let mut ps = readx::<(i32, i32)>();

    ps.sort_by_key(|p| p.0);
    let mut x_map = HashMap::new();
    for (i, x) in ps.iter().map(|&(x, _)| x).enumerate() {
        x_map.insert(x, i);
    }

    ps.sort_by_key(|p| p.1);
    let ps: Vec<(usize, usize)> = ps.into_iter().enumerate()
        .map(|(i, (x, _))| (x_map[&x], i))
        .collect();

    let mut tree_d = SegmentTree::new(n, 0u64, |&a, &b| a+b);
    let mut tree_u = repeat(1).take(n).segment_tree(0u64, |&a, &b| a+b);
    let mut quadrants = Vec::new();
    for &(x, _) in &ps {
        *tree_u.at(x) = 0;

        let n1 = tree_u.query(x..n).unwrap();
        let n2 = tree_u.query(0..x).unwrap();
        let n3 = tree_d.query(0..x).unwrap();
        let n4 = tree_d.query(x..n).unwrap();
        quadrants.push([n1, n2, n3, n4]);

        *tree_d.at(x) = 1;
    }

    let included = modp(2).pow(n as u64 - 1) * modp(n as u64);
    let excluded: ModP = (0..n).map(|i| {
        let ps: Vec<ModP> = quadrants[i].iter().map(|&n| modp(2).pow(n)).collect();
        (ps[0]-1) * (ps[2]-1) * ps[1] * ps[3] +
            (ps[1]-1) * (ps[3]-1) * ps[0] * ps[2] -
            (ps[0]-1) * (ps[1]-1) * (ps[2]-1) * (ps[3]-1)
    }).sum();
    println!("{}", included + excluded);
}

