    }
}
fn main() {
    input! { n, mut xy: [(i64, i64); n] };
    xy.sort();
    let xzip = xy.iter().map(|&(x, _y)| x).collect::<Compress<_>>();
    let yzip = xy.iter().map(|&(_x, y)| y).collect::<Compress<_>>();
    let mut xs = xy.iter().map(|&(x, _y)| x).collect::<Vec<_>>();
    let mut ys = xy.iter().map(|&(_x, y)| y).collect::<Vec<_>>();
    xs.sort();
    ys.sort();
    let mut tab = vec![Modi64(0); n + 1];
    for i in 0..n {
        tab[i + 1] = tab[i] * 2.into() + 1.into();
    }
    let mut xcnt = vec![vec![]; n];
    for &(x, y) in xy.iter() {
        let (a, b) = (xzip.get(x), yzip.get(y));
        xcnt[a].push(b);
    }
    let mut ans = tab[n] * (n as i64).into();
    let mut bit = BinaryIndexedTree::new(n, AnyGroup::new(0, |&x, &y| x + y, |&x| -x));
    for a in 0..n {
        for &b in &xcnt[a] {
            ans += tab[bit.query_section(0, b) as usize];
            ans += tab[bit.query_section(b + 1, n) as usize];
        }
        for &b in &xcnt[a] {
            bit.update(b + 1, 1);
        }
    }
    let mut bit = BinaryIndexedTree::new(n, AnyGroup::new(0, |&x, &y| x + y, |&x| -x));
    for a in (0..n).rev() {
        for &b in &xcnt[a] {
            ans += tab[bit.query_section(0, b) as usize];
            ans += tab[bit.query_section(b + 1, n) as usize];
        }
        for &b in &xcnt[a] {
            bit.update(b + 1, 1);
        }
    }
    for &(x, y) in xy.iter() {
        let (xlb, xub) = (lower_bound(&xs, x), upper_bound(&xs, x));
        let (ylb, yub) = (lower_bound(&ys, y), upper_bound(&ys, y));
        ans -= tab[xlb];
        ans -= tab[n - xub];
        ans -= tab[ylb];
        ans -= tab[n - yub];
    }
    println!("{}", ans);
}

use mod_int::ModInt;
const MOD: usize = 998244353;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let mut x = vec![];
    let mut y = vec![];
    for _ in 0..n {
        x.push(sc.read::<i64>());
        y.push(sc.read::<i64>());
    }

    let mut xi = x.clone();
    xi.sort();
    xi.dedup();

    let x = x
        .into_iter()
        .map(|x| xi.binary_search(&x).unwrap())
        .collect::<Vec<_>>();

    let mut yi = y.clone();
    yi.sort();
    yi.dedup();

    let y = y
        .into_iter()
        .map(|y| yi.binary_search(&y).unwrap())
        .collect::<Vec<_>>();
    let mut xy = x.into_iter().zip(y.into_iter()).collect::<Vec<_>>();
    xy.sort();

    let mut top_right = vec![0; n];
    let mut top_left = vec![0; n];
    let mut bottom_right = vec![0; n];
    let mut bottom_left = vec![0; n];

    let mut bit = fenwick_tree::FenwickTree::new(n, 0);
    for i in 0..n {
        let (_, y) = xy[i];
        let lower = bit.sum(0, y);
        let upper = i - lower;
        top_left[i] = upper;
        bottom_left[i] = lower;
        bit.add(y, 1);
    }

    let mut bit = fenwick_tree::FenwickTree::new(n, 0);
    for i in (0..n).rev() {
        let (_, y) = xy[i];
        let lower = bit.sum(0, y);
        let upper = (n - 1 - i) - lower;
        top_right[i] = upper;
        bottom_right[i] = lower;
        bit.add(y, 1);
    }

    let mut pow2 = vec![ModInt(1); n];
    for i in 1..n {
        pow2[i] = pow2[i - 1] * 2;
    }

    let mut ans = pow2[n - 1] * n;
    for i in 0..n {
        for mask in 0..(1 << 4) {
            let tl = mask & 1 != 0;
            let tr = mask & (1 << 1) != 0;
            let bl = mask & (1 << 2) != 0;
            let br = mask & (1 << 3) != 0;
            if (tl && br) || (tr && bl) {
                let mut add = ModInt(1);
                if tl {
                    add *= pow2[top_left[i]] - 1;
                }
                if tr {
                    add *= pow2[top_right[i]] - 1;
                }
                if bl {
                    add *= pow2[bottom_left[i]] - 1;
                }
                if br {
                    add *= pow2[bottom_right[i]] - 1;
                }
                ans += add;
            }
        }
    }

    println!("{}", ans.0);
}

