static MOD: u64 = 998244353;
use std::ops::*;
#[derive(Copy, Clone, Eq, PartialEq, Ord, PartialOrd, Default)]
struct Mint(u64);
impl Mint {
    pub fn value(&self) -> u64 { self.0 }
    pub fn zero() -> Mint { Mint(0) }
    pub fn from(n: u64) -> Mint { Mint(n % MOD) }
    pub fn pow(&self, mut n: u64) -> Mint {
        let mut v = 1;
        let mut a = self.0;
        while n > 0 {
            if n & 1 != 0 {
                v *= a;
                v %= MOD;
            }
            a *= a;
            a %= MOD;
            n >>= 1;
        }
        Mint(v)
    }
}
impl AddAssign for Mint {
    fn add_assign(&mut self, rhs: Mint) {
        self.0 += rhs.0;
        if self.0 >= MOD { self.0 -= MOD }
    }
}
impl Sub<u64> for Mint {
    type Output = Mint;
    fn sub(self, rhs: u64) -> Mint {
        let v = rhs % MOD;
        let mut v = self.0 + MOD - v;
        if v >= MOD { v -= MOD }
        Mint(v)
    }
}
impl SubAssign for Mint {
    fn sub_assign(&mut self, other: Mint) {
        self.0 += MOD - other.0;
        if self.0 >= MOD { self.0 -= MOD }
    }
}
impl Mul for Mint {
    type Output = Mint;
    fn mul(self, rhs: Mint) -> Mint { Mint(self.0 * rhs.0 % MOD) }
}

struct Bit<T>(Vec<T>);
impl<T: Default + Copy + ::std::ops::AddAssign> Bit<T> {
    pub fn new(n: usize) -> Bit<T> {
        Bit(vec![Default::default(); n + 1])
    }
    pub fn inc(&mut self, mut i: usize, val: T) {
        i += 1;
        while i < self.0.len() {
            self.0[i] += val;
            i += Bit::<T>::low(i);
        }
    }
    pub fn sum(&self, mut i: usize) -> T {
        i += 1;
        let mut v = T::default();
        while i > 0 {
            v += self.0[i];
            i -= Bit::<T>::low(i);
        }
        v
    }
    fn low(n: usize) -> usize {
        let n = n as isize;
        let n = n & -n;
        n as usize
    }
}

