fn compress<T: Copy + Ord + Hash, I: Iterator<Item=T>>(iter: I) -> HashMap<T, usize> {
    let mut vec: Vec<T> = iter.collect();
    vec.sort();
    vec.iter().cloned().enumerate().map(|(k, v)| (v, k)).collect()
}

use std::collections::*;
fn main() {
    input! {
        n: usize,
        ps: [(i32, i32); n]
    }
    let mut ps = ps;
    // let map_x = compress(ps.iter().map(|&(x, _)| x));
    let map_y = compress(ps.iter().map(|&(_, y)| y));

    ps.sort();
    let left = {
        let mut left = vec![];
        let mut bit: Bit<usize> = Bit::new(n);
        for (i, &(_, y)) in ps.iter().enumerate() {
            let y: usize = map_y[&y];
            let up = bit.sum(y);
            left.push((up, i - up));
            bit.inc(y, 1);
        }
        left
    };
    let right = {
        let mut right = vec![];
        let mut bit: Bit<usize> = Bit::new(n);
        for (i, &(_, y)) in ps.iter().rev().enumerate() {
            let y: usize = map_y[&y];
            let up = bit.sum(y);
            // assert!(i >= up, "{} >= {}", i, up);
            right.push((up, i - up));
            bit.inc(y, 1);
        }
        right.reverse();
        right
    };

    let mut sum: Mint = Mint::zero();
    for i in 0..n {
        let (lu, ld) = left[i];
        let (ru, rd) = right[i];

        let luc = Mint::from(2).pow(lu as u64);
        let ldc = Mint::from(2).pow(ld as u64);
        let ruc = Mint::from(2).pow(ru as u64);
        let rdc = Mint::from(2).pow(rd as u64);
        sum += luc * (ldc - 1) * (ruc - 1) * rdc;
        sum += (luc - 1) * ldc * ruc * (rdc - 1);
        sum -= (luc - 1) * (ldc - 1) * (ruc - 1) * (rdc - 1);
        sum += luc * ldc * ruc * rdc;
    }
    println!("{}", sum.value());
}

