fn main() {
    let n = read::<usize>();
    let mut points = vec![];
    for i in 0..n {
        let v = read_vec::<i64>();
        points.push((v[0], v[1]));
    }
    let mut xs = points.iter().map(|&x| x.0).collect::<Vec<_>>();
    xs.sort();
    let mut x_dict = HashMap::new();
    for (i, x) in xs.into_iter().enumerate() {
        x_dict.insert(x, i);
    }
    let mut ys = points.iter().map(|&x| x.1).collect::<Vec<_>>();
    ys.sort();
    let mut y_dict = HashMap::new();
    for (i, y) in ys.into_iter().enumerate() {
        y_dict.insert(y, i);
    }

    let mut points = points
        .into_iter()
        .map(|p| (x_dict[&p.0], y_dict[&p.1]))
        .collect::<Vec<_>>();

    points.sort();
    let mut seg = SegTree::new(n, 0i64, |x, y| x + y);
    let mut from_left_upper = vec![0; n];
    for (i, &(_, y)) in points.iter().enumerate() {
        from_left_upper[i] = seg.query(0, y);
        seg.update(y, 1);
    }

    let mut seg = SegTree::new(n, 0i64, |x, y| x + y);
    let mut from_right_upper = vec![0; n];
    for (i, &(_, y)) in points.iter().enumerate().rev() {
        from_right_upper[i] = seg.query(0, y);
        seg.update(y, 1);
    }

    let mut ans = Modulo(0);
    for i in 0..n {
        let left_upper_any = Modulo(2).pow(from_left_upper[i] as i64) - 1;
        let left_all = i as i64;
        let left_lower = left_all - from_left_upper[i];
        let left_lower_any = Modulo(2).pow(left_lower as i64) - 1;

        let right_upper_any = Modulo(2).pow(from_right_upper[i] as i64) - 1;
        let right_all = (n - 1 - i) as i64;
        let right_lower = right_all - from_right_upper[i];
        let right_lower_any = Modulo(2).pow(right_lower as i64) - 1;

        let lurl_res = n as i64 - 1 - (from_left_upper[i] + right_lower);
        let lurl = left_upper_any * right_lower_any * Modulo(2).pow(lurl_res as i64);

        let llru_res = n as i64 - 1 - (from_right_upper[i] + left_lower);
        let llru = left_lower_any * right_upper_any * Modulo(2).pow(llru_res as i64);

        let lurl_llru = left_upper_any * right_lower_any * left_lower_any * right_upper_any;
        let temp = lurl + llru - lurl_llru;
        let temp2 = Modulo(2).pow(n as i64 - 1); // self
        ans += temp + temp2;
    }
    println!("{}", ans);
}

