    pub fn new(x: u32) -> Self {
        Self {
            x: M::modulo(x),
            _marker: std::marker::PhantomData,
        }
    }
    #[inline]
    pub fn new_unchecked(x: u32) -> Self {
        Self {
            x,
            _marker: std::marker::PhantomData,
        }
    }
    #[inline]
    pub fn inner(self) -> u32 {
        self.x
    }
    #[inline]
    pub fn one() -> Self {
        Self::new_unchecked(1)
    }
