                        let k0 = points[i][0];
                        let k1 = points[i][1];
                        let k2 = points[i][2];
                        let k3 = points[i][3];

                        let mut temp = 1;
                        if a == 1 {
                            temp *= mod_pow(2, k0) - 1;
                            temp %= MOD;
                        }
                        if b == 1 {
                            temp *= mod_pow(2, k1) - 1;
                            temp %= MOD;
                        }
                        if c == 1 {
                            temp *= mod_pow(2, k2) - 1;
                            temp %= MOD;
                        }
                        if d == 1 {
                            temp *= mod_pow(2, k3) - 1;
                            temp %= MOD;
                        }

                        // 点Pを内部に含むときは、点Pを含まない部分集合の場合も加算する
                        if (a==1 && d==1) || (b==1 && c==1) {
                            temp *= 2;
                            temp %= MOD;
                        }
                        ans += temp;
                        ans %= MOD;
                    }
                }
            }
        }
    }
    puts!("{}\n", ans);
}

